_YF_DOWNLOAD_CACHE = {}
_YF_INFO_CACHE = {}
_ORIG_DOWNLOAD = yf.download
def _cached_download(tickers, *args, **kwargs):
    key = str(tickers) + str(args) + str(kwargs)
    if key in _YF_DOWNLOAD_CACHE:
        val, ts = _YF_DOWNLOAD_CACHE[key]
        if time.time() - ts < 600:
            return val.copy()
    res = _ORIG_DOWNLOAD(tickers, *args, **kwargs)
    if not res.empty:
        _YF_DOWNLOAD_CACHE[key] = (res.copy(), time.time())
    return res
yf.download = _cached_download
_orig_ticker_init = yf.Ticker.__init__
def _cached_ticker_init(self, ticker, *args, **kwargs):
    _orig_ticker_init(self, ticker, *args, **kwargs)
    self._tkr_name = ticker
yf.Ticker.__init__ = _cached_ticker_init
_orig_info = yf.Ticker.info
@property
def _cached_info(self):
    tkr = getattr(self, "_tkr_name", str(self))
    if tkr in _YF_INFO_CACHE:
        val, ts = _YF_INFO_CACHE[tkr]
        if time.time() - ts < 3600:
            return val
    res = _orig_info.fget(self)
    _YF_INFO_CACHE[tkr] = (res, time.time())
    return res
yf.Ticker.info = _cached_info
