_WATCHLIST_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_watchlist.json")
def load_watchlist():
    try:
        with open(_WATCHLIST_FILE, 'r') as f:
            data = json.load(f)
            return data if isinstance(data, list) else []
    except (FileNotFoundError, json.JSONDecodeError):
        return []
def save_watchlist(wl):
    with open(_WATCHLIST_FILE, 'w') as f:
        json.dump(wl, f, indent=2)
_PORTFOLIO_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_portfolio.json")
def load_portfolio():
    try:
        with open(_PORTFOLIO_FILE, 'r') as f:
            data = json.load(f)
            return data if isinstance(data, list) else []
    except (FileNotFoundError, json.JSONDecodeError):
        return []
def save_portfolio(p):
    with open(_PORTFOLIO_FILE, 'w') as f:
        json.dump(p, f, indent=2)
_WATCHLIST_NOTES_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_watchlist_notes.json")
def load_watchlist_notes():
    try:
        with open(_WATCHLIST_NOTES_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data if isinstance(data, dict) else {}
    except (FileNotFoundError, json.JSONDecodeError):
        return {}
def save_watchlist_notes(notes_dict):
    with open(_WATCHLIST_NOTES_FILE, 'w', encoding='utf-8') as f:
        json.dump(notes_dict, f, indent=2, ensure_ascii=False)
_NOTES_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "my_notes.json")
def _load_notes():
    try:
        with open(_NOTES_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data if isinstance(data, list) else []
    except (FileNotFoundError, json.JSONDecodeError):
        return []
def _save_notes(notes):
    with open(_NOTES_FILE, 'w', encoding='utf-8') as f:
        json.dump(notes, f, indent=2, ensure_ascii=False)
def _next_note_id(notes):
    if not notes:
        return 1
    return max(n.get('id', 0) for n in notes) + 1
def _format_timestamp(ts_str):
    try:
        dt = _dt.fromisoformat(ts_str)
        return dt.strftime("%d-%b-%Y %H:%M")
    except:
        return ts_str
def _truncate(text, max_len=50):
    if len(text) <= max_len:
        return text
    return text[:max_len-1] + '…'
def run_notes_app(active_ticker):
    notes = _load_notes()
    while True:
        clear()
        notes = _load_notes()
        notes_sorted = sorted(notes,
                              key=lambda n: (n.get('pinned', False),
                                             n.get('modified', n.get('created', ''))),
                              reverse=True)
        total_notes = len(notes)
        ticker_notes = [n for n in notes if n.get('ticker') == active_ticker]
        print(f"""
  ╔══════════════════════════════════════════════════════════════════╗
  ║              📝  NOTES APP                                      ║
  ║  Active Ticker: \033[93m{active_ticker:<42}\033[0m║
  ║  Total Notes: {total_notes:<3}  │  Notes for {active_ticker[:12]}: {len(ticker_notes):<18}║
  ╚══════════════════════════════════════════════════════════════════╝
        """)
        if notes_sorted:
            print("  ┌─── 📋 YOUR NOTES ─────────────────────────────────────────────┐")
            print(f"  │  {'#':<4} {'Pin':<4} {'Ticker':<14} {'Title':<28} {'Modified':<16}│")
            print("  ├──────────────────────────────────────────────────────────────┤")
            display_notes = notes_sorted[:15]
            for i, note in enumerate(display_notes, 1):
                pin_icon = '📌' if note.get('pinned') else '  '
                nticker = note.get('ticker', 'General')[:12]
                title = _truncate(note.get('title', 'Untitled'), 26)
                mod = _format_timestamp(note.get('modified', note.get('created', '')))
                nid = note.get('id', i)
                print(f"  │  {nid:<4} {pin_icon:<4} {nticker:<14} {title:<28} {mod:<16}│")
            if total_notes > 15:
                print(f"  │  … and {total_notes - 15} more notes (use [S] to search)          │")
            print("  └──────────────────────────────────────────────────────────────┘")
        else:
            print("  ┌──────────────────────────────────────────────────────────────┐")
            print("  │  No notes yet! Create your first note with [N] below.      │")
            print("  └──────────────────────────────────────────────────────────────┘")
        print()
        print("  ┌─── Actions ──────────────────────────────────────────────────┐")
        print("  │  [N]    New Note                                             │")
        print("  │  [V]    View a Note (by ID)                                  │")
        print("  │  [E]    Edit a Note (by ID)                                  │")
        print("  │  [D]    Delete a Note (by ID)                                │")
        print("  │  [P]    Toggle Pin on a Note                                 │")
        print("  │  [S]    Search Notes                                         │")
        print("  │  [F]    Filter Notes by Ticker                               │")
        print("  │  [T]    Show Notes for Current Ticker                        │")
        print("  │  [A]    Show All Notes                                       │")
        print("  │  [0]    ← Back to Menu                                      │")
        print("  └─────────────────────────────────────────────────────────────┘")
        action = input("\n  Notes action: ").strip().upper()
        if action == '0':
            break
        elif action == 'N':
            print()
            print("  ┌─── ✏️  CREATE NEW NOTE ──────────────────────────────────────┐")
            print("  │  Link to a ticker, or leave blank for a general note.      │")
            print("  └──────────────────────────────────────────────────────────────┘")
            link_ticker = input(f"  Ticker [{active_ticker}] (Enter=current, G=General): ").strip().upper()
            if link_ticker == 'G' or link_ticker == 'GENERAL':
                link_ticker = None
            elif link_ticker == '':
                link_ticker = active_ticker
            else:
                if '.' not in link_ticker:
                    link_ticker += '.NS'
            title = input("  Title: ").strip()
            if not title:
                title = "Untitled Note"
            print("  Content (type your note, press Enter twice to finish):")
            content_lines = []
            empty_count = 0
            while True:
                line = input("  │ ")
                if line == '':
                    empty_count += 1
                    if empty_count >= 2:
                        break
                    content_lines.append('')
                else:
                    empty_count = 0
                    content_lines.append(line)
            while content_lines and content_lines[-1] == '':
                content_lines.pop()
            content = '\n'.join(content_lines)
            tags_input = input("  Tags (comma-separated, or Enter to skip): ").strip()
            tags = [t.strip().lower() for t in tags_input.split(',') if t.strip()] if tags_input else []
            now = _dt.now().isoformat()
            new_note = {
                'id': _next_note_id(notes),
                'title': title,
                'content': content,
                'ticker': link_ticker,
                'tags': tags,
                'pinned': False,
                'created': now,
                'modified': now,
            }
            notes.append(new_note)
            _save_notes(notes)
            print(f"\n  \033[92m✔ Note #{new_note['id']} created successfully!\033[0m")
            if link_ticker:
                print(f"    Linked to: {link_ticker}")
            if tags:
                print(f"    Tags: {', '.join(tags)}")
            input("\n  Press Enter to continue …")
        elif action == 'V':
            note_id = input("  Enter note ID to view: ").strip()
            if note_id.isdigit():
                nid = int(note_id)
                note = next((n for n in notes if n.get('id') == nid), None)
                if note:
                    print()
                    pin_str = " 📌 PINNED" if note.get('pinned') else ""
                    print(f"  ╔══════════════════════════════════════════════════════════════╗")
                    print(f"  ║  📝 NOTE #{note['id']}{pin_str:<52}║")
                    print(f"  ╠══════════════════════════════════════════════════════════════╣")
                    print(f"  ║  Title   : {note.get('title', 'Untitled'):<51}║")
                    ticker_display = note.get('ticker', 'General') or 'General'
                    print(f"  ║  Ticker  : {ticker_display:<51}║")
                    print(f"  ║  Created : {_format_timestamp(note.get('created', '')):<51}║")
                    print(f"  ║  Modified: {_format_timestamp(note.get('modified', '')):<51}║")
                    tags_str = ', '.join(note.get('tags', [])) if note.get('tags') else 'None'
                    print(f"  ║  Tags    : {tags_str:<51}║")
                    print(f"  ╠══════════════════════════════════════════════════════════════╣")
                    content = note.get('content', '')
                    if content:
                        for cline in content.split('\n'):
                            while len(cline) > 60:
                                print(f"  ║  {cline[:60]:<60}║")
                                cline = cline[60:]
                            print(f"  ║  {cline:<60}║")
                    else:
                        print(f"  ║  {'(empty)':<60}║")
                    print(f"  ╚══════════════════════════════════════════════════════════════╝")
                else:
                    print(f"  \033[91m✘ Note #{nid} not found.\033[0m")
            else:
                print("  Invalid ID.")
            input("\n  Press Enter to continue …")
        elif action == 'E':
            note_id = input("  Enter note ID to edit: ").strip()
            if note_id.isdigit():
                nid = int(note_id)
                note = next((n for n in notes if n.get('id') == nid), None)
                if note:
                    print(f"\n  Editing Note #{nid}: {note.get('title', 'Untitled')}")
                    print(f"  (Press Enter to keep current value)\n")
                    new_title = input(f"  Title [{note.get('title', '')}]: ").strip()
                    if new_title:
                        note['title'] = new_title
                    print(f"  Current content:")
                    for cline in (note.get('content', '') or '(empty)').split('\n'):
                        print(f"    {cline}")
                    edit_content = input("\n  Replace content? [Y/N]: ").strip().upper()
                    if edit_content == 'Y':
                        print("  New content (press Enter twice to finish):")
                        content_lines = []
                        empty_count = 0
                        while True:
                            line = input("  │ ")
                            if line == '':
                                empty_count += 1
                                if empty_count >= 2:
                                    break
                                content_lines.append('')
                            else:
                                empty_count = 0
                                content_lines.append(line)
                        while content_lines and content_lines[-1] == '':
                            content_lines.pop()
                        note['content'] = '\n'.join(content_lines)
                    curr_tags = ', '.join(note.get('tags', []))
                    new_tags = input(f"  Tags [{curr_tags}]: ").strip()
                    if new_tags:
                        note['tags'] = [t.strip().lower() for t in new_tags.split(',') if t.strip()]
                    note['modified'] = _dt.now().isoformat()
                    _save_notes(notes)
                    print(f"\n  \033[92m✔ Note #{nid} updated successfully!\033[0m")
                else:
                    print(f"  \033[91m✘ Note #{nid} not found.\033[0m")
            else:
                print("  Invalid ID.")
            input("\n  Press Enter to continue …")
        elif action == 'D':
            note_id = input("  Enter note ID to delete: ").strip()
            if note_id.isdigit():
                nid = int(note_id)
                note = next((n for n in notes if n.get('id') == nid), None)
                if note:
                    print(f"\n  Note #{nid}: {note.get('title', 'Untitled')}")
                    confirm = input("  Are you sure you want to delete? [Y/N]: ").strip().upper()
                    if confirm == 'Y':
                        notes = [n for n in notes if n.get('id') != nid]
                        _save_notes(notes)
                        print(f"  \033[91m✘ Note #{nid} deleted.\033[0m")
                    else:
                        print("  Cancelled.")
                else:
                    print(f"  \033[91m✘ Note #{nid} not found.\033[0m")
            else:
                print("  Invalid ID.")
            input("\n  Press Enter to continue …")
        elif action == 'P':
            note_id = input("  Enter note ID to pin/unpin: ").strip()
            if note_id.isdigit():
                nid = int(note_id)
                note = next((n for n in notes if n.get('id') == nid), None)
                if note:
                    note['pinned'] = not note.get('pinned', False)
                    note['modified'] = _dt.now().isoformat()
                    _save_notes(notes)
                    state = '📌 Pinned' if note['pinned'] else 'Unpinned'
                    print(f"  \033[92m✔ Note #{nid} {state}.\033[0m")
                else:
                    print(f"  \033[91m✘ Note #{nid} not found.\033[0m")
            else:
                print("  Invalid ID.")
            input("\n  Press Enter to continue …")
        elif action == 'S':
            query = input("  Search query: ").strip().lower()
            if query:
                results = []
                for n in notes:
                    searchable = ' '.join([
                        n.get('title', ''),
                        n.get('content', ''),
                        n.get('ticker', ''),
                        ' '.join(n.get('tags', [])),
                    ]).lower()
                    if query in searchable:
                        results.append(n)
                print(f"\n  Found {len(results)} note(s) matching '{query}':")
                if results:
                    print("  ┌──────────────────────────────────────────────────────────────┐")
                    for n in results[:20]:
                        pin = '📌' if n.get('pinned') else '  '
                        nticker = (n.get('ticker') or 'General')[:12]
                        title = _truncate(n.get('title', 'Untitled'), 26)
                        print(f"  │  #{n['id']:<4} {pin} {nticker:<14} {title:<30}│")
                    print("  └──────────────────────────────────────────────────────────────┘")
                else:
                    print("  No notes found.")
            input("\n  Press Enter to continue …")
        elif action == 'F':
            filter_ticker = input("  Filter by ticker (e.g. RELIANCE.NS): ").strip().upper()
            if filter_ticker:
                if '.' not in filter_ticker:
                    filter_ticker += '.NS'
                filtered = [n for n in notes if n.get('ticker') == filter_ticker]
                print(f"\n  Notes for {filter_ticker}: {len(filtered)}")
                if filtered:
                    print("  ┌──────────────────────────────────────────────────────────────┐")
                    for n in filtered:
                        pin = '📌' if n.get('pinned') else '  '
                        title = _truncate(n.get('title', 'Untitled'), 30)
                        mod = _format_timestamp(n.get('modified', n.get('created', '')))
                        print(f"  │  #{n['id']:<4} {pin} {title:<34} {mod:<16}│")
                    print("  └──────────────────────────────────────────────────────────────┘")
            input("\n  Press Enter to continue …")
        elif action == 'T':
            filtered = [n for n in notes if n.get('ticker') == active_ticker]
            print(f"\n  Notes for {active_ticker}: {len(filtered)}")
            if filtered:
                print("  ┌──────────────────────────────────────────────────────────────┐")
                for n in filtered:
                    pin = '📌' if n.get('pinned') else '  '
                    title = _truncate(n.get('title', 'Untitled'), 30)
                    mod = _format_timestamp(n.get('modified', n.get('created', '')))
                    print(f"  │  #{n['id']:<4} {pin} {title:<34} {mod:<16}│")
                print("  └──────────────────────────────────────────────────────────────┘")
            else:
                print(f"  No notes for {active_ticker}. Create one with [N].")
            input("\n  Press Enter to continue …")
        elif action == 'A':
            if notes_sorted:
                print(f"\n  All Notes ({total_notes} total):")
                print("  ┌──────────────────────────────────────────────────────────────┐")
                print(f"  │  {'ID':<5}{'Pin':<4} {'Ticker':<14} {'Title':<28} {'Modified':<13}│")
                print("  ├──────────────────────────────────────────────────────────────┤")
                for n in notes_sorted:
                    pin = '📌' if n.get('pinned') else '  '
                    nticker = (n.get('ticker') or 'General')[:12]
                    title = _truncate(n.get('title', 'Untitled'), 26)
                    mod = _format_timestamp(n.get('modified', n.get('created', '')))
                    print(f"  │  #{n['id']:<4}{pin:<4} {nticker:<14} {title:<28} {mod:<13}│")
                print("  └──────────────────────────────────────────────────────────────┘")
            else:
                print("  No notes yet.")
            input("\n  Press Enter to continue …")
        else:
            print("  Invalid choice.")
            input("  Press Enter to continue …")
_ticker_history = []
def _record_ticker(ticker):
    if ticker in _ticker_history:
        _ticker_history.remove(ticker)
    _ticker_history.insert(0, ticker)
    if len(_ticker_history) > 20:
        _ticker_history.pop()
_APP_PREFS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "app_prefs.json")
_DEFAULT_PREFS = {
    "startup_mode":    "dashboard",                           
    "default_ticker":  "",                                       
    "theme":           "dark",                      
    "snapshot_auto":   True,                                        
    "batch_modules":   ["1","7","9"],                    
    "or_model":        _GLOBAL_OR_MODEL,                                       
}
def load_app_prefs():
    try:
        with open(_APP_PREFS_FILE, 'r') as f:
            data = json.load(f)
            return {**_DEFAULT_PREFS, **data}
    except (FileNotFoundError, json.JSONDecodeError):
        return dict(_DEFAULT_PREFS)
def save_app_prefs(prefs):
    with open(_APP_PREFS_FILE, 'w') as f:
        json.dump(prefs, f, indent=2)
def _apply_saved_model():
    global _GLOBAL_OR_MODEL
    try:
        with open(_APP_PREFS_FILE, 'r') as f:
            data = json.load(f)
        saved = data.get("or_model", "").strip()
        if saved:
            _GLOBAL_OR_MODEL = saved
    except (FileNotFoundError, json.JSONDecodeError):
        pass
_apply_saved_model()                           
def show_startup_splash(prefs):
    clear()
    last = prefs.get("default_ticker", "") or ""
    last_hint = f"  (last: \033[93m{last}\033[0m)" if last else ""
    print("""
  ╔══════════════════════════════════════════════════════════════════╗
  ║        🇮🇳  INDIAN STOCK MARKET ANALYSIS SUITE                  ║
  ║             NSE / BSE  •  Full Terminal Platform                 ║
  ╚══════════════════════════════════════════════════════════════════╝
""")
    print("  ┌─── STARTUP MODE ────────────────────────────────────────────┐")
    print("  │                                                             │")
    print("  │  [1]  📊  Load Live Market Dashboard                       │")
    print("  │          Full indexes, gainers/losers, sectors, watchlist  │")
    print("  │          ⚠  Takes ~20–35 sec (live data fetch)             │")
    print("  │                                                             │")
    print("  │  [2]  ⚡  Jump Directly to a Ticker                        │")
    print("  │          Instant — skip the dashboard entirely             │")
    print(f"  │          Enter any NSE/BSE symbol{last_hint:<29}│")
    print("  │                                                             │")
    print("  │  [3]  ⚙   Settings                                         │")
    print("  │                                                             │")
    print("  └─────────────────────────────────────────────────────────────┘")
    mode_label = "dashboard" if prefs["startup_mode"] == "dashboard" else "direct"
    print(f"\n  Default mode: \033[96m{mode_label}\033[0m  (change in Settings)")
    choice = input("\n  Select [1/2/3, or ENTER for default]: ").strip()
    if choice == "3":
        run_settings_standalone(prefs)
        return show_startup_splash(prefs)                           
    if choice == "1" or (choice == "" and prefs["startup_mode"] == "dashboard"):
        return "dashboard", None
    if choice == "2" or (choice == "" and prefs["startup_mode"] == "direct"):
        return "direct", None
    return prefs["startup_mode"], None
def prompt_direct_ticker(prefs):
    clear()
    last = prefs.get("default_ticker", "")
    print("""
  ╔══════════════════════════════════════════════════════════════════╗
  ║        ⚡  DIRECT TICKER JUMP                                    ║
  ╚══════════════════════════════════════════════════════════════════╝
""")
    if last:
        print(f"  Last ticker: \033[93m{last}\033[0m  (press ENTER to reuse)")
    wl = load_watchlist()
    if wl:
        print(f"\n  Your Watchlist: ", end="")
        print("  ".join(f"\033[96m{t.replace('.NS','').replace('.BO','')}\033[0m" for t in wl[:10]))
    raw = input("\n  Enter ticker (e.g. RELIANCE.NS, TCS): ").strip().upper()
    if raw == "" and last:
        raw = last
    if not raw:
        raw = "RELIANCE.NS"
    if '.' not in raw:
        raw += ".NS"
    print(f"\n  ✔  Jumping to \033[92m{raw}\033[0m …")
    return raw
def run_settings_standalone(prefs):
    while True:
        clear()
        mode_label = "Live Dashboard" if prefs["startup_mode"] == "dashboard" else "Direct Ticker Jump"
        snap_label = "ON" if prefs.get("snapshot_auto", True) else "OFF"
        batch_mods = ", ".join(prefs.get("batch_modules", []))
        def_tick   = prefs.get("default_ticker", "") or "(none)"
        print("""
  ╔══════════════════════════════════════════════════════════════════╗
  ║        ⚙   ADVANCED SETTINGS                                     ║
  ╚══════════════════════════════════════════════════════════════════╝
""")
        print("  ┌─── STARTUP & BEHAVIOUR ─────────────────────────────────────┐")
        print(f"  │  [1]  Startup Mode        : \033[93m{mode_label:<34}\033[0m│")
        print(f"  │  [2]  Default Ticker      : \033[93m{def_tick:<34}\033[0m│")
        print(f"  │  [3]  Auto Snapshot       : \033[93m{snap_label:<34}\033[0m│")
        print("  ├─── DATA & CACHE ────────────────────────────────────────────┤")
        print("  │  [4]  Purge YFinance Cache  (force fresh on next run)       │")
        print("  │  [5]  Prefetch Watchlist    (warm cache in background)      │")
        print("  ├─── WATCHLIST & PORTFOLIO ──────────────────────────────────┤")
        print("  │  [6]  Manage Watchlist      (add / remove tickers)         │")
        print("  │  [7]  Manage Portfolio       (add / remove holdings)        │")
        print("  ├─── BATCH & EXPORT ─────────────────────────────────────────┤")
        print(f"  │  [8]  Batch Modules        : \033[93m{batch_mods:<34}\033[0m│")
        print("  │  [0]  ← Back                                               │")
        print("  └─────────────────────────────────────────────────────────────┘")
        ch = input("\n  Choose setting [0-9]: ").strip()
        if ch == "1":
            prefs["startup_mode"] = "direct" if prefs["startup_mode"] == "dashboard" else "dashboard"
            save_app_prefs(prefs)
            print(f"\n  ✔  Startup mode set to: \033[92m{prefs['startup_mode']}\033[0m")
            time.sleep(0.8)
        elif ch == "2":
            t = input("  Enter default ticker (e.g. RELIANCE.NS): ").strip().upper()
            if t:
                if '.' not in t:
                    t += ".NS"
                prefs["default_ticker"] = t
                save_app_prefs(prefs)
                print(f"  ✔  Default ticker set to \033[92m{t}\033[0m")
            time.sleep(0.8)
        elif ch == "3":
            prefs["snapshot_auto"] = not prefs.get("snapshot_auto", True)
            save_app_prefs(prefs)
            state = "ON" if prefs["snapshot_auto"] else "OFF"
            print(f"  ✔  Auto Snapshot: \033[92m{state}\033[0m")
            time.sleep(0.8)
        elif ch == "4":
            _YF_DOWNLOAD_CACHE.clear()
            _YF_INFO_CACHE.clear()
            import shutil, pathlib
            cache_dir = pathlib.Path.home() / ".cache" / "py-yfinance"
            if cache_dir.exists():
                try:
                    shutil.rmtree(str(cache_dir))
                    print("  ✔  On-disk yfinance cache purged.")
                except Exception as e:
                    print(f"  ⚠  Could not purge disk cache: {e}")
            else:
                print("  ✔  In-memory cache cleared (no disk cache found).")
            time.sleep(1.2)
        elif ch == "5":
            wl = load_watchlist()
            if not wl:
                print("  ⚠  Watchlist is empty. Add tickers first.")
                time.sleep(1)
                continue
            print(f"\n  Prefetching {len(wl)} tickers in parallel …")
            import threading, io as _io, contextlib as _ctx
            errors = []
            def _fetch(sym):
                try:
                    with _ctx.redirect_stdout(_io.StringIO()), _ctx.redirect_stderr(_io.StringIO()):
                        yf.download(sym, period="3mo", interval="1d", progress=False)
                    t_obj = yf.Ticker(sym)
                    _ = t_obj.info
                except Exception as e:
                    errors.append(f"{sym}: {e}")
            threads = [threading.Thread(target=_fetch, args=(s,), daemon=True) for s in wl]
            for th in threads: th.start()
            for th in threads: th.join()
            ok = len(wl) - len(errors)
            print(f"  ✔  Prefetch complete: {ok}/{len(wl)} succeeded.")
            if errors:
                for err in errors[:3]:
                    print(f"  ⚠  {err}")
            time.sleep(1.5)
        elif ch == "6":
            _settings_manage_list("watchlist", load_watchlist, save_watchlist)
        elif ch == "7":
            _settings_manage_list("portfolio", load_portfolio, save_portfolio)
        elif ch == "8":
            print(f"\n  Current batch set: \033[93m{batch_mods}\033[0m")
            raw = input("  Enter comma-separated module numbers (e.g. 1,7,9,10): ").strip()
            nums = [x.strip() for x in raw.split(",") if x.strip().isdigit()]
            if nums:
                prefs["batch_modules"] = nums
                save_app_prefs(prefs)
                print(f"  ✔  Batch modules set to: {', '.join(nums)}")
            time.sleep(0.8)
        elif ch == "9":
            print("  [!] Export feature is disabled in this build.")
            time.sleep(1)
        elif ch == "0":
            break
def _settings_manage_list(list_name, load_fn, save_fn):
    while True:
        lst = load_fn()
        clear()
        print(f"\n  ── {list_name.upper()} MANAGER {'─'*45}")
        if lst:
            for i, t in enumerate(lst, 1):
                print(f"  [{i:>2}]  {t}")
        else:
            print("  (empty)")
        print(f"\n  [A] Add ticker   [R] Remove ticker   [C] Clear all   [0] Back")
        ch = input("  Choice: ").strip().upper()
        if ch == "0":
            break
        elif ch == "A":
            t = input("  Ticker to add (e.g. WIPRO.NS): ").strip().upper()
            if t:
                if '.' not in t:
                    t += ".NS"
                if t not in lst:
                    lst.append(t)
                    save_fn(lst)
                    print(f"  ✔  {t} added.")
                else:
                    print(f"  ⚠  {t} already in list.")
            time.sleep(0.6)
        elif ch == "R":
            n = input("  Number to remove: ").strip()
            if n.isdigit():
                idx = int(n) - 1
                if 0 <= idx < len(lst):
                    removed = lst.pop(idx)
                    save_fn(lst)
                    print(f"  ✔  {removed} removed.")
            time.sleep(0.6)
        elif ch == "C":
            confirm = input("  Clear all? [Y/N]: ").strip().upper()
            if confirm == "Y":
                save_fn([])
                print("  ✔  Cleared.")
            time.sleep(0.6)
def clear():
    if _CLI_BATCH_MODE or not sys.stdout.isatty():
        return
    os.system('cls' if os.name == 'nt' else 'clear')
def header(title):
    w = 70
    print("\n" + "═" * w)
    print(f"  {title}")
    print("═" * w)
def section(title):
    print(f"\n  ── {title} {'─'*(60-len(title))}")
def flatten_cols(df):
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = df.columns.droplevel(1)
    return df
def get_safe(df, keys):
    for key in keys:
        if key in df.index:
            return df.loc[key].fillna(0)
    return pd.Series(0, index=df.columns)
def get_val(df, keys, col_idx=0, default=0):
    for key in keys:
        if key in df.index:
            val = df.iloc[:, col_idx].loc[key]
            if pd.notna(val):
                return val
    return default
def safe_div(num, den):
    return np.where(den != 0, num / den, 0)
