def _fetch_quick_data(ticker_list, period='5d'):
    data = {}
    for sym in ticker_list:
        try:
            import io, contextlib
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
                d = yf.download(sym, period=period, interval='1d', progress=False)
            d = flatten_cols(d)
            if len(d) >= 2:
                data[sym] = d
        except Exception:
            pass
    return data
def _compute_changes(price_data):
    results = []
    for sym, d in price_data.items():
        try:
            curr  = float(d['Close'].iloc[-1])
            prev  = float(d['Close'].iloc[-2])
            daily = ((curr - prev) / prev) * 100
            if len(d) >= 5:
                week_ago = float(d['Close'].iloc[-5])
                weekly   = ((curr - week_ago) / week_ago) * 100
            else:
                weekly = daily
            clean = sym.replace('.NS', '').replace('.BO', '')
            results.append((clean, daily, weekly, curr))
        except Exception:
            pass
    results.sort(key=lambda x: x[1], reverse=True)
    return results
def fetch_market_movers():
    header("📡  FETCHING TODAY'S MARKET MOVERS  (NSE Watchlist)")
    print("  Downloading intraday snapshots — this may take ~20 sec …\n")
    results = []
    import io, contextlib
    for sym in WATCHLIST:
        try:
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
                d = yf.download(sym, period="2d", interval="1d", progress=False)
            d = flatten_cols(d)
            if len(d) >= 2:
                prev  = float(d['Close'].iloc[-2])
                curr  = float(d['Close'].iloc[-1])
                chg   = ((curr - prev) / prev) * 100
                results.append((sym.replace(".NS", ""), chg, curr))
        except Exception:
            pass
    results.sort(key=lambda x: x[1], reverse=True)
    return results
def fetch_index_data():
    print("  📊 Fetching market indexes …")
    import io, contextlib
    idx_results = []
    for name, sym in MARKET_INDEXES.items():
        try:
            with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
                d = yf.download(sym, period='5d', interval='1d', progress=False)
            d = flatten_cols(d)
            if len(d) >= 2:
                curr  = float(d['Close'].iloc[-1])
                prev  = float(d['Close'].iloc[-2])
                daily = ((curr - prev) / prev) * 100
                if len(d) >= 5:
                    w_ago  = float(d['Close'].iloc[-5])
                    weekly = ((curr - w_ago) / w_ago) * 100
                else:
                    weekly = daily
                idx_results.append((name, curr, daily, weekly))
        except Exception:
            pass
    return idx_results
def fetch_sector_performance():
    print("  🏭 Fetching sector performance …")
    import io, contextlib
    sector_perf = []
    for key in sorted(STARTUP_SECTORS.keys(), key=int):
        sec_name, stocks = STARTUP_SECTORS[key]
        sample = stocks[:5]
        daily_chgs, weekly_chgs = [], []
        for sym in sample:
            try:
                with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
                    d = yf.download(sym, period='5d', interval='1d', progress=False)
                d = flatten_cols(d)
                if len(d) >= 2:
                    curr = float(d['Close'].iloc[-1])
                    prev = float(d['Close'].iloc[-2])
                    daily_chgs.append(((curr - prev) / prev) * 100)
                    if len(d) >= 5:
                        w = float(d['Close'].iloc[-5])
                        weekly_chgs.append(((curr - w) / w) * 100)
            except Exception:
                pass
        avg_daily  = sum(daily_chgs)  / len(daily_chgs)  if daily_chgs else 0
        avg_weekly = sum(weekly_chgs) / len(weekly_chgs) if weekly_chgs else 0
        sector_perf.append((key, sec_name, avg_daily, avg_weekly))
    return sector_perf
def display_market_dashboard(movers, idx_data, sector_perf):
    clear()
    def chg_clr(v):
        if v >= 0.5:  return '\033[92m'                
        if v >= 0:    return '\033[32m'         
        if v >= -0.5: return '\033[91m'             
        return '\033[91m'       
    def chg_icon(v):
        return '▲' if v >= 0 else '▼'
    now = datetime.now().strftime("%d-%b-%Y  %H:%M:%S")
    print(f"""
  ╔══════════════════════════════════════════════════════════════════════════════╗
  ║     INDIAN STOCK MARKET ANALYSIS SUITE  —  LIVE MARKET DASHBOARD           ║
  ║     🕐 {now}                                                    ║
  ╚══════════════════════════════════════════════════════════════════════════════╝
    """)
    print("  ┌─── 📊 MARKET INDEXES ──────────────────────────────────────────────────────┐")
    print(f"  │  {'Index':<18} {'Price':>12}   {'Daily Chg':>12}   {'Weekly Chg':>12}          │")
    print("  ├──────────────────────────────────────────────────────────────────────────────┤")
    for name, price, daily, weekly in idx_data:
        dc = chg_clr(daily)
        wc = chg_clr(weekly)
        di = chg_icon(daily)
        wi = chg_icon(weekly)
        if price > 1000:
            p_str = f"{price:>12,.2f}"
        else:
            p_str = f"{price:>12.2f}"
        d_txt = f"{di} {daily:+6.2f}%"               
        w_txt = f"{wi} {weekly:+6.2f}%"              
        row  = f"  │  {name:<18} {p_str}   {dc}{d_txt}\033[0m   {wc}{w_txt}\033[0m          │"
        print(row)
    print("  └──────────────────────────────────────────────────────────────────────────────┘")
    gainers = movers[:5]
    losers  = movers[-5:][::-1]
    print()
    print("  ┌──────── 📈 TOP 5 GAINERS ─────────┐  ┌──────── 📉 TOP 5 LOSERS ──────────┐")
    print("  │  Ticker        Chg%       Price    │  │  Ticker        Chg%       Price    │")
    print("  ├─────────────────────────────────────┤  ├─────────────────────────────────────┤")
    for i in range(5):
        if i < len(gainers):
            gs, gc, gp = gainers[i]
            g_line = f"  │  \033[92m{gs:<14}{gc:+6.2f}%   ₹{gp:>9,.2f}\033[0m  │"
        else:
            g_line = f"  │{'':37}│"
        if i < len(losers):
            ls, lc, lp = losers[i]
            l_line = f"  │  \033[91m{ls:<14}{lc:+6.2f}%   ₹{lp:>9,.2f}\033[0m  │"
        else:
            l_line = f"  │{'':37}│"
        print(f"{g_line}  {l_line}")
    print("  └─────────────────────────────────────┘  └─────────────────────────────────────┘")
    print()
    W_TOTAL = 88                                           
    print(f"  ┌{'─' * W_TOTAL}┐")
    print(f"  │{'🏭 SECTOR PERFORMANCE':^{W_TOTAL}}│")
    print(f"  ├{'─' * W_TOTAL}┤")
    CELL_W = 43
    def _sector_cell(key, name, daily, weekly):
        dc = chg_clr(daily)
        wc = chg_clr(weekly)
        di = chg_icon(daily)
        wi = chg_icon(weekly)
        label = f"[{key:>2}] {name:<18}"                     
        d_txt = f"{di} {daily:+6.2f}%"                      
        w_txt = f"{wi} {weekly:+6.2f}%"                     
        return f"{label} {dc}{d_txt}\033[0m {wc}{w_txt}\033[0m"
    half = (len(sector_perf) + 1) // 2                          
    for row_i in range(half):
        left_idx  = row_i
        right_idx = row_i + half
        if left_idx < len(sector_perf):
            lk, ln, ld, lw = sector_perf[left_idx]
            left_cell = _sector_cell(lk, ln, ld, lw)
        else:
            left_cell = ' ' * CELL_W
        if right_idx < len(sector_perf):
            rk, rn, rd, rw = sector_perf[right_idx]
            right_cell = _sector_cell(rk, rn, rd, rw)
        else:
            right_cell = ' ' * CELL_W
        print(f"  │ {left_cell} │ {right_cell} │")
    print(f"  └{'─' * W_TOTAL}┘")
    print()
    wl_list = load_watchlist()
    if wl_list:
        print(f"  ┌─── ⭐ MY WATCHLIST {'─' * 69}┐")
        print(f"  │  Loading stock data …{' ' * 66}│", end="\r")
        import io as _io, contextlib as _ctxlib, yfinance as _yf
        wl_data = {}
        for _wt in wl_list:
            try:
                _tobj = _yf.Ticker(_wt)
                _inf = _tobj.info
                with _ctxlib.redirect_stdout(_io.StringIO()), _ctxlib.redirect_stderr(_io.StringIO()):
                    _hd = _yf.download(_wt, period="5d", interval="1d", progress=False)
                if not _hd.empty:
                    _hd = flatten_cols(_hd)
                    _cprice = float(_hd['Close'].iloc[-1]) if len(_hd) >= 1 else 0
                    _pprice = float(_hd['Close'].iloc[-2]) if len(_hd) >= 2 else _cprice
                    _dchg = ((_cprice - _pprice) / _pprice * 100) if _pprice else 0
                else:
                    _cprice, _dchg = 0, 0
                _hi52 = _inf.get('fiftyTwoWeekHigh', 0)
                _lo52 = _inf.get('fiftyTwoWeekLow', 0)
                _mcap = _inf.get('marketCap', 0)
                wl_data[_wt] = {'price': _cprice, 'chg': _dchg,
                                'hi52': _hi52, 'lo52': _lo52, 'mcap': _mcap}
            except Exception:
                wl_data[_wt] = None
        print(f"  │{' ' * 88}│", end="\r")                     
        print(f"  │  {'#':>3}  {'Ticker':<14} {'Price (₹)':>12}  {'Day Chg':>10}  {'52W Low':>10}  {'52W High':>10}  {'Mkt Cap':>14}  │")
        print(f"  ├{'─' * 88}┤")
        for j, wt in enumerate(wl_list, 1):
            d = wl_data.get(wt)
            if d:
                dc = '\033[92m' if d['chg'] >= 0 else '\033[91m'
                di = '▲' if d['chg'] >= 0 else '▼'
                mc = d['mcap']
                if mc and mc >= 1e12:
                    mc_str = f"₹{mc/1e7/1e5:,.1f}LCr"
                elif mc and mc >= 1e7:
                    mc_str = f"₹{mc/1e7:,.0f}Cr"
                else:
                    mc_str = "—"
                print(f"  │  [{j:>2}]  {wt:<14} ₹{d['price']:>10,.2f}  {dc}{di}{d['chg']:>+7.2f}%\033[0m  ₹{d['lo52']:>8,.0f}  ₹{d['hi52']:>8,.0f}  {mc_str:>14}  │")
            else:
                print(f"  │  [{j:>2}]  {wt:<14} {'—':>12}  {'—':>10}  {'—':>10}  {'—':>10}  {'—':>14}  │")
        print(f"  └{'─' * 88}┘")
        print()
    return gainers, losers
def display_sector_drilldown(sector_key):
    if sector_key not in STARTUP_SECTORS:
        print("  ⚠  Invalid sector.")
        return
    sec_name, stocks = STARTUP_SECTORS[sector_key]
    header(f"🏭 SECTOR DRILL-DOWN — {sec_name} ({len(stocks)} stocks)")
    print("  ⏳ Fetching company data … (this may take ~15 sec)\n")
    price_data = _fetch_quick_data(stocks[:15], period='5d')
    results    = _compute_changes(price_data)
    if not results:
        print("  ⚠  Could not fetch data for this sector.")
        press_enter()
        return
    avg_daily  = sum(r[1] for r in results) / len(results) if results else 0
    avg_weekly = sum(r[2] for r in results) / len(results) if results else 0
    avg_clr_d  = '\033[92m' if avg_daily >= 0 else '\033[91m'
    avg_clr_w  = '\033[92m' if avg_weekly >= 0 else '\033[91m'
    print(f"  ┌─── {sec_name} — SECTOR OVERVIEW ──────────────────────────────────────────┐")
    print(f"  │  Sector Avg Daily Change  : {avg_clr_d}{avg_daily:+.2f}%\033[0m                                   │")
    print(f"  │  Sector Avg Weekly Change : {avg_clr_w}{avg_weekly:+.2f}%\033[0m                                   │")
    print(f"  │  Companies Tracked        : {len(results)}                                        │")
    print(f"  └──────────────────────────────────────────────────────────────────────────────┘")
    print()
    print(f"  ┌──────────────────────────────────────────────────────────────────────────────┐")
    print(f"  │  {'#':<4} {'Company':<16} {'Price (₹)':>12}  {'Daily Chg':>12}  {'Weekly Chg':>12}       │")
    print(f"  ├──────────────────────────────────────────────────────────────────────────────┤")
    for i, (sym, daily, weekly, price) in enumerate(results[:15], 1):
        dc = '\033[92m' if daily >= 0 else '\033[91m'
        wc = '\033[92m' if weekly >= 0 else '\033[91m'
        di = '▲' if daily >= 0 else '▼'
        wi = '▲' if weekly >= 0 else '▼'
        print(f"  │  {i:<4} {sym:<16} ₹{price:>10,.2f}  {dc}{di} {daily:+6.2f}%\033[0m   {wc}{wi} {weekly:+6.2f}%\033[0m       │")
    print(f"  └──────────────────────────────────────────────────────────────────────────────┘")
    best  = results[0]
    worst = results[-1]
    print()
    print(f"  🏆 Best Performer  : \033[92m{best[0]} ({best[1]:+.2f}% daily, {best[2]:+.2f}% weekly)\033[0m")
    print(f"  📉 Worst Performer : \033[91m{worst[0]} ({worst[1]:+.2f}% daily, {worst[2]:+.2f}% weekly)\033[0m")
    print()
    return results
def pick_ticker_enhanced(movers, gainers, losers, idx_data, sector_perf):
    all_movers = sorted(movers, key=lambda x: x[1], reverse=True)
    while True:
        print("  ═══════════════════════════════════════════════════════════════")
        print("  ┌─── SELECT AN ACTION ────────────────────────────────────────┐")
        print("  │  [G]      View Top 20 Gainers of the Day                   │")
        print("  │  [L]      View Top 20 Losers of the Day                    │")
        print("  │  [G1–G5]  Quick-pick from Top Gainers                      │")
        print("  │  [L1–L5]  Quick-pick from Top Losers                       │")
        print("  │  [S1–S20] Drill into a Sector (view top 15 companies)      │")
        print("  │  [T]      Enter a custom ticker symbol                     │")
        print("  │  [W]      Open Watchlist / Pick from Favourites            │")
        print("  │  [P]      Open Portfolio / Pick from Owned                 │")
        print("  │  [R]      Refresh all data (live update)                   │")
        print("  └─────────────────────────────────────────────────────────────┘")
        raw = input("\n  Your choice: ").strip().upper()
        if raw == 'G':
            top_gainers = [m for m in all_movers if m[1] >= 0][:20]
            if not top_gainers:
                top_gainers = all_movers[:20]
            print()
            print("  ┌──────────────────────────────────────────────────────────────────┐")
            print("  │              📈  TOP 20 GAINERS OF THE DAY                       │")
            print("  ├──────────────────────────────────────────────────────────────────┤")
            print(f"  │  {'#':<4} {'Ticker':<16} {'Daily Chg':<14} {'Price (₹)':>14}        │")
            print("  ├──────────────────────────────────────────────────────────────────┤")
            for i, (sym, chg, price) in enumerate(top_gainers, 1):
                dc = '\033[92m' if chg >= 0 else '\033[91m'
                di = '▲' if chg >= 0 else '▼'
                print(f"  │  {i:<4} {sym:<16} {dc}{di} {chg:+7.2f}%\033[0m   ₹{price:>10,.2f}        │")
            print("  ├──────────────────────────────────────────────────────────────────┤")
            print("  │  [ 0]  ← Back to Menu                                           │")
            print("  └──────────────────────────────────────────────────────────────────┘")
            pick = input("\n  Pick a gainer [1-20, or 0 to go back]: ").strip()
            if pick.isdigit():
                pn = int(pick)
                if 1 <= pn <= len(top_gainers):
                    sym = top_gainers[pn-1][0]
                    ticker = sym if '.NS' in sym or '.BO' in sym else sym + ".NS"
                    print(f"\n  ✔ Selected: {ticker}")
                    return ticker
            continue
        elif raw == 'L':
            top_losers = [m for m in all_movers if m[1] < 0]
            top_losers.sort(key=lambda x: x[1])                      
            top_losers = top_losers[:20]
            if not top_losers:
                top_losers = all_movers[-20:][::-1]
            print()
            print("  ┌──────────────────────────────────────────────────────────────────┐")
            print("  │              📉  TOP 20 LOSERS OF THE DAY                        │")
            print("  ├──────────────────────────────────────────────────────────────────┤")
            print(f"  │  {'#':<4} {'Ticker':<16} {'Daily Chg':<14} {'Price (₹)':>14}        │")
            print("  ├──────────────────────────────────────────────────────────────────┤")
            for i, (sym, chg, price) in enumerate(top_losers, 1):
                dc = '\033[92m' if chg >= 0 else '\033[91m'
                di = '▲' if chg >= 0 else '▼'
                print(f"  │  {i:<4} {sym:<16} {dc}{di} {chg:+7.2f}%\033[0m   ₹{price:>10,.2f}        │")
            print("  ├──────────────────────────────────────────────────────────────────┤")
            print("  │  [ 0]  ← Back to Menu                                           │")
            print("  └──────────────────────────────────────────────────────────────────┘")
            pick = input("\n  Pick a loser [1-20, or 0 to go back]: ").strip()
            if pick.isdigit():
                pn = int(pick)
                if 1 <= pn <= len(top_losers):
                    sym = top_losers[pn-1][0]
                    ticker = sym if '.NS' in sym or '.BO' in sym else sym + ".NS"
                    print(f"\n  ✔ Selected: {ticker}")
                    return ticker
            continue
        elif raw.startswith('G') and len(raw) >= 2 and raw[1:].isdigit():
            n = int(raw[1:])
            if 1 <= n <= len(gainers):
                sym = gainers[n-1][0]
                ticker = sym + ".NS"
                print(f"\n  ✔ Selected: {ticker}")
                return ticker
            else:
                print("  Invalid gainer number.")
        elif raw.startswith('L') and len(raw) >= 2 and raw[1:].isdigit():
            n = int(raw[1:])
            all_losers_list = losers if losers else []
            if 1 <= n <= len(all_losers_list):
                sym = all_losers_list[n-1][0]
                ticker = sym + ".NS"
                print(f"\n  ✔ Selected: {ticker}")
                return ticker
            else:
                print("  Invalid loser number.")
        elif raw.startswith('S') and len(raw) >= 2 and raw[1:].isdigit():
            sec_key = raw[1:]
            if sec_key in STARTUP_SECTORS:
                drill_results = display_sector_drilldown(sec_key)
                sec_name, stocks = STARTUP_SECTORS[sec_key]
                perf_lookup = {}
                if drill_results:
                    for (cname, dchg, wchg, cprice) in drill_results:
                        perf_lookup[cname] = (dchg, wchg)
                print(f"  ┌─── PICK FROM {sec_name.upper()} {'─' * max(1, 50 - len(sec_name))}┐")
                for j, stk in enumerate(stocks[:15], 1):
                    clean = stk.replace('.NS', '').replace('.BO', '')
                    if clean in perf_lookup:
                        d_chg, w_chg = perf_lookup[clean]
                        dc = '\033[92m' if d_chg >= 0 else '\033[91m'
                        wc = '\033[92m' if w_chg >= 0 else '\033[91m'
                        di = '▲' if d_chg >= 0 else '▼'
                        wi = '▲' if w_chg >= 0 else '▼'
                        chg_str = f"{dc}{di}{d_chg:+.2f}%\033[0m  {wc}{wi}{w_chg:+.2f}%\033[0m"
                        print(f"  │  [{j:>2}]  {clean:<14} {chg_str}")
                    else:
                        print(f"  │  [{j:>2}]  {clean:<14}   --        --")
                print(f"  │  [ 0]  ← Back to Dashboard")
                print(f"  └{'─' * 58}┘")
                sec_raw = input("\n  Pick company [0 to go back]: ").strip()
                if sec_raw.isdigit():
                    sn = int(sec_raw)
                    if 1 <= sn <= min(15, len(stocks)):
                        ticker = stocks[sn-1]
                        print(f"\n  ✔ Selected: {ticker}")
                        return ticker
                    elif sn == 0:
                        display_market_dashboard(gainers + losers[::-1], idx_data, sector_perf)
                        continue
                print("  Back to main selection.")
            else:
                print(f"  ⚠  Invalid sector. Use S1–S{len(STARTUP_SECTORS)}.")
        elif raw in ('W', 'P'):
            is_portfolio = (raw == 'P')
            lst = load_portfolio() if is_portfolio else load_watchlist()
            if not lst:
                print(f"\n  ⚠  Your {'portfolio' if is_portfolio else 'watchlist'} is empty. Add tickers from the main menu [{'P' if is_portfolio else 'W'}].")
            else:
                print()
                print("  Loading stock data …", end="\r")
                import io as _io, contextlib as _ctxlib
                wl_data = {}
                for _wt in lst:
                    try:
                        _tobj = yf.Ticker(_wt)
                        _inf = _tobj.info
                        with _ctxlib.redirect_stdout(_io.StringIO()), _ctxlib.redirect_stderr(_io.StringIO()):
                            _hd = yf.download(_wt, period="3mo", interval="1d", progress=False)
                        _hd = flatten_cols(_hd)
                        _cprice = float(_hd['Close'].iloc[-1]) if len(_hd) >= 1 else 0
                        _pprice = float(_hd['Close'].iloc[-2]) if len(_hd) >= 2 else _cprice
                        _dchg = ((_cprice - _pprice) / _pprice * 100) if _pprice else 0
                        _hi52 = _inf.get('fiftyTwoWeekHigh', 0)
                        _lo52 = _inf.get('fiftyTwoWeekLow', 0)
                        _vol_raw = _inf.get('volume') or _inf.get('averageVolume') or 0
                        _beta_raw = _inf.get('beta') or 0
                        _rsi = 50.0
                        _trend = "Neutral"
                        if len(_hd) > 30:
                            delta = _hd['Close'].diff()
                            gain = delta.clip(lower=0).rolling(14).mean()
                            loss = (-1 * delta.clip(upper=0)).rolling(14).mean()
                            _rsis = 100 - (100 / (1 + gain / loss))
                            _rsi_val = _rsis.iloc[-1]
                            if not pd.isna(_rsi_val): _rsi = float(_rsi_val)
                            ema12 = _hd['Close'].ewm(span=12, adjust=False).mean()
                            ema26 = _hd['Close'].ewm(span=26, adjust=False).mean()
                            macd = ema12 - ema26
                            signal = macd.ewm(span=9, adjust=False).mean()
                            m_val = float(macd.iloc[-1])
                            s_val = float(signal.iloc[-1])
                            if m_val > s_val and _rsi < 70: _trend = "Bullish"
                            elif m_val < s_val and _rsi > 30: _trend = "Bearish"
                            elif _rsi >= 70: _trend = "Bearish"
                            elif _rsi <= 30: _trend = "Bullish"
                        wl_data[_wt] = {'price': _cprice, 'chg': _dchg,
                                        'hi52': _hi52, 'lo52': _lo52, 'vol': _vol_raw,
                                        'beta': _beta_raw, 'rsi': _rsi, 'trend': _trend}
                    except Exception:
                        wl_data[_wt] = None
                print("                          ", end="\r")                     
                _tbl_title = "Your Portfolio" if is_portfolio else "Your Saved Tickers"
                print(f"  ┌─── {_tbl_title} {'─'*(91 - len(_tbl_title))}┐")
                print(f"  │  {'#':>3}  {'Ticker':<14} {'Price (₹)':>10}  {'Day Chg':>10}  {'52W Low':>8}  {'52W High':>8}  {'Volume':>8}  {'RSI':>4}  {'Beta':>5}  {'MACD':>7}   │")
                print("  ├──────────────────────────────────────────────────────────────────────────────────────────────────┤")
                for idx, t in enumerate(lst, 1):
                    d = wl_data.get(t)
                    if d:
                        dc = '\033[92m' if d['chg'] >= 0 else '\033[91m'
                        di = '▲' if d['chg'] >= 0 else '▼'
                        _vol = d['vol']
                        if _vol >= 1e7: _vol_str = f"{_vol/1e7:,.1f}Cr"
                        elif _vol >= 1e5: _vol_str = f"{_vol/1e5:,.1f}L"
                        elif _vol >= 1000: _vol_str = f"{_vol/1000:,.1f}k"
                        else: _vol_str = f"{_vol:.0f}"
                        _rsi = d['rsi']
                        _rsi_c = '\033[92m' if _rsi < 30 else ('\033[91m' if _rsi > 70 else '')
                        _tr = d['trend']
                        _tr_c = '\033[92m' if 'Bull' in _tr else ('\033[91m' if 'Bear' in _tr else '')
                        print(f"  │  [{idx:>2}]  {t:<14} {d['price']:>10,.2f}  {dc}{di}{d['chg']:>+7.2f}%\033[0m  {d['lo52']:>8,.0f}  {d['hi52']:>8,.0f}  {_vol_str:>8}  {_rsi_c}{_rsi:>4.0f}\033[0m  {d['beta']:>5.2f}  {_tr_c}{_tr:>7}\033[0m   │")
                    else:
                        print(f"  │  [{idx:>2}]  {t:<14} {'—':>10}  {'—':>10}  {'—':>8}  {'—':>8}  {'—':>8}  {'—':>4}  {'—':>5}  {'—':>7}   │")
                print("  ├──────────────────────────────────────────────────────────────────────────────────────────────────┤")
                print(f"  │  [ 0]  ← Back                                                                                    │")
                print(f"  └──────────────────────────────────────────────────────────────────────────────────────────────────┘")
                wpick = input("\n  Pick ticker [0 to go back]: ").strip()
                if wpick.isdigit():
                    wn = int(wpick)
                    if 1 <= wn <= len(lst):
                        ticker = lst[wn - 1]
                        print(f"\n  ✔ Selected: {ticker}")
                        return ticker
            continue
        elif raw == 'T':
            ticker = input("  Enter ticker symbol (e.g. TATAMOTORS.NS): ").strip().upper()
            if ticker:
                print(f"\n  ✔ Using: {ticker}")
                return ticker
        elif raw == 'R':
            print("\n  🔄 Refreshing all market data …\n")
            movers      = fetch_market_movers()
            idx_data    = fetch_index_data()
            sector_perf = fetch_sector_performance()
            gainers_, losers_ = display_market_dashboard(movers, idx_data, sector_perf)
            gainers = gainers_
            losers  = losers_
            all_movers = gainers + losers[::-1]
            continue
        else:
            if raw.isdigit():
                quick = gainers + losers
                n = int(raw)
                if 1 <= n <= len(quick):
                    sym = quick[n-1][0]
                    ticker = sym + ".NS"
                    print(f"\n  ✔ Selected: {ticker}")
                    return ticker
            print("  Invalid choice. Try G, L, G1–G5, L1–L5, S1–S20, T, or R.")
def run_in_session_settings(ticker, prefs, MODULE_DISPATCH):
    global _GLOBAL_OR_MODEL
    while True:
        clear()
        snap_label = "ON" if prefs.get("snapshot_auto", True) else "OFF"
        batch_mods = ", ".join(prefs.get("batch_modules", []))
        print(f"""
  ╔══════════════════════════════════════════════════════════════════╗
  ║        ⚙   SETTINGS  —  Active: \033[93m{ticker:<34}\033[0m║
  ╚══════════════════════════════════════════════════════════════════╝
""")
        print("  ┌─── TICKER ──────────────────────────────────────────────────┐")
        print("  │  [I]  Stock Info / Quick Snapshot (reload current ticker)  │")
        print("  │  [C]  Quick Ticker Change          (instant, no snapshot)  │")
        print("  │  [T]  Full Ticker Change            (with fresh snapshot)  │")
        print("  ├─── PERSONAL DATA ───────────────────────────────────────────┤")
        print("  │  [W]  ⭐ Watchlist Manager          (view / add / remove)  │")
        print("  │  [P]  💼 Portfolio Manager           (view / add / remove)  │")
        print("  │  [N]  📒 Notes App                   (persistent per-ticker)│")
        print("  ├─── HISTORY & PRODUCTIVITY ──────────────────────────────────┤")
        print("  │  [H]  🕐 Recent Tickers               (session history)     │")
        print(f"  │  [B]  🤖 Batch Analysis               (modules: {batch_mods[:26]:<26})│")
        print("  ├─── APP SETTINGS ────────────────────────────────────────────┤")
        print(f"  │  [M]  🧠 Change AI Model               (current: {_GLOBAL_OR_MODEL[:22]:<22})│")
        print(f"  │  [S]  ⚙  App Preferences             (startup, cache …)   │")
        print("  ├─────────────────────────────────────────────────────────────┤")
        print("  │  [Q]  🚪 Quit Application                                   │")
        print("  │  [0]  ← Back to Main Menu                                  │")
        print("  └─────────────────────────────────────────────────────────────┘")
        ch = input("\n  Select: ").strip().upper()
        if ch == "I":
            run_stock_snapshot(ticker)
        elif ch == "C":
            raw = input("  New ticker (e.g. INFY.NS): ").strip().upper()
            if raw:
                if '.' not in raw:
                    raw += ".NS"
                ticker = raw
                _record_ticker(ticker)
                prefs["default_ticker"] = ticker
                save_app_prefs(prefs)
                print(f"  ✔  Switched to \033[92m{ticker}\033[0m  (snapshot skipped)")
                time.sleep(0.7)
                return ticker, prefs
        elif ch == "T":
            raw = input("  New ticker (e.g. HDFCBANK.NS): ").strip().upper()
            if raw:
                if '.' not in raw:
                    raw += ".NS"
                ticker = raw
                _record_ticker(ticker)
                prefs["default_ticker"] = ticker
                save_app_prefs(prefs)
                if prefs.get("snapshot_auto", True):
                    run_stock_snapshot(ticker)
                return ticker, prefs
        elif ch == "W":
            _settings_manage_list_with_add_current(
                "watchlist", load_watchlist, save_watchlist, ticker)
        elif ch == "P":
            _settings_manage_list_with_add_current(
                "portfolio", load_portfolio, save_portfolio, ticker)
        elif ch == "N":
            run_notes_app(ticker)
        elif ch == "H":
            _show_ticker_history(ticker, prefs)
            selected = _pick_from_history()
            if selected:
                ticker = selected
                _record_ticker(ticker)
                prefs["default_ticker"] = ticker
                save_app_prefs(prefs)
                if prefs.get("snapshot_auto", True):
                    run_stock_snapshot(ticker)
                return ticker, prefs
        elif ch == "B":
            ticker, prefs = _run_batch_analysis(ticker, prefs, MODULE_DISPATCH)
        elif ch == "X":
            print("\n  [!] Export feature is disabled in this build.\n")
            time.sleep(1)
        elif ch == "M":
            print(f"\n  Current model : \033[93m{_GLOBAL_OR_MODEL}\033[0m")
            print("  Enter a new OpenRouter model ID, or press ENTER to keep current.")
            print("  Example: nvidia/nemotron-3-super-120b-a12b:free")
            print("           meta-llama/llama-3.3-70b-instruct:free")
            new_model = input("\n  New model ID : ").strip()
            if new_model:
                _GLOBAL_OR_MODEL = new_model
                prefs["or_model"] = new_model
                save_app_prefs(prefs)
                print(f"\n  ✔  Model updated and saved to \033[92m{_GLOBAL_OR_MODEL}\033[0m")
                print("     This will be used on every future run.")
            else:
                print("  (unchanged)")
            time.sleep(1.2)
        elif ch == "S":
            run_settings_standalone(prefs)
        elif ch == "Q":
            print("\n  👋  Goodbye! Happy Trading.\n")
            sys.exit(0)
        elif ch == "0":
            break
    return ticker, prefs
def _settings_manage_list_with_add_current(list_name, load_fn, save_fn, current_ticker):
    while True:
        lst = load_fn()
        clear()
        in_list = current_ticker in lst
        print(f"\n  ── {list_name.upper()} {'─'*50}")
        if lst:
            for i, t in enumerate(lst, 1):
                marker = " \033[92m✓\033[0m" if t == current_ticker else ""
                print(f"  [{i:>2}]  {t}{marker}")
        else:
            print("  (empty)")
        print()
        if not in_list:
            print(f"  [A]  Add current ticker (\033[93m{current_ticker}\033[0m) to {list_name}")
        else:
            print(f"  [A]  Remove current ticker (\033[93m{current_ticker}\033[0m) from {list_name}")
        print("  [+]  Add any ticker    [-]  Remove by number    [C]  Clear all    [0]  Back")
        ch = input("  Choice: ").strip().upper()
        if ch == "0":
            break
        elif ch == "A":
            if not in_list:
                lst.append(current_ticker)
                save_fn(lst)
                print(f"  ✔  {current_ticker} added to {list_name}.")
            else:
                lst.remove(current_ticker)
                save_fn(lst)
                print(f"  ✔  {current_ticker} removed from {list_name}.")
            time.sleep(0.6)
        elif ch == "+":
            t = input("  Ticker to add: ").strip().upper()
            if t:
                if '.' not in t: t += ".NS"
                if t not in lst:
                    lst.append(t); save_fn(lst)
                    print(f"  ✔  {t} added.")
                else:
                    print(f"  ⚠  Already in list.")
            time.sleep(0.6)
        elif ch == "-":
            n = input("  Number to remove: ").strip()
            if n.isdigit():
                idx = int(n) - 1
                if 0 <= idx < len(lst):
                    removed = lst.pop(idx); save_fn(lst)
                    print(f"  ✔  {removed} removed.")
            time.sleep(0.6)
        elif ch == "C":
            if input("  Clear all? [Y/N]: ").strip().upper() == "Y":
                save_fn([]); print("  ✔  Cleared.")
            time.sleep(0.6)
def _show_ticker_history(current_ticker, prefs):
    clear()
    print("\n  ── 🕐  RECENT TICKERS (Session History) " + "─"*32)
    if not _ticker_history:
        print("  (no history this session)")
    else:
        for i, t in enumerate(_ticker_history, 1):
            marker = "  ← current" if t == current_ticker else ""
            print(f"  [{i:>2}]  {t}{marker}")
    print("\n  [0]  Back")
def _pick_from_history():
    if not _ticker_history:
        input("  Press ENTER …")
        return None
    raw = input("\n  Pick number (or 0 to cancel): ").strip()
    if raw.isdigit():
        n = int(raw)
        if 1 <= n <= len(_ticker_history):
            return _ticker_history[n - 1]
    return None
def _run_batch_analysis(ticker, prefs, MODULE_DISPATCH):
    clear()
    batch_mods = prefs.get("batch_modules", ["1","7","9"])
    print(f"""
  ╔══════════════════════════════════════════════════════════════════╗
  ║        🤖  BATCH ANALYSIS ENGINE                                 ║
  ╚══════════════════════════════════════════════════════════════════╝
""")
    print(f"  Current module set : \033[93m{', '.join(batch_mods)}\033[0m")
    print(f"  Current ticker     : \033[93m{ticker}\033[0m\n")
    print("  [1]  Run batch on current ticker")
    print("  [2]  Run batch on ALL watchlist tickers")
    print("  [3]  Run batch on a custom ticker list")
    print("  [4]  Edit module set")
    print("  [0]  Back")
    ch = input("\n  Choice: ").strip()
    if ch == "0":
        return ticker, prefs
    if ch == "4":
        raw = input("  Enter comma-separated module numbers: ").strip()
        nums = [x.strip() for x in raw.split(",") if x.strip().isdigit()]
        if nums:
            prefs["batch_modules"] = nums
            save_app_prefs(prefs)
            batch_mods = nums
        return ticker, prefs
    tickers_to_run = []
    if ch == "1":
        tickers_to_run = [ticker]
    elif ch == "2":
        tickers_to_run = load_watchlist()
        if not tickers_to_run:
            print("  ⚠  Watchlist is empty."); time.sleep(1); return ticker, prefs
    elif ch == "3":
        raw = input("  Enter tickers (comma-separated, e.g. TCS.NS, INFY.NS): ").strip().upper()
        tickers_to_run = [t.strip() if '.' in t.strip() else t.strip()+".NS"
                          for t in raw.split(",") if t.strip()]
    if not tickers_to_run:
        return ticker, prefs
    total = len(tickers_to_run) * len(batch_mods)
    done  = 0
    print(f"\n  Running {len(batch_mods)} modules × {len(tickers_to_run)} ticker(s) = {total} analyses …\n")
    for tkr in tickers_to_run:
        print(f"  ══ Ticker: \033[93m{tkr}\033[0m ══")
        for mod in batch_mods:
            if mod in MODULE_DISPATCH:
                print(f"  → Module [{mod}] …")
                try:
                    MODULE_DISPATCH[mod](tkr)
                except Exception as e:
                    print(f"    ⚠  Module {mod} failed: {e}")
                done += 1
                print(f"  Progress: {done}/{total}")
            else:
                print(f"  ⚠  Module [{mod}] not found, skipping.")
    print(f"\n  ✔  Batch complete for {len(tickers_to_run)} ticker(s).")
    ticker = tickers_to_run[-1]                            
    press_enter()
    return ticker, prefs
import os, sys, json, time, textwrap, contextlib, io as _io
