    {"id": "nvidia/nemotron-3-super-120b-a12b:free",                  "name": "DeepSeek R1",    "note": "★ Best for quant reasoning"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",     "name": "Llama 3.3 70B", "note": "Deep financial language"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",                 "name": "Gemma 3 27B",   "note": "Balanced, fast"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",                "name": "DeepSeek V3",   "note": "Clear concise summaries"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",            "name": "Qwen 2.5 72B",  "note": "Great for emerging markets"},
