def _equity_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title(),
    }
    if not os.path.exists(_EQUITY_AI_CONFIG_FILE):
        return defaults
    try:
        with open(_EQUITY_AI_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**defaults, **data}                                   
    except (json.JSONDecodeError, OSError):
        return defaults
def _equity_save_config(cfg: dict) -> bool:
    try:
        with open(_EQUITY_AI_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump({
                "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
                "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
                "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
            }, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  ⚠  Could not save equity AI config: {exc}")
        return False
def _equity_setup_key(cfg: dict) -> dict:
    import getpass
    print("\n  ── Equity AI Config ─────────────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_EQUITY_AI_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            return cfg
    if not key:
        return cfg
    cfg["api_key"] = key
    _equity_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _safe_info(info: dict, key: str, default="—"):
    v = info.get(key, default)
    return v if v is not None else default
def _safe_float(v, default: float = 0.0) -> float:
    try:
        return float(v)
    except (TypeError, ValueError):
        return default
def _get_val(df: pd.DataFrame, keys: list, col: int = -1, default: float = 0.0) -> float:
    if df is None or df.empty:
        return default
    for key in keys:
        if key in df.index:
            try:
                val = df.loc[key].iloc[col]
                if pd.notna(val):
                    return float(val)
            except (IndexError, TypeError, ValueError):
                continue
    return default
def _flatten_cols(df: pd.DataFrame) -> pd.DataFrame:
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = df.columns.get_level_values(0)
    return df
def _fmtcr(v, default="—") -> str:
    try:
        x = float(v)
        if x == 0:              return "—"
        if abs(x) >= 1e12:      return f"₹{x/1e7:,.0f} Cr  (₹{x/1e12:.2f}T)"
        if abs(x) >= 1e7:       return f"₹{x/1e7:,.2f} Cr"
        if abs(x) >= 1e5:       return f"₹{x/1e5:,.2f} L"
        return f"₹{x:,.0f}"
    except (TypeError, ValueError):
        return default
def _fmtpct(v, mult: bool = True, dec: int = 2, default="—") -> str:
    try:
        x = float(v) * (100 if mult else 1)
        return f"{x:.{dec}f}%"
    except (TypeError, ValueError):
        return default
def _fmtx(v, dec: int = 2, default="—") -> str:
    try:
        return f"{float(v):.{dec}f}x"
    except (TypeError, ValueError):
        return default
def _fmtf(v, dec: int = 2, default="—") -> str:
    try:
        return f"{float(v):,.{dec}f}"
    except (TypeError, ValueError):
        return default
def _color_cls(v, good_thresh: float = 0, bad_thresh: float = None,
               higher_is_good: bool = True) -> str:
    try:
        x = float(v)
        if higher_is_good:
            if x > good_thresh:                                  return "pos"
            if bad_thresh is not None and x < bad_thresh:        return "neg"
        else:
            if x < good_thresh:                                  return "pos"
            if bad_thresh is not None and x > bad_thresh:        return "neg"
    except (TypeError, ValueError):
        pass
    return "neutral"
def _calc_piotroski(ni_c, ni_p, cfo_c, a_c, a_p, ca_c, ca_p, cl_c, cl_p,
                    ltd_c, ltd_p, rev_c, rev_p, gp_c, gp_p, sh_c, sh_p) -> dict:
    def safe_div(a, b, default=0.0):
        return a / b if b and b != 0 else default
    roa_c = safe_div(ni_c, a_c)
    roa_p = safe_div(ni_p, a_p)
    cr_c  = safe_div(ca_c, cl_c)
    cr_p  = safe_div(ca_p, cl_p)
    lev_c = safe_div(ltd_c, a_c)
    lev_p = safe_div(ltd_p, a_p)
    gm_c  = safe_div(gp_c, rev_c)
    gm_p  = safe_div(gp_p, rev_p)
    at_c  = safe_div(rev_c, a_c)
    at_p  = safe_div(rev_p, a_p)
    checks = [
        ("ROA Positive",              f"ROA = {roa_c*100:.2f}%",                          roa_c > 0),
        ("CFO Positive",              f"CFO = {_fmtcr(cfo_c)}",                            cfo_c > 0),
        ("ROA Improving",             f"Δ ROA = {(roa_c-roa_p)*100:+.2f}pp",              roa_c > roa_p),
        ("Earnings Quality (CFO>NI)", f"CFO/NI = {safe_div(cfo_c,ni_c):.2f}x" if ni_c else "NI=0", cfo_c > ni_c),
        ("Leverage Falling",          f"D/A: {lev_p*100:.1f}% → {lev_c*100:.1f}%",        lev_c < lev_p),
        ("Liquidity Improving",       f"CR: {cr_p:.2f} → {cr_c:.2f}",                      cr_c > cr_p),
        ("No Share Dilution",         f"Shares: {sh_p/1e7:.1f}Cr → {sh_c/1e7:.1f}Cr",     sh_c <= sh_p),
        ("Gross Margin Improving",    f"GM: {gm_p*100:.1f}% → {gm_c*100:.1f}%",            gm_c > gm_p),
        ("Asset Turnover Improving",  f"AT: {at_p:.2f} → {at_c:.2f}",                      at_c > at_p),
    ]
    score = sum(1 for _, _, v in checks if v)
    return {
        "score": score,
        "interpretation": ("🟢 Exceptional" if score >= 8 else "🟢 Strong" if score >= 7
                           else "🟡 Average"  if score >= 4 else "🔴 Weak"),
        "css_class": "pos" if score >= 7 else "neg" if score < 4 else "neutral",
        "checks": checks,
    }
def _calc_altman_z(ni_c, re_c, eb_c, wc, a_c, tl_c, rev_c, mc) -> dict:
    def sdiv(a, b): return a/b if b else 0
    X1 = sdiv(wc,   a_c)
    X2 = sdiv(re_c, a_c)
    X3 = sdiv(eb_c, a_c)
    X4 = sdiv(mc,   tl_c)
    X5 = sdiv(rev_c, a_c)
    z  = 1.2*X1 + 1.4*X2 + 3.3*X3 + 0.6*X4 + 1.0*X5
    return {
        "z_score": z,
        "X1": X1, "X2": X2, "X3": X3, "X4": X4, "X5": X5,
        "zone":      "🟢 SAFE ZONE"    if z >= 2.99 else "🟡 GREY ZONE" if z >= 1.81 else "🔴 DISTRESS ZONE",
        "css_class": "pos"             if z >= 2.99 else "neutral"       if z >= 1.81 else "neg",
    }
def _calc_monte_carlo_dcf(fcf_base: float, sh_c: float,
                           wacc: float = 0.12, terminal_g: float = 0.04,
                           g_means: list = None,
                           n_sims: int = 2000, n_years: int = 5) -> dict:
    np.random.seed(42)                                                   
    if fcf_base <= 0 or sh_c <= 0:
        return {"error": "Negative or zero FCF — DCF not meaningful"}
    all_values = []
    _g_means = g_means if g_means else [0.05, 0.10, 0.15]
    for g_mean in _g_means:                                       
        waccs    = np.clip(np.random.normal(wacc,  0.020, n_sims), 0.05, 0.30)
        growths  = np.clip(np.random.normal(g_mean, 0.030, n_sims), -0.10, 0.50)
        term_gs  = np.clip(np.random.normal(terminal_g,  0.010, n_sims),  max(0.01, terminal_g-0.03), min(0.12, terminal_g+0.03))
        years     = np.arange(1, n_years + 1)
        fcf_proj  = fcf_base * (1 + growths[:, None]) ** years                     
        disc_fact = (1 + waccs[:, None]) ** years                                   
        pv_fcf    = (fcf_proj / disc_fact).sum(axis=1)                            
        tv        = fcf_proj[:, -1] * (1 + term_gs) / (waccs - term_gs)
        tv        = np.where(waccs <= term_gs, 0, tv)                       
        pv_tv     = tv / (1 + waccs) ** n_years
        values_per_share = (pv_fcf + pv_tv) / sh_c
        all_values.append(values_per_share)
    combined = np.concatenate(all_values)
    combined = combined[combined > 0]                               
    if len(combined) == 0:
        return {"error": "All simulated paths produced negative values"}
    return {
        "p10":     float(np.percentile(combined, 10)),
        "p25":     float(np.percentile(combined, 25)),
        "p50":     float(np.percentile(combined, 50)),           
        "p75":     float(np.percentile(combined, 75)),
        "p90":     float(np.percentile(combined, 90)),
        "mean":    float(np.mean(combined)),
        "std":     float(np.std(combined)),
        "hist_counts": list(map(int, np.histogram(combined, bins=20)[0])),
        "hist_edges":  [round(float(x), 2) for x in np.histogram(combined, bins=20)[1]],
        "n_paths": len(combined),
        "dcf_params": {"wacc": wacc, "term_g": terminal_g, "g_means": _g_means}
    }
def _calc_reverse_dcf(price: float, fcf_base: float, sh_c: float,
                      wacc: float = 0.12, terminal_g: float = 0.04,
                      n_years: int = 5) -> dict:
    if price <= 0 or fcf_base <= 0 or sh_c <= 0:
        return {"error": "Cannot compute reverse DCF with zero/negative inputs"}
    def dcf_price(g):
        years    = np.arange(1, n_years + 1)
        fcf_proj = fcf_base * (1 + g) ** years
        pv_fcf   = sum(f / (1 + wacc) ** i for i, f in enumerate(fcf_proj, 1))
        if wacc <= terminal_g:
            return 0.0
        tv    = fcf_proj[-1] * (1 + terminal_g) / (wacc - terminal_g)
        pv_tv = tv / (1 + wacc) ** n_years
        return (pv_fcf + pv_tv) / sh_c
    lo, hi = -0.05, 0.50
    for _ in range(60):                                                 
        mid = (lo + hi) / 2.0
        if dcf_price(mid) < price:
            lo = mid
        else:
            hi = mid
    implied_g = (lo + hi) / 2.0
    if implied_g > 0.20:
        verdict, cls = "🔴 Expensive (market prices high growth)", "neg"
    elif implied_g > 0.10:
        verdict, cls = "🟡 Fairly valued", "neutral"
    elif implied_g >= 0:
        verdict, cls = "🟢 Inexpensive (low implied growth)", "pos"
    else:
        verdict, cls = "🔴 Market implies shrinkage", "neg"
    return {
        "implied_growth_pct": round(implied_g * 100, 2),
        "verdict":            verdict,
        "css_class":          cls,
        "wacc_used":          wacc,
        "terminal_g_used":    terminal_g,
    }
def _calc_beneish(dsri, gmi, aqi, sgi, depi, sgai, tata, lvgi) -> dict:
    M = (-4.84 + 0.920*dsri + 0.528*gmi + 0.404*aqi + 0.892*sgi
         + 0.115*depi - 0.172*sgai + 4.679*tata - 0.327*lvgi)
    risk = ("🔴 HIGH MANIPULATION RISK" if M > -1.78 else
            "🟡 GREY ZONE"             if M > -2.22 else
            "🟢 LOW RISK")
    cls  = "neg" if M > -1.78 else "neutral" if M > -2.22 else "pos"
    components = [
        ("DSRI — Days Sales Receivable Index", dsri,  dsri  > 1.46, "Inflated receivables"),
        ("GMI  — Gross Margin Index",          gmi,   gmi   > 1.19, "Declining margins"),
        ("AQI  — Asset Quality Index",         aqi,   aqi   > 1.25, "Non-current asset bloat"),
        ("SGI  — Sales Growth Index",          sgi,   sgi   > 1.60, "Aggressive growth"),
        ("DEPI — Depreciation Index",          depi,  depi  > 1.08, "Slowing depreciation"),
        ("SGAI — SG&A Index",                  sgai,  sgai  > 1.02, "Rising overhead"),
        ("LVGI — Leverage Index",              lvgi,  lvgi  > 1.11, "Rising leverage"),
        ("TATA — Total Accruals/Assets",       tata,  tata  > 0.031, "High accruals"),
    ]
    return {"M": M, "risk": risk, "css_class": cls, "components": components}
def _kv(label: str, value: str, cls: str = "neutral",
        tooltip: str = "") -> str:
    tip_html = (
        f" <span class='tooltip-icon' data-tip='{tooltip}'>ⓘ</span>"
        if tooltip else ""
    )
    return (
        f"<div class='kv-card {cls}'>"
        f"<div class='kv-label'>{label}{tip_html}</div>"
        f"<div class='kv-value'>{value}</div>"
        f"</div>"
    )
def _section(title: str, icon: str = "", collapsible: bool = True,
             section_id: str = "") -> str:
    sid = section_id or title.lower().replace(" ", "-").replace("&", "")
    caret = "<span class='caret'>▾</span>" if collapsible else ""
    onclick = f" onclick=\"toggleSection('{sid}')\"" if collapsible else ""
    return (
        f"<h2 class='section-title'{onclick} id='hdr-{sid}'>"
        f"{icon} {title} {caret}"
        f"</h2>"
        f"<div id='sec-{sid}' class='section-body'>"
    )
def _section_end() -> str:
    return "</div>"
def _build_piotroski_html(pf: dict) -> str:
    rows = "".join(
        f"<tr>"
        f"<td>{'✅' if v else '❌'} {n}</td>"
        f"<td class='neutral' style='font-size:0.76rem;color:var(--sub)'>{d}</td>"
        f"</tr>"
        for n, d, v in pf["checks"]
    )
    score = pf["score"]
    color = "var(--green)" if score >= 7 else "var(--red)" if score < 4 else "var(--orange)"
    badge_cls = "pos-badge" if score >= 7 else "neg-badge" if score < 4 else "neu-badge"
    return f"""
    <div class="score-card">
      <h3>Piotroski F-Score
        <span class="tooltip-icon" data-tip="9-point checklist of profitability, leverage, and efficiency signals. ≥7 = strong, ≤3 = weak.">ⓘ</span>
      </h3>
      <div class="score-value" style="color:{color}">{score}/9</div>
      <span class="score-badge {badge_cls}">{pf['interpretation']}</span>
      <div class="score-rows"><table>{rows}</table></div>
    </div>"""
def _build_altman_html(az: dict) -> str:
    z = az["z_score"]
    color = "var(--green)" if z >= 2.99 else "var(--red)" if z < 1.81 else "var(--orange)"
    badge_cls = "pos-badge" if z >= 2.99 else "neg-badge" if z < 1.81 else "neu-badge"
    return f"""
    <div class="score-card">
      <h3>Altman Z-Score
        <span class="tooltip-icon" data-tip="Bankruptcy predictor. Z&gt;2.99 safe; 1.81–2.99 grey; &lt;1.81 distress. Developed 1968 for US manufacturers — treat as indicative for Indian firms.">ⓘ</span>
      </h3>
      <div class="score-value" style="color:{color}">{z:.3f}</div>
      <span class="score-badge {badge_cls}">{az['zone']}</span>
      <table style="font-size:0.78rem;width:100%;margin-top:0.5rem">
        <tr><td>X1 Working Capital/Assets</td>  <td style="text-align:right">{az['X1']:.4f}</td></tr>
        <tr><td>X2 Retained Earnings/Assets</td><td style="text-align:right">{az['X2']:.4f}</td></tr>
        <tr><td>X3 EBIT/Assets</td>             <td style="text-align:right">{az['X3']:.4f}</td></tr>
        <tr><td>X4 Market Cap/Total Liab</td>   <td style="text-align:right">{az['X4']:.4f}</td></tr>
        <tr><td>X5 Revenue/Assets</td>          <td style="text-align:right">{az['X5']:.4f}</td></tr>
      </table>
    </div>"""
def _build_mc_dcf_html(mc_result: dict, current_price: float) -> str:
    if "error" in mc_result:
        return f"<div class='score-card'><h3>Monte Carlo DCF</h3><p style='color:var(--sub)'>{mc_result['error']}</p></div>"
    p50   = mc_result["p50"]
    p10   = mc_result["p10"]
    p90   = mc_result["p90"]
    paths = mc_result["n_paths"]
    upside_pct = (p50 / current_price - 1) * 100 if current_price > 0 else 0
    badge_cls  = "pos-badge" if upside_pct > 15 else "neg-badge" if upside_pct < -15 else "neu-badge"
    _ret = f"""
    <div class="score-card">
      <h3>Monte Carlo DCF
        <span class="tooltip-icon" data-tip="{paths:,} simulated FCF paths with randomised WACC, growth rate, and terminal growth. P50 is the median intrinsic value across all scenarios.">ⓘ</span>
      </h3>
      <div class="score-value" style="color:var(--accent)">₹{_fmtf(p50)}</div>
      <span class="score-badge {badge_cls}">Median upside: {upside_pct:+.1f}%</span>
      <table style="font-size:0.78rem;width:100%;margin-top:0.6rem">
        <tr><td>Pessimistic (P10)</td><td style="text-align:right;color:var(--red)">₹{_fmtf(p10)}</td></tr>
        <tr><td>Median (P50)</td>     <td style="text-align:right;color:var(--accent)">₹{_fmtf(p50)}</td></tr>
        <tr><td>Optimistic (P90)</td> <td style="text-align:right;color:var(--green)">₹{_fmtf(p90)}</td></tr>
        <tr><td>Current Price</td>    <td style="text-align:right">₹{_fmtf(current_price)}</td></tr>
        <tr><td>Paths simulated</td>  <td style="text-align:right">{paths:,}</td></tr>"""
    params = mc_result.get("dcf_params", {})
    if params:
        w = params['wacc']*100; tg = params['term_g']*100; gm = [g*100 for g in params['g_means']]
        _ret += f"\n        <tr><td colspan='2' style='text-align:center;padding:0.4rem;padding-top:0.6rem;color:var(--sub)'><b>AI ASSUMPTIONS:</b> WACC {w:.1f}% | TermG {tg:.1f}% | Bull Growth {gm[2]:.1f}%</td></tr>"
    _ret += f"\n      </table>\n    </div>"
    return _ret
def _build_reverse_dcf_html(rdcf: dict) -> str:
    if "error" in rdcf:
        return f"<div class='score-card'><h3>Reverse DCF</h3><p style='color:var(--sub)'>{rdcf['error']}</p></div>"
    g   = rdcf["implied_growth_pct"]
    cls = rdcf["css_class"]
    color = "var(--green)" if cls == "pos" else "var(--red)" if cls == "neg" else "var(--orange)"
    return f"""
    <div class="score-card">
      <h3>Reverse DCF
        <span class="tooltip-icon" data-tip="Solves for the FCF growth rate g that makes the discounted cash flow equal the current market price. Reveals what growth the market is implicitly betting on.">ⓘ</span>
      </h3>
      <div class="score-value" style="color:{color}">{g:+.1f}% p.a.</div>
      <p style="font-size:0.82rem;margin-top:0.4rem">{rdcf['verdict']}</p>
      <table style="font-size:0.78rem;width:100%;margin-top:0.6rem">
        <tr><td>WACC used</td>        <td style="text-align:right">{rdcf['wacc_used']*100:.1f}%</td></tr>
        <tr><td>Terminal g used</td>  <td style="text-align:right">{rdcf['terminal_g_used']*100:.1f}%</td></tr>
        <tr><td>Interpretation</td>   <td style="text-align:right;color:{color}">Implied: {g:.1f}% growth</td></tr>
      </table>
    </div>"""
def _build_beneish_html(bm: dict) -> str:
    M   = bm["M"]
    cls = bm["css_class"]
    color = "var(--red)" if M > -1.78 else "var(--orange)" if M > -2.22 else "var(--green)"
    comp_rows = "".join(
        f"<tr><td class='row-label'>{name}</td>"
        f"<td>{val:.4f}</td>"
        f"<td class=\"{'neg' if flagged else 'pos'}\">"
        f"{'⚠ ' + reason if flagged else '✅ Normal'}"
        f"</td></tr>"
        for name, val, flagged, reason in bm["components"]
    )
    return f"""
    <div class="score-card" style="grid-column:span 2">
      <h3>Beneish M-Score
        <span class="tooltip-icon" data-tip="Detects earnings manipulation. M &gt; -1.78 indicates possible manipulation. 8 financial ratios are combined into a single score.">ⓘ</span>
      </h3>
      <div style="display:flex;align-items:center;gap:2rem;flex-wrap:wrap">
        <div>
          <div class="score-value" style="color:{color}">{M:.4f}</div>
          <span class="score-badge {'neg-badge' if M > -1.78 else 'neu-badge' if M > -2.22 else 'pos-badge'}">{bm['risk']}</span>
          <p style="font-size:0.72rem;color:var(--sub);margin-top:0.4rem">
            &gt; -1.78 = Likely Manipulator | &lt; -2.22 = Unlikely
          </p>
        </div>
        <table style="flex:1;font-size:0.78rem;border-collapse:collapse">
          <thead><tr>
            <th style="text-align:left;padding:0.25rem 0.4rem">Component</th>
            <th style="text-align:right;padding:0.25rem 0.4rem">Value</th>
            <th style="text-align:right;padding:0.25rem 0.4rem">Signal</th>
          </tr></thead>
          <tbody>{comp_rows}</tbody>
        </table>
      </div>
    </div>"""
def _build_equity_ai_prompt(ticker: str, name: str, sector: str,
                             price: float, metrics: dict) -> str:
    data_json = json.dumps(metrics, indent=2, default=str)
    return textwrap.dedent(f"""\
        You are a Senior Equity Research Analyst and CFA Charterholder specialising
        in Indian and global equities.  You have just computed a comprehensive
        financial model for {name} ({ticker}), a company in the {sector} sector.
        Your task is to produce a structured investment memo.
        RULES:
        1. Base every claim on the <financial_data> below. Do not fabricate numbers.
        2. Be specific — cite actual figures (e.g. "ROE of 18.3% vs sector avg ~12%").
        3. Separate facts from interpretation. Label opinions clearly.
        4. Acknowledge data limitations (e.g., if FCF is negative, note it explicitly).
        5. Do not be promotional. If the stock looks expensive, say so.
        6. Limit each section to 3–5 crisp bullet points.
        7. For the ONE-LINE VERDICT, use exactly: BUY / ACCUMULATE / HOLD / REDUCE / SELL
           followed by a single sentence rationale.
        OUTPUT FORMAT — use these EXACT section headings (Markdown ##):
        ## Executive Summary
        ## Investment Thesis
        ## Bull Case  
        ## Bear Case
        ## Key Financial Observations
        ## Red Flags & Risks
        ## Valuation Verdict
        ## One-Line Verdict
        <financial_data ticker="{ticker}" name="{name}" sector="{sector}">
        {data_json}
        </financial_data>
    """)
def _call_equity_ai(metrics_for_ai: dict, ticker: str, name: str,
                    sector: str, price: float, cfg: dict) -> str:
    try:
        pass
    except ImportError:
        return ""
    system_prompt = _build_equity_ai_prompt(
        ticker, name, sector, price, metrics_for_ai
    )
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user",   "content":
            f"Please produce the full investment memo for {name} ({ticker}) "
            f"now, following the exact format specified."},
    ]
    headers = {
        "Authorization": f"Bearer {cfg['api_key']}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Equity Research Report AI Engine",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    cfg["model_id"],
        "messages": messages,
        "stream":   True,
        "max_tokens": 1800,                                               
    }
    BACKOFF = 1.5
    MAX_TRIES = 3
    full_response = ""
    for attempt in range(MAX_TRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers, json=payload, stream=True,
                timeout=(10, 90),                              
            )
            if resp.status_code == 401:
                print("  \033[91m[!] AI API key rejected (401). Use /setkey in any module.\033[0m")
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            token_count = 0
            print(f"\n  \033[90m{cfg['model_name']} is analysing {ticker} ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                line = raw_line.decode("utf-8", errors="replace") if isinstance(raw_line, bytes) else raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        token_count   += len(token.split())
                        if token_count % 30 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({token_count} words)\033[0m")
            return full_response
        except Exception as exc:
            if attempt < MAX_TRIES - 1:
                wait = BACKOFF ** (attempt + 1)
                print(f"  \033[93m[~] AI attempt {attempt+1} failed ({exc}). Retry in {wait:.1f}s…\033[0m")
                time.sleep(wait)
            else:
                print(f"  \033[91m[!] AI analysis failed after {MAX_TRIES} attempts: {exc}\033[0m")
    return ""
def _ai_response_to_html(markdown_text: str, model_name: str,
                          ticker: str) -> str:
    if not markdown_text.strip():
        return "<p style='color:var(--sub)'>AI analysis unavailable.</p>"
    lines = markdown_text.strip().split("\n")
    html_parts = []
    in_list = False
    for line in lines:
        line_s = line.strip()
        if line_s.startswith("## "):
            if in_list:
                html_parts.append("</ul>")
                in_list = False
            heading = line_s[3:].strip()
            style = " style='color:var(--accent);margin-top:1.5rem'" if "Verdict" in heading else ""
            html_parts.append(f"<h3 class='ai-section-heading'{style}>{heading}</h3>")
        elif line_s.startswith("- ") or line_s.startswith("• "):
            if not in_list:
                html_parts.append("<ul class='ai-list'>")
                in_list = True
            content = line_s[2:].strip()
            content = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", content)
            html_parts.append(f"<li>{content}</li>")
        elif line_s == "":
            if in_list:
                html_parts.append("</ul>")
                in_list = False
            else:
                html_parts.append("<div style='height:0.4rem'></div>")
        else:
            if in_list:
                html_parts.append("</ul>")
                in_list = False
            content = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", line_s)
            html_parts.append(f"<p class='ai-para'>{content}</p>")
    if in_list:
        html_parts.append("</ul>")
    inner = "\n".join(html_parts)
    return f"""
    <div class="ai-report-card">
      <div class="ai-report-header">
        <span class="ai-icon">🤖</span>
        <span class="ai-model-badge">{model_name}</span>
        <span class="ai-sub">AI-Generated Investment Memo for {ticker}</span>
        <span class="ai-disclaimer" title="AI analysis is for informational purposes only and does not constitute financial advice.">⚠ Not financial advice</span>
      </div>
      <div class="ai-report-body">
        {inner}
      </div>
    </div>"""
