import os, json, time, threading
from pathlib import Path
from typing  import Optional
def run_terminal_dashboard(ticker: str) -> None:
    warnings.filterwarnings('ignore')
    from rich.console  import Console
    from rich.panel    import Panel
    from rich.table    import Table
    from rich.rule     import Rule
    from rich.prompt   import Prompt
    from rich.markdown import Markdown
    from rich.layout   import Layout
    from rich          import box as _box
    console = Console()
    def _load_or():
        return _GLOBAL_OR_KEY, _GLOBAL_OR_MODEL
    OR_KEY, OR_MODEL = _load_or()
    def _ai_call(sys_p: str, user_p: str) -> tuple[str, float]:
        if not OR_KEY:
            return "[AI UNAVAILABLE] Configure API key in Module 71/37 Settings.", 0.0
        bag  = {}; done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization":f"Bearer {OR_KEY}",
                             "Content-Type":"application/json",
                             "X-Title":"Module53-Dashboard"},
                    json={"model":OR_MODEL,
                          "messages":[{"role":"system","content":sys_p},
                                      {"role":"user","content":user_p}],
                          "temperature":0.3},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter()-t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter()-t0
            finally: done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin="⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i=0; t0=time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i%len(spin)]} AI thinking… "
                  f"{time.perf_counter()-t0:.1f}s   ",
                  end="", flush=True)
            i+=1
        print()
        return bag.get("reply",""), bag.get("latency",0.0)
    CACHE_DIR = Path(".dash_cache"); CACHE_DIR.mkdir(exist_ok=True)
    CACHE_TTL = 10 * 60
    def _cache_path(key: str) -> Path:
        return CACHE_DIR / f"{hashlib.md5(key.encode()).hexdigest()[:10]}.pkl"
    def _cache_valid(key: str) -> bool:
        p = _cache_path(key)
        return p.exists() and (time.time() - p.stat().st_mtime) < CACHE_TTL
    def _load_cache(key: str):
        import pickle
        try:
            with open(_cache_path(key),'rb') as f: return pickle.load(f)
        except: return None
    def _save_cache(key: str, obj) -> None:
        import pickle
        try:
            with open(_cache_path(key),'wb') as f: pickle.dump(obj, f)
        except: pass
    def _fetch(sym: str, period: str = "6mo",
               interval: str = "1d") -> pd.DataFrame:
        key = f"{sym}:{period}:{interval}"
        if _cache_valid(key):
            df = _load_cache(key)
            if df is not None:
                console.print(
                    f"  [dim]Cache hit: {sym} ({period})[/]", end="\r"
                )
                return df
        console.print(
            f"  [dim]Downloading {sym} ({period}/{interval})…[/]", end="\r"
        )
        try:
            raw = yf.download(sym, period=period,
                              interval=interval, progress=False,
                              auto_adjust=True)
            df  = flatten_cols(raw)
            if not df.empty:
                _save_cache(key, df)
            return df
        except Exception as e:
            console.print(f"  [red]Download failed: {e}[/]")
            return pd.DataFrame()
    def _compute_all(df: pd.DataFrame) -> dict:
        c  = df['Close'].astype(float)
        h  = df['High'].astype(float)
        lo = df['Low'].astype(float)
        v  = df['Volume'].astype(float)
        n  = len(c)
        ind = {}
        ind['close']   = float(c.iloc[-1])
        ind['prev']    = float(c.iloc[-2]) if n > 1 else ind['close']
        ind['chg_pct'] = (ind['close']/ind['prev']-1)*100
        ind['chg_abs'] = ind['close'] - ind['prev']
        lret           = np.log(c / c.shift(1)).dropna()
        ind['log_ret_series'] = lret
        for p in [20, 50, 200]:
            s = c.rolling(p).mean()
            ind[f'sma{p}'] = float(s.iloc[-1]) if len(s.dropna())>0 else None
            ind[f'sma{p}_series'] = s
        for p in [12, 26, 9]:
            e = c.ewm(span=p, adjust=False).mean()
            ind[f'ema{p}'] = float(e.iloc[-1])
            ind[f'ema{p}_series'] = e
        macd_line   = ind['ema12_series'] - ind['ema26_series']
        macd_sig    = macd_line.ewm(span=9, adjust=False).mean()
        macd_hist   = macd_line - macd_sig
        ind['macd']      = float(macd_line.iloc[-1])
        ind['macd_sig']  = float(macd_sig.iloc[-1])
        ind['macd_hist'] = float(macd_hist.iloc[-1])
        ind['macd_series']      = macd_line
        ind['macd_sig_series']  = macd_sig
        ind['macd_hist_series'] = macd_hist
        delta = c.diff()
        gain  = delta.clip(lower=0)
        loss  = (-delta.clip(upper=0))
        ag    = gain.ewm(alpha=1/14, adjust=False).mean()
        al    = loss.ewm(alpha=1/14, adjust=False).mean()
        rs    = ag / (al + 1e-9)
        rsi   = 100 - 100/(1+rs)
        ind['rsi']        = float(rsi.iloc[-1])
        ind['rsi_series'] = rsi
        bb_mid = c.rolling(20).mean()
        bb_std = c.rolling(20).std()
        bb_up  = bb_mid + 2*bb_std
        bb_dn  = bb_mid - 2*bb_std
        ind['bb_upper']  = float(bb_up.iloc[-1]) if pd.notna(bb_up.iloc[-1]) else None
        ind['bb_lower']  = float(bb_dn.iloc[-1]) if pd.notna(bb_dn.iloc[-1]) else None
        ind['bb_mid']    = float(bb_mid.iloc[-1]) if pd.notna(bb_mid.iloc[-1]) else None
        ind['bb_pct']    = float(
            (c.iloc[-1]-float(bb_dn.iloc[-1])) /
            max(float(bb_up.iloc[-1])-float(bb_dn.iloc[-1]),1e-9)*100
        ) if ind['bb_upper'] else None
        ind['bb_width']  = float(
            (float(bb_up.iloc[-1])-float(bb_dn.iloc[-1]))/
            max(float(bb_mid.iloc[-1]),1e-9)*100
        ) if ind['bb_mid'] else None
        ind['bb_up_series'] = bb_up
        ind['bb_dn_series'] = bb_dn
        ind['bb_mid_series']= bb_mid
        tr  = pd.concat([
            h - lo,
            (h - c.shift(1)).abs(),
            (lo - c.shift(1)).abs()
        ], axis=1).max(axis=1)
        atr = tr.ewm(alpha=1/14, adjust=False).mean()
        ind['atr']        = float(atr.iloc[-1])
        ind['atr_series'] = atr
        hv = lret.rolling(21).std() * np.sqrt(252) * 100
        ind['hv21']        = float(hv.iloc[-1]) if pd.notna(hv.iloc[-1]) else 0.0
        ind['hv21_series'] = hv
        roc10 = c.pct_change(10)*100
        ind['roc10']        = float(roc10.iloc[-1]) if pd.notna(roc10.iloc[-1]) else 0.0
        ind['roc10_series'] = roc10
        hh14 = h.rolling(14).max()
        ll14 = lo.rolling(14).min()
        willr = -100*(hh14-c)/(hh14-ll14+1e-9)
        ind['willr']        = float(willr.iloc[-1]) if pd.notna(willr.iloc[-1]) else -50.0
        ind['willr_series'] = willr
        direction = np.sign(c.diff().fillna(0))
        obv       = (direction * v).cumsum()
        ind['obv']        = float(obv.iloc[-1])
        ind['obv_series'] = obv
        typical = (h + lo + c) / 3
        vwap    = (typical * v).rolling(14).sum() / v.rolling(14).sum()
        ind['vwap']        = float(vwap.iloc[-1]) if pd.notna(vwap.iloc[-1]) else None
        ind['vwap_series'] = vwap
        mfm  = ((c - lo) - (h - c)) / (h - lo + 1e-9)
        mfv  = mfm * v
        cmf  = mfv.rolling(20).sum() / v.rolling(20).sum()
        ind['cmf']        = float(cmf.iloc[-1]) if pd.notna(cmf.iloc[-1]) else 0.0
        ind['cmf_series'] = cmf
        vsma  = v.rolling(20).mean()
        ind['vol_ratio'] = float(v.iloc[-1]/vsma.iloc[-1]) if pd.notna(vsma.iloc[-1]) else 1.0
        try:
            mult      = 3.0
            mid       = (h + lo) / 2
            atr10     = tr.ewm(alpha=1/10, adjust=False).mean()
            up_band   = mid + mult * atr10
            dn_band   = mid - mult * atr10
            st        = pd.Series(index=c.index, dtype=float)
            direction_st = pd.Series(1, index=c.index, dtype=int)
            st.iloc[0]   = dn_band.iloc[0]
            for i in range(1, len(c)):
                if c.iloc[i] > up_band.iloc[i-1]:
                    direction_st.iloc[i] = 1
                elif c.iloc[i] < dn_band.iloc[i-1]:
                    direction_st.iloc[i] = -1
                else:
                    direction_st.iloc[i] = direction_st.iloc[i-1]
                st.iloc[i] = (dn_band.iloc[i] if direction_st.iloc[i]==1
                              else up_band.iloc[i])
            ind['supertrend']       = float(st.iloc[-1])
            ind['supertrend_dir']   = int(direction_st.iloc[-1])
            ind['supertrend_series']= st
        except Exception:
            ind['supertrend']     = None
            ind['supertrend_dir'] = 0
        ph = float(h.iloc[-2]) if n>1 else float(h.iloc[-1])
        pl = float(lo.iloc[-2]) if n>1 else float(lo.iloc[-1])
        pc = float(c.iloc[-2])  if n>1 else float(c.iloc[-1])
        pp = (ph+pl+pc)/3
        ind['pivot'] = pp
        ind['r1']    = 2*pp - pl
        ind['r2']    = pp + (ph - pl)
        ind['r3']    = ph + 2*(pp - pl)
        ind['s1']    = 2*pp - ph
        ind['s2']    = pp - (ph - pl)
        ind['s3']    = pl - 2*(ph - pp)
        ind['high_52w'] = float(c.tail(252).max())
        ind['low_52w']  = float(c.tail(252).min())
        ind['range_pct']= (ind['close'] - ind['low_52w']) /                          max(ind['high_52w'] - ind['low_52w'], 1e-9) * 100
        ind['close_series']  = c
        ind['high_series']   = h
        ind['low_series']    = lo
        ind['volume_series'] = v
        return ind
    def _sparkline(series: pd.Series, width: int = 12) -> str:
        blocks = "▁▂▃▄▅▆▇█"
        vals   = series.dropna().tail(width).values
        if len(vals) < 2: return "─" * width
        mn, mx = vals.min(), vals.max()
        rng    = mx - mn or 1e-9
        return "".join(blocks[int((v-mn)/rng*(len(blocks)-1))]
                       for v in vals)
    def _plot_price(df: pd.DataFrame, ind: dict,
                    days: int = 90) -> None:
        try:
            import plotext as plt
            import shutil
            cols, rows = shutil.get_terminal_size((120, 30))
            height     = max(14, rows - 16)
            c  = df['Close'].astype(float).tail(days)
            dates = [str(d)[:10] for d in c.index]
            plt.clf()
            plt.plotsize(cols, height)
            plt.theme('dark')
            plt.date_form('Y-m-d')
            plt.plot(dates, c.tolist(), color="cyan",
                     label=f"{ticker} Close")
            s20 = ind['sma20_series'].tail(days)
            s50 = ind['sma50_series'].tail(days)
            if not s20.dropna().empty:
                plt.plot(dates[-len(s20.dropna()):],
                         s20.dropna().tolist(),
                         color="orange", label="SMA-20")
            if not s50.dropna().empty:
                plt.plot(dates[-len(s50.dropna()):],
                         s50.dropna().tolist(),
                         color="magenta+", label="SMA-50")
            bb_up = ind['bb_up_series'].tail(days).dropna()
            bb_dn = ind['bb_dn_series'].tail(days).dropna()
            if not bb_up.empty:
                plt.plot(dates[-len(bb_up):], bb_up.tolist(),
                         color="dim", label="BB±2σ")
                plt.plot(dates[-len(bb_dn):], bb_dn.tolist(),
                         color="dim")
            if ind.get('supertrend_series') is not None:
                st = ind['supertrend_series'].tail(days).dropna()
                if not st.empty:
                    sc = "green" if ind['supertrend_dir']==1 else "red"
                    plt.plot(dates[-len(st):], st.tolist(),
                             color=sc, label="Supertrend")
            plt.title(
                f"  {ticker} — Price Chart ({days}d)  |  "
                f"SMA20 | SMA50 | Bollinger | Supertrend"
            )
            plt.show()
        except ImportError:
            _plot_price_ascii(df, ind, days)
        except Exception as e:
            console.print(f"  [dim]Chart error: {e}[/]")
    def _plot_price_ascii(df: pd.DataFrame, ind: dict,
                          days: int = 90) -> None:
        c    = df['Close'].astype(float).tail(days).values
        H, W = 16, min(days, 80)
        mn, mx = c.min(), c.max()
        rng  = mx - mn or 1e-9
        canvas = [[" "]*W for _ in range(H)]
        step = max(1, len(c)//W)
        vals = c[::step][:W]
        for x, val in enumerate(vals):
            y = int((val-mn)/rng*(H-1))
            y = max(0,min(H-1,y))
            canvas[H-1-y][x] = "█"
        console.print()
        for row_i, row in enumerate(canvas):
            rv = mx - row_i*(mx-mn)/(H-1)
            line = f"  {rv:>10,.2f} │ " + "".join(row)
            console.print(line)
        console.print("  " + " "*13 + "└" + "─"*W)
    def _plot_volume(df: pd.DataFrame,
                     days: int = 60) -> None:
        try:
            import plotext as plt
            import shutil
            cols, rows = shutil.get_terminal_size((120, 30))
            v    = df['Volume'].astype(float).tail(days)
            vsma = v.rolling(20).mean()
            dates= [str(d)[:10] for d in v.index]
            plt.clf()
            plt.plotsize(cols, max(10, rows-24))
            plt.theme('dark')
            plt.date_form('Y-m-d')
            plt.bar(dates, (v/1e6).tolist(), color="blue+",
                    label="Volume (M)")
            if not vsma.dropna().empty:
                plt.plot(dates[-len(vsma.dropna()):],
                         (vsma.dropna()/1e6).tolist(),
                         color="orange", label="Vol SMA-20")
            plt.title(f"  Volume Chart ({days}d)  |  Units: Millions")
            plt.show()
        except Exception:
            pass
    def _plot_momentum(ind: dict) -> None:
        try:
            import plotext as plt
            import shutil
            cols, rows = shutil.get_terminal_size((120, 30))
            rsi  = ind['rsi_series'].dropna().tail(60)
            macd = ind['macd_hist_series'].dropna().tail(60)
            dates_r = [str(d)[:10] for d in rsi.index]
            dates_m = [str(d)[:10] for d in macd.index]
            plt.clf()
            plt.plotsize(cols, max(10, rows-24))
            plt.theme('dark')
            plt.date_form('Y-m-d')
            plt.subplots(1, 2)
            plt.subplot(1, 1)
            plt.plot(dates_r, rsi.tolist(), color="cyan", label="RSI-14")
            plt.hline(70, color="red");  plt.hline(30, color="green")
            plt.hline(50, color="dim")
            plt.title("RSI-14  (OB=70 / OS=30)")
            plt.subplot(1, 2)
            pos = [max(0,v) for v in macd.tolist()]
            neg = [min(0,v) for v in macd.tolist()]
            plt.bar(dates_m, pos, color="green+", label="MACD Hist+")
            plt.bar(dates_m, neg, color="red+",   label="MACD Hist−")
            plt.hline(0, color="dim")
            plt.title("MACD Histogram")
            plt.show()
        except Exception:
            pass
    def _plot_compare(ticker: str,
                      benchmark: str = "^NSEI") -> None:
        try:
            import plotext as plt
            import shutil
            cols, rows = shutil.get_terminal_size((120, 30))
            df1 = _fetch(ticker,    "1y", "1d")
            df2 = _fetch(benchmark, "1y", "1d")
            if df1.empty or df2.empty: return
            c1 = df1['Close'].astype(float).dropna()
            c2 = df2['Close'].astype(float).dropna()
            common = c1.index.intersection(c2.index)
            c1, c2 = c1.loc[common], c2.loc[common]
            n1 = (c1 / c1.iloc[0] - 1) * 100
            n2 = (c2 / c2.iloc[0] - 1) * 100
            dates = [str(d)[:10] for d in n1.index]
            plt.clf()
            plt.plotsize(cols, max(12, rows-20))
            plt.theme('dark')
            plt.date_form('Y-m-d')
            plt.plot(dates, n1.tolist(), color="cyan",
                     label=f"{ticker}")
            plt.plot(dates, n2.tolist(), color="orange",
                     label=f"{benchmark}")
            plt.hline(0, color="dim")
            plt.title(
                f"  1-Year Normalised Returns: {ticker} vs {benchmark}  (%)"
            )
            plt.show()
        except Exception as e:
            console.print(f"  [dim]Comparison chart error: {e}[/]")
    def _render_overview(ind: dict, df: pd.DataFrame) -> None:
        pc = "green" if ind['chg_pct']>=0 else "red"
        arrow = "▲" if ind['chg_pct']>=0 else "▼"
        c  = ind['close']
        s20= ind['sma20'] or c
        s50= ind['sma50'] or c
        s200=ind['sma200'] or c
        if c > s20 > s50 > s200:
            trend_label = "STRONG BULL"; tc="bold green"
        elif c > s20 and c > s50:
            trend_label = "BULLISH";     tc="green"
        elif c < s20 < s50 < s200:
            trend_label = "STRONG BEAR"; tc="bold red"
        elif c < s20 and c < s50:
            trend_label = "BEARISH";     tc="red"
        else:
            trend_label = "SIDEWAYS";    tc="yellow"
        st_dir = ind.get('supertrend_dir', 0)
        st_lbl = "[green]▲ BULL[/]" if st_dir==1 else "[red]▼ BEAR[/]" if st_dir==-1 else "[dim]—[/]"
        price_panel = (
            f"[bold white]{ticker}[/]  "
            f"[bold {pc}]₹{c:,.2f}  {arrow}{ind['chg_pct']:+.2f}%  "
            f"({ind['chg_abs']:+,.2f})[/]\n\n"
            f"[bold]Trend (SMA):[/]    [{tc}]{trend_label}[/{tc}]\n"
            f"[bold]Supertrend:[/]     {st_lbl}\n"
            f"[bold]VWAP:[/]           "
            f"{'₹' + format(ind['vwap'], ',.2f') if ind['vwap'] else '—'}  "
            f"{'[green]↑ Above[/]' if ind['vwap'] and c>ind['vwap'] else '[red]↓ Below[/]'}\n"
            f"[bold]52W Range:[/]      "
            f"₹{ind['low_52w']:,.2f} – ₹{ind['high_52w']:,.2f}  "
            f"[dim]({ind['range_pct']:.1f}% of range)[/]\n"
            f"[bold]ATR-14:[/]         ₹{ind['atr']:,.2f}  "
            f"[dim]({ind['atr']/c*100:.2f}% of price)[/]\n"
            f"[bold]Hist.Vol 21d:[/]   {ind['hv21']:.1f}%"
        )
        console.print(Panel(
            price_panel,
            title=f"[bold white]Price & Trend[/]",
            border_style=pc, expand=False
        ))
        osc_tbl = Table(
            border_style="cyan", box=_box.SIMPLE_HEAVY,
            show_lines=True, expand=False
        )
        osc_tbl.add_column("Indicator", width=18, style="bold")
        osc_tbl.add_column("Value",     width=12, justify="right")
        osc_tbl.add_column("Signal",    width=16)
        osc_tbl.add_column("Spark",     width=14)
        def _rsi_sig(r):
            if r > 70: return "[bold red]OVERBOUGHT[/]"
            if r < 30: return "[bold green]OVERSOLD[/]"
            if r > 55: return "[green]Bullish[/]"
            if r < 45: return "[red]Bearish[/]"
            return "[yellow]Neutral[/]"
        def _macd_sig(h_val):
            if h_val > 0: return "[green]Bullish[/]"
            return "[red]Bearish[/]"
        def _cmf_sig(c_val):
            if c_val > 0.1: return "[green]Accumulate[/]"
            if c_val < -0.1: return "[red]Distribute[/]"
            return "[yellow]Neutral[/]"
        def _willr_sig(w):
            if w > -20: return "[red]Overbought[/]"
            if w < -80: return "[green]Oversold[/]"
            return "[yellow]Neutral[/]"
        rows_osc = [
            ("RSI-14",
             f"{ind['rsi']:.1f}",
             _rsi_sig(ind['rsi']),
             _sparkline(ind['rsi_series'])),
            ("MACD Hist",
             f"{ind['macd_hist']:+.3f}",
             _macd_sig(ind['macd_hist']),
             _sparkline(ind['macd_hist_series'])),
            ("Williams %R",
             f"{ind['willr']:.1f}",
             _willr_sig(ind['willr']),
             _sparkline(ind['willr_series'])),
            ("CMF-20",
             f"{ind['cmf']:+.3f}",
             _cmf_sig(ind['cmf']),
             _sparkline(ind['cmf_series'])),
            ("ROC-10",
             f"{ind['roc10']:+.2f}%",
             "[green]↑[/]" if ind['roc10']>0 else "[red]↓[/]",
             _sparkline(ind['roc10_series'])),
            ("Vol Ratio",
             f"{ind['vol_ratio']:.2f}×",
             "[green]High Vol[/]" if ind['vol_ratio']>1.5
             else "[red]Low Vol[/]" if ind['vol_ratio']<0.7
             else "[yellow]Normal[/]",
             _sparkline(ind['volume_series'])),
        ]
        for r in rows_osc:
            osc_tbl.add_row(*r)
        console.print(
            Panel(osc_tbl, title="[bold cyan]Oscillators & Momentum[/]",
                  border_style="cyan", expand=False)
        )
        ma_tbl = Table(
            border_style="magenta", box=_box.SIMPLE_HEAVY,
            show_lines=False, expand=False
        )
        ma_tbl.add_column("Level",   width=14, style="bold")
        ma_tbl.add_column("Price",   width=14, justify="right")
        ma_tbl.add_column("Dist%",   width=9,  justify="right")
        ma_tbl.add_column("Stance",  width=14)
        def _dist(level):
            if level is None: return "N/A", "—"
            d = (c-level)/level*100
            clr = "green" if d>0 else "red"
            return f"[{clr}]{d:+.2f}%[/{clr}]",                   f"[{clr}]{'Above' if d>0 else 'Below'}[/{clr}]"
        for lbl, val in [
            ("SMA-20",   ind['sma20']),
            ("SMA-50",   ind['sma50']),
            ("SMA-200",  ind['sma200']),
            ("EMA-12",   ind.get('ema12')),
            ("EMA-26",   ind.get('ema26')),
            ("BB Upper", ind['bb_upper']),
            ("BB Mid",   ind['bb_mid']),
            ("BB Lower", ind['bb_lower']),
            ("VWAP",     ind['vwap']),
        ]:
            dist_str, stance = _dist(val)
            price_str = f"₹{val:,.2f}" if val else "N/A"
            ma_tbl.add_row(lbl, price_str, dist_str, stance)
        console.print(
            Panel(ma_tbl,
                  title="[bold magenta]Moving Averages & Bands[/]",
                  border_style="magenta", expand=False)
        )
        lvl_tbl = Table(
            border_style="yellow", box=_box.SIMPLE_HEAVY,
            show_lines=False, expand=False
        )
        lvl_tbl.add_column("Level", width=10, style="bold")
        lvl_tbl.add_column("Price", width=14, justify="right")
        lvl_tbl.add_column("Dist%", width=10, justify="right")
        lvl_tbl.add_column("Type",  width=14)
        levels = [
            ("R3", ind['r3'], "Resistance"),
            ("R2", ind['r2'], "Resistance"),
            ("R1", ind['r1'], "Resistance"),
            ("PP", ind['pivot'], "Pivot"),
            ("S1", ind['s1'], "Support"),
            ("S2", ind['s2'], "Support"),
            ("S3", ind['s3'], "Support"),
        ]
        for lbl, val, typ in levels:
            d = (c-val)/val*100
            dc= "green" if typ=="Support" else ("yellow" if typ=="Pivot" else "red")
            lvl_tbl.add_row(
                f"[{dc}]{lbl}[/{dc}]",
                f"₹{val:,.2f}",
                f"{d:+.2f}%",
                f"[{dc}]{typ}[/{dc}]"
            )
        console.print(
            Panel(lvl_tbl,
                  title="[bold yellow]Classic Pivot Points (S/R Levels)[/]",
                  border_style="yellow", expand=False)
        )
        signals = []
        if ind['close'] > (ind['sma20'] or 0): signals.append(("SMA20 Cross", "BULL"))
        else: signals.append(("SMA20 Cross", "BEAR"))
        if ind['close'] > (ind['sma50'] or 0): signals.append(("SMA50 Cross", "BULL"))
        else: signals.append(("SMA50 Cross", "BEAR"))
        if ind['macd_hist'] > 0: signals.append(("MACD Hist", "BULL"))
        else: signals.append(("MACD Hist", "BEAR"))
        if 30 < ind['rsi'] < 70: signals.append(("RSI Zone", "NEUT"))
        elif ind['rsi'] < 30:    signals.append(("RSI Zone", "BULL"))
        else:                    signals.append(("RSI Zone", "BEAR"))
        if ind['vwap'] and ind['close'] > ind['vwap']:
            signals.append(("VWAP Position", "BULL"))
        else:
            signals.append(("VWAP Position", "BEAR"))
        if ind['cmf'] > 0.05:    signals.append(("CMF Flow", "BULL"))
        elif ind['cmf'] < -0.05: signals.append(("CMF Flow", "BEAR"))
        else:                    signals.append(("CMF Flow", "NEUT"))
        if ind.get('supertrend_dir')==1:  signals.append(("Supertrend", "BULL"))
        elif ind.get('supertrend_dir')==-1: signals.append(("Supertrend", "BEAR"))
        else:                             signals.append(("Supertrend", "NEUT"))
        if ind['vol_ratio'] > 1.3: signals.append(("Volume", "BULL"))
        else:                      signals.append(("Volume", "NEUT"))
        bulls = sum(1 for _,s in signals if s=="BULL")
        bears = sum(1 for _,s in signals if s=="BEAR")
        neuts = sum(1 for _,s in signals if s=="NEUT")
        total = len(signals)
        bull_score = bulls/total*100
        if bull_score >= 70:   overall = "[bold green]STRONG BUY[/]"
        elif bull_score >= 55: overall = "[green]BUY[/]"
        elif bull_score <= 30: overall = "[bold red]STRONG SELL[/]"
        elif bull_score <= 45: overall = "[red]SELL[/]"
        else:                  overall = "[yellow]NEUTRAL[/]"
        sig_str = "  ".join(
            f"[{'green' if s=='BULL' else 'red' if s=='BEAR' else 'dim'}]"
            f"{nm}:{s}[/]"
            for nm,s in signals
        )
        console.print(Panel(
            f"[bold]Signal Scorecard:[/]  {sig_str}\n\n"
            f"[bold]Bulls:[/] {bulls}/{total}  "
            f"[bold]Bears:[/] {bears}/{total}  "
            f"[bold]Neutral:[/] {neuts}/{total}  "
            f"[bold]Overall:[/] {overall}  "
            f"[dim](score={bull_score:.0f}/100)[/]",
            title="[bold white]Composite Technical Signal[/]",
            border_style="white", expand=False
        ))
    def _build_ai_digest(ind: dict, df: pd.DataFrame) -> str:
        c = ind['close']
        lines = [
            f"=== TECHNICAL DASHBOARD — {ticker} ===",
            f"Current Price: ₹{c:,.2f}  "
            f"Change: {ind['chg_pct']:+.2f}% ({ind['chg_abs']:+,.2f})",
            "",
            "TREND INDICATORS:",
            f"  SMA-20: ₹{ind['sma20']:,.2f}  "
            f"({'Above' if c>ind['sma20'] else 'Below'})" if ind['sma20'] else "  SMA-20: N/A",
            f"  SMA-50: ₹{ind['sma50']:,.2f}  "
            f"({'Above' if c>ind['sma50'] else 'Below'})" if ind['sma50'] else "  SMA-50: N/A",
            f"  SMA-200: ₹{ind['sma200']:,.2f}  "
            f"({'Above' if c>ind['sma200'] else 'Below'})" if ind['sma200'] else "  SMA-200: N/A",
            f"  Supertrend: {'BULLISH' if ind.get('supertrend_dir')==1 else 'BEARISH'} "
            f"@ ₹{ind['supertrend']:,.2f}" if ind.get('supertrend') else "  Supertrend: N/A",
            f"  VWAP: ₹{ind['vwap']:,.2f}  "
            f"({'Above' if c>ind['vwap'] else 'Below'})" if ind['vwap'] else "  VWAP: N/A",
            "",
            "MOMENTUM OSCILLATORS:",
            f"  RSI-14: {ind['rsi']:.1f}  "
            f"({'Overbought' if ind['rsi']>70 else 'Oversold' if ind['rsi']<30 else 'Neutral'})",
            f"  MACD: {ind['macd']:.4f}  Signal: {ind['macd_sig']:.4f}  "
            f"Histogram: {ind['macd_hist']:+.4f}",
            f"  Williams %R: {ind['willr']:.1f}",
            f"  ROC-10: {ind['roc10']:+.2f}%",
            "",
            "VOLATILITY:",
            f"  Bollinger Bands: Upper={ind['bb_upper']:,.2f}  "
            f"Mid={ind['bb_mid']:,.2f}  Lower={ind['bb_lower']:,.2f}  "
            f"Position={ind['bb_pct']:.1f}%" if ind['bb_upper'] else "  BB: N/A",
            f"  BB Width: {ind['bb_width']:.2f}%" if ind['bb_width'] else "",
            f"  ATR-14: ₹{ind['atr']:,.2f}  ({ind['atr']/c*100:.2f}% of price)",
            f"  Historical Vol (21d): {ind['hv21']:.1f}%",
            "",
            "VOLUME & FLOW:",
            f"  Volume Ratio vs 20d avg: {ind['vol_ratio']:.2f}×",
            f"  CMF-20: {ind['cmf']:+.4f}  "
            f"({'Accumulation' if ind['cmf']>0 else 'Distribution'})",
            f"  OBV trend: {'Rising' if ind['obv_series'].diff().tail(5).mean()>0 else 'Falling'}",
            "",
            "KEY LEVELS (Classic Pivots):",
            f"  R3={ind['r3']:,.2f}  R2={ind['r2']:,.2f}  R1={ind['r1']:,.2f}",
            f"  PP={ind['pivot']:,.2f}",
            f"  S1={ind['s1']:,.2f}  S2={ind['s2']:,.2f}  S3={ind['s3']:,.2f}",
            "",
            f"52-WEEK RANGE: ₹{ind['low_52w']:,.2f} – ₹{ind['high_52w']:,.2f}  "
            f"({ind['range_pct']:.1f}% of range)",
        ]
        return "\n".join(l for l in lines if l is not None)
    _SYS_ANALYST = (
        "You are a senior technical analyst at a leading Indian broking firm.\n"
        "You have been given a full technical dashboard for an Indian listed stock.\n\n"
        "Write a structured technical analysis report:\n\n"
        "## 1. Trend Analysis\n"
        "Analyse the SMA structure (20/50/200), Supertrend direction, and price "
        "position vs VWAP. Is the stock in a confirmed trend or consolidating?\n\n"
        "## 2. Momentum Read\n"
        "Interpret RSI, MACD histogram, Williams %R, and ROC-10 together. "
        "Is momentum building, diverging, or exhausted? Quote specific values.\n\n"
        "## 3. Volatility Assessment\n"
        "Interpret the Bollinger Band width and position. Is the stock "
        "squeezing (low volatility pre-breakout) or expanding? "
        "What does ATR tell us about daily risk?\n\n"
        "## 4. Volume & Flow Analysis\n"
        "Interpret CMF-20 and volume ratio. Is money flowing in or out? "
        "Is the recent price move confirmed by volume?\n\n"
        "## 5. Key Levels\n"
        "Identify the most important support and resistance levels from the pivots. "
        "Where are the nearest make-or-break levels?\n\n"
        "## 6. Trade Setup\n"
        "Bias: LONG / SHORT / AVOID\n"
        "Entry zone, stop-loss level, and target (R1, R2, or S1 etc).\n"
        "R:R ratio. Timeframe: intraday / swing / positional.\n\n"
        "## 7. Risk Flags\n"
        "What could invalidate this analysis? "
        "Overbought/oversold extremes, divergences, volume gaps?\n\n"
        "Be direct. Use specific prices. Reference Indian market context "
        "(NSE, F&O, circuit limits, delivery % if applicable)."
    )
    def _run_ai_analyst(ind: dict, df: pd.DataFrame) -> str:
        from rich.panel import Panel
        from rich.markdown import Markdown
        from rich.rule import Rule
        console.print(Rule("[bold green]AI Technical Analyst[/]"))
        digest = _build_ai_digest(ind, df)
        reply, lat = _ai_call(_SYS_ANALYST, digest)
        if reply and not reply.startswith("[AI"):
            console.print(Panel(
                Markdown(reply), border_style="green",
                title=f"[bold green]AI Technical Analysis — {ticker}[/] "
                      f"[dim]({lat:.2f}s)[/]",
                expand=False
            ))
        else:
            console.print(f"  [dim]{reply}[/]")
        return reply
