    def _run_ai_chat(ind: dict, df: pd.DataFrame,
                     seed_reply: str = "") -> None:
        from rich.panel import Panel
        from rich.markdown import Markdown
        _SYS_CHAT = (
            "You are a technical analyst and Indian market expert.\n"
            "The user is viewing a live technical dashboard for a stock.\n"
            "Answer questions about indicators, patterns, levels, and trade setups.\n"
            "Cite specific values from the dashboard data provided."
        )
        digest  = _build_ai_digest(ind, df)
        history = [
            {"role":"system",    "content":_SYS_CHAT},
            {"role":"user",      "content":digest},
            {"role":"assistant", "content": seed_reply or
             f"I've reviewed the full dashboard for {ticker}. "
             "Ask me about the trend, oscillators, levels, or a trade setup."},
        ]
        turn=0; _WARN=7_000
        console.print(Panel(
            f"[bold cyan]💬 Dashboard Chat — {ticker}[/]\n\n"
            "Ask about any indicator, support/resistance level,\n"
            "pattern, or trade setup.\n\n"
            "[bold]Commands:[/]  [cyan]clear[/]   [cyan]exit[/]",
            border_style="cyan", expand=False
        ))
        while True:
            est = sum(len(m["content"]) for m in history)//4
            tok = f"[yellow]~{est} ⚠[/]" if est>=_WARN else f"[dim]~{est}t[/]"
            q   = Prompt.ask(
                f"\n  [bold cyan]You[/] [dim](turn {turn+1} | {tok})[/]"
            ).strip()
            if not q: continue
            if q.lower()=="exit":  console.print("  [dim]Returning…[/]"); break
            if q.lower()=="clear":
                history=[{"role":"system","content":_SYS_CHAT}]; turn=0
                console.print("  [green]✓ Cleared.[/]"); continue
            history.append({"role":"user","content":q})
            conv = "\n".join(f"{m['role'].upper()}: {m['content']}"
                             for m in history[1:])
            reply, lat = _ai_call(_SYS_CHAT, conv)
