def _check_and_install():
    missing = []
    for pkg in ["yfinance","pandas","pandas_ta","numpy","rich","requests"]:
        try: __import__(pkg)
        except ImportError: missing.append(pkg)
    if missing:
        print(f"\033[93m[!] Missing: {', '.join(missing)}\033[0m")
        print("    pip install yfinance pandas pandas-ta numpy lxml html5lib rich requests\n")
        return False
    return True
