def _build_universe():
    seen, result = set(), []
    for sec, stocks in MASTER_UNIVERSE.items():
        for s in stocks:
            k = s.upper().strip()
            if k not in seen:
                seen.add(k)
                result.append((f"{k}.NS", sec))
    return result
FULL_UNIVERSE = _build_universe()
SECTOR_LOOKUP = {sym: sec for sym, sec in FULL_UNIVERSE}
class PrecisionSwingOracle:
    def __init__(self, ticker: str = "RELIANCE.NS"):
        raw = ticker.upper().strip()
        self.ticker = raw if raw.endswith(".NS") else raw + ".NS"
        self.nifty  = "^NSEI"
        self._lock  = threading.Lock()
        self._cache = {}
    def _fetch(self, symbol, period, interval):
        import yfinance as yf, pandas as pd
        key = f"{symbol}|{period}|{interval}"
        with self._lock:
            if key in self._cache: return self._cache[key]
        try:
            df = yf.download(symbol, period=period, interval=interval,
                             progress=False, auto_adjust=True)
            if df is None or df.empty: return None
            if isinstance(df.columns, pd.MultiIndex):
                df.columns = df.columns.droplevel(1)
            df = df.dropna()
            if len(df) < {"1d":120,"1wk":70}.get(interval,40): return None
            with self._lock: self._cache[key] = df
            return df
        except Exception: return None
    def _daily(self,  s): return self._fetch(s, "2y", "1d")
    def _weekly(self, s): return self._fetch(s, "5y", "1wk")
    def _fetch_web_universe(self):
        UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
              "AppleWebKit/537.36 (KHTML, like Gecko) "
              "Chrome/122.0.0.0 Safari/537.36")
        extras, seen = [], {s for s,_ in FULL_UNIVERSE}
        for url in [
            "https://en.wikipedia.org/wiki/NIFTY_50",
            "https://en.wikipedia.org/wiki/NIFTY_Next_50",
            "https://en.wikipedia.org/wiki/NIFTY_Midcap_150",
        ]:
            try:
                tables = pd.read_html(url, storage_options={"User-Agent": UA})
                df = next((t for t in tables if "Symbol" in t.columns), None)
                if df is not None:
                    for s in df["Symbol"].tolist():
                        sym = f"{str(s).strip()}.NS"
                        if sym not in seen:
                            seen.add(sym); extras.append((sym, "NiftyWeb"))
            except Exception: pass
        return extras
    def get_market_regime(self):
        import pandas_ta as ta
        df = self._daily(self.nifty)
        if df is None:
            return {"regime":"UNKNOWN","detail":"NIFTY data unavailable","close":0,"pct_from_52w_high":0,"rsi":50}
        df.ta.sma(length=50,  append=True)
        df.ta.sma(length=200, append=True)
        df.ta.rsi(length=14,  append=True)
        df.dropna(inplace=True)
        if len(df) < 5:
            return {"regime":"UNKNOWN","detail":"Insufficient NIFTY bars","close":0,"pct_from_52w_high":0,"rsi":50}
        l = df.iloc[-1]
        close  = float(l["Close"])
        sma50  = float(l["SMA_50"])
        sma200 = float(l["SMA_200"])
        rsi    = float(l["RSI_14"])
        high52 = float(df["High"].rolling(min(252,len(df))).max().iloc[-1])
        pct_h  = (high52-close)/high52*100
        slope200 = float(df["SMA_200"].iloc[-1]) - float(df["SMA_200"].iloc[-20])
        if   close>sma50>sma200 and rsi>50 and slope200>0:
            regime="BULL";    detail=f"Stage-2 Uptrend. RSI={rsi:.0f}. {pct_h:.1f}% below 52W high."
        elif close<sma50 and close<sma200 and rsi<50:
            regime="BEAR";    detail=f"Stage-4 Downtrend. RSI={rsi:.0f}. Focus on RS Leaders."
        elif close>sma200:
            regime="NEUTRAL"; detail=f"Above 200 SMA, mixed momentum. RSI={rsi:.0f}."
        else:
            regime="CAUTION"; detail=f"Below 200 SMA. Distribution phase. RSI={rsi:.0f}."
        return {"regime":regime,"close":close,"detail":detail,"rsi":rsi,"pct_from_52w_high":pct_h}
    def analyze(self, symbol, market_regime="BULL", nifty_ret_20d=0.0): pass
    def _candle(self, sl): pass
    def _avoid(self,sym,sc,rsns):
        return {"symbol":sym,"status":"AVOID","setup":"NONE",
                "sector":SECTOR_LOOKUP.get(sym,"Other"),
                "score":sc,"close":0,"entry":0,"sl":0,"t1":0,"t2":0,"t3":0,
                "atr":0,"riskpct":0,"rs":0,"adx":0,"rsi":0,"volr":0,
                "wk_bull":False,"candle":"—","pct52h":100,"reasons":rsns}
    def scan_market(self): pass
    def deep_dive_ticker(self): pass
    def interactive_menu(self): pass
