        g.add_row("[bold bright_green]🎯 T2 (1:3 RR, book 30%):[/]", f"[bold bright_green]₹{res['t2']:,.2f}[/]")
        g.add_row("[bold magenta]🚀 T3 (1:5 RR, trail 20%):[/]", f"[bold magenta]₹{res['t3']:,.2f}[/]")
        g.add_row("", "")
        g.add_row("[bold]ATR:[/]", f"₹{res['atr']:,.2f}")
        g.add_row("[bold]Trailing Stop Protocol:[/]", "[dim]BEP at T1 → Trail 1.5×ATR after T1 → Free-ride above T2[/]")
        console.print(Panel(g, title="Execution Levels", border_style="cyan"))
        console.print(Rule("[bold cyan]🗓 ATR TRAILING STOP SCHEDULE[/]"))
        atr = res['atr']; entry = res['entry']
        trail_tbl = Table(box=box.SIMPLE_HEAVY, border_style="dim")
