        trail_tbl.add_column("If Price ≥",width=12,justify="right")
        trail_tbl.add_column("Move SL to",width=12,justify="right",style="red")
        trail_tbl.add_column("Action",  width=24)
        trail_tbl.add_row("Entry", f"₹{entry:,.2f}", f"₹{res['sl']:,.2f}", "Initial stop — do not move")
        trail_tbl.add_row("Day 3",  f"₹{res['t1']:,.2f}", f"₹{entry:,.2f}", "[yellow]Move to breakeven[/]")
        trail_tbl.add_row("Day 5",  f"₹{res['t1']+atr:,.2f}", f"₹{res['t1']:,.2f}", "[green]Lock in T1 level[/]")
        trail_tbl.add_row("Day 10", f"₹{res['t2']:,.2f}", f"₹{res['t1']+atr:,.2f}", "[bright_green]Trail +1 ATR per day[/]")
        trail_tbl.add_row("Day 15", f"₹{res['t3']:,.2f}", f"₹{res['t2']:,.2f}", "[magenta]Free ride to T3[/]")
        console.print(trail_tbl)
        kelly_f = res.get('kelly_f', 0.1); wr = res.get('win_rate', 0.5)
