        console.print(f"  [bold]Kelly Fraction:[/] {kelly_f*100:.1f}%  [dim](win rate={wr:.0%}, avg RR=2.5)[/]\n")
        for capital in [100_000, 500_000, 1_000_000]:
            risk_amt  = capital * 0.02
            kelly_amt = capital * kelly_f
            shares_risk  = int(risk_amt  / max(risk, 1))
            shares_kelly = int(kelly_amt / max(risk, 1))
            console.print(f"  ₹{capital//1000}K capital  |  2%-risk: [bold]{shares_risk}sh[/] (₹{shares_risk*entry:,.0f})  |  Kelly: [bold]{shares_kelly}sh[/] (₹{shares_kelly*entry:,.0f})")
        console.print(f"\n  [dim]📌 BUY STOP: ₹{entry:,.2f}  📌 Book 50% at T1, trail the rest[/]\n")
