    def _ai_call(self, sys_p: str, user_p: str) -> tuple[str, float]:
        if not self._or_key: return "[AI UNAVAILABLE] Configure API key in Settings.", 0.0
        bag  = {}; done = threading.Event()
        def _w():
            t0 = time.perf_counter()
            try:
                resp = requests.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={
                        "Authorization": f"Bearer {self._or_key}",
                        "Content-Type": "application/json",
                        "HTTP-Referer": "https://github.com/Module74",                                           
                        "X-Title": "Module74-SwingOracle"
                    },
                    json={
                        "model": self._or_model, 
                        "messages": [{"role": "system", "content": sys_p}, {"role": "user", "content": user_p}], 
                        "temperature": 0.35
                    },
                    timeout=90,
                )
                if resp.status_code != 200:
                    err_msg = resp.text
                    try:
                        err_msg = resp.json().get('error', {}).get('message', resp.text)
                    except: pass
                    bag["reply"] = f"[AI ERROR] HTTP {resp.status_code}: {err_msg}"
                else:
                    bag["reply"] = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter() - t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] Request Failed: {str(e)}"
                bag["latency"] = time.perf_counter() - t0
            finally: 
                done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i = 0; t0 = time.perf_counter()
        while not done.wait(0.1):
            print(f"\r  {spin[i%len(spin)]} AI scanning oracle data... {time.perf_counter()-t0:.1f}s   ", end="", flush=True)
            i += 1
        print("\r" + " "*60 + "\r", end="", flush=True)
        return bag.get("reply", ""), bag.get("latency", 0.0)
    def _build_scan_digest(self, results: list, regime_data: dict, sector_data: dict) -> str:
        rd = regime_data
        lines = [
            f"=== NSE SWING TRADING SCAN — {time.strftime('%Y-%m-%d')} ===", f"",
            f"MARKET REGIME: {rd.get('regime','?')}",
            f"NIFTY: ₹{rd.get('close',0):,.2f}  RSI={rd.get('rsi',50):.0f}  {rd.get('pct_from_52w_high',0):.1f}% below 52W high",
            f"Regime detail: {rd.get('detail','')}", f"",
            f"SECTOR ROTATION — TOP 5:",
        ]
        if sector_data:
            sorted_s = sorted(sector_data.items(), key=lambda x: x[1]['score'], reverse=True)
            for sec, d in sorted_s[:5]:
                lines.append(f"  {sec:<18}: score={d['score']:.0f}  RS={d['rs']:+.1f}%  RSI={d['rsi']:.0f}  Breadth={d['breadth']:.0f}%")
        lines += ["", f"TOP 10 QUALIFYING SETUPS:"]
        for i, r in enumerate(results[:10], 1):
            lines.append(
                f"\n{i}. {r['symbol'].replace('.NS','')}  [{r['setup']}]  Score={r['score']}/300  {r['status']}\n"
                f"   Sector={r['sector']}  Weinstein=Stage{r.get('weinstein',0)}  Inst={r.get('inst_score',0)}/4  Win%={r.get('win_rate',0.5)*100:.0f}%\n"
                f"   LTP=₹{r['close']:,.2f}  Entry=₹{r['entry']:,.2f}  SL=₹{r['sl']:,.2f}  T1=₹{r['t1']:,.2f}  T2=₹{r['t2']:,.2f}\n"
                f"   RSI={r['rsi']:.0f}  ADX={r['adx']:.0f}  RS={r['rs']*100:+.1f}%  Vol={r['volr']:.1f}×  52WH={r['pct52h']:.1f}% away\n"
                f"   Key reasons: " + " | ".join(rr[:50] for rr in r['reasons'][:3])
            )
        return "\n".join(lines)
