    def run_ai_chat(self, seed_reply: str = "") -> None:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.prompt   import Prompt
        from rich.markdown import Markdown
        console = Console()
        _SYS    = "You are a quantitative swing trading analyst specialising in NSE. Answer questions about scan results, setups, sector rotation, options strategies, position sizing, and market regime. Be specific. Give exact price levels."
        if self._scan_results:
            rd  = self.get_market_regime()
            ctx = self._build_scan_digest(self._scan_results[:10], rd, self._sector_scores or {})
        else:
            ctx = f"No scan results yet. Ticker: {self.ticker}"
        history = [
            {"role":"system",    "content":_SYS},
            {"role":"user",      "content":ctx},
            {"role":"assistant", "content": seed_reply or "I have the full oracle scan context. Ask me about any setup, sector, or market regime question."},
        ]
        turn=0; _WARN=8_000
        console.print(Panel(f"[bold cyan]💬 Oracle AI Chat[/]\n\nAsk about setups, sectors, regime, options, position sizing.\n\n[bold]Commands:[/]  [cyan]clear[/]   [cyan]exit[/]", border_style="cyan", expand=False))
        while True:
            est = sum(len(m["content"]) for m in history)//4
            tok = f"[yellow]~{est} ⚠[/]" if est>=_WARN else f"[dim]~{est}t[/]"
            q   = Prompt.ask(f"\n  [bold cyan]You[/] [dim](turn {turn+1}|{tok})[/]").strip()
            if not q: continue
            if q.lower()=="exit":  console.print("  [dim]Returning...[/]"); break
            if q.lower()=="clear":
                history=[{"role":"system","content":_SYS}]; turn=0
                console.print("  [green]✓[/]"); continue
            history.append({"role":"user","content":q})
            conv = "\n".join(f"{m['role'].upper()}: {m['content']}" for m in history[1:])
            reply, lat = self._ai_call(_SYS, conv)
            if reply and not reply.startswith("[AI ERROR]"):
                console.print(Panel(Markdown(reply), border_style="green", title=f"[bold green]Oracle AI[/] [dim]({lat:.2f}s)[/]", expand=False))
                history.append({"role":"assistant","content":reply})
                turn+=1
            else:
                console.print(f"\n  [bold red]{reply}[/]")
                history.pop()
