        if user_q.lower() in {"0","exit","quit"}: break
        parts = user_q.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts)>1 else ""
        if cmd == "/help": _m3_print_help(); continue
        elif cmd == "/setkey":
            cfg = _m3_setup_key(cfg)
            history[0]["content"] = _m3_build_system_prompt(ctx, model_name); continue
