def _m06_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title(),
    }
    if not os.path.exists(_M06_CONFIG_FILE):
        return defaults
    try:
        with open(_M06_CONFIG_FILE, "r", encoding="utf-8") as fh:
            return {**defaults, **json.load(fh)}
    except (json.JSONDecodeError, OSError):
        return defaults
def _m06_save_config(cfg: dict) -> bool:
    payload = {
        "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
        "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
        "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
    }
    try:
        with open(_M06_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  \033[93m[!] Could not save config: {exc}\033[0m")
        return False
def _m06_setup_key(cfg: dict) -> dict:
    import getpass, sys
    print("\n  ── API Key Setup (Module 6) ─────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M06_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m06_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _m06_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models (stochastic-maths optimised) ─")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 60)
    for i, m in enumerate(_M06_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M06_FREE_MODELS):
            sel               = _M06_FREE_MODELS[idx]
            cfg["model_id"]   = sel["id"]
            cfg["model_name"] = sel["name"]
            _m06_save_config(cfg)
            print(f"  [✓] Switched to {sel['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
@dataclass
class JumpDiffusionParams:
    mu:           float = 0.0
    sigma:        float = 0.15
    lambda_jump:  float = 0.02
    mu_jump:      float = -0.03
    sigma_jump:   float = 0.06
    k_bar:        float = 0.0
    threshold_k:  float = 2.5
    n_jump_days:  int   = 0
    total_days:   int   = 0
    ticker:       str   = ""
    last_price:   float = 0.0
    date_start:   str   = ""
    date_end:     str   = ""
@dataclass
class SimulationResult:
    paths:       object = None                             
    final:       object = None                        
    sim_returns: object = None                        
    params:      Optional[JumpDiffusionParams] = None
    n_sim:       int    = 0
    days:        int    = 0
    elapsed_s:   float  = 0.0
    model_label: str    = "Merton JD"
@dataclass
class RiskMetrics:
    expected_price:  float = 0.0
    median_price:    float = 0.0
    bull_price_95:   float = 0.0
    bear_price_05:   float = 0.0
    prob_gain:       float = 0.0
    var_95:          float = 0.0
    cvar_95:         float = 0.0
    var_99:          float = 0.0
    cvar_99:         float = 0.0
    sortino:         float = 0.0
    calmar:          float = 0.0
    omega_ratio:     float = 0.0
    tail_ratio:      float = 0.0
    max_drawdown:    float = 0.0
class _C:
    B = '\033[1m'; CY = '\033[96m'; G = '\033[92m'
    Y = '\033[93m'; R = '\033[91m'; M = '\033[95m'
    BB = '\033[44m\033[97m'; DIM = '\033[2m'; RST = '\033[0m'
C = _C
def _calibrate_params(
    log_returns: "np.ndarray",
    ticker: str,
    last_price: float,
    date_start: str,
    date_end: str,
    threshold_k: float = 2.5,
    risk_free_rate: float = 0.07,
) -> JumpDiffusionParams:
    T           = len(log_returns)
    sigma_total = float(np.std(log_returns))
    threshold   = threshold_k * sigma_total
    is_jump     = np.abs(log_returns) > threshold
    n_jumps     = int(is_jump.sum())
    jump_rets   = log_returns[is_jump]
    diff_rets   = log_returns[~is_jump]
    if len(diff_rets) > 2:
        mu_daily    = float(diff_rets.mean())
        sigma_daily = float(diff_rets.std(ddof=1))
    else:
        mu_daily    = float(log_returns.mean())
        sigma_daily = float(log_returns.std(ddof=1))
    mu_ann    = mu_daily    * 252
    sigma_ann = sigma_daily * math.sqrt(252)
    lambda_jump = (n_jumps / T) * 252                                   
    if n_jumps >= 2:
        mu_jump    = float(jump_rets.mean())
        sigma_jump = float(jump_rets.std(ddof=1))
    else:
        mu_jump    = -0.02
        sigma_jump = 0.05
        print(f"  {C.Y}[⚠] Only {n_jumps} jump day(s) found. "
              f"Using conservative jump defaults.{C.RST}")
    k_bar = math.exp(mu_jump + 0.5 * sigma_jump ** 2) - 1
    return JumpDiffusionParams(
        mu          = mu_ann,
        sigma       = sigma_ann,
        lambda_jump = lambda_jump,
        mu_jump     = mu_jump,
        sigma_jump  = sigma_jump,
        k_bar       = k_bar,
        threshold_k = threshold_k,
        n_jump_days = n_jumps,
        total_days  = T,
        ticker      = ticker,
        last_price  = last_price,
        date_start  = date_start,
        date_end    = date_end,
    )
def _simulate_paths(
    p:     JumpDiffusionParams,
    days:  int   = 252,
    n_sim: int   = 3000,
    seed:  Optional[int] = None,
    model: str   = "merton",                      
) -> SimulationResult:
    rng = np.random.default_rng(seed)
    dt  = 1.0 / 252.0                                            
    t0 = time.perf_counter()
    Z = rng.standard_normal((days, n_sim))                                 
    if model == "merton":
        N = rng.poisson(p.lambda_jump * dt, (days, n_sim))               
        J = rng.normal(p.mu_jump, p.sigma_jump, (days, n_sim))              
        jump_term = N * J                                                      
        drift = (p.mu - p.lambda_jump * p.k_bar - 0.5 * p.sigma ** 2) * dt
        label = "Merton JD"
    else:
        jump_term = np.zeros((days, n_sim))
        drift     = (p.mu - 0.5 * p.sigma ** 2) * dt
        label     = "GBM"
    log_increments = drift + p.sigma * math.sqrt(dt) * Z + jump_term
    log_cum  = np.cumsum(log_increments, axis=0)
    paths    = p.last_price * np.exp(log_cum)                          
    elapsed  = time.perf_counter() - t0
    final    = paths[-1]                                                         
    sim_rets = (final - p.last_price) / p.last_price                     
    return SimulationResult(
        paths       = paths,
        final       = final,
        sim_returns = sim_rets,
        params      = p,
        n_sim       = n_sim,
        days        = days,
        elapsed_s   = elapsed,
        model_label = label,
    )
def _compute_risk_metrics(
    result:         SimulationResult,
    risk_free_rate: float = 0.07,
) -> RiskMetrics:
    r     = result.sim_returns
    S0    = result.params.last_price
    final = result.final
    expected = float(final.mean())
    median   = float(np.median(final))
    bull_95  = float(np.percentile(final, 95))
    bear_05  = float(np.percentile(final, 5))
    p_gain   = float((r > 0).mean())
    var_95  = float(np.percentile(r, 5))
    cvar_95 = float(r[r <= var_95].mean()) if (r <= var_95).any() else var_95
    var_99  = float(np.percentile(r, 1))
    cvar_99 = float(r[r <= var_99].mean()) if (r <= var_99).any() else var_99
    neg = r[r < 0]
    if len(neg) > 1:
        semi_std = float(neg.std(ddof=1)) * math.sqrt(252)
        sortino  = (r.mean() * 252 - risk_free_rate) / max(semi_std, 1e-12)
    else:
        sortino = float('nan')
    mean_path   = result.paths.mean(axis=1)                                    
    roll_max    = np.maximum.accumulate(mean_path)
    dd          = (mean_path - roll_max) / roll_max
    max_dd      = float(dd.min())                                          
    ann_ret     = float(r.mean()) * 252
    calmar      = ann_ret / max(abs(max_dd), 1e-12) if max_dd < 0 else float('nan')
    h           = risk_free_rate / 252                                    
    gains       = np.maximum(r - h, 0)
    losses      = np.maximum(h - r, 0)
    omega       = float(gains.mean() / max(losses.mean(), 1e-12))
    p95 = abs(float(np.percentile(r, 95)))
    p05 = abs(float(np.percentile(r, 5)))
    tail_ratio  = p95 / max(p05, 1e-12)
    return RiskMetrics(
        expected_price = expected,
        median_price   = median,
        bull_price_95  = bull_95,
        bear_price_05  = bear_05,
        prob_gain      = p_gain,
        var_95         = var_95,
        cvar_95        = cvar_95,
        var_99         = var_99,
        cvar_99        = cvar_99,
        sortino        = sortino,
        calmar         = calmar,
        omega_ratio    = omega,
        tail_ratio     = tail_ratio,
        max_drawdown   = max_dd,
    )
def _sensitivity_sweep(
    base_params:    JumpDiffusionParams,
    param_name:     str,
    values:         List[float],
    days:           int = 252,
    n_sim:          int = 800,
) -> List[dict]:
    from dataclasses import replace
    results = []
    for val in values:
        p_mod = replace(base_params, **{param_name: float(val)})
        if param_name in ("mu_jump", "sigma_jump"):
            p_mod = replace(p_mod,
                k_bar=math.exp(p_mod.mu_jump + 0.5 * p_mod.sigma_jump ** 2) - 1
            )
        sim  = _simulate_paths(p_mod, days=days, n_sim=n_sim, seed=42)
        mets = _compute_risk_metrics(sim)
        results.append({
            "value":      round(val, 4),
            "exp_return": round(float(sim.sim_returns.mean()) * 100, 2),
            "vol":        round(float(sim.sim_returns.std()) * 100, 2),
            "var_95_pct": round(mets.var_95 * 100, 2),
            "cvar_95_pct":round(mets.cvar_95 * 100, 2),
            "sortino":    round(mets.sortino, 3) if not math.isnan(mets.sortino) else None,
            "prob_gain":  round(mets.prob_gain * 100, 1),
        })
    return results
def _run_stress_scenarios(
    base_params: JumpDiffusionParams,
    days:  int = 252,
    n_sim: int = 1000,
) -> List[dict]:
    from dataclasses import replace
    def _mk(label, desc, **overrides):
        p = replace(base_params, **overrides)
        if any(k in overrides for k in ("mu_jump", "sigma_jump")):
            p = replace(p, k_bar=math.exp(p.mu_jump + 0.5 * p.sigma_jump**2) - 1)
        s = _simulate_paths(p, days=days, n_sim=n_sim, seed=42)
        m = _compute_risk_metrics(s)
        return {
            "label":       label,
            "description": desc,
            "var_95_pct":  round(m.var_95  * 100, 2),
            "cvar_95_pct": round(m.cvar_95 * 100, 2),
            "exp_ret_pct": round(float(s.sim_returns.mean()) * 100, 2),
            "prob_gain":   round(m.prob_gain * 100, 1),
            "sortino":     round(m.sortino, 3) if not math.isnan(m.sortino) else None,
            "max_dd_pct":  round(m.max_drawdown * 100, 2),
        }
    bp = base_params
    return [
        _mk("Baseline",       "Calibrated parameters",
            mu=bp.mu, sigma=bp.sigma,
            lambda_jump=bp.lambda_jump, mu_jump=bp.mu_jump, sigma_jump=bp.sigma_jump),
        _mk("Flash Crash",    "5× jump freq, 2.5× neg jump size",
            lambda_jump=bp.lambda_jump * 5,
            mu_jump=bp.mu_jump * 2.5),
        _mk("Bear Market",    "Half drift, 1.5× volatility",
            mu=bp.mu * 0.5,
            sigma=bp.sigma * 1.5),
        _mk("Vol Spike",      "2× diffusion vol, 3× jump freq",
            sigma=bp.sigma * 2.0,
            lambda_jump=bp.lambda_jump * 3),
        _mk("Low-Vol Bull",   "0.6× vol, 0.3× jump freq, 1.3× drift",
            sigma=bp.sigma * 0.6,
            lambda_jump=bp.lambda_jump * 0.3,
            mu=bp.mu * 1.3),
        _mk("Tail Event",     "8× jumps, 3.5× magnitude, 2× jump vol",
            lambda_jump=bp.lambda_jump * 8,
            mu_jump=bp.mu_jump * 3.5,
            sigma_jump=bp.sigma_jump * 2.0),
    ]
def _build_merton_context(
    params:          JumpDiffusionParams,
    result:          SimulationResult,
    metrics:         RiskMetrics,
    gbm_result:      Optional[SimulationResult],
    gbm_metrics:     Optional[RiskMetrics],
    stress_results:  Optional[List[dict]],
    sensitivity_results: Optional[dict],
) -> dict:
    def _safe(v):
        if v is None:
            return None
        if isinstance(v, float) and math.isnan(v):
            return None
        if isinstance(v, (np.floating, np.integer)):
            return round(float(v), 4)
        if isinstance(v, float):
            return round(v, 4)
        return v
    params_dict = {
        "ticker":       params.ticker,
        "last_price":   round(params.last_price, 2),
        "date_range":   f"{params.date_start} to {params.date_end}",
        "total_days":   params.total_days,
        "jump_days":    params.n_jump_days,
        "jump_pct":     round(100 * params.n_jump_days / max(params.total_days, 1), 2),
        "threshold_k":  params.threshold_k,
        "mu_annual":        round(params.mu, 4),
        "sigma_annual":     round(params.sigma, 4),
        "lambda_annual":    round(params.lambda_jump, 4),
        "mu_jump":          round(params.mu_jump, 4),
        "sigma_jump":       round(params.sigma_jump, 4),
        "k_bar":            round(params.k_bar, 4),
        "implied_mean_jump_pct": round((math.exp(params.mu_jump) - 1) * 100, 2),
    }
    merton_dict = {
        "n_sim":         result.n_sim,
        "days":          result.days,
        "expected_price":  round(metrics.expected_price, 2),
        "median_price":    round(metrics.median_price, 2),
        "bull_price_95":   round(metrics.bull_price_95, 2),
        "bear_price_05":   round(metrics.bear_price_05, 2),
        "prob_gain_pct":   round(metrics.prob_gain * 100, 1),
        "exp_annual_ret_pct": round(result.sim_returns.mean() * 100 * (252 / result.days), 2),
        "var_95_pct":    round(metrics.var_95  * 100, 3),
        "cvar_95_pct":   round(metrics.cvar_95 * 100, 3),
        "var_99_pct":    round(metrics.var_99  * 100, 3),
        "cvar_99_pct":   round(metrics.cvar_99 * 100, 3),
        "sortino":       _safe(metrics.sortino),
        "calmar":        _safe(metrics.calmar),
        "omega_ratio":   round(metrics.omega_ratio, 3),
        "tail_ratio":    round(metrics.tail_ratio, 3),
        "max_drawdown_pct": round(metrics.max_drawdown * 100, 2),
    }
    gbm_dict = None
    if gbm_result and gbm_metrics:
        gbm_dict = {
            "var_95_pct":    round(gbm_metrics.var_95  * 100, 3),
            "cvar_95_pct":   round(gbm_metrics.cvar_95 * 100, 3),
            "prob_gain_pct": round(gbm_metrics.prob_gain * 100, 1),
            "sortino":       _safe(gbm_metrics.sortino),
            "tail_ratio":    round(gbm_metrics.tail_ratio, 3),
            "merton_cvar_premium_pct": round(
                (metrics.cvar_95 - gbm_metrics.cvar_95) * 100, 3
            ),
        }
    return {
        "model_params":        params_dict,
        "merton_simulation":   merton_dict,
        "gbm_baseline":        gbm_dict,
        "stress_scenarios":    stress_results,
        "sensitivity":         sensitivity_results,
    }
def _build_m06_system_prompt(ctx: dict, model_name: str) -> str:
    import json, textwrap
    ticker = ctx["model_params"]["ticker"]
    n_sim  = ctx["merton_simulation"]["n_sim"]
    days   = ctx["merton_simulation"]["days"]
    lam    = ctx["model_params"]["lambda_annual"]
    persona = textwrap.dedent(f"""\
        You are a senior quantitative risk analyst with a background in
        derivatives pricing and stochastic processes.
        You have just completed a Merton Jump-Diffusion Monte Carlo forecast
        for {ticker}: {n_sim:,} simulations over {days} trading days.
        You are powered by {model_name}.
        The calibrated jump intensity λ = {lam:.4f} (annualised).
        Your goal: help the user interpret the parameters, understand the
        risk metrics, compare against GBM, and make practical decisions.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in the <model_params>, <simulation>, <stress>,
           or <sensitivity> data.  Never fabricate statistics.
        2. When citing a metric, quote it exactly
           (e.g. "CVaR₉₅ = −X.XX% means the average loss in the worst 5% of
           scenarios is X.XX%").
        3. Always explain Poisson intensity λ in plain English
           (e.g. λ=0.04 → ~10 jump events per year, on average once every
           25 trading days).
        4. Flag fat-tail risk when |CVaR₉₅| > 1.5 × |VaR₉₅|.
        5. When comparing Merton vs GBM, focus on the CVaR premium and
           tail ratio — these show where the jump model adds the most value.
        6. Translate stress scenarios into plain-English sentences about
           position sizing and stop-loss placement.
        7. Suggest practical hedging actions: protective puts, stop-loss
           levels derived from VaR, position sizing via Kelly criterion.
        8. Keep responses under 450 words unless the user asks for depth.
        9. Never recommend a specific trade or predict the stock price —
           focus on risk framework and probabilistic interpretation.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Lead every response with: [DISTRIBUTION] | [RISK] | [JUMP] | [ACTION]
        - **Bold** key stochastic process terms on first use.
        - Use Markdown tables for any multi-scenario or multi-metric comparison.
        - Use > blockquotes when quoting statistics from the data.
        - Round all percentages to 2 decimal places in tables.
    """)
    params_block = (
        "<model_params description='calibrated Merton Jump-Diffusion parameters'>\n"
        + json.dumps(ctx["model_params"], indent=2)
        + "\n</model_params>"
    )
    sim_block = (
        "<simulation description='Merton JD Monte Carlo results'>\n"
        + json.dumps(ctx["merton_simulation"], indent=2)
        + "\n</simulation>"
    )
    gbm_block = ""
    if ctx.get("gbm_baseline"):
        gbm_block = (
            "<gbm_baseline description='GBM comparison — Merton minus GBM'>\n"
            + json.dumps(ctx["gbm_baseline"], indent=2)
            + "\n</gbm_baseline>"
        )
    stress_block = ""
    if ctx.get("stress_scenarios"):
        stress_block = (
            "<stress_scenarios description='6 regime shock scenarios'>\n"
            + json.dumps(ctx["stress_scenarios"], indent=2)
            + "\n</stress_scenarios>"
        )
    sens_block = ""
    if ctx.get("sensitivity"):
        sens_block = (
            "<sensitivity description='parameter sweep results'>\n"
            + json.dumps(ctx["sensitivity"], indent=2)
            + "\n</sensitivity>"
        )
    parts = [persona, rules, fmt, params_block, sim_block]
    for b in [gbm_block, stress_block, sens_block]:
        if b:
            parts.append(b)
    return "\n\n".join(parts)
def _m06_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        import subprocess, sys
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    import json, time
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS = 20
    if (len(history) - 1) // 2 > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 6 Jump-Diffusion Co-Pilot",
        "Content-Type":  "application/json",
    }
    payload = {"model": model_id, "messages": history, "stream": True}
    full_response = ""
    last_error    = None
    for attempt in range(3):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers, json=payload, stream=True, timeout=(10, 90),
            )
            if resp.status_code == 401:
                console.print("\n  [bold red][!] API key rejected (401). Use /setkey.[/bold red]")
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            word_count = 0
            print(f"\n  \033[90m{model_name} is analysing ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                ps = line[6:]
                if ps.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(ps)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        word_count    += len(token.split())
                        if word_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({word_count} words)\033[0m\n")
            if full_response.strip():
                console.print(Panel(
                    Markdown(full_response),
                    title=f"[bold cyan]{model_name}[/bold cyan]",
                    border_style="cyan", padding=(1, 2), expand=True,
                ))
            return full_response
        except requests.Timeout:
            console.print("\n  [bold red][!] Request timed out.[/bold red]")
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < 2:
                wait = 1.5 ** (attempt + 1)
                console.print(f"  [yellow][~] Attempt {attempt+1} failed ({exc}). Retry in {wait:.1f}s…[/yellow]")
                time.sleep(wait)
            else:
                console.print(f"  [bold red][!] All 3 attempts failed: {last_error}[/bold red]")
    return ""
def _print_m06_chat_help() -> None:
    print("\n  ── Module 6 Jump-Diffusion Co-Pilot Commands ────────")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter"),
        ("/jump",        "Ask AI to interpret the jump parameters"),
        ("/tail",        "Ask AI to analyse tail risk (VaR/CVaR/Omega)"),
        ("/stress",      "Ask AI to rank and explain stress scenarios"),
        ("/hedge",       "Ask AI for practical hedging strategies"),
        ("/compare",     "Ask AI to compare Merton vs GBM results"),
        ("/clear",       "Reset conversation (keeps simulation context)"),
        ("/export",      "Save session to timestamped JSON"),
        ("/status",      "Show model, key, simulation summary"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to the simulation menu"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m06_chat(ctx: dict, cfg: Optional[dict] = None) -> None:
    if cfg is None:
        cfg = _m06_load_config()
    if not cfg["api_key"]:
        print("\n  \033[93m[!] No API key configured for the Jump-Diffusion Co-Pilot.\033[0m")
        cfg = _m06_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Configure a key to enable this feature.")
            return
    history = [
        {
            "role":    "system",
            "content": _build_m06_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    B, CY, G, Y, R, M, RST = C.B, C.CY, C.G, C.Y, C.R, C.M, C.RST
    ticker = ctx["model_params"]["ticker"]
    n_sim  = ctx["merton_simulation"]["n_sim"]
    lam    = ctx["model_params"]["lambda_annual"]
    var95  = ctx["merton_simulation"]["var_95_pct"]
    print("\n" + "─" * 68)
    print(f"  {M}✦ JUMP-DIFFUSION AI CO-PILOT{RST}  |  {CY}{cfg['model_name']}{RST}")
    print(f"  {Y}{ticker}{RST}  |  {CY}{n_sim:,} simulations{RST}  |  "
          f"\033[90mλ={lam:.4f}  VaR₉₅={var95:.2f}%\033[0m")
    print("  Ask about parameters, tail risk, stress scenarios, or hedging.")
    print("  Type /help for commands.")
    print("─" * 68)
    first_prompt = (
        f"I just completed a Merton Jump-Diffusion simulation for {ticker}: "
        f"{n_sim:,} paths, calibrated from historical data. "
        f"Please give me: "
        f"(1) A plain-English interpretation of the key calibrated parameters: "
        f"λ={lam:.4f}, μ_j={ctx['model_params']['mu_jump']:.4f}, "
        f"σ_j={ctx['model_params']['sigma_jump']:.4f}. "
        f"What do these say about this stock's historical jump behaviour? "
        f"(2) The single most important risk finding from the simulation results "
        f"(flag any fat-tail warning if CVaR >> VaR). "
        f"(3) If stress scenarios are available, which is the most dangerous "
        f"and why? "
        f"(4) One practical, actionable hedging suggestion based on VaR₉₅ = "
        f"{var95:.2f}% (what stop-loss level or option structure makes sense?)."
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m06_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        print(f"  {R}[!] Auto-analysis failed. Ask questions below.{RST}\n")
    while True:
        try:
            from rich.console import Console
            user_input = Console().input("\n  [bold cyan]You ›[/bold cyan] ").strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Session ended]"); break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m06_chat_help(); continue
        elif cmd == "/setkey":
            cfg = _m06_setup_key(cfg)
            history[0]["content"] = _build_m06_system_prompt(ctx, cfg["model_name"])
            continue
        elif cmd == "/models":
            cfg = _m06_pick_model(cfg)
            history[0]["content"] = _build_m06_system_prompt(ctx, cfg["model_name"])
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}"); print("  Usage: /model <id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = arg.split("/")[-1].replace(":free"," (free)").replace("-"," ").title()
                _m06_save_config(cfg)
                history[0]["content"] = _build_m06_system_prompt(ctx, cfg["model_name"])
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get("http://127.0.0.1:9999/disabled", timeout=10)
                resp.raise_for_status()
                free = [m for m in resp.json().get("data",[]) if m.get("id","").endswith(":free")]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    print(f"  {m['id']:<55} {(m.get('context_length') or 0)//1000:>5}K")
                print(f"\n  {len(free)} free models. Use: /model <id>\n")
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/jump":
            p = ctx["model_params"]
            jp = (
                f"Focus entirely on jump parameter interpretation. "
                f"λ={p['lambda_annual']:.4f} means how many jump events per year on average? "
                f"μ_j={p['mu_jump']:.4f} — interpret the typical jump magnitude in percentage terms. "
                f"σ_j={p['sigma_jump']:.4f} — what does the dispersion of jump sizes imply? "
                f"k_bar={p['k_bar']:.4f} — explain the drift correction in plain English. "
                f"Compare these parameters to typical values for large-cap equities vs penny stocks."
            )
            history.append({"role": "user", "content": jp})
            ai = _m06_stream_response(history, cfg["api_key"], cfg["model_id"], cfg["model_name"])
            if ai: history.append({"role": "assistant", "content": ai})
            else:  history.pop()
            continue
        elif cmd == "/tail":
            s = ctx["merton_simulation"]
            tp = (
                f"Focus entirely on tail risk analysis. "
                f"VaR₉₅={s['var_95_pct']:.2f}%, CVaR₉₅={s['cvar_95_pct']:.2f}%. "
                f"VaR₉₉={s['var_99_pct']:.2f}%, CVaR₉₉={s['cvar_99_pct']:.2f}%. "
                f"Omega ratio={s['omega_ratio']:.3f}, Tail ratio={s['tail_ratio']:.3f}. "
                f"Is CVaR >> VaR (fat-tail signal)? Interpret the Omega and Tail ratio. "
                f"Compare to regulatory Basel III Expected Shortfall requirements. "
                f"What probability of loss > 10% in one year can be derived from the distribution?"
            )
            history.append({"role": "user", "content": tp})
            ai = _m06_stream_response(history, cfg["api_key"], cfg["model_id"], cfg["model_name"])
            if ai: history.append({"role": "assistant", "content": ai})
            else:  history.pop()
            continue
        elif cmd == "/stress":
            sp = (
                "Produce a Markdown table of all stress scenarios ranked from most to least "
                "dangerous by CVaR₉₅. For each: interpret what market event it represents, "
                "what probability of gain it implies, and whether the risk-reward is "
                "acceptable for a momentum trader vs a long-term value investor."
            )
            history.append({"role": "user", "content": sp})
            ai = _m06_stream_response(history, cfg["api_key"], cfg["model_id"], cfg["model_name"])
            if ai: history.append({"role": "assistant", "content": ai})
            else:  history.pop()
            continue
        elif cmd == "/hedge":
            s    = ctx["merton_simulation"]
            last = ctx["model_params"]["last_price"]
            hp   = (
                f"Suggest practical hedging strategies for a long position in {ticker} "
                f"(current price ≈ ₹{last:.0f}). "
                f"VaR₉₅ = {s['var_95_pct']:.2f}% over the 1-year horizon. "
                f"(1) What stop-loss level corresponds to the VaR₉₅? "
                f"(2) What delta of a protective put would hedge the CVaR₉₅ risk? "
                f"(3) Suggest a Kelly criterion position sizing formula given the "
                f"prob_gain = {s['prob_gain_pct']:.1f}% and expected return. "
                f"(4) Would a collar strategy make sense given the current tail ratio?"
            )
            history.append({"role": "user", "content": hp})
            ai = _m06_stream_response(history, cfg["api_key"], cfg["model_id"], cfg["model_name"])
            if ai: history.append({"role": "assistant", "content": ai})
            else:  history.pop()
            continue
        elif cmd == "/compare":
            if not ctx.get("gbm_baseline"):
                print("  [~] Run GBM comparison first (option G in the menu).")
                continue
            gb = ctx["gbm_baseline"]
            cp = (
                f"Compare Merton Jump-Diffusion vs GBM in a Markdown table. "
                f"Focus on: VaR₉₅ difference, CVaR₉₅ premium "
                f"({gb['merton_cvar_premium_pct']:.2f}%), tail ratio gap, "
                f"and prob_gain difference. "
                f"Explain: when does the Merton model add the most value over GBM? "
                f"Under what market conditions would GBM be 'good enough'? "
                f"What is the CVaR premium telling us about the jump risk?"
            )
            history.append({"role": "user", "content": cp})
            ai = _m06_stream_response(history, cfg["api_key"], cfg["model_id"], cfg["model_name"])
            if ai: history.append({"role": "assistant", "content": ai})
            else:  history.pop()
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Simulation context retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns = (len(history) - 1) // 2
            kh    = f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}" if len(cfg["api_key"])>12 else "not set"
            print(f"\n  Model    : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key  : {kh}")
            print(f"  Ticker   : {ticker}  |  Sims: {n_sim:,}  |  λ={lam:.4f}")
            print(f"  VaR₉₅    : {var95:.2f}%  |  CVaR₉₅: {ctx['merton_simulation']['cvar_95_pct']:.2f}%")
            print(f"  History  : {turns} turns (max 20)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help."); continue
        history.append({"role": "user", "content": user_input})
        ai_resp = _m06_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_resp: history.append({"role": "assistant", "content": ai_resp})
        else:       history.pop()
    print("  [Analysis session closed — returning to simulation menu]\n")
class MertonJumpDiffusion:
    _ANNUALISATION   = 252
    _DATA_PERIOD     = "5y"
    def __init__(
        self,
        ticker:         str,
        n_sim:          int   = 3000,
        days:           int   = 252,
        threshold_k:    float = 2.5,
        risk_free_rate: float = 0.07,
    ):
        self.ticker         = ticker.strip().upper() if ticker else "RELIANCE.NS"
        self.n_sim          = n_sim
        self.days           = days
        self.threshold_k    = threshold_k
        self.risk_free_rate = risk_free_rate
        self._params:         Optional[JumpDiffusionParams]  = None
        self._merton_result:  Optional[SimulationResult]     = None
        self._merton_metrics: Optional[RiskMetrics]          = None
        self._gbm_result:     Optional[SimulationResult]     = None
        self._gbm_metrics:    Optional[RiskMetrics]          = None
        self._stress_results: Optional[List[dict]]           = None
        self._sens_results:   Optional[dict]                 = None
    @staticmethod
    def _check_dependencies() -> bool:
        required = {
            "numpy":   "pip install numpy",
            "pandas":  "pip install pandas",
            "yfinance":"pip install yfinance",
            "matplotlib":"pip install matplotlib",
            "plotly":  "pip install plotly",
            "scipy":   "pip install scipy",
        }
        missing = [(lib, cmd) for lib, cmd in required.items()
                   if not __import__("importlib").util.find_spec(lib)]
        if missing:
            print(f"\n  {C.R}[!] Missing dependencies:{C.RST}")
            for lib, cmd in missing:
                print(f"      {C.Y}{lib:<14}{C.RST} → {cmd}")
            return False
        return True
    def _fetch_and_calibrate(self) -> bool:
        try:
            pass
        except ImportError as e:
            print(f"  {C.R}[!] Import error: {e}{C.RST}")
            return False
        print(f"  {C.CY}Downloading {self._DATA_PERIOD} of daily data for {self.ticker} …{C.RST}")
        try:
            raw = yf.download(
                self.ticker, period=self._DATA_PERIOD,
                interval="1d", progress=False, auto_adjust=True,
            )
        except Exception as exc:
            print(f"  {C.R}[!] Download error: {exc}{C.RST}")
            return False
        if raw.empty:
            print(f"  {C.R}[!] Empty data. Check ticker format "
                  f"(e.g. RELIANCE.NS, AAPL, BTC-USD).{C.RST}")
            return False
        try:
            if isinstance(raw.columns, pd.MultiIndex):
                close = raw['Close'].squeeze()                                       
            else:
                close = raw['Close']
        except KeyError:
            print(f"  {C.R}[!] 'Close' column not found.{C.RST}")
            return False
        close     = close.dropna()
        T         = len(close)
        last_px   = float(close.iloc[-1])
        date_start = str(close.index[0])[:10]
        date_end   = str(close.index[-1])[:10]
        if T < 100:
            print(f"  {C.Y}[⚠] Only {T} trading days — statistics will be unreliable.{C.RST}")
        log_rets = np.log(close / close.shift(1)).dropna().values.astype(float)
        print(f"  {C.M}Calibrating Merton parameters (threshold method, k={self.threshold_k}) …{C.RST}")
        self._params = _calibrate_params(
            log_returns    = log_rets,
            ticker         = self.ticker,
            last_price     = last_px,
            date_start     = date_start,
            date_end       = date_end,
            threshold_k    = self.threshold_k,
            risk_free_rate = self.risk_free_rate,
        )
        self._merton_result  = None
        self._merton_metrics = None
        self._gbm_result     = None
        self._gbm_metrics    = None
        self._stress_results = None
        self._sens_results   = None
        self._display_params()
        return True
    def _run_simulation(self) -> bool:
        if self._params is None:
            print(f"  {C.R}[!] Calibrate parameters first (option F).{C.RST}")
            return False
        print(f"\n  {C.CY}Running Merton JD Monte Carlo …{C.RST}")
        print(f"  {C.DIM}{self.n_sim:,} paths × {self.days} days{C.RST}")
        self._merton_result  = _simulate_paths(
            self._params, days=self.days, n_sim=self.n_sim
        )
        self._merton_metrics = _compute_risk_metrics(
            self._merton_result, self.risk_free_rate
        )
        elapsed = self._merton_result.elapsed_s
        print(f"  {C.G}[✓] Simulation complete in {elapsed*1000:.0f} ms.{C.RST}")
        return True
    def _run_gbm_comparison(self) -> bool:
        if self._params is None:
            print(f"  {C.R}[!] Calibrate first (option F).{C.RST}")
            return False
        print(f"\n  {C.CY}Running GBM baseline (same μ, σ — no jumps) …{C.RST}")
        self._gbm_result  = _simulate_paths(
            self._params, days=self.days, n_sim=self.n_sim, model="gbm"
        )
        self._gbm_metrics = _compute_risk_metrics(
            self._gbm_result, self.risk_free_rate
        )
        print(f"  {C.G}[✓] GBM baseline ready.{C.RST}")
        return True
    def _display_params(self) -> None:
        p = self._params
        if p is None:
            return
        B, G, Y, R, CY, M, RST = C.B, C.G, C.Y, C.R, C.CY, C.M, C.RST
        jump_pct = 100 * p.n_jump_days / max(p.total_days, 1)
        days_between = 252 / max(p.lambda_jump, 1e-6)
        mean_jump_pct = (math.exp(p.mu_jump) - 1) * 100
        print(f"\n  {B}{'═'*70}{RST}")
        print(f"  {C.BB}  MERTON JUMP-DIFFUSION CALIBRATION  |  {p.ticker}  {' '*20}{RST}")
        print(f"  {B}{'═'*70}{RST}")
        print(f"  {CY}Data:{RST} {p.total_days} days  ({p.date_start} → {p.date_end})")
        print(f"  {CY}Jump threshold:{RST} |r| > {p.threshold_k}σ  → {p.n_jump_days} jump days "
              f"({jump_pct:.1f}% of history)")
        print(f"  {'─'*70}")
        print(f"  {B}{'Diffusion Component':<28}{RST}")
        print(f"  {'μ (annual drift)':<24}  {G}{p.mu*100:>8.2f}%{RST}  "
              f"\033[90m← expected annual return (no-jump days)\033[0m")
        print(f"  {'σ (annual vol)':<24}  {Y}{p.sigma*100:>8.2f}%{RST}  "
              f"\033[90m← diffusion volatility (no-jump days)\033[0m")
        print(f"  {'─'*70}")
        print(f"  {B}{'Jump Component':<28}{RST}")
        print(f"  {'λ (jumps/year)':<24}  {M}{p.lambda_jump:>8.4f}{RST}  "
              f"\033[90m← ≈ {p.lambda_jump:.1f} jumps/year, "
              f"once every ~{days_between:.0f} trading days\033[0m")
        print(f"  {'μ_j (mean jump)':<24}  {R}{p.mu_jump*100:>8.2f}%{RST}  "
              f"\033[90m← typical jump = {mean_jump_pct:+.1f}% price change\033[0m")
        print(f"  {'σ_j (jump scatter)':<24}  {Y}{p.sigma_jump*100:>8.2f}%{RST}  "
              f"\033[90m← dispersion of jump magnitudes\033[0m")
        print(f"  {'k̄ (mean excess)':<24}  {CY}{p.k_bar:>8.4f}{RST}  "
              f"\033[90m← drift correction for jump risk premium\033[0m")
        print(f"  {B}{'═'*70}{RST}")
    def _display_risk_report(self) -> None:
        if self._merton_result is None or self._merton_metrics is None:
            print(f"  {C.R}[!] Run simulation first (option R).{C.RST}")
            return
        B, G, Y, R, CY, M, RST = C.B, C.G, C.Y, C.R, C.CY, C.M, C.RST
        m  = self._merton_metrics
        p  = self._params
        S0 = p.last_price
        def _f(v): return f"{v:>8.3f}" if not math.isnan(v) else "     N/A"
        def _p(v): return f"{v*100:>7.2f}%" if v is not None else "    N/A"
        print(f"\n  {B}{'═'*70}{RST}")
        print(f"  {C.BB}  MERTON JD RISK REPORT  |  {self.ticker}  "
              f"|  {self.n_sim:,} sims × {self.days}d  {' '*10}{RST}")
        print(f"  {B}{'═'*70}{RST}")
        print(f"  {'Current Price':<28}  {B}₹{S0:.2f}{RST}")
        print(f"  {'Expected Price (E[S_T])':<28}  {G}₹{m.expected_price:.2f}{RST}")
        print(f"  {'Median Price':<28}  {G}₹{m.median_price:.2f}{RST}")
        print(f"  {'95th Pctile (Bull scenario)':<28}  {G}₹{m.bull_price_95:.2f}{RST}")
        print(f"  {'5th Pctile  (Bear scenario)':<28}  {R}₹{m.bear_price_05:.2f}{RST}")
        print(f"  {'Probability of Gain (>S0)':<28}  {CY}{m.prob_gain*100:>7.1f}%{RST}")
        print(f"  {'─'*70}")
        print(f"  {B}{'TAIL RISK (historical simulation)':<28}{RST}")
        print(f"  {'VaR₉₅  (1-yr, 95% conf)':<28}  "
              f"{R}{_p(m.var_95)}{RST}  "
              f"\033[90m← loss exceeded in 5% of scenarios\033[0m")
        print(f"  {'CVaR₉₅ (Exp. Shortfall)':<28}  "
              f"{R}{_p(m.cvar_95)}{RST}  "
              f"\033[90m← avg loss in worst 5% of scenarios\033[0m")
        print(f"  {'VaR₉₉  (1-yr, 99% conf)':<28}  "
              f"{R}{_p(m.var_99)}{RST}  "
              f"\033[90m← loss exceeded in 1% of scenarios\033[0m")
        print(f"  {'CVaR₉₉ (Exp. Shortfall)':<28}  "
              f"{R}{_p(m.cvar_99)}{RST}  "
              f"\033[90m← avg loss in worst 1% of scenarios\033[0m")
        print(f"  {'─'*70}")
        print(f"  {B}{'RISK-ADJUSTED RATIOS':<28}{RST}")
        print(f"  {'Sortino Ratio':<28}  {CY}{_f(m.sortino)}{RST}  "
              f"\033[90m← (μ−rf) / σ_downside × √252\033[0m")
        print(f"  {'Calmar Ratio':<28}  {CY}{_f(m.calmar)}{RST}  "
              f"\033[90m← annual return / |max drawdown|\033[0m")
        print(f"  {'Omega Ratio (vs rf daily)':<28}  "
              f"{G if m.omega_ratio > 1 else R}{m.omega_ratio:>8.3f}{RST}  "
              f"\033[90m← >1 = more prob mass above rf threshold\033[0m")
        print(f"  {'Tail Ratio (95th/5th)':<28}  "
              f"{G if m.tail_ratio > 1 else R}{m.tail_ratio:>8.3f}{RST}  "
              f"\033[90m← >1 = right tail fatter (upside bias)\033[0m")
        print(f"  {'Max Drawdown (mean path)':<28}  "
              f"{R}{m.max_drawdown*100:>7.2f}%{RST}")
        print(f"  {B}{'═'*70}{RST}")
        if m.var_95 != 0 and abs(m.cvar_95 / m.var_95) > 1.5:
            print(f"  {Y}[⚠] CVaR₉₅ > 1.5× VaR₉₅: fat-tailed distribution detected. "
                  f"Jump component is material to tail risk.{RST}")
        if self._gbm_metrics:
            gm = self._gbm_metrics
            print(f"\n  {B}{'GBM BASELINE COMPARISON':<28}{RST}")
            print(f"  {'─'*70}")
            print(f"  {'Metric':<28}  {'Merton JD':>12}  {'GBM':>10}  {'Premium':>10}")
            print(f"  {'─'*70}")
            def _cmp(label, mval, gval, invert=False):
                diff  = mval - gval
                worse = diff < 0 if not invert else diff > 0
                dc    = R if worse else G
                print(f"  {label:<28}  {mval*100:>11.2f}%  {gval*100:>9.2f}%  "
                      f"{dc}{diff*100:>+9.2f}%{RST}")
            _cmp("VaR₉₅",    m.var_95,  gm.var_95,  invert=True)
            _cmp("CVaR₉₅",   m.cvar_95, gm.cvar_95, invert=True)
            _cmp("Prob Gain", m.prob_gain, gm.prob_gain)
            print(f"  {'─'*70}")
            sr_diff = m.sortino - gm.sortino if not math.isnan(m.sortino) and not math.isnan(gm.sortino) else float('nan')
            sc = G if sr_diff > 0 else R
            sr_str = f"{m.sortino:.3f}" if not math.isnan(m.sortino) else "N/A"
            gsr_str = f"{gm.sortino:.3f}" if not math.isnan(gm.sortino) else "N/A"
            print(f"  {'Sortino Ratio':<28}  {sr_str:>12}  {gsr_str:>10}  "
                  f"{sc}{sr_diff:>+9.3f}{RST}")
            print(f"  {B}{'═'*70}{RST}")
    def _display_sensitivity_table(self, results: List[dict], param_name: str) -> None:
        B, G, Y, R, CY, RST = C.B, C.G, C.Y, C.R, C.CY, C.RST
        cal_val = getattr(self._params, param_name, None)
        label_map = {
            "lambda_jump": "λ (jumps/yr)",
            "mu_jump":     "μ_j (jump mean)",
            "sigma_jump":  "σ_j (jump vol)",
            "sigma":       "σ (diffusion vol)",
        }
        col_label = label_map.get(param_name, param_name)
        print(f"\n  {B}{'═'*74}{RST}")
        print(f"  {C.BB}  SENSITIVITY ANALYSIS — {col_label}  {' '*30}{RST}")
        print(f"  {B}{'═'*74}{RST}")
        print(f"  {B}{col_label:<18}  {'E[ret%]':>8}  {'Vol%':>6}  "
              f"{'VaR₉₅%':>8}  {'CVaR₉₅%':>9}  {'Sortino':>8}  {'P(gain%)':>9}{RST}")
        print(f"  {'─'*72}")
        for row in results:
            v     = row["value"]
            mark  = " ◄" if cal_val is not None and abs(v - cal_val) < 1e-6 else "  "
            vc    = G if row["var_95_pct"] > -2 else (Y if row["var_95_pct"] > -4 else R)
            sr    = f"{row['sortino']:>8.3f}" if row["sortino"] is not None else "     N/A"
            print(
                f"  {B}{v:<18.4f}{RST}  "
                f"{row['exp_return']:>8.2f}  "
                f"{row['vol']:>6.2f}  "
                f"{vc}{row['var_95_pct']:>8.2f}{RST}  "
                f"{vc}{row['cvar_95_pct']:>9.2f}{RST}  "
                f"{sr}  "
                f"{row['prob_gain']:>9.1f}"
                f"{Y}{mark}{RST}"
            )
        print(f"  {B}{'═'*74}{RST}")
    def _display_stress_table(self, results: List[dict]) -> None:
        B, G, Y, R, CY, M, RST = C.B, C.G, C.Y, C.R, C.CY, C.M, C.RST
        sorted_r = sorted(results, key=lambda x: x["cvar_95_pct"])                       
        print(f"\n  {B}{'═'*76}{RST}")
        print(f"  {C.BB}  STRESS SCENARIO ANALYSIS (sorted by CVaR₉₅)  {' '*26}{RST}")
        print(f"  {B}{'═'*76}{RST}")
        print(f"  {B}{'Scenario':<16}  {'CVaR₉₅%':>9}  {'VaR₉₅%':>8}  "
              f"{'E[ret%]':>8}  {'P(gain%)':>9}  {'MaxDD%':>8}{RST}")
        print(f"  {'─'*74}")
        for row in sorted_r:
            is_base = row["label"] == "Baseline"
            cc       = Y if is_base else (R if row["cvar_95_pct"] < -5 else G)
            sr_s     = f"{row['sortino']:>8.3f}" if row["sortino"] is not None else "     N/A"
            mark     = f"  {CY}← baseline{RST}" if is_base else ""
            print(
                f"  {B}{row['label']:<16}{RST}  "
                f"{cc}{row['cvar_95_pct']:>9.2f}{RST}  "
                f"{cc}{row['var_95_pct']:>8.2f}{RST}  "
                f"{row['exp_ret_pct']:>8.2f}  "
                f"{row['prob_gain']:>9.1f}  "
                f"{R}{row['max_dd_pct']:>8.2f}{RST}"
                f"{mark}"
            )
        print(f"  {'─'*74}")
        print(f"  \033[90mAll scenarios: {self.n_sim//6:,} sims × {self.days} days  "
              f"| Sorted most dangerous → least dangerous\033[0m")
        print(f"  {B}{'═'*76}{RST}")
    def visualize_2d(self) -> None:
        if self._merton_result is None:
            print(f"  {C.R}[!] Run simulation first (option R).{C.RST}")
            return
        result = self._merton_result
        m      = self._merton_metrics
        p      = self._params
        paths  = result.paths
        r      = result.sim_returns
        print(f"  {C.M}Rendering 2D visualisation …{C.RST}")
        fig = plt.figure(figsize=(18, 9))
        gs  = gridspec.GridSpec(2, 2, width_ratios=[2.2, 1.8], hspace=0.35, wspace=0.3)
        ax1 = fig.add_subplot(gs[:, 0])
        ax2 = fig.add_subplot(gs[0, 1])
        ax3 = fig.add_subplot(gs[1, 1])
        fig.suptitle(
            f"Merton Jump-Diffusion  |  {self.ticker}  |  "
            f"{self.n_sim:,} simulations  |  "
            f"λ={p.lambda_jump:.4f}  σ={p.sigma*100:.1f}%",
            fontsize=14, fontweight="bold",
        )
        days_ax  = np.arange(result.days)
        pct_10   = np.percentile(paths, 10, axis=1)
        pct_90   = np.percentile(paths, 90, axis=1)
        mean_p   = paths.mean(axis=1)
        bear_p   = paths[:, np.argmin(paths[-1])]                        
        bull_p   = paths[:, np.argmax(paths[-1])]                       
        ax1.plot(days_ax, paths[:, :min(300, self.n_sim)],
                 alpha=0.04, color='teal', lw=0.6)
        ax1.fill_between(days_ax, pct_10, pct_90,
                         alpha=0.12, color='teal', label='10th–90th pctile')
        ax1.plot(days_ax, mean_p, 'k-', lw=2.0, label=f'Mean path')
        ax1.plot(days_ax, bear_p, 'r--', lw=1.2, alpha=0.7, label='Worst path')
        ax1.plot(days_ax, bull_p, 'g--', lw=1.2, alpha=0.7, label='Best path')
        ax1.axhline(p.last_price, ls=':', color='gray', lw=1, alpha=0.6)
        ax1.set_title(f"{self.n_sim:,} Simulated Paths (Merton JD)", fontweight='bold')
        ax1.set_xlabel("Trading Days")
        ax1.set_ylabel("Price (₹)")
        ax1.legend(fontsize=9); ax1.grid(True, alpha=0.25)
        ax2.hist(r * 100, bins=80, color='darkred', alpha=0.55, edgecolor='black', lw=0.3)
        ax2.axvline(m.var_95  * 100, color='orange', ls='--', lw=2.0,
                    label=f'VaR₉₅  ({m.var_95*100:.1f}%)')
        ax2.axvline(m.cvar_95 * 100, color='red',    ls='-',  lw=2.0,
                    label=f'CVaR₉₅ ({m.cvar_95*100:.1f}%)')
        ax2.axvspan(r.min() * 100, m.var_95 * 100, color='red', alpha=0.15, label='Tail')
        prob_str = f"P(gain) = {m.prob_gain*100:.1f}%"
        ax2.annotate(prob_str, xy=(0.97, 0.94), xycoords='axes fraction',
                     ha='right', fontsize=9, color='darkgreen',
                     bbox=dict(boxstyle='round,pad=0.3', fc='white', ec='darkgreen', alpha=0.7))
        ax2.set_title("Terminal Return Distribution", fontweight='bold')
        ax2.set_xlabel("1-year Return (%)"); ax2.set_ylabel("Frequency")
        ax2.legend(fontsize=8); ax2.grid(True, alpha=0.25)
        roll_mx = np.maximum.accumulate(mean_p)
        dd_pct  = (mean_p - roll_mx) / roll_mx * 100
        ax3.fill_between(days_ax, dd_pct, 0, color='crimson', alpha=0.4)
        ax3.plot(days_ax, dd_pct, color='crimson', lw=1.0)
        ax3.axhline(m.max_drawdown * 100, color='black', ls='--', lw=1.2,
                    label=f'Max DD = {m.max_drawdown*100:.1f}%')
        ax3.set_title("Drawdown — Mean Path", fontweight='bold')
        ax3.set_xlabel("Trading Days"); ax3.set_ylabel("Drawdown (%)")
        ax3.legend(fontsize=8); ax3.grid(True, alpha=0.25)
        plt.tight_layout(rect=[0, 0, 1, 0.96])
        plt.show()
    def visualize_3d_surface(self) -> None:
        if self._merton_result is None:
            print(f"  {C.R}[!] Run simulation first (option R).{C.RST}")
            return
        try:
            import plotly.graph_objs as go
            from plotly.subplots import make_subplots
            from scipy.stats import gaussian_kde
        except ImportError:
            print(f"  {C.R}[!] plotly and scipy are required for 3D visualisation.{C.RST}")
            print("      pip install plotly scipy")
            return
        paths  = self._merton_result.paths                   
        p      = self._params
        n_sim  = self._merton_result.n_sim
        days   = self._merton_result.days
        DARK_BG = "#0e1117"
        ACCENT  = "#00d4aa"
        print(f"  {C.M}Building 3D price distribution surface …{C.RST}")
        print(f"  {C.DIM}Computing KDE at 30 time snapshots × 80 price points{C.RST}")
        n_t_snaps   = 30
        t_indices   = np.linspace(0, days - 1, n_t_snaps, dtype=int)
        price_lo    = float(np.percentile(paths, 1))
        price_hi    = float(np.percentile(paths, 99))
        n_price_pts = 80
        price_grid  = np.linspace(price_lo, price_hi, n_price_pts)
        Z_surface = np.zeros((n_price_pts, n_t_snaps))
        for j, t_idx in enumerate(t_indices):
            price_slice = paths[t_idx]                                      
            try:
                kde = gaussian_kde(price_slice, bw_method=0.25)
                Z_surface[:, j] = kde(price_grid)
            except Exception:
                Z_surface[:, j] = 0.0
        T_mesh, P_mesh = np.meshgrid(t_indices, price_grid)
        surf = go.Surface(
            x=T_mesh,
            y=P_mesh,
            z=Z_surface,
            colorscale="Viridis",
            opacity=0.88,
            showscale=True,
            colorbar=dict(
                title=dict(text="Density", font=dict(color=ACCENT)),
                tickfont=dict(color=ACCENT),
            ),
            hovertemplate=(
                "Day: %{x}<br>Price: ₹%{y:.2f}<br>Density: %{z:.4f}<extra></extra>"
            ),
            name="PDF cone",
        )
        mean_prices_at_snaps = paths[t_indices].mean(axis=1)
        mean_density_at_snaps = np.array([
            float(gaussian_kde(paths[t], bw_method=0.25)(mean_prices_at_snaps[j]))
            for j, t in enumerate(t_indices)
        ])
        mean_line = go.Scatter3d(
            x=t_indices,
            y=mean_prices_at_snaps,
            z=mean_density_at_snaps + 0.0002,                                               
            mode="lines",
            line=dict(color=ACCENT, width=6),
            name="Mean path",
            hovertemplate="Day: %{x}<br>E[Price]: ₹%{y:.2f}<extra></extra>",
        )
        var_price  = float(np.percentile(paths[-1], 5))                         
        var_t_line = go.Scatter3d(
            x=[0, days - 1],
            y=[var_price, var_price],
            z=[0, 0],
            mode="lines",
            line=dict(color="red", width=4, dash="dash"),
            name=f"5th pctile price ₹{var_price:.0f}",
        )
        fig1 = go.Figure(data=[surf, mean_line, var_t_line])
        fig1.update_layout(
            title=dict(
                text=f"3D Price Distribution Cone — {self.ticker}  "
                     f"[Merton JD | λ={p.lambda_jump:.4f}]",
                font=dict(color=ACCENT, size=16),
            ),
            scene=dict(
                xaxis=dict(title="Trading Day", color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                yaxis=dict(title="Price (₹)", color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                zaxis=dict(title="Probability Density", color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                bgcolor=DARK_BG,
                camera=dict(eye=dict(x=-1.6, y=1.8, z=0.8)),               
            ),
            paper_bgcolor=DARK_BG,
            font=dict(color=ACCENT),
            margin=dict(l=0, r=0, b=0, t=50),
            legend=dict(font=dict(color=ACCENT), bgcolor=DARK_BG),
        )
        print(f"  {C.G}Launching 3D Price Distribution Surface in browser …{C.RST}")
        fig1.show()
        print(f"  {C.M}Building 3D path landscape (coloured by jump count) …{C.RST}")
        rng2     = np.random.default_rng(seed=99)
        dt       = 1.0 / 252.0
        n_show   = min(400, n_sim)                                  
        N_jumps = rng2.poisson(p.lambda_jump * dt, (days, n_show))
        jump_counts_per_path = N_jumps.sum(axis=0)                                   
        sub_final    = self._merton_result.final[:n_show]
        sort_order   = np.argsort(sub_final)
        sorted_paths = paths[:, sort_order]                                  
        sorted_jc    = jump_counts_per_path[sort_order]                 
        t_arr  = np.tile(np.arange(days), n_show)                                 
        p_arr  = np.arange(n_show).repeat(days)                                   
        s_arr  = sorted_paths.T.flatten()                                      
        c_arr  = sorted_jc.repeat(days)                                            
        scatter3d = go.Scatter3d(
            x=t_arr[::2],                                            
            y=p_arr[::2],
            z=s_arr[::2],
            mode="lines",
            line=dict(
                color=c_arr[::2],
                colorscale="Plasma",
                width=1,
                cmin=0,
                cmax=int(jump_counts_per_path.max()),
                colorbar=dict(
                  title=dict(text="Total jumps", font=dict(color=ACCENT)),
                  tickfont=dict(color=ACCENT),
                  x=1.02,
                ),
            ),
            opacity=0.6,
            hovertemplate="Day: %{x}<br>Path: %{y}<br>Price: ₹%{z:.2f}<extra></extra>",
            name="paths",
        )
        fig2 = go.Figure(data=[scatter3d])
        fig2.update_layout(
            title=dict(
                text=f"3D Path Landscape — {self.ticker}  "
                     f"[{n_show} paths sorted by final price | colour = jump count]",
                font=dict(color=ACCENT, size=15),
            ),
            scene=dict(
                xaxis=dict(title="Trading Day",  color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                yaxis=dict(title="Path rank",    color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                zaxis=dict(title="Price (₹)",   color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                bgcolor=DARK_BG,
                camera=dict(eye=dict(x=2.0, y=-1.5, z=0.9)),
            ),
            paper_bgcolor=DARK_BG,
            font=dict(color=ACCENT),
            margin=dict(l=0, r=0, b=0, t=50),
        )
        print(f"  {C.G}Launching 3D Path Landscape in browser …{C.RST}")
        fig2.show()
    def _run_sensitivity(self) -> None:
        if self._params is None:
            print(f"  {C.R}[!] Calibrate first (option F).{C.RST}")
            return
        p = self._params
        print(f"\n  {C.CY}Running sensitivity sweep (3 parameters × 8 values) …{C.RST}")
        sweeps = {
            "lambda_jump": np.linspace(max(p.lambda_jump * 0.25, 0.005),
                                       p.lambda_jump * 3.0, 8).tolist(),
            "mu_jump":     np.linspace(p.mu_jump * 2.0, p.mu_jump * 0.2, 8).tolist()
                           if p.mu_jump < 0
                           else np.linspace(-0.10, 0.05, 8).tolist(),
            "sigma":       np.linspace(p.sigma * 0.4, p.sigma * 2.0, 8).tolist(),
        }
        self._sens_results = {}
        for param_name, values in sweeps.items():
            print(f"  {C.DIM}  Sweeping {param_name} …{C.RST}", end="", flush=True)
            results = _sensitivity_sweep(
                p, param_name, values, days=self.days, n_sim=800
            )
            self._sens_results[param_name] = results
            print(f" {C.G}done{C.RST}")
            self._display_sensitivity_table(results, param_name)
    def _run_stress_tests(self) -> None:
        if self._params is None:
            print(f"  {C.R}[!] Calibrate first (option F).{C.RST}")
            return
        print(f"\n  {C.CY}Running 6 stress scenarios …{C.RST}")
        stress_n = max(500, self.n_sim // 6)
        self._stress_results = _run_stress_scenarios(
            self._params, days=self.days, n_sim=stress_n
        )
        self._display_stress_table(self._stress_results)
    def _build_ai_context(self) -> Optional[dict]:
        if self._params is None or self._merton_result is None or self._merton_metrics is None:
            print(f"  {C.Y}[~] Run at least one simulation first.{C.RST}")
            return None
        return _build_merton_context(
            params           = self._params,
            result           = self._merton_result,
            metrics          = self._merton_metrics,
            gbm_result       = self._gbm_result,
            gbm_metrics      = self._gbm_metrics,
            stress_results   = self._stress_results,
            sensitivity_results = self._sens_results,
        )
    def interactive_menu(self) -> None:
        if not self._check_dependencies():
            return
        ai_cfg = _m06_load_config()
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            has_params = self._params is not None
            has_sim    = self._merton_result is not None
            has_gbm    = self._gbm_result is not None
            has_stress = self._stress_results is not None
            has_sens   = self._sens_results is not None
            ps = f"{C.G}[calibrated]{C.RST}" if has_params else f"{C.Y}[not calibrated]{C.RST}"
            ss = f"{C.G}[sim ready]{C.RST}"   if has_sim    else f"{C.Y}[no sim]{C.RST}"
            print(f"\n  {C.BB} MODULE 6 — MERTON JUMP-DIFFUSION MONTE CARLO {' '*28}{C.RST}")
            print(f"  {'═'*76}")
            print(f"  {C.B}Ticker:{C.RST}  {C.CY}{self.ticker}{C.RST}   {ps}   {ss}")
            print(f"  {C.B}Sims:{C.RST} {self.n_sim:,}   "
                  f"{C.B}Horizon:{C.RST} {self.days}d   "
                  f"{C.B}Threshold k:{C.RST} {self.threshold_k}   "
                  f"{C.B}rf:{C.RST} {self.risk_free_rate*100:.1f}%")
            if has_params:
                p = self._params
                print(f"  {C.DIM}λ={p.lambda_jump:.4f}  μ={p.mu*100:.1f}%  "
                      f"σ={p.sigma*100:.1f}%  μ_j={p.mu_jump*100:.2f}%  "
                      f"σ_j={p.sigma_jump*100:.2f}%{C.RST}")
