def _m22_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title(),
    }
    if not os.path.exists(_M22_CONFIG_FILE):
        return defaults
    try:
        with open(_M22_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**defaults, **data}
    except (json.JSONDecodeError, OSError):
        return defaults
def _m22_save_config(cfg: dict) -> bool:
    payload = {
        "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
        "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
        "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
    }
    try:
        with open(_M22_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  ⚠  Could not save config: {exc}")
        return False
def _m22_setup_key(cfg: dict) -> dict:
    import getpass
    print("\n  ── API Key Setup (Module 22) ────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M22_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m22_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _m22_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models ───────────────────────────")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 54)
    for i, m in enumerate(_M22_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M22_FREE_MODELS):
            sel               = _M22_FREE_MODELS[idx]
            cfg["model_id"]   = sel["id"]
            cfg["model_name"] = sel["name"]
            _m22_save_config(cfg)
            print(f"  [✓] Switched to {sel['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
def _build_risk_context(
    ticker:          str,
    account_balance: float,
    ks:              dict,
    ts:              dict,
    ps:              dict,
    trade_returns:   "np.ndarray",
) -> dict:
    def _s(v, dp: int = 4):
        if v is None:
            return None
        try:
            f = float(v)
            return None if math.isnan(f) or math.isinf(f) else round(f, dp)
        except (TypeError, ValueError):
            return None
    dist_ctx: dict = {}
    if len(trade_returns) > 0:
        wins   = trade_returns[trade_returns > 0]
        losses = trade_returns[trade_returns < 0]
        dist_ctx = {
            "mean_return_pct":    _s(float(np.mean(trade_returns))  * 100, 3),
            "median_return_pct":  _s(float(np.median(trade_returns)) * 100, 3),
            "std_return_pct":     _s(float(np.std(trade_returns))    * 100, 3),
            "best_trade_pct":     _s(float(np.max(trade_returns))    * 100, 3),
            "worst_trade_pct":    _s(float(np.min(trade_returns))    * 100, 3),
            "pct25":              _s(float(np.percentile(trade_returns, 25)) * 100, 3),
            "pct75":              _s(float(np.percentile(trade_returns, 75)) * 100, 3),
            "avg_win_pct":        _s(float(np.mean(wins))   * 100, 3) if len(wins)   else None,
            "avg_loss_pct":       _s(float(np.mean(losses)) * 100, 3) if len(losses) else None,
            "n_wins":             int(len(wins)),
            "n_losses":           int(len(losses)),
            "n_flat":             int(len(trade_returns) - len(wins) - len(losses)),
        }
    warnings_list: list[str] = []
    if ks.get("n_trades", 0) < 30:
        warnings_list.append(
            f"Small sample: only {ks.get('n_trades',0)} trades — "
            f"bootstrap CI is wide; prefer Quarter-Kelly."
        )
    if ks.get("expected_value", 0) <= 0:
        warnings_list.append(
            "Negative expected value — strategy has no statistical edge; "
            "do not deploy capital."
        )
    if ks.get("R", 0) < 1.0:
        warnings_list.append(
            f"R-ratio {_s(ks.get('R',0), 2)} < 1.0 — average losses exceed "
            f"average wins; position sizing alone cannot fix this."
        )
    if ts.get("risk_of_ruin", 1.0) > 0.10:
        warnings_list.append(
            f"Risk-of-Ruin {_s(ts.get('risk_of_ruin',0)*100, 1)}% > 10% — "
            f"reduce position size or improve win rate before live trading."
        )
    if ts.get("max_drawdown", 0) < -0.30:
        warnings_list.append(
            f"Max drawdown {_s(ts.get('max_drawdown',0)*100, 1)}% — equity fell "
            f"more than 30%; psychological and margin-call risk is elevated."
        )
    if ts.get("profit_factor", 0) < 1.0:
        warnings_list.append(
            f"Profit factor {_s(ts.get('profit_factor',0), 2)} < 1.0 — "
            f"gross losses exceed gross wins; strategy is net unprofitable."
        )
    return {
        "ticker":          ticker,
        "account_balance": _s(account_balance, 2),
        "backtest_period": "3 years (daily, MA 20/50 crossover)",
        "kelly_metrics": {
            "n_trades":        ks.get("n_trades"),
            "n_wins":          ks.get("n_wins"),
            "n_losses":        ks.get("n_losses"),
            "win_rate_pct":    _s(ks.get("W", 0) * 100, 2),
            "win_rate_ci_95":  [_s(ks.get("win_ci_lo", 0) * 100, 2),
                                 _s(ks.get("win_ci_hi", 0) * 100, 2)],
            "avg_win_pct":     _s(ks.get("avg_win",  0) * 100, 3),
            "avg_loss_pct":    _s(ks.get("avg_loss", 0) * 100, 3),
            "r_ratio":         _s(ks.get("R", 0), 3),
            "expected_value_pct": _s(ks.get("expected_value", 0) * 100, 3),
            "full_kelly_pct":    _s(ks.get("full_kelly",    0) * 100, 2),
            "half_kelly_pct":    _s(ks.get("half_kelly",    0) * 100, 2),
            "quarter_kelly_pct": _s(ks.get("quarter_kelly", 0) * 100, 2),
            "kelly_ci_95":       [_s(ks.get("kelly_ci_lo", 0) * 100, 2),
                                   _s(ks.get("kelly_ci_hi", 0) * 100, 2)],
        },
        "trade_statistics": {
            "sharpe_ratio":        _s(ts.get("sharpe")),
            "sortino_ratio":       _s(ts.get("sortino")),
            "profit_factor":       _s(ts.get("profit_factor")),
            "max_drawdown_pct":    _s(ts.get("max_drawdown", 0) * 100, 2),
            "max_consec_losses":   ts.get("max_consec_losses"),
            "risk_of_ruin_pct":    _s(ts.get("risk_of_ruin", 0) * 100, 3),
            "gross_win":           _s(ts.get("gross_win")),
            "gross_loss":          _s(ts.get("gross_loss")),
        },
        "position_sizing": {
            "current_price":     _s(ps.get("curr_price"), 2),
            "fixed_2pct_risk": {
                "shares":          ps.get("shares_fixed"),
                "investment":      _s(ps.get("invest_fixed"), 2),
                "pct_of_account":  _s((ps.get("invest_fixed", 0) /
                                       account_balance * 100)
                                      if account_balance else None, 2),
            },
            "half_kelly": {
                "shares":          ps.get("shares_hk"),
                "investment":      _s(ps.get("invest_hk"), 2),
                "pct_of_account":  _s((ps.get("invest_hk", 0) /
                                       account_balance * 100)
                                      if account_balance else None, 2),
            },
            "quarter_kelly": {
                "shares":          ps.get("shares_qk"),
                "investment":      _s(ps.get("invest_qk"), 2),
                "pct_of_account":  _s((ps.get("invest_qk", 0) /
                                       account_balance * 100)
                                      if account_balance else None, 2),
            },
        },
        "stop_loss_atr": {
            "atr_14_period":       _s(ps.get("curr_atr"), 4),
            "stop_distance_2xatr": _s(ps.get("sl_dist"), 4),
            "stop_price":          _s(ps.get("sl_price"), 2),
            "stop_pct_of_price":   _s((ps.get("sl_dist", 0) /
                                       ps.get("curr_price", 1) * 100)
                                      if ps.get("curr_price") else None, 2),
        },
        "return_distribution": dist_ctx,
        "pre_computed_warnings": warnings_list,
    }
def _build_m22_system_prompt(ctx: dict, model_name: str) -> str:
    ticker = ctx["ticker"]
    persona = textwrap.dedent(f"""\
        You are a senior Quantitative Risk Manager reviewing a Kelly Criterion
        analysis and backtest results for {ticker}.
        You have access to the complete computed metrics: Kelly fractions with
        bootstrap confidence intervals, trade statistics, position sizing
        comparison, and ATR stop-loss parameters.
        You are powered by {model_name}.
        Be precise — cite exact values. Explain maths in plain English first,
        then give the number.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in the <terminal_data> below. Do not invent values.
        2. When citing a metric, include its value
           (e.g. "Win rate is 54.3% with a 95% CI of [42.1%, 66.5%]").
        3. Explain WHY each Kelly fraction is what it is — trace it back
           to the win rate and R-ratio that produced it.
        4. Surface ALL pre_computed_warnings and explain what each means
           for live trading decisions.
        5. Kelly sizing recommendation MUST reference the CI width —
           a wide CI means high uncertainty and justifies Quarter-Kelly.
        6. Distinguish backtest results (historical) from forward expectations
           (regime change, slippage, commissions are not captured here).
        7. Keep responses under 450 words unless the user asks for more.
        8. If a metric is None/null, say it wasn't computed rather than guessing.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Prefix every response: [KELLY] | [RISK] | [SIZING] | [ANSWER] | [INFO]
        - **Bold** all metric names and values.
        - Use > blockquotes for critical risk warnings.
        - Use Markdown tables when comparing the three position sizing methods.
        - Express Kelly fractions as percentages (e.g. "Half-Kelly: 8.3%").
    """)
    data_json  = json.dumps(ctx, indent=2)
    data_block = f"<terminal_data>\n{data_json}\n</terminal_data>"
    return "\n\n".join([persona, rules, fmt, data_block])
def _m22_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS  = 20
    turn_count = (len(history) - 1) // 2
    if turn_count > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 22 Risk & Kelly CoPilot",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    model_id,
        "messages": history,
        "stream":   True,
    }
    BACKOFF_BASE  = 1.5
    MAX_RETRIES   = 3
    full_response = ""
    last_error    = None
    for attempt in range(MAX_RETRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers,
                json=payload,
                stream=True,
                timeout=(10, 60),
            )
            if resp.status_code == 401:
                console.print(
                    "\n  [bold red][!] API key rejected (401). "
                    "Use /setkey to update.[/bold red]"
                )
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            token_count = 0
            print(f"\n  \033[90m{model_name} is thinking ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        token_count   += len(token.split())
                        if token_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({token_count} words)\033[0m\n")
            if full_response.strip():
                console.print(
                    Panel(
                        Markdown(full_response),
                        title=f"[bold cyan]{model_name}[/bold cyan]",
                        border_style="cyan",
                        padding=(1, 2),
                        expand=True,
                    )
                )
            return full_response
        except requests.Timeout:
            console.print(
                "\n  [bold red][!] Request timed out. "
                "Try a shorter question or /models to switch.[/bold red]"
            )
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < MAX_RETRIES - 1:
                wait = BACKOFF_BASE ** (attempt + 1)
                console.print(
                    f"  [yellow][~] Attempt {attempt + 1} failed ({exc}). "
                    f"Retrying in {wait:.1f}s…[/yellow]"
                )
                time.sleep(wait)
            else:
                console.print(
                    f"  [bold red][!] All {MAX_RETRIES} attempts failed: "
                    f"{last_error}[/bold red]"
                )
    return ""
def _print_m22_chat_help() -> None:
    print("\n  ── Module 22 Risk & Kelly Co-Pilot Commands ─────────")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by full OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter API"),
        ("/clear",       "Clear conversation (keep risk data)"),
        ("/export",      "Save session to a timestamped JSON file"),
        ("/status",      "Show model, key status, history length"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to the main terminal"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m22_chat(
    ticker:          str,
    account_balance: float,
    ks:              dict,
    ts:              dict,
    ps:              dict,
    trade_returns:   "np.ndarray",
) -> None:
    cfg = _m22_load_config()
    if not cfg["api_key"]:
        print("\n  \033[93m[!] No API key configured for Module 22 AI.\033[0m")
        cfg = _m22_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Run module again to configure.")
            return
    ctx = _build_risk_context(ticker, account_balance, ks, ts, ps, trade_returns)
    history = [
        {
            "role":    "system",
            "content": _build_m22_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    print("\n" + "─" * 68)
    print(f"  \033[95m🧠 MODULE 22 RISK & KELLY CO-PILOT\033[0m  |  "
          f"\033[96m{cfg['model_name']}\033[0m  |  "
          f"\033[93m{ticker}\033[0m")
    print("  Ask about Kelly sizing, risk metrics, or position sizing.")
    print("  Type /help for commands.")
    print("─" * 68)
    n_warnings = len(ctx.get("pre_computed_warnings", []))
    warn_note  = (f" There are {n_warnings} pre-computed risk warnings — "
                  f"address all of them."
                  if n_warnings else "")
    first_prompt = (
        f"I've just run a Kelly Criterion risk assessment for {ticker} "
        f"on a 3-year MA crossover backtest.{warn_note} "
        f"Give me a comprehensive analysis covering: "
        f"(1) explain what my win rate and R-ratio mean and how they "
        f"combine to produce the Kelly fraction shown — trace the maths, "
        f"(2) interpret the bootstrap confidence interval on the Kelly — "
        f"what does the CI width tell me about how much to trust this number, "
        f"(3) which of the three position sizing methods (Fixed 2%, Half-Kelly, "
        f"Quarter-Kelly) should I use and why, given my specific sample size "
        f"and CI, "
        f"(4) what does the Risk-of-Ruin figure mean in practical terms, and "
        f"(5) the single most important thing I should fix before deploying "
        f"this strategy with real capital."
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m22_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        print("  \033[91m[!] Auto-analysis failed. "
              "You can still ask questions below.\033[0m\n")
    while True:
        try:
            from rich.console import Console
            _con       = Console()
            user_input = _con.input(
                "\n  [bold cyan]You ›[/bold cyan] "
            ).strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Co-Pilot session ended]")
            break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m22_chat_help()
            continue
        elif cmd == "/setkey":
            cfg = _m22_setup_key(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m22_system_prompt(ctx, cfg["model_name"]),
            }
            continue
        elif cmd == "/models":
            cfg = _m22_pick_model(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m22_system_prompt(ctx, cfg["model_name"]),
            }
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}")
                print("  Usage:   /model <openrouter-model-id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = (
                    arg.split("/")[-1]
                       .replace(":free", " (free)")
                       .replace("-", " ")
                       .title()
                )
                _m22_save_config(cfg)
                history[0] = {
                    "role":    "system",
                    "content": _build_m22_system_prompt(ctx, cfg["model_name"]),
                }
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get(
                    "http://127.0.0.1:9999/disabled", timeout=10
                )
                resp.raise_for_status()
                free = [
                    m for m in resp.json().get("data", [])
                    if m.get("id", "").endswith(":free")
                ]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    ctx_k = (m.get("context_length") or 0) // 1000
                    print(f"  {m['id']:<55} {ctx_k:>5}K")
                print(
                    f"\n  {len(free)} free models found. "
                    f"Activate with: /model <id>\n"
                )
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Risk data retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns    = (len(history) - 1) // 2
            key_hint = (
                f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}"
                if len(cfg["api_key"]) > 12 else "not set"
            )
            n_warn = len(ctx.get("pre_computed_warnings", []))
            print(f"\n  Model     : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key   : {key_hint}")
            print(f"  Ticker    : {ticker}  |  "
                  f"Trades: {ks.get('n_trades', 0)}  |  "
                  f"Warnings: {n_warn}")
            print(f"  History   : {turns} turns (max 20 before auto-prune)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help.")
            continue
        history.append({"role": "user", "content": user_input})
        ai_response = _m22_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_response:
            history.append({"role": "assistant", "content": ai_response})
        else:
            history.pop()
    print("  [Co-Pilot closed — returning to terminal]\n")
def run_risk_assessment(ticker: str) -> None:
    header(f"MODULE 22 — RISK ASSESSMENT & KELLY CRITERION  |  {ticker}")
    account_balance = _prompt_positive_float(
        "  Enter your account balance (₹) [default 1000000]: ", 1_000_000
    )
    print(f"\n  Downloading 3-year daily data for {ticker} …")
    try:
        data = yf.download(ticker, period="3y", interval="1d", progress=False)
        if data.empty:
            print(f"  ✗ No data returned for '{ticker}'. "
                  "Check the symbol and your internet connection.")
            return
        data = flatten_cols(data)                          
    except Exception as exc:
        print(f"  ✗ Download failed: {exc}")
        return
    required_cols = {'Open', 'High', 'Low', 'Close'}
    missing = required_cols - set(data.columns)
    if missing:
        print(f"  ✗ Missing columns after flatten: {missing}")
        return
    print("  Running MA Crossover backtest …")
    trade_returns = _ma_crossover_trades(data, fast=20, slow=50)
    print("  Computing Kelly statistics (bootstrap 2 000 resamples) …")
    ks = _kelly_stats(trade_returns)
    ts = _trade_statistics(trade_returns)
    ps = _atr_position_sizing(data, account_balance, ks)
    _print_report(ticker, account_balance, ks, ts, ps)
    _render_dashboard(ticker, data, trade_returns, ks, ts, ps, account_balance)
    print(f"\n  {'─' * 54}")
    try:
        launch = input(
            "  Open AI Co-Pilot to analyse these risk results? [Y/n]: "
        ).strip().lower()
    except (EOFError, KeyboardInterrupt):
        launch = "n"
    if launch not in {"n", "no"}:
        run_m22_chat(
            ticker          = ticker,
            account_balance = account_balance,
            ks              = ks,
            ts              = ts,
            ps              = ps,
            trade_returns   = trade_returns,
        )
    else:
        press_enter()
_M12_CONFIG_FILE = "module12_config.json"
_M12_FREE_MODELS = [
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",                 "name": "Gemma 3 27B",    "note": "★ Default — best balance"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",                  "name": "DeepSeek R1",    "note": "Best for ratio analysis"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",                "name": "DeepSeek V3",    "note": "Fast + strong on data"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",     "name": "Llama 3.3 70B", "note": "128K ctx, handles all 3 stmts"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",            "name": "Qwen 2.5 72B",  "note": "Great Markdown tables"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",         "name": "Mistral 7B",    "note": "Reliable, fast"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",  "name": "Hermes 3 405B", "note": "Largest free — deepest analysis"},
    {"id": "nvidia/nemotron-3-super-120b-a12b:free",  "name": "Phi-3 Medium",  "note": "Efficient, good reasoning"},
]
def _m12_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title(),
    }
    if not os.path.exists(_M12_CONFIG_FILE):
        return defaults
    try:
        with open(_M12_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**defaults, **data}
    except (json.JSONDecodeError, OSError):
        return defaults
def _m12_save_config(cfg: dict) -> bool:
    payload = {
        "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
        "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
        "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
    }
    try:
        with open(_M12_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  ⚠  Could not save config: {exc}")
        return False
def _m12_setup_key(cfg: dict) -> dict:
    import getpass
    print("\n  ── API Key Setup (Module 12) ────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M12_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m12_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _m12_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models ───────────────────────────")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 54)
    for i, m in enumerate(_M12_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M12_FREE_MODELS):
            sel               = _M12_FREE_MODELS[idx]
            cfg["model_id"]   = sel["id"]
            cfg["model_name"] = sel["name"]
            _m12_save_config(cfg)
            print(f"  [✓] Switched to {sel['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
def _build_statements_context(
    ticker:  str,
    income:  "pd.DataFrame",
    balance: "pd.DataFrame",
    cash:    "pd.DataFrame",
    flags:   dict,
) -> dict:
    def _safe(v, dp: int = 2):
        if v is None:
            return None
        try:
            f = float(v)
            return None if math.isnan(f) else round(f, dp)
        except (TypeError, ValueError):
            return None
    def _find_row(df: "pd.DataFrame", *keys: str) -> "pd.Series | None":
        if df is None or df.empty:
            return None
        for key in keys:
            for iname in df.index:
                if key.lower() in str(iname).lower():
                    return df.loc[iname]
        return None
    def _last(s: "pd.Series | None") -> float | None:
        if s is None:
            return None
        try:
            v = float(s.iloc[-1])
            return None if math.isnan(v) else v
        except (TypeError, ValueError, IndexError):
            return None
    def _prev(s: "pd.Series | None") -> float | None:
        if s is None or len(s) < 2:
            return None
        try:
            v = float(s.iloc[-2])
            return None if math.isnan(v) else v
        except (TypeError, ValueError):
            return None
    def _periods(df: "pd.DataFrame") -> list[str]:
        if df is None or df.empty:
            return []
        return list(df.columns)
    def _cagr(series: "pd.Series | None") -> float | None:
        if series is None:
            return None
        vals = []
        for v in series:
            try:
                f = float(v)
                if not math.isnan(f) and f > 0:
                    vals.append(f)
            except (TypeError, ValueError):
                pass
        if len(vals) < 2:
            return None
        n = len(vals) - 1
        return round(((vals[-1] / vals[0]) ** (1 / n) - 1) * 100, 2)
    rev    = _find_row(income, "Total Revenue", "Operating Revenue", "Revenue")
    gp     = _find_row(income, "Gross Profit")
    opinc  = _find_row(income, "Operating Income", "Ebit")
    ni     = _find_row(income, "Net Income")
    rev_last  = _last(rev);   rev_prev  = _prev(rev)
    gp_last   = _last(gp)
    op_last   = _last(opinc)
    ni_last   = _last(ni);    ni_prev   = _prev(ni)
    gross_margin = _safe((gp_last / rev_last * 100)   if (gp_last is not None and rev_last) else None)
    net_margin   = _safe((ni_last / rev_last * 100)   if (ni_last is not None and rev_last) else None)
    op_margin    = _safe((op_last / rev_last * 100)   if (op_last is not None and rev_last) else None)
    rev_yoy      = _safe(((rev_last - rev_prev) / abs(rev_prev) * 100)
                          if (rev_last is not None and rev_prev) else None)
    ni_yoy       = _safe(((ni_last  - ni_prev)  / abs(ni_prev)  * 100)
                          if (ni_last is not None and ni_prev)  else None)
    income_ctx = {
        "periods":              _periods(income),
        "revenue_latest":       _safe(rev_last),
        "revenue_prev":         _safe(rev_prev),
        "revenue_yoy_pct":      rev_yoy,
        "revenue_cagr_pct":     _cagr(rev),
        "gross_profit_latest":  _safe(gp_last),
        "gross_margin_pct":     gross_margin,
        "operating_income":     _safe(op_last),
        "operating_margin_pct": op_margin,
        "net_income_latest":    _safe(ni_last),
        "net_income_prev":      _safe(ni_prev),
        "net_margin_pct":       net_margin,
        "net_income_yoy_pct":   ni_yoy,
        "net_income_cagr_pct":  _cagr(ni),
    }
    ta   = _find_row(balance, "Total Assets")
    tl   = _find_row(balance, "Total Liabilities")
    ca   = _find_row(balance, "Total Current Assets", "Current Assets")
    cl   = _find_row(balance, "Total Current Liabilities", "Current Liabilities")
    debt = _find_row(balance, "Total Debt", "Long Term Debt")
    eq   = _find_row(balance, "Stockholders Equity", "Total Equity",
                     "Shareholders Equity")
    ta_v   = _last(ta);  tl_v = _last(tl)
    ca_v   = _last(ca);  cl_v = _last(cl)
    dbt_v  = _last(debt)
    eq_v   = _last(eq)
    curr_ratio = _safe((ca_v / cl_v) if (ca_v and cl_v and cl_v != 0) else None)
    de_ratio   = _safe((abs(dbt_v) / eq_v)
                        if (dbt_v and eq_v and eq_v > 0) else None)
    debt_to_assets = _safe((abs(dbt_v) / ta_v * 100)
                            if (dbt_v and ta_v and ta_v != 0) else None)
    balance_ctx = {
        "periods":                _periods(balance),
        "total_assets":           _safe(ta_v),
        "total_liabilities":      _safe(tl_v),
        "stockholders_equity":    _safe(eq_v),
        "current_assets":         _safe(ca_v),
        "current_liabilities":    _safe(cl_v),
        "total_debt":             _safe(dbt_v),
        "current_ratio":          curr_ratio,
        "debt_to_equity":         de_ratio,
        "debt_to_assets_pct":     debt_to_assets,
        "equity_cagr_pct":        _cagr(eq),
    }
    ocf  = _find_row(cash, "Operating Cash Flow", "Total Cash From Operating")
    capx = _find_row(cash, "Capital Expenditure", "Purchase Of")
    fcf  = _find_row(cash, "Free Cash Flow")
    ivcf = _find_row(cash, "Total Cash From Invest", "Investing Cash")
    ficf = _find_row(cash, "Total Cash From Financ", "Financing Cash")
    ocf_v  = _last(ocf)
    capx_v = _last(capx)
    fcf_v  = _last(fcf)
    ocf_ni_ratio = _safe((ocf_v / abs(ni_last))
                          if (ocf_v and ni_last and ni_last != 0) else None)
    if fcf_v is None and ocf_v is not None and capx_v is not None:
        fcf_v = ocf_v + capx_v                                           
    cash_ctx = {
        "periods":              _periods(cash),
        "operating_cash_flow":  _safe(ocf_v),
        "capital_expenditure":  _safe(capx_v),
        "free_cash_flow":       _safe(fcf_v),
        "investing_cash_flow":  _safe(_last(ivcf)),
        "financing_cash_flow":  _safe(_last(ficf)),
        "ocf_ni_quality_ratio": ocf_ni_ratio,
        "ocf_cagr_pct":         _cagr(ocf),
        "fcf_cagr_pct":         _cagr(fcf),
    }
    ansi_re = re.compile(r"\033\[[0-9;]*m")
    clean_flags: dict[str, list[str]] = {}
    for stmt_key, flag_list in flags.items():
        clean_flags[stmt_key] = [
            ansi_re.sub("", f).strip() for f in flag_list if f.strip()
        ]
    return {
        "ticker":             ticker,
        "income_statement":   income_ctx,
        "balance_sheet":      balance_ctx,
        "cash_flow":          cash_ctx,
        "red_flags":          clean_flags,
        "data_note": (
            "Key metrics extracted from annual statements. "
            "Row-level detail is available in the printed terminal table. "
            "All monetary values are in the currency reported by yfinance "
            "(raw units, not scaled)."
        ),
    }
def _build_m12_system_prompt(ctx: dict, model_name: str) -> str:
    ticker = ctx["ticker"]
    persona = textwrap.dedent(f"""\
        You are a senior Fundamental Analyst reviewing the annual financial
        statements for {ticker}. You have access to key extracted metrics
        from the Income Statement, Balance Sheet, and Cash Flow Statement.
        You are powered by {model_name}.
        Speak precisely — cite exact values, not vague generalities.
        Your audience ranges from beginners to experienced investors.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in the <terminal_data> below. Do not invent values.
        2. Cite metric names and values explicitly
           (e.g. "Net margin contracted from 18.2% to 11.4%").
        3. Cross-statement analysis is highest priority — connect income,
           balance sheet, and cash flow signals to find hidden risks or strengths.
        4. Lead with the single most important insight in one sentence.
        5. Surface ALL pre-computed red_flags and explain WHY each matters.
        6. Context-qualify ratios — note that "good" depends on industry.
        7. Keep responses under 450 words unless the user explicitly asks for more.
        8. If a metric is None/null in the data, say it wasn't captured rather
           than guessing.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Prefix every response: [ANALYSIS] | [RISK] | [ANSWER] | [RATIOS] | [INFO]
        - **Bold** all metric names and values.
        - Use > blockquotes for critical red-flag warnings.
        - Use Markdown tables when comparing metrics across periods or statements.
        - For ratio interpretation, use format: "X.Xx — [interpretation]"
    """)
    data_json  = json.dumps(ctx, indent=2)
    data_block = f"<terminal_data>\n{data_json}\n</terminal_data>"
    return "\n\n".join([persona, rules, fmt, data_block])
def _m12_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS  = 20
    turn_count = (len(history) - 1) // 2
    if turn_count > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 12 Financial Statements CoPilot",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    model_id,
        "messages": history,
        "stream":   True,
    }
    BACKOFF_BASE  = 1.5
    MAX_RETRIES   = 3
    full_response = ""
    last_error    = None
    for attempt in range(MAX_RETRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers,
                json=payload,
                stream=True,
                timeout=(10, 60),
            )
            if resp.status_code == 401:
                console.print(
                    "\n  [bold red][!] API key rejected (401). "
                    "Use /setkey to update.[/bold red]"
                )
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            token_count = 0
            print(f"\n  \033[90m{model_name} is thinking ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        token_count   += len(token.split())
                        if token_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({token_count} words)\033[0m\n")
            if full_response.strip():
                console.print(
                    Panel(
                        Markdown(full_response),
                        title=f"[bold cyan]{model_name}[/bold cyan]",
                        border_style="cyan",
                        padding=(1, 2),
                        expand=True,
                    )
                )
            return full_response                              
        except requests.Timeout:
            console.print(
                "\n  [bold red][!] Request timed out. "
                "Try a shorter question or /models to switch.[/bold red]"
            )
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < MAX_RETRIES - 1:
                wait = BACKOFF_BASE ** (attempt + 1)
                console.print(
                    f"  [yellow][~] Attempt {attempt + 1} failed ({exc}). "
                    f"Retrying in {wait:.1f}s…[/yellow]"
                )
                time.sleep(wait)
            else:
                console.print(
                    f"  [bold red][!] All {MAX_RETRIES} attempts failed: "
                    f"{last_error}[/bold red]"
                )
    return ""
def _print_m12_chat_help() -> None:
    print("\n  ── Module 12 Financial Statements Co-Pilot Commands ─")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by full OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter API"),
        ("/clear",       "Clear conversation (keep statements data)"),
        ("/export",      "Save session to a timestamped JSON file"),
        ("/status",      "Show model, key status, history length"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to the main terminal"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m12_chat(
    ticker:  str,
    income:  "pd.DataFrame",
    balance: "pd.DataFrame",
    cash:    "pd.DataFrame",
    flags:   dict,
) -> None:
    cfg = _m12_load_config()
    if not cfg["api_key"]:
        print("\n  \033[93m[!] No API key configured for Module 12 AI.\033[0m")
        cfg = _m12_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Run module again to configure.")
            return
    ctx = _build_statements_context(ticker, income, balance, cash, flags)
    history = [
        {
            "role":    "system",
            "content": _build_m12_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    print("\n" + "─" * 68)
    print(f"  \033[95m🧠 MODULE 12 FINANCIAL STATEMENTS CO-PILOT\033[0m  |  "
          f"\033[96m{cfg['model_name']}\033[0m  |  "
          f"\033[93m{ticker}\033[0m")
    print("  Ask about ratios, margins, red flags. Type /help for commands.")
    print("─" * 68)
    total_flags = sum(len(v) for v in flags.values())
    flag_note   = (f" There are {total_flags} pre-computed red flags — address all of them."
                   if total_flags else " No red flags were triggered.")
    first_prompt = (
        f"I've just downloaded and analysed the annual financial statements "
        f"for {ticker} covering all three: Income Statement, Balance Sheet, "
        f"and Cash Flow Statement.{flag_note} "
        f"Give me a comprehensive cross-statement analysis: "
        f"(1) the overall financial health verdict in one sentence, "
        f"(2) profitability trend — are margins expanding or contracting and why, "
        f"(3) balance sheet strength — liquidity, leverage, and equity trajectory, "
        f"(4) cash flow quality — does reported profit translate to real cash, "
        f"(5) the single most important risk and the single biggest strength "
        f"visible across all three statements together."
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m12_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        print("  \033[91m[!] Auto-analysis failed. "
              "You can still ask questions below.\033[0m\n")
    while True:
        try:
            from rich.console import Console
            _con       = Console()
            user_input = _con.input(
                "\n  [bold cyan]You ›[/bold cyan] "
            ).strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Co-Pilot session ended]")
            break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m12_chat_help()
            continue
        elif cmd == "/setkey":
            cfg = _m12_setup_key(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m12_system_prompt(ctx, cfg["model_name"]),
            }
            continue
        elif cmd == "/models":
            cfg = _m12_pick_model(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m12_system_prompt(ctx, cfg["model_name"]),
            }
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}")
                print("  Usage:   /model <openrouter-model-id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = (
                    arg.split("/")[-1]
                       .replace(":free", " (free)")
                       .replace("-", " ")
                       .title()
                )
                _m12_save_config(cfg)
                history[0] = {
                    "role":    "system",
                    "content": _build_m12_system_prompt(ctx, cfg["model_name"]),
                }
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get(
                    "http://127.0.0.1:9999/disabled", timeout=10
                )
                resp.raise_for_status()
                free = [
                    m for m in resp.json().get("data", [])
                    if m.get("id", "").endswith(":free")
                ]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    ctx_k = (m.get("context_length") or 0) // 1000
                    print(f"  {m['id']:<55} {ctx_k:>5}K")
                print(
                    f"\n  {len(free)} free models found. "
                    f"Activate with: /model <id>\n"
                )
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Statements data retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns    = (len(history) - 1) // 2
            key_hint = (
                f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}"
                if len(cfg["api_key"]) > 12 else "not set"
            )
            total_flags = sum(len(v) for v in flags.values())
            print(f"\n  Model      : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key    : {key_hint}")
            print(f"  Ticker     : {ticker}")
            print(f"  Red Flags  : {total_flags} total across all statements")
            print(f"  History    : {turns} turns (max 20 before auto-prune)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help.")
            continue
        history.append({"role": "user", "content": user_input})
        ai_response = _m12_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_response:
            history.append({"role": "assistant", "content": ai_response})
        else:
            history.pop()                                        
    print("  [Co-Pilot closed — returning to terminal]\n")
def run_financial_statements(ticker: str) -> None:
    GR  = '\033[92m'                                                   
    RD  = '\033[91m'                                                       
    BL  = '\033[94m'                                                     
    YL  = '\033[93m'                                        
    CY  = '\033[96m'                                         
    MG  = '\033[95m'                                         
    BD  = '\033[1m'          
    DIM = '\033[90m'                  
    RS  = '\033[0m'                                              
    FLOW_COLOR: dict[str, str] = {
        'inflow':  GR,
        'outflow': RD,
        'net':     YL,
        'neutral': BL,
    }
    print(f"\n  Downloading financials for {BD}{ticker}{RS} …\n")
    try:
        pass
    except ImportError:
        print(f"  {RD}[!] yfinance not installed.  Run: pip install yfinance{RS}")
        press_enter(); return
    try:
        stock = yf.Ticker(ticker)
    except Exception as exc:
        print(f"  {RD}[!] Could not create Ticker('{ticker}'): {exc}{RS}")
        press_enter(); return
    def _safe_fetch(attr: str) -> 'pd.DataFrame':
        try:
            raw = getattr(stock, attr)
            if raw is None or raw.empty:
                print(f"  {DIM}  ⚠ No data returned for '{attr}'.{RS}")
                return pd.DataFrame()
            df = (raw
                  .iloc[:, :4]                                    
                  .dropna(how='all')                                 
                  .iloc[:, ::-1])                                                
            df.columns = [str(c).split()[0] for c in df.columns]
            return df
        except Exception as exc:
            print(f"  {DIM}  ⚠ Could not fetch '{attr}': {exc}{RS}")
            return pd.DataFrame()
    income  = _safe_fetch('income_stmt')
    balance = _safe_fetch('balance_sheet')
    cash    = _safe_fetch('cash_flow')
    if all(df.empty for df in [income, balance, cash]):
        print(f"  {RD}[!] No financial data found for '{ticker}'.\n"
              f"      Check the ticker symbol and try again.{RS}")
        press_enter(); return
    MIN_LABEL_W = 28
    MAX_LABEL_W = 50
    COL_W       = 16
    def _compute_label_width(dataframes: list) -> int:
        max_seen = MIN_LABEL_W
        for df in dataframes:
            if df is not None and not df.empty:
                for name in df.index:
                    max_seen = max(max_seen, len(str(name)))
        return min(max_seen + 1, MAX_LABEL_W)
    LABEL_W: int = _compute_label_width([income, balance, cash])
    _INFLOW_KEYS: frozenset[str] = frozenset({
        'revenue', 'gross profit', 'operating income', 'ebit',
        'net revenue', 'total revenue', 'operating revenue',
        'interest income', 'other income', 'non operating income',
        'investment income', 'net interest income',
        'total assets', 'current assets', 'cash and cash',
        'receivable', 'inventory', 'prepaid',
        'operating cash flow', 'total cash from operating',
        'proceeds', 'sale of investment', 'issuance',
    })
    _OUTFLOW_KEYS: frozenset[str] = frozenset({
        'cost of', 'expense', 'income tax', 'tax provision',
        'interest expense', 'depreciation', 'amortization',
        'selling general', 'research', 'operating expense', 'impairment',
        'total liabilities', 'current liabilities', 'accounts payable',
        'long term debt', 'short term debt', 'total debt', 'payable',
        'capital expenditure', 'purchase of', 'repayment', 'dividend paid',
        'investing cash', 'financing cash',
        'total cash from invest', 'total cash from financ',
    })
    _NET_KEYS: frozenset[str] = frozenset({
        'net income', 'comprehensive income', 'earnings per share',
        'diluted eps', 'basic eps',
        'free cash flow', 'changes in cash', 'net change in cash',
        'net cash', 'net operating',
        'retained earnings', 'total equity', 'stockholders equity',
        'shareholders equity',
        'ebitda',
    })
    from functools import lru_cache
    @lru_cache(maxsize=256)
    def classify(label: str) -> str:
        ll = label.lower()
        if any(k in ll for k in _NET_KEYS):     return 'net'
        if any(k in ll for k in _INFLOW_KEYS):  return 'inflow'
        if any(k in ll for k in _OUTFLOW_KEYS): return 'outflow'
        return 'neutral'
    def flow_arrow(ftype: str, value: float) -> str:
        if ftype == 'net':
            return f"{GR}↑{RS}" if value >= 0 else f"{RD}↓{RS}"
        return {
            'inflow':  f"{GR}↑{RS}",
            'outflow': f"{RD}↓{RS}",
            'neutral': f"{BL}·{RS}",
        }.get(ftype, ' ')
    def trunc_word(label: str, width: int = LABEL_W) -> str:
        if len(label) <= width:
            return label.ljust(width)
        last_space = label.rfind(' ', 0, width - 1)
        if last_space > 0:
            kept = label[:last_space].rstrip()
        else:
            kept = label[:width - 1]
        padding = width - 1 - len(kept)
        result  = kept + ' ' * padding + '…'
        assert len(result) == width, (
            f"trunc_word invariant violated: len={len(result)}, "
            f"expected={width}, label={label!r}"
        )
        return result
    def fmt_num(value: float, col_w: int = COL_W) -> str:
        abs_v = abs(value)
        sign  = '-' if value < 0 else ''
        def _try(formatted: str) -> str | None:
            full = sign + formatted
            return full.rjust(col_w) if len(full) <= col_w else None
        r = _try(f"{abs_v:,.0f}")
        if r:
            return r
        if abs_v >= 1e9:
            for fmt_str in (f"{abs_v / 1e9:,.2f}B",                     
                            f"{abs_v / 1e9:,.1f}B",                    
                            f"{abs_v / 1e9:,.0f}B"):                 
                r = _try(fmt_str)
                if r:
                    return r
        if abs_v >= 1e6:
            for fmt_str in (f"{abs_v / 1e6:,.1f}M",                     
                            f"{abs_v / 1e6:,.0f}M"):                  
                r = _try(fmt_str)
                if r:
                    return r
        if abs_v >= 1e3:
            r = _try(f"{abs_v / 1e3:,.0f}K")
            if r:
                return r
        return f"{value:.3e}".rjust(col_w)
    def fmt_yoy(prev: float, curr: float) -> str:
        if prev == 0:
            return f"{DIM}  N/M {RS}"
        if (prev < 0 < curr) or (prev > 0 > curr):
            return f"{DIM}  N/M {RS}"
        pct = (curr - prev) / abs(prev) * 100
        if abs(pct) > 999:
            arrow = f"{GR}▲{RS}" if pct > 0 else f"{RD}▼{RS}"
            return f"{arrow}{DIM}>999%{RS}"
        color = CY if pct >= 0 else MG
        sign  = '+' if pct >= 0 else ''
        return f"{color}{sign}{pct:.1f}%{RS}"
    def _border(left: str, lbl_fill: str, junc: str,
                num_fill: str, right: str, n_cols: int) -> str:
        lseg = lbl_fill * (LABEL_W + 2)
        nseg = (junc + num_fill * (COL_W + 2)) * n_cols
        return f"  {left}{lseg}{nseg}{right}"
    def make_top(n_cols: int)       -> str: return _border('┌','─','┬','─','┐', n_cols)
    def make_mid(n_cols: int)       -> str: return _border('├','─','┼','─','┤', n_cols)
    def make_bot(n_cols: int)       -> str: return _border('└','─','┴','─','┘', n_cols)
    def make_heavy_div(n_cols: int) -> str: return _border('╞','═','╪','═','╡', n_cols)
    def make_header_row(cols: list[str]) -> str:
        lbl_cell  = f" {BD}{YL}{'Metric'.ljust(LABEL_W)}{RS} "
        num_cells = ''.join(f"│ {BD}{YL}{c.rjust(COL_W)}{RS} " for c in cols)
        return f"  │{lbl_cell}{num_cells}│"
    def make_data_row(label: str, values: list, ftype: str) -> str:
        col  = FLOW_COLOR.get(ftype, RS)
        bold = BD if ftype == 'net' else ''
        first_val = 0.0
        for v in values:
            if v is not None and not (isinstance(v, float) and pd.isna(v)):
                try:
                    first_val = float(v)
                    break
                except (TypeError, ValueError):
                    pass
        arrow = flow_arrow(ftype, first_val)
        t_label    = trunc_word(label)                                           
        label_cell = f" {arrow}{bold}{col}{t_label}{RS} "
        num_cells = ""
        for v in values:
            if v is None or (isinstance(v, float) and pd.isna(v)):
                num_cells += f"│ {DIM}{'—'.rjust(COL_W)}{RS} "
            else:
                try:
                    fv = float(v)
                    num_str    = fmt_num(fv)
                    num_cells += f"│ {bold}{col}{num_str}{RS} "
                except (TypeError, ValueError):
                    display = str(v)[-COL_W:].rjust(COL_W)
                    num_cells += f"│ {display} "
        return f"  │{label_cell}{num_cells}│"
    def scan_flags(df: 'pd.DataFrame', stype: str) -> list[str]:
        flags: list[str] = []
        cols  = df.columns.tolist()
        if len(cols) < 2:
            return flags                                            
        def _find_row(*keys: str) -> 'pd.Series | None':
            for key in keys:
                for iname in df.index:
                    if key.lower() in str(iname).lower():
                        return df.loc[iname]
            return None
        if stype == 'income':
            rev = _find_row('Total Revenue', 'Operating Revenue', 'Revenue')
            ni  = _find_row('Net Income')
            if rev is not None and ni is not None:
                try:
                    r_last = float(rev.iloc[-1]);  r_prev = float(rev.iloc[-2])
                    n_last = float(ni.iloc[-1]);   n_prev = float(ni.iloc[-2])
                    if r_last != 0 and r_prev != 0:
                        ml = n_last / r_last
                        mp = n_prev / r_prev
                        if ml < mp * 0.70:
                            flags.append(
                                f"  {RD}⚠  Net margin contracted: "
                                f"{mp*100:.1f}% → {ml*100:.1f}% "
                                f"(−{(mp-ml)*100:.1f}pp){RS}"
                            )
                        if ml < 0:
                            flags.append(
                                f"  {RD}⚠  NEGATIVE net margin — "
                                f"loss-making latest period{RS}"
                            )
                    if r_prev > 0 and r_last < r_prev:
                        pct_chg = (r_last - r_prev) / r_prev * 100
                        flags.append(
                            f"  {YL}⚠  Revenue declined {pct_chg:.1f}% YoY "
                            f"— investigate demand, pricing, or mix{RS}"
                        )
                except Exception:
                    pass                                  
        elif stype == 'balance':
            ca   = _find_row('Total Current Assets', 'Current Assets')
            cl   = _find_row('Total Current Liabilities', 'Current Liabilities')
            debt = _find_row('Total Debt', 'Long Term Debt')
            eq   = _find_row('Stockholders Equity', 'Total Equity',
                             'Shareholders Equity')
            if ca is not None and cl is not None:
                try:
                    cr = float(ca.iloc[-1]) / float(cl.iloc[-1])
                    if cr < 1.0:
                        flags.append(
                            f"  {RD}⚠  Current Ratio {cr:.2f}× < 1.0 — "
                            f"current liabilities exceed assets "
                            f"(liquidity risk){RS}"
                        )
                    elif cr < 1.5:
                        flags.append(
                            f"  {YL}⚠  Current Ratio {cr:.2f}× — "
                            f"below 1.5× comfort zone (advisory){RS}"
                        )
                except Exception:
                    pass
            if debt is not None and eq is not None:
                try:
                    eq_val  = float(eq.iloc[-1])
                    dbt_val = abs(float(debt.iloc[-1]))
                    if eq_val < 0:
                        flags.append(
                            f"  {RD}⚠  NEGATIVE stockholders' equity — "
                            f"total liabilities exceed total assets{RS}"
                        )
                    elif eq_val > 0:
                        de = dbt_val / eq_val
                        if de > 3.0:
                            flags.append(
                                f"  {RD}⚠  Debt/Equity {de:.1f}× > 3× — "
                                f"high leverage; rising default risk{RS}"
                            )
                        elif de > 2.0:
                            flags.append(
                                f"  {YL}⚠  Debt/Equity {de:.1f}× > 2× — "
                                f"moderately elevated leverage (advisory){RS}"
                            )
                except Exception:
                    pass
        elif stype == 'cash':
            ocf = _find_row('Operating Cash Flow', 'Total Cash From Operating')
            ni  = _find_row('Net Income')
            fcf = _find_row('Free Cash Flow')
            if ocf is not None and ni is not None:
                try:
                    ocf_v = float(ocf.iloc[-1])
                    ni_v  = float(ni.iloc[-1])
                    if ni_v > 0 and ocf_v < 0:
                        flags.append(
                            f"  {RD}⚠  Positive Net Income but NEGATIVE OCF — "
                            f"earnings quality concern; check receivables{RS}"
                        )
                    if abs(ni_v) > 1e-9:
                        ratio = ocf_v / abs(ni_v)
                        if 0 < ratio < 0.5:
                            flags.append(
                                f"  {YL}⚠  OCF/NI = {ratio:.2f} — "
                                f"accrual-heavy; net income outpaces cash{RS}"
                            )
                except Exception:
                    pass
            if fcf is not None:
                try:
                    fcf_v = float(fcf.iloc[-1])
                    if fcf_v < 0:
                        flags.append(
                            f"  {YL}⚠  Negative Free Cash Flow "
                            f"({fmt_num(fcf_v).strip()}) — "
                            f"investing > earning (check if growth-phase){RS}"
                        )
                except Exception:
                    pass
        return flags
    print(f"\n  {BD}COLOUR GUIDE:{RS}  "
          f"{GR}■ Green = Inflow{RS}   "
          f"{RD}■ Red = Outflow{RS}   "
          f"{BL}■ Blue = Neutral/Equity{RS}   "
          f"{YL}■ Yellow = Net/Summary{RS}\n")
    GUIDES: dict[str, list[str]] = {
        'income': [
            f"  {BD}HOW TO READ — INCOME STATEMENT{RS}",
            f"  {GR}↑ Revenue{RS}          Top line — total inflows from operations.",
            f"  {RD}↓ COGS / Expenses{RS}  Subtracted from revenue to reach profit.",
            f"  {YL}● Net Income{RS}        Bottom line — profit after all deductions.",
            f"  {DIM}  Key ratio : Gross Margin = (Revenue − COGS) / Revenue",
            f"  Tip       : Rising gross margin → stronger pricing power.",
            f"  Red flag  : Revenue up + Net Income down → cost structure problem.",
            f"  Red flag  : Negative net income 2+ periods → structural loss.{RS}",
        ],
        'balance': [
            f"  {BD}HOW TO READ — BALANCE SHEET{RS}",
            f"  {GR}↑ Assets{RS}           Everything the company owns or is owed.",
            f"  {RD}↓ Liabilities{RS}      Everything owed to creditors.",
            f"  {BL}· Equity{RS}           Residual owner value (Assets − Liabilities).",
            f"  {DIM}  Identity  : Assets = Liabilities + Equity (always balances).",
            f"  Key ratio : Current Ratio = Current Assets / Current Liabilities.",
            f"  Red flag  : Current Ratio < 1.0 → near-term liquidity risk.",
            f"  Red flag  : Debt/Equity > 3× → heavily leveraged balance sheet.{RS}",
        ],
        'cash': [
            f"  {BD}HOW TO READ — CASH FLOW STATEMENT{RS}",
            f"  {GR}↑ Operating CF{RS}     Cash generated by day-to-day business.",
            f"  {RD}↓ Investing CF{RS}     Cash spent on assets (−ve = reinvestment).",
            f"  {BL}· Financing CF{RS}     Cash from/to debt and equity holders.",
            f"  {YL}● FCF = OCF − CapEx{RS} Most important single cash-flow metric.",
            f"  {DIM}  Tip      : OCF > Net Income → high-quality cash-backed earnings.",
            f"  Red flag : Negative OCF consistently → business burns real cash.{RS}",
        ],
    }
    def print_statement(df: 'pd.DataFrame', title: str, stype: str) -> None:
        if df.empty:
            print(f"\n  {DIM}  [{title}] — no data available for {ticker}.{RS}\n")
            return
        cols   = df.columns.tolist()
        n_cols = len(cols)
        TOP = make_top(n_cols)
        MID = make_mid(n_cols)
        BOT = make_bot(n_cols)
        HDV = make_heavy_div(n_cols)
        inner_w = (LABEL_W + 3) + n_cols * (COL_W + 3)
        print(f"\n  {BD}{YL}{'═' * inner_w}{RS}")
        print(f"  {BD}{YL}  {title}  —  {ticker}{RS}")
        print(f"  {BD}{YL}{'═' * inner_w}{RS}")
        print(TOP)
        print(make_header_row(cols))
        print(MID)
        prev_ftype: str | None = None
        for idx_name in df.index:
            ftype  = classify(str(idx_name))
            values = [df.loc[idx_name, c] for c in cols]
            if prev_ftype is not None and ftype != prev_ftype:
                if 'net' in (ftype, prev_ftype):
                    print(HDV)
                else:
                    print(MID)
            prev_ftype = ftype
            print(make_data_row(str(idx_name), values, ftype))
        print(BOT)
        NET_CANDIDATES: dict[str, list[str]] = {
            'income':  ['Net Income', 'Net Income Common Stockholders'],
            'balance': ['Total Assets', 'Stockholders Equity', 'Total Equity'],
            'cash':    ['Free Cash Flow', 'Changes In Cash',
                        'Operating Cash Flow'],
        }
        for key in NET_CANDIDATES.get(stype, []):
            for idx_name in df.index:
                if key.lower() in str(idx_name).lower():
                    vals = df.loc[idx_name]
                    try:
                        latest = float(vals.iloc[-1])
                        sc     = GR if latest >= 0 else RD
                        ar     = "↑" if latest >= 0 else "↓"
                        cagr_str = ''
                        valid_vals = []
                        for x in vals:
                            try:
                                fv = float(x)
                                if not pd.isna(fv):
                                    valid_vals.append(fv)
                            except (TypeError, ValueError):
                                pass
                        if (len(valid_vals) >= 2
                                and valid_vals[0] > 0
                                and valid_vals[-1] > 0):
                            n_periods  = len(valid_vals) - 1
                            cagr       = (valid_vals[-1] / valid_vals[0]) ** (1 / n_periods) - 1
                            cagr_col   = GR if cagr >= 0 else RD
                            cagr_str   = (f"   {DIM}│{RS}  "
                                          f"CAGR {cagr_col}{cagr*100:+.1f}%{RS}"
                                          f"{DIM}/yr "
                                          f"over {n_periods} period(s){RS}")
                        print(f"\n  {BD}{YL}  NET SUMMARY  →  "
                              f"{idx_name}: {sc}{ar} "
                              f"{fmt_num(latest).strip()}{RS}{cagr_str}")
                    except Exception:
                        pass
                    break                                  
        flags = scan_flags(df, stype)
        if flags:
            print(f"\n  {BD}{RD}  RED FLAGS:{RS}")
            for flag_line in flags:
                print(flag_line)
        print()
        for line in GUIDES[stype]:
            print(line)
        print()
    print("  Select view:")
    print("  [1] All Three Statements")
    print("  [2] Income Statement Only")
    print("  [3] Balance Sheet Only")
    print("  [4] Cash Flow Statement Only")
    sel = input("  Choice [1]: ").strip() or "1"
    SEL_MAP: dict[str, list[str]] = {
        '1': ['income', 'balance', 'cash'],
        '2': ['income'],
        '3': ['balance'],
        '4': ['cash'],
    }
    show_keys = SEL_MAP.get(sel, ['income', 'balance', 'cash'])
    STMTS: dict[str, tuple] = {
        'income':  (income,  'INCOME STATEMENT'),
        'balance': (balance, 'BALANCE SHEET'),
        'cash':    (cash,    'CASH FLOW STATEMENT'),
    }
    for key in show_keys:
        df, title = STMTS[key]
        print_statement(df, title, key)
    exp = input(
        f"\n  {BD}Export colour-coded Excel workbook? [Y/N]:{RS} "
    ).strip().upper()
    if exp == 'Y':
        _export_statements_excel(ticker, income, balance, cash, GUIDES)
    all_flags: dict = {}
    for key in show_keys:
        df, _ = STMTS[key]
        if not df.empty:
            all_flags[key] = scan_flags(df, key)
    print(f"\n  {'─' * 54}")
    try:
        launch = input(
            "  Open AI Co-Pilot to analyse these statements? [Y/n]: "
        ).strip().lower()
    except (EOFError, KeyboardInterrupt):
        launch = "n"
    if launch not in {"n", "no"}:
        run_m12_chat(
            ticker  = ticker,
            income  = income,
            balance = balance,
            cash    = cash,
            flags   = all_flags,
        )
    else:
        press_enter()
def _export_statements_excel(ticker: str,
                              income:  'pd.DataFrame',
                              balance: 'pd.DataFrame',
                              cash:    'pd.DataFrame',
                              guides:  dict) -> None:
    try:
        import openpyxl
        from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
    except ImportError:
        print("  \033[91m[!] openpyxl not installed.  Run: pip install openpyxl\033[0m")
        return
    FILL: dict[str, 'PatternFill'] = {
        'inflow':  PatternFill('solid', fgColor='C6EFCE'),               
        'outflow': PatternFill('solid', fgColor='FFC7CE'),                  
        'neutral': PatternFill('solid', fgColor='DCE6F1'),              
        'net':     PatternFill('solid', fgColor='FFEB9C'),                
        'header':  PatternFill('solid', fgColor='1F3864'),             
        'guide':   PatternFill('solid', fgColor='F2F2F2'),              
    }
    HDR_FONT  = Font(color='FFFFFF', bold=True, size=11)                         
    BOLD_FONT = Font(bold=True, size=10)
    NORM_FONT = Font(size=10)
    _thin  = Side(style='thin', color='AAAAAA')
    BORDER = Border(top=_thin, bottom=_thin, left=_thin, right=_thin)
    _IL = {'revenue','gross profit','operating income','ebit','interest income',
           'other income','total assets','current assets','cash and cash',
           'receivable','inventory','operating cash flow',
           'total cash from operating','proceeds','sale of investment','issuance',
           'net revenue','total revenue','operating revenue','net interest income'}
    _OL = {'cost of','expense','tax','interest expense','depreciation',
           'amortization','selling general','research','total liabilities',
           'current liabilities','long term debt','debt','payable',
           'capital expenditure','purchase of','repayment','dividend',
           'investing cash','financing cash','total cash from invest',
           'total cash from financ','impairment'}
    _NL = {'net income','free cash flow','retained earnings','total equity',
           'stockholders equity','shareholders equity','ebitda',
           'changes in cash','net change in cash','net cash','net operating',
           'comprehensive income','diluted eps','basic eps'}
    def _classify_xl(label: str) -> str:
        ll = label.lower()
        if any(k in ll for k in _NL): return 'net'
        if any(k in ll for k in _IL): return 'inflow'
        if any(k in ll for k in _OL): return 'outflow'
        return 'neutral'
    def _flow_label(ftype: str) -> str:
        return {'inflow': '↑ Inflow', 'outflow': '↓ Outflow',
                'net': '● Net',       'neutral': '· Neutral'}.get(ftype, '')
    wb = openpyxl.Workbook()
    wb.remove(wb.active)                               
    def _write_stmt_sheet(df: 'pd.DataFrame', sheet_name: str) -> None:
        if df.empty:
            return
        ws   = wb.create_sheet(title=sheet_name)
        cols = df.columns.tolist()
        hdrs = ['Line Item', 'Flow Type'] + [str(c) for c in cols]
        for j, h in enumerate(hdrs, 1):
            cell = ws.cell(row=1, column=j, value=h)
            cell.fill      = FILL['header']
            cell.font      = HDR_FONT
            cell.alignment = Alignment(horizontal='center', vertical='center')
            cell.border    = BORDER
        for r, idx_name in enumerate(df.index, 2):
            ftype = _classify_xl(str(idx_name))
            fill  = FILL[ftype]
            is_net = (ftype == 'net')
            c1 = ws.cell(row=r, column=1, value=str(idx_name))
            c1.fill      = fill
            c1.font      = BOLD_FONT if is_net else NORM_FONT
            c1.border    = BORDER
            c1.alignment = Alignment(wrap_text=True, vertical='top')
            c2 = ws.cell(row=r, column=2, value=_flow_label(ftype))
            c2.fill      = fill
            c2.font      = NORM_FONT
            c2.border    = BORDER
            c2.alignment = Alignment(horizontal='center')
            for j, col_name in enumerate(cols, 3):
                v = df.loc[idx_name, col_name]
                try:
                    val = None if pd.isna(v) else float(v)
                except (TypeError, ValueError):
                    val = str(v) if (v is not None and
                                     not (isinstance(v, float) and pd.isna(v))
                                     ) else None
                cell = ws.cell(row=r, column=j, value=val)
                cell.fill      = fill
                cell.font      = BOLD_FONT if is_net else NORM_FONT
                cell.border    = BORDER
                cell.alignment = Alignment(horizontal='right')
                if isinstance(val, float):
                    cell.number_format = '#,##0.00'
        ws.column_dimensions['A'].width = 44
        ws.column_dimensions['B'].width = 14
        for j in range(3, len(cols) + 3):
            ws.column_dimensions[get_column_letter(j)].width = 18
        ws.freeze_panes = 'C2'                                                  
    _write_stmt_sheet(income,  'Income Statement')
    _write_stmt_sheet(balance, 'Balance Sheet')
    _write_stmt_sheet(cash,    'Cash Flow')
    ws_piv = wb.create_sheet(title='Pivot (Tidy)')
    phdr   = ['Ticker', 'Statement', 'Date', 'Category', 'Amount', 'Flow_Type']
    for j, h in enumerate(phdr, 1):
        cell = ws_piv.cell(row=1, column=j, value=h)
        cell.fill      = FILL['header']
        cell.font      = HDR_FONT
        cell.border    = BORDER
        cell.alignment = Alignment(horizontal='center')
    pr = 2                               
    for sname, df in [('Income Statement', income),
                       ('Balance Sheet',   balance),
                       ('Cash Flow',        cash)]:
        if df.empty:
            continue
        for dcol in df.columns:
            for iname in df.index:
                v = df.loc[iname, dcol]
                try:
                    amt = float(v)
                    if pd.isna(amt):
                        continue
                except (TypeError, ValueError):
                    continue
                ftype = _classify_xl(str(iname))
                row_vals = [ticker, sname, str(dcol),
                            str(iname), amt, _flow_label(ftype)]
                for j, val in enumerate(row_vals, 1):
                    cell = ws_piv.cell(row=pr, column=j, value=val)
                    cell.font   = NORM_FONT
                    cell.border = BORDER
                    if j == 5:                  
                        cell.number_format = '#,##0.00'
                        cell.fill = FILL[ftype]
                        cell.alignment = Alignment(horizontal='right')
                pr += 1
    for j, w in enumerate([10, 22, 12, 44, 18, 14], 1):
        ws_piv.column_dimensions[get_column_letter(j)].width = w
    ws_piv.freeze_panes = 'A2'
    ws_g = wb.create_sheet(title='Reading Guides')
    ws_g.column_dimensions['A'].width = 100
    ansi_re = re.compile(r'\033\[[0-9;]*m')                                    
    guide_rows: list[tuple[str, str]] = [
        ('COLOUR GUIDE', 'header'),
        ('■ Green  (C6EFCE) = Inflow  : Revenue, Assets, Operating Cash Flow', 'inflow'),
        ('■ Red    (FFC7CE) = Outflow : Expenses, Liabilities, CapEx, Debt',   'outflow'),
        ('■ Blue   (DCE6F1) = Neutral : Equity components, non-cash items',     'neutral'),
        ('■ Yellow (FFEB9C) = Net     : Net Income, Free Cash Flow, Totals',    'net'),
        ('', 'guide'),
        ('INCOME STATEMENT', 'header'),
        ('Revenue (top) = Total inflows from business operations',              'inflow'),
        ('COGS + Expenses = Deductions from revenue (outflows)',                'outflow'),
        ('Net Income (bottom) = Profit after all outflows',                     'net'),
        ('Key ratio: Gross Margin = (Revenue − COGS) / Revenue',               'guide'),
        ('Tip: Rising gross margin signals stronger pricing power',             'guide'),
        ('Red Flag: Revenue growing but net income shrinking = cost problem',   'guide'),
        ('Red Flag: Negative net income 2+ periods = structural losses',        'guide'),
        ('', 'guide'),
        ('BALANCE SHEET', 'header'),
        ('Assets = Everything the company owns or is owed',                     'inflow'),
        ('Liabilities = Everything owed to creditors',                          'outflow'),
        ('Equity = Residual value for shareholders (Assets − Liabilities)',     'neutral'),
        ('Identity: Assets = Liabilities + Equity (always)',                    'guide'),
        ('Red Flag: Current Ratio < 1.0 = liquidity risk',                     'guide'),
        ('Red Flag: Debt/Equity > 3× = heavily leveraged balance sheet',        'guide'),
        ('', 'guide'),
        ('CASH FLOW STATEMENT', 'header'),
        ('Operating CF = Cash from day-to-day business (positive is ideal)',    'inflow'),
        ('Investing CF = Cash on assets (negative = reinvestment)',              'outflow'),
        ('Financing CF = Cash from/to debt and equity holders',                 'neutral'),
        ('FCF = OCF − CapEx (most important valuation input)',                  'net'),
        ('Tip: OCF > Net Income = high-quality cash-backed earnings',           'guide'),
        ('Red Flag: Negative OCF consistently = business burns cash',           'guide'),
    ]
    for r, (text, ftype) in enumerate(guide_rows, 1):
        cell = ws_g.cell(row=r, column=1, value=ansi_re.sub('', text))
        cell.alignment = Alignment(wrap_text=True, vertical='top')
        cell.border    = BORDER
        if ftype == 'header':
            cell.fill = FILL['header']
            cell.font = HDR_FONT
        else:
            cell.fill = FILL.get(ftype, FILL['guide'])
            cell.font = Font(size=10, bold=(ftype == 'net'))
    reports_dir = r"reports"
    os.makedirs(reports_dir, exist_ok=True)
    safe_ticker = ticker.replace('.', '_').replace('/', '_')
    fpath       = os.path.join(reports_dir, f"{safe_ticker}_Financial_Statements.xlsx")
    try:
        wb.save(fpath)
        print(f"\n  \033[92m✔ Saved: {fpath}\033[0m")
        print(f"  \033[90m  Sheets: Income Statement | Balance Sheet | "
              f"Cash Flow | Pivot (Tidy) | Reading Guides\033[0m")
    except PermissionError:
        print(f"\n  \033[91m[!] File is open in Excel — close it and retry.\033[0m")
    except OSError as exc:
        print(f"\n  \033[91m[!] OS error saving workbook: {exc}\033[0m")
    except Exception as exc:
        print(f"\n  \033[91m[!] Unexpected save failure: {exc}\033[0m")
import random
