import subprocess
from typing import List, Optional, Tuple
log = logging.getLogger(__name__)
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    datefmt="%H:%M:%S",
)
class DependencyError(RuntimeError):
    pass
class DataFetchError(RuntimeError):
    pass
class InsufficientDataError(ValueError):
    pass
class BacktestError(RuntimeError):
    pass
@dataclass(frozen=True)                                                         
class BacktestConfig:
    ticker          : str   = "RELIANCE.NS"
    initial_deposit : float = 100_000.0
    fast_ma         : int   = 20
    slow_ma         : int   = 50
    rsi_period      : int   = 14
    rsi_overbought  : float = 70.0
    rsi_oversold    : float = 30.0
    period          : str   = "2y"
    use_rsi_filter  : bool  = True
    def __post_init__(self) -> None:
        if self.fast_ma >= self.slow_ma:
            raise ValueError(
                f"fast_ma ({self.fast_ma}) must be strictly less than "
                f"slow_ma ({self.slow_ma}).  A crossover strategy requires two "
                f"distinct windows to generate signal transitions."
            )
        if self.initial_deposit <= 0:
            raise ValueError("initial_deposit must be a positive number.")
        if not self.ticker.strip():
            raise ValueError("ticker cannot be an empty string.")
        if not (0 < self.rsi_period < 200):
            raise ValueError("rsi_period must be between 1 and 199.")
        if not (0 < self.rsi_oversold < self.rsi_overbought < 100):
            raise ValueError(
                "RSI thresholds must satisfy: 0 < rsi_oversold < rsi_overbought < 100"
            )
        log.debug("BacktestConfig validated: %s", self)
@dataclass(frozen=True)
class TradeRecord:
    entry_date  : str
    exit_date   : str
    entry_price : float
    exit_price  : float
    shares      : float
    pnl         : float
    hold_bars   : int
    @property
    def is_winner(self) -> bool:
        return self.pnl > 0
    @property
    def return_pct(self) -> float:
        return ((self.exit_price - self.entry_price) / self.entry_price) * 100
@dataclass
class BacktestMetrics:
    bars              : int   = 0
    initial_deposit   : float = 0.0
    total_net_profit  : float = 0.0
    gross_profit      : float = 0.0
    gross_loss        : float = 0.0
    profit_factor     : float = 0.0                                                   
    expected_payoff   : float = 0.0                                                
    return_pct        : float = 0.0                                   
    abs_drawdown      : float = 0.0                                                 
    max_drawdown      : float = 0.0                                    
    max_drawdown_pct  : float = 0.0                                            
    max_dd_duration   : int   = 0                                      
    sharpe_ratio      : float = 0.0
    sortino_ratio     : float = 0.0
    calmar_ratio      : float = 0.0
    recovery_factor   : float = 0.0
    total_trades      : int   = 0
    win_trades        : int   = 0
    loss_trades       : int   = 0
    win_pct           : float = 0.0
    loss_pct          : float = 0.0
    largest_profit    : float = 0.0
    largest_loss      : float = 0.0
    avg_profit        : float = 0.0
    avg_loss          : float = 0.0
    avg_hold_bars     : float = 0.0                                     
    max_cons_wins     : int   = 0
    max_cons_losses   : int   = 0
    oracle_signal     : str   = "N/A"
    oracle_score      : int   = 0                             
    oracle_reason     : str   = ""
    last_price        : float = 0.0
    last_rsi          : float = 0.0
class DataFetcher:
    def __init__(self, cfg: BacktestConfig) -> None:
        self.cfg = cfg
    def fetch(self):                   
        log.info("Fetching %s for period=%s …", self.cfg.ticker, self.cfg.period)
        try:
            raw = yf.download(
                self.cfg.ticker,
                period=self.cfg.period,
                progress=False,
                auto_adjust=True,                                              
            )
        except Exception as exc:
            raise DataFetchError(
                f"yfinance.download raised an exception: {exc}"
            ) from exc
        if raw is None or raw.empty:
            raise DataFetchError(
                f"No data returned for ticker '{self.cfg.ticker}'. "
                "Check the symbol spelling and that markets were open during "
                "the requested period."
            )
        df = self._normalise_columns(raw)
        df = self._clean(df)
        self._validate_length(df)
        log.info("Fetched %d bars for %s.", len(df), self.cfg.ticker)
        return df
    def _normalise_columns(self, raw):                  
        if isinstance(raw.columns, pd.MultiIndex):
            ticker = self.cfg.ticker
            lvl1_values = raw.columns.get_level_values(1).unique().tolist()
            if ticker in lvl1_values:
                df = raw.xs(ticker, level=1, axis=1)
            else:
                log.warning(
                    "Ticker '%s' not found in MultiIndex level-1 values %s. "
                    "Dropping level-1 blindly.",
                    ticker, lvl1_values,
                )
                df = raw.droplevel(1, axis=1)
        else:
            df = raw.copy()
        return df
    def _clean(self, df):                  
        df = df.copy()
        df.sort_index(inplace=True)                                             
        df['Close'] = df['Close'].ffill()                              
        df.dropna(subset=['Close'], inplace=True)                          
        invalid = df['Close'] <= 0
        if invalid.any():
            log.warning("Removed %d rows with Close ≤ 0.", invalid.sum())
            df = df[~invalid]
        return df
    def _validate_length(self, df) -> None:
        min_required = self.cfg.slow_ma + 1                                        
        if len(df) < min_required:
            raise InsufficientDataError(
                f"Only {len(df)} bars available but slow_ma={self.cfg.slow_ma} "
                f"requires at least {min_required} bars.  Increase the period "
                f"(e.g., '5y') or decrease slow_ma."
            )
class StrategyEngine:
    def __init__(self, cfg: BacktestConfig) -> None:
        self.cfg = cfg
    def build_indicators(self, df):                                    
        df = df.copy()
        closes = df['Close']
        df['Fast_SMA'] = closes.rolling(window=self.cfg.fast_ma).mean()
        df['Slow_SMA'] = closes.rolling(window=self.cfg.slow_ma).mean()
        delta = closes.diff()                                            
        gain  = delta.clip(lower=0)                                             
        loss  = (-delta).clip(lower=0)                                                        
        avg_gain = gain.ewm(com=self.cfg.rsi_period - 1, adjust=False).mean()
        avg_loss = loss.ewm(com=self.cfg.rsi_period - 1, adjust=False).mean()
        rs = avg_gain / avg_loss.replace(0, float('nan'))
        df['RSI'] = 100 - (100 / (1 + rs))
        df['RSI'].fillna(100, inplace=True)                               
        df.dropna(subset=['Fast_SMA', 'Slow_SMA', 'RSI'], inplace=True)
        log.debug("Indicators built. Usable rows after dropna: %d", len(df))
        return df
    def simulate(
        self,
        df,
        initial_deposit: float,
    ) -> Tuple[List[TradeRecord], List[float]]:
        closes    = df['Close'].to_numpy(dtype=float)
        fast_sma  = df['Fast_SMA'].to_numpy(dtype=float)
        slow_sma  = df['Slow_SMA'].to_numpy(dtype=float)
        rsi_vals  = df['RSI'].to_numpy(dtype=float)
        dates     = df.index.strftime('%Y-%m-%d').tolist()                   
        n         = len(closes)
        equity      : float = initial_deposit
        position    : float = 0.0                                  
        entry_price : float = 0.0
        entry_date  : str   = ""
        entry_bar   : int   = 0
        trades       : List[TradeRecord] = []
        equity_curve : List[float]       = [equity]                        
        for i in range(1, n):
            price = closes[i]
            if math.isnan(price) or price <= 0:
                equity_curve.append(
                    equity if position == 0.0
                    else equity + position * (closes[i - 1] - entry_price)
                )
                continue
            prev_fast, curr_fast = fast_sma[i - 1], fast_sma[i]
            prev_slow, curr_slow = slow_sma[i - 1], slow_sma[i]
            curr_rsi             = rsi_vals[i]
            golden_cross = (curr_fast > curr_slow) and (prev_fast <= prev_slow)
            rsi_buy_ok   = (not self.cfg.use_rsi_filter) or (curr_rsi < self.cfg.rsi_overbought)
            if golden_cross and rsi_buy_ok and position == 0.0:
                position    = equity / price
                entry_price = price
                entry_date  = dates[i]
                entry_bar   = i
                log.debug("BUY  @ %s  price=%.2f  RSI=%.1f", entry_date, price, curr_rsi)
            elif position > 0.0:
                death_cross   = (curr_fast < curr_slow) and (prev_fast >= prev_slow)
                rsi_sell_ok   = (not self.cfg.use_rsi_filter) or (curr_rsi > self.cfg.rsi_oversold)
                if death_cross and rsi_sell_ok:
                    pnl = position * (price - entry_price)
                    equity += pnl
                    record = TradeRecord(
                        entry_date  = entry_date,
                        exit_date   = dates[i],
                        entry_price = entry_price,
                        exit_price  = price,
                        shares      = position,
                        pnl         = pnl,
                        hold_bars   = i - entry_bar,
                    )
                    trades.append(record)
                    log.debug(
                        "SELL @ %s  price=%.2f  PnL=%.2f  bars_held=%d",
                        dates[i], price, pnl, i - entry_bar,
                    )
                    position = 0.0
            mtm = equity if position == 0.0 else equity + position * (price - entry_price)
            equity_curve.append(mtm)
        if position > 0.0:
            final_price = closes[-1]
            pnl = position * (final_price - entry_price)
            equity += pnl
            trades.append(TradeRecord(
                entry_date  = entry_date,
                exit_date   = dates[-1] + " (forced close)",
                entry_price = entry_price,
                exit_price  = final_price,
                shares      = position,
                pnl         = pnl,
                hold_bars   = n - 1 - entry_bar,
            ))
            log.info(
                "Open position closed at end-of-series. Final price: %.2f, PnL: %.2f",
                final_price, pnl,
            )
        return trades, equity_curve
class MetricsCalculator:
    TRADING_DAYS_PER_YEAR : int = 252                        
    def __init__(
        self,
        cfg          : BacktestConfig,
        trades       : List[TradeRecord],
        equity_curve : List[float],
        df,                         
    ) -> None:
        self.cfg          = cfg
        self.trades       = trades
        self.equity_curve = equity_curve
        self.df           = df
    def compute(self) -> BacktestMetrics:
        m = BacktestMetrics()
        m.bars            = len(self.df)
        m.initial_deposit = self.cfg.initial_deposit
        pnls = [t.pnl for t in self.trades]                                 
        m.gross_profit    = sum(p for p in pnls if p > 0)
        m.gross_loss      = sum(p for p in pnls if p < 0)                    
        m.total_net_profit = m.gross_profit + m.gross_loss
        m.profit_factor = (
            m.gross_profit / abs(m.gross_loss)
            if m.gross_loss != 0 else float('inf')
        )
        m.total_trades    = len(self.trades)
        m.expected_payoff = (
            m.total_net_profit / m.total_trades if m.total_trades > 0 else 0.0
        )
        m.return_pct = (m.total_net_profit / m.initial_deposit) * 100
        wins   = [t for t in self.trades if t.is_winner]
        losses = [t for t in self.trades if not t.is_winner]
        m.win_trades   = len(wins)
        m.loss_trades  = len(losses)
        m.win_pct      = (m.win_trades  / m.total_trades * 100) if m.total_trades > 0 else 0.0
        m.loss_pct     = (m.loss_trades / m.total_trades * 100) if m.total_trades > 0 else 0.0
        win_pnls  = [t.pnl for t in wins]
        loss_pnls = [t.pnl for t in losses]
        m.largest_profit = max(win_pnls,  default=0.0)
        m.largest_loss   = min(loss_pnls, default=0.0)
        m.avg_profit     = (sum(win_pnls)  / len(win_pnls))  if win_pnls  else 0.0
        m.avg_loss       = (sum(loss_pnls) / len(loss_pnls)) if loss_pnls else 0.0
        m.avg_hold_bars  = (
            sum(t.hold_bars for t in self.trades) / m.total_trades
            if m.total_trades > 0 else 0.0
        )
        m.max_cons_wins, m.max_cons_losses = self._compute_streaks(pnls)
        m.abs_drawdown, m.max_drawdown, m.max_drawdown_pct, m.max_dd_duration = (
            self._compute_drawdowns(self.equity_curve, self.cfg.initial_deposit)
        )
        m.sharpe_ratio  = self._sharpe(self.equity_curve)
        m.sortino_ratio = self._sortino(self.equity_curve)
        m.calmar_ratio  = self._calmar(m.return_pct, m.max_drawdown_pct, m.bars)
        m.recovery_factor = (
            m.total_net_profit / m.max_drawdown
            if m.max_drawdown > 0 else float('inf')
        )
        m.last_price = float(self.df['Close'].iloc[-1])
        m.last_rsi   = float(self.df['RSI'].iloc[-1])
        return m
    @staticmethod
    def _compute_streaks(pnls: List[float]) -> Tuple[int, int]:
        max_wins = max_losses = 0
        curr_wins = curr_losses = 0
        for p in pnls:
            if p > 0:
                curr_wins   += 1
                curr_losses  = 0
            else:
                curr_losses += 1
                curr_wins    = 0
            max_wins   = max(max_wins,   curr_wins)
            max_losses = max(max_losses, curr_losses)
        return max_wins, max_losses
    @staticmethod
    def _compute_drawdowns(
        equity_curve   : List[float],
        initial_deposit: float,
    ) -> Tuple[float, float, float, int]:
        eq  = np.asarray(equity_curve, dtype=float)
        n   = len(eq)
        running_max = np.maximum.accumulate(eq)
        drawdown_series = running_max - eq
        max_dd     = float(drawdown_series.max())
        dd_peak_ix = int(drawdown_series.argmax())                            
        max_dd_pct = (
            (max_dd / running_max[dd_peak_ix]) * 100
            if max_dd > 0 and running_max[dd_peak_ix] > 0 else 0.0
        )
        min_equity    = float(eq.min())
        abs_drawdown  = max(0.0, initial_deposit - min_equity)
        max_duration = 0
        curr_duration = 0
        for i in range(n):
            if eq[i] < running_max[i]:
                curr_duration += 1
                max_duration   = max(max_duration, curr_duration)
            else:
                curr_duration  = 0                                   
        return abs_drawdown, max_dd, max_dd_pct, max_duration
    @staticmethod
    def _sharpe(equity_curve: List[float]) -> float:
        eq = np.asarray(equity_curve, dtype=float)
        if len(eq) < 2:
            return 0.0
        eq_safe = np.where(eq <= 0, 1e-10, eq)
        log_returns = np.diff(np.log(eq_safe))
        std = float(log_returns.std())
        if std < 1e-10:
            return 0.0
        return float(log_returns.mean() / std * math.sqrt(252))
    @staticmethod
    def _sortino(equity_curve: List[float]) -> float:
        eq = np.asarray(equity_curve, dtype=float)
        if len(eq) < 2:
            return 0.0
        eq_safe     = np.where(eq <= 0, 1e-10, eq)
        log_returns = np.diff(np.log(eq_safe))
        negative_returns = log_returns[log_returns < 0]
        if len(negative_returns) == 0:
            return float('inf')
        downside_std = float(negative_returns.std())
        if downside_std < 1e-10:
            return 0.0
        return float(log_returns.mean() / downside_std * math.sqrt(252))
    @staticmethod
    def _calmar(return_pct: float, max_dd_pct: float, bars: int) -> float:
        if max_dd_pct <= 0:
            return float('inf')                                  
        if bars <= 0:
            return 0.0
        total_multiplier = 1.0 + return_pct / 100.0
        if total_multiplier <= 0:
            return 0.0
        annualised_return = (total_multiplier ** (252.0 / bars) - 1.0) * 100.0
        return annualised_return / max_dd_pct
class OracleEngine:
    def __init__(self, cfg: BacktestConfig) -> None:
        self.cfg = cfg
    def analyse(self, df, metrics: BacktestMetrics) -> BacktestMetrics:
        if len(df) < 4:
            metrics.oracle_signal = "INSUFFICIENT DATA"
            return metrics
        latest  = df.iloc[-1]
        prev1   = df.iloc[-2]
        prev3   = df.iloc[-4] if len(df) >= 4 else df.iloc[0]
        price    = float(latest['Close'])
        f_now    = float(latest['Fast_SMA'])
        s_now    = float(latest['Slow_SMA'])
        f_prev   = float(prev1['Fast_SMA'])
        s_prev   = float(prev1['Slow_SMA'])
        rsi_now  = float(latest['RSI'])
        rsi_prev = float(prev3['RSI'])
        score = 0
        reasons: List[str] = []
        if f_now > s_now:
            if f_prev <= s_prev:
                score += 20                                                
                reasons.append("GOLDEN CROSS just formed (+20)")
            else:
                score += 14                     
                reasons.append("Active uptrend: fast > slow SMA (+14)")
        else:
            if f_prev >= s_prev:
                score += 0                                         
                reasons.append("DEATH CROSS just formed (+0)")
            else:
                score += 6                        
                reasons.append("Active downtrend: fast < slow SMA (+6)")
        gap_now  = f_now - s_now
        gap_prev = f_prev - s_prev
        if gap_now > gap_prev:
            score += 20                           
            reasons.append("Bullish momentum: SMA gap widening (+20)")
        elif gap_now > 0:
            score += 10                                     
            reasons.append("Momentum fading but trend intact (+10)")
        else:
            score += 0                                           
            reasons.append("Bearish momentum: gap negative/widening (+0)")
        if 40 <= rsi_now <= 60:
            score += 15                                                     
            reasons.append(f"RSI neutral zone ({rsi_now:.1f}) (+15)")
        elif 30 <= rsi_now < 40:
            score += 20                                       
            reasons.append(f"RSI mildly oversold ({rsi_now:.1f}) — potential bounce (+20)")
        elif rsi_now < 30:
            score += 10                                                     
            reasons.append(f"RSI deeply oversold ({rsi_now:.1f}) — risky (+10)")
        elif 60 < rsi_now <= 70:
            score += 10                                
            reasons.append(f"RSI mildly overbought ({rsi_now:.1f}) (+10)")
        else:
            score += 5                                                  
            reasons.append(f"RSI deeply overbought ({rsi_now:.1f}) (+5)")
        if rsi_now > rsi_prev:
            score += 20
            reasons.append(f"RSI rising ({rsi_prev:.1f}→{rsi_now:.1f}) (+20)")
        else:
            score += 0
            reasons.append(f"RSI falling ({rsi_prev:.1f}→{rsi_now:.1f}) (+0)")
        above_fast = price > f_now
        above_slow = price > s_now
        if above_fast and above_slow:
            score += 20
            reasons.append("Price above BOTH SMAs (+20) — strong bull structure")
        elif above_slow and not above_fast:
            score += 12
            reasons.append("Price above slow SMA only (+12) — mild bull")
        elif above_fast and not above_slow:
            score += 8
            reasons.append("Price above fast only (+8) — mixed signal")
        else:
            score += 0
            reasons.append("Price below BOTH SMAs (+0) — bear structure")
        if score >= 80:
            signal = "🟢 STRONG BUY"
        elif score >= 60:
            signal = "🔵 BUY"
        elif score >= 40:
            signal = "🟡 NEUTRAL — STAY OUT"
        elif score >= 20:
            signal = "🟠 SELL"
        else:
            signal = "🔴 STRONG SELL"
        metrics.oracle_signal = signal
        metrics.oracle_score  = score
        metrics.oracle_reason = "\n  • ".join([""] + reasons)
        metrics.last_price    = price
        metrics.last_rsi      = rsi_now
        return metrics
class ReportRenderer:
    def __init__(self, cfg: BacktestConfig) -> None:
        from rich.console import Console
        self.cfg     = cfg
        self.console = Console()
    def render(
        self,
        metrics      : BacktestMetrics,
        equity_curve : List[float],
        trades       : List[TradeRecord],
    ) -> None:
        os.system('cls' if os.name == 'nt' else 'clear')
        self._header()
        self._metrics_panel(metrics)
        self._equity_chart(equity_curve)
        self._trade_log(trades)
        self._oracle_panel(metrics)
    def _header(self) -> None:
        from rich.align import Align
        c = self.console
        c.print(Align.center("[bold white on dark_blue]  Strategy Tester Report  [/bold white on dark_blue]"))
        c.print(Align.center("[bold]Quant-Terminal-Alpha01  ·  v2.0[/bold]"))
        c.print(Align.center(
            f"[dim]SMA {self.cfg.fast_ma}/{self.cfg.slow_ma} Crossover"
            f"{'  +RSI Filter' if self.cfg.use_rsi_filter else ''}[/dim]\n"
        ))
    def _metrics_panel(self, m: BacktestMetrics) -> None:
        from rich.table import Table
        from rich.panel import Panel
        from rich import box
        def _fmt(val: float, decimals: int = 2, positive_color: str = "green") -> str:
            colour = positive_color if val >= 0 else "red"
            return f"[{colour}]{val:,.{decimals}f}[/{colour}]"
        def _pct(val: float) -> str:
            colour = "green" if val >= 0 else "red"
            return f"[{colour}]{val:+.2f}%[/{colour}]"
        grid = Table.grid(expand=True, padding=(0, 2))
        for _ in range(6):
            grid.add_column()                              
        def row(l1, v1, l2="", v2="", l3="", v3=""):
            grid.add_row(
                f"[dim]{l1}[/dim]", v1,
                f"[dim]{l2}[/dim]", v2,
                f"[dim]{l3}[/dim]", v3,
            )
        row("Symbol",          f"[cyan]{self.cfg.ticker}[/cyan]",
            "Period",          f"[cyan]{self.cfg.period}[/cyan]",
            "Bars in test",    str(m.bars))
        row("Initial Deposit", f"[white]{m.initial_deposit:,.2f}[/white]",
            "Total Net Profit",_fmt(m.total_net_profit),
            "Return",          _pct(m.return_pct))
        row("Gross Profit",    _fmt(m.gross_profit),
            "Gross Loss",      _fmt(m.gross_loss, positive_color="red"),
            "Profit Factor",   _fmt(m.profit_factor, positive_color="green"))
        row("Expected Payoff", _fmt(m.expected_payoff),
            "Avg Hold (bars)", f"{m.avg_hold_bars:.1f}",
            "Total Trades",    str(m.total_trades))
        grid.add_row("", "", "", "", "", "")                  
        row("Abs Drawdown",    f"[red]{m.abs_drawdown:,.2f}[/red]",
            "Max Drawdown",    f"[red]{m.max_drawdown:,.2f} ({m.max_drawdown_pct:.2f}%)[/red]",
            "DD Duration",     f"[yellow]{m.max_dd_duration} bars[/yellow]")
        grid.add_row("", "", "", "", "", "")                  
        sharpe_col  = "green" if m.sharpe_ratio  >= 1.0 else ("yellow" if m.sharpe_ratio >= 0 else "red")
        sortino_col = "green" if m.sortino_ratio >= 1.5 else ("yellow" if m.sortino_ratio >= 0 else "red")
        calmar_col  = "green" if m.calmar_ratio  >= 1.0 else ("yellow" if m.calmar_ratio >= 0 else "red")
        recov_col   = "green" if m.recovery_factor >= 3.0 else "yellow"
        row("Sharpe Ratio",    f"[{sharpe_col}]{m.sharpe_ratio:.3f}[/{sharpe_col}]",
            "Sortino Ratio",   f"[{sortino_col}]{m.sortino_ratio:.3f}[/{sortino_col}]",
            "Calmar Ratio",    f"[{calmar_col}]{m.calmar_ratio:.3f}[/{calmar_col}]")
        row("Recovery Factor", f"[{recov_col}]{m.recovery_factor:.2f}[/{recov_col}]",
            "Max Cons. Wins",  str(m.max_cons_wins),
            "Max Cons. Losses",str(m.max_cons_losses))
        grid.add_row("", "", "", "", "", "")
        row("Win Trades",      f"[green]{m.win_trades} ({m.win_pct:.1f}%)[/green]",
            "Loss Trades",     f"[red]{m.loss_trades} ({m.loss_pct:.1f}%)[/red]",
            "Win Rate",        _pct(m.win_pct))
        row("Largest Profit",  _fmt(m.largest_profit),
            "Largest Loss",    _fmt(m.largest_loss, positive_color="red"),
            "")
        row("Avg Profit",      _fmt(m.avg_profit),
            "Avg Loss",        _fmt(m.avg_loss, positive_color="red"),
            "Last RSI",        f"{m.last_rsi:.1f}")
        self.console.print(
            Panel(grid, title="[bold]📊 Backtest Statistics[/bold]", border_style="blue")
        )
    def _equity_chart(self, equity_curve: List[float]) -> None:
        from rich.panel import Panel
        from rich.text  import Text
        CHART_WIDTH  = 80
        CHART_HEIGHT = 10
        CHARS        = " ▂▃▄▅▆▇█"
        if not equity_curve:
            return
        step    = max(1, len(equity_curve) // CHART_WIDTH)
        samples = equity_curve[::step][:CHART_WIDTH]
        n       = len(samples)
        min_eq  = min(samples)
        max_eq  = max(samples)
        range_eq = max_eq - min_eq
        def normalise(v: float) -> int:
            if range_eq == 0:
                return CHART_HEIGHT // 2
            return int(((v - min_eq) / range_eq) * (CHART_HEIGHT - 1))
        heights = [normalise(s) for s in samples]
        lines = []
        for row_idx in range(CHART_HEIGHT - 1, -1, -1):                         
            line = ""
            for bar_height in heights:
                above_baseline = bar_height >= row_idx
                if above_baseline:
                    char_idx = min(
                        len(CHARS) - 1,
                        int((bar_height / (CHART_HEIGHT - 1)) * (len(CHARS) - 1)),
                    )
                    line += f"[green]{CHARS[char_idx]}[/green]"
                else:
                    line += " "
            lines.append(line)
        y_top    = f"{max_eq:>12,.0f}"
        y_mid    = f"{(min_eq + max_eq) / 2:>12,.0f}"
        y_bottom = f"{min_eq:>12,.0f}"
        chart_text  = f"[bold]{y_top}[/bold]  " + lines[0] + "\n"
        chart_text += f"[dim]{y_mid}[/dim]   " + lines[CHART_HEIGHT // 2] + "\n"
        chart_text += f"[bold]{y_bottom}[/bold]  " + lines[-1] + "\n"
        self.console.print(
            Panel(
                chart_text,
                title="[bold cyan]📈 Equity Curve[/bold cyan]",
                border_style="cyan",
            )
        )
    def _trade_log(self, trades: List[TradeRecord]) -> None:
        from rich.table import Table
        from rich.panel import Panel
        from rich import box
        if not trades:
            return
        table = Table(box=box.SIMPLE_HEAD, show_header=True, header_style="bold dim")
        for col in ("#", "Entry Date", "Exit Date", "Entry ₹", "Exit ₹", "PnL", "Rtn%", "Bars", ""):
            table.add_column(col, justify="right" if col not in ("#", "Entry Date", "Exit Date", "") else "left")
        display_trades = trades[-10:]                                        
        for i, t in enumerate(display_trades, start=len(trades) - len(display_trades) + 1):
            style = "green" if t.is_winner else "red"
            table.add_row(
                str(i),
                t.entry_date,
                t.exit_date,
                f"₹{t.entry_price:,.2f}",
                f"₹{t.exit_price:,.2f}",
                f"[{style}]₹{t.pnl:+,.2f}[/{style}]",
                f"[{style}]{t.return_pct:+.2f}%[/{style}]",
                str(t.hold_bars),
                "✓" if t.is_winner else "✗",
            )
        self.console.print(
            Panel(table, title="[bold]📋 Recent Trade Log (last 10)[/bold]", border_style="dim")
        )
    def _oracle_panel(self, m: BacktestMetrics) -> None:
        from rich.panel import Panel
        from rich.text  import Text
        if m.oracle_score >= 80:   border = "green"
        elif m.oracle_score >= 60: border = "cyan"
        elif m.oracle_score >= 40: border = "yellow"
        elif m.oracle_score >= 20: border = "dark_orange"
        else:                      border = "red"
        filled  = m.oracle_score // 10
        bar_str = "█" * filled + "░" * (10 - filled)
        text = Text()
        text.append(f"Current Price : ₹{m.last_price:,.2f}\n", style="bold white")
        text.append(f"RSI ({self.cfg.rsi_period})      : {m.last_rsi:.1f}\n", style="dim")
        text.append(f"Oracle Signal : ", style="white")
        text.append(f"{m.oracle_signal}\n", style=f"bold {border}")
        text.append(f"Confluence    : [{bar_str}] {m.oracle_score}/100\n\n", style="bold")
        text.append("Signal Breakdown:\n", style="bold dim")
        text.append(m.oracle_reason, style="dim")
        self.console.print(
            Panel(
                text,
                title="[bold]🔮 THE TRADE ORACLE  ·  Multi-Signal Confluence Engine[/bold]",
                border_style=border,
            )
        )
class StrategyTester:
    def __init__(self, cfg: Optional[BacktestConfig] = None) -> None:
        self.cfg          : BacktestConfig          = cfg or BacktestConfig()
        self.metrics      : Optional[BacktestMetrics]  = None
        self.equity_curve : List[float]               = []
        self.trades       : List[TradeRecord]          = []
    def run(self) -> bool:
        from rich.console import Console
        from rich.progress import Progress, SpinnerColumn, TextColumn
        console = Console()
        if not self._ensure_dependencies():
            return False
        with Progress(
            SpinnerColumn("dots2"),
            TextColumn("[bold cyan]Running full analysis pipeline…"),
            console=console,
            transient=True,
        ) as progress:
            progress.add_task("pipeline", total=None)
            try:
                fetcher = DataFetcher(self.cfg)
                raw_df  = fetcher.fetch()
                engine = StrategyEngine(self.cfg)
                df     = engine.build_indicators(raw_df)
                self.trades, self.equity_curve = engine.simulate(
                    df, self.cfg.initial_deposit
                )
                calculator  = MetricsCalculator(self.cfg, self.trades, self.equity_curve, df)
                self.metrics = calculator.compute()
                oracle       = OracleEngine(self.cfg)
                self.metrics = oracle.analyse(df, self.metrics)
            except (DataFetchError, InsufficientDataError, BacktestError) as known_err:
                console.print(f"\n[bold red][!] {type(known_err).__name__}: {known_err}[/bold red]")
                return False
            except Exception as unexpected_err:
                console.print(f"\n[bold red][!] Unexpected error: {unexpected_err}[/bold red]")
                log.exception("Unexpected exception in pipeline.")
                return False
        renderer = ReportRenderer(self.cfg)
        renderer.render(self.metrics, self.equity_curve, self.trades)
        return True
    def interactive_menu(self) -> None:
        from rich.console import Console
        from rich.prompt  import Prompt
        if not self._ensure_dependencies():
            return
        console = Console()
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            c = self.cfg              
            console.print("\n[bold magenta on black] 📊  ALGORITHMIC STRATEGY TESTER & ORACLE  v2.0 [/bold magenta on black]")
            console.print("═" * 70)
            console.print(f"[bold]Ticker:[/bold]           [cyan]{c.ticker}[/cyan]")
            console.print(f"[bold]Capital:[/bold]          [green]₹{c.initial_deposit:,.2f}[/green]")
            console.print(
                f"[bold]Strategy:[/bold]         [yellow]SMA Crossover "
                f"({c.fast_ma}/{c.slow_ma})"
                f"{'  +RSI(' + str(c.rsi_period) + ')' if c.use_rsi_filter else '  (no RSI filter)'}[/yellow]"
            )
            console.print(f"[bold]Time Period:[/bold]      [yellow]{c.period}[/yellow]")
            console.print("═" * 70)
            console.print("\n  [bold cyan]1.[/bold cyan]  🚀  Run Backtest & Oracle Analysis")
            console.print("  [bold cyan]T.[/bold cyan]  🔄  Change Ticker")
            console.print("  [bold cyan]C.[/bold cyan]  💰  Change Initial Capital")
            console.print("  [bold cyan]S.[/bold cyan]  ⚙️   Tune Strategy Parameters")
            console.print("  [bold cyan]R.[/bold cyan]  🔀  Toggle RSI Confluence Filter")
            console.print("  [bold cyan]0.[/bold cyan]  ⬅️   Return to Main Menu")
            choice = Prompt.ask("\n[bold green]Select Action[/bold green]").strip().upper()
            if choice == '0':
                break
            elif choice == '1':
                if self.run():
                    input("\nPress ENTER to continue…")
            elif choice == 'T':
                new_t = Prompt.ask("Enter ticker (e.g. AAPL, TCS.NS, BTC-USD)").strip().upper()
                if new_t:
                    self._rebuild_config(ticker=new_t)
            elif choice == 'C':
                raw = Prompt.ask("Enter initial deposit").strip().replace(',', '')
                try:
                    self._rebuild_config(initial_deposit=float(raw))
                except ValueError:
                    console.print("[red]Invalid amount — must be a positive number.[/red]")
                    time.sleep(1)
            elif choice == 'S':
                try:
                    fast = int(Prompt.ask("Fast SMA period").strip())
                    slow = int(Prompt.ask("Slow SMA period").strip())
                    rsi  = int(Prompt.ask("RSI period (default 14)").strip() or "14")
                    self._rebuild_config(fast_ma=fast, slow_ma=slow, rsi_period=rsi)
                except ValueError as e:
                    console.print(f"[red]Invalid input: {e}[/red]")
                    time.sleep(1)
            elif choice == 'R':
                self._rebuild_config(use_rsi_filter=not self.cfg.use_rsi_filter)
                state = "ENABLED" if self.cfg.use_rsi_filter else "DISABLED"
                console.print(f"[yellow]RSI filter {state}.[/yellow]")
                time.sleep(0.8)
            else:
                console.print("[bold red]Invalid selection.[/bold red]")
                time.sleep(0.8)
    def _rebuild_config(self, **overrides) -> None:
        from rich.console import Console
        import dataclasses
        current = dataclasses.asdict(self.cfg)
        current.update(overrides)
        try:
            self.cfg = BacktestConfig(**current)
        except (ValueError, TypeError) as err:
            Console().print(f"[red]Config error: {err}[/red]")
    @staticmethod
    def _ensure_dependencies() -> bool:
        packages = ["yfinance", "pandas", "numpy", "rich"]
        missing  = []
        for pkg in packages:
            try:
                __import__(pkg)
            except ImportError:
                missing.append(pkg)
        if not missing:
            return True
        print(f"\033[93m[!] Installing missing packages: {', '.join(missing)}…\033[0m")
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install", *missing, "--quiet"],
                timeout=120,                                                      
            )
            log.info("Installed: %s", missing)
            return True
        except subprocess.TimeoutExpired:
            print("\033[91m[!] Install timed out. Please run: pip install " + " ".join(missing) + "\033[0m")
            return False
        except subprocess.CalledProcessError as exc:
            print(f"\033[91m[!] pip install failed (exit code {exc.returncode}).\033[0m")
            return False
def run_strategy_tester(ticker_ignored: str) -> None:
    tester = StrategyTester()                                                  
    tester.interactive_menu()             
