def run_options_greeks(ticker):
    from math import log, sqrt, exp
    try:
        from scipy.stats import norm
        HAS_SCIPY = True
    except ImportError:
        HAS_SCIPY = False
        print("\n  ⚠  scipy not installed. Run: pip install scipy"); press_enter(); return
    header(f"MODULE 33 — BLACK-SCHOLES OPTIONS GREEKS  |  {ticker}")
    stock = yf.Ticker(ticker)
    S     = stock.info.get('currentPrice') or stock.info.get('previousClose', 0)
    if S == 0:
        d  = yf.download(ticker, period="5d", progress=False)
        d  = flatten_cols(d)
        S  = float(d['Close'].iloc[-1])
    print(f"  Current Price: ₹{S:.2f}")
    try:
        K   = float(input(f"  Strike Price  [default ₹{S:.0f}]: ").strip() or S)
        T_d = float(input("  Days to Expiry [default 30]: ").strip() or 30)
        r   = float(input("  Risk-Free Rate % [default 6.5]: ").strip() or 6.5) / 100
        d2  = yf.download(ticker, period="1y", progress=False)
        d2  = flatten_cols(d2)
        hv  = float(d2['Close'].pct_change().dropna().std() * np.sqrt(252))
        iv_inp = input(f"  Implied Vol %  [default HV={hv*100:.1f}%]: ").strip()
        sigma = float(iv_inp)/100 if iv_inp else hv
    except ValueError:
        print("  Invalid input."); press_enter(); return
    T = T_d / 365
    if T <= 0 or sigma <= 0:
        print("  Invalid T or σ."); press_enter(); return
    d1 = (log(S/K) + (r + 0.5*sigma**2)*T) / (sigma*sqrt(T))
    d2v= d1 - sigma*sqrt(T)
    C  = S*norm.cdf(d1)  - K*exp(-r*T)*norm.cdf(d2v)
    P  = K*exp(-r*T)*norm.cdf(-d2v) - S*norm.cdf(-d1)
    delta_c =  norm.cdf(d1)
    delta_p =  norm.cdf(d1) - 1
    gamma   =  norm.pdf(d1) / (S * sigma * sqrt(T))
    vega    =  S * norm.pdf(d1) * sqrt(T) / 100                              
    theta_c = (-(S*norm.pdf(d1)*sigma)/(2*sqrt(T)) - r*K*exp(-r*T)*norm.cdf(d2v))  / 365
    theta_p = (-(S*norm.pdf(d1)*sigma)/(2*sqrt(T)) + r*K*exp(-r*T)*norm.cdf(-d2v)) / 365
    rho_c   =  K * T * exp(-r*T) * norm.cdf(d2v)  / 100
    rho_p   = -K * T * exp(-r*T) * norm.cdf(-d2v) / 100
    section("Option Prices")
    print(f"  CALL Price  : ₹{C:.2f}")
    print(f"  PUT  Price  : ₹{P:.2f}")
    print(f"  Put-Call Parity Check (C-P+PV(K)-S): {C-P+K*exp(-r*T)-S:.4f} ≈ 0")
    section("Greeks  (CALL / PUT)")
    print(f"  Delta  : {delta_c:+.4f} / {delta_p:+.4f}  ← price sensitivity")
    print(f"  Gamma  : {gamma:.6f}              ← delta rate of change")
    print(f"  Vega   : {vega:+.4f} / {vega:+.4f}  ← per 1% vol move (₹)")
    print(f"  Theta  : {theta_c:+.4f} / {theta_p:+.4f}  ← daily time decay (₹)")
    print(f"  Rho    : {rho_c:+.4f} / {rho_p:+.4f}  ← per 1% rate move (₹)")
    strikes  = np.linspace(S*0.70, S*1.30, 60)
    call_px  = []
    put_px   = []
    for k in strikes:
        d1s  = (log(S/k) + (r+0.5*sigma**2)*T) / (sigma*sqrt(T))
        d2s  = d1s - sigma*sqrt(T)
        call_px.append(S*norm.cdf(d1s) - k*exp(-r*T)*norm.cdf(d2s))
        put_px.append(k*exp(-r*T)*norm.cdf(-d2s) - S*norm.cdf(-d1s))
    plt.style.use('dark_background')
    fig, axes = plt.subplots(2, 3, figsize=(20, 10))
    fig.suptitle(f"Black-Scholes Options Analysis: {ticker}  |  S=₹{S:.0f}  K=₹{K:.0f}  T={T_d:.0f}d  σ={sigma*100:.1f}%",
                 fontsize=15, fontweight='bold')
    axes[0,0].plot(strikes, call_px, color=GREEN, lw=2, label='Call')
    axes[0,0].plot(strikes, put_px,  color=RED,   lw=2, label='Put')
    axes[0,0].axvline(K, color=ORANGE, ls='--', lw=1.5, label=f'Strike ₹{K:.0f}')
    axes[0,0].axvline(S, color=ACCENT, ls=':',  lw=1.5, label=f'Spot ₹{S:.0f}')
    axes[0,0].set_title('Option Price vs Strike'); axes[0,0].legend(); axes[0,0].grid(alpha=0.3)
    axes[0,0].set_xlabel('Strike (₹)'); axes[0,0].set_ylabel('Price (₹)')
    deltas_c = [norm.cdf((log(S/k)+(r+0.5*sigma**2)*T)/(sigma*sqrt(T))) for k in strikes]
    axes[0,1].plot(strikes, deltas_c, color=ACCENT, lw=2)
    axes[0,1].axhline(0.5, color=ORANGE, ls='--', lw=1, label='ATM Delta=0.5')
    axes[0,1].set_title('Call Delta vs Strike'); axes[0,1].legend(); axes[0,1].grid(alpha=0.3)
    axes[0,1].set_xlabel('Strike (₹)'); axes[0,1].set_ylabel('Delta')
    gammas = [norm.pdf((log(S/k)+(r+0.5*sigma**2)*T)/(sigma*sqrt(T))) / (k*sigma*sqrt(T)) for k in strikes]
    axes[0,2].plot(strikes, gammas, color=PURPLE, lw=2)
    axes[0,2].set_title('Gamma vs Strike'); axes[0,2].grid(alpha=0.3)
    axes[0,2].set_xlabel('Strike (₹)'); axes[0,2].set_ylabel('Gamma')
    T_range = np.linspace(0.01, 1.0, 100)
    thetas_t = []
    for t in T_range:
        d1t = (log(S/K)+(r+0.5*sigma**2)*t)/(sigma*sqrt(t))
        d2t = d1t - sigma*sqrt(t)
        thetas_t.append((-(S*norm.pdf(d1t)*sigma)/(2*sqrt(t)) - r*K*exp(-r*t)*norm.cdf(d2t))/365)
    axes[1,0].plot(T_range*365, thetas_t, color=BROWN, lw=2)
    axes[1,0].axvline(T_d, color=ORANGE, ls='--', lw=1.5, label=f'T={T_d:.0f}d')
    axes[1,0].set_title('Call Theta (Daily Decay) vs DTE'); axes[1,0].legend(); axes[1,0].grid(alpha=0.3)
    axes[1,0].set_xlabel('Days to Expiry'); axes[1,0].set_ylabel('Theta (₹/day)')
    vegas = [S*norm.pdf((log(S/k)+(r+0.5*sigma**2)*T)/(sigma*sqrt(T)))*sqrt(T)/100 for k in strikes]
    axes[1,1].plot(strikes, vegas, color=TEAL, lw=2)
    axes[1,1].set_title('Vega vs Strike (₹ per 1% vol)'); axes[1,1].grid(alpha=0.3)
    axes[1,1].set_xlabel('Strike (₹)'); axes[1,1].set_ylabel('Vega')
    payoff_c = np.maximum(strikes - K, 0) - C
    payoff_p = np.maximum(K - strikes, 0) - P
    axes[1,2].plot(strikes, payoff_c, color=GREEN, lw=2, label=f'Long Call (cost ₹{C:.2f})')
    axes[1,2].plot(strikes, payoff_p, color=RED,   lw=2, label=f'Long Put  (cost ₹{P:.2f})')
    axes[1,2].axhline(0, color='white', lw=1); axes[1,2].axvline(S, color=ACCENT, ls=':', lw=1.5)
    axes[1,2].set_title('P&L Profile at Expiry'); axes[1,2].legend(); axes[1,2].grid(alpha=0.3)
    axes[1,2].set_xlabel('Price at Expiry (₹)'); axes[1,2].set_ylabel('P&L (₹)')
    for ax in axes.flat:
        ax.set_facecolor(PANEL_BG)
        for sp in ax.spines.values(): sp.set_edgecolor(GRID)
    fig.patch.set_facecolor(BG)
    plt.tight_layout()
    plt.show()
    press_enter()
def run_advanced_greeks(ticker):
    from math import log, sqrt, exp
    try:
        from scipy.stats import norm
    except ImportError:
        print("\n  ⚠  scipy not installed. Run: pip install scipy")
        press_enter()
        return
    header(f"MODULE 36 — ADVANCED HIGHER-ORDER GREEKS  |  {ticker}")
    stock = yf.Ticker(ticker)
    S = stock.info.get('currentPrice') or stock.info.get('previousClose', 0)
    if S == 0:
        import io, contextlib
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            d = yf.download(ticker, period="5d", progress=False)
        d = flatten_cols(d)
        if not d.empty: S = float(d['Close'].iloc[-1])
    if S == 0:
        print("  Could not fetch stock price.")
        press_enter()
        return
    print(f"  Current Price: ₹{S:.2f}")
    try:
        K_inp = input(f"  Strike Price  [default ₹{S:.0f}]: ").strip()
        K = float(K_inp) if K_inp else S
        T_inp = input("  Days to Expiry [default 30]: ").strip()
        T_d = float(T_inp) if T_inp else 30.0
        r_inp = input("  Risk-Free Rate % [default 6.5]: ").strip()
        r = float(r_inp)/100 if r_inp else 0.065
        q = 0.0
        import io, contextlib
        with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            d2 = yf.download(ticker, period="1y", progress=False)
        d2 = flatten_cols(d2)
        hv = float(d2['Close'].pct_change().dropna().std() * np.sqrt(252))
        iv_inp = input(f"  Implied Vol %  [default HV={hv*100:.1f}%]: ").strip()
        sigma = float(iv_inp)/100 if iv_inp else hv
    except ValueError:
        print("  Invalid input.")
        press_enter()
        return
    T = T_d / 365
    if T <= 0 or sigma <= 0:
        print("  Invalid T or σ.")
        press_enter()
        return
    d1 = (log(S/K) + (r - q + 0.5*sigma**2)*T) / (sigma*sqrt(T))
    d2_val = d1 - sigma*sqrt(T)
    delta_c = exp(-q*T) * norm.cdf(d1)
    delta_p = exp(-q*T) * (norm.cdf(d1) - 1)
    vega = S * exp(-q*T) * norm.pdf(d1) * sqrt(T)
    theta_c = (-S * exp(-q*T) * norm.pdf(d1) * sigma/(2*sqrt(T)) - r*K*exp(-r*T)*norm.cdf(d2_val)) / 365
    gamma = exp(-q*T) * norm.pdf(d1) / (S * sigma * sqrt(T))
    vanna = -exp(-q*T) * norm.pdf(d1) * d2_val / sigma
    charm = -exp(-q*T) * norm.pdf(d1) * (2*(r-q)*T - d2_val*sigma*sqrt(T)) / (2*T*sigma*sqrt(T))
    vomma = vega * d1 * d2_val / sigma
    veta = -vega * (r + d1*(r-q)/(sigma*sqrt(T)) - (1 + d1*d2_val)/(2*T))
    speed = -gamma * (1 + d1/(sigma*sqrt(T))) / S
    zomma = gamma * (d1 * d2_val - 1) / sigma
    color = -gamma / (2*T) * (1 + d1 * (2*r*T - d2_val*sigma*sqrt(T))/(sigma*sqrt(T)))
    ultima = -vomma / sigma * (d1*d2_val - d1/d2_val - d2_val/d1 - 1) if d2_val != 0 and d1 != 0 else 0
    section("Higher-Order Greeks (The Sensitivities of Sensitivities)")
    print(f"  Vanna (∂Δ/∂σ) : {vanna:+.6f}   ← How delta changes if vol moves 100%")
    print(f"  Charm (∂Δ/∂T) : {charm:+.6f}   ← Delta decay per year (Weekend effect)")
    print(f"  Vomma (∂V/∂σ²): {vomma:+.6f}   ← Vega convexity (Vol of Vol)")
    print(f"  Veta  (∂V/∂T) : {veta:+.6f}   ← Vega decay over time")
    print(f"  Speed (∂Γ/∂S) : {speed:+.8f}   ← Rate of change of Gamma with Spot")
    print(f"  Zomma (∂Γ/∂σ) : {zomma:+.6f}   ← How Gamma changes with Vol")
    print(f"  Color (∂Γ/∂T) : {color:+.6f}   ← Gamma time decay")
    print(f"  Ultima        : {ultima:+.6f}   ← Third derivative of price to Vol")
    plt.style.use('dark_background')
    fig, axes = plt.subplots(2, 2, figsize=(16, 12))
    fig.suptitle(f"Advanced Greeks Analysis: {ticker} | K=₹{K:.0f}, T={T_d:.0f}d, σ={sigma*100:.1f}%", fontsize=16, fontweight='bold')
    spots = np.linspace(S*0.7, S*1.3, 100)
    for sig_loop in [sigma*0.8, sigma, sigma*1.2]:
        vannas = []
        for s_loop in spots:
            d1_v = (log(s_loop/K) + (r - q + 0.5*sig_loop**2)*T) / (sig_loop*sqrt(T))
            d2_v = d1_v - sig_loop*sqrt(T)
            v = -exp(-q*T) * norm.pdf(d1_v) * d2_v / sig_loop
            vannas.append(v)
        axes[0,0].plot(spots, vannas, label=f"σ = {sig_loop*100:.1f}%", lw=2)
    axes[0,0].axhline(0, color='gray', ls='--')
    axes[0,0].axvline(K, color='gray', ls=':', label='ATM')
    axes[0,0].set_title("Vanna vs Spot (The Pin Risk)")
    axes[0,0].legend(); axes[0,0].grid(alpha=0.3)
    for sig_loop in [sigma*0.8, sigma, sigma*1.2]:
        vommas = []
        for s_loop in spots:
            d1_v = (log(s_loop/K) + (r - q + 0.5*sig_loop**2)*T) / (sig_loop*sqrt(T))
            d2_v = d1_v - sig_loop*sqrt(T)
            vg = s_loop * exp(-q*T) * norm.pdf(d1_v) * sqrt(T)
            vm = vg * d1_v * d2_v / sig_loop
            vommas.append(vm)
        axes[0,1].plot(spots, vommas, label=f"σ = {sig_loop*100:.1f}%", lw=2)
    axes[0,1].axhline(0, color='gray', ls='--')
    axes[0,1].axvline(K, color='gray', ls=':', label='ATM')
    axes[0,1].set_title("Vomma vs Spot (Vega Convexity)")
    axes[0,1].legend(); axes[0,1].grid(alpha=0.3)
    for t_loop in [max(1, T_d-10)/365, T_d/365, (T_d+10)/365]:
        speeds = []
        for s_loop in spots:
            d1_v = (log(s_loop/K) + (r - q + 0.5*sigma**2)*t_loop) / (sigma*sqrt(t_loop))
            gm = exp(-q*t_loop) * norm.pdf(d1_v) / (s_loop * sigma * sqrt(t_loop))
            sp = -gm * (1 + d1_v/(sigma*sqrt(t_loop))) / s_loop
            speeds.append(sp)
        axes[1,0].plot(spots, speeds, label=f"T = {t_loop*365:.0f}d", lw=2)
    axes[1,0].axhline(0, color='gray', ls='--')
    axes[1,0].axvline(K, color='gray', ls=':', label='ATM')
    axes[1,0].set_title("Speed vs Spot (How Gamma moves)")
    axes[1,0].legend(); axes[1,0].grid(alpha=0.3)
    for sig_loop in [sigma*0.8, sigma, sigma*1.2]:
        zommas = []
        for s_loop in spots:
            d1_v = (log(s_loop/K) + (r - q + 0.5*sig_loop**2)*T) / (sig_loop*sqrt(T))
            d2_v = d1_v - sig_loop*sqrt(T)
            gm = exp(-q*T) * norm.pdf(d1_v) / (s_loop * sig_loop * sqrt(T))
            zm = gm * (d1_v * d2_v - 1) / sig_loop
            zommas.append(zm)
        axes[1,1].plot(spots, zommas, label=f"σ = {sig_loop*100:.1f}%", lw=2)
    axes[1,1].axhline(0, color='gray', ls='--')
    axes[1,1].axvline(K, color='gray', ls=':', label='ATM')
    axes[1,1].set_title("Zomma vs Spot (Gamma sensitivity to Vol)")
    axes[1,1].legend(); axes[1,1].grid(alpha=0.3)
    for ax in axes.flat:
        ax.set_facecolor(PANEL_BG)
        for sp in ax.spines.values(): sp.set_edgecolor(GRID)
    fig.patch.set_facecolor(BG)
    plt.tight_layout()
    plt.show()
    press_enter()
def run_pairs_trading(ticker):
    header(f"MODULE 27 — PAIRS TRADING / COINTEGRATION  |  {ticker}")
    pair2 = input("  Enter the second ticker for pairs trade (e.g. HDFCBANK.NS): ").strip().upper()
    if not pair2:
        print("  No ticker entered."); press_enter(); return
    print(f"  Downloading 2-year data for {ticker} & {pair2} …")
    try:
        d1 = yf.download(ticker, period="2y", interval="1d", progress=False)
        d2 = yf.download(pair2,  period="2y", interval="1d", progress=False)
        d1 = flatten_cols(d1)['Close'].dropna()
        d2 = flatten_cols(d2)['Close'].dropna()
    except Exception as e:
        print(f"  ⚠ Download error: {e}"); press_enter(); return
    common = d1.index.intersection(d2.index)
    if len(common) < 60:
        print("  ⚠ Not enough overlapping data."); press_enter(); return
    s1 = d1.loc[common]
    s2 = d2.loc[common]
    from numpy.linalg import lstsq
    X_mat = np.column_stack([s2.values, np.ones(len(s2))])
    beta_h, alpha_h = lstsq(X_mat, s1.values, rcond=None)[0]
    spread = s1 - beta_h * s2 - alpha_h
    roll_mean = spread.rolling(20).mean()
    roll_std  = spread.rolling(20).std()
    z_score   = (spread - roll_mean) / roll_std
    try:
        from statsmodels.tsa.stattools import adfuller, coint
        adf_stat, adf_p, *_ = adfuller(spread.dropna())
        _, coint_p, _       = coint(s1, s2)
        HAS_SM = True
    except ImportError:
        HAS_SM = False
        adf_stat, adf_p, coint_p = float('nan'), float('nan'), float('nan')
    signal = pd.Series(0, index=z_score.index)
    signal[z_score < -2] =  1
    signal[z_score >  2] = -1
    section("Cointegration Statistics")
    if HAS_SM:
        print(f"  ADF Stat (spread)   : {adf_stat:.4f}")
        print(f"  ADF p-value         : {adf_p:.4f}  {'← Cointegrated ✔' if adf_p < 0.05 else '← Not cointegrated ✘'}")
        print(f"  Engle-Granger p-val : {coint_p:.4f}")
    else:
        print("  ⚠ Install statsmodels for cointegration test: pip install statsmodels")
    print(f"  Hedge Ratio (β)     : {beta_h:.4f}")
    print(f"  Current Z-Score     : {z_score.iloc[-1]:.2f}")
    signal_txt = ("LONG SPREAD (buy {}, sell {})".format(ticker, pair2)
                  if z_score.iloc[-1] < -2 else
                  "SHORT SPREAD (sell {}, buy {})".format(ticker, pair2)
                  if z_score.iloc[-1] >  2 else "NO TRADE — Z within ±2 band")
    print(f"  Current Signal      : {signal_txt}")
    plt.style.use('dark_background')
    fig, axes = plt.subplots(3, 1, figsize=(16, 14), sharex=True)
    fig.suptitle(f"Pairs Trading: {ticker} vs {pair2}  |  β={beta_h:.3f}",
                 fontsize=16, fontweight='bold')
    norm1 = s1 / s1.iloc[0] * 100
    norm2 = s2 / s2.iloc[0] * 100
    axes[0].plot(common, norm1, color=ACCENT, lw=1.5, label=ticker)
    axes[0].plot(common, norm2, color=ORANGE, lw=1.5, label=pair2)
    axes[0].set_ylabel("Indexed (base=100)"); axes[0].legend()
    axes[0].set_title("Normalised Price Ratio")
    axes[0].grid(alpha=0.3); axes[0].set_facecolor(PANEL_BG)
    axes[1].plot(common, spread, color=PURPLE, lw=1.2, label='Spread')
    axes[1].plot(common, roll_mean, color=ORANGE, ls='--', lw=1, label='Rolling Mean')
    axes[1].fill_between(common, roll_mean - 2*roll_std, roll_mean + 2*roll_std,
                         alpha=0.15, color=ORANGE, label='±2σ Band')
    axes[1].set_ylabel("Spread (₹)"); axes[1].legend()
    axes[1].set_title("Spread = Stock1 − β·Stock2")
    axes[1].grid(alpha=0.3); axes[1].set_facecolor(PANEL_BG)
    axes[2].plot(common, z_score, color=TEAL, lw=1.2, label='Z-Score')
    axes[2].axhline( 2, color=RED,   ls='--', lw=1.5, label='Short signal (+2)')
    axes[2].axhline(-2, color=GREEN, ls='--', lw=1.5, label='Long signal  (−2)')
    axes[2].axhline( 0, color=SUBTEXT, ls=':', lw=0.8)
    axes[2].fill_between(common, z_score,  2, where=(z_score >  2), color=RED,   alpha=0.2)
    axes[2].fill_between(common, z_score, -2, where=(z_score < -2), color=GREEN, alpha=0.2)
    axes[2].set_ylabel("Z-Score"); axes[2].legend()
    axes[2].set_title("Z-Score of Spread (Entry/Exit Signals)")
