def _m25_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title(),
    }
    if not os.path.exists(_M25_CONFIG_FILE):
        return defaults
    try:
        with open(_M25_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**defaults, **data}
    except (json.JSONDecodeError, OSError):
        return defaults
def _m25_save_config(cfg: dict) -> bool:
    payload = {
        "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
        "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
        "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
    }
    try:
        with open(_M25_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  ⚠  Could not save config: {exc}")
        return False
def _m25_setup_key(cfg: dict) -> dict:
    import getpass
    print("\n  ── API Key Setup (Module 25) ────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M25_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m25_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _m25_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models ───────────────────────────")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 54)
    for i, m in enumerate(_M25_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M25_FREE_MODELS):
            sel               = _M25_FREE_MODELS[idx]
            cfg["model_id"]   = sel["id"]
            cfg["model_name"] = sel["name"]
            _m25_save_config(cfg)
            print(f"  [✓] Switched to {sel['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
def _engineer_regime_features(data: pd.DataFrame) -> pd.DataFrame:
    close = data['Close']
    high  = data['High']
    low   = data['Low']
    vol   = data['Volume']
    ret   = close.pct_change()
    data['Vol21'] = ret.rolling(21).std() * np.sqrt(252) * 100
    data['Vol63'] = ret.rolling(63).std() * np.sqrt(252) * 100
    data['MA50']  = close.rolling(50).mean()
    data['MA200'] = close.rolling(200).mean()
    data['Trend'] = (close - data['MA200']) / data['MA200'] * 100
    data['MomRet63'] = close.pct_change(63) * 100
    data['MomRet21'] = close.pct_change(21) * 100
    data['MA50_cross'] = (data['MA50'] - data['MA200']) / data['MA200'] * 100
    delta  = close.diff()
    gain   = delta.clip(lower=0)
    loss   = (-delta).clip(lower=0)
    ag     = gain.ewm(com=13, adjust=False).mean()
    al     = loss.ewm(com=13, adjust=False).mean()
    rs     = ag / al.replace(0, np.nan)
    data['RSI14'] = 100 - (100 / (1 + rs))
    bb_mid   = close.rolling(20).mean()
    bb_std   = close.rolling(20).std()
    bb_upper = bb_mid + 2 * bb_std
    bb_lower = bb_mid - 2 * bb_std
    denom    = (bb_upper - bb_lower).replace(0, np.nan)
    data['BBpctB'] = (close - bb_lower) / denom * 100
    data['VolAccel'] = (data['Vol21'] / data['Vol63'].replace(0, np.nan)) - 1
    trend_mean = data['Trend'].rolling(252).mean()
    trend_std  = data['Trend'].rolling(252).std().replace(0, np.nan)
    data['TrendZ'] = (data['Trend'] - trend_mean) / trend_std
    data['VolRank'] = data['Vol21'].rolling(252).rank(pct=True) * 100
    rolling_high     = close.rolling(252).max()
    data['DrawdownPct'] = (close - rolling_high) / rolling_high * 100
    obv = (np.sign(ret) * vol).cumsum()
    obv_norm = (obv - obv.rolling(252).mean()) / (
        obv.rolling(252).std().replace(0, np.nan)
    )
    data['OBV_slope'] = obv_norm.diff(21)                                   
    return data.dropna()
def _classify_regimes(data: pd.DataFrame) -> pd.DataFrame:
    REGIMES = {
        1: "Strong Bull",
        2: "Volatile Bull",
        3: "Sideways/Chop",
        4: "Mild Bear",
        5: "Crash/Panic",
    }
    n = len(data)
    scores = np.zeros((n, 5))                         
    scores[:, 0] += (data['Trend'].values > 15)  * 30.0                     
    scores[:, 0] += (data['Trend'].values > 5)   * 15.0                
    scores[:, 0] += (data['Vol21'].values < 15)  * 25.0              
    scores[:, 0] += (data['Vol21'].values < 20)  * 15.0         
    scores[:, 0] += (data['MomRet63'].values > 10) * 20.0                     
    scores[:, 0] += (data['MomRet63'].values > 5)  * 10.0
    scores[:, 0] += (data['RSI14'].values > 60)  * 15.0                
    scores[:, 0] += (data['MA50_cross'].values > 2) * 10.0               
    scores[:, 0] += (data['BBpctB'].values > 50) * 5.0                        
    scores[:, 0] += (data['VolAccel'].values < 0) * 10.0                   
    scores[:, 0] += (data['DrawdownPct'].values > -5) * 10.0              
    scores[:, 0] += (data['OBV_slope'].values > 0) * 10.0                  
    scores[:, 1] += (data['Trend'].values > 0)    * 25.0
    scores[:, 1] += (data['Vol21'].values >= 20)  * 20.0
    scores[:, 1] += (data['Vol21'].values < 35)   * 15.0                  
    scores[:, 1] += (data['MomRet63'].values > 0) * 15.0
    scores[:, 1] += (data['VolAccel'].values > 0) * 10.0               
    scores[:, 1] += (data['RSI14'].values > 50)   * 10.0
    scores[:, 1] += (data['BBpctB'].values > 40)  * 5.0
    scores[:, 1] += (data['MomRet21'].values > 0) * 10.0
    scores[:, 1] += (data['TrendZ'].values > 0)   * 10.0
    scores[:, 2] += (np.abs(data['Trend'].values) < 8)  * 25.0
    scores[:, 2] += (np.abs(data['Trend'].values) < 5)  * 15.0
    scores[:, 2] += (data['Vol21'].values >= 12)         * 10.0
    scores[:, 2] += (data['Vol21'].values < 28)          * 15.0
    scores[:, 2] += (np.abs(data['MomRet63'].values) < 8) * 20.0
    scores[:, 2] += (np.abs(data['TrendZ'].values) < 0.5) * 15.0
    scores[:, 2] += (data['RSI14'].values > 40)          * 5.0
    scores[:, 2] += (data['RSI14'].values < 60)          * 5.0
    scores[:, 2] += (np.abs(data['MA50_cross'].values) < 3) * 10.0
    scores[:, 3] += (data['Trend'].values < 0)    * 20.0
    scores[:, 3] += (data['Trend'].values < -5)   * 15.0
    scores[:, 3] += (data['Vol21'].values < 30)   * 15.0                           
    scores[:, 3] += (data['MomRet63'].values < 0) * 20.0
    scores[:, 3] += (data['MomRet21'].values < 0) * 10.0
    scores[:, 3] += (data['RSI14'].values < 50)   * 10.0
    scores[:, 3] += (data['MA50_cross'].values < 0) * 10.0              
    scores[:, 3] += (data['BBpctB'].values < 40)  * 5.0
    scores[:, 3] += (data['OBV_slope'].values < 0) * 10.0                    
    scores[:, 3] += (data['DrawdownPct'].values < -10) * 10.0
    scores[:, 4] += (data['Trend'].values < -10)  * 20.0
    scores[:, 4] += (data['Trend'].values < -20)  * 15.0
    scores[:, 4] += (data['Vol21'].values >= 30)  * 20.0
    scores[:, 4] += (data['Vol21'].values >= 40)  * 15.0                  
    scores[:, 4] += (data['MomRet63'].values < -15) * 20.0
    scores[:, 4] += (data['VolAccel'].values > 0.3) * 10.0                        
    scores[:, 4] += (data['RSI14'].values < 35)   * 10.0
    scores[:, 4] += (data['VolRank'].values > 80) * 10.0                  
    scores[:, 4] += (data['DrawdownPct'].values < -20) * 15.0
    scores[:, 4] += (data['OBV_slope'].values < -0.1) * 10.0
    exp_scores = np.exp(scores / 20.0)
    total      = exp_scores.sum(axis=1, keepdims=True)
    probs      = exp_scores / np.maximum(total, 1e-9) * 100               
    regime_codes = np.argmax(probs, axis=1) + 1              
    confidence   = np.max(probs, axis=1)
    probs_copy   = probs.copy()
    probs_copy[np.arange(n), regime_codes - 1] = -1
    secondary_codes = np.argmax(probs_copy, axis=1) + 1
    data['Regime']       = regime_codes
    data['RegimeConf']   = confidence.round(1)
    data['RegimeSecond'] = secondary_codes
    data['RegimeName']   = data['Regime'].map(REGIMES)
    data['RegimeSecName']= data['RegimeSecond'].map(REGIMES)
    for i, name in REGIMES.items():
        data[f'P_{name.replace("/","_").replace(" ","_")}'] = probs[:, i - 1].round(1)
    return data
def _compute_regime_analytics(data: pd.DataFrame) -> dict:
    REGIMES = {
        1: "Strong Bull",
        2: "Volatile Bull",
        3: "Sideways/Chop",
        4: "Mild Bear",
        5: "Crash/Panic",
    }
    regime_stats = {}
    for code, name in REGIMES.items():
        sub = data[data['Regime'] == code]
        if len(sub) == 0:
            regime_stats[name] = {
                "days": 0, "pct_time": 0,
                "avg_daily_ret_pct": 0, "avg_vol": 0,
                "avg_confidence": 0, "avg_drawdown": 0,
                "sharpe": 0,
            }
            continue
        pct_time = len(sub) / len(data) * 100
        avg_ret  = float(sub['Ret'].mean() * 100)
        avg_vol  = float(sub['Vol21'].mean())
        avg_conf = float(sub['RegimeConf'].mean())
        avg_dd   = float(sub['DrawdownPct'].mean())
        std_ret  = float(sub['Ret'].std())
        sharpe   = (avg_ret / 100 / std_ret * np.sqrt(252)) if std_ret > 0 else 0.0
        regime_stats[name] = {
            "days":              len(sub),
            "pct_time":          round(pct_time, 1),
            "avg_daily_ret_pct": round(avg_ret, 4),
            "avg_vol_pct":       round(avg_vol, 2),
            "avg_confidence":    round(avg_conf, 1),
            "avg_drawdown_pct":  round(avg_dd, 2),
            "annualised_sharpe": round(sharpe, 3),
        }
    trans_counts = np.zeros((5, 5), dtype=int)
    reg_arr = data['Regime'].values
    for i in range(len(reg_arr) - 1):
        cur  = reg_arr[i] - 1                 
        nxt  = reg_arr[i + 1] - 1
        trans_counts[cur, nxt] += 1
    trans_probs = {}
    for i, from_name in REGIMES.items():
        row_sum = trans_counts[i - 1].sum()
        row_probs = {}
        for j, to_name in REGIMES.items():
            row_probs[to_name] = round(
                trans_counts[i - 1][j - 1] / row_sum * 100
                if row_sum > 0 else 0.0, 1
            )
        trans_probs[from_name] = row_probs
    dwell_times = {name: {"runs": [], "avg": 0, "max": 0}
                   for name in REGIMES.values()}
    cur_regime = reg_arr[0]
    cur_count  = 1
    for i in range(1, len(reg_arr)):
        if reg_arr[i] == cur_regime:
            cur_count += 1
        else:
            dwell_times[REGIMES[cur_regime]]["runs"].append(cur_count)
            cur_regime = reg_arr[i]
            cur_count  = 1
    dwell_times[REGIMES[cur_regime]]["runs"].append(cur_count)
    for name, dt in dwell_times.items():
        runs = dt["runs"]
        dt["avg"] = round(float(np.mean(runs)), 1) if runs else 0
        dt["max"] = int(max(runs)) if runs else 0
        del dt["runs"]                                                 
    forward_returns = {}
    close = data['Close']
    for code, name in REGIMES.items():
        idx = data.index[data['Regime'] == code]
        fwd5, fwd21, fwd63 = [], [], []
        for dt in idx:
            pos = data.index.get_loc(dt)
            for horizon, store in [(5, fwd5), (21, fwd21), (63, fwd63)]:
                end_pos = pos + horizon
                if end_pos < len(close):
                    ret = (close.iloc[end_pos] / close.iloc[pos] - 1) * 100
                    store.append(float(ret))
        forward_returns[name] = {
            "fwd_5d_avg_pct":  round(float(np.mean(fwd5)),  2) if fwd5  else None,
            "fwd_21d_avg_pct": round(float(np.mean(fwd21)), 2) if fwd21 else None,
            "fwd_63d_avg_pct": round(float(np.mean(fwd63)), 2) if fwd63 else None,
            "fwd_5d_win_pct":  round(float(np.mean(np.array(fwd5) > 0)) * 100, 1)
                               if fwd5 else None,
        }
    last = data.iloc[-1]
    current = {
        "regime":           str(last['RegimeName']),
        "secondary_regime": str(last['RegimeSecName']),
        "confidence_pct":   float(last['RegimeConf']),
        "vol21_pct":        round(float(last['Vol21']), 2),
        "trend_pct":        round(float(last['Trend']), 2),
        "mom63_pct":        round(float(last['MomRet63']), 2),
        "mom21_pct":        round(float(last['MomRet21']), 2),
        "rsi14":            round(float(last['RSI14']), 1),
        "bb_pctB":          round(float(last['BBpctB']), 1),
        "vol_accel":        round(float(last['VolAccel']), 4),
        "trend_zscore":     round(float(last['TrendZ']), 2),
        "vol_rank_pct":     round(float(last['VolRank']), 1),
        "drawdown_pct":     round(float(last['DrawdownPct']), 2),
        "obv_slope":        round(float(last['OBV_slope']), 4),
        "ma50_cross_pct":   round(float(last['MA50_cross']), 2),
    }
    cur_code = int(last['Regime'])
    recent5  = data.tail(5)
    recent21 = data.tail(21)
    conf5    = float(recent5[recent5['Regime'] == cur_code]['RegimeConf'].mean()
                     if len(recent5[recent5['Regime'] == cur_code]) > 0 else 0)
    conf21   = float(recent21[recent21['Regime'] == cur_code]['RegimeConf'].mean()
                     if len(recent21[recent21['Regime'] == cur_code]) > 0 else 0)
    regime_momentum = "strengthening" if conf5 > conf21 else "weakening"
    return {
        "regime_stats":      regime_stats,
        "transition_matrix": trans_probs,
        "dwell_times":       dwell_times,
        "forward_returns":   forward_returns,
        "current":           current,
        "regime_momentum":   regime_momentum,
        "conf5_vs_conf21": {
            "conf_last5d_avg":  round(conf5, 1),
            "conf_last21d_avg": round(conf21, 1),
        },
    }
def _print_regime_report(ticker: str, analytics: dict) -> None:
    BOLD = '\033[1m'; RST = '\033[0m'; CY = '\033[96m'
    GRN  = '\033[92m'; RED = '\033[91m'; YL = '\033[93m'; MG = '\033[95m'
    REGIME_COLORS = {
        "Strong Bull":    GRN,
        "Volatile Bull":  YL,
        "Sideways/Chop":  CY,
        "Mild Bear":      RED,
        "Crash/Panic":    MG,
    }
    cur = analytics["current"]
    clr = REGIME_COLORS.get(cur["regime"], RST)
    section("Current Regime State")
    print(f"  Primary Regime    : {BOLD}{clr}{cur['regime']}{RST}  "
          f"(confidence: {cur['confidence_pct']:.1f}%)  "
          f"[{analytics['regime_momentum'].upper()}]")
    print(f"  Secondary Regime  : {cur['secondary_regime']}")
    print(f"  21-Day Vol (Ann.) : {cur['vol21_pct']:.1f}%  "
          f"(vol rank: {cur['vol_rank_pct']:.0f}th pctile in past year)")
    print(f"  Price vs MA200    : {cur['trend_pct']:+.1f}%  "
          f"(z-score: {cur['trend_zscore']:+.2f})")
    print(f"  3-Month Momentum  : {cur['mom63_pct']:+.1f}%  "
          f"| 1-Month: {cur['mom21_pct']:+.1f}%")
    print(f"  RSI (14-day)      : {cur['rsi14']:.1f}  "
          f"| BB %B: {cur['bb_pctB']:.1f}%")
    print(f"  Vol Acceleration  : {cur['vol_accel']:+.3f}  "
          f"({'expanding — stress building' if cur['vol_accel'] > 0.05 else 'compressing — calm returning' if cur['vol_accel'] < -0.05 else 'stable'})")
    print(f"  Rolling Drawdown  : {cur['drawdown_pct']:+.1f}%  "
          f"(from 252-day high)")
    print(f"  OBV Slope (21d)   : {cur['obv_slope']:+.4f}  "
          f"({'buying' if cur['obv_slope'] > 0 else 'selling'} pressure)")
    print(f"  MA50 Cross        : {cur['ma50_cross_pct']:+.2f}%  "
          f"({'Golden' if cur['ma50_cross_pct'] > 0 else 'Death'} cross territory)")
    section("Historical Regime Statistics")
    hdr = f"  {'Regime':<16} {'Days':>6} {'%Time':>6} {'AvgDRet':>9} "          f"{'AvgVol':>8} {'AvgConf':>9} {'Sharpe':>8}"
    print(hdr)
    print("  " + "─" * 68)
    for name, st in analytics["regime_stats"].items():
        if st["days"] == 0:
            continue
        clr2 = REGIME_COLORS.get(name, RST)
        print(f"  {clr2}{name:<16}{RST} "
              f"{st['days']:>6} "
              f"{st['pct_time']:>5.1f}% "
              f"{st['avg_daily_ret_pct']:>+8.3f}% "
              f"{st['avg_vol_pct']:>7.1f}% "
              f"{st['avg_confidence']:>8.1f}% "
              f"{st['annualised_sharpe']:>+7.2f}")
    section("Regime Dwell Times (avg / max consecutive days)")
    for name, dt in analytics["dwell_times"].items():
        if dt["avg"] == 0:
            continue
        clr2 = REGIME_COLORS.get(name, RST)
        print(f"  {clr2}{name:<16}{RST} "
              f"avg {dt['avg']:>5.1f} days  |  max {dt['max']:>4} days")
    section("Forward Returns Conditioned on Current Entry Regime")
    print(f"  {'Regime':<16} {'5d avg':>9} {'21d avg':>9} "
          f"{'63d avg':>9} {'5d win%':>9}")
    print("  " + "─" * 55)
    for name, fr in analytics["forward_returns"].items():
        clr2 = REGIME_COLORS.get(name, RST)
        def _fmtr(v):
            return f"{v:>+8.2f}%" if v is not None else "      N/A"
        def _fmtw(v):
            return f"{v:>8.1f}%" if v is not None else "      N/A"
        print(f"  {clr2}{name:<16}{RST} "
              f"{_fmtr(fr['fwd_5d_avg_pct'])} "
              f"{_fmtr(fr['fwd_21d_avg_pct'])} "
              f"{_fmtr(fr['fwd_63d_avg_pct'])} "
              f"{_fmtw(fr['fwd_5d_win_pct'])}")
    section("Regime Transition Matrix  (row=from, col=to, % probability)")
    names = ["Strong Bull", "Volatile Bull", "Sideways/Chop",
             "Mild Bear", "Crash/Panic"]
    short = ["S.Bull", "V.Bull", "Sidew.", "M.Bear", "Crash"]
    print(f"  {'From / To':<16} " + "  ".join(f"{s:>7}" for s in short))
    print("  " + "─" * 60)
    for from_name in names:
        row = analytics["transition_matrix"].get(from_name, {})
        clr2 = REGIME_COLORS.get(from_name, RST)
        vals = [row.get(to, 0) for to in names]
        max_val = max(
            (v for i, v in enumerate(vals) if names[i] != from_name),
            default=0
        )
        cells = []
        for i, v in enumerate(vals):
            if names[i] == from_name:
                cells.append(f"\033[90m{v:>6.1f}%\033[0m")               
            elif v == max_val and max_val > 0:
                cells.append(f"\033[93m{v:>6.1f}%\033[0m")                           
            else:
                cells.append(f"{v:>6.1f}%")
        print(f"  {clr2}{from_name:<16}{RST} " + "  ".join(cells))
def _render_regime_dashboard(
    data:      pd.DataFrame,
    analytics: dict,
    ticker:    str,
) -> None:
    from matplotlib.gridspec import GridSpec
    REGIME_PALETTE = {
        1: '#2ecc71',                          
        2: '#f39c12',                           
        3: '#3498db',                         
        4: '#e74c3c',                        
        5: '#9b59b6',                           
    }
    REGIME_NAMES = {
        1: "Strong Bull",
        2: "Volatile Bull",
        3: "Sideways/Chop",
        4: "Mild Bear",
        5: "Crash/Panic",
    }
    plt.style.use('dark_background')
    BG    = '#0d1117'
    PANEL = '#161b22'
    GRID  = '#2a2a3c'
    fig = plt.figure(figsize=(24, 20), facecolor=BG)
    gs  = GridSpec(
        3, 2, figure=fig,
        height_ratios=[2.2, 1.4, 1.4],
        hspace=0.38, wspace=0.28,
        left=0.05, right=0.97, top=0.93, bottom=0.04,
    )
    ax0 = fig.add_subplot(gs[0, :])                  
    ax1 = fig.add_subplot(gs[1, 0])                             
    ax2 = fig.add_subplot(gs[1, 1])                
    ax3 = fig.add_subplot(gs[2, 0])                
    ax4 = fig.add_subplot(gs[2, 1])                     
    for ax in [ax0, ax1, ax2, ax3, ax4]:
        ax.set_facecolor(PANEL)
        for sp in ax.spines.values():
            sp.set_edgecolor(GRID)
    cur = analytics["current"]
    prev_code = None
    span_start = None
    for i, (dt, row) in enumerate(data.iterrows()):
        code = int(row['Regime'])
        if code != prev_code:
            if prev_code is not None and span_start is not None:
                ax0.axvspan(span_start, dt,
                            alpha=0.15,
                            color=REGIME_PALETTE[prev_code])
            span_start = dt
            prev_code  = code
    if prev_code is not None and span_start is not None:
        ax0.axvspan(span_start, data.index[-1],
                    alpha=0.15, color=REGIME_PALETTE[prev_code])
    ax0.plot(data.index, data['Close'],
             color='#ffffff', lw=1.6, label='Close', zorder=4)
    ax0.plot(data.index, data['MA50'],
             color='#f39c12', lw=1.0, ls='--', alpha=0.8,
             label='MA50', zorder=3)
    ax0.plot(data.index, data['MA200'],
             color='#9b59b6', lw=1.0, ls='--', alpha=0.8,
             label='MA200', zorder=3)
    patches = [mpatches.Patch(color=REGIME_PALETTE[c], alpha=0.6,
                              label=REGIME_NAMES[c])
               for c in range(1, 6)]
    handles, labels = ax0.get_legend_handles_labels()
    ax0.legend(handles + patches, labels + [p.get_label() for p in patches],
               fontsize=8, loc='upper left', ncol=4,
               facecolor='#1a1a2e', edgecolor=GRID, labelcolor='white',
               framealpha=0.9)
    ax0.set_ylabel("Price (₹)", fontsize=10, color='white')
    ax0.set_title(
        f"Price + Regime Shading  |  "
        f"Current: {cur['regime']}  "
        f"(conf {cur['confidence_pct']:.0f}%,  "
        f"{analytics['regime_momentum']})",
        fontsize=12, color='white', pad=8,
    )
    ax0.grid(ls='--', alpha=0.2, zorder=0)
    ax0.tick_params(colors='white', labelsize=8)
    prob_cols = {
        1: f"P_Strong_Bull",
        2: f"P_Volatile_Bull",
        3: f"P_Sideways_Chop",
        4: f"P_Mild_Bear",
        5: f"P_Crash_Panic",
    }
    available = [c for c in prob_cols.values() if c in data.columns]
    if len(available) == 5:
        bottom = np.zeros(len(data))
        for code in range(1, 6):
            col   = prob_cols[code]
            vals  = data[col].values
            ax1.fill_between(data.index, bottom, bottom + vals,
                             color=REGIME_PALETTE[code],
                             alpha=0.75, label=REGIME_NAMES[code])
            bottom += vals
        ax1.set_ylim(0, 100)
        ax1.yaxis.set_major_formatter(
            plt.FuncFormatter(lambda x, _: f"{x:.0f}%")
        )
    ax1.set_title("Regime Probability Distribution (softmax confidence)",
                  fontsize=11, color='white', pad=8)
    ax1.set_ylabel("Probability %", fontsize=9, color='white')
    ax1.tick_params(colors='white', labelsize=8)
    ax1.grid(ls='--', alpha=0.2)
    ax1.legend(fontsize=7, loc='lower left', ncol=2,
               facecolor='#1a1a2e', edgecolor=GRID,
               labelcolor='white', framealpha=0.8)
    ax2.plot(data.index, data['Vol21'],
             color='#f39c12', lw=1.3, label='Vol21 %', zorder=3)
    ax2.fill_between(data.index, data['Vol21'], 0,
                     alpha=0.15, color='#f39c12')
    ax2.axhline(20, color='#f39c12', ls='--', lw=0.8, alpha=0.6,
                label='20% (elevated)')
    ax2.axhline(30, color='#e74c3c', ls='--', lw=0.8, alpha=0.6,
                label='30% (panic)')
    ax2.axhline(40, color='#9b59b6', ls='--', lw=0.8, alpha=0.6,
                label='40% (extreme)')
    ax2.fill_between(data.index, data['Vol21'], 30,
                     where=(data['Vol21'] >= 30),
                     color='#e74c3c', alpha=0.25)
    ax2r = ax2.twinx()
    ax2r.plot(data.index, data['VolAccel'],
              color='#3498db', lw=0.9, alpha=0.7,
              label='Vol Accel (rhs)')
    ax2r.axhline(0, color='white', lw=0.5, alpha=0.4)
    ax2r.fill_between(data.index, data['VolAccel'], 0,
                      where=(data['VolAccel'] > 0),
                      color='#e74c3c', alpha=0.12)
    ax2r.fill_between(data.index, data['VolAccel'], 0,
                      where=(data['VolAccel'] < 0),
                      color='#2ecc71', alpha=0.12)
    ax2r.set_ylabel("Vol Accel", fontsize=8, color='#3498db')
    ax2r.tick_params(colors='#3498db', labelsize=7)
    ax2.set_title("Realised Volatility + Acceleration",
                  fontsize=11, color='white', pad=8)
    ax2.set_ylabel("Ann. Vol %", fontsize=9, color='#f39c12')
    ax2.tick_params(colors='white', labelsize=8)
    ax2.grid(ls='--', alpha=0.2)
    ax2.legend(fontsize=7, loc='upper left',
               facecolor='#1a1a2e', edgecolor=GRID,
               labelcolor='white', framealpha=0.8)
    ax3.plot(data.index, data['RSI14'],
             color='#3498db', lw=1.2, label='RSI 14')
    ax3.axhline(70, color='#e74c3c', ls='--', lw=0.8, alpha=0.6,
                label='OB 70')
    ax3.axhline(50, color='white', lw=0.5, alpha=0.4)
    ax3.axhline(30, color='#2ecc71', ls='--', lw=0.8, alpha=0.6,
                label='OS 30')
    ax3.fill_between(data.index, data['RSI14'], 70,
                     where=(data['RSI14'] >= 70),
                     color='#e74c3c', alpha=0.20)
    ax3.fill_between(data.index, data['RSI14'], 30,
                     where=(data['RSI14'] <= 30),
                     color='#2ecc71', alpha=0.20)
    ax3.set_ylim(0, 100)
    ax3r = ax3.twinx()
    ax3r.plot(data.index, data['BBpctB'],
              color='#f39c12', lw=0.9, alpha=0.8,
              label='BB %B (rhs)')
    ax3r.axhline(100, color='#e74c3c', ls=':', lw=0.8, alpha=0.5)
    ax3r.axhline(0,   color='#2ecc71', ls=':', lw=0.8, alpha=0.5)
    ax3r.set_ylabel("BB %B", fontsize=8, color='#f39c12')
    ax3r.tick_params(colors='#f39c12', labelsize=7)
    ax3.set_title("RSI(14) + Bollinger Band %B",
                  fontsize=11, color='white', pad=8)
    ax3.set_ylabel("RSI", fontsize=9, color='#3498db')
    ax3.tick_params(colors='white', labelsize=8)
    ax3.grid(ls='--', alpha=0.2)
    ax3.legend(fontsize=7, loc='upper left',
               facecolor='#1a1a2e', edgecolor=GRID,
               labelcolor='white', framealpha=0.8)
    ax4.step(data.index, data['Regime'],
             color='white', lw=1.2, where='post', zorder=4, alpha=0.8)
    for code, col in REGIME_PALETTE.items():
        mask = data['Regime'] == code
        ax4.fill_between(data.index, data['Regime'],
                         where=mask, step='post',
                         color=col, alpha=0.40)
    for code in range(1, 6):
        ax4.axhline(code, color=REGIME_PALETTE[code],
                    ls=':', lw=0.7, alpha=0.5)
    ax4r = ax4.twinx()
    ax4r.fill_between(data.index, data['DrawdownPct'], 0,
                      where=(data['DrawdownPct'] <= 0),
                      color='#e74c3c', alpha=0.25,
                      label='Drawdown %')
    ax4r.plot(data.index, data['DrawdownPct'],
              color='#e74c3c', lw=0.8, alpha=0.7)
    ax4r.axhline(-20, color='#e74c3c', ls='--', lw=0.7, alpha=0.5)
    ax4r.set_ylabel("Drawdown %", fontsize=8, color='#e74c3c')
    ax4r.tick_params(colors='#e74c3c', labelsize=7)
    ax4.set_yticks(list(range(1, 6)))
    ax4.set_yticklabels(
        [REGIME_NAMES[c] for c in range(1, 6)],
        fontsize=7.5, color='white',
    )
    ax4.set_title("Regime Timeline + Rolling Drawdown",
                  fontsize=11, color='white', pad=8)
    ax4.tick_params(colors='white', labelsize=8)
    ax4.grid(ls='--', alpha=0.2)
    for ax in [ax1, ax2, ax3, ax4]:
        ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
        ax.xaxis.set_major_locator(mdates.YearLocator())
        plt.setp(ax.get_xticklabels(), rotation=0,
                 color='white', fontsize=8)
    fig.suptitle(
        f"Market Regime Detection  |  {ticker.upper()}  "
        f"|  Current: {cur['regime']}  "
        f"(conf {cur['confidence_pct']:.0f}%)  "
        f"|  Vol {cur['vol21_pct']:.1f}%  "
        f"|  Trend {cur['trend_pct']:+.1f}%  "
        f"|  RSI {cur['rsi14']:.0f}",
        fontsize=13, fontweight='bold', color='white', y=0.96,
    )
    plt.show()
def _build_regime_context(ticker: str, analytics: dict) -> dict:
    import math as _m
    def _s(v, dp=4):
        if v is None:
            return None
        try:
            f = float(v)
            return None if (_m.isnan(f) or _m.isinf(f)) else round(f, dp)
        except (TypeError, ValueError):
            return None
    def _sanitise(obj):
        if isinstance(obj, dict):
            return {k: _sanitise(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_sanitise(v) for v in obj]
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating,)):
            v = float(obj)
            return None if (_m.isnan(v) or _m.isinf(v)) else v
        if isinstance(obj, (np.bool_,)):
            return bool(obj)
        return obj
    return _sanitise({
        "ticker": ticker,
        "analysis_period": "5 years daily",
        "regime_system": {
            "n_regimes": 5,
            "features_used": 12,
            "scoring_method": "Weighted evidence accumulation + softmax normalisation",
            "regimes": [
                "Strong Bull: trend>10%, vol<20%, momentum>5%",
                "Volatile Bull: trend>0%, vol≥20%, momentum>0%",
                "Sideways/Chop: |trend|<8%, vol 12-28%",
                "Mild Bear: trend<0%, vol<30%, negative momentum",
                "Crash/Panic: trend<-10%, vol≥30%, very negative momentum",
            ],
        },
        "current_state":     analytics["current"],
        "regime_momentum":   analytics["regime_momentum"],
        "regime_statistics": analytics["regime_stats"],
        "dwell_times":       analytics["dwell_times"],
        "forward_returns":   analytics["forward_returns"],
        "transition_matrix": analytics["transition_matrix"],
        "confidence_trend":  analytics["conf5_vs_conf21"],
    })
def _build_m25_system_prompt(ctx: dict, model_name: str) -> str:
    cur    = ctx.get("current_state", {})
    ticker = ctx.get("ticker", "Unknown")
    regime = cur.get("regime", "Unknown")
    conf   = cur.get("confidence_pct", 0)
    mom    = ctx.get("regime_momentum", "unknown")
    persona = textwrap.dedent(f"""\
        You are a senior Quantitative Strategist specialising in market regime
        analysis for Indian equity markets. You have just completed a full
        5-year regime detection study for {ticker} using a 12-feature,
        5-regime probabilistic classifier.
        The current regime is {regime} with {conf:.0f}% model confidence
        and is {mom} (confidence rising/falling in recent days vs. 21-day avg).
        You are powered by {model_name}.
        Be precise — cite specific numbers. Explain regime concepts in plain
        English. Connect every metric to the investor's actual decision:
        "should I buy, hold, reduce, or hedge?"
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in <regime_data> below. Do not invent values.
        2. Always cite the exact metric value when making a claim
           (e.g. "Vol21 is 28.4%, above the 20% elevated threshold").
        3. Lead with the single most actionable insight for the current regime.
        4. When discussing forward returns, contextualise them:
           "Entering during Crash/Panic has historically returned +X% over
           the next 63 days on average — but with Y% win rate."
        5. The transition matrix shows what regime historically follows this one.
           Use it to discuss what the NEXT regime is most likely to be.
        6. Regime momentum (strengthening vs weakening) tells you whether
           the current regime is consolidating or approaching a transition.
           Always mention this in your analysis.
        7. Dwell times tell you how long regimes typically last — use this
           to advise on time horizon ("this regime typically lasts X days,
           so a trade needs at least a Y-day horizon").
        8. Keep responses under 450 words unless the user asks for more.
        9. If a metric is missing from the data, say so.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Prefix every response: [REGIME] | [FORWARD] | [TRANSITION] |
          [RISK] | [ANSWER] | [INFO]
        - **Bold** regime names and key metric values.
        - Use > blockquotes for critical regime warnings
          (Crash/Panic, unrecovered drawdown, vol rank > 80%).
        - Use Markdown tables for comparing forward returns or
          transition probabilities across regimes.
        - Express vol as percentage (28.4% not 0.284).
    """)
    data_json  = json.dumps(ctx, indent=2)
    data_block = f"<regime_data>\n{data_json}\n</regime_data>"
    return "\n\n".join([persona, rules, fmt, data_block])
def _m25_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS  = 20
    turn_count = (len(history) - 1) // 2
    if turn_count > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 25 Regime Detection CoPilot",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    model_id,
        "messages": history,
        "stream":   True,
    }
    BACKOFF_BASE  = 1.5
    MAX_RETRIES   = 3
    full_response = ""
    last_error    = None
    for attempt in range(MAX_RETRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers,
                json=payload,
                stream=True,
                timeout=(10, 60),
            )
            if resp.status_code == 401:
                console.print(
                    "\n  [bold red][!] API key rejected (401). "
                    "Use /setkey to update.[/bold red]"
                )
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            token_count = 0
            print(f"\n  \033[90m{model_name} is analysing regime data ",
                  end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        token_count   += len(token.split())
                        if token_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({token_count} words)\033[0m\n")
            if full_response.strip():
                console.print(
                    Panel(
                        Markdown(full_response),
                        title=f"[bold cyan]{model_name}[/bold cyan]",
                        border_style="cyan",
                        padding=(1, 2),
                        expand=True,
                    )
                )
            return full_response
        except requests.Timeout:
            console.print(
                "\n  [bold red][!] Timed out. "
                "Try shorter question or /models.[/bold red]"
            )
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < MAX_RETRIES - 1:
                wait = BACKOFF_BASE ** (attempt + 1)
                console.print(
                    f"  [yellow][~] Attempt {attempt+1} failed ({exc}). "
                    f"Retrying in {wait:.1f}s…[/yellow]"
                )
                time.sleep(wait)
            else:
                console.print(
                    f"  [bold red][!] All {MAX_RETRIES} attempts failed: "
                    f"{last_error}[/bold red]"
                )
    return ""
def _print_m25_chat_help() -> None:
    print("\n  ── Module 25 Regime Co-Pilot Commands ───────────────")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by full OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter API"),
        ("/clear",       "Clear conversation (keep regime data)"),
        ("/export",      "Save session to a timestamped JSON file"),
        ("/status",      "Show model, key, current regime, history"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to the main terminal"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m25_chat(ticker: str, analytics: dict) -> None:
    cfg = _m25_load_config()
    if not cfg["api_key"]:
        print(
            "\n  \033[93m[!] No API key configured for the "
            "Regime Detection Co-Pilot.\033[0m"
        )
        cfg = _m25_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Run module again to configure.")
            return
    ctx = _build_regime_context(ticker, analytics)
    history = [
        {
            "role":    "system",
            "content": _build_m25_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    cur  = analytics["current"]
    from rich.console import Console
    from rich.panel   import Panel
    console = Console()
    console.print(Panel(
        f"[bold]Model:[/]   [cyan]{cfg['model_name']}[/cyan]\n"
        f"[bold]Ticker:[/]  [yellow]{ticker}[/yellow]  |  "
        f"5-year daily analysis\n"
        f"[bold]Regime:[/]  [green]{cur['regime']}[/green]  "
        f"({cur['confidence_pct']:.0f}% confidence, "
        f"{analytics['regime_momentum']})\n"
        f"[bold]State:[/]   "
        f"Vol {cur['vol21_pct']:.1f}%  |  "
        f"Trend {cur['trend_pct']:+.1f}%  |  "
        f"RSI {cur['rsi14']:.0f}  |  "
        f"Drawdown {cur['drawdown_pct']:+.1f}%\n\n"
        f"[dim]Ask about the current regime, forward returns, "
        f"transition probabilities, or any feature. /help for commands.[/dim]",
        title="[bold cyan]🧠 MARKET REGIME CO-PILOT[/bold cyan]",
        border_style="cyan",
        padding=(0, 2),
    ))
    fwd  = analytics["forward_returns"].get(cur["regime"], {})
    trans= analytics["transition_matrix"].get(cur["regime"], {})
    next_likely = max(trans, key=trans.get) if trans else "unknown"
    first_prompt = (
        f"I've just completed a 5-year market regime analysis for {ticker}. "
        f"The current regime is {cur['regime']} with {cur['confidence_pct']:.0f}% "
        f"confidence. The regime is {analytics['regime_momentum']} "
        f"(5-day confidence avg vs 21-day avg). "
        f"Give me a comprehensive integrated analysis: "
        f"(1) interpret every feature in the current state — what does "
        f"Vol {cur['vol21_pct']:.1f}%, Trend {cur['trend_pct']:+.1f}%, "
        f"RSI {cur['rsi14']:.0f}, BB%B {cur['bb_pctB']:.1f}%, "
        f"Vol acceleration {cur['vol_accel']:+.3f}, "
        f"and drawdown {cur['drawdown_pct']:+.1f}% collectively say about "
        f"where we are in the market cycle? "
        f"(2) based on the forward returns table, what has historically "
        f"happened after entering during this regime — give the 5/21/63-day "
        f"averages and win rates and what they mean for position sizing; "
        f"(3) the transition matrix says the most likely next regime is "
        f"{next_likely} — explain what conditions would trigger that transition "
        f"and what warning signs to watch for; "
        f"(4) the regime dwell time analysis — how much longer might this "
        f"regime last based on historical averages, and what does that mean "
        f"for a trader deciding whether to enter now or wait; "
        f"(5) the single most important action a trader should take right now "
        f"based on everything in the analysis."
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m25_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        console.print(
            "[bold red][!] Auto-analysis failed. "
            "You can still ask questions below.[/bold red]\n"
        )
    while True:
        try:
            from rich.console import Console as _C
            _con       = _C()
            user_input = _con.input(
                "\n  [bold cyan]You ›[/bold cyan] "
            ).strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Co-Pilot session ended]")
            break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m25_chat_help()
            continue
        elif cmd == "/setkey":
            cfg = _m25_setup_key(cfg)
            history[0] = {"role": "system",
                          "content": _build_m25_system_prompt(ctx, cfg["model_name"])}
            continue
        elif cmd == "/models":
            cfg = _m25_pick_model(cfg)
            history[0] = {"role": "system",
                          "content": _build_m25_system_prompt(ctx, cfg["model_name"])}
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}")
                print("  Usage:   /model <openrouter-model-id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = (arg.split("/")[-1]
                                     .replace(":free", " (free)")
                                     .replace("-", " ").title())
                _m25_save_config(cfg)
                history[0] = {"role": "system",
                              "content": _build_m25_system_prompt(ctx, cfg["model_name"])}
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get(
                    "http://127.0.0.1:9999/disabled", timeout=10
                )
                resp.raise_for_status()
                free = [m for m in resp.json().get("data", [])
                        if m.get("id", "").endswith(":free")]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    ctx_k = (m.get("context_length") or 0) // 1000
                    print(f"  {m['id']:<55} {ctx_k:>5}K")
                print(f"\n  {len(free)} free models. Activate: /model <id>\n")
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Regime data retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns    = (len(history) - 1) // 2
            key_hint = (f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}"
                        if len(cfg["api_key"]) > 12 else "not set")
            print(f"\n  Model    : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key  : {key_hint}")
            print(f"  Ticker   : {ticker}  |  "
                  f"Regime: {cur['regime']} ({cur['confidence_pct']:.0f}%)")
            print(f"  History  : {turns} turns (max 20 before auto-prune)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help.")
            continue
        history.append({"role": "user", "content": user_input})
        ai_response = _m25_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_response:
            history.append({"role": "assistant", "content": ai_response})
        else:
            history.pop()
    print("  [Co-Pilot closed — returning to terminal]\n")
def run_regime_detection(ticker: str) -> None:
    header(f"MODULE 25 — MARKET REGIME DETECTION  |  {ticker}")
    print("  Downloading 5-year daily OHLCV data …")
    plt.style.use('dark_background')
    raw = yf.download(ticker, period="5y", interval="1d", progress=False)
    if raw is None or raw.empty:
        print(f"  ✗ No data returned for '{ticker}'. Check the symbol.")
        press_enter(); return
    data = flatten_cols(raw)
    required = {"Close", "High", "Low", "Volume"}
    if not required.issubset(data.columns):
        print(f"  ✗ Missing columns after flatten: "
              f"{required - set(data.columns)}")
        press_enter(); return
    if data.index.tz is not None:
        data.index = data.index.tz_convert("UTC").tz_localize(None)
    data['Ret'] = data['Close'].pct_change()
    print("  Engineering 12 regime features …")
    data = _engineer_regime_features(data)
    if len(data) < 100:
        print("  ✗ Insufficient data after feature engineering "
              "(need ≥ 100 bars).")
        press_enter(); return
    print("  Classifying regimes with 5-regime probabilistic scorer …")
    data = _classify_regimes(data)
    print("  Computing analytics: transitions, dwell times, "
          "forward returns …\n")
    analytics = _compute_regime_analytics(data)
    _print_regime_report(ticker, analytics)
    _render_regime_dashboard(data, analytics, ticker)
    print(f"\n  {'─' * 54}")
    try:
        launch = input(
            "  Open AI Co-Pilot to analyse these regime results? [Y/n]: "
        ).strip().lower()
    except (EOFError, KeyboardInterrupt):
        launch = "n"
    if launch not in {"n", "no"}:
        run_m25_chat(ticker, analytics)
    else:
        press_enter()
def run_forensic_accounting(ticker):
    header(f"MODULE 15 — FORENSIC ACCOUNTING & BENEISH M-SCORE  |  {ticker}")
    print("  Extracting 2-year financial data for forensic analysis …")
    stock = yf.Ticker(ticker)
    inc   = stock.income_stmt.dropna(how='all')
    bal   = stock.balance_sheet.dropna(how='all')
    cf    = stock.cash_flow.dropna(how='all')
    if inc.shape[1] < 2 or bal.shape[1] < 2:
        print("  ⚠  Insufficient financial data."); press_enter(); return
    def gv(df, keys, col=0):
        return get_val(df, keys, col, 0)
    rev_t   = gv(inc, ['Total Revenue','Operating Revenue'], 0)
    rev_t1  = gv(inc, ['Total Revenue','Operating Revenue'], 1)
    gp_t    = gv(inc, ['Gross Profit'], 0)
    gp_t1   = gv(inc, ['Gross Profit'], 1)
    ni_t    = gv(inc, ['Net Income','Net Income Common Stockholders'], 0)
    ni_t1   = gv(inc, ['Net Income','Net Income Common Stockholders'], 1)
    cfo_t   = gv(cf,  ['Operating Cash Flow','Total Cash From Operating Activities'], 0)
    ta_t    = gv(bal, ['Total Assets'], 0)
    ta_t1   = gv(bal, ['Total Assets'], 1)
    rec_t   = gv(bal, ['Accounts Receivable','Net Receivables'], 0)
    rec_t1  = gv(bal, ['Accounts Receivable','Net Receivables'], 1)
    ca_t    = gv(bal, ['Current Assets','Total Current Assets'], 0)
    ca_t1   = gv(bal, ['Current Assets','Total Current Assets'], 1)
    cl_t    = gv(bal, ['Current Liabilities','Total Current Liabilities'], 0)
    cl_t1   = gv(bal, ['Current Liabilities','Total Current Liabilities'], 1)
    ppe_t   = gv(bal, ['Net PPE','Property Plant Equipment'], 0)
    ppe_t1  = gv(bal, ['Net PPE','Property Plant Equipment'], 1)
    dep_t   = abs(gv(cf,  ['Depreciation','Depreciation And Amortization'], 0))
    ltd_t   = gv(bal, ['Long Term Debt','Total Long Term Debt'], 0)
    ltd_t1  = gv(bal, ['Long Term Debt','Total Long Term Debt'], 1)
    sga_t   = abs(gv(inc, ['Selling General And Administration','Selling General Administrative'], 0))
    sga_t1  = abs(gv(inc, ['Selling General And Administration','Selling General Administrative'], 1))
    dsri = ((rec_t / rev_t) / (rec_t1 / rev_t1)) if (rev_t > 0 and rev_t1 > 0 and rec_t1 > 0) else 1
    gmi  = ((gp_t1 / rev_t1) / (gp_t / rev_t)) if (rev_t > 0 and rev_t1 > 0 and gp_t > 0) else 1
    nca_t  = ta_t  - ca_t  - ppe_t
    nca_t1 = ta_t1 - ca_t1 - ppe_t1
    aqi  = (nca_t / ta_t) / (nca_t1 / ta_t1) if (ta_t > 0 and ta_t1 > 0 and nca_t1 != 0) else 1
    sgi  = (rev_t / rev_t1) if rev_t1 > 0 else 1
    depi = (dep_t1 := abs(gv(cf, ['Depreciation','Depreciation And Amortization'], 1)))
    depi = ((dep_t1 / (dep_t1 + ppe_t1)) / (dep_t / (dep_t + ppe_t)))           if (dep_t > 0 and ppe_t > 0 and dep_t1 > 0 and ppe_t1 > 0) else 1
    sgai = ((sga_t / rev_t) / (sga_t1 / rev_t1)) if (rev_t > 0 and rev_t1 > 0 and sga_t1 > 0) else 1
    lvgi = ((ltd_t / ta_t) / (ltd_t1 / ta_t1)) if (ta_t > 0 and ta_t1 > 0 and ltd_t1 > 0) else 1
    tata = (ni_t - cfo_t) / ta_t if ta_t > 0 else 0
    M = (-4.84
         + 0.920 * dsri
         + 0.528 * gmi
         + 0.404 * aqi
         + 0.892 * sgi
         + 0.115 * depi
         - 0.172 * sgai
         + 4.679 * tata
         - 0.327 * lvgi)
    risk = ("HIGH MANIPULATION RISK ⚠" if M > -1.78 else
            "MODERATE RISK (Grey Zone)"  if M > -2.22 else
            "LOW MANIPULATION RISK ✔")
    risk_col = ("\033[91m" if M > -1.78 else "\033[93m" if M > -2.22 else "\033[92m")
    sloan = (ni_t - cfo_t) / ta_t if ta_t > 0 else 0
    sloan_flag = "⚠ High Accruals" if abs(sloan) > 0.1 else "✔ Normal Accruals"
    cfo_ni = cfo_t / ni_t if ni_t > 0 else 0
    cfo_flag = "✔ Cash-backed"   if cfo_ni > 1.0 else               "⚠ Low Cash Backing" if cfo_ni > 0 else "⚠ Negative CFO"
    try:
        roe_list, roa_list, yr_list = [], [], []
        for i in range(min(inc.shape[1], bal.shape[1])):
            ni_i  = gv(inc, ['Net Income','Net Income Common Stockholders'], i)
            ta_i  = gv(bal, ['Total Assets'], i)
            eq_i  = gv(bal, ['Stockholders Equity','Total Equity Gross Minority Interest'], i)
            if ta_i > 0 and eq_i > 0:
                roa_list.append(ni_i / ta_i * 100)
                roe_list.append(ni_i / eq_i * 100)
                yr_list.append(str(inc.columns[i]).split('-')[0])
        yr_list = yr_list[::-1]; roa_list = roa_list[::-1]; roe_list = roe_list[::-1]
    except Exception:
        yr_list, roa_list, roe_list = [], [], []
    section("Beneish M-Score")
    print(f"  M-Score Value : {M:.4f}")
    print(f"  Risk Level    : {risk_col}{risk}\033[0m")
    print(f"  Threshold     : > -1.78 = Likely Manipulator  |  < -2.22 = Unlikely")
    section("M-Score Components")
    rows_m = [
        ("DSRI (Receivables inflated?)",     dsri, "> 1.46 ⚠" if dsri > 1.46 else "Normal"),
        ("GMI  (Gross margin declining?)",   gmi,  "> 1.19 ⚠" if gmi  > 1.19 else "Normal"),
        ("AQI  (Asset quality falling?)",    aqi,  "> 1.25 ⚠" if aqi  > 1.25 else "Normal"),
        ("SGI  (Revenue growth high?)",      sgi,  "> 1.60 ⚠" if sgi  > 1.60 else "Normal"),
        ("DEPI (Depreciation slowing?)",     depi, "> 1.08 ⚠" if depi > 1.08 else "Normal"),
        ("SGAI (SGA growing faster?)",       sgai, "> 1.02 ⚠" if sgai > 1.02 else "Normal"),
        ("LVGI (Leverage rising?)",          lvgi, "> 1.11 ⚠" if lvgi > 1.11 else "Normal"),
        ("TATA (Accruals high?)",            tata, "> 0.031 ⚠" if tata > 0.031 else "Normal"),
    ]
    for name, val, flag in rows_m:
        col = "\033[91m" if "⚠" in flag else "\033[92m"
        print(f"  {name:<38} {val:>8.4f}   {col}{flag}\033[0m")
    section("Additional Quality Checks")
    print(f"  Sloan Accruals Ratio : {sloan:+.4f}  →  {sloan_flag}")
    print(f"  CFO / Net Income     : {cfo_ni:.2f}x  →  {cfo_flag}")
    if yr_list:
        plt.style.use('dark_background')
        fig, axes = plt.subplots(1, 3, figsize=(18, 7))
        fig.suptitle(f"Forensic Accounting Dashboard: {ticker}",
                     fontsize=16, fontweight='bold')
        axes[0].axis('off')
        gauge_col = RED if M > -1.78 else ORANGE if M > -2.22 else GREEN
        axes[0].text(0.5, 0.75, f"Beneish M-Score", ha='center', fontsize=15, color=TEXT)
        axes[0].text(0.5, 0.55, f"{M:.3f}", ha='center', fontsize=42, color=gauge_col, weight='bold')
        axes[0].text(0.5, 0.35, risk, ha='center', fontsize=13, color=gauge_col,
                     bbox=dict(facecolor=gauge_col, alpha=0.15, boxstyle='round,pad=0.4'))
        axes[0].text(0.5, 0.15,
                     f"Sloan Ratio: {sloan:+.3f}\nCFO/NI ratio: {cfo_ni:.2f}x",
                     ha='center', fontsize=12, color=SUBTEXT, family='monospace')
        axes[0].set_facecolor(PANEL_BG)
        axes[1].plot(yr_list, roa_list, marker='o', lw=2, color=ACCENT, label='ROA %')
        axes[1].axhline(0, color='white', lw=1)
        axes[1].fill_between(yr_list, roa_list, 0,
                             where=[r >= 0 for r in roa_list], color=GREEN, alpha=0.15)
        axes[1].fill_between(yr_list, roa_list, 0,
                             where=[r < 0  for r in roa_list], color=RED,   alpha=0.15)
        axes[1].set_title("Return on Assets Trend (%)"); axes[1].legend()
        axes[1].grid(alpha=0.3); axes[1].set_facecolor(PANEL_BG)
        axes[2].plot(yr_list, roe_list, marker='s', lw=2, color=PURPLE, label='ROE %')
        axes[2].axhline(0, color='white', lw=1)
        axes[2].fill_between(yr_list, roe_list, 0,
                             where=[r >= 0 for r in roe_list], color=GREEN, alpha=0.15)
        axes[2].fill_between(yr_list, roe_list, 0,
                             where=[r < 0  for r in roe_list], color=RED,   alpha=0.15)
        axes[2].set_title("Return on Equity Trend (%)"); axes[2].legend()
        axes[2].grid(alpha=0.3); axes[2].set_facecolor(PANEL_BG)
        for ax in axes:
            for sp in ax.spines.values(): sp.set_edgecolor(GRID)
            ax.tick_params(colors=SUBTEXT)
        fig.patch.set_facecolor(BG)
        plt.tight_layout()
        plt.show()
    press_enter()
