    def save_checkpoint(self) -> None:
        from rich.console import Console
        if not self._mc_done:
            Console().print("  [red]Nothing to save.[/]")
            return
        data = {
            'ticker'        : self.ticker,
            'final_models'  : self._final_models,
            'weights'       : self._weights,
            'model_names'   : self._model_names,
            'model_ic'      : self._model_ic,
            'model_da'      : self._model_da,
            'model_rmse'    : self._model_rmse,
            'scaler'        : self._scaler,
            'ens_ic'        : self._ens_ic,
            'ens_da'        : self._ens_da,
            'garch_omega'   : self._garch_omega,
            'garch_alpha'   : self._garch_alpha,
            'garch_beta'    : self._garch_beta,
            'daily_vol'     : self._daily_vol,
            'current_price' : self._current_price,
            'prob_up'       : self._prob_up,
            'var_95'        : self._var_95,
            'cvar_95'       : self._cvar_95,
            'sharpe_mc'     : self._sharpe_mc,
            'exp_ret'       : self._exp_ret,
            'last_hurst'    : self._last_hurst,
            'feature_cols'  : self._feature_cols,
        }
        try:
            with open(self._ckpt_path(), 'wb') as f:
                pickle.dump(data, f)
            Console().print(f"  [green]✓ Checkpoint → {self._ckpt_path()}[/]")
        except Exception as e:
            Console().print(f"  [red]Save failed: {e}[/]")
    def _ai_call(self, sys_p: str, user_p: str) -> tuple:
        if not self._or_key:
            return "[AI UNAVAILABLE] Configure API key in Settings.", 0.0
        bag  = {}
        done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization": f"Bearer {self._or_key}",
                             "Content-Type": "application/json",
                             "X-Title": "Module9-ForecastEngine"},
                    json={"model": self._or_model,
                          "messages": [{"role": "system", "content": sys_p},
                                       {"role": "user",   "content": user_p}],
                          "temperature": 0.3},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter() - t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter() - t0
            finally:
                done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"
        i = 0
        t0 = time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i % len(spin)]} AI thinking… "
                  f"{time.perf_counter()-t0:.1f}s   ", end="", flush=True)
            i += 1
        print()
        return bag.get("reply", ""), bag.get("latency", 0.0)
    def _build_ai_digest(self) -> str:
        persist = self._garch_alpha + self._garch_beta
        verdct, _ = self._verdict()
        ou  = float(self._df['ou_theta'].iloc[-1]) if 'ou_theta' in self._df else 0.0
        ent = float(self._df['entropy'].iloc[-1])  if 'entropy'  in self._df else 1.0
        cp  = self._current_price
        lines = [
            f"=== QUANTITATIVE PRICE FORECAST — {self.ticker} ===",
            f"",
            f"CURRENT PRICE (LIVE): ₹{cp:,.2f}",
            f"FORECAST HORIZON: {self.HORIZON} trading days",
            f"",
            f"MONTE CARLO RESULTS ({self.N_PATHS} paths, start=₹{cp:,.2f}):",
            f"  Bear (5th pct):  ₹{self._p5[-1]:,.2f}  "
            f"({(self._p5[-1]/cp-1)*100:+.1f}%)",
            f"  Low  (25th pct): ₹{self._p25[-1]:,.2f}  "
            f"({(self._p25[-1]/cp-1)*100:+.1f}%)",
            f"  Base (Median):   ₹{self._p50[-1]:,.2f}  "
            f"({(self._p50[-1]/cp-1)*100:+.1f}%)",
            f"  High (75th pct): ₹{self._p75[-1]:,.2f}  "
            f"({(self._p75[-1]/cp-1)*100:+.1f}%)",
            f"  Bull (95th pct): ₹{self._p95[-1]:,.2f}  "
            f"({(self._p95[-1]/cp-1)*100:+.1f}%)",
            f"  Expected Return: {self._exp_ret:+.1f}%",
            f"  P(price rises):  {self._prob_up:.1f}%",
            f"  95% VaR:         {self._var_95:+.1f}%",
            f"  95% CVaR/ES:     {self._cvar_95:+.1f}%",
            f"  MC Sharpe:       {self._sharpe_mc:.2f}",
            f"",
            f"GARCH(1,1) PARAMETERS:",
            f"  ω={self._garch_omega:.2e}  α={self._garch_alpha:.4f}  "
            f"β={self._garch_beta:.4f}  Persistence={persist:.4f}",
            f"  Daily vol: {self._daily_vol*100:.3f}%  "
            f"({self._daily_vol*252**0.5*100:.1f}% ann.)",
            f"",
            f"REGIME SIGNALS:",
            f"  Hurst: {self._last_hurst:.3f}  "
            f"({'Trending' if self._last_hurst>0.55 else 'Mean-Reverting' if self._last_hurst<0.45 else 'Random Walk'})",
            f"  OU Reversion θ: {ou:.2f}/yr",
            f"  Entropy: {ent:.3f}",
            f"  Drift Decay: {self._drift_decay:.0%}",
            f"  Adj Daily Drift: {self._adj_drift*100:+.4f}%",
            f"",
            f"ML ENSEMBLE:",
            f"  Models: {', '.join(self._model_names)}",
            f"  Ensemble IC: {self._ens_ic:.4f}",
            f"  Dir. Accuracy: {self._ens_da:.1f}%",
        ]
        for m in self._model_names:
            lines.append(
                f"  {m:<14}: IC={self._model_ic[m]:.3f}  "
                f"DA={self._model_da[m]:.1f}%  "
                f"W={self._weights[m]:.1%}"
            )
        lines += ["", f"OVERALL VERDICT: {verdct}"]
        return "\n".join(lines)
    def run_ai_forecast_analyst(self) -> str:
        from rich.console  import Console
