    def __init__(self, ticker: str):
        self.ticker   = ticker.upper().strip()
        self.ticker_ns= self.ticker if '.' in self.ticker                        else self.ticker + ".NS"
        self.period   = "1y"
        self.n_bars   = 252
        self.per_label= "1 Year"
        self._df      = None              
        self._info    : dict = {}
        self._bench_ret = None                                 
        self._ind_series: dict = {}                    
        self._signals : list[dict] = []
        self._selected_keys : list[str] = []
        self._compare_tickers: list[str] = []
        self._cache_dir = Path(".dash_cache"); self._cache_dir.mkdir(exist_ok=True)
        self._or_key   = _GLOBAL_OR_KEY
        self._or_model = _GLOBAL_OR_MODEL
        self._load_or_config()
    def _load_or_config(self):
        self._or_key   = _GLOBAL_OR_KEY
        self._or_model = _GLOBAL_OR_MODEL
    def _save_or_config(self):
        try:
            existing = {}
            if p.exists():
                try: existing = json.loads(p.read_text(encoding="utf-8"))
                except: pass
            existing.update({"api_key":self._or_key,"model":self._or_model})
            p.write_text(json.dumps(existing,indent=2),encoding="utf-8")
        except: pass
    def _cache_key(self, sym:str, period:str) -> str:
        h = hashlib.md5(f"{sym}:{period}".encode()).hexdigest()[:10]
        return h
    def _cache_valid(self, key:str) -> bool:
        p = self._cache_dir / f"{key}.pkl"
        return p.exists() and (time.time()-p.stat().st_mtime) < 600
    def _load_cache(self, key:str):
        import pickle
        try:
            with open(self._cache_dir/f"{key}.pkl",'rb') as f: return pickle.load(f)
        except: return None
    def _save_cache(self, key:str, obj):
        import pickle
        try:
            with open(self._cache_dir/f"{key}.pkl",'wb') as f: pickle.dump(obj,f)
        except: pass
    def load_data(self) -> bool:
        from rich.console import Console
        from rich.rule    import Rule
        console = Console()
        console.print(Rule(f"[bold cyan]Data Fetch — {self.ticker}[/]"))
        ck = self._cache_key(self.ticker_ns, self.period)
        if self._cache_valid(ck):
            cached = self._load_cache(ck)
            if cached:
                self._df, self._info = cached
                console.print(f"  [dim]Cache: {len(self._df)} bars ({self.period})[/]")
                return True
        console.print(f"  [dim]Downloading {self.ticker_ns} ({self.period})…[/]")
        try:
            tk  = yf.Ticker(self.ticker_ns)
            raw = tk.history(period=self.period, interval="1d")
            raw = flatten_cols(raw)
            if raw.empty or len(raw) < 30:
                console.print("  [red]✗ Insufficient data.[/]"); return False
            self._df = raw[['Open','High','Low','Close','Volume']].copy().dropna()
            try:   self._info = tk.info or {}
            except: self._info = {}
            self._save_cache(ck, (self._df, self._info))
            console.print(
                f"  [green]✓[/] {len(self._df)} bars  "
                f"({self._df.index[0].date()} → {self._df.index[-1].date()})"
            )
        except Exception as e:
            console.print(f"  [red]✗ {e}[/]"); return False
        try:
            bk  = self._cache_key("^NSEI", self.period)
            if self._cache_valid(bk):
                bench = self._load_cache(bk)
            else:
                bm   = yf.download("^NSEI", period=self.period,
                                   interval="1d", progress=False,
                                   auto_adjust=True)
                bm   = flatten_cols(bm)
                bench= np.log(bm['Close']/bm['Close'].shift(1)).dropna()                       if not bm.empty else None
                self._save_cache(bk, bench)
            self._bench_ret = bench
        except: self._bench_ret = None
        return True
    def compute_indicators(self, keys: list[str]) -> bool:
        from rich.console  import Console
        from rich.progress import Progress, BarColumn, TextColumn
        console = Console()
        df = self._df
        C  = df['Close'].astype(float)
        H  = df['High'].astype(float)
        L  = df['Low'].astype(float)
        V  = df['Volume'].astype(float)
        O  = df['Open'].astype(float)
        n  = len(C)
        log_ret = np.log(C / C.shift(1))
        df  = df.tail(self.n_bars)
        C   = C.tail(self.n_bars)
        H   = H.tail(self.n_bars)
        L   = L.tail(self.n_bars)
        V   = V.tail(self.n_bars)
        O   = O.tail(self.n_bars)
        log_ret = log_ret.tail(self.n_bars)
        codes_needed = set(self.CATALOGUE[k][1] for k in keys
                           if k in self.CATALOGUE)
        self._ind_series = {}
        def _compute(code: str):
            if code == "price":
                return C.copy()
            if code == "log_ret":
                return log_ret * 100
            if code == "cum_ret":
                return ((1 + log_ret).cumprod() - 1) * 100
            if code == "gap":
                return np.log(O / C.shift(1) + 1e-9).fillna(0) * 100
            if code == "vs_sma20":
                return (C / C.rolling(20).mean() - 1) * 100
            if code == "vs_sma50":
                return (C / C.rolling(50).mean() - 1) * 100
            if code == "vs_sma200":
                return (C / C.rolling(200).mean() - 1) * 100
            if code == "vwap_dev":
                tp   = (H+L+C)/3
                vwap = (tp*V).rolling(20).sum()/(V.rolling(20).sum()+1e-9)
                return (C/vwap - 1)*100
            if code == "golden_x":
                return (C.rolling(50).mean() > C.rolling(200).mean()).astype(float)
            if code == "rsi14":
                delta = C.diff()
                g = delta.clip(lower=0).ewm(alpha=1/14,adjust=False).mean()
                l = (-delta.clip(upper=0)).ewm(alpha=1/14,adjust=False).mean()
                return 100 - 100/(1+g/(l+1e-9))
            if code == "macd_hist":
                ema12 = C.ewm(span=12,adjust=False).mean()
                ema26 = C.ewm(span=26,adjust=False).mean()
                macd  = ema12-ema26
                sig   = macd.ewm(span=9,adjust=False).mean()
                return macd-sig
            if code == "roc5":
                return C.pct_change(5)*100
            if code == "roc20":
                return C.pct_change(20)*100
            if code == "cci20":
                tp   = (H+L+C)/3
                sma  = tp.rolling(20).mean()
                mad  = tp.rolling(20).apply(lambda x: np.abs(x-x.mean()).mean())
                return (tp-sma)/(0.015*mad+1e-9)
            if code == "stoch_k":
                lo14 = L.rolling(14).min()
                hi14 = H.rolling(14).max()
                return 100*(C-lo14)/(hi14-lo14+1e-9)
            if code == "willr":
                lo14 = L.rolling(14).min()
                hi14 = H.rolling(14).max()
                return -100*(hi14-C)/(hi14-lo14+1e-9)
            if code == "atr14":
                tr = pd.concat([H-L,(H-C.shift()).abs(),(L-C.shift()).abs()],axis=1).max(axis=1)
                return tr.ewm(alpha=1/14,adjust=False).mean()
            if code == "bb_width":
                bb_mid = C.rolling(20).mean()
                bb_std = C.rolling(20).std()
                return (4*bb_std)/(bb_mid+1e-9)*100
            if code == "hv5":
                return log_ret.rolling(5).std()*(252**0.5)*100
            if code == "hv21":
                return log_ret.rolling(21).std()*(252**0.5)*100
            if code == "hv63":
                return log_ret.rolling(63).std()*(252**0.5)*100
            if code == "vovol":
                rv5 = log_ret.rolling(5).std()
                return rv5.rolling(20).std()/(rv5.rolling(20).mean()+1e-9)
            if code == "vol_regime":
                hv5  = log_ret.rolling(5).std()*(252**0.5)
                hv21 = log_ret.rolling(21).std()*(252**0.5)
                return hv5/(hv21+1e-9)
            if code == "volume":
                return V/1e6                
            if code == "vol_ratio":
                return V/(V.rolling(20).mean()+1e-9)
            if code == "obv_idx":
                obv = (np.sign(C.diff())*V).fillna(0).cumsum()
                return (obv/obv.iloc[0]*100) if obv.iloc[0]!=0 else obv
            if code == "cmf20":
                mfm = ((C-L)-(H-C))/(H-L+1e-9)
                return (mfm*V).rolling(20).sum()/V.rolling(20).sum()
            if code == "mfi14":
                tp  = (H+L+C)/3
                mfp = (tp*V*(tp>tp.shift()).astype(float)).rolling(14).sum()
                mfn = (tp*V*(tp<=tp.shift()).astype(float)).rolling(14).sum()
                return 100-100/(1+mfp/(mfn+1e-9))
            if code == "amihud":
                am = (log_ret.abs()/(V*C+1e-9)).rolling(20).mean()
                return am/(am.rolling(252).mean()+1e-9)
            if code == "beta60":
                if self._bench_ret is None:
                    return pd.Series(np.nan, index=C.index)
                align = pd.DataFrame({'s':log_ret,'b':self._bench_ret}).dropna()
                rc = align['s'].rolling(60).cov(align['b'])
                rv = align['b'].rolling(60).var()
                return (rc/rv).reindex(C.index)
            if code == "sharpe60":
                mu = log_ret.rolling(60).mean()*252
                sd = log_ret.rolling(60).std()*(252**0.5)
                return mu/(sd+1e-9)
            if code == "sharpe252":
                mu = log_ret.rolling(252).mean()*252
                sd = log_ret.rolling(252).std()*(252**0.5)
                return mu/(sd+1e-9)
            if code == "sortino60":
                mu  = log_ret.rolling(60).mean()*252
                neg = log_ret.where(log_ret<0,0)
                sd  = neg.rolling(60).std()*(252**0.5)
                return mu/(sd+1e-9)
            if code == "max_dd":
                def _mdd(x):
                    c = (1+x/100).cumprod()
                    return (c/c.cummax()-1).min()*100
                return log_ret.rolling(60).apply(_mdd, raw=False)
            if code == "skew20":
                return log_ret.rolling(20).skew().fillna(0)
            if code == "hurst60":
                def _hurst(x):
                    if len(x)<20: return 0.5
                    rs_list=[]
                    for k in [max(10,len(x)//4), max(15,len(x)//2)]:
                        if k>=len(x): continue
                        nk=len(x)//k; rs_v=[]
                        for i in range(nk):
                            s=x[i*k:(i+1)*k]; m=s.mean()
                            y=(s-m).cumsum(); R=y.max()-y.min(); S=s.std()
                            if S>1e-12: rs_v.append(R/S)
                        if rs_v: rs_list.append((np.log(k),np.log(np.mean(rs_v))))
                    if len(rs_list)<2: return 0.5
                    xs=np.array([p[0] for p in rs_list])
                    ys=np.array([p[1] for p in rs_list])
                    return float(np.clip((ys[-1]-ys[0])/(xs[-1]-xs[0]+1e-9),0,1))
                return log_ret.rolling(60).apply(_hurst, raw=True).fillna(0.5)
            info = self._info
            def _flat(val, scale=1): return pd.Series(
                val*scale if val else np.nan, index=C.index
            )
            eps_v = info.get('trailingEps')
            bvps  = info.get('bookValue')
            so    = info.get('sharesOutstanding')
            if code == "pe":
                return (C/eps_v) if eps_v and eps_v>0 else pd.Series(np.nan,index=C.index)
            if code == "pb":
                return (C/bvps) if bvps and bvps>0 else pd.Series(np.nan,index=C.index)
            if code == "ev_ebitda":
                ev = info.get('enterpriseValue'); eb = info.get('ebitda')
                return _flat(ev/eb) if ev and eb and eb>0 else pd.Series(np.nan,index=C.index)
            if code == "eps":    return _flat(eps_v)
            if code == "roe":    return _flat(info.get('returnOnEquity'),100)
            if code == "roa":    return _flat(info.get('returnOnAssets'),100)
            if code == "gross_margin": return _flat(info.get('grossMargins'),100)
            if code == "op_margin":    return _flat(info.get('operatingMargins'),100)
            if code == "net_margin":   return _flat(info.get('profitMargins'),100)
            if code == "debt_equity":  return _flat(info.get('debtToEquity'),0.01)
            if code == "curr_ratio":   return _flat(info.get('currentRatio'))
            if code == "rev_growth":   return _flat(info.get('revenueGrowth'),100)
            if code == "mcap":
                return (C*so/1e7) if so else pd.Series(np.nan,index=C.index)
            if code == "div_yield":    return _flat(info.get('dividendYield'),100)
            if code == "peg":          return _flat(info.get('pegRatio'))
            return pd.Series(np.nan, index=C.index)
        with Progress(
            TextColumn("  [cyan]{task.description}[/]"),
            BarColumn(), console=console
        ) as prog:
            task = prog.add_task("Computing indicators", total=len(codes_needed))
            for code in codes_needed:
                try:
                    s = _compute(code)
                    if s is not None:
                        self._ind_series[code] = s
                except Exception as e:
                    self._ind_series[code] = pd.Series(
                        float('nan'), index=C.index
                    )
                prog.advance(task)
        console.print(
            f"  [green]✓[/] {len(self._ind_series)} indicators computed  "
            f"|  {len(C)} bars"
        )
        return True
    def detect_signals(self, keys: list[str]) -> list[dict]:
        signals = []
        C = self._df['Close'].astype(float).tail(self.n_bars)
        def _add(stype, ind, date, val, desc):
            signals.append({
                "type": stype, "indicator": ind,
                "date": str(date)[:10], "value": val, "desc": desc
            })
        if "rsi14" in self._ind_series:
            rsi = self._ind_series["rsi14"].dropna()
            for i in range(1, len(rsi)):
                r0, r1 = float(rsi.iloc[i-1]), float(rsi.iloc[i])
                if r0 < 30 and r1 >= 30:
                    _add("CROSS", "RSI-14", rsi.index[i], r1,
                         f"RSI crossed above 30 (oversold exit) → bullish")
                elif r0 > 70 and r1 <= 70:
                    _add("CROSS", "RSI-14", rsi.index[i], r1,
                         f"RSI crossed below 70 (overbought exit) → bearish")
                elif r0 < 50 and r1 >= 50:
                    _add("CROSS", "RSI-14", rsi.index[i], r1,
                         f"RSI crossed above 50 (momentum shift) → bullish")
                elif r0 > 50 and r1 <= 50:
                    _add("CROSS", "RSI-14", rsi.index[i], r1,
                         f"RSI crossed below 50 (momentum loss) → bearish")
        if "macd_hist" in self._ind_series:
            mh = self._ind_series["macd_hist"].dropna()
            for i in range(1, len(mh)):
                m0, m1 = float(mh.iloc[i-1]), float(mh.iloc[i])
                if m0 < 0 and m1 >= 0:
                    _add("CROSS", "MACD", mh.index[i], m1,
                         f"MACD histogram turned positive → bullish crossover")
                elif m0 > 0 and m1 <= 0:
                    _add("CROSS", "MACD", mh.index[i], m1,
                         f"MACD histogram turned negative → bearish crossover")
        if "golden_x" in self._ind_series:
            gx = self._ind_series["golden_x"].dropna()
            for i in range(1, len(gx)):
                g0, g1 = float(gx.iloc[i-1]), float(gx.iloc[i])
                if g0 == 0 and g1 == 1:
                    _add("CROSS", "SMA50/200", gx.index[i], g1,
                         "Golden Cross — SMA-50 crossed above SMA-200 → strong bullish")
                elif g0 == 1 and g1 == 0:
                    _add("CROSS", "SMA50/200", gx.index[i], g1,
                         "Death Cross — SMA-50 crossed below SMA-200 → strong bearish")
        if "vol_regime" in self._ind_series:
            vr = self._ind_series["vol_regime"].dropna()
            for i in range(1, len(vr)):
                v0, v1 = float(vr.iloc[i-1]), float(vr.iloc[i])
                if v0 < 1.3 and v1 >= 1.3:
                    _add("REGIME", "Vol Regime", vr.index[i], v1,
                         "Volatility spike — short-term vol > 1.3× long-term → risk-off")
                elif v0 > 1.3 and v1 < 1.3:
                    _add("REGIME", "Vol Regime", vr.index[i], v1,
                         "Volatility compression — short-term vol < long-term → calming")
        LOOKBACK = 20
        for div_code, div_name in [
            ("rsi14","RSI-14"), ("macd_hist","MACD"), ("obv_idx","OBV")
        ]:
            if div_code not in self._ind_series: continue
            ind_s = self._ind_series[div_code].dropna()
            c_align = C.reindex(ind_s.index).dropna()
            aligned = pd.concat([c_align, ind_s], axis=1).dropna()
            aligned.columns = ['price','ind']
            if len(aligned) < LOOKBACK+2: continue
            for i in range(LOOKBACK, len(aligned)-1):
                seg_p = aligned['price'].iloc[i-LOOKBACK:i+1]
                seg_i = aligned['ind'].iloc[i-LOOKBACK:i+1]
                p_last = float(seg_p.iloc[-1]); p_prev = float(seg_p.min())
                i_last = float(seg_i.iloc[-1])
                p_min_idx = int(seg_p.argmin())
                i_at_pmin = float(seg_i.iloc[p_min_idx])
                if (p_last < p_prev and i_last > i_at_pmin * 1.05 and
                        i >= LOOKBACK + 5 and i % 10 == 0):                        
                    _add("DIVERGENCE", div_name,
                         aligned.index[i], p_last,
                         f"Bullish divergence — price lower low but {div_name} higher low → reversal signal")
                p_max = float(seg_p.max()); p_max_idx = int(seg_p.argmax())
                i_at_pmax = float(seg_i.iloc[p_max_idx])
                if (p_last > p_max * 0.995 and i_last < i_at_pmax * 0.95 and
                        i >= LOOKBACK + 5 and i % 10 == 0):
                    _add("DIVERGENCE", div_name,
                         aligned.index[i], p_last,
                         f"Bearish divergence — price higher high but {div_name} lower high → weakness signal")
        if "hurst60" in self._ind_series:
            hurst = self._ind_series["hurst60"].dropna()
            if len(hurst) > 0:
                h_last = float(hurst.iloc[-1])
                if h_last > 0.6:
                    _add("REGIME", "Hurst", hurst.index[-1], h_last,
                         f"Hurst={h_last:.2f} > 0.6 → strongly trending — momentum strategies work")
                elif h_last < 0.4:
                    _add("REGIME", "Hurst", hurst.index[-1], h_last,
                         f"Hurst={h_last:.2f} < 0.4 → mean-reverting — oscillator strategies work")
        signals.sort(key=lambda x: x['date'], reverse=True)
        self._signals = signals[:30]
        return self._signals
    def render_summary_table(self, keys: list[str]) -> None:
        from rich.console import Console
        from rich.table   import Table
        from rich.panel   import Panel
        from rich.rule    import Rule
        from rich         import box as _box
        console = Console()
        console.print(Rule(f"[bold cyan]Indicator Summary — {self.ticker}  {self.per_label}[/]"))
        tbl = Table(border_style="cyan", box=_box.SIMPLE_HEAVY,
                    show_lines=True, expand=False)
        tbl.add_column("Indicator",  width=26, style="bold")
        tbl.add_column("Unit",       width=6,  style="dim")
        tbl.add_column("Current",    width=12, justify="right")
        tbl.add_column("Min",        width=12, justify="right")
        tbl.add_column("Max",        width=12, justify="right")
        tbl.add_column("Mean",       width=12, justify="right")
        tbl.add_column("Std",        width=10, justify="right")
        tbl.add_column("Percentile", width=10, justify="right")
        tbl.add_column("Signal",     width=12, justify="center")
        for k in keys:
            if k not in self.CATALOGUE: continue
            name, code, unit, group = self.CATALOGUE[k]
            if code not in self._ind_series: continue
            s = self._ind_series[code].dropna()
            if len(s) == 0: continue
            cur = float(s.iloc[-1])
            mn  = float(s.min())
            mx  = float(s.max())
            avg = float(s.mean())
            std = float(s.std())
            pct = float((s <= cur).sum() / len(s) * 100)
            def _fmt(v):
                if abs(v) >= 1e6:  return f"{v/1e6:.2f}M"
                if abs(v) >= 1e3:  return f"{v:,.1f}"
                return f"{v:.3f}" if abs(v) < 10 else f"{v:.2f}"
            if   pct >= 80: sig_str = "[red]HIGH[/]"
            elif pct >= 60: sig_str = "[yellow]ABOVE AVG[/]"
            elif pct <= 20: sig_str = "[green]LOW[/]"
            elif pct <= 40: sig_str = "[cyan]BELOW AVG[/]"
            else:           sig_str = "[dim]NEUTRAL[/]"
            cur_c = "green" if cur > avg else "red"
            tbl.add_row(
                name, unit,
                f"[{cur_c}]{_fmt(cur)}[/{cur_c}]",
                _fmt(mn), _fmt(mx), _fmt(avg), _fmt(std),
                f"{pct:.0f}th",
                sig_str,
            )
        console.print(tbl)
        if self._signals:
            console.print(Rule("[bold yellow]Detected Signals & Divergences[/]"))
            sig_tbl = Table(border_style="yellow", box=_box.SIMPLE_HEAVY,
                            show_lines=False, expand=False)
            sig_tbl.add_column("Type",       width=12, style="bold")
            sig_tbl.add_column("Indicator",  width=14)
            sig_tbl.add_column("Date",       width=12, style="dim")
            sig_tbl.add_column("Value",      width=10, justify="right")
            sig_tbl.add_column("Description",width=60)
            type_colours = {
                "CROSS":"cyan","REGIME":"magenta","DIVERGENCE":"yellow"
            }
            for sig in self._signals[:15]:
                tc = type_colours.get(sig['type'],'white')
                tbl_desc = sig['desc']
                bull = "→ bull" in tbl_desc.lower()
                dc   = "green" if bull else ("red" if "→ bear" in tbl_desc.lower()
                                             else "dim")
                sig_tbl.add_row(
                    f"[{tc}]{sig['type']}[/{tc}]",
                    sig['indicator'],
                    sig['date'],
                    f"{sig['value']:.2f}",
                    f"[{dc}]{tbl_desc}[/{dc}]",
                )
            console.print(sig_tbl)
    def _get_series_list(self, keys: list[str]) -> tuple:
        names, series, units = [], [], []
        for k in keys:
            if k not in self.CATALOGUE: continue
            name, code, unit, group = self.CATALOGUE[k]
            if code in self._ind_series:
                s = self._ind_series[code].dropna()
                if len(s) >= 5:
                    names.append(name); series.append(s); units.append(unit)
        return names, series, units
    def _palette(self) -> list:
        return [
            '#3498db','#2ecc71','#e74c3c','#e67e22','#9b59b6',
            '#1abc9c','#f39c12','#e91e63','#00bcd4','#8bc34a',
        ]
    def _style_ax(self, ax) -> None:
        BG='#0d0d1a'; PBG='#1a1a2e'; GRID='#2c3e50'
        ax.set_facecolor(PBG)
        ax.grid(alpha=0.18, color=GRID)
        for sp in ax.spines.values(): sp.set_edgecolor(GRID)
        ax.tick_params(colors='#7f8c8d', labelsize=8.5)
    def plot_panel(self, panel_id: str, keys: list[str]) -> None:
        BG='#0d0d1a'; TEXT='#ecf0f1'
        plt.style.use('dark_background')
        names, series, units = self._get_series_list(keys)
        if len(names) < 1:
            from rich.console import Console
            Console().print("  [red]No valid series to plot.[/]"); return
        palette = self._palette()
        C = self._df['Close'].astype(float).tail(self.n_bars)
        xs_all = C.index                   
        if panel_id == "1":
            self._plot_multiaxis(names, series, units, palette, BG, TEXT)
        elif panel_id == "2":
            self._plot_zscore(names, series, palette, BG, TEXT)
        elif panel_id == "3":
            self._plot_minmax(names, series, palette, BG, TEXT)
        elif panel_id == "4":
            self._plot_rolling_corr(names, series, palette, BG, TEXT)
        elif panel_id == "5":
            self._plot_scatter(names, series, palette, BG, TEXT)
        elif panel_id == "6":
            self._plot_heatmap(names, series, C, BG, TEXT)
        elif panel_id == "7":
            self._plot_divergence(names, series, C, palette, BG, TEXT)
        elif panel_id == "8":
            self._plot_master_dashboard(names, series, units, C, palette, BG, TEXT)
    def _plot_multiaxis(self, names, series, units, pal, BG, TEXT):
        import matplotlib.ticker as mtk
        n = min(len(names), 5)
        fig, ax = plt.subplots(figsize=(18, 7), facecolor=BG)
        self._style_ax(ax)
        ax.plot(series[0].index, series[0].values,
                color=pal[0], lw=2.0, label=names[0], zorder=5)
        ax.set_ylabel(f"{names[0]} ({units[0]})", color=pal[0], fontsize=9)
        ax.tick_params(axis='y', labelcolor=pal[0])
        twin_axes = []
        for i in range(1, n):
            tw = ax.twinx()
            offset = 70 * (i-1)
            tw.spines['right'].set_position(('outward', offset))
            tw.spines['right'].set_visible(True)
            tw.spines['right'].set_edgecolor(pal[i])
            tw.plot(series[i].index, series[i].values,
                    color=pal[i], lw=1.5, label=names[i], alpha=0.85)
            tw.set_ylabel(f"{names[i]} ({units[i]})", color=pal[i], fontsize=8)
            tw.tick_params(axis='y', labelcolor=pal[i], labelsize=7)
            tw.set_facecolor(BG)
            twin_axes.append(tw)
        all_lines = []
        for a in [ax]+twin_axes:
            ln, lb = a.get_legend_handles_labels()
            all_lines += ln
        from matplotlib.lines import Line2D
        all_labels = names[:n]
        ax.legend(all_lines, all_labels, fontsize=8, loc='upper left',
                  facecolor='#1a1a2e', edgecolor='#2c3e50',
                  labelcolor=TEXT, framealpha=0.85)
        ax.set_title(
            f"Multi-Axis Overlay — {self.ticker}  |  {self.per_label}",
            fontsize=12, color=TEXT
        )
        fig.patch.set_facecolor(BG)
        plt.tight_layout()
        plt.show()
    def _plot_zscore(self, names, series, pal, BG, TEXT):
        fig, ax = plt.subplots(figsize=(18, 7), facecolor=BG)
        self._style_ax(ax)
        for i, (nm, s) in enumerate(zip(names, series)):
            z = (s - s.mean()) / (s.std() + 1e-9)
            ax.plot(z.index, z.values, color=pal[i%len(pal)],
                    lw=1.5, label=nm, alpha=0.85)
        ax.axhline(0,   color='#7f8c8d', lw=1.0, ls='--', alpha=0.6)
        ax.axhline(2,   color='#e74c3c', lw=0.8, ls=':', alpha=0.5,  label='+2σ')
        ax.axhline(-2,  color='#2ecc71', lw=0.8, ls=':', alpha=0.5,  label='-2σ')
        ax.fill_between(ax.get_xlim(),[2,2],[3,3],alpha=0.05,color='#e74c3c')
        ax.fill_between(ax.get_xlim(),[-2,-2],[-3,-3],alpha=0.05,color='#2ecc71')
        ax.set_ylabel("Standard Deviations (σ)", color=TEXT, fontsize=10)
        ax.legend(fontsize=8, loc='upper left',
                  facecolor='#1a1a2e', edgecolor='#2c3e50',
                  labelcolor=TEXT, framealpha=0.85)
        ax.set_title(
            f"Z-Score Normalised Comparison — {self.ticker}  |  {self.per_label}",
            fontsize=12, color=TEXT
        )
        fig.patch.set_facecolor(BG)
        plt.tight_layout(); plt.show()
    def _plot_minmax(self, names, series, pal, BG, TEXT):
        fig, ax = plt.subplots(figsize=(18, 7), facecolor=BG)
        self._style_ax(ax)
        for i, (nm, s) in enumerate(zip(names, series)):
            mn, mx = s.min(), s.max(); rng = mx-mn or 1e-9
            norm = (s-mn)/rng*100
            c = pal[i%len(pal)]
            ax.fill_between(norm.index, 0, norm.values, alpha=0.12, color=c)
            ax.plot(norm.index, norm.values, color=c, lw=1.5, label=nm, alpha=0.9)
        ax.axhline(50, color='#7f8c8d', lw=0.8, ls='--', alpha=0.5)
        ax.axhline(80, color='#e74c3c', lw=0.6, ls=':', alpha=0.4)
        ax.axhline(20, color='#2ecc71', lw=0.6, ls=':', alpha=0.4)
        ax.set_ylim(-5, 105)
        ax.set_ylabel("Normalised Value (0–100)", color=TEXT, fontsize=10)
        ax.legend(fontsize=8, loc='upper left',
                  facecolor='#1a1a2e', edgecolor='#2c3e50',
                  labelcolor=TEXT, framealpha=0.85)
        ax.set_title(
            f"Min-Max (0–100) Comparison — {self.ticker}  |  {self.per_label}",
            fontsize=12, color=TEXT
        )
        fig.patch.set_facecolor(BG); plt.tight_layout(); plt.show()
    def _plot_rolling_corr(self, names, series, pal, BG, TEXT):
        if len(names) < 2:
            from rich.console import Console
            Console().print("  [yellow]Need ≥2 indicators for rolling correlation.[/]")
            return
        n_pairs = min(3, len(names)*(len(names)-1)//2)
        fig, axes = plt.subplots(n_pairs, 1, figsize=(18, 4*n_pairs),
                                  facecolor=BG, sharex=True)
        if n_pairs == 1: axes = [axes]
        idx = 0
        for i in range(len(names)):
            for j in range(i+1, len(names)):
                if idx >= n_pairs: break
                ax = axes[idx]; self._style_ax(ax)
                s1 = series[i].pct_change().dropna()
                s2 = series[j].pct_change().dropna()
                align = pd.concat([s1,s2],axis=1).dropna()
                if len(align) < 30: idx+=1; continue
                align.columns = ['a','b']
                roll_corr = align['a'].rolling(30).corr(align['b'])
                ax.plot(roll_corr.index, roll_corr.values,
                        color=pal[idx%len(pal)], lw=1.5)
                ax.axhline(0, color='#7f8c8d', lw=1, ls='--')
                ax.axhline(0.7, color='#2ecc71', lw=0.8, ls=':', alpha=0.6)
                ax.axhline(-0.7, color='#e74c3c', lw=0.8, ls=':', alpha=0.6)
                ax.fill_between(roll_corr.index, roll_corr.values, 0,
                                where=(roll_corr>0), alpha=0.15,
                                color='#2ecc71')
                ax.fill_between(roll_corr.index, roll_corr.values, 0,
                                where=(roll_corr<0), alpha=0.15,
                                color='#e74c3c')
                ax.set_ylim(-1.1, 1.1); ax.set_ylabel("Correlation", fontsize=9)
                ax.set_title(f"30d Rolling Correlation: "
                             f"{names[i]} vs {names[j]}", fontsize=10, color=TEXT)
                idx += 1
        fig.suptitle(
            f"Rolling Pairwise Correlation — {self.ticker}  |  {self.per_label}",
            fontsize=12, color=TEXT, y=1.01
        )
        fig.patch.set_facecolor(BG); plt.tight_layout(); plt.show()
    def _plot_scatter(self, names, series, pal, BG, TEXT):
        import matplotlib.cm     as cm
        if len(names) < 2:
            from rich.console import Console
            Console().print("  [yellow]Need ≥2 indicators for scatter plot.[/]")
            return
        n_pairs = min(4, len(names)*(len(names)-1)//2)
        ncols   = min(2, n_pairs); nrows = (n_pairs+ncols-1)//ncols
        fig, axes = plt.subplots(nrows, ncols, figsize=(9*ncols, 7*nrows),
                                  facecolor=BG)
        axes = axes.flatten() if n_pairs>1 else [axes]
        idx = 0
        for i in range(len(names)):
            for j in range(i+1, len(names)):
                if idx >= n_pairs: break
                ax = axes[idx]; self._style_ax(ax)
                align = pd.concat([series[i],series[j]],axis=1).dropna()
                if len(align)<10: idx+=1; continue
                align.columns=['x','y']
                t_norm = np.linspace(0,1,len(align))
                sc = ax.scatter(align['x'], align['y'],
                                c=t_norm, cmap='plasma',
                                s=20, alpha=0.7, edgecolors='none')
                m,b = np.polyfit(align['x'],align['y'],1)
                xl = np.linspace(align['x'].min(), align['x'].max(), 100)
                ax.plot(xl, m*xl+b, color='white', lw=1.2, alpha=0.6)
                corr = float(align['x'].corr(align['y']))
                ax.set_xlabel(names[i], color=TEXT, fontsize=9)
                ax.set_ylabel(names[j], color=TEXT, fontsize=9)
                ax.set_title(f"r = {corr:+.3f}  |  "
                             f"Older → purple  Newer → yellow",
                             fontsize=9, color=TEXT)
                plt.colorbar(sc, ax=ax, label="Time →")
                idx += 1
        for a in axes[idx:]: a.axis('off')
        fig.suptitle(
            f"Scatter / Regime Chart — {self.ticker}  |  {self.per_label}",
            fontsize=12, color=TEXT
        )
        fig.patch.set_facecolor(BG); plt.tight_layout(); plt.show()
    def _plot_heatmap(self, names, series, price_series, BG, TEXT):
        n = min(len(names), 8)
        fig, axes = plt.subplots(n+1, 1, figsize=(18, 1.5*(n+1)+3),
                                  facecolor=BG,
                                  gridspec_kw={'height_ratios':[3]+[1]*n})
        ax0 = axes[0]; self._style_ax(ax0)
        ax0.plot(price_series.index, price_series.values,
                 color='#3498db', lw=1.5)
        ax0.set_ylabel("Price", color=TEXT, fontsize=9)
        ax0.set_title(
            f"Signal Heatmap (Decile Colour per Bar) — "
            f"{self.ticker}  |  {self.per_label}",
            fontsize=11, color=TEXT
        )
        cmap_pos = plt.cm.RdYlGn
        for i in range(n):
            ax = axes[i+1]; self._style_ax(ax)
            s = series[i].dropna()
            if len(s) < 5: ax.axis('off'); continue
            decile = s.rank(pct=True)
            values = decile.values
            dates  = decile.index
            for j in range(len(dates)-1):
                col = cmap_pos(float(values[j]))
                ax.axvspan(dates[j], dates[j+1], alpha=0.85, color=col,
                           ymin=0, ymax=1)
            ax.set_yticks([]); ax.set_ylabel(names[i][:16], fontsize=7.5,
                                              color=TEXT, rotation=0,
                                              labelpad=60)
            ax.set_xlim(dates[0], dates[-1])
        sm = plt.cm.ScalarMappable(cmap=cmap_pos,
                                    norm=mcolors.Normalize(0,1))
        sm.set_array([])
        cbar = plt.colorbar(sm, ax=axes.tolist(), shrink=0.3,
                             pad=0.02, label="Decile (0=Low 1=High)")
        cbar.ax.yaxis.label.set_color(TEXT)
        fig.patch.set_facecolor(BG)
        plt.tight_layout(); plt.show()
    def _plot_divergence(self, names, series, price_series, pal, BG, TEXT):
        n = min(len(names), 4)
        fig, axes = plt.subplots(n+1, 1, figsize=(18, 4*(n+1)),
                                  facecolor=BG, sharex=True,
                                  gridspec_kw={'height_ratios':[2]+[1]*n})
        ax0 = axes[0]; self._style_ax(ax0)
        ax0.plot(price_series.index, price_series.values,
                 color='#3498db', lw=1.8, label='Price')
        div_sigs = [s for s in self._signals if s['type']=='DIVERGENCE']
        for sig in div_sigs:
            try:
                dt   = pd.Timestamp(sig['date'])
                val  = float(sig['value'])
                col  = '#2ecc71' if 'bullish' in sig['desc'].lower() else '#e74c3c'
                mrk  = '^' if 'bullish' in sig['desc'].lower() else 'v'
                ax0.scatter([dt],[val], color=col, marker=mrk, s=100, zorder=6)
            except: pass
        ax0.set_ylabel("Price (₹)", color=TEXT, fontsize=9)
        ax0.legend(fontsize=8, facecolor='#1a1a2e', edgecolor='#2c3e50',
                   labelcolor=TEXT)
        ax0.set_title(
            f"Divergence Analysis — {self.ticker}  |  {self.per_label}",
            fontsize=11, color=TEXT
        )
        for i in range(n):
            ax = axes[i+1]; self._style_ax(ax)
            s  = series[i].reindex(price_series.index).dropna()
            c  = pal[i % len(pal)]
            ax.plot(s.index, s.values, color=c, lw=1.3, label=names[i])
            ax.axhline(s.mean(), color='#7f8c8d', lw=0.7, ls='--')
            for sig in div_sigs:
                if names[i].lower() in sig['indicator'].lower():
                    try:
                        dt = pd.Timestamp(sig['date'])
                        if dt in s.index:
                            col = '#2ecc71' if 'bullish' in sig['desc'].lower()                                  else '#e74c3c'
                            ax.axvline(dt, color=col, lw=1.5, alpha=0.6, ls='--')
                    except: pass
            ax.set_ylabel(names[i][:18], color=c, fontsize=8)
            ax.legend(fontsize=7.5, facecolor='#1a1a2e', edgecolor='#2c3e50',
                      labelcolor=TEXT)
        fig.patch.set_facecolor(BG)
        plt.tight_layout(); plt.show()
