    ax4.axhline(0, color='#555', lw=0.8, ls='--', alpha=0.4)
    ax4.set_title("Risk-Return Scatter (Annualised)", fontsize=11)
    ax4.set_xlabel("Annualised Volatility (%)")
    ax4.set_ylabel("Annualised Return (%)")
    ax4.legend(fontsize=8); ax4.grid(alpha=0.18)
    ax4.set_facecolor(PANEL_BG)
    ax5 = fig.add_subplot(gs[2, 1])
    for nm in sec_names:
        d = sector_data[nm]
        rv = d['rolling_vol'].dropna()
        ax5.plot(rv.index, rv.values, color=d['color'], lw=1.6, alpha=0.85, label=nm)
    ax5.set_title("Rolling 20-Day Annualised Volatility (%)", fontsize=11)
    ax5.set_ylabel("Volatility (%)")
    ax5.legend(fontsize=7, loc='upper left', ncol=2,
               framealpha=0.6, facecolor=PANEL_BG, edgecolor=GRID)
    ax5.grid(alpha=0.18); ax5.set_facecolor(PANEL_BG)
    ax6 = fig.add_subplot(gs[3, 0])
    corr_df = pd.DataFrame({n: sector_data[n]['daily_ret'] for n in sec_names})
    corr_m  = corr_df.corr()
    sns.heatmap(corr_m, annot=True, fmt='.2f', cmap='RdYlGn',
                center=0, vmin=-1, vmax=1, linewidths=0.5,
                linecolor=GRID,
                cbar_kws={'shrink':0.8,'label':'Correlation'},
                ax=ax6, annot_kws={'size': 8 if n_sec<=8 else 6})
    ax6.set_title("Inter-Sector Correlation Matrix", fontsize=11)
    ax6.set_facecolor(PANEL_BG)
    ax6.tick_params(axis='x', rotation=35, labelsize=8)
    ax6.tick_params(axis='y', rotation=0,  labelsize=8)
    ax7 = fig.add_subplot(gs[3, 1])
    rp   = min(21, n_bars//4) if n_bars>40 else 5
    roll_df = pd.DataFrame(
        {n: sector_data[n]['daily_ret'].rolling(rp).sum()*100
         for n in sec_names}
    ).dropna()
    if len(roll_df) > 5:
        step    = max(1, len(roll_df)//35)
        sampled = roll_df.iloc[::step].T
        sns.heatmap(sampled, cmap='RdYlGn', center=0,
                    linewidths=0.3, linecolor=GRID,
                    cbar_kws={'shrink':0.7,'label':f'{rp}d Return %'},
                    ax=ax7, xticklabels=False, annot=False)
        ax7.set_title(f"Rolling {rp}-Day Returns Heatmap", fontsize=11)
        ax7.tick_params(axis='y', labelsize=9)
        ax7.set_facecolor(PANEL_BG)
    ax8 = fig.add_subplot(gs[4, 0])
    ax8.axvline(100, color='#555', lw=1.5, ls='--', alpha=0.8)
