    for q, xy, c in [
        ("IMPROVING",(97.5,102),'#ffd43b'),
        ("LEADING",  (102,102), '#51cf66'),
        ("LAGGING",  (97.5,98), '#ff6b6b'),
        ("WEAKENING",(102,98),  '#aaa'),
    ]:
        ax8.text(xy[0], xy[1], q, fontsize=7.5, color=c,
                 ha='right' if xy[0]<100 else 'left',
                 alpha=0.75, style='italic')
    for nm in sec_names:
        d   = sector_data[nm]
        rsr = d['rs_ratio'].dropna().tail(20)
        rsm = d['rs_momentum'].dropna().tail(20)
        idx = rsr.index.intersection(rsm.index)
        if len(idx)>=2:
            ax8.plot(rsr.loc[idx].values, rsm.loc[idx].values,
                     color=d['color'], lw=1.2, alpha=0.6)
        ax8.scatter(d['rsr_latest'], d['rsm_latest'],
                    color=d['color'], s=100, zorder=5,
                    edgecolors='white', linewidths=0.8)
        ax8.annotate(nm, (d['rsr_latest'], d['rsm_latest']),
                     fontsize=7, color=d['color'],
                     xytext=(6,3), textcoords='offset points')
    ax8.set_title("Sector Rotation (JdK RS-Ratio vs RS-Momentum)", fontsize=10.5)
    ax8.set_xlabel("RS-Ratio (>100 = Outperforming Nifty)")
    ax8.set_ylabel("RS-Momentum (>100 = Accelerating)")
    ax8.grid(alpha=0.15); ax8.set_facecolor(PANEL_BG)
    ax9 = fig.add_subplot(gs[4, 1])
    x   = np.arange(len(sorted_secs)); w = 0.22
    nm_list = [n for n,_ in sorted_secs]
