def run_news_events_hub(ticker):
    import textwrap as _tw
    from rich.console   import Console
    from rich.panel     import Panel
    from rich.table     import Table
    from rich.markdown  import Markdown
    from rich.prompt    import Prompt
    from rich.columns   import Columns
    from rich.text      import Text
    from rich.rule      import Rule
    from rich           import box
    console = Console()
    try:
        from nltk.sentiment.vader import SentimentIntensityAnalyzer
        import nltk
        try:    nltk.data.find('sentiment/vader_lexicon.zip')
        except: nltk.download('vader_lexicon', quiet=True)
        _sia          = SentimentIntensityAnalyzer()
        HAS_VADER     = True
    except ImportError:
        HAS_VADER     = False
    try:
        from GoogleNews import GoogleNews as _GN
        HAS_GNEWS     = True
    except ImportError:
        HAS_GNEWS     = False
    try:
        import feedparser
        HAS_FEEDPARSER = True
    except ImportError:
        HAS_FEEDPARSER = False
    try:
        import requests as _req
        HAS_REQUESTS   = True
    except ImportError:
        HAS_REQUESTS   = False
    _OR_CONFIG_FILE = ".md_task_config.json"
    def _load_or_config():
        p = Path(_OR_CONFIG_FILE)
        if p.exists():
            try:
                d = json.loads(p.read_text(encoding="utf-8"))
                return (d.get("api_key", "") or _GLOBAL_OR_KEY).strip(), (d.get("model", "") or _GLOBAL_OR_MODEL).strip()
            except: pass
        return _GLOBAL_OR_KEY, _GLOBAL_OR_MODEL
    def _save_or_config(key, model):
        try:
            Path(_OR_CONFIG_FILE).write_text(
                json.dumps({"api_key": key, "model": model}, indent=2),
                encoding="utf-8"
            )
        except: pass
    OR_API_KEY, OR_MODEL = _load_or_config()
    if not OR_MODEL:
        OR_MODEL = _GLOBAL_OR_MODEL
    def _vader_score(text: str) -> dict:
        if not HAS_VADER or not text:
            return {"compound": 0.0, "pos": 0.0, "neu": 1.0, "neg": 0.0}
        return _sia.polarity_scores(str(text))
    def _sentiment_label(compound: float) -> tuple[str, str]:
        if compound >= 0.05:  return "Bullish", "green"
        if compound <= -0.05: return "Bearish", "red"
        return "Neutral", "yellow"
    def _trigrams(text: str) -> set:
        t = re.sub(r'[^a-z0-9 ]', '', text.lower())
        return {t[i:i+3] for i in range(len(t)-2)} if len(t) > 2 else set()
    def _deduplicate(articles: list[dict], threshold: float = 0.72) -> list[dict]:
        kept    : list[dict] = []
        kept_tg : list[set]  = []
        for art in articles:
            tg = _trigrams(art.get("title", ""))
            if not tg:
                kept.append(art); kept_tg.append(tg); continue
            duplicate = False
            for existing_tg in kept_tg:
                union = tg | existing_tg
                if union and len(tg & existing_tg) / len(union) >= threshold:
                    duplicate = True; break
            if not duplicate:
                kept.append(art); kept_tg.append(tg)
        return kept
    def _fetch_yfinance_news(ticker_sym: str, max_items: int = 40) -> list[dict]:
        try:
            raw = yf.Ticker(ticker_sym).news or []
            out = []
            for item in raw[:max_items]:
                content = item.get("content", {})
                if content and isinstance(content, dict):
                    title  = (content.get("title")
                              or content.get("headline", ""))
                    source = (content.get("provider", {}).get("displayName")
                              or content.get("source", "yfinance"))
                    url    = (content.get("canonicalUrl", {}).get("url")
                              or content.get("clickThroughUrl", {}).get("url")
                              or item.get("link", ""))
                    desc   = content.get("summary", "")
                    pub    = content.get("pubDate", "")
                    try:
                        dt = datetime.fromisoformat(pub.replace("Z", "+00:00"))
                        dt = dt.replace(tzinfo=None)
                    except Exception:
                        ts = item.get("providerPublishTime", 0)
                        dt = datetime.fromtimestamp(ts) if ts else datetime.now()
                else:
                    title  = item.get("title", "")
                    source = item.get("publisher", "yfinance")
                    url    = item.get("link", "")
                    desc   = item.get("summary", "")
                    ts     = item.get("providerPublishTime", 0)
                    dt     = datetime.fromtimestamp(ts) if ts else datetime.now()
                if not title:
                    continue
                out.append({
                    "title"   : title,
                    "source"  : source or "yfinance",
                    "url"     : url,
                    "datetime": dt,
                    "desc"    : desc,
                    "origin"  : "yfinance",
                })
            return out
        except Exception as e:
            return []
    _RSS_FEEDS = {
        "ET Markets"     : "https://economictimes.indiatimes.com/markets/rssfeeds/1977021501.cms",
        "Moneycontrol"   : "https://www.moneycontrol.com/rss/MCtopnews.xml",
        "LiveMint"       : "https://www.livemint.com/rss/markets",
        "BusinessStandard": "https://www.business-standard.com/rss/markets-106.rss",
    }
    def _fetch_rss(query_keywords: list[str], max_per_feed: int = 20) -> list[dict]:
        if not HAS_FEEDPARSER:
            return []
        articles = []
        kw_lower = [k.lower() for k in query_keywords]
        def _fetch_one(name, url):
            try:
                feed = feedparser.parse(url)
                result = []
                for entry in feed.entries[:max_per_feed]:
                    title   = entry.get("title", "")
                    summary = entry.get("summary", "")
                    combined = (title + " " + summary).lower()
                    if kw_lower and not any(kw in combined for kw in kw_lower):
                        continue
                    published = entry.get("published_parsed")
                    dt = datetime(*published[:6]) if published else datetime.now()
                    result.append({
                        "title"   : title,
                        "source"  : name,
                        "url"     : entry.get("link", ""),
                        "datetime": dt,
                        "desc"    : summary[:300],
                        "origin"  : "rss",
                    })
                return result
            except Exception:
                return []
        with ThreadPoolExecutor(max_workers=4) as pool:
            futures = {pool.submit(_fetch_one, n, u): n for n, u in _RSS_FEEDS.items()}
            for fut in as_completed(futures, timeout=12):
                try: articles.extend(fut.result())
                except: pass
        return articles
    def _fetch_googlenews(query: str, months_back: int = 2) -> list[dict]:
        if not HAS_GNEWS:
            return []
        try:
            end   = datetime.now()
            start = end - timedelta(days=months_back * 30)
            gn    = _GN(lang='en', region='IN',
                        start=start.strftime("%m/%d/%Y"),
                        end=end.strftime("%m/%d/%Y"))
            gn.search(query)
            for pg in range(2, 7):
                time.sleep(0.5)
                try: gn.getpage(pg)
                except: break
            out = []
            for r in (gn.result() or []):
                dt = pd.to_datetime(r.get("datetime"), errors="coerce")
                if pd.isna(dt): continue
                out.append({
                    "title"   : r.get("title", ""),
                    "source"  : r.get("media", "GoogleNews"),
                    "url"     : r.get("link", ""),
                    "datetime": dt.to_pydatetime(),
                    "desc"    : r.get("desc", ""),
                    "origin"  : "googlenews",
                })
            return out
        except Exception:
            return []
    def _aggregate_news(
        ticker_sym     : str,
        query          : str,
        keywords       : list[str],
        months_back    : int = 2,
        use_yf         : bool = True,
    ) -> pd.DataFrame:
        results = []
        def _yf():
            return _fetch_yfinance_news(ticker_sym) if use_yf else []
        def _rss():
            kw = keywords if use_yf else []
            return _fetch_rss(kw)
        def _gn():
            return _fetch_googlenews(query, months_back)
        with ThreadPoolExecutor(max_workers=3) as pool:
            futures = [pool.submit(_yf), pool.submit(_rss), pool.submit(_gn)]
            for fut in as_completed(futures, timeout=30):
                try: results.extend(fut.result())
                except: pass
        if not results:
            return pd.DataFrame()
        results = _deduplicate(results)
        df = pd.DataFrame(results)
        df["datetime"] = pd.to_datetime(df["datetime"], errors="coerce")
        df = df.dropna(subset=["datetime"]).sort_values("datetime", ascending=False)
        def _score(row):
            text = str(row.get("title","")) + " " + str(row.get("desc",""))
            sc   = _vader_score(text)
            lbl, _ = _sentiment_label(sc["compound"])
            return pd.Series({
                "compound": sc["compound"],
                "pos"     : sc["pos"],
                "neu"     : sc["neu"],
                "neg"     : sc["neg"],
                "label"   : lbl,
            })
        scores = df.apply(_score, axis=1)
        df     = pd.concat([df.reset_index(drop=True), scores], axis=1)
        return df
    def _ai_call(system_prompt: str, user_prompt: str,
                 messages_extra: list[dict] | None = None) -> str:
        if not HAS_REQUESTS or not OR_API_KEY:
            return "[AI UNAVAILABLE] No API key configured. Use [S] Settings."
        import requests as _r
        msgs = [{"role":"system","content":system_prompt},
                {"role":"user",  "content":user_prompt}]
        if messages_extra:
            msgs += messages_extra
        try:
            resp = _r.post(
                "http://127.0.0.1:9999/disabled",
                headers={"Authorization": f"Bearer {OR_API_KEY}",
                         "Content-Type": "application/json",
                         "X-Title": "Module37-NewsHub"},
                json={"model": OR_MODEL, "messages": msgs, "temperature": 0.3},
                timeout=90,
            )
            resp.raise_for_status()
            return resp.json()["choices"][0]["message"]["content"]
        except Exception as e:
            return f"[AI ERROR] {e}"
    def _ai_call_threaded(system_p: str, user_p: str) -> tuple[str, float]:
        bag  : dict            = {}
        done : threading.Event = threading.Event()
        def _worker():
            t0 = time.perf_counter()
            bag["reply"]   = _ai_call(system_p, user_p)
            bag["latency"] = time.perf_counter() - t0
            done.set()
        threading.Thread(target=_worker, daemon=True).start()
        spin  = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"
        idx   = 0
        t0    = time.perf_counter()
        while not done.wait(timeout=0.5):
            elapsed = time.perf_counter() - t0
            print(f"\r  {spin[idx%len(spin)]} AI thinking… {elapsed:.1f}s   ",
                  end="", flush=True)
            idx += 1
        print()
        return bag.get("reply",""), bag.get("latency", 0.0)
