    def _render_news_table(df: pd.DataFrame, title: str, n: int = 20):
        tbl = Table(
            title=title, border_style="cyan", show_lines=True,
            box=box.SIMPLE_HEAVY, expand=True
        )
        tbl.add_column("Date",     width=11,  style="dim")
        tbl.add_column("Src",      width=14,  style="dim")
        tbl.add_column("Sentiment",width=9)
        tbl.add_column("Score",    width=7,   style="dim")
        tbl.add_column("Headline", ratio=1)
        for _, row in df.head(n).iterrows():
            lbl, clr = _sentiment_label(row["compound"])
            date_s   = str(row["datetime"])[:10] if pd.notna(row["datetime"]) else "—"
            src      = str(row.get("source",""))[:13]
            title_s  = str(row.get("title",""))
            wrapped  = "\n".join(_tw.wrap(title_s, width=70)) if len(title_s)>70 else title_s
            tbl.add_row(
                date_s, src,
                f"[{clr}]{lbl}[/{clr}]",
                f"[{clr}]{row['compound']:+.3f}[/{clr}]",
                wrapped,
            )
        console.print(tbl)
    def _render_sentiment_summary(df: pd.DataFrame):
        lc   = df["label"].value_counts()
        avg  = df["compound"].mean()
        lbl, clr = _sentiment_label(avg)
        bull = lc.get("Bullish", 0)
        neu  = lc.get("Neutral", 0)
        bear = lc.get("Bearish", 0)
        total = len(df)
        def _bar(count, total, clr, width=20):
            filled = int(round(count / total * width)) if total else 0
            return f"[{clr}]{'█' * filled}{'░' * (width-filled)}[/{clr}] {count}"
        lines = (
            f"[bold]Articles:[/] {total}   "
            f"[bold]Period:[/] {str(df['datetime'].min())[:10]} → {str(df['datetime'].max())[:10]}\n\n"
            f"[bold]Overall:[/] [{clr}]{lbl}  {avg:+.4f}[/{clr}]\n\n"
            f"[green]Bullish[/]  {_bar(bull, total, 'green')}\n"
            f"[yellow]Neutral[/]  {_bar(neu,  total, 'yellow')}\n"
            f"[red]Bearish[/]  {_bar(bear, total, 'red')}"
        )
        console.print(Panel(lines, title="[bold white]Sentiment Summary[/]",
                            border_style="cyan", expand=False))
    def _render_matplotlib_dashboard(df: pd.DataFrame, title_label: str):
        plt.style.use("dark_background")
        fig = plt.figure(figsize=(22, 14))
        fig.suptitle(f"News & Events Hub  |  {title_label}",
                     fontsize=14, fontweight="bold", y=0.998)
        gs = gridspec.GridSpec(2, 3, figure=fig, hspace=0.42, wspace=0.35)
        GREEN   = "#2ecc71"; RED   = "#e74c3c"
        ORANGE  = "#f39c12"; ACCENT= "#3498db"
        PANEL_BG= "#1a1a2e"; TEXT  = "#ecf0f1"
        SUBTEXT = "#7f8c8d"; GRID  = "#2c3e50"
        label_counts = df["label"].value_counts()
        overall      = df["compound"].mean()
        ax1 = fig.add_subplot(gs[0,0])
        cnts = [label_counts.get("Bullish",0), label_counts.get("Neutral",0),
                label_counts.get("Bearish",0)]
        if sum(cnts) > 0:
            ax1.pie(cnts, labels=["Bullish","Neutral","Bearish"],
                    colors=[GREEN, ORANGE, RED], autopct="%1.0f%%", startangle=140,
                    textprops={"color": TEXT, "fontsize": 10})
        ax1.set_title("Sentiment Distribution", fontsize=11)
        ax2 = fig.add_subplot(gs[0,1])
        df_sorted = df.sort_values("datetime")
        clrs = [GREEN if v>=0.05 else (RED if v<=-0.05 else ORANGE)
                for v in df_sorted["compound"]]
        ax2.scatter(df_sorted["datetime"], df_sorted["compound"],
                    c=clrs, alpha=0.65, s=30, edgecolors="none")
        ax2.axhline(0,    color=SUBTEXT, lw=1,   ls="--")
        ax2.axhline(0.05, color=GREEN,   lw=0.8, ls=":", alpha=0.5)
        ax2.axhline(-0.05,color=RED,     lw=0.8, ls=":", alpha=0.5)
        if len(df_sorted) > 5:
            roll = df_sorted.set_index("datetime")["compound"].rolling(5, min_periods=1).mean()
            ax2.plot(roll.index, roll.values, color="white", lw=2, alpha=0.8, label="5-art MA")
            ax2.legend(fontsize=8)
        ax2.set_ylabel("Compound Score"); ax2.set_title("Sentiment Timeline")
        ax2.grid(alpha=0.2); ax2.set_facecolor(PANEL_BG)
        ax2.tick_params(axis="x", rotation=30)
        ax3 = fig.add_subplot(gs[0,2])
        src_avg = (df.groupby("source")["compound"]
                     .agg(["mean","count"])
                     .sort_values("count", ascending=False)
                     .head(10))
        colors_src = [GREEN if v>=0.05 else (RED if v<=-0.05 else ORANGE)
                      for v in src_avg["mean"]]
        ax3.barh(src_avg.index, src_avg["count"], color=ACCENT, alpha=0.8)
        ax3_twin = ax3.twiny()
        ax3_twin.plot(src_avg["mean"], src_avg.index, "o-",
                      color="white", markersize=4, lw=1.5)
        ax3_twin.axvline(0, color=SUBTEXT, lw=1, ls="--")
        ax3.set_xlabel("Article Count"); ax3_twin.set_xlabel("Avg Sentiment")
        ax3.set_title("News Sources"); ax3.set_facecolor(PANEL_BG)
        ax3.grid(axis="x", alpha=0.2)
        ax4 = fig.add_subplot(gs[1,0])
        ax4.hist(df["compound"], bins=28, color=ACCENT, alpha=0.8,
                 edgecolor="white", lw=0.4)
        ax4.axvline(0, color=SUBTEXT, lw=1.5, ls="--")
        ax4.axvline(overall, color="white", lw=2, ls="-",
                    label=f"Mean ({overall:+.3f})")
        ax4.set_xlabel("Compound Score"); ax4.set_ylabel("Count")
        ax4.set_title("Score Distribution"); ax4.legend(fontsize=8)
        ax4.grid(axis="y", alpha=0.2); ax4.set_facecolor(PANEL_BG)
        ax5 = fig.add_subplot(gs[1,1])
        ds   = df.sort_values("datetime").set_index("datetime")
        cumS = ds["compound"].cumsum()
        ax5.fill_between(cumS.index, cumS, 0,
                         where=cumS>=0, color=GREEN, alpha=0.3, interpolate=True)
        ax5.fill_between(cumS.index, cumS, 0,
                         where=cumS< 0, color=RED,   alpha=0.3, interpolate=True)
        ax5.plot(cumS.index, cumS, color="white", lw=1.5)
        ax5.axhline(0, color=SUBTEXT, lw=1, ls="--")
        ax5.set_ylabel("Cumulative Score"); ax5.set_title("Sentiment Momentum")
        ax5.grid(alpha=0.2); ax5.set_facecolor(PANEL_BG)
        ax5.tick_params(axis="x", rotation=30)
        ax6 = fig.add_subplot(gs[1,2])
        orig_vc = df["origin"].value_counts()
        ax6.pie(orig_vc.values, labels=orig_vc.index,
                colors=[ACCENT, GREEN, ORANGE, RED][:len(orig_vc)],
                autopct="%1.0f%%", startangle=90,
                textprops={"color": TEXT, "fontsize": 10})
        ax6.set_title("Source Breakdown by Origin")
        fig.patch.set_facecolor("#0d0d1a")
        plt.tight_layout()
        plt.show()
    def _chat_loop(system_prompt: str, seed_messages: list[dict]):
        _WARN = 6_000
        chat_history = list(seed_messages)                           
        turn         = 0
        console.print(
            Panel(
                "[bold cyan]💬 AI Follow-up Chat[/]\n\n"
                "Ask anything about the headlines, sentiment, or analysis above.\n"
                "Full context is retained across turns.\n\n"
                "[bold]Commands:[/]  "
                "[cyan]clear[/] — reset history   "
                "[cyan]history[/] — token estimate   "
                "[cyan]exit[/] — return to menu",
                border_style="cyan",
                title="[bold white]Chat Mode[/]",
                expand=False,
            )
        )
        while True:
            est_tok = sum(len(m["content"]) for m in chat_history) // 4
            tok_tag = (
                f"[yellow]~{est_tok} tokens ⚠[/]" if est_tok >= _WARN
                else f"[dim]~{est_tok} tokens[/]"
            )
            user_q = Prompt.ask(
                f"\n  [bold cyan]You[/] [dim](turn {turn+1} | {tok_tag})[/]"
            ).strip()
            if not user_q:           continue
            if user_q.lower()=="exit":
                console.print("  [dim]Returning to menu…[/]"); break
            if user_q.lower()=="clear":
                chat_history = [{"role":"system","content":system_prompt}]
                turn = 0
                console.print("  [green]✓ History cleared.[/]"); continue
            if user_q.lower()=="history":
                console.print(
                    f"  Turns: {turn}  |  Messages: {len(chat_history)}  |  "
                    f"Est. tokens: {est_tok}"
                ); continue
            chat_history.append({"role":"user","content":user_q})
            reply, lat = _ai_call_threaded(
                system_prompt,
                "\n".join(
                    f"{m['role'].upper()}: {m['content']}"
                    for m in chat_history[1:]                
                )
            )
            if reply:
                console.print(
                    Panel(Markdown(reply),
                          border_style="green",
                          title=f"[bold green]Assistant[/] [dim]({lat:.2f}s)[/]",
                          expand=False)
                )
                chat_history.append({"role":"assistant","content":reply})
                turn += 1
            else:
                chat_history.pop()                               
