        if OR_API_KEY and ai_reply:
            sys_p    = _news_analyst_system(context_tag)
            seed_msgs = [
                {"role":"system",    "content": sys_p},
                {"role":"user",      "content": stats_block},
                {"role":"assistant", "content": ai_reply},
            ]
            go_chat = Prompt.ask(
                "\n  Chat with AI about these headlines? [Y/N]", default="N"
            ).strip().upper()
            if go_chat == "Y":
                _chat_loop(sys_p, seed_msgs)
        Prompt.ask("\n  [dim]Press ENTER to return…[/]")
