    def _cache_key(sid):
        h = hashlib.md5(sid.encode()).hexdigest()[:12]
        return CACHE_DIR / f"{sid}_{h}.json"
    def _cache_valid(p):
        if not p.exists(): return False
        return (time.time() - p.stat().st_mtime) / 3600 < CACHE_TTL_H
    def fetch_fred(series_id):
        cp = _cache_key(series_id)
        if _cache_valid(cp):
            try:
                saved = json.loads(cp.read_text())
                df = pd.DataFrame({"VAL": saved["VAL"]},
                                  index=pd.to_datetime(saved["index"]))
                _cache_hits[0] += 1
                return df
            except: pass
        _cache_miss[0] += 1
        url = (f"{FRED_BASE}?series_id={series_id}&api_key={FRED_API_KEY}"
               "&file_type=json&sort_order=asc&observation_start=2000-01-01")
        data = None
        for attempt in range(3):
            try:
                req = urllib.request.Request(url, headers={"User-Agent": "Module38/4.0"})
                with urllib.request.urlopen(req, timeout=15) as res:
                    data = json.loads(res.read().decode())
                break
            except Exception:
                if attempt < 2: time.sleep(2 ** attempt)
        if data is None:
            return pd.DataFrame()
        dates, vals = [], []
        for obs in data.get("observations", []):
            try:
                dates.append(pd.to_datetime(obs["date"]))
                vals.append(float(obs["value"]))
            except (ValueError, KeyError):
                continue
        if not dates:
            return pd.DataFrame()
        df = pd.DataFrame({"VAL": vals}, index=pd.to_datetime(dates)).dropna()
        try:
            cp.write_text(json.dumps({"VAL": df["VAL"].tolist(),
                                      "index": [str(d) for d in df.index]}))
        except: pass
        return df
    def _process_series(label, series_id, is_yoy, n_periods, freq="Q"):
        try:
            raw = fetch_fred(series_id)
            if raw is None or raw.empty: return label, None
            rs = raw.resample(freq).last().dropna()
            if is_yoy:
                rs = (rs.pct_change(4 if freq=="Q" else 12) * 100).dropna()
            return label, rs.tail(n_periods)
        except Exception:
            return label, None
    def _harvest(futures_map, timeout):
        out = {}
        try:
            for fut in as_completed(futures_map, timeout=timeout):
                try:
                    out[futures_map[fut]] = fut.result()
                except Exception:
                    pass
        except TimeoutError:
            for fut, key in futures_map.items():
                if fut.done():
                    try:
                        out[key] = fut.result()
                    except Exception:
                        pass
        return out
    def _fetch_country_parallel(country, n_quarters=20):
        labels = COUNTRY_INDICATORS.get(country, [])
        tasks  = [(lbl, *INDICATORS[lbl][:2]) for lbl in labels if lbl in INDICATORS]
        with ThreadPoolExecutor(max_workers=8) as pool:
            futures = {pool.submit(_process_series, lbl, sid, yoy, n_quarters, "Q"): lbl
                       for lbl, sid, yoy in tasks}
            harvested = _harvest(futures, timeout=60)
        return {lbl: df for lbl, (_, df) in harvested.items()
                if df is not None and not df.empty}
    def _sparkline(values, width=8):
        BARS = "▁▂▃▄▅▆▇█"
        clean = [v for v in values if v is not None]
        if len(clean) < 2: return "[dim]——[/]"
        mn, mx = min(clean), max(clean)
        rng = mx - mn
        result = ""
        for v in clean[-width:]:
            idx = int((v - mn) / rng * (len(BARS)-1)) if rng > 0 else 3
            result += BARS[idx]
        return result
    def _zscore(series, value):
        if len(series) < 4: return 0.0
        mu, std = series.mean(), series.std()
        return (value - mu) / std if std > 0 else 0.0
    def _zclr(z):
        if z >  2.0: return "bold red"
        if z >  1.0: return "red"
        if z >  0.3: return "yellow"
        if z < -2.0: return "bold green"
        if z < -1.0: return "green"
        if z < -0.3: return "cyan"
        return "white"
    ALERT_RULES = [
        ("US 10Y-2Y Spread (%)",     lambda v: v < 0,    "Yield curve INVERTED (10Y-2Y)"),
        ("US 10Y-3M Spread (%)",     lambda v: v < 0,    "Yield curve INVERTED (10Y-3M)"),
        ("US Credit Spread (HY)",    lambda v: v > 6.0,  "HY credit spreads elevated >6%"),
        ("US Financial Cond. Index", lambda v: v > 0.5,  "Financial conditions tightening"),
        ("US CPI YoY (%)",           lambda v: v > 5.0,  "US CPI above 5% — inflation hot"),
        ("US CPI YoY (%)",           lambda v: v < 1.0,  "US CPI below 1% — deflation risk"),
        ("India CPI YoY (%)",        lambda v: v > 6.0,  "India CPI above RBI upper band 6%"),
        ("Euro CPI YoY (%)",         lambda v: v > 4.0,  "Euro CPI elevated >4%"),
        ("US Unemployment (%)",      lambda v: v > 6.0,  "US unemployment rising sharply"),
        ("Argentina CPI YoY (%)",    lambda v: v > 50,   "Argentina hyperinflation risk"),
    ]
    def _compute_alerts(results):
        alerts = []
        for ind, rule, msg in ALERT_RULES:
            if ind in results and not results[ind].empty:
                try:
                    v = float(results[ind]["VAL"].iloc[-1])
                    if rule(v): alerts.append((msg, v))
                except: pass
        return alerts
    def _ai_call(system_p, user_p):
        if not OR_API_KEY:
            return "[AI UNAVAILABLE] Configure API key in [S] Settings.", 0.0
        bag = {}
        done = threading.Event()
        def _worker():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization": f"Bearer {OR_API_KEY}",
                             "Content-Type": "application/json",
                             "X-Title": "Module38-v4"},
                    json={"model": OR_MODEL,
                          "messages": [{"role":"system","content":system_p},
                                       {"role":"user","content":user_p}],
                          "temperature": 0.3},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter() - t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter() - t0
            finally: done.set()
        threading.Thread(target=_worker, daemon=True).start()
        spin = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; idx = 0; t0 = time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[idx%len(spin)]} AI thinking… {time.perf_counter()-t0:.1f}s   ",
                  end="", flush=True); idx += 1
        print()
        return bag.get("reply",""), bag.get("latency", 0.0)
