    def _chat_loop(sys_p, seed):
        history = list(seed)
        turn = 0
        console.print(Panel(
            "[bold cyan]💬 AI Chat[/]\n"
            "Commands: [cyan]clear[/]  [cyan]history[/]  [cyan]exit[/]",
            border_style="cyan", expand=False
        ))
        while True:
            est = sum(len(m["content"]) for m in history) // 4
            tok = f"[{'yellow' if est>=6000 else 'dim'}]~{est} tokens[/]"
            q = Prompt.ask(f"\n  [bold cyan]You[/] [dim](turn {turn+1}|{tok})[/]").strip()
            if not q: continue
            if q.lower() == "exit": break
            if q.lower() == "clear":
                history = [{"role":"system","content":sys_p}]; turn = 0
                console.print("  [green]✓ Cleared.[/]"); continue
            if q.lower() == "history":
                console.print(f"  Turns:{turn} Msgs:{len(history)} ~{est} tokens"); continue
            history.append({"role":"user","content":q})
            conv = "\n".join(f"{m['role'].upper()}: {m['content']}" for m in history[1:])
            reply, lat = _ai_call(sys_p, conv)
            if reply:
                console.print(Panel(Markdown(reply), border_style="green",
                    title=f"[bold green]Assistant[/] [dim]({lat:.2f}s)[/]", expand=False))
                history.append({"role":"assistant","content":reply}); turn += 1
            else:
                history.pop()
