class PredictionMarketOracle:
    def __init__(self, ticker=None):
        self.markets_data  : list[dict] = []
        self.portfolio     : list[dict] = []                   
        self.bankroll      : float      = 1000.0
        self.kelly_mode    : str        = "Quarter Kelly"
        self.min_volume    : float      = 0.0                                                                    
        self.min_edge      : float      = 0.02                               
        self._or_key   : str = ""
        self._or_model : str = _GLOBAL_OR_MODEL
        self._load_or_config()
        CACHE_DIR.mkdir(exist_ok=True)
    def _load_or_config(self):
        self._or_key   = _GLOBAL_OR_KEY
        self._or_model = _GLOBAL_OR_MODEL
    def _save_or_config(self):
        try:
            pass                                            
        except: pass
    def _cache_path(self, key: str) -> Path:
        h = hashlib.md5(key.encode()).hexdigest()[:10]
        return CACHE_DIR / f"{h}.json"
    def _cache_valid(self, key: str) -> bool:
        p = self._cache_path(key)
        return p.exists() and (time.time() - p.stat().st_mtime) < CACHE_TTL
    def _load_cache(self, key: str) -> Optional[list]:
        try:
            return json.loads(self._cache_path(key).read_text())
        except: return None
    def _save_cache(self, key: str, data) -> None:
        try:
            self._cache_path(key).write_text(json.dumps(data))
        except: pass
    def fetch_live_markets(self,
                            limit        : int  = 50000,
                            search_query : str  = "",
                            category     : str  = "",
                            use_cache    : bool = True) -> bool:
        from rich.console   import Console
        from rich.progress  import Progress, SpinnerColumn, BarColumn, TextColumn
        console = Console()
        cache_key = f"markets_v3:{limit}:{search_query}:{category}"
        if use_cache and self._cache_valid(cache_key):
            cached = self._load_cache(cache_key)
            if cached:
                self.markets_data = cached
                console.print(f"  [dim]Cache: {len(cached)} markets (TTL {CACHE_TTL//60}m)[/]")
                return True
        hdrs = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
            "Accept"    : "application/json",
        }
        raw_all : list[dict] = []
        PAGE_SIZE = 100
        with Progress(
            SpinnerColumn(),
            TextColumn("[bold cyan]Fetching Polymarket Universe…[/]"),
            BarColumn(),
            TextColumn("{task.completed} pages"),
            console=console, transient=True
        ) as prog:
            m_task = prog.add_task("Markets", total=None)
            for page in range(500):                    
                url = f"{POLY_API}/markets?active=true&closed=false&limit={PAGE_SIZE}&offset={page*PAGE_SIZE}&order=volume&ascending=false"
                try:
                    res = requests.get(url, headers=hdrs, timeout=15)
                    if not res.ok: break
                    batch = res.json()
                    if not batch: break
                    raw_all.extend(batch)
                    prog.advance(m_task)
                    if len(batch) < PAGE_SIZE: break
                except: break
                if len(raw_all) >= limit: break
                time.sleep(0.05)
            e_task = prog.add_task("Events", total=None)
            for page in range(100):                   
                url = f"{POLY_API}/events?active=true&closed=false&limit={PAGE_SIZE}&offset={page*PAGE_SIZE}&order=volume&ascending=false"
                try:
                    res = requests.get(url, headers=hdrs, timeout=15)
                    if not res.ok: break
                    batch = res.json()
                    if not batch: break
                    for ev in batch:
                        mkt_list = ev.get('markets', [])
                        for mkt in mkt_list:
                            mkt.setdefault('question', ev.get('title', mkt.get('question','')))
                            mkt.setdefault('volume', ev.get('volume', 0))
                            mkt.setdefault('description', ev.get('description', ''))
                            raw_all.append(mkt)
                    prog.advance(e_task)
                    if len(batch) < PAGE_SIZE: break
                except: break
                time.sleep(0.05)
        seen = set(); deduped = []
        for m in raw_all:
            mid = str(m.get('id') or m.get('conditionId') or m.get('asset_address') or hash(m.get('question','')))
            if mid not in seen and mid != 'None':
                seen.add(mid)
                deduped.append(m)
        markets = []
        for m in deduped:
            question = (m.get('question') or m.get('title') or '').strip()
            if not question: continue
            if search_query and search_query.lower() not in question.lower(): continue
            cat = self._classify(question)
            if category and category.lower() not in cat.lower(): continue
            try:
                v_raw = m.get('volume') or m.get('volumeNum') or 0
                vol = float(str(v_raw).replace(',',''))
            except: vol = 0.0
            if vol < self.min_volume: continue
            yp = np_ = None
            outcomes = m.get('outcomes') or []
            prices   = m.get('outcomePrices') or []
            if isinstance(outcomes, str): 
                try: outcomes = json.loads(outcomes)
                except: outcomes = []
            if isinstance(prices, str):
                try: prices = json.loads(prices)
                except: prices = []
            out_norm = [str(o).strip().upper() for o in outcomes]
            if 'YES' in out_norm:
                yi = out_norm.index('YES')
                try: yp = float(prices[yi])
                except: pass
            if 'NO' in out_norm:
                ni = out_norm.index('NO')
                try: np_ = float(prices[ni])
                except: pass
            if yp is None or np_ is None:
                for t in m.get('tokens', []):
                    oc = str(t.get('outcome','')).upper()
                    pr = t.get('price') or t.get('lastPrice')
                    try:
                        if oc == 'YES': yp = float(pr)
                        elif oc == 'NO': np_ = float(pr)
                    except: pass
            if yp is None:
                try: yp = float(m.get('bestBid') or m.get('lastPrice') or 0)
                except: pass
            if yp is None: continue                        
            if np_ is None: np_ = 1.0 - yp
            if not (0 <= yp <= 1 and 0 <= np_ <= 1): continue
            vig = round((yp + np_ - 1.0) * 100, 2)
            end_raw = m.get('endDate') or m.get('end_date_iso') or 'TBD'
            markets.append({
                'id'      : str(m.get('id') or m.get('conditionId') or ''),
                'question': question,
                'volume'  : vol,
                'yes_prob': round(yp, 4),
                'no_prob' : round(np_, 4),
                'vig_pct' : vig,
                'category': cat,
                'end_date': end_raw[:10],
                'slug'    : m.get('slug') or '',
                'url'     : f"https://polymarket.com/event/{m.get('slug','')}"
            })
        markets.sort(key=lambda x: x['volume'], reverse=True)
        self.markets_data = markets
        self._save_cache(cache_key, markets)
        console.print(f"  [green]✓[/] [bold]{len(markets)}[/] markets loaded (vol≥${self.min_volume:,.0f})")
        return True
    def _classify(self, question: str) -> str:
        ql = question.lower()
        for cat, keywords in CATEGORY_KEYWORDS.items():
            if any(kw in ql for kw in keywords):
                return cat
        return "Other"
    def _ev(self, true_prob: float, cost: float) -> float:
        p_win  = true_prob
        p_loss = 1.0 - true_prob
        return (p_win * (1.0 - cost)) - (p_loss * cost)
    def _kelly(self, ev: float, cost: float) -> float:
        if cost <= 0 or cost >= 1:
            return 0.0
        b = (1.0 - cost) / cost             
        if b <= 0:
            return 0.0
        return max(0.0, ev / b)
    def _breakeven(self, cost: float) -> float:
        return cost
    def _roi(self, cost: float) -> float:
        if cost <= 0 or cost >= 1: return 0.0
        return (1.0 - cost) / cost * 100.0
    def _sharpe_kelly(self, ev: float, cost: float, n_std: float = 2.0) -> float:
        true_prob = cost                                                
        sigma = math.sqrt(true_prob * (1 - true_prob)) if 0 < true_prob < 1 else 1.0
        full_k = self._kelly(ev, cost)
        return full_k * (ev / (n_std * sigma)) if sigma > 0 else 0.0
    def calculate_full_edge(self, market: dict,
                             true_prob_yes: float) -> dict:
        tp_yes = true_prob_yes / 100.0
        tp_no  = 1.0 - tp_yes
        yc     = market['yes_prob']
        nc     = market['no_prob']
        ev_yes = self._ev(tp_yes, yc)
        ev_no  = self._ev(tp_no,  nc)
        fk_yes = self._kelly(ev_yes, yc)
        fk_no  = self._kelly(ev_no,  nc)
        frac   = KELLY_FRACS.get(self.kelly_mode, 0.25)
        def _bet(full_k) -> float:
            return max(0.0, min(full_k * frac, 0.30)) * self.bankroll
        return {
            "true_prob_yes"  : tp_yes,
            "true_prob_no"   : tp_no,
            "ev_yes"         : round(ev_yes, 4),
            "ev_no"          : round(ev_no,  4),
            "roi_yes"        : round(self._roi(yc), 2),
            "roi_no"         : round(self._roi(nc), 2),
            "full_kelly_yes" : round(fk_yes, 4),
            "full_kelly_no"  : round(fk_no,  4),
            "kelly_frac"     : frac,
            "kelly_mode"     : self.kelly_mode,
            "bet_yes_$"      : round(_bet(fk_yes), 2),
            "bet_no_$"       : round(_bet(fk_no),  2),
            "breakeven_yes"  : round(self._breakeven(yc)*100, 1),
            "breakeven_no"   : round(self._breakeven(nc)*100, 1),
            "edge_yes_pct"   : round((tp_yes - yc)*100, 2),
            "edge_no_pct"    : round((tp_no  - nc)*100, 2),
            "best_side"      : ("YES" if ev_yes > ev_no and ev_yes > 0
                                else "NO"  if ev_no > 0
                                else "NO BET"),
            "vig_pct"        : market['vig_pct'],
        }
    def portfolio_kelly(self) -> dict:
        if not self.portfolio:
            return {}
        n   = len(self.portfolio)
        frac= KELLY_FRACS.get(self.kelly_mode, 0.25)
        total_allocated = sum(p.get('bet_$', 0) for p in self.portfolio)
        total_ev        = sum(p.get('ev', 0) for p in self.portfolio)
        max_single_pct  = frac / n                                
        return {
            'n_positions'       : n,
            'total_allocated_$' : round(total_allocated, 2),
            'total_ev'          : round(total_ev, 4),
            'max_single_pct'    : round(max_single_pct * 100, 1),
            'recommended_bank_$': round(total_allocated * 1.5, 2),                      
        }
    def _scan_for_edges(self) -> list[dict]:
        flagged = []
        for m in self.markets_data:
            yp = m['yes_prob']
            np = m['no_prob']
            vig = m['vig_pct']
            if vig < 2.0:
                flagged.append({**m, 'flag': 'LOW VIG', 'note':
                                f"Only {vig:.2f}% overround — tight market, fair prices"})
            if yp < 0.05 or yp > 0.95:
                flagged.append({**m, 'flag': 'EXTREME ODDS', 'note':
                                f"YES at {yp*100:.1f}% — tail events often mispriced"})
        return sorted(flagged, key=lambda x: x['volume'], reverse=True)[:10]
    def render_market_table(self, display_data=None, title="🔮 POLYMARKET LIVE MARKETS",
                            current_page=0, page_size=30) -> int:
        from rich.console import Console
        from rich.table   import Table
        from rich.rule    import Rule
        from rich         import box as _box
        console = Console()
        markets = display_data if display_data is not None else self.markets_data
        if not markets:
            console.print("  [dim]No markets found matching criteria.[/]")
            return 1
        total_pages = max(1, math.ceil(len(markets) / max(1, page_size)))
        current_page = max(0, min(current_page, total_pages - 1))
        start_idx = current_page * page_size
        end_idx   = start_idx + page_size
        page_markets = markets[start_idx:end_idx]
        ui_title = f"[bold cyan]{title}[/]  [dim](Page {current_page+1}/{total_pages})[/]"
        console.print(Rule(ui_title))
        tbl = Table(box=_box.SIMPLE_HEAVY, header_style="bold cyan", expand=True)
        tbl.add_column("#", width=4, justify="right")
        tbl.add_column("Market", width=55)
        tbl.add_column("Vol ($)", width=10, justify="right")
        tbl.add_column("YES %", width=8, justify="right")
        tbl.add_column("NO %", width=8, justify="right")
        tbl.add_column("Vig", width=7, justify="right")
        tbl.add_column("Ends", width=11, justify="right")
        for i, m in enumerate(page_markets):
            global_idx = start_idx + i + 1
            question = m.get('question', '')
            if len(question) > 52:
                question = question[:49] + "..."
            yp = m.get('yes_prob', 0) * 100
            np_ = m.get('no_prob', 0) * 100
            yp_str = f"[green]{yp:.1f}%[/]" if yp >= 50 else f"{yp:.1f}%"
            np_str = f"[red]{np_:.1f}%[/]" if np_ >= 50 else f"{np_:.1f}%"
            tbl.add_row(
                str(global_idx),
                question,
                f"{m.get('volume', 0):,.0f}",
                yp_str,
                np_str,
                f"{m.get('vig_pct', 0):.2f}%",
                str(m.get('end_date', ''))[:10]
            )
        console.print(tbl)
        return total_pages
    def _web_search_sentiment(self, question: str,
                               end_date: str = "") -> dict:
        try:
            pass
        except ImportError:
            return _empty_sentiment()
        from rich.console  import Console
        from rich.progress import Progress, SpinnerColumn, TextColumn
        console = Console()
        def _empty_sentiment():
            return {
                'sentiment_label'  : 'Unavailable',
                'sentiment_score'  : 0.0,
                'yes_bias_pct'     : 0.0,
                'weighted_prob'    : None,
                'confidence_low'   : None,
                'confidence_high'  : None,
                'source_breakdown' : {},
                'headlines'        : [],
                'search_digest'    : '',
            }
        stop = {'will','the','a','an','be','is','are','does','do',
                'in','on','at','by','for','of','to','this','that',
                'before','after','end','during','within','ever'}
        words = [w for w in re.sub(r'[^\w\s]','',question).lower().split()
                 if w not in stop]
        core_query    = " ".join(words[:8])
        precise_query = question[:120]
        year_hint     = end_date[:4] if end_date and end_date != 'TBD' else ""
        if year_hint:
            core_query += f" {year_hint}"
        headlines     : list[dict] = []
        source_scores : dict[str, list[float]] = {}
        hdrs = {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 Chrome/124 Safari/537.36"
            )
        }
        with Progress(
            SpinnerColumn(),
            TextColumn("[bold cyan]{task.description}[/]"),
            console=console, transient=True
        ) as prog:
            task = prog.add_task("Searching Google News…", total=None)
            try:
                prog.update(task, description="Google News RSS…")
                import xml.etree.ElementTree as ET
                for q in [precise_query, core_query]:
                    rss_url = (
                        f"https://news.google.com/rss/search"
                        f"?q={requests.utils.quote(q)}"
                        f"&hl=en-US&gl=US&ceid=US:en"
                    )
                    rss = requests.get(rss_url, headers=hdrs, timeout=12).text
                    root = ET.fromstring(rss)
                    for item in root.findall('.//item')[:12]:
                        t   = (item.findtext('title')       or '').strip()
                        src = (item.findtext('source')      or 'Google News').strip()
                        lnk = (item.findtext('link')        or '').strip()
                        pub = (item.findtext('pubDate')      or '').strip()[:16]
                        desc= (item.findtext('description') or '').strip()[:200]
                        if t and not any(h['title']==t for h in headlines):
                            headlines.append({
                                'source'   : src,
                                'title'    : t,
                                'snippet'  : desc,
                                'url'      : lnk,
                                'pub_date' : pub,
                                'src_type' : 'google_news',
                            })
            except Exception:
                pass
            try:
                prog.update(task, description="DuckDuckGo…")
                ddg_url = (
                    f"https://api.duckduckgo.com/"
                    f"?q={requests.utils.quote(core_query)}"
                    f"&format=json&no_html=1&skip_disambig=1"
                )
                ddg = requests.get(ddg_url, headers=hdrs, timeout=10).json()
                abstract = ddg.get('AbstractText','').strip()
                if abstract:
                    headlines.append({
                        'source'  : ddg.get('AbstractSource','DDG'),
                        'title'   : abstract[:200],
                        'snippet' : '',
                        'url'     : ddg.get('AbstractURL',''),
                        'pub_date': '',
                        'src_type': 'ddg_abstract',
                    })
                for topic in ddg.get('RelatedTopics',[])[:6]:
                    text = topic.get('Text','').strip()
                    if text:
                        headlines.append({
                            'source'  : 'DuckDuckGo',
                            'title'   : text[:200],
                            'snippet' : '',
                            'url'     : topic.get('FirstURL',''),
                            'pub_date': '',
                            'src_type': 'ddg_related',
                        })
            except Exception:
                pass
            try:
                prog.update(task, description="Bing News…")
                import xml.etree.ElementTree as ET
                bing_url = (
                    f"https://www.bing.com/news/search"
                    f"?q={requests.utils.quote(core_query)}"
                    f"&format=rss"
                )
                bing_rss = requests.get(
                    bing_url, headers=hdrs, timeout=10
                ).text
                br = ET.fromstring(bing_rss)
                for item in br.findall('.//item')[:8]:
                    t   = (item.findtext('title')       or '').strip()
                    src = (item.findtext('source')      or 'Bing News').strip()
                    lnk = (item.findtext('link')        or '').strip()
                    pub = (item.findtext('pubDate')     or '').strip()[:16]
                    desc= (item.findtext('description') or '').strip()[:200]
                    if t and not any(h['title']==t for h in headlines):
                        headlines.append({
                            'source'  : src or 'Bing News',
                            'title'   : t,
                            'snippet' : desc,
                            'url'     : lnk,
                            'pub_date': pub,
                            'src_type': 'bing_news',
                        })
            except Exception:
                pass
            try:
                prog.update(task, description="Reddit signal…")
                import xml.etree.ElementTree as ET
                reddit_url = (
                    f"https://www.reddit.com/search.rss"
                    f"?q={requests.utils.quote(core_query)}"
                    f"&sort=relevance&t=month&limit=8"
                )
                r_rss = requests.get(
                    reddit_url,
                    headers={**hdrs, "User-Agent":"prediction_market_bot/1.0"},
                    timeout=10
                ).text
                rr = ET.fromstring(r_rss)
                NS = {'atom':'http://www.w3.org/2005/Atom'}
                for entry in rr.findall('atom:entry', NS)[:6]:
                    t   = (entry.findtext('atom:title',   '', NS) or '').strip()
                    lnk_el = entry.find('atom:link', NS)
                    lnk = lnk_el.get('href','') if lnk_el is not None else ''
                    if t and not any(h['title']==t for h in headlines):
                        headlines.append({
                            'source'  : 'Reddit',
                            'title'   : t[:200],
                            'snippet' : '',
                            'url'     : lnk,
                            'pub_date': '',
                            'src_type': 'reddit',
                        })
            except Exception:
                pass
            wiki_context = ""
            try:
                prog.update(task, description="Wikipedia base-rate…")
                short_q = " ".join(words[:4])
                wiki_url = (
                    f"https://en.wikipedia.org/api/rest_v1/page/summary/"
                    f"{requests.utils.quote(short_q.replace(' ','_'))}"
                )
                wk = requests.get(wiki_url, headers=hdrs, timeout=8).json()
                if wk.get('extract'):
                    wiki_context = wk['extract'][:600]
            except Exception:
                pass
        if not headlines and not wiki_context:
            return _empty_sentiment()
        PRED_LEXICON = {
            'likely'    : +2.0, 'unlikely'     : -2.0,
            'certain'   : +2.5, 'uncertain'    : -1.5,
            'imminent'  : +1.8, 'impossible'   : -2.5,
            'confirmed' : +2.5, 'denied'       : -2.5,
            'approved'  : +2.0, 'rejected'     : -2.0,
            'passes'    : +2.0, 'fails'        : -2.0,
            'wins'      : +2.0, 'loses'        : -2.0,
            'surges'    : +1.5, 'crashes'      : -2.0,
            'rises'     : +1.2, 'falls'        : -1.2,
            'growing'   : +1.0, 'declining'    : -1.2,
            'record'    : +1.0, 'collapse'     : -2.0,
            'milestone' : +1.2, 'crisis'       : -1.5,
            'accelerate': +1.2, 'delayed'      : -1.0,
            'breakthrough': +2.0,'setback'     : -1.5,
            'landmark'  : +1.5, 'blocked'      : -1.8,
            'agreement' : +1.5, 'dispute'      : -1.2,
            'historic'  : +1.2, 'unprecedented': +0.5,
        }
        scores_by_source : dict[str, list[float]] = {}
        try:
            from nltk.sentiment.vader import SentimentIntensityAnalyzer
            import nltk
            try: nltk.data.find('sentiment/vader_lexicon.zip')
            except: nltk.download('vader_lexicon', quiet=True)
            sia = SentimentIntensityAnalyzer()
            sia.lexicon.update(PRED_LEXICON)
            for h in headlines:
                text  = h['title'] + " " + h.get('snippet','')
                score = sia.polarity_scores(text)['compound']
                h['score'] = round(score, 3)
                st = h['src_type']
                scores_by_source.setdefault(st, []).append(score)
        except ImportError:
            POS_KW = list(PRED_LEXICON.keys())[:len(PRED_LEXICON)//2]
            NEG_KW = list(PRED_LEXICON.keys())[len(PRED_LEXICON)//2:]
            for h in headlines:
                tl = (h['title'] + " " + h.get('snippet','')).lower()
                sc = (sum(PRED_LEXICON[w] for w in POS_KW if w in tl) +
                      sum(PRED_LEXICON[w] for w in NEG_KW if w in tl))
                sc = max(-1.0, min(1.0, sc / 5.0))
                h['score'] = round(sc, 3)
                st = h['src_type']
                scores_by_source.setdefault(st, []).append(sc)
        SOURCE_WEIGHTS = {
            'google_news'  : 1.0,
            'bing_news'    : 1.0,
            'ddg_abstract' : 0.8,
            'ddg_related'  : 0.5,
            'reddit'       : 0.6,
        }
        weighted_sum = 0.0
        weight_total = 0.0
        for src_type, sc_list in scores_by_source.items():
            w = SOURCE_WEIGHTS.get(src_type, 0.7)
            for sc in sc_list:
                weighted_sum += sc * w
                weight_total += w
        avg_score = weighted_sum / max(weight_total, 1e-9)
        MAX_NUDGE    = 15.0
        yes_nudge    = round(avg_score * MAX_NUDGE, 2)
        yes_nudge    = max(-MAX_NUDGE, min(MAX_NUDGE, yes_nudge))
        if len(headlines) >= 3:
            all_scores = [h.get('score', 0) for h in headlines]
            import statistics
            score_std  = statistics.stdev(all_scores) if len(all_scores)>1 else 0.3
            ci_half    = round(score_std * 20, 1)        
        else:
            ci_half = 12.0                                             
        if avg_score >= 0.30:
            label = "Strongly Bullish for YES"
        elif avg_score >= 0.10:
            label = "Mildly Bullish for YES"
        elif avg_score <= -0.30:
            label = "Strongly Bearish for YES"
        elif avg_score <= -0.10:
            label = "Mildly Bearish for YES"
        else:
            label = "Neutral / Conflicting"
        digest_lines = [
            f"=== WEB SEARCH + SENTIMENT ANALYSIS ===",
            f"Search queries: '{precise_query[:60]}' / '{core_query}'",
            f"Headlines found: {len(headlines)} "
            f"(Google:{len(scores_by_source.get('google_news',[]))}  "
            f"Bing:{len(scores_by_source.get('bing_news',[]))}  "
            f"Reddit:{len(scores_by_source.get('reddit',[]))}  "
            f"DDG:{len(scores_by_source.get('ddg_abstract',[]))+len(scores_by_source.get('ddg_related',[]))})",
            f"Weighted Sentiment Score: {avg_score:+.3f}",
            f"Sentiment Label: {label}",
            f"Suggested YES probability nudge: {yes_nudge:+.1f} percentage points",
            f"Confidence interval halfwidth: ±{ci_half:.1f}pp",
            "",
            "Top Headlines (sorted by signal strength):",
        ]
        top_hl = sorted(headlines, key=lambda x: abs(x.get('score',0)), reverse=True)
        for h in top_hl[:10]:
            sc_str = f"{h.get('score',0):+.2f}"
            digest_lines.append(
                f"  [{sc_str}] [{h['source'][:12]}] "
                f"{h['title'][:100]}"
                + (f" | {h['snippet'][:60]}" if h.get('snippet') else "")
            )
        if wiki_context:
            digest_lines += [
                "",
                "Wikipedia Context (base-rate reference):",
                wiki_context[:500],
            ]
        console.print(
            f"  [green]✓[/] Sentiment: "
            f"[{'green' if avg_score>0.1 else 'red' if avg_score<-0.1 else 'yellow'}]"
            f"{label}[/]  "
            f"score={avg_score:+.3f}  "
            f"nudge={yes_nudge:+.1f}pp  "
            f"CI=±{ci_half:.1f}pp  "
            f"n={len(headlines)}"
        )
        return {
            'sentiment_label'  : label,
            'sentiment_score'  : round(avg_score, 3),
            'yes_bias_pct'     : yes_nudge,
            'ci_half_pp'       : ci_half,
            'source_breakdown' : {k: len(v) for k,v in scores_by_source.items()},
            'headlines'        : headlines,
            'search_digest'    : "\n".join(digest_lines),
            'wiki_context'     : wiki_context,
        }
    def _advanced_category_search(self) -> list[dict]:
        from rich.console import Console
        from rich.prompt  import Prompt
        from rich.table   import Table
        from rich         import box as _box
        console = Console()
        cats = list(CATEGORY_KEYWORDS.keys())
        console.print("\n  [bold]Main Categories:[/]")
        ct = Table(border_style="dim", box=_box.SIMPLE, show_header=False)
        ct.add_column("#", style="bold cyan", width=4)
        ct.add_column("Category", width=16)
        ct.add_column("Markets in universe", justify="right", width=20)
        active_cats = []
        classifications = [self._classify(m['question']) for m in self.markets_data]
        for c in list(CATEGORY_KEYWORDS.keys()) + ["Other"]:
            n = classifications.count(c)
            if n > 0:
                active_cats.append((c, n))
        if not active_cats and self.markets_data:
            active_cats = [("All Markets", len(self.markets_data))]
        for i, (c, n) in enumerate(active_cats, 1):
            ct.add_row(str(i), c, f"[bold cyan]{n}[/]")
        if len(active_cats) > 1:
            ct.add_row(str(len(active_cats)+1), "[bold]ALL CATEGORIES[/]", f"[bold]{len(self.markets_data)}[/]")
        console.print(ct)
        cc = Prompt.ask("  Category #").strip()
        if not cc.isdigit():
            return self.markets_data
        ci = int(cc) - 1
        if ci == len(active_cats):
            return self.markets_data
        if not (0 <= ci < len(active_cats)):
            return self.markets_data
        chosen_cat = active_cats[ci][0]
        cat_markets = [m for m in self.markets_data
                       if self._classify(m['question']) == chosen_cat]
        subs = SUBCATEGORY_MAP.get(chosen_cat, {})
        if subs:
            active_subs = []
            for s, kw_list in subs.items():
                if not kw_list:
                    kw_list = s.lower().replace("/"," ").split()
                n  = sum(1 for m in cat_markets
                         if any(k in m['question'].lower() for k in kw_list))
                if n > 0:
                    active_subs.append((s, n, kw_list))
            if active_subs:
                console.print(f"\n  [bold]{chosen_cat} — Subcategories:[/]")
                st = Table(border_style="dim", box=_box.SIMPLE, show_header=False)
                st.add_column("#", style="bold cyan", width=4)
                st.add_column("Subcategory", width=22)
                st.add_column("Estimated matches", justify="right", width=18)
                for i, (s, n, kw) in enumerate(active_subs, 1):
                    st.add_row(str(i), s, str(n))
                st.add_row(str(len(active_subs)+1), f"All {chosen_cat}", str(len(cat_markets)))
                console.print(st)
                sc = Prompt.ask("  Subcategory # (ENTER for all)").strip()
                if sc.isdigit() and 1 <= int(sc) <= len(active_subs):
                    sub_name, _, kws = active_subs[int(sc)-1]
                    cat_markets = [m for m in cat_markets
                                   if any(k in m['question'].lower() for k in kws)]
        console.print("\n  [bold]Sort by:[/]  "
                      "[cyan]1[/] Volume  [cyan]2[/] YES prob (low→high)  "
                      "[cyan]3[/] NO prob (low→high)  [cyan]4[/] Vig (tight first)")
        sort_c = Prompt.ask("  Sort", default="1").strip()
        if sort_c == "2":
            cat_markets.sort(key=lambda x: x['yes_prob'])
        elif sort_c == "3":
            cat_markets.sort(key=lambda x: x['no_prob'])
        elif sort_c == "4":
            cat_markets.sort(key=lambda x: x['vig_pct'])
        else:
            cat_markets.sort(key=lambda x: x['volume'], reverse=True)
        console.print(
            f"  [green]✓[/] {len(cat_markets)} markets in "
            f"[bold]{chosen_cat}[/]"
        )
        return cat_markets
    def render_edge_panel(self, market: dict, edge: dict) -> None:
        from rich.console import Console
        from rich.panel   import Panel
        from rich.table   import Table
        from rich.rule    import Rule
        from rich         import box as _box
        console = Console()
        signal_colour = {"YES":"green","NO":"red","NO BET":"yellow"}.get(
            edge['best_side'], "white"
        )
        console.print(Panel(
            f"[bold white]{market['question']}[/]\n"
            f"[dim]Volume: ${market['volume']:,.0f}  |  "
            f"Ends: {market['end_date']}  |  "
            f"Vig: {market['vig_pct']:.2f}%[/]\n\n"
            f"[bold]Market Implied:[/]  "
            f"YES [green]{market['yes_prob']*100:.1f}%[/]   "
            f"NO [red]{market['no_prob']*100:.1f}%[/]\n\n"
            f"[bold]Your Estimate:[/]  "
            f"YES [bold white]{edge['true_prob_yes']*100:.1f}%[/]   "
            f"NO [bold white]{edge['true_prob_no']*100:.1f}%[/]",
            title=f"[bold {signal_colour}]▶ {edge['best_side']}[/]",
            border_style=signal_colour, expand=False
        ))
        tbl = Table(box=_box.SIMPLE_HEAVY, show_header=True,
                    header_style="bold cyan", expand=False)
        tbl.add_column("Metric",              width=32)
        tbl.add_column("BET YES",             width=18, justify="right")
        tbl.add_column("BET NO",              width=18, justify="right")
        def _evc(v):
            return (f"[green]+${v:.4f}[/]" if v > 0
                    else f"[red]-${abs(v):.4f}[/]")
        def _kc(v):
            return f"[green]${v:,.2f}[/]" if v > 0 else "[dim]$0.00[/]"
        tbl.add_row("Expected Value / $1",
                    _evc(edge['ev_yes']), _evc(edge['ev_no']))
        tbl.add_row("Your Edge vs Market",
                    f"[{'green' if edge['edge_yes_pct']>0 else 'red'}]{edge['edge_yes_pct']:+.2f}%[/]",
                    f"[{'green' if edge['edge_no_pct']>0 else 'red'}]{edge['edge_no_pct']:+.2f}%[/]")
        tbl.add_row("Max ROI (if correct)",
                    f"{edge['roi_yes']:.1f}%", f"{edge['roi_no']:.1f}%")
        tbl.add_row("Breakeven Probability",
                    f"{edge['breakeven_yes']:.1f}%", f"{edge['breakeven_no']:.1f}%")
        tbl.add_row("Full Kelly Fraction",
                    f"{edge['full_kelly_yes']*100:.2f}%",
                    f"{edge['full_kelly_no']*100:.2f}%")
        tbl.add_row(f"{edge['kelly_mode']} Bet (${self.bankroll:,.0f})",
                    _kc(edge['bet_yes_$']), _kc(edge['bet_no_$']))
        console.print(tbl)
        bs   = edge['best_side']
        side = "YES" if bs == "YES" else "NO"
        bet  = edge['bet_yes_$'] if bs == "YES" else edge['bet_no_$']
        ev   = edge['ev_yes']    if bs == "YES" else edge['ev_no']
        if bs == "NO BET":
            console.print(Panel(
                "[bold yellow]NO EDGE DETECTED.[/]\n\n"
                "Your probability estimate aligns too closely with market pricing.\n"
                "The expected value is negative on both sides.\n"
                "Wait for new information to move your estimate further from the market.",
                border_style="yellow", title="[bold]Verdict[/]", expand=False
            ))
        else:
            roi_str = edge[f'roi_{side.lower()}']
            console.print(Panel(
                f"[bold {signal_colour}]BET {side}[/]\n\n"
                f"EV = [bold]{ev:+.4f}[/] per $1 wagered  |  "
                f"Max ROI = {roi_str:.1f}%\n"
                f"{edge['kelly_mode']}: [bold]${bet:,.2f}[/] "
                f"({edge['kelly_frac']*100:.0f}% of Full Kelly × "
                f"{edge['full_kelly_yes' if bs=='YES' else 'full_kelly_no']*100:.2f}%)\n\n"
                f"[dim]Cap applied: no single bet exceeds 30% of bankroll.  "
                f"Vig of {edge['vig_pct']:.2f}% is included in EV calculation.[/]",
                border_style=signal_colour, title="[bold]Verdict[/]", expand=False
            ))
    def _ai_call(self, sys_p: str, user_p: str) -> tuple[str, float]:
        if not self._or_key:
            return "[AI UNAVAILABLE] Configure API key in Settings.", 0.0
        bag  = {}; done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization":f"Bearer {self._or_key}",
                             "Content-Type":"application/json",
                             "X-Title":"Module73-PredMarket"},
                    json={"model":self._or_model,
                          "messages":[{"role":"system","content":sys_p},
                                      {"role":"user","content":user_p}],
                          "temperature":0.4},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter()-t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter()-t0
            finally: done.set()
        threading.Thread(target=_w,daemon=True).start()
        spin="⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i=0; t0=time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i%len(spin)]} AI thinking… {time.perf_counter()-t0:.1f}s   ",
                  end="",flush=True)
            i+=1
        print()
        return bag.get("reply",""), bag.get("latency",0.0)
    def run_ai_market_analysis(self, market: dict) -> str:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.markdown import Markdown
        from rich.rule     import Rule
        console = Console()
        console.print(Rule("[bold green]AI Market Analysis[/]"))
        _SYS = (
            "You are a professional prediction market analyst and forecaster.\n"
            "You have deep knowledge of global politics, economics, sports, and technology.\n"
            "A user wants to bet on a Polymarket prediction market and needs your "
            "probability estimate to calculate their edge.\n\n"
            "Write a structured analysis:\n\n"
            "## Event Understanding\n"
            "What is this market about? What exactly needs to happen for YES to resolve?\n\n"
            "## Base Rate Analysis\n"
            "What is the historical base rate for similar events? "
            "Use concrete historical examples.\n\n"
            "## Current Evidence\n"
            "What factors currently push the probability UP? What factors push it DOWN?\n"
            "Weight each factor by its importance.\n\n"
            "## Fair Probability Estimate\n"
            "State your estimated probability for YES resolution: X%\n"
            "Provide a 90% confidence interval: [LOW%, HIGH%]\n"
            "Explain your reasoning in 2–3 sentences.\n\n"
            "## Edge Assessment\n"
            "Compare your estimate to the market's implied probability.\n"
            "If the gap is > 5 percentage points, call it EDGE DETECTED.\n"
            "If < 5pp, call it NO MEANINGFUL EDGE.\n\n"
            "## Key Risks\n"
            "What could invalidate your estimate? What are the known unknowns?\n\n"
            "## Bet Recommendation\n"
            "YES / NO / PASS — with one sentence rationale.\n\n"
            "Be direct. Give a specific number. Do not hedge excessively."
        )
        user_p = (
            f"Market Question: {market['question']}\n"
            f"Resolution Date: {market['end_date']}\n"
            f"Market Implied YES Probability: {market['yes_prob']*100:.1f}%\n"
            f"Market Implied NO  Probability: {market['no_prob']*100:.1f}%\n"
            f"Total Volume: ${market['volume']:,.0f}\n"
            f"Market Vig: {market['vig_pct']:.2f}%\n"
            f"Category: {market['category']}\n"
        )
        reply, lat = self._ai_call(_SYS, user_p)
        if reply and not reply.startswith("[AI"):
            console.print(Panel(
                Markdown(reply), border_style="green",
                title=f"[bold green]AI Market Analyst[/] [dim]({lat:.2f}s)[/]",
                expand=False
            ))
        else:
            console.print(f"  [dim]{reply}[/]")
        return reply
