    def _ai_chat(self, market: dict = None, seed_reply: str = "") -> None:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.prompt   import Prompt
        from rich.markdown import Markdown
        console = Console()
        ctx = ""
        if market:
            ctx = (
                f"Current market under analysis:\n"
                f"  Question: {market['question']}\n"
                f"  YES: {market['yes_prob']*100:.1f}%  NO: {market['no_prob']*100:.1f}%\n"
                f"  Volume: ${market['volume']:,.0f}  Ends: {market['end_date']}\n"
            )
        _SYS = (
            "You are an expert prediction market analyst, statistician, and "
            "quantitative bettor.\n"
            "Answer questions about prediction markets, probability estimation, "
            "Kelly criterion, expected value, Polymarket mechanics, and event research.\n"
            "Be precise with numbers. Give specific probability estimates when asked.\n"
            f"{ctx}"
        )
        history = [
            {"role":"system",    "content":_SYS},
            {"role":"user",      "content":ctx or "Ready to discuss markets."},
            {"role":"assistant", "content": seed_reply or
             "Ready to help you analyse prediction markets, estimate probabilities, "
             "or discuss bet sizing strategy."},
        ]
        turn  = 0; _WARN = 7_000
        console.print(Panel(
            "[bold cyan]💬 Prediction Market Chat[/]\n\n"
            "Ask about event research, probability estimation, Kelly sizing,\n"
            "Polymarket mechanics, or portfolio strategy.\n\n"
            "[bold]Commands:[/]  [cyan]clear[/]   [cyan]exit[/]",
            border_style="cyan", title="[bold white]Chat[/]", expand=False
        ))
        while True:
            est = sum(len(m["content"]) for m in history)//4
            tok = f"[yellow]~{est} ⚠[/]" if est>=_WARN else f"[dim]~{est} tokens[/]"
            q   = Prompt.ask(
                f"\n  [bold cyan]You[/] [dim](turn {turn+1} | {tok})[/]"
            ).strip()
            if not q: continue
            if q.lower()=="exit":  console.print("  [dim]Returning…[/]"); break
            if q.lower()=="clear":
                history=[{"role":"system","content":_SYS}]; turn=0
                console.print("  [green]✓ Cleared.[/]"); continue
            history.append({"role":"user","content":q})
            conv  = "\n".join(
                f"{m['role'].upper()}: {m['content']}" for m in history[1:]
            )
            reply, lat = self._ai_call(_SYS, conv)
            if reply:
                console.print(Panel(
                    Markdown(reply), border_style="green",
                    title=f"[bold green]Assistant[/] [dim]({lat:.2f}s)[/]",
                    expand=False
                ))
                history.append({"role":"assistant","content":reply})
                turn+=1
            else:
                history.pop()
    def analyze_market(self, idx: int) -> None:
        from rich.console import Console
        from rich.panel   import Panel
        from rich.prompt  import Prompt
        from rich.rule    import Rule
        from rich.table   import Table
        from rich         import box as _box
        console = Console()
        if not (0 <= idx < len(self.markets_data)):
            console.print("  [red]Invalid market index.[/]"); return
        market   = self.markets_data[idx]
        os.system('cls' if os.name == 'nt' else 'clear')
        console.print(Rule(f"[bold cyan]{market['question'][:70]}[/]"))
        console.print(Panel(
            f"[bold white]{market['question']}[/]\n"
            f"[dim]Vol: ${market['volume']:,.0f}  "
            f"Ends: {market['end_date']}  "
            f"Vig: {market['vig_pct']:.2f}%  "
            f"Cat: {market['category']}[/]\n\n"
            f"[bold]Market Implied:[/]  "
            f"YES [green]{market['yes_prob']*100:.1f}%[/]  "
            f"NO [red]{market['no_prob']*100:.1f}%[/]",
            border_style="blue", expand=False
        ))
        run_search = Prompt.ask(
            "\n  Run web search + sentiment analysis? [Y/N]", default="Y"
        ).upper()
        sentiment = {}
        sentiment_nudge = 0.0
        if run_search == "Y":
            sentiment = self._web_search_sentiment(
                market['question'], market['end_date']
            )
            if sentiment.get('headlines'):
                console.print(Rule("[bold cyan]Web Sentiment Analysis[/]"))
                sc    = sentiment.get('sentiment_score', 0.0)
                label = sentiment.get('sentiment_label', "")
                nudge = sentiment.get('yes_bias_pct', 0.0)
                sc_clr= "green" if sc>0.1 else ("red" if sc<-0.1 else "yellow")
                console.print(Panel(
                    f"[bold]Overall Sentiment:[/] [{sc_clr}]{label}[/{sc_clr}]  "
                    f"(score: [{sc_clr}]{sc:+.3f}[/{sc_clr}])\n"
                    f"[bold]YES Probability Nudge:[/] "
                    f"[{sc_clr}]{nudge:+.1f} percentage points[/{sc_clr}]\n"
                    f"[dim]This nudge is a soft signal from news sentiment — "
                    f"not a deterministic forecast.  "
                    f"Use as one input among many.[/]",
                    border_style=sc_clr, expand=False
                ))
                htbl = Table(
                    border_style="dim", box=_box.SIMPLE_HEAVY,
                    show_lines=False, expand=True
                )
                htbl.add_column("Score", width=7,  justify="right")
                htbl.add_column("Source",width=16, style="dim")
                htbl.add_column("Headline", ratio=1)
                for h in sorted(sentiment['headlines'],
                                key=lambda x: abs(x.get('score',0)),
                                reverse=True)[:8]:
                    hs  = h.get('score', 0)
                    hc  = "green" if hs>0.1 else ("red" if hs<-0.1 else "dim")
                    htbl.add_row(
                        f"[{hc}]{hs:+.2f}[/{hc}]",
                        h['source'][:15],
                        h['title'][:85],
                    )
                console.print(htbl)
                sentiment_nudge = sentiment.get('yes_bias_pct', 0.0)
        base_suggested = market['yes_prob'] * 100
        suggested      = round(base_suggested + sentiment_nudge, 1)
        suggested      = max(1.0, min(99.0, suggested))
        console.print(
            f"\n  [bold]Market implied YES:[/] {base_suggested:.1f}%  "
            f"[dim]|[/]  [bold]Sentiment-adjusted suggestion:[/] "
            f"[{'green' if sentiment_nudge>0 else 'red' if sentiment_nudge<0 else 'white'}]"
            f"{suggested:.1f}%[/]\n"
            f"  [dim]Enter your TRUE probability for YES (0–100).  "
            f"Press ENTER to use AI research first.[/]"
        )
        ai_reply = ""
        raw = Prompt.ask(
            f"  True prob % [dim](suggested: {suggested})[/]", default=""
        ).strip()
        if not raw:
            ai_reply = self._run_ai_with_sentiment(market, sentiment)
            raw = Prompt.ask(
                "\n  Enter your TRUE probability for YES % (informed by AI + sentiment)"
            ).strip()
        if not raw:
            raw = str(suggested)
        try:
            true_prob = float(raw)
            if not (0 <= true_prob <= 100):
                raise ValueError
        except ValueError:
            console.print("  [red]Invalid probability.[/]"); return
        edge = self.calculate_full_edge(market, true_prob)
        if abs(sentiment_nudge) > 2:
            sentiment_ev_contribution = abs(sentiment_nudge / 100) * 0.65         
            edge['sentiment_contribution_note'] = (
                f"Sentiment nudge of {sentiment_nudge:+.1f}pp contributes "
                f"~{sentiment_ev_contribution:.3f} to EV estimate"
            )
        self.render_edge_panel(market, edge)
        if edge.get('sentiment_contribution_note'):
            console.print(
                f"  [dim]ℹ  {edge['sentiment_contribution_note']}[/]"
            )
        if not ai_reply and self._or_key:
            go_ai = Prompt.ask(
                "\n  Run AI market research? [Y/N]", default="Y"
            ).upper()
            if go_ai == "Y":
                ai_reply = self._run_ai_with_sentiment(market, sentiment)
        bs = edge['best_side']
        if bs != "NO BET":
            add = Prompt.ask(
                f"\n  Add to portfolio tracker? [Y/N]", default="N"
            ).upper()
            if add == "Y":
                side = bs
                bet  = edge['bet_yes_$'] if side=="YES" else edge['bet_no_$']
                ev   = edge['ev_yes']    if side=="YES" else edge['ev_no']
                self.portfolio.append({
                    'question'       : market['question'],
                    'side'           : side,
                    'bet_$'          : bet,
                    'ev'             : ev,
                    'true_prob'      : true_prob/100,
                    'market_prob'    : (market['yes_prob']
                                       if side=="YES" else market['no_prob']),
                    'sentiment_score': sentiment.get('sentiment_score', 0.0),
                    'added'          : datetime.now().strftime("%d %b %H:%M"),
                })
                console.print(
                    f"  [green]✓ Added {side} (${bet:.2f})  |  "
                    f"Sentiment: {sentiment.get('sentiment_label','N/A')}[/]"
                )
        if self._or_key:
            if Prompt.ask(
                "\n  Chat with AI about this market? [Y/N]", default="N"
            ).upper() == "Y":
                self._ai_chat(market, seed_reply=ai_reply)
        Prompt.ask("\n  [dim]Press ENTER to return…[/]")
    def _run_ai_with_sentiment(self, market: dict,
                                sentiment: dict) -> str:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.markdown import Markdown
        from rich.rule     import Rule
        console = Console()
        console.print(Rule("[bold green]AI Market Analysis + Web Sentiment[/]"))
        _SYS = (
            "You are a professional prediction market analyst and forecaster.\n"
            "You have deep knowledge of global politics, economics, sports, and technology.\n"
            "You have been given BOTH the market data AND live web search results "
            "with sentiment scores for this event.\n\n"
            "Write a structured analysis:\n\n"
            "## Event Understanding\n"
            "What exactly needs to happen for YES to resolve?\n\n"
            "## Web Sentiment Read\n"
            "Interpret the sentiment scores from the headlines provided. "
            "Are the headlines confirming or contradicting the market's implied probability? "
            "Quote specific headlines that are most informative.\n\n"
            "## Base Rate Analysis\n"
            "Historical base rate for similar events with concrete examples.\n\n"
            "## Synthesis: Market + Sentiment + Base Rate\n"
            "Weight all three inputs and arrive at a final probability estimate.\n"
            "State: My fair probability for YES = X%  (90% CI: [LOW%–HIGH%])\n\n"
            "## Edge Assessment\n"
            "Compare your estimate to the market's implied probability.\n"
            "EDGE DETECTED if gap > 5pp. NO MEANINGFUL EDGE if < 5pp.\n\n"
            "## Sentiment-Specific Risks\n"
            "Could the current news sentiment be misleading? "
            "Is this a narrative-driven market or fundamentals-driven?\n\n"
            "## Bet Recommendation\n"
            "YES / NO / PASS — one sentence rationale.\n\n"
            "Be direct. Give a specific number. Cite actual headline text."
        )
        user_p = (
            f"Market Question: {market['question']}\n"
            f"Resolution Date: {market['end_date']}\n"
            f"Market Implied YES: {market['yes_prob']*100:.1f}%  "
            f"NO: {market['no_prob']*100:.1f}%\n"
            f"Total Volume: ${market['volume']:,.0f}\n"
            f"Category: {market['category']}\n"
            f"Vig: {market['vig_pct']:.2f}%\n\n"
        )
        if sentiment.get('search_digest'):
            user_p += f"LIVE WEB SEARCH + SENTIMENT ANALYSIS:\n"
            user_p += sentiment['search_digest']
        else:
            user_p += "Web search returned no results.\n"
        reply, lat = self._ai_call(_SYS, user_p)
        if reply and not reply.startswith("[AI"):
            console.print(Panel(
                Markdown(reply), border_style="green",
                title=f"[bold green]AI + Sentiment Analysis[/] [dim]({lat:.2f}s)[/]",
                expand=False
            ))
        else:
            console.print(f"  [dim]{reply}[/]")
        return reply
