class QuantSyntheticOptions:
    def __init__(self, ticker):
        self.ticker = ticker.upper()
        self.S0 = 0.0
        self.trend_bias = 0.0
        self.r = 0.07                              
        self.hv_10 = 0.0
        self.hv_30 = 0.0
        self.hv_252 = 0.0
        self.vol_regime = "NORMAL"
        self.expiry_date = None
        self.dte = 0
        self.T = 0.0
        self.expected_move_1sd = 0.0
        self.expected_move_2sd = 0.0
        self.rec = {}
    def _get_next_nse_expiry(self):
        import datetime
        import calendar
        today = datetime.datetime.now().date()
        year, month = today.year, today.month
        def get_last_thursday(y, m):
            last_day = calendar.monthrange(y, m)[1]
            last_date = datetime.date(y, m, last_day)
            offset = (last_date.weekday() - 3) % 7                
            return last_date - datetime.timedelta(days=offset)
        expiry = get_last_thursday(year, month)
        if today > expiry:
            month = 1 if month == 12 else month + 1
            year = year + 1 if month == 1 else year
            expiry = get_last_thursday(year, month)
        self.expiry_date = expiry
        self.dte = max((expiry - today).days, 1)                            
        self.T = self.dte / 365.0
    def _black_scholes_and_greeks(self, S, K, T, r, sigma, option_type="call"):
        from scipy.stats import norm
        d1 = (np.log(S / K) + (r + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
        d2 = d1 - sigma * np.sqrt(T)
        if option_type == "call":
            price = S * norm.cdf(d1) - K * np.exp(-r * T) * norm.cdf(d2)
            delta = norm.cdf(d1)
            prob_itm = norm.cdf(d2)
        else:
            price = K * np.exp(-r * T) * norm.cdf(-d2) - S * norm.cdf(-d1)
            delta = norm.cdf(d1) - 1
            prob_itm = norm.cdf(-d2)
        gamma = norm.pdf(d1) / (S * sigma * np.sqrt(T))
        vega = S * norm.pdf(d1) * np.sqrt(T) / 100                      
        if option_type == "call":
            theta = (-S * norm.pdf(d1) * sigma / (2 * np.sqrt(T)) - r * K * np.exp(-r * T) * norm.cdf(d2)) / 365
        else:
            theta = (-S * norm.pdf(d1) * sigma / (2 * np.sqrt(T)) + r * K * np.exp(-r * T) * norm.cdf(-d2)) / 365
        return {
            "price": price, "delta": delta, "gamma": gamma, 
            "theta": theta, "vega": vega, "prob_itm": prob_itm
        }
    def _fetch_and_analyze(self):
        try:
            from scipy.stats import norm
        except ImportError:
            print("  [!] Error: 'scipy' is required. Run 'pip install scipy'")
            return False
        print(f"  [1] Fetching Price Action & Options Calendar for {self.ticker}...")
        self._get_next_nse_expiry()
        stock = yf.Ticker(self.ticker)
        hist = stock.history(period="1y")
        if hist.empty: return False
        self.S0 = float(hist['Close'].iloc[-1])
        print(f"  [2] Calculating Volatility Term Structure & Market Greeks...")
        log_ret = np.log(hist['Close'] / hist['Close'].shift(1)).dropna()
        self.hv_252 = log_ret.std() * np.sqrt(252)
        self.hv_30 = log_ret.tail(30).std() * np.sqrt(252)
        self.hv_10 = log_ret.tail(10).std() * np.sqrt(252)
        if self.hv_10 > self.hv_252 * 1.3: self.vol_regime = "EXPANDING (HIGH)"
        elif self.hv_10 < self.hv_252 * 0.7: self.vol_regime = "COMPRESSING (LOW)"
        else: self.vol_regime = "NORMAL (MEAN REVERTING)"
        sigma = self.hv_30
        self.expected_move_1sd = self.S0 * sigma * np.sqrt(self.T)
        self.expected_move_2sd = self.expected_move_1sd * 2
        close = hist['Close']
        ema9, ema21 = close.ewm(span=9).mean().iloc[-1], close.ewm(span=21).mean().iloc[-1]
        sma50 = close.rolling(50).mean().iloc[-1]
        score = 0
        if self.S0 > ema9: score += 0.3
        else: score -= 0.3
        if ema9 > ema21: score += 0.4
        else: score -= 0.4
        if self.S0 > sma50: score += 0.3
        else: score -= 0.3
        self.trend_bias = score
        return True
    def _generate_strategy(self):
        if abs(self.trend_bias) < 0.2:
            self.rec = {'type': 'NEUTRAL', 'msg': 'Choppy/Flat trend. Options will bleed Theta. Avoid directional buying.'}
            return
        opt_type = 'CALL' if self.trend_bias > 0 else 'PUT'
        sigma = self.hv_30
        step = 10 if self.S0 > 1000 else (5 if self.S0 > 200 else 1)
        best_strike = self.S0
        best_greeks = None
        min_delta_diff = 1.0
        scan_range = np.arange(self.S0 * 0.8, self.S0 * 1.2, step)
        for K in scan_range:
            greeks = self._black_scholes_and_greeks(self.S0, K, self.T, self.r, sigma, opt_type.lower())
            delta_target = 0.40
            current_delta_abs = abs(greeks['delta'])
            if abs(current_delta_abs - delta_target) < min_delta_diff:
                if (opt_type == 'CALL' and K >= self.S0) or (opt_type == 'PUT' and K <= self.S0):
                    min_delta_diff = abs(current_delta_abs - delta_target)
                    best_strike = K
                    best_greeks = greeks
        strategy_name = f"Outright {opt_type} Buy"
        hedge_leg = None
        if "EXPANDING" in self.vol_regime:
            strategy_name = f"Bull Call Spread" if opt_type == 'CALL' else f"Bear Put Spread"
            hedge_strike = round((best_strike + self.expected_move_1sd) / step) * step if opt_type == 'CALL' else round((best_strike - self.expected_move_1sd) / step) * step
            hedge_greeks = self._black_scholes_and_greeks(self.S0, hedge_strike, self.T, self.r, sigma, opt_type.lower())
            hedge_leg = {"strike": hedge_strike, "price": hedge_greeks['price']}
        self.rec = {
            'type': opt_type,
            'strategy': strategy_name,
            'strike': best_strike,
            'greeks': best_greeks,
            'hedge': hedge_leg
        }
    def print_report(self):
        if not self._fetch_and_analyze(): return
        self._generate_strategy()
        G, R, Y, B, C, M, RES = '\033[92m', '\033[91m', '\033[93m', '\033[1m', '\033[96m', '\033[95m', '\033[0m'
        BLUE_BG = '\033[44m\033[97m'
        print(f"\n  {BLUE_BG} QUANTITATIVE OPTIONS & GREEKS ENGINE | {self.ticker} {' ' * 5} {RES}")
        print(f"  {B}LTP:{RES} ₹ {self.S0:,.2f}  |  {B}NSE Expiry:{RES} {self.expiry_date} ({self.dte} Days / {self.T:.3f}T)")
        print("  " + "═" * 70)
        print(f"  {C}{B}[1] VOLATILITY TERM STRUCTURE{RES}")
        print(f"  10-Day HV (Short)  : {self.hv_10 * 100:>6.2f}%  |  Regime: {Y}{self.vol_regime}{RES}")
        print(f"  30-Day HV (Medium) : {self.hv_30 * 100:>6.2f}%")
        print(f"  252-Day HV (Long)  : {self.hv_252 * 100:>6.2f}%")
        print(f"\n  {C}{B}[2] MATH-EXPECTED MOVES (BY EXPIRY){RES}")
        print(f"  ± 1 Std.Dev (68% Prob)  : {Y}± ₹ {self.expected_move_1sd:.2f}{RES}  [₹ {self.S0 - self.expected_move_1sd:,.0f} to ₹ {self.S0 + self.expected_move_1sd:,.0f}]")
        print(f"  ± 2 Std.Dev (95% Prob)  : {Y}± ₹ {self.expected_move_2sd:.2f}{RES}  [₹ {self.S0 - self.expected_move_2sd:,.0f} to ₹ {self.S0 + self.expected_move_2sd:,.0f}]")
        bias_str = f"{G}BULLISH{RES}" if self.trend_bias > 0 else f"{R}BEARISH{RES}"
        print(f"  Algorithmic Trend Bias  : {bias_str} (Confidence: {abs(self.trend_bias)*100:.0f}%)")
        print(f"\n  {C}{B}[3] QUANTITATIVE DEPLOYMENT MATRIX{RES}")
        if self.rec['type'] == 'NEUTRAL':
            print(f"  {Y}Signal:{RES} {self.rec['msg']}")
            print("  " + "─" * 70)
            return
        opt = self.rec
        grk = opt['greeks']
        color = G if opt['type'] == 'CALL' else R
        print(f"  {B}Strategy Form        :{RES} {M}{opt['strategy']}{RES}")
        print(f"  {B}Target Strike (Leg 1):{RES} {color}BUY {opt['strike']} {opt['type']}{RES}")
        print(f"  {B}Theoretical Premium  :{RES} {Y}₹ {grk['price']:.2f}{RES}")
        if opt['hedge']:
            print(f"  {B}Hedge Strike (Leg 2) :{RES} {color}SELL {opt['hedge']['strike']} {opt['type']}{RES}")
            print(f"  {B}Hedge Premium Credit :{RES} {Y}₹ {opt['hedge']['price']:.2f}{RES}")
            net_debit = grk['price'] - opt['hedge']['price']
            print(f"  {B}Net Strategy Cost    :{RES} {Y}₹ {net_debit:.2f}{RES} (Max Loss Capped)")
        print(f"\n  {C}{B}[4] THE OPTION GREEKS (RISK PARAMETERS){RES}")
        print(f"  {B}Delta (Direction)    :{RES} {grk['delta']:>6.3f}  (Moves ₹{abs(grk['delta']):.2f} for every ₹1 stock move)")
        print(f"  {B}Gamma (Acceleration) :{RES} {grk['gamma']:>6.4f}  (Rate of change in Delta)")
        print(f"  {B}Theta (Time Decay)   :{RES} {R}{grk['theta']:>6.2f}{RES}  (Loses ₹{abs(grk['theta']):.2f} per day held)")
        print(f"  {B}Vega  (Vol Risk)     :{RES} {Y}{grk['vega']:>6.2f}{RES}  (Gains ₹{abs(grk['vega']):.2f} per 1% rise in IV)")
        print(f"\n  {B}Probability of Expiring ITM :{RES} {M}{grk['prob_itm']*100:.1f}%{RES}")
        print(f"\n  {C}{B}[5] HEDGE FUND EXECUTION RULES{RES}")
        if opt['hedge']:
            print(f"  {G}Logic{RES}: Volatility is historically high. Outright options will suffer 'IV Crush'.")
            print(f"         Using a Vertical Spread neutralizes Vega and heavily reduces Theta decay.")
        else:
            print(f"  {G}Logic{RES}: Volatility is normal/low. Outright buying is safe. Gamma will reward explosive moves.")
            print(f"  {R}Stop Loss{RES}: Exit if Delta drops below 0.15, or Premium drops 50%. Do not hold to 0.")
        print("\n  " + "─" * 70)
        print(f"  \033[90mMatch Leg 1 (and Leg 2 if recommended) in your broker app.\n  If broker premium is >20% higher than Theoretical Premium, IV is inflated (Skip trade).\033[0m")
        print("  " + "─" * 70)
