def _m32_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": "nematron 3 super",
    }
    if not os.path.exists(_M32_CONFIG_FILE):
        return defaults
    try:
        with open(_M32_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**defaults, **data}
    except (json.JSONDecodeError, OSError):
        return defaults
def _m32_save_config(cfg: dict) -> bool:
    payload = {
        "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
        "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
        "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
    }
    try:
        with open(_M32_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  ⚠  Could not save config: {exc}")
        return False
def _m32_setup_key(cfg: dict) -> dict:
    import getpass
    print("\n  ── API Key Setup (Module 32) ────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M32_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m32_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _m32_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models ───────────────────────────")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 54)
    for i, m in enumerate(_M32_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M32_FREE_MODELS):
            selected          = _M32_FREE_MODELS[idx]
            cfg["model_id"]   = selected["id"]
            cfg["model_name"] = selected["name"]
            _m32_save_config(cfg)
            print(f"  [✓] Switched to {selected['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
def _build_options_context(engine: "QuantSyntheticOptions") -> dict:
    def _safe(v, dp=4):
        if v is None:
            return None
        try:
            return None if math.isnan(float(v)) else round(float(v), dp)
        except (TypeError, ValueError):
            return v
    rec = engine.rec
    greeks_block = None
    if rec.get("greeks"):
        g = rec["greeks"]
        greeks_block = {
            "delta":    _safe(g.get("delta")),
            "gamma":    _safe(g.get("gamma")),
            "theta":    _safe(g.get("theta")),
            "vega":     _safe(g.get("vega")),
            "prob_itm": _safe(g.get("prob_itm")),
            "premium":  _safe(g.get("price"), 2),
        }
    hedge_block = None
    if rec.get("hedge"):
        h = rec["hedge"]
        hedge_block = {
            "strike":         _safe(h.get("strike"), 1),
            "premium_credit": _safe(h.get("price"), 2),
            "net_debit": _safe(
                (rec["greeks"]["price"] - h["price"])
                if rec.get("greeks") else None, 2
            ),
        }
    return {
        "ticker":      engine.ticker,
        "spot_price":  _safe(engine.S0, 2),
        "expiry_date": str(engine.expiry_date),
        "dte":         engine.dte,
        "T":           _safe(engine.T, 4),
        "risk_free_rate": engine.r,
        "volatility": {
            "hv_10_annualised_pct":  _safe(engine.hv_10  * 100, 2),
            "hv_30_annualised_pct":  _safe(engine.hv_30  * 100, 2),
            "hv_252_annualised_pct": _safe(engine.hv_252 * 100, 2),
            "regime":                engine.vol_regime,
        },
        "expected_moves": {
            "one_sd_68pct": {
                "move_rs":   _safe(engine.expected_move_1sd, 2),
                "lower":     _safe(engine.S0 - engine.expected_move_1sd, 2),
                "upper":     _safe(engine.S0 + engine.expected_move_1sd, 2),
            },
            "two_sd_95pct": {
                "move_rs":   _safe(engine.expected_move_2sd, 2),
                "lower":     _safe(engine.S0 - engine.expected_move_2sd, 2),
                "upper":     _safe(engine.S0 + engine.expected_move_2sd, 2),
            },
        },
        "trend": {
            "bias_score":  _safe(engine.trend_bias, 3),
            "direction":   ("BULLISH" if engine.trend_bias > 0
                            else "BEARISH" if engine.trend_bias < 0
                            else "NEUTRAL"),
            "confidence_pct": _safe(abs(engine.trend_bias) * 100, 1),
        },
        "strategy": {
            "signal_type":    rec.get("type", "NEUTRAL"),
            "strategy_name":  rec.get("strategy", "N/A"),
            "leg1_strike":    _safe(rec.get("strike"), 1),
            "leg1_option":    rec.get("type", "N/A"),
            "greeks":         greeks_block,
            "hedge_leg":      hedge_block,
            "neutral_reason": rec.get("msg") if rec.get("type") == "NEUTRAL" else None,
        },
    }
def _build_m32_system_prompt(options_context: dict, model_name: str) -> str:
    ticker = options_context["ticker"]
    persona = textwrap.dedent(f"""\
        You are a senior Derivatives Quant at an institutional options desk.
        You have just run a complete Black-Scholes analysis for {ticker}.
        Your job is to help the trader understand the greeks, the strategy
        recommendation, and the risk/reward of the suggested trade.
        You are powered by {model_name}.
        Speak precisely — cite exact values, not vague generalities.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in the <terminal_data> below. Do not invent values.
        2. When citing a metric, include its value (e.g. "Theta is -2.14, costing ₹2.14/day").
        3. Explain greeks in plain English before giving the number — many users are learning.
        4. Risk-first: flag theta decay, IV crush risk, and stop-loss levels before upside.
        5. If vol_regime is EXPANDING, proactively warn about IV crush eating into premium.
        6. If trend bias is NEUTRAL, strongly caution against directional option buying.
        7. Keep responses under 400 words unless the user explicitly asks for more depth.
        8. If the user asks something not in the data, say so clearly.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Prefix every response: [ANALYSIS] | [RISK] | [ANSWER] | [GREEKS] | [INFO]
        - **Bold** all greek names and their values.
        - Use > blockquotes for critical risk warnings.
        - Use Markdown tables when comparing greeks or strikes side-by-side.
        - Express probabilities as percentages (e.g. "67.3% probability of expiring ITM").
    """)
    data_json  = json.dumps(options_context, indent=2)
    data_block = f"<terminal_data>\n{data_json}\n</terminal_data>"
    return "\n\n".join([persona, rules, fmt, data_block])
def _m32_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS  = 20
    turn_count = (len(history) - 1) // 2
    if turn_count > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 32 Options Engine CoPilot",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    model_id,
        "messages": history,
        "stream":   True,
    }
    BACKOFF_BASE  = 1.5
    MAX_RETRIES   = 3
    full_response = ""
    last_error    = None
    for attempt in range(MAX_RETRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers,
                json=payload,
                stream=True,
                timeout=(10, 60),
            )
            if resp.status_code == 401:
                console.print(
                    "\n  [bold red][!] API key rejected (401). "
                    "Use /setkey to update.[/bold red]"
                )
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            token_count = 0
            print(f"\n  \033[90m{model_name} is thinking ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        token_count   += len(token.split())
                        if token_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({token_count} words)\033[0m\n")
            if full_response.strip():
                console.print(
                    Panel(
                        Markdown(full_response),
                        title=f"[bold cyan]{model_name}[/bold cyan]",
                        border_style="cyan",
                        padding=(1, 2),
                        expand=True,
                    )
                )
            return full_response                              
        except requests.Timeout:
            console.print(
                "\n  [bold red][!] Request timed out. "
                "Try a shorter question or /models to switch.[/bold red]"
            )
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < MAX_RETRIES - 1:
                wait = BACKOFF_BASE ** (attempt + 1)
                console.print(
                    f"  [yellow][~] Attempt {attempt + 1} failed ({exc}). "
                    f"Retrying in {wait:.1f}s…[/yellow]"
                )
                time.sleep(wait)
            else:
                console.print(
                    f"  [bold red][!] All {MAX_RETRIES} attempts failed: "
                    f"{last_error}[/bold red]"
                )
    return ""
def _print_m32_chat_help() -> None:
    print("\n  ── Module 32 Options Co-Pilot Commands ─────────────")
    cmds = [
        ("/setkey",       "Update your OpenRouter API key"),
        ("/models",       "Browse & switch free AI models"),
        ("/model <id>",   "Switch to any model by full OpenRouter ID"),
        ("/fetchmodels",  "Pull live free model list from OpenRouter API"),
        ("/clear",        "Clear conversation (keep options data)"),
        ("/export",       "Save session to a timestamped JSON file"),
        ("/status",       "Show model, key status, history length"),
        ("/help",         "Show this command list"),
        ("0 / exit",      "Return to the main terminal"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m32_chat(engine: "QuantSyntheticOptions") -> None:
    cfg = _m32_load_config()
    if not cfg["api_key"]:
        print("\n  \033[93m[!] No API key configured for Module 32 AI.\033[0m")
        cfg = _m32_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Run module again to configure.")
            return
    opt_context = _build_options_context(engine)
    history = [
        {
            "role":    "system",
            "content": _build_m32_system_prompt(opt_context, cfg["model_name"]),
        }
    ]
    print("\n" + "─" * 68)
    print(f"  \033[95m🧠 MODULE 32 OPTIONS CO-PILOT\033[0m  |  "
          f"\033[96m{cfg['model_name']}\033[0m  |  "
          f"\033[93m{engine.ticker}\033[0m")
    print("  Ask about greeks, strategy, risk. Type /help for commands.")
    print("─" * 68)
    first_prompt = (
        f"I've just run the quantitative options engine for {engine.ticker}. "
        f"Give me a complete analysis covering: "
        f"(1) what the strategy recommendation means and whether the current "
        f"volatility regime supports or undermines it, "
        f"(2) explain each greek in the context of this specific trade — "
        f"what does the theta cost mean in rupees per day, what does "
        f"the probability of expiring ITM tell me, "
        f"(3) the single biggest risk in this position right now, and "
        f"(4) what market conditions would make me exit this trade early."
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m32_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        print("  \033[91m[!] Auto-analysis failed. "
              "You can still ask questions below.\033[0m\n")
    while True:
        try:
            from rich.console import Console
            _con      = Console()
            user_input = _con.input(
                "\n  [bold cyan]You ›[/bold cyan] "
            ).strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Co-Pilot session ended]")
            break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m32_chat_help()
            continue
        elif cmd == "/setkey":
            cfg = _m32_setup_key(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m32_system_prompt(opt_context, cfg["model_name"]),
            }
            continue
        elif cmd == "/models":
            cfg = _m32_pick_model(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m32_system_prompt(opt_context, cfg["model_name"]),
            }
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}")
                print("  Usage:   /model <openrouter-model-id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = (
                    arg.split("/")[-1]
                       .replace(":free", " (free)")
                       .replace("-", " ")
                       .title()
                )
                _m32_save_config(cfg)
                history[0] = {
                    "role":    "system",
                    "content": _build_m32_system_prompt(opt_context, cfg["model_name"]),
                }
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get(
                    "http://127.0.0.1:9999/disabled", timeout=10
                )
                resp.raise_for_status()
                free = [
                    m for m in resp.json().get("data", [])
                    if m.get("id", "").endswith(":free")
                ]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    ctx = (m.get("context_length") or 0) // 1000
                    print(f"  {m['id']:<55} {ctx:>5}K")
                print(
                    f"\n  {len(free)} free models found. "
                    f"Activate with: /model <id>\n"
                )
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Options data retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns    = (len(history) - 1) // 2
            key_hint = (
                f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}"
                if len(cfg["api_key"]) > 12 else "not set"
            )
            print(f"\n  Model    : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key  : {key_hint}")
            print(f"  Ticker   : {engine.ticker}  |  Expiry: {engine.expiry_date}  ({engine.dte} DTE)")
            print(f"  History  : {turns} turns (max 20 before auto-prune)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help.")
            continue
        history.append({"role": "user", "content": user_input})
        ai_response = _m32_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_response:
            history.append({"role": "assistant", "content": ai_response})
        else:
            history.pop()                                        
    print("  [Co-Pilot closed — returning to terminal]\n")
def run_options_engine(ticker):
    header(f"MODULE 32 — QUANT OPTIONS ENGINE (GREEKS)")
    engine = QuantSyntheticOptions(ticker)
    engine.print_report()
    if engine.S0 == 0.0:
        press_enter()
        return
    print("\n  ─────────────────────────────────────────────────────")
    try:
        launch = input(
            "  Open AI Co-Pilot to analyse these options results? [Y/n]: "
        ).strip().lower()
    except (EOFError, KeyboardInterrupt):
        launch = "n"
    if launch not in {"n", "no"}:
        run_m32_chat(engine)
    else:
        press_enter()
class ExternalChartOpener:
    def __init__(self, ticker):
        self.ticker = ticker.upper()
        self.clean_sym = self.ticker.replace('.NS', '').replace('.BO', '')
        if self.ticker.endswith('.NS'):
            self.tv_symbol = f"NSE:{self.clean_sym}"
        elif self.ticker.endswith('.BO'):
            self.tv_symbol = f"BSE:{self.clean_sym}"
        else:
            self.tv_symbol = self.ticker
        print(f"  Fetching pre-flight status for {self.ticker}...")
        self.stock = yf.Ticker(self.ticker)
        try:
            self.options_expiries = self.stock.options
            self.has_options = len(self.options_expiries) > 0
        except Exception:
            self.options_expiries = []
            self.has_options = False
        try:
            hist = self.stock.history(period="1d")
            self.ltp = float(hist['Close'].iloc[-1]) if not hist.empty else 0.0
        except Exception:
            self.ltp = 0.0
    def launch_menu(self):
        import webbrowser
        import urllib.parse
        BOLD = '\033[1m'
        CYAN = '\033[96m'
        GREEN = '\033[92m'
        YELLOW = '\033[93m'
        RED = '\033[91m'
        MAGENTA = '\033[95m'
        RESET = '\033[0m'
        BLUE_BG = '\033[44m\033[97m'
        encoded_tv_sym = urllib.parse.quote(self.tv_symbol)
        urls = {
            "1": f"https://www.tradingview.com/chart/?symbol={encoded_tv_sym}",
            "2": f"https://www.tradingview.com/symbols/{self.tv_symbol.replace(':', '-')}/technicals/",
            "3": f"https://finance.yahoo.com/quote/{self.ticker}/chart/",
            "4": f"https://finance.yahoo.com/quote/{self.ticker}/options/",
            "5": f"https://www.screener.in/company/{self.clean_sym}/consolidated/",
            "6": f"https://www.nseindia.com/get-quotes/equity?symbol={urllib.parse.quote(self.clean_sym)}"
        }
        while True:
            print(f"\n  {BLUE_BG} EXTERNAL PORTAL LAUNCHER | {self.ticker} {' ' * 15} {RESET}")
            print(f"  {BOLD}LTP:{RESET} ₹ {self.ltp:,.2f}")
            if self.has_options:
                print(f"  {BOLD}Derivatives:{RESET} {GREEN}ACTIVE{RESET} ({len(self.options_expiries)} Expiries Detected on Yahoo)")
                print(f"  {BOLD}Next Expiry:{RESET} {YELLOW}{self.options_expiries[0]}{RESET}")
            else:
                print(f"  {BOLD}Derivatives:{RESET} {RED}UNAVAILABLE{RESET} (No Options Chain Data on Yahoo)")
            print("  " + "═" * 60)
            print(f"  {CYAN}--- TRADINGVIEW (CHARTING & ALGOS) ---{RESET}")
            print(f"  {BOLD}1.{RESET} Open TradingView {YELLOW}Advanced Chart{RESET}")
            print(f"  {BOLD}2.{RESET} Open TradingView {MAGENTA}Algorithmic Technicals Gauge{RESET}")
            print(f"\n  {CYAN}--- YAHOO FINANCE (GLOBAL DATA) ---{RESET}")
            print(f"  {BOLD}3.{RESET} Open Yahoo Finance {YELLOW}Interactive Chart{RESET}")
            print(f"  {BOLD}4.{RESET} Open Yahoo Finance {MAGENTA}Options Chain Matrix{RESET}")
            print(f"\n  {CYAN}--- INDIAN MARKET SPECIALS ---{RESET}")
            print(f"  {BOLD}5.{RESET} Open {GREEN}Screener.in{RESET} (Deep Fundamentals & Ratios)")
            print(f"  {BOLD}6.{RESET} Open {GREEN}NSE India{RESET} (Official Exchange Portal)")
            print(f"\n  {BOLD}7.{RESET} Launch {GREEN}ALL TABS{RESET} (Ultimate Research Mode)")
            print(f"  {BOLD}0.{RESET} Cancel & Return to Main Menu")
            print("  " + "═" * 60)
            choice = input(f"\n  Select portal to launch [0-7]: ").strip()
            try:
                if choice in urls.keys():
                    portal_names = {"1":"TV Chart", "2":"TV Technicals", "3":"YF Chart", "4":"YF Options", "5":"Screener.in", "6":"NSE India"}
                    print(f"  {GREEN}Launching {portal_names[choice]} for {self.ticker}...{RESET}")
                    time.sleep(0.5)
                    webbrowser.open(urls[choice])
                    break
                elif choice == '7':
                    print(f"  {GREEN}Launching ultimate research workspace (6 Tabs)...{RESET}")
                    time.sleep(0.5)
                    for url in urls.values():
                        webbrowser.open(url)
                    break
                elif choice == '0':
                    print("  Launch cancelled.")
                    break
                else:
                    print(f"  {YELLOW}[!] Invalid choice. Please select from the menu.{RESET}")
            except Exception as e:
                print(f"  \033[91m[!] Error launching browser: {e}\033[0m")
                break
