def _m49_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title(),
    }
    if not os.path.exists(_M49_CONFIG_FILE):
        return defaults
    try:
        with open(_M49_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**defaults, **data}
    except (json.JSONDecodeError, OSError):
        return defaults
def _m49_save_config(cfg: dict) -> bool:
    payload = {
        "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
        "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
        "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
    }
    try:
        with open(_M49_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  ⚠  Could not save config: {exc}")
        return False
def _m49_setup_key(cfg: dict) -> dict:
    import getpass
    print("\n  ── API Key Setup (Module 49) ────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M49_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m49_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _m49_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models ───────────────────────────")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 54)
    for i, m in enumerate(_M49_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M49_FREE_MODELS):
            sel               = _M49_FREE_MODELS[idx]
            cfg["model_id"]   = sel["id"]
            cfg["model_name"] = sel["name"]
            _m49_save_config(cfg)
            print(f"  [✓] Switched to {sel['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
def _build_scripture_context(
    reference:  str,
    title:      str | None,
    verses:     list,
    api_ref:    str,
) -> dict:
    NT_KEYWORDS = {
        "matthew", "mark", "luke", "john", "acts", "romans",
        "corinthians", "galatians", "ephesians", "philippians",
        "colossians", "thessalonians", "timothy", "titus",
        "philemon", "hebrews", "james", "peter", "jude",
        "revelation", "1 john", "2 john", "3 john",
    }
    ref_lower  = reference.lower()
    testament  = "New Testament" if any(k in ref_lower for k in NT_KEYWORDS) else "Old Testament"
    ansi_re   = re.compile(r"\033\[[0-9;]*m")
    verse_list = []
    full_parts = []
    for v in verses:
        num  = str(v.get("verse", ""))
        text = ansi_re.sub("", v.get("text", "")).replace("\n", " ").strip()
        verse_list.append({"verse": num, "text": text})
        full_parts.append(f"[{num}] {text}")
    full_text = " ".join(full_parts)
    return {
        "reference":     reference,
        "api_reference": api_ref,
        "title":         title or "Custom passage",
        "testament":     testament,
        "verse_count":   len(verse_list),
        "full_text":     full_text,
        "verses":        verse_list,
    }
def _build_m49_system_prompt(ctx: dict, model_name: str) -> str:
    ref   = ctx["reference"]
    title = ctx["title"]
    test  = ctx["testament"]
    persona = textwrap.dedent(f"""\
        You are a respectful, academically grounded Biblical Scholar and
        Theologian. You have just read the following passage with the user:
        "{title}" — {ref} ({test}).
        You are powered by {model_name}.
        Engage at whatever level the user needs — from simple explanation
        to deep theological analysis. Respect all Christian traditions equally.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every textual claim in the <scripture> below.
           Do not cite verses not present in the passage.
        2. When referencing specific content, cite the verse number
           (e.g. "In verse 7, the text says…").
        3. Lead with the central theme or main message of the passage.
        4. Historical and literary context before theological application.
        5. When multiple interpretive traditions exist (Catholic, Protestant,
           Orthodox, etc.), present them fairly rather than asserting one.
        6. If the user asks about something outside this passage, you may
           draw on broader biblical knowledge but make clear you are doing so.
        7. Keep responses under 400 words unless the user asks for more depth.
        8. Never be preachy or assume the user's faith background.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Prefix every response: [THEME] | [CONTEXT] | [VERSE] | [ANSWER] | [INFO]
        - **Bold** key theological terms and names on first use.
        - Use > blockquotes when quoting directly from the passage.
        - Use Markdown tables when comparing parallel passages or themes.
        - Keep verse citations in the format: verse N — "quoted text"
    """)
    verses_text = "\n".join(
        f"  [{v['verse']}] {v['text']}" for v in ctx["verses"]
    )
    scripture_block = (
        f'<scripture reference="{ctx["api_reference"]}" testament="{ctx["testament"]}">\n'
        f"{verses_text}\n"
        f"</scripture>"
    )
    return "\n\n".join([persona, rules, fmt, scripture_block])
def _m49_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS  = 20
    turn_count = (len(history) - 1) // 2
    if turn_count > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 49 Bible Study CoPilot",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    model_id,
        "messages": history,
        "stream":   True,
    }
    BACKOFF_BASE  = 1.5
    MAX_RETRIES   = 3
    full_response = ""
    last_error    = None
    for attempt in range(MAX_RETRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers,
                json=payload,
                stream=True,
                timeout=(10, 60),
            )
            if resp.status_code == 401:
                console.print(
                    "\n  [bold red][!] API key rejected (401). "
                    "Use /setkey to update.[/bold red]"
                )
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            token_count = 0
            print(f"\n  \033[90m{model_name} is reflecting ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        token_count   += len(token.split())
                        if token_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({token_count} words)\033[0m\n")
            if full_response.strip():
                console.print(
                    Panel(
                        Markdown(full_response),
                        title=f"[bold cyan]{model_name}[/bold cyan]",
                        border_style="cyan",
                        padding=(1, 2),
                        expand=True,
                    )
                )
            return full_response
        except requests.Timeout:
            console.print(
                "\n  [bold red][!] Request timed out. "
                "Try a shorter question or /models to switch.[/bold red]"
            )
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < MAX_RETRIES - 1:
                wait = BACKOFF_BASE ** (attempt + 1)
                console.print(
                    f"  [yellow][~] Attempt {attempt + 1} failed ({exc}). "
                    f"Retrying in {wait:.1f}s…[/yellow]"
                )
                time.sleep(wait)
            else:
                console.print(
                    f"  [bold red][!] All {MAX_RETRIES} attempts failed: "
                    f"{last_error}[/bold red]"
                )
    return ""
def _print_m49_chat_help() -> None:
    print("\n  ── Module 49 Bible Study Co-Pilot Commands ──────────")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by full OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter API"),
        ("/clear",       "Clear conversation (keep scripture passage)"),
        ("/export",      "Save session to a timestamped JSON file"),
        ("/status",      "Show model, key status, history length"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to the Bible Terminal menu"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m49_chat(
    reference: str,
    title:     str | None,
    verses:    list,
    api_ref:   str,
) -> None:
    cfg = _m49_load_config()
    if not cfg["api_key"]:
        print("\n  \033[93m[!] No API key configured for the Bible Study Co-Pilot.\033[0m")
        cfg = _m49_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI study. Run module again to configure.")
            return
    ctx = _build_scripture_context(reference, title, verses, api_ref)
    history = [
        {
            "role":    "system",
            "content": _build_m49_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    display_ref = title if title else api_ref
    print("\n" + "─" * 68)
    print(f"  \033[95m✦ BIBLE STUDY CO-PILOT\033[0m  |  "
          f"\033[96m{cfg['model_name']}\033[0m")
    print(f"  \033[93m{display_ref}\033[0m  |  "
          f"\033[90m{ctx['verse_count']} verses  ·  {ctx['testament']}\033[0m")
    print("  Ask about themes, context, theology, or any verse.")
    print("  Type /help for commands.")
    print("─" * 68)
    if ctx["verse_count"] == 1:
        first_prompt = (
            f"I just read {api_ref}. This is a single verse. "
            f"Give me a deep analysis: "
            f"(1) what this verse means in its immediate textual context — "
            f"what comes before and after it in the chapter, "
            f"(2) the key theological concepts embedded in this verse and "
            f"what they meant to the original audience, "
            f"(3) how different Christian traditions have interpreted this "
            f"verse differently, and "
            f"(4) why this particular verse is considered significant."
        )
    else:
        first_prompt = (
            f"I just read '{display_ref}' ({api_ref}, {ctx['verse_count']} verses, "
            f"{ctx['testament']}). Give me a scholarly overview: "
            f"(1) the central theme of this passage in one sentence, "
            f"(2) the historical and literary context — who wrote this, "
            f"when, and who was the original audience, "
            f"(3) identify the single most theologically significant verse "
            f"in the passage and explain why, "
            f"(4) any symbols, numbers, or names with special meaning that "
            f"a modern reader would likely miss."
        )
    history.append({"role": "user", "content": first_prompt})
    response = _m49_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        print("  \033[91m[!] Auto-analysis failed. "
              "You can still ask questions below.\033[0m\n")
    while True:
        try:
            from rich.console import Console
            _con       = Console()
            user_input = _con.input(
                "\n  [bold cyan]You ›[/bold cyan] "
            ).strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Study session ended]")
            break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m49_chat_help()
            continue
        elif cmd == "/setkey":
            cfg = _m49_setup_key(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m49_system_prompt(ctx, cfg["model_name"]),
            }
            continue
        elif cmd == "/models":
            cfg = _m49_pick_model(cfg)
            history[0] = {
                "role":    "system",
                "content": _build_m49_system_prompt(ctx, cfg["model_name"]),
            }
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}")
                print("  Usage:   /model <openrouter-model-id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = (
                    arg.split("/")[-1]
                       .replace(":free", " (free)")
                       .replace("-", " ")
                       .title()
                )
                _m49_save_config(cfg)
                history[0] = {
                    "role":    "system",
                    "content": _build_m49_system_prompt(ctx, cfg["model_name"]),
                }
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get(
                    "http://127.0.0.1:9999/disabled", timeout=10
                )
                resp.raise_for_status()
                free = [
                    m for m in resp.json().get("data", [])
                    if m.get("id", "").endswith(":free")
                ]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    ctx_k = (m.get("context_length") or 0) // 1000
                    print(f"  {m['id']:<55} {ctx_k:>5}K")
                print(
                    f"\n  {len(free)} free models found. "
                    f"Activate with: /model <id>\n"
                )
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Scripture passage retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns    = (len(history) - 1) // 2
            key_hint = (
                f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}"
                if len(cfg["api_key"]) > 12 else "not set"
            )
            print(f"\n  Model      : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key    : {key_hint}")
            print(f"  Passage    : {api_ref}  ({ctx['verse_count']} verses)")
            print(f"  Testament  : {ctx['testament']}")
            print(f"  History    : {turns} turns (max 20 before auto-prune)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help.")
            continue
        history.append({"role": "user", "content": user_input})
        ai_response = _m49_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_response:
            history.append({"role": "assistant", "content": ai_response})
        else:
            history.pop()
    print("  [Study session closed — returning to Bible Terminal]\n")
