import os, json, time, threading, textwrap, re, hashlib, shutil
from datetime   import datetime, date
DEFAULT_LIBRARY = Path(r"D:\CLI apps\EPUB")
PROGRESS_FILE   = Path(".epub_progress.json")
BOOKMARKS_FILE  = Path(".epub_bookmarks.json")
STATS_FILE      = Path(".epub_stats.json")
READING_SPEED   = 200                                     
MIN_CHAPTER_LEN = 150                                                   
class EpubTerminalReader:
    def __init__(self):
        self.library_path  = DEFAULT_LIBRARY
        self.books         : list[dict] = []
        self.progress      : dict = {}
        self.bookmarks_db  : dict = {}
        self.stats         : dict = {}
        self._or_key       : str  = ""
        self._or_model     : str  = _GLOBAL_OR_MODEL
        self._session_words: int  = 0
        self._session_start: float = time.time()
        self._load_all()
    def _load_all(self):
        self._load_or_config()
        for path, attr in [
            (PROGRESS_FILE,  'progress'),
            (BOOKMARKS_FILE, 'bookmarks_db'),
            (STATS_FILE,     'stats'),
        ]:
            if path.exists():
                try:
                    setattr(self, attr, json.loads(path.read_text(encoding="utf-8")))
                except: pass
    def _save_progress(self):
        try:
            PROGRESS_FILE.write_text(
                json.dumps(self.progress, indent=2), encoding="utf-8"
            )
        except: pass
    def _save_bookmarks(self):
        try:
            BOOKMARKS_FILE.write_text(
                json.dumps(self.bookmarks_db, indent=2), encoding="utf-8"
            )
        except: pass
    def _save_stats(self):
        today = str(date.today())
        if today not in self.stats:
            self.stats[today] = {"words":0,"sessions":0}
        self.stats[today]["words"]    += self._session_words
        self.stats[today]["sessions"] += 1
        try:
            STATS_FILE.write_text(
                json.dumps(self.stats, indent=2), encoding="utf-8"
            )
        except: pass
    def _load_or_config(self):
        self._or_key   = _GLOBAL_OR_KEY
        self._or_model = _GLOBAL_OR_MODEL
    def _save_or_config(self):
        try:
            pass                                            
        except: pass
    @staticmethod
    def _book_hash(filepath: str) -> str:
        return hashlib.sha256(filepath.encode()).hexdigest()[:16]
    def scan_library(self, sort_by: str = "title") -> None:
        warnings.filterwarnings("ignore")
        from rich.console import Console
        console = Console()
        self.books = []
        if not self.library_path.exists():
            try: self.library_path.mkdir(parents=True, exist_ok=True)
            except: pass
            return
        epub_files = list(self.library_path.rglob("*.epub"))
        if not epub_files:
            return
        console.print(
            f"  [dim]Scanning {len(epub_files)} EPUB files…[/]",
            end="\r"
        )
        try:
            from ebooklib import epub
        except ImportError:
            console.print("  [red]ebooklib not installed. Run: pip install EbookLib[/]")
            return
        for fp in epub_files:
            try:
                book = epub.read_epub(str(fp), options={"ignore_ncx":True})
                title  = (book.get_metadata('DC','title') or [[fp.stem]])[0][0]
                author = (book.get_metadata('DC','creator') or [["Unknown"]])[0][0]
                desc_m = book.get_metadata('DC','description') or [[""]];
                desc   = re.sub(r'<[^>]+>','',desc_m[0][0])[:300] if desc_m[0][0] else ""
                lang_m = book.get_metadata('DC','language') or [["en"]]
                lang   = lang_m[0][0] if lang_m else "en"
                bh     = self._book_hash(str(fp))
                prog   = self.progress.get(bh, {})
                self.books.append({
                    'title'       : title,
                    'author'      : author,
                    'description' : desc,
                    'language'    : lang,
                    'filepath'    : str(fp),
                    'filename'    : fp.name,
                    'size_kb'     : fp.stat().st_size // 1024,
                    'hash'        : bh,
                    'book_obj'    : book,
                    'last_read'   : prog.get('last_read',''),
                    'read_pct'    : prog.get('pct', 0),
                    'chapter'     : prog.get('chapter', 0),
                    'page'        : prog.get('page', 0),
                })
            except Exception as e:
                self.books.append({
                    'title'   : fp.stem,
                    'author'  : 'Unknown',
                    'filepath': str(fp),
                    'filename': fp.name,
                    'size_kb' : fp.stat().st_size // 1024,
                    'hash'    : self._book_hash(str(fp)),
                    'book_obj': None,
                    'last_read':'',
                    'read_pct': 0,
                    'chapter' : 0,
                    'page'    : 0,
                    'description':'',
                    'language':'en',
                    'error'   : str(e),
                })
        if sort_by == "title":
            self.books.sort(key=lambda b: b['title'].lower())
        elif sort_by == "author":
            self.books.sort(key=lambda b: b['author'].lower())
        elif sort_by == "recent":
            self.books.sort(key=lambda b: b['last_read'], reverse=True)
        elif sort_by == "size":
            self.books.sort(key=lambda b: b['size_kb'], reverse=True)
        elif sort_by == "progress":
            self.books.sort(key=lambda b: b['read_pct'], reverse=True)
        console.print(
            f"  [green]✓[/] {len(self.books)} books found in "
            f"[dim]{self.library_path}[/]" + " "*20
        )
    def search_library(self, query: str) -> list[dict]:
        q = query.lower()
        return [
            b for b in self.books
            if q in b['title'].lower()
            or q in b['author'].lower()
            or q in b.get('description','').lower()
        ]
    def _parse_chapters(self, book) -> list[dict]:
        import ebooklib
        from ebooklib import epub
        from bs4      import BeautifulSoup
        chapters = []
        spine_ids = [item[0] for item in book.spine]
        ch_num    = 1
        for item_id in spine_ids:
            item = book.get_item_with_id(item_id)
            if item is None: continue
            if item.get_type() != ebooklib.ITEM_DOCUMENT: continue
            content = item.get_content()
            try:
                soup = BeautifulSoup(content, 'html.parser')
            except Exception:
                continue
            for tag in soup(["script","style","nav","aside"]):
                tag.decompose()
            heading   = soup.find(['h1','h2','h3'])
            ch_title  = heading.get_text(strip=True) if heading else f"Chapter {ch_num}"
            paragraphs = []
            for elem in soup.find_all(['p','li','blockquote','pre']):
                t = elem.get_text(separator=' ', strip=True)
                if t and len(t) > 20:
                    paragraphs.append(t)
            clean_text = "\n\n".join(paragraphs)
            if len(clean_text) < MIN_CHAPTER_LEN:
                continue
            word_count = len(clean_text.split())
            chapters.append({
                'title'   : ch_title,
                'text'    : clean_text,
                'words'   : word_count,
                'raw_html': str(soup)[:5000],                       
            })
            ch_num += 1
        return chapters
    def _paginate(self, text: str,
                   lpp: int,
                   width: int) -> list[list[str]]:
        pages   : list[list[str]] = []
        current : list[str]       = []
        def _flush():
            if current:
                pages.append(list(current))
                current.clear()
        for para in text.split('\n\n'):
            para = para.strip()
            if not para:
                if current: current.append("")
                continue
            lines = textwrap.wrap(para, width=width) or [""]
            if len(current) + len(lines) + 1 > lpp and len(lines) <= lpp * 0.4:
                _flush()
            for line in lines:
                current.append(line)
                if len(current) >= lpp:
                    _flush()
            if current and current[-1] != "":
                current.append("")
        if current: pages.append(current)
        return pages or [["(No readable content.)"]]
    def _search_in_chapters(self, chapters: list[dict],
                              query: str) -> list[tuple[int,int,str]]:
        q      = query.lower()
        hits   = []
        for ci, ch in enumerate(chapters):
            text = ch['text']
            tl   = text.lower()
            pos  = tl.find(q)
            while pos != -1:
                start   = max(0, pos-60)
                end     = min(len(text), pos+len(q)+60)
                snippet = text[start:end].replace('\n',' ')
                hits.append((ci, pos, snippet))
                pos = tl.find(q, pos+1)
        return hits[:20]                      
    @staticmethod
    def _prog_bar(pct: float, width: int = 20) -> str:
        filled = int(pct * width / 100)
        return f"[{'█'*filled}{'░'*(width-filled)}] {pct:.0f}%"
    def _ai_call(self, sys_p: str, user_p: str) -> tuple[str,float]:
        if not self._or_key:
            return "[AI UNAVAILABLE] Configure API key in Settings.", 0.0
        bag  = {}
        done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization":f"Bearer {self._or_key}",
                             "Content-Type":"application/json",
                             "X-Title":"Module50-EpubReader"},
                    json={"model":self._or_model,
                          "messages":[{"role":"system","content":sys_p},
                                      {"role":"user","content":user_p}],
                          "temperature":0.4},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter()-t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter()-t0
            finally: done.set()
        threading.Thread(target=_w,daemon=True).start()
        spin="⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i=0; t0=time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i%len(spin)]} AI thinking… {time.perf_counter()-t0:.1f}s   ",
                  end="",flush=True)
            i+=1
        print()
        return bag.get("reply",""), bag.get("latency",0.0)
