    def _ai_chat(self, book_dict: dict,
                  chapters: list[dict],
                  current_ch: int,
                  seed_reply: str = "") -> None:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.prompt   import Prompt
        from rich.markdown import Markdown
        console = Console()
        title   = book_dict['title']
        _SYS    = (
            f"You are an expert on '{title}' by {book_dict['author']}.\n"
            "The user is currently reading this book and has questions.\n"
            "Answer with depth and nuance. Reference specific content.\n"
            "Commands the user can type: 'coach' (reflection questions), "
            "'finance' (investment angle), 'summary' (chapter summary), 'exit'."
        )
        context  = f"Book: {title}\nAuthor: {book_dict['author']}\n\n"
        context += f"Current Chapter: {chapters[current_ch]['title']}\n"
        context += ' '.join(chapters[current_ch]['text'].split()[:1000])
        context += "\n\nBook opening:\n"
        context += ' '.join(chapters[0]['text'].split()[:500])
        history = [
            {"role":"system",    "content":_SYS},
            {"role":"user",      "content":context},
            {"role":"assistant", "content": seed_reply or
             f"I'm ready to discuss '{title}'. "
             "Ask me anything about this chapter, the book's ideas, "
             "or type 'coach' for reflection questions."},
        ]
        turn  = 0; _WARN = 7_000
        console.print(Panel(
            f"[bold cyan]💬 Chat about: {title}[/]\n\n"
            f"Currently on: [yellow]{chapters[current_ch]['title']}[/]\n\n"
            "Ask anything — ideas, explanations, themes, comparisons.\n"
            "[bold]Commands:[/]  [cyan]coach[/]  [cyan]finance[/]  "
            "[cyan]summary[/]  [cyan]clear[/]  [cyan]exit[/]",
            border_style="cyan", title="[bold white]Book Chat[/]", expand=False
        ))
        while True:
            est = sum(len(m["content"]) for m in history)//4
            tok = f"[yellow]~{est} ⚠[/]" if est>=_WARN else f"[dim]~{est} tokens[/]"
            q   = Prompt.ask(
                f"\n  [bold cyan]You[/] [dim](turn {turn+1} | {tok})[/]"
            ).strip()
            if not q: continue
            if q.lower()=="exit":   console.print("  [dim]Returning to reader…[/]"); break
            if q.lower()=="clear":
                history=[{"role":"system","content":_SYS}]; turn=0
                console.print("  [green]✓ Cleared.[/]"); continue
            if q.lower()=="coach":
                self._ai_reading_coach(book_dict, chapters[current_ch])
                input("  Press ENTER to continue…"); continue
            if q.lower()=="finance":
                self._ai_finance_lens(book_dict, chapters); input("  Press ENTER…"); continue
            if q.lower()=="summary":
                self._ai_summarise_chapter(title, chapters[current_ch])
                input("  Press ENTER…"); continue
            history.append({"role":"user","content":q})
            conv  = "\n".join(
                f"{m['role'].upper()}: {m['content']}" for m in history[1:]
            )
            reply, lat = self._ai_call(_SYS, conv)
            if reply:
                console.print(Panel(
                    Markdown(reply), border_style="green",
                    title=f"[bold green]Assistant[/] [dim]({lat:.2f}s)[/]",
                    expand=False
                ))
                history.append({"role":"assistant","content":reply})
                turn+=1
            else:
                history.pop()
    def open_reader(self, book_dict: dict) -> None:
        from rich.console import Console
        from rich.panel   import Panel
        from rich.rule    import Rule
        from rich.prompt  import Prompt
        from rich.markdown import Markdown
        console = Console()
        console.print(f"\n  [dim]Parsing EPUB: {book_dict['title']}…[/]")
        if book_dict.get('error') or book_dict.get('book_obj') is None:
            console.print(f"  [red]Cannot open: {book_dict.get('error','No book object')}[/]")
            return
        chapters = self._parse_chapters(book_dict['book_obj'])
        if not chapters:
            console.print("  [bold red]✗ No readable text found in this EPUB.[/]")
            return
        total_words  = sum(c['words'] for c in chapters)
        bh           = book_dict['hash']
        prog         = self.progress.get(bh, {})
        current_ch   = min(prog.get('chapter', 0), len(chapters)-1)
        current_pg   = prog.get('page', 0)
        words_read   = prog.get('words_read', 0)
        t_open       = time.time()
        while True:
            cols, rows    = shutil.get_terminal_size((100, 30))
            content_width = min(cols - 6, 115)
            lpp           = max(rows - 11, 15)
            chapter       = chapters[current_ch]
            pages         = self._paginate(chapter['text'], lpp, content_width)
            current_pg    = max(0, min(current_pg, len(pages)-1))
            words_this_chapter = chapter['words']
            words_before       = sum(c['words'] for c in chapters[:current_ch])
            words_so_far       = words_before + int(
                (current_pg / max(len(pages)-1,1)) * words_this_chapter
            )
            pct                = words_so_far / max(total_words,1) * 100
            remaining_words    = total_words - words_so_far
            remaining_min      = max(1, remaining_words // READING_SPEED)
            os.system('cls' if os.name == 'nt' else 'clear')
            header = (
                f"📖 {book_dict['title'][:40]}  "
                f"[dim]by {book_dict['author'][:25]}[/]"
            )
            console.print(Panel(
                header,
                border_style="blue", expand=True
            ))
            if current_pg == 0:
                console.print(
                    f"  [bold yellow]{chapter['title'].upper()}[/]  "
                    f"[dim]({chapter['words']:,} words · "
                    f"~{max(1,chapter['words']//READING_SPEED)}m)[/]\n"
                )
            for line in pages[current_pg]:
                console.print(f"  {line}")
            for _ in range(lpp - len(pages[current_pg])):
                print()
            pb    = self._prog_bar(pct, width=18)
            ch_s  = f"Ch {current_ch+1}/{len(chapters)}"
            pg_s  = f"Pg {current_pg+1}/{len(pages)}"
            rem_s = f"~{remaining_min}m left"
            console.print(Rule(style="dim"))
            console.print(
                f"  [cyan]{ch_s}[/]  [magenta]{pg_s}[/]  "
                f"[green]{pb}[/]  [dim]{rem_s}[/]"
            )
            console.print(
                "  [bold]↵[/]=Next  [bold]P[/]=Prev  "
                "[bold]C/B[/]=Chapter  [bold]T[/]=TOC  "
                "[bold]K[/]=Bookmark  [bold]F[/]=Find  "
                "[bold]S[/]=AI Sum  [bold]Z[/]=Chat  "
                "[bold]A[/]=Analysis  [bold]Q[/]=Quit"
            )
            action = input("  Action: ").strip().lower()
            if action in ('','n'):
                if current_pg < len(pages)-1:
                    current_pg += 1
                elif current_ch < len(chapters)-1:
                    current_ch += 1; current_pg = 0
                else:
                    console.print(
                        f"\n  [bold green]🎉 You have finished '{book_dict['title']}'![/]"
                    )
                    self.progress[bh] = {
                        'chapter':0, 'page':0, 'pct':100,
                        'words_read':total_words,
                        'last_read':datetime.now().strftime("%Y-%m-%d %H:%M"),
                    }
                    self._save_progress()
                    input("  Press ENTER to return to library…")
                    break
            elif action == 'p':
                if current_pg > 0:
                    current_pg -= 1
                elif current_ch > 0:
                    current_ch -= 1
                    prev_pages = self._paginate(
                        chapters[current_ch]['text'], lpp, content_width
                    )
                    current_pg = len(prev_pages)-1
            elif action == 'c':
                if current_ch < len(chapters)-1:
                    current_ch += 1; current_pg = 0
            elif action == 'b':
                if current_ch > 0:
                    current_ch -= 1; current_pg = 0
            elif action == 't':
                os.system('cls' if os.name == 'nt' else 'clear')
                from rich.table import Table
                from rich import box as _box
                tbl = Table(
                    title=f"Table of Contents — {book_dict['title'][:35]}",
                    border_style="cyan", box=_box.SIMPLE_HEAVY,
                    show_lines=False, expand=False
                )
                tbl.add_column("#",     style="bold cyan", width=5)
                tbl.add_column("Chapter",               width=40)
                tbl.add_column("Words",  justify="right",width=8, style="dim")
                tbl.add_column("~Time",  justify="right",width=6, style="dim")
                for i, ch in enumerate(chapters):
                    rt   = max(1, ch['words']//READING_SPEED)
                    style= "bold white" if i==current_ch else ""
                    marker = " ◄" if i==current_ch else ""
                    title_markup = f"[{style}]{ch['title'][:38]}{marker}[/{style}]" if style else f"{ch['title'][:38]}{marker}"
                    tbl.add_row(
                        str(i+1),
                        title_markup,
                        f"{ch['words']:,}",
                        f"{rt}m",
                    )
                console.print(tbl)
                jmp = input("  Jump to chapter # (ENTER to cancel): ").strip()
                if jmp.isdigit() and 1<=int(jmp)<=len(chapters):
                    current_ch = int(jmp)-1; current_pg = 0
            elif action == 'k':
                note = input("  Bookmark note (ENTER to skip): ").strip()
                bms  = self.bookmarks_db.setdefault(bh, [])
                bms.append({
                    'chapter': current_ch,
                    'page'   : current_pg,
                    'note'   : note or f"{chapter['title']} p{current_pg+1}",
                    'ts'     : datetime.now().strftime("%d %b %H:%M"),
                })
                self._save_bookmarks()
                console.print("  [green]✓ Bookmark saved.[/]"); time.sleep(0.8)
            elif action == 'v':
                bms = self.bookmarks_db.get(bh, [])
                if not bms:
                    console.print("  [dim]No bookmarks for this book.[/]")
                    time.sleep(1); continue
                os.system('cls' if os.name == 'nt' else 'clear')
                from rich.table import Table
                from rich import box as _box
                bt = Table(title="Bookmarks", border_style="cyan",
                           box=_box.SIMPLE_HEAVY)
                bt.add_column("#",    style="bold cyan", width=4)
                bt.add_column("Note", width=35)
                bt.add_column("Location", width=20)
                bt.add_column("Saved", width=14, style="dim")
                for i, bm in enumerate(bms, 1):
                    ch_t = chapters[bm['chapter']]['title'][:18]
                    bt.add_row(
                        str(i), bm['note'][:33],
                        f"{ch_t} p{bm['page']+1}", bm['ts']
                    )
                console.print(bt)
                jmp = input("  Jump to # (D+# delete, ENTER cancel): ").strip().upper()
                if jmp.isdigit() and 1<=int(jmp)<=len(bms):
                    bm = bms[int(jmp)-1]
                    current_ch = min(bm['chapter'], len(chapters)-1)
                    current_pg = bm['page']
                elif jmp.startswith('D') and jmp[1:].isdigit():
                    idx = int(jmp[1:])-1
                    if 0<=idx<len(bms):
                        bms.pop(idx); self._save_bookmarks()
                        console.print("  [dim]Bookmark deleted.[/]"); time.sleep(0.8)
            elif action == 'f':
                query = input("  Search text: ").strip()
                if not query: continue
                hits = self._search_in_chapters(chapters, query)
                if not hits:
                    console.print(f"  [yellow]'{query}' not found.[/]"); time.sleep(1); continue
                os.system('cls' if os.name == 'nt' else 'clear')
                from rich.table import Table
                from rich import box as _box
                ft = Table(title=f"Search: '{query}' ({len(hits)} hits)",
                           border_style="cyan", box=_box.SIMPLE_HEAVY,
                           expand=True)
                ft.add_column("#",       style="bold cyan", width=4)
                ft.add_column("Chapter", width=22)
                ft.add_column("Context", ratio=1)
                for i,(ci,_,ctx) in enumerate(hits,1):
                    ch_name = chapters[ci]['title'][:20]
                    ctx_hl = re.sub(
                        re.escape(query),
                        f"[bold yellow]{query}[/]",
                        ctx, flags=re.IGNORECASE
                    )
                    ft.add_row(str(i), ch_name, ctx_hl)
                console.print(ft)
                jmp = input("  Jump to result # (ENTER cancel): ").strip()
                if jmp.isdigit() and 1<=int(jmp)<=len(hits):
                    ci,_,__ = hits[int(jmp)-1]
                    current_ch = ci; current_pg = 0
            elif action == 's':
                if not self._or_key:
                    console.print("  [red]Configure AI key in Settings.[/]"); time.sleep(1); continue
                self._ai_summarise_chapter(book_dict['title'], chapter)
                input("  Press ENTER to continue reading…")
            elif action == 'e':
                if not self._or_key:
                    console.print("  [red]Configure AI key in Settings.[/]"); time.sleep(1); continue
                passage = input(
                    "  Paste or type the passage you want explained:\n  > "
                ).strip()
                if passage:
                    self._ai_explain_passage(book_dict['title'], passage)
                input("  Press ENTER to continue reading…")
            elif action == 'a':
                if not self._or_key:
                    console.print("  [red]Configure AI key in Settings.[/]"); time.sleep(1); continue
                self._ai_book_analysis(book_dict, chapters)
                input("  Press ENTER to continue reading…")
            elif action == 'l':
                if not self._or_key:
                    console.print("  [red]Configure AI key in Settings.[/]"); time.sleep(1); continue
                self._ai_finance_lens(book_dict, chapters)
                input("  Press ENTER to continue reading…")
            elif action == 'r':
                if not self._or_key:
                    console.print("  [red]Configure AI key in Settings.[/]"); time.sleep(1); continue
                self._ai_reading_coach(book_dict, chapter)
                input("  Press ENTER to continue reading…")
            elif action == 'z':
                if not self._or_key:
                    console.print("  [red]Configure AI key in Settings.[/]"); time.sleep(1); continue
                self._ai_chat(book_dict, chapters, current_ch)
            elif action == 'i':
                os.system('cls' if os.name == 'nt' else 'clear')
                session_min = int((time.time()-t_open)//60)
                console.print(Panel(
                    f"[bold white]{book_dict['title']}[/]\n"
                    f"[dim]by {book_dict['author']}[/]\n\n"
                    f"[bold]Progress:[/]     {pct:.1f}%  {self._prog_bar(pct,25)}\n"
                    f"[bold]Position:[/]     Ch {current_ch+1}/{len(chapters)} · "
                    f"Pg {current_pg+1}/{len(pages)}\n"
                    f"[bold]Words read:[/]   {words_so_far:,} / {total_words:,}\n"
                    f"[bold]Time remaining:[/] ~{remaining_min} min\n"
                    f"[bold]Session time:[/] {session_min} min\n"
                    f"[bold]File:[/]         {book_dict['filename']}\n"
                    f"[bold]Size:[/]         {book_dict['size_kb']:,} KB\n"
                    f"[bold]Language:[/]     {book_dict.get('language','?')}\n\n"
                    f"[dim]{book_dict.get('description','')[:200]}[/]",
                    border_style="cyan",
                    title="[bold white]Book Info[/]"
                ))
                input("  Press ENTER to continue reading…")
            elif action == 'q':
                break
            session_secs = time.time() - t_open
            self._session_words = int(
                pct / 100 * total_words - words_read
            )
            self.progress[bh] = {
                'chapter'    : current_ch,
                'page'       : current_pg,
                'pct'        : round(pct, 1),
                'words_read' : words_so_far,
                'last_read'  : datetime.now().strftime("%Y-%m-%d %H:%M"),
            }
            self._save_progress()
        self._save_stats()
    def _settings(self, console) -> None:
        from rich.panel  import Panel
