        from rich.prompt import Prompt
        from rich.table  import Table
        MODELS = [
            (_GLOBAL_OR_MODEL,"nemotron 3 super"),
            ("nvidia/nemotron-3-super-120b-a12b:free","Llama 3.3 70B [FREE]"),
            ("nvidia/nemotron-3-super-120b-a12b:free","DeepSeek R1 [FREE]"),
            ("nvidia/nemotron-3-super-120b-a12b:free","GPT-4o Mini [PAID]"),
            ("nvidia/nemotron-3-super-120b-a12b:free","Claude Haiku [PAID]"),
        ]
        console.clear()
        masked = f"sk-…{self._or_key[-6:]}" if len(self._or_key)>6 else "[red]Not set[/]"
        console.print(Panel(
            f"[bold cyan]🔧 Module 51 — Settings[/]\n\n"
            f"Key   : {masked}\nModel : [dim]{self._or_model}[/]",
            border_style="cyan"
        ))
        nk = Prompt.ask("  New API Key [dim](ENTER to keep)[/]",default="").strip()
        if nk: self._or_key = nk
        tbl = Table(border_style="cyan")
