        for i,(mid,lbl) in enumerate(MODELS,1):
            act = " [green]◄[/]" if mid==self._or_model else ""
            tbl.add_row(str(i), lbl+act, mid)
        console.print(tbl)
        mc = Prompt.ask("  Model #",default="").strip()
        if mc.isdigit() and 1<=int(mc)<=len(MODELS):
            self._or_model = MODELS[int(mc)-1][0]
