class CorporateDocumentsHub:
    def __init__(self, ticker):
        self.ticker = ticker.upper()
        self.clean_ticker = self.ticker.replace('.NS', '').replace('.BO', '')
        self.documents = {
            "Announcements": [],
            "Annual Reports": [],
            "Credit Ratings": []
        }
    def fetch_documents(self):
        try:
            from bs4 import BeautifulSoup
        except ImportError:
            print("  \033[91m[!] Error: 'beautifulsoup4' library is missing.\033[0m")
            return False
        print(f"  Fetching Corporate Documents for {self.clean_ticker}...")
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36'
        }
        urls = [
            f"https://www.screener.in/company/{self.clean_ticker}/consolidated/",
            f"https://www.screener.in/company/{self.clean_ticker}/"
        ]
        html_content = None
        for url in urls:
            try:
                res = requests.get(url, headers=headers, timeout=10)
                if res.status_code == 200:
                    html_content = res.text
                    break
            except Exception:
                continue
        if not html_content:
            print("  \033[91m[!] Connection to Screener failed.\033[0m")
            return False
        soup = BeautifulSoup(html_content, 'html.parser')
        docs_section = soup.find('section', id='documents')
        if not docs_section:
            print("  \033[91m[!] Documents section not available for this ticker.\033[0m")
            return False
        for ul in docs_section.find_all('ul'):
            header = ul.find_previous(['h2', 'h3', 'h4'])
            if header:
                cat_name = header.text.strip().lower()
                matched_key = None
                if "announcement" in cat_name: matched_key = "Announcements"
                elif "annual report" in cat_name: matched_key = "Annual Reports"
                elif "credit rating" in cat_name: matched_key = "Credit Ratings"
                if matched_key:
                    for li in ul.find_all('li'):
                        a_tag = li.find('a')
                        if a_tag and a_tag.has_attr('href'):
                            title = " ".join(a_tag.text.split())
                            link = a_tag['href']
                            if not link.startswith('http'):
                                link = "https://www.screener.in" + link
                            self.documents[matched_key].append({'title': title, 'link': link})
        return True
    def _open_category_menu(self, category_name):
        import webbrowser
        B, C, G, Y, R, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[0m'
        docs = self.documents[category_name]
        if not docs:
            print(f"\n  {Y}[!] No documents found in '{category_name}'.{RES}")
            input(f"\n  Press ENTER to return...")
            return
        while True:
            print(f"\n  {C}{B}--- {category_name.upper()} ---{RES}")
            print(f"  {B}Ticker:{RES} {self.ticker}")
            print("  " + "─" * 70)
            display_docs = docs[:15]
            for i, doc in enumerate(display_docs, 1):
                title = doc['title']
                if len(title) > 60: title = title[:57] + "..."
                print(f"  {B}{i:>2}.{RES} {title}")
            print("  " + "─" * 70)
            print(f"  {B}0.{RES} Go Back")
            choice = input(f"\n  Select document to open [0-{len(display_docs)}]: ").strip()
            if choice == '0':
                break
            elif choice.isdigit() and 1 <= int(choice) <= len(display_docs):
                selected_doc = display_docs[int(choice)-1]
                print(f"  {G}Opening: {selected_doc['title']}{RES}")
                webbrowser.open(selected_doc['link'])
            else:
                print(f"  {R}Invalid selection.{RES}")
    def interactive_menu(self):
        if not self.fetch_documents(): return
        B, C, G, Y, R, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[0m'
        BLUE_BG = '\033[44m\033[97m'
        while True:
            print(f"\n  {BLUE_BG} CORPORATE DOCUMENTS HUB | {self.ticker} {' ' * 20} {RES}")
            print("  " + "═" * 70)
            ann_count = len(self.documents["Announcements"])
            ar_count = len(self.documents["Annual Reports"])
            cr_count = len(self.documents["Credit Ratings"])
            print(f"  {B}1.{RES} View {G}Announcements{RES} ({ann_count} Files)")
            print(f"  {B}2.{RES} View {C}Annual Reports{RES} ({ar_count} Files)")
            print(f"  {B}3.{RES} View {Y}Credit Ratings{RES} ({cr_count} Files)")
            print(f"  {B}4.{RES} Open 'All Documents' webpage directly")
            print(f"  {B}0.{RES} Return to Main Menu")
            print("  " + "═" * 70)
            choice = input(f"\n  Select document category [0-4]: ").strip()
            if choice == '1':
                self._open_category_menu("Announcements")
            elif choice == '2':
                self._open_category_menu("Annual Reports")
            elif choice == '3':
                self._open_category_menu("Credit Ratings")
            elif choice == '4':
                import webbrowser
                url = f"https://www.screener.in/company/{self.clean_ticker}/consolidated/#documents"
                print(f"  {G}Launching Screener Documents portal...{RES}")
                webbrowser.open(url)
            elif choice == '0':
                break
            else:
                print(f"  {R}Invalid selection.{RES}")
def run_documents_hub(ticker):
    header(f"MODULE 43 — CORPORATE DOCUMENTS HUB")
    hub = CorporateDocumentsHub(ticker)
    hub.interactive_menu()
