class IntradayScanner:
    _LOT_SIZES: Dict[str, int] = {
        'NIFTY':      50,
        'BANKNIFTY':  15,
        'FINNIFTY':   40,
        'MIDCPNIFTY': 75,
        'RELIANCE':   250,
        'ITC':        3200,
        'HDFCBANK':   550,
        'INFY':       400,
        'TCS':        150,
        'ICICIBANK':  700,
        'SBIN':       1500,
        'AXISBANK':   1200,
        'WIPRO':      1500,
        'KOTAKBANK':  400,
        'LT':         300,
        'BAJFINANCE': 125,
        'TATAMOTORS': 1400,
        'TATASTEEL':  5500,
        'IDEA':       70000,
        'ZOMATO':     4500,
        'ADANIENT':   125,
    }
    _W: Dict[str, float] = {
        'gamma_per_rupee': 30.0,                               
        'delta_zone':      25.0,                                        
        'liquidity':       25.0,                          
        'vega_per_rupee':  10.0,                             
        'theta_hourly':    10.0,                         
    }
    @dataclass
    class IntradayScore:
        total:          float = 0.0                           
        gamma_score:    float = 0.0                                   
        delta_score:    float = 0.0                                  
        liquidity_score:float = 0.0                                 
        vega_score:     float = 0.0                                  
        theta_score:    float = 0.0                                        
        expected_move:  float = 0.0                                   
        proj_pnl_half:  float = 0.0                                         
        proj_pnl_one:   float = 0.0                                         
        proj_pnl_one5:  float = 0.0                                         
        lot_size:       int   = 1                                    
        verdict:        str   = ""                            
        guidance:       List[str] = field(default_factory=list)
        risks:          List[str] = field(default_factory=list)
    @classmethod
    def _get_lot_size(cls, symbol: str) -> int:
        clean = symbol.upper().replace('.NS', '').replace('.BO', '')
        return cls._LOT_SIZES.get(clean, 1)
    @classmethod
    def _score_contract(
        cls,
        c:      'AnalysedContract',
        symbol: str,
    ) -> 'IntradayScanner.IntradayScore':
        g       = c.greeks
        ltp     = g.price_market if g.price_market > 0.05 else g.price_bsm
        lot     = cls._get_lot_size(symbol)
        result  = cls.IntradayScore(lot_size=lot)
        if ltp <= 0:
            return result
        gamma_price_ratio = g.gamma / ltp if ltp > 0 else 0.0
        if gamma_price_ratio > 0:
            gp_normalised = min(
                100.0,
                math.log10(gamma_price_ratio * 10000 + 1) / math.log10(21) * 100
            )
        else:
            gp_normalised = 0.0
        result.gamma_score = gp_normalised
        abs_d = abs(g.delta)
        if 0.40 <= abs_d <= 0.60:
            delta_s = 100.0                                            
        elif 0.35 <= abs_d < 0.40:
            delta_s = 70.0 + (abs_d - 0.35) / 0.05 * 30.0            
        elif 0.60 < abs_d <= 0.70:
            delta_s = 70.0 + (0.70 - abs_d) / 0.10 * 30.0              
        elif 0.25 <= abs_d < 0.35:
            delta_s = 30.0 + (abs_d - 0.25) / 0.10 * 40.0               
        elif 0.70 < abs_d <= 0.80:
            delta_s = 30.0 + (0.80 - abs_d) / 0.10 * 40.0
        else:
            delta_s = max(0.0, abs_d / 0.25 * 10.0)                               
        result.delta_score = delta_s
        oi  = g.oi
        vol = g.volume
        if oi >= 100_000:
            oi_score = 100.0
        elif oi >= 50_000:
            oi_score = 85.0 + (oi - 50_000) / 50_000 * 15.0
        elif oi >= 10_000:
            oi_score = 60.0 + (oi - 10_000) / 40_000 * 25.0
        elif oi >= 1_000:
            oi_score = 20.0 + (oi - 1_000) / 9_000 * 40.0
        else:
            oi_score = max(0.0, oi / 1_000 * 20.0)
        vol_score = min(100.0, math.log10(vol + 1) / math.log10(10001) * 100) if vol > 0 else 0.0
        result.liquidity_score = 0.6 * oi_score + 0.4 * vol_score
        vega_price = g.vega / ltp if ltp > 0 else 0.0
        result.vega_score = min(100.0, vega_price / 0.20 * 100.0)
        hourly_theta_pct = (
            abs(g.theta) / 6.25 / ltp * 100                                       
            if ltp > 0 else 0.0
        )
        if hourly_theta_pct < 0.5:
            theta_s = 100.0
        elif hourly_theta_pct < 1.0:
            theta_s = 100.0 - (hourly_theta_pct - 0.5) / 0.5 * 30.0
        elif hourly_theta_pct < 3.0:
            theta_s = 70.0 - (hourly_theta_pct - 1.0) / 2.0 * 50.0
        else:
            theta_s = max(0.0, 20.0 - (hourly_theta_pct - 3.0) * 5.0)
        result.theta_score = theta_s
        result.total = (
            cls._W['gamma_per_rupee'] * result.gamma_score  / 100.0 +
            cls._W['delta_zone']      * result.delta_score   / 100.0 +
            cls._W['liquidity']       * result.liquidity_score / 100.0 +
            cls._W['vega_per_rupee']  * result.vega_score    / 100.0 +
            cls._W['theta_hourly']    * result.theta_score   / 100.0
        )
        result.total = max(0.0, min(100.0, result.total))
        S  = c.greeks.price_bsm / max(abs(g.delta), 1e-6)                        
        if g.moneyness > 0:
            S = c.strike / g.moneyness                      
        expected_move = S * (g.iv / math.sqrt(252))
        result.expected_move = expected_move
        def _proj_pnl(ds: float) -> float:
            per_unit = g.delta * ds + 0.5 * g.gamma * ds * ds
            return per_unit * lot
        result.proj_pnl_half = _proj_pnl(expected_move * 0.5)
        result.proj_pnl_one  = _proj_pnl(expected_move * 1.0)
        result.proj_pnl_one5 = _proj_pnl(expected_move * 1.5)
        if result.total >= 75:
            result.verdict = "[bold green]⚡ PRIME INTRADAY TARGET[/]"
        elif result.total >= 55:
            result.verdict = "[bold yellow]◈ GOOD INTRADAY SETUP[/]"
        elif result.total >= 35:
            result.verdict = "[yellow]◇ MODERATE — PROCEED WITH CAUTION[/]"
        else:
            result.verdict = "[bold red]✗ POOR INTRADAY SETUP[/]"
        entry_price   = ltp
        stop_loss     = round(entry_price * 0.40, 2)                                                       
        target_1      = round(entry_price + result.proj_pnl_one / lot, 2)
        target_2      = round(entry_price + result.proj_pnl_one5 / lot, 2)
        result.guidance = [
            f"[bold]Entry:[/]       Buy between ₹{entry_price*0.97:.2f} – ₹{entry_price*1.03:.2f} "
            f"(±3% of current LTP)",
            f"[bold]Stop Loss:[/]   ₹{stop_loss:.2f}  "
            f"[dim](40% of premium — standard intraday option stop)[/]",
            f"[bold]Target 1:[/]    ₹{target_1:.2f}  "
            f"[dim](at 1× expected move ₹{expected_move:.1f})[/]",
            f"[bold]Target 2:[/]    ₹{target_2:.2f}  "
            f"[dim](at 1.5× expected move ₹{expected_move*1.5:.1f})[/]",
            f"[bold]Exit latest:[/] [red]15:15 IST[/]  "
            f"[dim](never hold options into last 15 min — spreads widen sharply)[/]",
        ]
        result.risks = []
        if hourly_theta_pct > 2.0:
            result.risks.append(
                f"[red]HIGH THETA BURN:[/] Losing ~{hourly_theta_pct:.1f}% of premium "
                f"per hour. Must enter and exit within same session."
            )
        if result.liquidity_score < 40:
            result.risks.append(
                f"[red]LOW LIQUIDITY:[/] OI={int(oi):,} — spreads may be wide. "
                f"Use limit orders only; never market orders."
            )
        if g.iv * 100 > 50:
            result.risks.append(
                f"[yellow]HIGH IV:[/] At {g.iv*100:.1f}%, premium is expensive. "
                f"A correct direction with no IV expansion may underperform."
            )
        if abs(g.delta) < 0.30:
            result.risks.append(
                f"[yellow]LOW DELTA:[/] Δ={g.delta:.3f} — "
                f"needs a large move just to generate meaningful P&L."
            )
        if ltp < 1.0:
            result.risks.append(
                f"[yellow]VERY CHEAP OPTION:[/] ₹{ltp:.2f} premium — "
                f"likely illiquid deep OTM. Slippage will dominate P&L."
            )
        return result
    @classmethod
    def find_best_intraday(
        cls,
        calls:   List['AnalysedContract'],
        puts:    List['AnalysedContract'],
        symbol:  str,
        spot:    float,
        iv:      float,
    ) -> Tuple[
        Optional['AnalysedContract'],
        Optional['IntradayScanner.IntradayScore'],
        Optional['AnalysedContract'],
        Optional['IntradayScanner.IntradayScore'],
    ]:
        def _best(contracts: List['AnalysedContract']):
            if not contracts:
                return None, None
            scored = [
                (c, cls._score_contract(c, symbol))
                for c in contracts
            ]
            scored.sort(key=lambda x: x[1].total, reverse=True)
            return scored[0]
        bc, bcs = _best(calls)
        bp, bps = _best(puts)
        return bc, bcs, bp, bps
    @classmethod
    def render(
        cls,
        call:      Optional['AnalysedContract'],
        call_sc:   Optional['IntradayScanner.IntradayScore'],
        put:       Optional['AnalysedContract'],
        put_sc:    Optional['IntradayScanner.IntradayScore'],
        spot:      float,
    ) -> None:
        from rich.console import Console
        from rich.table import Table
        from rich.panel import Panel
        from rich import box
        console = Console()
        console.print(Panel(
            "[bold white on dark_orange] ⚡  INTRADAY STRIKE RECOMMENDER "
            "— Maximum Same-Day P&L  [/]",
            border_style="dark_orange",
            padding=(0, 1),
        ))
        def _render_one(
            side_label: str,
            c:          Optional['AnalysedContract'],
            sc:         Optional['IntradayScanner.IntradayScore'],
        ) -> None:
            if c is None or sc is None:
                console.print(f"  [red]No {side_label} data available.[/]")
                return
            g   = c.greeks
            ltp = g.price_market if g.price_market > 0.05 else g.price_bsm
            color = "green" if side_label == "CALL" else "red"
            score_tbl = Table(
                title=(
                    f"[bold {color}]BEST INTRADAY {side_label}: "
                    f"₹{c.strike:,.1f} {side_label}  "
                    f"| LTP ₹{ltp:.2f}  "
                    f"| IV {g.iv*100:.1f}%  "
                    f"| Δ {g.delta:+.3f}[/]"
                ),
                box=box.ROUNDED,
                header_style=f"bold {color}",
                show_lines=True,
            )
            score_tbl.add_column("Factor",              style="bold", width=22)
            score_tbl.add_column("Raw Value",           justify="right", width=14)
            score_tbl.add_column("Sub-Score /100",      justify="center", width=16)
            score_tbl.add_column("Weight",              justify="right", width=8)
            score_tbl.add_column("Contribution",        justify="right", width=13)
            score_tbl.add_column("Interpretation",      width=36)
            def _sc_col(s: float) -> str:
                col = "green" if s >= 70 else ("yellow" if s >= 40 else "red")
                bar = '█' * int(s / 10) + '░' * (10 - int(s / 10))
                return f"[{col}]{bar} {s:.0f}[/]"
            rows = [
                (
                    "Γ/Price  (convexity)",
                    f"{g.gamma/ltp:.5f}",
                    sc.gamma_score,
                    30,
                    sc.gamma_score * 0.30,
                    "How fast Delta accelerates per ₹ invested",
                ),
                (
                    "Δ Zone  (direction)",
                    f"{abs(g.delta):.3f}",
                    sc.delta_score,
                    25,
                    sc.delta_score * 0.25,
                    "Proximity to optimal ATM band (0.40–0.60)",
                ),
                (
                    "Liquidity  (OI+Vol)",
                    f"OI {int(g.oi):,}",
                    sc.liquidity_score,
                    25,
                    sc.liquidity_score * 0.25,
                    "Entry/exit ease — OI & volume proxy",
                ),
                (
                    "ν/Price  (IV expansion)",
                    f"{g.vega/ltp:.3f}",
                    sc.vega_score,
                    10,
                    sc.vega_score * 0.10,
                    "Bonus if IV spikes intraday",
                ),
                (
                    "Hourly Θ cost",
                    f"{abs(g.theta)/6.25/ltp*100:.2f}%/hr",
                    sc.theta_score,
                    10,
                    sc.theta_score * 0.10,
                    "Premium burned per hour held",
                ),
            ]
            for name, raw, sub, wt, contrib, interp in rows:
                score_tbl.add_row(
                    name, raw,
                    _sc_col(sub),
                    f"{wt}%",
                    f"[bold]{contrib:.1f}[/]",
                    f"[dim]{interp}[/]",
                )
            score_tbl.add_row(
                "[bold]COMPOSITE SCORE[/]", "",
                _sc_col(sc.total),
                "[bold]100%[/]",
                f"[bold]{sc.total:.1f}[/]",
                sc.verdict,
                style="bold",
            )
            console.print(score_tbl)
            pnl_tbl = Table(
                title="[bold]Projected P&L per Lot[/] "
                      "[dim](Δ·ΔS + ½·Γ·ΔS² — 2nd-order Taylor)[/]",
                box=box.SIMPLE_HEAVY,
                header_style="bold yellow",
            )
            pnl_tbl.add_column("Scenario",       width=22)
            pnl_tbl.add_column("Spot Move",      justify="right", width=12)
            pnl_tbl.add_column("New Spot",        justify="right", width=12)
            pnl_tbl.add_column("Δ P&L",          justify="right", width=12)
            pnl_tbl.add_column("Γ P&L (bonus)",  justify="right", width=14)
            pnl_tbl.add_column("Total P&L/Lot",  justify="right", width=14)
            pnl_tbl.add_column("Return on Premium", justify="right", width=16)
            direction = 1 if side_label == "CALL" else -1
            for label_, mult_ in [
                ("0.5× Expected (calm)", 0.5),
                ("1.0× Expected (normal)", 1.0),
                ("1.5× Expected (strong)", 1.5),
            ]:
                ds         = sc.expected_move * mult_ * direction
                delta_pnl  = g.delta * ds * sc.lot_size
                gamma_pnl  = 0.5 * g.gamma * ds * ds * sc.lot_size
                total_pnl  = delta_pnl + gamma_pnl
                invested   = ltp * sc.lot_size
                ret_pct    = total_pnl / invested * 100 if invested > 0 else 0
                pnl_col   = "green" if total_pnl > 0 else "red"
                ret_col   = "green" if ret_pct  > 0 else "red"
                new_spot = spot + ds
                pnl_tbl.add_row(
                    label_,
                    f"{'↑' if direction > 0 else '↓'} ₹{abs(ds):,.1f}",
                    f"₹{new_spot:,.1f}",
                    f"[{pnl_col}]₹{delta_pnl:+,.0f}[/]",
                    f"[{pnl_col}]₹{gamma_pnl:+,.0f}[/]",
                    f"[{pnl_col}][bold]₹{total_pnl:+,.0f}[/][/]",
                    f"[{ret_col}][bold]{ret_pct:+.1f}%[/][/]",
                )
            ds_sl = -ltp * 0.40 / max(abs(g.delta), 1e-6) * direction          
            pnl_tbl.add_row(
                "[red]Stop-Loss (−40% of LTP)[/]",
                f"[red]{'↓' if direction > 0 else '↑'} adverse[/]",
                "[dim]varies[/]",
                "[dim]—[/]",
                "[dim]—[/]",
                f"[red][bold]−₹{ltp*0.40*sc.lot_size:,.0f}[/][/]",
                f"[red][bold]−40.0%[/][/]",
            )
            console.print(pnl_tbl)
            guide_text = "\n".join(f"  {line}" for line in sc.guidance)
            console.print(Panel(
                guide_text,
                title="[bold yellow]📋 Entry · Target · Stop Guidance[/]",
                border_style="yellow",
                padding=(0, 2),
            ))
            if sc.risks:
                risk_text = "\n".join(f"  ⚠  {r}" for r in sc.risks)
                console.print(Panel(
                    risk_text,
                    title="[bold red]⚠ Intraday Risk Warnings[/]",
                    border_style="red",
                    padding=(0, 2),
                ))
        _render_one("CALL", call, call_sc)
        console.print()
        _render_one("PUT",  put,  put_sc)
class OptionsChainOracle:
    def __init__(self, ticker: str, r: float = _DEFAULT_R):
        self.raw_ticker  = ticker.upper()
        self.nse_symbol  = self._normalise_symbol(self.raw_ticker)
        self.r           = r
        self.S:           float = 0.0
        self.hist_vol:    float = 0.20
        self.T:           float = 0.0
        self.dte:         float = 0.0
        self.selected_expiry: Optional[str] = None
        self._calls: List[AnalysedContract] = []
        self._puts:  List[AnalysedContract] = []
    @staticmethod
    def _normalise_symbol(ticker: str) -> str:
        sym = ticker.replace('.NS', '').replace('.BO', '').upper()
        _map = {
            '^NSEI':    'NIFTY',
            'NIFTY50':  'NIFTY',
            '^NSEBANK': 'BANKNIFTY',
            '^CNXFIN':  'FINNIFTY',
        }
        return _map.get(sym, sym)
    @staticmethod
    def _ensure_dependencies() -> bool:
        required = {
            'scipy':    'scipy',
            'numpy':    'numpy',
            'yfinance': 'yfinance',
            'nselib':   'nselib',
            'rich':     'rich',
        }
        missing = []
        for import_name in required:
            try:
                __import__(import_name)
            except ImportError:
                missing.append(required[import_name])
        if not missing:
            return True
        import sys, subprocess
        print(f"  [!] Installing missing packages: {', '.join(missing)}")
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install", "--quiet"] + missing
            )
            return True
        except Exception as exc:
            print(f"  [!] Auto-install failed: {exc}")
            print(f"  [!] Run manually: pip install {' '.join(missing)}")
            return False
    def _fetch_spot(self) -> bool:
        from rich.console import Console
        console = Console()
        console.print(
            f"  [cyan]Fetching spot price & historical vol for "
            f"{self.raw_ticker}...[/]"
        )
        try:
            stock = yf.Ticker(self.raw_ticker)
            hist  = stock.history(period="3mo")                                     
            if hist.empty or len(hist) < 5:
                console.print(
                    f"  [bold red][!] No price history for '{self.raw_ticker}'. "
                    f"Check ticker symbol.[/]"
                )
                return False
            self.S = float(hist['Close'].iloc[-1])
            log_ret   = np.log(hist['Close'] / hist['Close'].shift(1)).dropna()
            self.hist_vol = float(log_ret.std() * math.sqrt(252))
            if not math.isfinite(self.hist_vol) or self.hist_vol < 0.01:
                self.hist_vol = 0.20
                console.print(
                    "  [yellow][!] Vol estimation returned degenerate value; "
                    "using 20% default.[/]"
                )
            console.print(
                f"  [bold green][✓] Spot: ₹{self.S:,.2f}  |  "
                f"HVol: {self.hist_vol*100:.1f}%[/]"
            )
            return True
        except Exception as exc:
            console.print(
                f"  [bold red][!] yfinance error: {exc}[/]"
            )
            return False
    def _fetch_nse_chain(self) -> Optional[Any]:
        from nselib import derivatives
        from rich.console import Console
        console = Console()
        console.print(
            f"  [dim]Fetching NSE expiry dates for {self.nse_symbol}...[/]"
        )
        try:
            if self.nse_symbol in _NSE_INDEX_SYMBOLS:
                raw_exp = derivatives.expiry_dates_option_index()
                exp_dates = (
                    raw_exp.get(self.nse_symbol, raw_exp)
                    if isinstance(raw_exp, dict) else raw_exp
                )
            else:
                exp_dates = derivatives.expiry_dates_future()
        except Exception as exc:
            console.print(
                f"  [bold red][!] nselib expiry fetch failed: {exc}[/]"
            )
            return None
        valid_exp = None
        for exp in exp_dates:
            try:
                for fmt in ('%d-%b-%Y', '%d-%m-%Y'):
                    try:
                        dte = (datetime.strptime(exp, fmt) - datetime.now()).days
                        break
                    except ValueError:
                        continue
                else:
                    continue
                if dte >= 3:
                    valid_exp = exp
                    self.T    = dte / 365.0
                    self.dte  = float(dte)
                    break
            except Exception:
                continue
        if not valid_exp:
            console.print(
                f"  [bold red][!] No valid upcoming expiry for "
                f"'{self.nse_symbol}'.[/]"
            )
            return None
        self.selected_expiry = valid_exp
        console.print(
            f"  [bold green][✓] Expiry: {valid_exp} "
            f"({self.dte:.0f} DTE)[/]"
        )
        original_to_datetime = pd.to_datetime
        def _patched_to_datetime(*args, **kwargs):
            try:
                return original_to_datetime(*args, **kwargs)
            except (ValueError, TypeError):
                kwargs.pop('format', None)
                return original_to_datetime(*args, **kwargs)
        pd.to_datetime = _patched_to_datetime                
        chain_df = None
        try:
            console.print(
                f"  [dim]Fetching live chain from NSE...[/]"
            )
            chain_df = derivatives.nse_live_option_chain(
                self.nse_symbol, valid_exp
            )
            if chain_df is not None and not chain_df.empty:
                chain_df.columns = [
                    str(c).strip() for c in chain_df.columns
                ]
                console.print(
                    f"  [bold green][✓] Chain received: "
                    f"{len(chain_df)} rows, "
                    f"{len(chain_df.columns)} columns.[/]"
                )
        except Exception as exc:
            console.print(
                f"  [bold red][!] nselib chain fetch failed: {exc}[/]"
            )
        finally:
            pd.to_datetime = original_to_datetime                  
        return chain_df
    @staticmethod
    def _clean(val: Any) -> float:
        if val is None or (isinstance(val, float) and math.isnan(val)):
            return 0.0
        if isinstance(val, str):
            val = val.replace(',', '').replace('%', '').strip()
            if val in ('-', '--', ''):
                return 0.0
        try:
            return float(val)
        except (ValueError, TypeError):
            return 0.0
    def _analyse_side(
        self,
        chain_df: Any,
        side:     OptionSide,
    ) -> List[AnalysedContract]:
        prefix     = "CALLS" if side == OptionSide.CALL else "PUTS"
        strike_col = "Strike_Price"
        ltp_col    = f"{prefix}_LTP"
        iv_col     = f"{prefix}_IV"
        vol_col    = f"{prefix}_Volume"
        oi_col     = f"{prefix}_OI"
        if strike_col not in chain_df.columns or ltp_col not in chain_df.columns:
            return []
        df = chain_df.copy()
        df['_strike'] = df[strike_col].apply(self._clean)
        df = df[
            (df['_strike'] >= self.S * 0.85) &
            (df['_strike'] <= self.S * 1.15) &
            (df['_strike'] > 0)
        ]
        if df.empty:
            return []
        results: List[AnalysedContract] = []
        for _, row in df.iterrows():
            strike = self._clean(row['_strike'])
            ltp    = self._clean(row.get(ltp_col, 0))
            iv_raw = self._clean(row.get(iv_col, 0))
            vol    = self._clean(row.get(vol_col, 0))
            oi     = self._clean(row.get(oi_col, 0))
            if ltp < 0.05:
                continue
            iv_fallback_used = False
            if iv_raw < 0.5:
                iv     = self.hist_vol
                iv_fallback_used = True
            else:
                iv = iv_raw / 100.0
            g = BSMEngine.compute(
                S=self.S, K=strike, T=self.T, r=self.r,
                sigma=iv, side=side,
                ltp=ltp, oi=oi, volume=vol
            )
            if g is None:
                continue
            cs = ScoringEngine.evaluate(g, self.dte)
            if iv_fallback_used:
                cs.warnings.insert(0,
                    f"[dim]IV unavailable from NSE — using HVol "
                    f"{self.hist_vol*100:.1f}% as proxy.[/]"
                )
            results.append(AnalysedContract(
                side=side, strike=strike,
                dte=self.dte, greeks=g, score=cs
            ))
        results.sort(key=lambda c: c.score.score, reverse=True)
        return results
    def process_options_chain(self) -> bool:
        chain_df = self._fetch_nse_chain()
        if chain_df is None or chain_df.empty:
            return False
        self._calls = self._analyse_side(chain_df, OptionSide.CALL)
        self._puts  = self._analyse_side(chain_df, OptionSide.PUT)
        return bool(self._calls or self._puts)
    @staticmethod
    def _score_bar(score: int, width: int = 15) -> str:
        filled = int(round(score / 100.0 * width))
        bar    = '█' * filled + '░' * (width - filled)
        if score >= 80:
            return f"[green][{bar}][/]"
        elif score >= 60:
            return f"[yellow][{bar}][/]"
        else:
            return f"[red][{bar}][/]"
    @staticmethod
    def _moneyness_tag(moneyness: float, side: OptionSide) -> str:
        band = 0.015                
        if abs(moneyness - 1.0) <= band:
            return "[yellow]ATM[/]"
        if side == OptionSide.CALL:
            return "[green]ITM[/]" if moneyness > 1.0 else "[red]OTM[/]"
        return "[green]ITM[/]" if moneyness < 1.0 else "[red]OTM[/]"
    def _print_chain_table(
        self,
        contracts: List[AnalysedContract],
        side:      OptionSide,
    ) -> None:
        if not contracts:
            return
        from rich.console import Console
        from rich.table import Table
        from rich import box
        console = Console()
        color   = side.rich_color
        tbl = Table(
            title=(
                f"[bold {color}]"
                f"NSE LIVE — {side.label}S  "
                f"[dim](Expiry: {self.selected_expiry} · "
                f"Spot: ₹{self.S:,.2f})[/]"
                f"[/]"
            ),
            box=box.ROUNDED,
            header_style=f"bold {color}",
            show_lines=False,
        )
        for col, just, style in [
            ("Strike",        "right",  ""),
            ("M",             "center", "dim"),                  
            ("NSE LTP",       "right",  ""),
            ("BSM Fair",      "right",  "dim"),
            ("IV %",          "right",  ""),
            ("Delta",         "right",  ""),
            ("Gamma",         "right",  "dim"),
            ("Theta/day",     "right",  "red"),
            ("Vega/1%",       "right",  "yellow"),
            ("Θ/Δ",           "right",  ""),
            ("Score",         "center", ""),
            ("Verdict",       "left",   ""),
        ]:
            tbl.add_column(col, justify=just, style=style)
        best_score = contracts[0].score.score if contracts else -1
        for c in contracts:
            g  = c.greeks
            cs = c.score
            is_atm = abs(g.moneyness - 1.0) <= 0.015
            strike_str = (
                f"[bold yellow]₹{c.strike:>9,.1f} ★[/]"
                if c.score.score == best_score
                else f"₹{c.strike:>9,.1f}"
            )
            if is_atm:
                strike_str = f"[bold yellow]{strike_str}[/]"
            tdr     = g.theta_delta
            tdr_str = (
                f"[green]{tdr:.4f}[/]" if tdr < 0.10
                else f"[yellow]{tdr:.4f}[/]" if tdr < 0.20
                else f"[red]{tdr:.4f}[/]"
                if math.isfinite(tdr) else "[dim]∞[/]"
            )
            tbl.add_row(
                strike_str,
                self._moneyness_tag(g.moneyness, c.side),
                f"₹{g.price_market:>7.2f}",
                f"₹{g.price_bsm:>7.2f}",
                f"{g.iv*100:>5.1f}%",
                f"{g.delta:>+6.3f}",
                f"{g.gamma:>7.4f}",
                f"[red]{g.theta:>+7.2f}[/]",
                f"[yellow]{g.vega:>+6.3f}[/]",
                tdr_str,
                f"{self._score_bar(cs.score)} {cs.score}",
                cs.verdict,
            )
        console.print(tbl)
    def _print_top_candidate(self, contract: AnalysedContract) -> None:
        from rich.console import Console
        from rich.panel import Panel
        console = Console()
        g       = contract.greeks
        cs      = contract.score
        color   = contract.side.rich_color
        label   = contract.side.label
        spot     = self.S
        pct_to_be = abs(g.breakeven - spot) / spot * 100 if spot > 0 else 0.0
        be_color = "green" if pct_to_be < 3.0 else ("yellow" if pct_to_be < 7.0 else "red")
        lines = []
        lines.append(
            f"[bold]Strike:[/] [{color}]₹{contract.strike:,.1f} {label}[/]  "
            f"| [bold]DTE:[/] [yellow]{contract.dte:.0f}[/]  "
            f"| [bold]IV:[/] [yellow]{g.iv*100:.1f}%[/]  "
            f"| {self._moneyness_tag(g.moneyness, contract.side)}"
        )
        lines.append("")
        lines.append(
            f"  [bold]NSE LTP:[/]    [yellow]₹{g.price_market:>9,.2f}[/]"
        )
        lines.append(
            f"  [bold]BSM Fair:[/]   [dim]₹{g.price_bsm:>9,.2f}[/]  "
            f"(Intrinsic ₹{g.intrinsic:.2f} + Extrinsic ₹{g.extrinsic:.2f})"
        )
        lines.append(
            f"  [bold]Breakeven:[/]  [{be_color}]₹{g.breakeven:>9,.2f}[/]  "
            f"[dim]({pct_to_be:+.2f}% from spot — needed at expiry to recover premium)[/]"
        )
        lines.append("")
        lines.append("[bold]── First-Order Greeks ─────────────────────────────────[/]")
        lines.append(
            f"  [cyan]Δ Delta[/]  {g.delta:>+8.4f}  [dim]₹ gain per ₹1 spot move[/]"
        )
        lines.append(
            f"  [green]Γ Gamma[/]  {g.gamma:>+8.4f}  [dim]Rate of Delta change (convexity)[/]"
        )
        lines.append(
            f"  [red]Θ Theta[/]  {g.theta:>+8.4f}  [dim]₹ lost per calendar day[/]"
        )
        lines.append(
            f"  [yellow]ν Vega[/]   {g.vega:>+8.4f}  [dim]₹ change per 1% IV move[/]"
        )
        lines.append(
            f"  [blue]ρ Rho[/]    {g.rho:>+8.4f}  [dim]₹ change per 1% rate move[/]"
        )
        lines.append("")
        lines.append("[bold]── Higher-Order Greeks ────────────────────────────────[/]")
        lines.append(
            f"  [magenta]Vanna[/]  {g.vanna:>+9.4f}  "
            f"[dim]∂Δ/∂σ — Delta shifts when IV moves (vol-spot cross)[/]"
        )
        lines.append(
            f"  [magenta]Charm[/]  {g.charm:>+9.5f}  "
            f"[dim]∂Δ/∂t — Delta bleed per day (no price move needed)[/]"
        )
        lines.append(
            f"  [magenta]Vomma[/]  {g.vomma:>+9.5f}  "
            f"[dim]∂ν/∂σ — Vega convexity (gain Vega as IV rises)[/]"
        )
        lines.append(
            f"  [magenta]Speed[/]  {g.speed:>+9.5f}  "
            f"[dim]∂Γ/∂S — Gamma curvature (how fast hedge goes stale)[/]"
        )
        lines.append("")
        lines.append("[bold]── Efficiency Ratios ──────────────────────────────────[/]")
        tdr     = g.theta_delta
        tdr_col = "green" if tdr < 0.10 else ("yellow" if tdr < 0.20 else "red")
        tdr_str = f"[{tdr_col}]{tdr:.4f}[/]" if math.isfinite(tdr) else "[dim]∞[/]"
        lines.append(
            f"  Θ/Δ Ratio: {tdr_str}  "
            f"[dim](target < 0.10 — daily decay per ₹1 of Delta)[/]"
        )
        lines.append("")
        lines.append(
            f"[bold]Quant Score:[/] "
            f"{self._score_bar(cs.score)}  "
            f"[bold]{cs.score}/100[/]  →  {cs.verdict}"
        )
        if cs.reasons:
            lines.append("")
            lines.append("[green]✓ Positive Factors:[/]")
            for r in cs.reasons:
                lines.append(f"   {r}")
        if cs.warnings:
            lines.append("")
            lines.append("[red]⚠ Risk Warnings:[/]")
            for w in cs.warnings:
                lines.append(f"   {w}")
        console.print(Panel(
            "\n".join(lines),
            title=f"[bold cyan]🏆 TOP RECOMMENDED {label}[/]",
            border_style="cyan",
            padding=(0, 2),
        ))
    def _print_header(self) -> None:
        from rich.console import Console
        from rich.panel import Panel
        console = Console()
        text = (
            f"[bold white on blue] MODULE 70 — LIVE NSE OPTIONS CHAIN & GREEKS ORACLE [/]\n"
            f"[bold]Ticker:[/] [cyan]{self.raw_ticker}[/]  "
            f"[dim](NSE: {self.nse_symbol})[/]   "
            f"[bold]Spot:[/] [yellow]₹{self.S:,.2f}[/]   "
            f"[bold]HVol:[/] {self.hist_vol*100:.1f}%   "
            f"[bold]r=[/]{self.r*100:.1f}%"
        )
        console.print(Panel(text, border_style="blue", padding=(0, 1)))
    def interactive_menu(self) -> None:
        from rich.console import Console
        from rich.prompt import Prompt
        if not self._ensure_dependencies():
            return
        console = Console()
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            if not self._fetch_spot():
                console.print(
                    "\n  [bold red][!] Cannot fetch market data. "
                    "Check ticker or internet connection.[/]"
                )
            else:
                self._print_header()
                if self.process_options_chain():
                    self._print_chain_table(self._calls, OptionSide.CALL)
                    self._print_chain_table(self._puts,  OptionSide.PUT)
                    if self._calls:
                        self._print_top_candidate(self._calls[0])
                    if self._puts:
                        self._print_top_candidate(self._puts[0])
                    bc, bcs, bp, bps = IntradayScanner.find_best_intraday(
                        calls   = self._calls,
                        puts    = self._puts,
                        symbol  = self.nse_symbol,
                        spot    = self.S,
                        iv      = (self._calls[0].greeks.iv
                                   if self._calls else self.hist_vol),
                    )
                    IntradayScanner.render(bc, bcs, bp, bps, self.S)
                else:
                    console.print(
                        "\n  [bold red][!] Could not retrieve live NSE data "
                        f"for '{self.nse_symbol}'.\n"
                        "  [yellow]Verify the symbol is in NSE's F&O segment.\n"
                        "  Examples: ITC.NS · RELIANCE.NS · ^NSEI · ^NSEBANK[/]"
                    )
            console.print(
                "\n[bold cyan]R[/]=Refresh  "
                "[bold cyan]T[/]=Change Ticker  "
                "[bold cyan]A[/]=AI Co-Pilot  "
                "[bold cyan]S[/]=Strategy Advisor  "
                "[bold cyan]0[/]=Exit"
            )
            choice = Prompt.ask("Select").strip().upper()
            if choice == '0':
                break
            elif choice == 'T':
                new_t = Prompt.ask(
                    "Enter ticker (e.g. RELIANCE.NS, BANKNIFTY)"
                ).strip().upper()
                if new_t:
                    self.raw_ticker   = new_t
                    self.nse_symbol   = self._normalise_symbol(new_t)
                    self._calls       = []
                    self._puts        = []
            elif choice == 'A':
                if self._calls or self._puts:
                    _bc, _bcs, _bp, _bps = IntradayScanner.find_best_intraday(
                        calls  = self._calls,
                        puts   = self._puts,
                        symbol = self.nse_symbol,
                        spot   = self.S,
                        iv     = (
                            self._calls[0].greeks.iv
                            if self._calls else self.hist_vol
                        ),
                    )
                    run_m70_chat(
                        oracle = self,
                        calls  = self._calls,
                        puts   = self._puts,
                        bc     = _bc,
                        bcs    = _bcs,
                        bp     = _bp,
                        bps    = _bps,
                    )
                else:
                    console.print(
                        "[bold red][!] No chain data available. "
                        "Press R to refresh first.[/]"
                    )
            elif choice == 'S':
                if self._calls or self._puts:
                    StrategyAdvisor.run(self, self._calls, self._puts)
                else:
                    console.print("[bold red][!] No Chain data. Press R to refresh first.[/]")
            elif choice == 'R':
                continue
            else:
                console.print("[bold red][!] Invalid selection.[/]")
                time.sleep(1)
import math as _math
import numpy as _np
import json as _json
import re as _re
@dataclass
class StrategyLeg:
    option_type : OptionSide
    strike      : float
    action      : str                           
    qty         : int = 1
    premium     : float = 0.0
    delta       : float = 0.0
    @property
    def net_cost(self) -> float:
        return self.premium * (1 if self.action == 'buy' else -1) * self.qty
    def payoff_at_expiry(self, spot_T: float) -> float:
        if self.option_type == OptionSide.CALL:
            intrinsic = max(spot_T - self.strike, 0.0)
        else:
            intrinsic = max(self.strike - spot_T, 0.0)
        per_unit = intrinsic - self.premium if self.action == 'buy' else self.premium - intrinsic
        return per_unit * self.qty
@dataclass
class StrategyResult:
    name                : str
    category            : str                                                   
    description         : str
    legs                : List[StrategyLeg]
    bias_suited_for     : str                                          
    max_profit          : float                
    max_loss            : float                                  
    breakevens          : List[float]
    net_premium         : float                                       
    probability_profit  : float                                               
    risk_reward         : float                              
    score               : float            
    score_reasons       : List[str] = field(default_factory=list)
    score_warnings      : List[str] = field(default_factory=list)
    max_profit_unlimited: bool = False
    max_loss_unlimited  : bool = False
    lot_size            : int  = 1
    @property
    def net_debit_credit(self) -> str:
        if self.net_premium > 0.01:
            return f"Debit  ₹{self.net_premium:,.2f}"
        elif self.net_premium < -0.01:
            return f"Credit ₹{abs(self.net_premium):,.2f}"
        return "Zero Cost"
    @property
    def max_profit_str(self) -> str:
        return "Unlimited" if self.max_profit_unlimited else f"₹{self.max_profit:,.0f}"
    @property
    def max_loss_str(self) -> str:
        return "Unlimited" if self.max_loss_unlimited else f"₹{abs(self.max_loss):,.0f}"
@dataclass
class MarketBias:
    bias_score          : float
    vol_score           : float
    avg_iv_pct          : float
    iv_regime           : str
    momentum_5d_pct     : float
    price_vs_ma20_pct   : float
    price_vs_ma50_pct   : float
    vol_expanding       : bool
    trend_label         : str
    approach            : str
class MarketBiasDetector:
    @classmethod
    def detect(
        cls,
        oracle : 'OptionsChainOracle',
        calls  : List[AnalysedContract],
        puts   : List[AnalysedContract],
    ) -> MarketBias:
        import yfinance as _yf
        all_iv = (
            [c.greeks.iv for c in calls if c.greeks.iv > 0.01] +
            [p.greeks.iv for p in puts  if p.greeks.iv > 0.01]
        )
        avg_iv = float(_np.mean(all_iv)) if all_iv else oracle.hist_vol
        avg_iv_pct = avg_iv * 100.0
        if   avg_iv_pct < 20: iv_regime = 'Low'
        elif avg_iv_pct < 35: iv_regime = 'Normal'
        elif avg_iv_pct < 50: iv_regime = 'Elevated'
        else:                  iv_regime = 'Extreme'
        mom_5d = 0.0; pct_ma20 = 0.0; pct_ma50 = 0.0; vol_exp = False
        try:
            hist = _yf.Ticker(oracle.raw_ticker).history(period='3mo')
            if len(hist) >= 20:
                cl = hist['Close'].values
                ma20 = cl[-20:].mean()
                pct_ma20 = (cl[-1] - ma20) / ma20 * 100
                if len(cl) >= 50:
                    ma50 = cl[-50:].mean()
                    pct_ma50 = (cl[-1] - ma50) / ma50 * 100
                if len(cl) >= 6:
                    mom_5d = (cl[-1] - cl[-6]) / cl[-6] * 100
                if len(cl) >= 31:
                    rv_rec = float(_np.std(_np.diff(_np.log(cl[-11:]))) * _np.sqrt(252) * 100)
                    rv_old = float(_np.std(_np.diff(_np.log(cl[-31:-11]))) * _np.sqrt(252) * 100)
                    vol_exp = rv_rec > rv_old * 1.15
        except Exception:
            pass
        raw = pct_ma20 * 2.5 + pct_ma50 * 1.5 + mom_5d * 4.0
        bias = max(-100.0, min(100.0, raw))
        if   bias >  55: label = 'Strong Bullish'
        elif bias >  20: label = 'Mild Bullish'
        elif bias > -20: label = 'Neutral / Range-bound'
        elif bias > -55: label = 'Mild Bearish'
        else:            label = 'Strong Bearish'
        if vol_exp and avg_iv_pct > 25:
            label += ' (Volatility Expanding)'
        if iv_regime == 'Low':
            approach = 'Buy Premium — options are cheap; directional buyers favoured'
        elif iv_regime in ('Elevated', 'Extreme'):
            approach = 'Sell Premium / Spreads — high IV makes buying expensive'
        else:
            approach = 'Spreads — balanced premium environment; limit directional cost'
        return MarketBias(
            bias_score=round(bias, 1),
            vol_score=round(min(avg_iv_pct, 100), 1),
            avg_iv_pct=round(avg_iv_pct, 2),
            iv_regime=iv_regime,
            momentum_5d_pct=round(mom_5d, 2),
            price_vs_ma20_pct=round(pct_ma20, 2),
            price_vs_ma50_pct=round(pct_ma50, 2),
            vol_expanding=vol_exp,
            trend_label=label,
            approach=approach,
        )
class StrategyEngine:
    _SCAN_WIDTH  = 0.30                                
    _SCAN_POINTS = 300
    @staticmethod
    def _premium(c: AnalysedContract) -> float:
        p = c.greeks.price_market
        return p if p > 0.05 else c.greeks.price_bsm
    @staticmethod
    def _nearest(pool: List[AnalysedContract], target_strike: float) -> Optional[AnalysedContract]:
        if not pool:
            return None
        return min(pool, key=lambda c: abs(c.strike - target_strike))
    @staticmethod
    def _by_delta(pool: List[AnalysedContract], target_abs_delta: float) -> Optional[AnalysedContract]:
        if not pool:
            return None
        return min(pool, key=lambda c: abs(abs(c.greeks.delta) - target_abs_delta))
    @classmethod
    def _atm(cls, pool: List[AnalysedContract], spot: float) -> Optional[AnalysedContract]:
        return cls._nearest(pool, spot)
    @classmethod
    def _analyse_payoff(
        cls,
        legs    : List[StrategyLeg],
        spot    : float,
        lot_size: int,
    ) -> dict:
        lo  = spot * (1 - cls._SCAN_WIDTH)
        hi  = spot * (1 + cls._SCAN_WIDTH)
        sps = _np.linspace(lo, hi, cls._SCAN_POINTS)
        payoffs = _np.zeros(cls._SCAN_POINTS)
        for leg in legs:
            for i, s in enumerate(sps):
                payoffs[i] += leg.payoff_at_expiry(s) * lot_size
        max_p = float(payoffs.max())
        max_l = float(payoffs.min())
        bes = []
        for i in range(len(payoffs) - 1):
            if payoffs[i] * payoffs[i + 1] <= 0 and payoffs[i] != payoffs[i + 1]:
                frac = -payoffs[i] / (payoffs[i + 1] - payoffs[i])
                be = sps[i] + frac * (sps[i + 1] - sps[i])
                if lo < be < hi:
                    bes.append(round(float(be), 2))
        merged = []
        for be in sorted(bes):
            if not merged or abs(be - merged[-1]) > spot * 0.002:
                merged.append(be)
        pop = float(_np.sum(payoffs > 0) / cls._SCAN_POINTS)
        rr = (abs(max_p) / max(abs(max_l), 0.01)) if max_l < 0 else float('inf')
        return dict(max_profit=max_p, max_loss=max_l,
                    breakevens=merged, prob_profit=pop, risk_reward=rr)
    @staticmethod
    def _score(
        base        : float,
        bias        : MarketBias,
        pa          : dict,
        net_premium : float,
        spot        : float,
        dte         : float,
        iv_good_low : bool,                                           
        iv_good_high: bool,                                            
    ) -> Tuple[float, List[str], List[str]]:
        score  = base
        rsns : List[str] = []
        warns: List[str] = []
        if iv_good_low and bias.iv_regime == 'Low':
            score += 15
            rsns.append(f"IV {bias.avg_iv_pct:.1f}% (Low) — cheap premium suits this buying strategy")
        elif iv_good_high and bias.iv_regime in ('Elevated', 'Extreme'):
            score += 15
            rsns.append(f"IV {bias.avg_iv_pct:.1f}% ({bias.iv_regime}) — expensive premium suits selling")
        elif iv_good_low and bias.iv_regime in ('Elevated', 'Extreme'):
            score -= 20
            warns.append(f"IV {bias.avg_iv_pct:.1f}% ({bias.iv_regime}) — premium is expensive for buyers")
        elif iv_good_high and bias.iv_regime == 'Low':
            score -= 15
            warns.append(f"IV {bias.avg_iv_pct:.1f}% (Low) — low premium reduces seller income")
        rr = pa['risk_reward']
        if rr != float('inf') and rr > 2.0:
            score += 10; rsns.append(f"Favourable R/R {rr:.1f}:1")
        elif rr < 0.5:
            score -= 10; warns.append(f"Poor R/R {rr:.1f}:1")
        pop = pa['prob_profit']
        if pop >= 0.65:
            score += 10; rsns.append(f"High P(profit) ≈ {pop*100:.0f}% of price range")
        elif pop < 0.40:
            score -= 10; warns.append(f"Low P(profit) ≈ {pop*100:.0f}% of price range")
        if dte < 7:
            score -= 20; warns.append(f"< 7 DTE — gamma trap; theta decimates premium daily")
        elif dte < 14:
            score -= 10; warns.append(f"{dte:.0f} DTE — accelerating decay, need quick move")
        elif dte >= 30:
            score += 5; rsns.append(f"{dte:.0f} DTE — adequate time for thesis to develop")
        bes = pa['breakevens']
        if bes:
            nearest_be = min(abs(be - spot) / spot * 100 for be in bes)
            if nearest_be > 10:
                score -= 15; warns.append(f"Breakeven requires {nearest_be:.1f}% spot move")
            elif nearest_be < 3:
                score += 8; rsns.append(f"Tight breakeven only {nearest_be:.1f}% from spot")
        pct_of_spot = abs(net_premium) / spot * 100
        if pct_of_spot > 5:
            score -= 10; warns.append(f"High premium cost {pct_of_spot:.1f}% of spot")
        elif pct_of_spot < 1.5 and net_premium > 0:
            score += 5; rsns.append(f"Low debit {pct_of_spot:.1f}% of spot")
        return max(0.0, min(100.0, score)), rsns, warns
    @classmethod
    def _long_call(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        c = cls._by_delta(calls, 0.45)
        if not c: return None
        p = cls._premium(c)
        legs = [StrategyLeg(OptionSide.CALL, c.strike, 'buy', 1, p, c.greeks.delta)]
        pa   = cls._analyse_payoff(legs, spot, lot)
        base = 75 if 'Bullish' in bias.trend_label else 45 if 'Bear' in bias.trend_label else 55
        score, rsns, warns = cls._score(base, bias, pa, p, spot, dte, True, False)
        rsns.insert(0, "Simple directional bet — max loss capped at premium paid")
        return StrategyResult(
            name='Long Call', category='Debit', bias_suited_for='Bullish',
            description='Buy 1 call near ATM. Profit if spot rises above breakeven. Loss capped at premium.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=p,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            max_profit_unlimited=True, lot_size=lot,
        )
    @classmethod
    def _long_put(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        p_c = cls._by_delta(puts, 0.45)
        if not p_c: return None
        p = cls._premium(p_c)
        legs = [StrategyLeg(OptionSide.PUT, p_c.strike, 'buy', 1, p, p_c.greeks.delta)]
        pa   = cls._analyse_payoff(legs, spot, lot)
        base = 75 if 'Bear' in bias.trend_label else 45 if 'Bull' in bias.trend_label else 55
        score, rsns, warns = cls._score(base, bias, pa, p, spot, dte, True, False)
        rsns.insert(0, "Simple directional hedge — profits if stock falls sharply")
        return StrategyResult(
            name='Long Put', category='Debit', bias_suited_for='Bearish',
            description='Buy 1 put near ATM. Profit if spot falls below breakeven. Loss capped at premium.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=p,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def _bull_call_spread(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        lower = cls._by_delta(calls, 0.50)
        upper = cls._by_delta(calls, 0.25)
        if not lower or not upper or lower.strike >= upper.strike: return None
        p_l = cls._premium(lower); p_u = cls._premium(upper)
        net  = p_l - p_u
        legs = [
            StrategyLeg(OptionSide.CALL, lower.strike, 'buy',  1, p_l, lower.greeks.delta),
            StrategyLeg(OptionSide.CALL, upper.strike, 'sell', 1, p_u, upper.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 80 if 'Bullish' in bias.trend_label else 40 if 'Bear' in bias.trend_label else 55
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, True, False)
        rsns.insert(0, f"Capped upside ₹{(upper.strike - lower.strike - net)*lot:,.0f} but reduced cost vs long call")
        return StrategyResult(
            name='Bull Call Spread', category='Debit', bias_suited_for='Mild Bullish',
            description=f'Buy ₹{lower.strike:,.0f} call, Sell ₹{upper.strike:,.0f} call. Profit between strikes.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def _bear_put_spread(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        upper = cls._by_delta(puts, 0.50)
        lower = cls._by_delta(puts, 0.25)
        if not upper or not lower or upper.strike <= lower.strike: return None
        p_u = cls._premium(upper); p_l = cls._premium(lower)
        net  = p_u - p_l
        legs = [
            StrategyLeg(OptionSide.PUT, upper.strike, 'buy',  1, p_u, upper.greeks.delta),
            StrategyLeg(OptionSide.PUT, lower.strike, 'sell', 1, p_l, lower.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 80 if 'Bear' in bias.trend_label else 40 if 'Bull' in bias.trend_label else 55
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, True, False)
        rsns.insert(0, "Defined risk bearish strategy — lower cost than long put")
        return StrategyResult(
            name='Bear Put Spread', category='Debit', bias_suited_for='Mild Bearish',
            description=f'Buy ₹{upper.strike:,.0f} put, Sell ₹{lower.strike:,.0f} put. Profit on downside.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def _bull_put_spread(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        short_p = cls._by_delta(puts, 0.40)
        long_p  = cls._by_delta(puts, 0.20)
        if not short_p or not long_p or short_p.strike <= long_p.strike: return None
        p_s = cls._premium(short_p); p_l = cls._premium(long_p)
        credit = p_s - p_l
        legs = [
            StrategyLeg(OptionSide.PUT, short_p.strike, 'sell', 1, p_s, short_p.greeks.delta),
            StrategyLeg(OptionSide.PUT, long_p.strike,  'buy',  1, p_l, long_p.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 75 if 'Bullish' in bias.trend_label else 40 if 'Bear' in bias.trend_label else 60
        score, rsns, warns = cls._score(base, bias, pa, -credit, spot, dte, False, True)
        rsns.insert(0, f"Collect ₹{credit*lot:,.0f}/lot credit upfront — keep if spot stays above ₹{short_p.strike:,.0f}")
        return StrategyResult(
            name='Bull Put Spread', category='Credit', bias_suited_for='Mild Bullish (Credit)',
            description=f'Sell ₹{short_p.strike:,.0f} put, Buy ₹{long_p.strike:,.0f} put. Keep credit if market holds.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=-credit,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def _bear_call_spread(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        short_c = cls._by_delta(calls, 0.40)
        long_c  = cls._by_delta(calls, 0.20)
        if not short_c or not long_c or short_c.strike >= long_c.strike: return None
        p_s = cls._premium(short_c); p_l = cls._premium(long_c)
        credit = p_s - p_l
        legs = [
            StrategyLeg(OptionSide.CALL, short_c.strike, 'sell', 1, p_s, short_c.greeks.delta),
            StrategyLeg(OptionSide.CALL, long_c.strike,  'buy',  1, p_l, long_c.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 75 if 'Bear' in bias.trend_label else 40 if 'Bull' in bias.trend_label else 55
        score, rsns, warns = cls._score(base, bias, pa, -credit, spot, dte, False, True)
        rsns.insert(0, f"Collect ₹{credit*lot:,.0f}/lot credit — keep if stock stays below ₹{short_c.strike:,.0f}")
        return StrategyResult(
            name='Bear Call Spread', category='Credit', bias_suited_for='Mild Bearish (Credit)',
            description=f'Sell ₹{short_c.strike:,.0f} call, Buy ₹{long_c.strike:,.0f} call. Profit if market stays flat/down.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=-credit,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def _long_straddle(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        c_atm = cls._atm(calls, spot)
        p_atm = cls._atm(puts,  spot)
        if not c_atm or not p_atm: return None
        pc = cls._premium(c_atm); pp = cls._premium(p_atm)
        net  = pc + pp
        legs = [
            StrategyLeg(OptionSide.CALL, c_atm.strike, 'buy', 1, pc, c_atm.greeks.delta),
            StrategyLeg(OptionSide.PUT,  p_atm.strike, 'buy', 1, pp, p_atm.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 80 if bias.vol_expanding or bias.iv_regime == 'Low' else 45
        if 'Neutral' in bias.trend_label and not bias.vol_expanding: base = 35
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, True, False)
        rsns.insert(0, "Profits from BIG move in EITHER direction — direction-agnostic")
        if bias.iv_regime in ('Elevated', 'Extreme'):
            warns.insert(0, f"HIGH IV {bias.avg_iv_pct:.1f}% — IV crush risk post-event can erode both legs")
        return StrategyResult(
            name='Long Straddle', category='Volatility', bias_suited_for='Volatile / Pre-catalyst',
            description=f'Buy ₹{c_atm.strike:,.0f} Call + ₹{p_atm.strike:,.0f} Put. Profits on big move either direction.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            max_profit_unlimited=True, lot_size=lot,
        )
    @classmethod
    def _long_strangle(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        c_otm = cls._by_delta(calls, 0.30)
        p_otm = cls._by_delta(puts,  0.30)
        if not c_otm or not p_otm: return None
        pc = cls._premium(c_otm); pp = cls._premium(p_otm)
        net  = pc + pp
        legs = [
            StrategyLeg(OptionSide.CALL, c_otm.strike, 'buy', 1, pc, c_otm.greeks.delta),
            StrategyLeg(OptionSide.PUT,  p_otm.strike, 'buy', 1, pp, p_otm.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 70 if bias.vol_expanding else (55 if bias.iv_regime == 'Low' else 35)
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, True, False)
        rsns.insert(0, "Lower cost than straddle — needs bigger move but maximum loss is smaller")
        return StrategyResult(
            name='Long Strangle', category='Volatility', bias_suited_for='High Volatility Expected',
            description=f'Buy OTM Call ₹{c_otm.strike:,.0f} + OTM Put ₹{p_otm.strike:,.0f}. Cheaper than straddle.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            max_profit_unlimited=True, lot_size=lot,
        )
    @classmethod
    def _short_straddle(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        c_atm = cls._atm(calls, spot)
        p_atm = cls._atm(puts,  spot)
        if not c_atm or not p_atm: return None
        pc = cls._premium(c_atm); pp = cls._premium(p_atm)
        credit = pc + pp
        legs = [
            StrategyLeg(OptionSide.CALL, c_atm.strike, 'sell', 1, pc, c_atm.greeks.delta),
            StrategyLeg(OptionSide.PUT,  p_atm.strike, 'sell', 1, pp, p_atm.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 75 if ('Neutral' in bias.trend_label and bias.iv_regime in ('Elevated','Extreme')) else 30
        score, rsns, warns = cls._score(base, bias, pa, -credit, spot, dte, False, True)
        rsns.insert(0, f"Collect ₹{credit*lot:,.0f}/lot — keep ALL if spot stays at ₹{c_atm.strike:,.0f}")
        warns.append("UNLIMITED LOSS if large move — suitable for hedged/experienced traders only")
        return StrategyResult(
            name='Short Straddle', category='Credit', bias_suited_for='Range-bound / High IV',
            description=f'Sell ₹{c_atm.strike:,.0f} Call + Put. Profit from time decay if spot stays near strike.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=-credit,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            max_loss_unlimited=True, lot_size=lot,
        )
    @classmethod
    def _short_strangle(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        c_otm = cls._by_delta(calls, 0.25)
        p_otm = cls._by_delta(puts,  0.25)
        if not c_otm or not p_otm: return None
        pc = cls._premium(c_otm); pp = cls._premium(p_otm)
        credit = pc + pp
        legs = [
            StrategyLeg(OptionSide.CALL, c_otm.strike, 'sell', 1, pc, c_otm.greeks.delta),
            StrategyLeg(OptionSide.PUT,  p_otm.strike, 'sell', 1, pp, p_otm.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 72 if ('Neutral' in bias.trend_label and bias.iv_regime in ('Elevated','Extreme')) else 30
        score, rsns, warns = cls._score(base, bias, pa, -credit, spot, dte, False, True)
        rsns.insert(0, "Wider profit zone than short straddle — profit if spot stays between strikes")
        warns.append("UNLIMITED LOSS beyond either sold strike — use only with hedges/experience")
        return StrategyResult(
            name='Short Strangle', category='Credit', bias_suited_for='Range-bound / Extreme IV',
            description=f'Sell OTM Call ₹{c_otm.strike:,.0f} + OTM Put ₹{p_otm.strike:,.0f}. Range profit strategy.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=-credit,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            max_loss_unlimited=True, lot_size=lot,
        )
    @classmethod
    def _long_butterfly(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        lower  = cls._by_delta(calls, 0.35)
        middle = cls._atm(calls, spot)
        upper  = cls._by_delta(calls, 0.20)
        if not lower or not middle or not upper: return None
        if not (lower.strike < middle.strike < upper.strike): return None
        p_l = cls._premium(lower); p_m = cls._premium(middle); p_u = cls._premium(upper)
        net = p_l + p_u - 2 * p_m                          
        legs = [
            StrategyLeg(OptionSide.CALL, lower.strike,  'buy',  1, p_l, lower.greeks.delta),
            StrategyLeg(OptionSide.CALL, middle.strike, 'sell', 2, p_m, middle.greeks.delta),
            StrategyLeg(OptionSide.CALL, upper.strike,  'buy',  1, p_u, upper.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 82 if 'Neutral' in bias.trend_label else 40
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, False, True)
        rsns.insert(0, f"Best range strategy — defined risk, max profit ₹{pa['max_profit']:,.0f} if stock pins at ₹{middle.strike:,.0f}")
        return StrategyResult(
            name='Long Butterfly', category='Neutral', bias_suited_for='Strongly Neutral (Pin at ATM)',
            description=f'Buy ₹{lower.strike:,.0f}+₹{upper.strike:,.0f} calls, Sell 2×₹{middle.strike:,.0f} call. Max profit at middle strike.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def _iron_condor(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        sc = cls._by_delta(calls, 0.25)                       
        lc = cls._by_delta(calls, 0.15)                      
        sp = cls._by_delta(puts,  0.25)                      
        lp = cls._by_delta(puts,  0.15)                     
        if not all([sc, lc, sp, lp]): return None
        if sc.strike >= lc.strike or sp.strike <= lp.strike: return None
        p_sc = cls._premium(sc); p_lc = cls._premium(lc)
        p_sp = cls._premium(sp); p_lp = cls._premium(lp)
        credit = (p_sc - p_lc) + (p_sp - p_lp)
        if credit <= 0: return None
        legs = [
            StrategyLeg(OptionSide.CALL, lc.strike, 'buy',  1, p_lc, lc.greeks.delta),
            StrategyLeg(OptionSide.CALL, sc.strike, 'sell', 1, p_sc, sc.greeks.delta),
            StrategyLeg(OptionSide.PUT,  sp.strike, 'sell', 1, p_sp, sp.greeks.delta),
            StrategyLeg(OptionSide.PUT,  lp.strike, 'buy',  1, p_lp, lp.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 85 if ('Neutral' in bias.trend_label and bias.iv_regime in ('Normal','Elevated','Extreme')) else 40
        score, rsns, warns = cls._score(base, bias, pa, -credit, spot, dte, False, True)
        rsns.insert(0, f"4-leg income strategy — profit ₹{credit*lot:,.0f}/lot as long as spot stays "
                    f"between ₹{sp.strike:,.0f}–₹{sc.strike:,.0f}")
        return StrategyResult(
            name='Iron Condor', category='Credit', bias_suited_for='Neutral / Range-bound (Income)',
            description=(f'Sell ₹{sp.strike:,.0f}P+₹{sc.strike:,.0f}C, Buy ₹{lp.strike:,.0f}P+₹{lc.strike:,.0f}C. '
                         f'Profit in range ₹{sp.strike:,.0f}–₹{sc.strike:,.0f}.'),
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=-credit,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def _married_put(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        stock_leg = cls._by_delta(calls, 0.80)                          
        put_ins   = cls._atm(puts, spot)                               
        if not stock_leg or not put_ins: return None
        p_s = cls._premium(stock_leg); p_p = cls._premium(put_ins)
        net  = p_s + p_p
        legs = [
            StrategyLeg(OptionSide.CALL, stock_leg.strike, 'buy', 1, p_s, stock_leg.greeks.delta),
            StrategyLeg(OptionSide.PUT,  put_ins.strike,   'buy', 1, p_p, put_ins.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 72 if 'Bullish' in bias.trend_label else 45
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, True, False)
        rsns.insert(0, f"Built-in floor at ₹{put_ins.strike:,.0f} — unlimited upside, capped downside loss = put premium only")
        return StrategyResult(
            name='Married Put', category='Debit', bias_suited_for='Bullish with Downside Protection',
            description=f'Deep ITM Call ≈ stock + ATM Put insurance. Profit if up, protected if down.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            max_profit_unlimited=True, lot_size=lot,
        )
    @classmethod
    def _call_backspread(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        short_c = cls._by_delta(calls, 0.55)                  
        long_c  = cls._by_delta(calls, 0.30)               
        if not short_c or not long_c or short_c.strike >= long_c.strike: return None
        p_s = cls._premium(short_c); p_l = cls._premium(long_c)
        net  = 2 * p_l - p_s                                
        legs = [
            StrategyLeg(OptionSide.CALL, short_c.strike, 'sell', 1, p_s, short_c.greeks.delta),
            StrategyLeg(OptionSide.CALL, long_c.strike,  'buy',  2, p_l, long_c.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 70 if 'Bullish' in bias.trend_label and bias.iv_regime in ('Low','Normal') else 40
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, True, False)
        rsns.insert(0, "Explosive upside play — gains accelerate beyond long strike, small defined max loss")
        return StrategyResult(
            name='Call Backspread', category='Volatility', bias_suited_for='Strongly Bullish / Big Move Up',
            description=f'Sell 1×₹{short_c.strike:,.0f} call, Buy 2×₹{long_c.strike:,.0f} calls. Benefits from explosive upside.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            max_profit_unlimited=True, lot_size=lot,
        )
    @classmethod
    def _put_backspread(cls, calls, puts, spot, dte, lot, bias) -> Optional[StrategyResult]:
        short_p = cls._by_delta(puts, 0.55)
        long_p  = cls._by_delta(puts, 0.30)
        if not short_p or not long_p or short_p.strike <= long_p.strike: return None
        p_s = cls._premium(short_p); p_l = cls._premium(long_p)
        net  = 2 * p_l - p_s
        legs = [
            StrategyLeg(OptionSide.PUT, short_p.strike, 'sell', 1, p_s, short_p.greeks.delta),
            StrategyLeg(OptionSide.PUT, long_p.strike,  'buy',  2, p_l, long_p.greeks.delta),
        ]
        pa = cls._analyse_payoff(legs, spot, lot)
        base = 70 if 'Bear' in bias.trend_label and bias.iv_regime in ('Low','Normal') else 40
        score, rsns, warns = cls._score(base, bias, pa, net, spot, dte, True, False)
        rsns.insert(0, "Explosive downside play — gains accelerate on crash, defined max loss")
        return StrategyResult(
            name='Put Backspread', category='Volatility', bias_suited_for='Strongly Bearish / Big Move Down',
            description=f'Sell 1×₹{short_p.strike:,.0f} put, Buy 2×₹{long_p.strike:,.0f} puts. Big crash profits.',
            legs=legs, max_profit=pa['max_profit'], max_loss=pa['max_loss'],
            breakevens=pa['breakevens'], net_premium=net,
            probability_profit=pa['prob_profit'], risk_reward=pa['risk_reward'],
            score=score, score_reasons=rsns, score_warnings=warns,
            lot_size=lot,
        )
    @classmethod
    def build_all(
        cls,
        oracle : 'OptionsChainOracle',
        calls  : List[AnalysedContract],
        puts   : List[AnalysedContract],
        bias   : MarketBias,
    ) -> List[StrategyResult]:
        lot  = IntradayScanner._get_lot_size(oracle.nse_symbol)
        dte  = oracle.dte
        spot = oracle.S
        builders = [
            cls._long_call, cls._long_put, cls._bull_call_spread,
            cls._bear_put_spread, cls._bull_put_spread, cls._bear_call_spread,
            cls._long_straddle, cls._long_strangle, cls._short_straddle,
            cls._short_strangle, cls._long_butterfly, cls._iron_condor,
            cls._married_put, cls._call_backspread, cls._put_backspread,
        ]
        results: List[StrategyResult] = []
        for fn in builders:
            try:
                r = fn(calls, puts, spot, dte, lot, bias)
                if r is not None:
                    results.append(r)
            except Exception:
                pass
        results.sort(key=lambda r: r.score, reverse=True)
        for r in results[:3]:
            r.score_reasons.insert(0, "★ TOP-3 RECOMMENDATION for current market conditions")
        return results
class StrategyAdvisor:
    @staticmethod
    def _ascii_payoff(
        legs    : List[StrategyLeg],
        spot    : float,
        lot_size: int,
        width   : int = 58,
        height  : int = 11,
    ) -> str:
        lo = spot * 0.78; hi = spot * 1.22
        sps = _np.linspace(lo, hi, 200)
        pnl = _np.zeros(200)
        for leg in legs:
            for i, s in enumerate(sps):
                pnl[i] += leg.payoff_at_expiry(s) * lot_size
        max_p = max(float(pnl.max()),  0.01)
        min_p = min(float(pnl.min()), -0.01)
        p_rng = max_p - min_p
        def _row(v):
            return max(0, min(height-1, int((max_p - v) / p_rng * (height-1))))
        zero_row = _row(0)
        grid = [[' '] * width for _ in range(height)]
        for col in range(width):
            grid[zero_row][col] = '─'
        for i, v in enumerate(pnl):
            col = int(i / 199 * (width - 1))
            row = _row(float(v))
            row = max(0, min(height-1, row))
            grid[row][col] = '█' if v >= 0 else '▒'
        lines = []
        for r in range(height):
            if r == 0:
                lbl = f"₹{max_p/lot_size:>+9.0f} │"
            elif r == zero_row:
                lbl = f"₹{'0':>9} ┼"
            elif r == height - 1:
                lbl = f"₹{min_p/lot_size:>+9.0f} │"
            else:
                lbl = f"{'':>10} │"
            row_str = ''.join(grid[r])
            lines.append(f"  {lbl}{row_str}")
        x_axis = (f"  {'':>11}  "
                  f"₹{lo:,.0f}{' '*((width//3)-8)}"
                  f"₹{spot:,.0f} (SPOT){' '*((width//3)-12)}"
                  f"₹{hi:,.0f}")
        lines.append(x_axis)
        lines.append(f"  {'':>11}  {'█ = Profit':12}  {'▒ = Loss':10}  {'─ = Zero':10}")
        return '\n'.join(lines)
    @staticmethod
    def _render_bias_panel(bias: MarketBias, console) -> None:
        from rich.panel import Panel
        from rich.table import Table
        from rich import box
        bc = ("bold green" if bias.bias_score > 30 else
              "bold red"   if bias.bias_score < -30 else "bold yellow")
        ic = ("green" if bias.iv_regime == 'Low' else
              "red"   if bias.iv_regime in ('Elevated','Extreme') else "yellow")
        tbl = Table(box=box.SIMPLE, show_header=False, padding=(0,1))
        tbl.add_column("", style="bold dim", width=22)
        tbl.add_column("", width=40)
        tbl.add_row("Market Trend",
                    f"[{bc}]{bias.trend_label}[/]  (bias {bias.bias_score:+.0f}/100)")
        tbl.add_row("IV Regime",
                    f"[{ic}]{bias.iv_regime}[/]  avg IV {bias.avg_iv_pct:.1f}%")
        tbl.add_row("5d Momentum",
                    f"{('+' if bias.momentum_5d_pct >= 0 else '')}{bias.momentum_5d_pct:.2f}%")
        tbl.add_row("Price vs MA20",
                    f"{('+' if bias.price_vs_ma20_pct >= 0 else '')}{bias.price_vs_ma20_pct:.2f}%")
        tbl.add_row("Vol Expanding",
                    f"[red]YES — regime shift in progress[/]" if bias.vol_expanding else "No")
        tbl.add_row("Recommended",
                    f"[cyan]{bias.approach}[/]")
        console.print(Panel(tbl,
                            title="[bold white]📊 MARKET BIAS — CURRENT CONDITIONS[/]",
                            border_style="blue", padding=(0,1)))
    @staticmethod
    def _render_top3_table(results: List[StrategyResult], console) -> None:
        from rich.table import Table
        from rich import box
        top3 = results[:3]
        tbl  = Table(
            title="[bold cyan]⭐ TOP-3 RECOMMENDED STRATEGIES FOR CURRENT MARKET[/]",
            box=box.ROUNDED, show_lines=True, header_style="bold cyan",
        )
        tbl.add_column("Rank",         width=5,  justify="center")
        tbl.add_column("Strategy",     width=22)
        tbl.add_column("Score",        width=8,  justify="center")
        tbl.add_column("Category",     width=12)
        tbl.add_column("Bias Suited",  width=28)
        tbl.add_column("Max Profit",   width=14, justify="right")
        tbl.add_column("Max Loss",     width=14, justify="right")
        tbl.add_column("P(Profit)",    width=10, justify="center")
        tbl.add_column("R/R",          width=8,  justify="center")
        tbl.add_column("Net Premium",  width=16, justify="right")
        medals = ["🥇", "🥈", "🥉"]
        for i, r in enumerate(top3):
            sc = r.score
            sc_col = "green" if sc >= 70 else "yellow" if sc >= 50 else "red"
            bar    = '█' * int(sc / 10) + '░' * (10 - int(sc / 10))
            rr_str = "∞" if r.risk_reward == float('inf') else f"{r.risk_reward:.1f}"
            tbl.add_row(
                medals[i],
                f"[bold]{r.name}[/]",
                f"[{sc_col}]{bar}\n{sc:.0f}/100[/]",
                r.category,
                r.bias_suited_for,
                f"[green]{r.max_profit_str}[/]",
                f"[red]{r.max_loss_str}[/]",
                f"[{'green' if r.probability_profit >= 0.55 else 'yellow'}]{r.probability_profit*100:.0f}%[/]",
                f"[{'green' if rr_str not in ('∞','') and float(rr_str.replace('∞','9')) >= 1.5 else 'yellow'}]{rr_str}[/]",
                f"[{'red' if r.net_premium > 0 else 'green'}]{r.net_debit_credit}[/]",
            )
        console.print(tbl)
    @staticmethod
    def _render_strategy_card(r: StrategyResult, rank: int, console) -> None:
        from rich.panel import Panel
        from rich.table import Table
        from rich import box
        medal_map = {1: "🥇", 2: "🥈", 3: "🥉"}
        medal = medal_map.get(rank, f"#{rank}")
        lines = []
        sc_col = "green" if r.score >= 70 else "yellow" if r.score >= 50 else "red"
        lines.append(f"[bold]{medal} {r.name}[/]  "
                     f"[{sc_col}]Score {r.score:.0f}/100[/]  "
                     f"│  [{('red' if r.net_premium > 0 else 'green')}]{r.net_debit_credit}[/]  "
                     f"│  [dim]{r.description}[/]")
        lines.append("")
        lines.append("[bold]LEGS:[/]")
        total_cost = 0.0
        for leg in r.legs:
            cost = leg.net_cost * r.lot_size
            total_cost += cost
            action_col = "green" if leg.action == 'buy' else "red"
            lines.append(
                f"  [{action_col}]{leg.action.upper():4}[/]  "
                f"{leg.qty}× ₹{leg.strike:>10,.1f} {leg.option_type.label:<4}  "
                f"Premium ₹{leg.premium:>7.2f}  "
                f"Δ {leg.delta:>+6.3f}  "
                f"Net [{action_col}]₹{cost:>+8.0f}[/] per lot"
            )
        lines.append("")
        lines.append(
            f"[bold]Max Profit:[/] [green]{r.max_profit_str}[/]  "
            f"│  [bold]Max Loss:[/] [red]{r.max_loss_str}[/]  "
            f"│  [bold]R/R:[/] {'∞' if r.risk_reward == float('inf') else f'{r.risk_reward:.2f}:1'}  "
            f"│  [bold]P(Profit):[/] {r.probability_profit*100:.0f}%"
        )
        if r.breakevens:
            be_str = "  │  ".join(f"₹{be:,.2f}" for be in r.breakevens)
            lines.append(f"[bold]Breakeven(s):[/] {be_str}")
        be_mid = r.breakevens[0] if r.breakevens else 0
        spot_est = be_mid or (r.legs[0].strike if r.legs else 100)
        try:
            ascii_chart = StrategyAdvisor._ascii_payoff(
                r.legs, spot_est * 1.03, r.lot_size                                         
            )
            lines.append("")
            lines.append("[bold]PAYOFF AT EXPIRY:[/]")
            lines.append(ascii_chart)
        except Exception:
            pass
        if r.score_reasons:
            lines.append("")
            lines.append("[green]✓ WHY THIS STRATEGY SUITS NOW:[/]")
            for reason in r.score_reasons[1:]:                                    
                lines.append(f"   {reason}")
        if r.score_warnings:
            lines.append("")
            lines.append("[red]⚠ RISK WARNINGS:[/]")
            for w in r.score_warnings:
                lines.append(f"   {w}")
        color_map = {"Debit": "cyan", "Credit": "green", "Volatility": "magenta", "Neutral": "blue"}
        border_c  = color_map.get(r.category, "white")
        console.print(Panel(
            '\n'.join(lines),
            title=f"[bold {border_c}]STRATEGY DETAIL — {r.name}[/]",
            border_style=border_c,
            padding=(0, 2),
        ))
    @staticmethod
    def _matplotlib_chart(results: List[StrategyResult], spot: float) -> None:
        import numpy as _np2
        plt.style.use('dark_background')
        top = results[:min(4, len(results))]
        if not top: return
        fig = plt.figure(figsize=(20, 12))
        fig.patch.set_facecolor('#0d1117')
        gs  = gridspec.GridSpec(2, len(top), figure=fig, hspace=0.55, wspace=0.35)
        ax_all = fig.add_subplot(gs[0, :])
        ax_all.set_facecolor('#161b22')
        ax_all.axhline(0, color='white', lw=1.0)
        ax_all.axvline(spot, color='#00d2ff', lw=1.2, ls='--',
                       label=f'Current Spot ₹{spot:,.0f}')
        ax_all.grid(alpha=0.15, color='#21262d')
        colours = ['#3fb950', '#00d2ff', '#bc8cff', '#f85149']
        lo = spot * 0.78; hi = spot * 1.22
        sps = _np2.linspace(lo, hi, 300)
        for r, col in zip(top, colours):
            lot = r.lot_size
            pnl = _np2.array([
                sum(leg.payoff_at_expiry(s) * lot for leg in r.legs)
                for s in sps
            ])
            sc_lbl = f"{r.name}  [{r.score:.0f}/100]"
            ax_all.plot(sps, pnl, color=col, lw=2.0, label=sc_lbl)
            ax_all.fill_between(sps, pnl, 0, where=(pnl >= 0),
                                alpha=0.10, color=col)
            ax_all.fill_between(sps, pnl, 0, where=(pnl < 0),
                                alpha=0.06, color='#f85149')
        ax_all.set_title(f"Options Strategy Payoff Comparison  |  {spot=}",
                         color='#e6edf3', fontsize=12, fontweight='bold')
        ax_all.set_ylabel("P&L ₹ per Lot", color='#8b949e')
        ax_all.set_xlabel("Spot at Expiry ₹", color='#8b949e')
        ax_all.tick_params(colors='#8b949e')
        ax_all.yaxis.set_major_formatter(plt.FuncFormatter(lambda x,_: f'₹{x:,.0f}'))
        ax_all.xaxis.set_major_formatter(plt.FuncFormatter(lambda x,_: f'₹{x:,.0f}'))
        ax_all.legend(fontsize=9, facecolor='#161b22', edgecolor='#21262d',
                      labelcolor='#e6edf3')
        for j, (r, col) in enumerate(zip(top, colours)):
            ax = fig.add_subplot(gs[1, j])
            ax.set_facecolor('#161b22')
            ax.grid(alpha=0.15, color='#21262d')
            ax.axhline(0, color='white', lw=0.8)
            ax.axvline(spot, color='#00d2ff', lw=1.0, ls='--', alpha=0.7)
            lot = r.lot_size
            pnl = _np2.array([
                sum(leg.payoff_at_expiry(s) * lot for leg in r.legs)
                for s in sps
            ])
            ax.plot(sps, pnl, color=col, lw=1.8)
            ax.fill_between(sps, pnl, 0, where=(pnl >= 0), alpha=0.25, color=col)
            ax.fill_between(sps, pnl, 0, where=(pnl < 0), alpha=0.20, color='#f85149')
            for be in r.breakevens:
                ax.axvline(be, color='#d29922', lw=0.9, ls=':', alpha=0.8)
                ax.text(be, ax.get_ylim()[0]*0.05, f'BE\n₹{be:,.0f}',
                        fontsize=6.5, color='#d29922', ha='center')
            sc_col = '#3fb950' if r.score >= 70 else ('#d29922' if r.score >= 50 else '#f85149')
            ax.set_title(f"{r.name}\nScore {r.score:.0f}/100  |  P(profit) {r.probability_profit*100:.0f}%",
                         color='#e6edf3', fontsize=9)
            ax.set_ylabel("₹/lot", color='#8b949e', fontsize=8)
            ax.tick_params(colors='#8b949e', labelsize=7)
            ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda x,_: f'₹{x:,.0f}'))
            ax.xaxis.set_major_formatter(plt.FuncFormatter(lambda x,_: f'₹{x:,.0f}'))
            for sp in ax.spines.values():
                sp.set_edgecolor('#21262d')
        fig.suptitle(
            f"Strategy Payoff Analysis  |  Spot ₹{spot:,.0f}  "
            f"|  Top {len(top)} Strategies Ranked by Score",
            color='#e6edf3', fontsize=13, fontweight='bold',
        )
        plt.tight_layout(rect=[0, 0, 1, 0.96])
        plt.show()
    @classmethod
    def run(
        cls,
        oracle : 'OptionsChainOracle',
        calls  : List[AnalysedContract],
        puts   : List[AnalysedContract],
    ) -> None:
        from rich.console import Console
        from rich.panel   import Panel
        from rich.prompt  import Prompt
        console = Console()
        os.system('cls' if os.name == 'nt' else 'clear')
        console.print(Panel(
            "[bold white on dark_green]  ♟  MODULE 70 — STRATEGY ADVISOR  "
            "│  Find the Best Strategy for Any Market Condition  [/]",
            border_style="green", padding=(0, 1),
        ))
        console.print(
            f"  [dim]Ticker:[/] [cyan]{oracle.raw_ticker}[/]  "
            f"[dim]Spot:[/] [yellow]₹{oracle.S:,.2f}[/]  "
            f"[dim]Expiry:[/] {oracle.selected_expiry}  "
            f"[dim]DTE:[/] {oracle.dte:.0f}\n"
        )
        console.print("  [dim]Detecting market bias...[/]", end="\r")
        bias = MarketBiasDetector.detect(oracle, calls, puts)
        cls._render_bias_panel(bias, console)
        console.print("  [dim]Building and scoring 15 strategies...[/]", end="\r")
        results = StrategyEngine.build_all(oracle, calls, puts, bias)
        if not results:
            console.print("[bold red][!] Could not build any strategies from the current chain.[/]")
            Prompt.ask("  Press ENTER to return"); return
        console.print(f"  [green][✓] Built {len(results)} strategies — ranked by score.[/]\n")
        cls._render_top3_table(results, console)
        try:
            n_str = Prompt.ask(
                "\n  Show detailed cards for top [bold]N[/] strategies "
                "[dim](1–5, ENTER=3)[/]",
                default="3"
            ).strip()
            n = max(1, min(5, int(n_str)))
        except (ValueError, KeyboardInterrupt):
            n = 3
        for i, r in enumerate(results[:n], 1):
            cls._render_strategy_card(r, i, console)
        try:
            show_all = Prompt.ask(
                "  Show [bold]ALL 15[/] strategy scores? [dim](Y/N)[/]",
                default="N"
            ).strip().upper()
        except KeyboardInterrupt:
            show_all = "N"
        if show_all == 'Y':
            from rich.table import Table
            from rich import box
            all_tbl = Table(
                title="[bold]All 15 Strategies — Ranked by Score[/]",
                box=box.SIMPLE_HEAVY, show_lines=False,
                header_style="bold dim",
            )
            all_tbl.add_column("#",          width=4,  justify="right")
            all_tbl.add_column("Strategy",   width=22)
            all_tbl.add_column("Score",      width=8,  justify="center")
            all_tbl.add_column("Category",   width=12)
            all_tbl.add_column("Max Profit", width=14, justify="right")
            all_tbl.add_column("Max Loss",   width=14, justify="right")
            all_tbl.add_column("BE Count",   width=8,  justify="center")
            all_tbl.add_column("P(Profit)",  width=10, justify="center")
            for i, r in enumerate(results, 1):
                sc = r.score
                col = "green" if sc >= 70 else "yellow" if sc >= 50 else "red"
                all_tbl.add_row(
                    str(i), r.name,
                    f"[{col}]{sc:.0f}[/]",
                    r.category,
                    f"[green]{r.max_profit_str}[/]",
                    f"[red]{r.max_loss_str}[/]",
                    str(len(r.breakevens)),
                    f"{r.probability_profit*100:.0f}%",
                )
            console.print(all_tbl)
        try:
            show_chart = Prompt.ask(
                "  Show [bold]Payoff Chart[/] (matplotlib)? [dim](Y/N)[/]",
                default="N"
            ).strip().upper()
        except KeyboardInterrupt:
            show_chart = "N"
        if show_chart == 'Y':
            console.print("  [dim]Rendering payoff chart...[/]")
            try:
                cls._matplotlib_chart(results, oracle.S)
            except Exception as exc:
                console.print(f"  [yellow][!] Chart failed: {exc}[/]")
        console.print(
            "\n  [dim]Strategy Advisor complete — returning to options terminal.[/]\n"
        )
        try:
            Prompt.ask("  Press ENTER to return")
        except (EOFError, KeyboardInterrupt):
            pass
