class BloombergLiveWire:
    def __init__(self):
        self.articles     : list[dict] = []
        self.clusters     : dict       = {}                           
        self.breaking     : list[dict] = []                     
        self._or_key      = _GLOBAL_OR_KEY
        self._or_model    = FREE_MODELS[0]["id"]
        self._or_model_name = FREE_MODELS[0]["name"]
        self._watchlist   : list[str]  = []                           
        self._load_config()
    def _load_config(self):
        if CONFIG_FILE.exists():
            try:
                d = json.loads(CONFIG_FILE.read_text(encoding="utf-8"))
                self._or_key = _GLOBAL_OR_KEY
                self._or_model = _GLOBAL_OR_MODEL
                self._or_model_name = d.get("model_name","") or self._or_model_name
                self._watchlist     = d.get("watchlist",[])
            except: pass
    def _save_config(self):
        try:
            existing = {}
            if CONFIG_FILE.exists():
                try: existing = json.loads(CONFIG_FILE.read_text(encoding="utf-8"))
                except: pass
            existing.update({
                "api_key"    : self._or_key,
                "model"      : self._or_model,
                "model_name" : self._or_model_name,
                "watchlist"  : self._watchlist,
            })
            CONFIG_FILE.write_text(
                json.dumps(existing, indent=2), encoding="utf-8"
            )
        except: pass
    def _cache_path(self, key: str) -> Path:
        h = hashlib.md5(key.encode()).hexdigest()[:10]
        return CACHE_DIR / f"{h}.json"
    def _cache_valid(self, key: str) -> bool:
        p = self._cache_path(key)
        return p.exists() and (time.time() - p.stat().st_mtime) < CACHE_TTL
    @staticmethod
    def _parse_time_ago(pub_date_str: str) -> tuple[str, float]:
        import email.utils
        try:
            dt_tuple = email.utils.parsedate_tz(pub_date_str)
            if dt_tuple:
                dt = datetime.fromtimestamp(
                    email.utils.mktime_tz(dt_tuple), timezone.utc
                )
            else:
                dt = datetime.fromisoformat(
                    pub_date_str.replace("Z","+00:00")
                ).astimezone(timezone.utc)
            now  = datetime.now(timezone.utc)
            diff = (now - dt).total_seconds()
            hrs  = diff / 3600
            if diff < 60:      return f"{int(diff)}s ago", hrs
            if diff < 3600:    return f"{int(diff//60)}m ago", hrs
            if diff < 86400:   return f"{int(diff//3600)}h ago", hrs
            return "1d+ ago", hrs
        except Exception:
            return "Recent", 12.0
    @staticmethod
    def _trigram_set(text: str) -> set:
        t = text.lower()
        return {t[i:i+3] for i in range(len(t)-2)}
    @staticmethod
    def _jaccard(a: set, b: set) -> float:
        u = a | b
        return len(a & b) / len(u) if u else 0.0
    def _deduplicate(self, articles: list[dict],
                      threshold: float = 0.5) -> list[dict]:
        kept    : list[dict] = []
        tri_sets: list[set]  = []
        for art in sorted(articles,
                           key=lambda x: x.get('source_weight', 0.5),
                           reverse=True):
            tri = self._trigram_set(art['title'])
            if all(self._jaccard(tri, ts) < threshold for ts in tri_sets):
                kept.append(art)
                tri_sets.append(tri)
        return kept
    @staticmethod
    def _score_sentiment(text: str) -> tuple[float, str]:
        try:
            from nltk.sentiment.vader import SentimentIntensityAnalyzer
            import nltk
            try: nltk.data.find('sentiment/vader_lexicon.zip')
            except: nltk.download('vader_lexicon', quiet=True)
            sia = SentimentIntensityAnalyzer()
            sia.lexicon.update(FINANCE_LEXICON)
            c = sia.polarity_scores(text)['compound']
        except ImportError:
            tl = text.lower()
            c  = 0.0
            for word, score in FINANCE_LEXICON.items():
                if word in tl:
                    c += score * 0.15
            c = max(-1.0, min(1.0, c))
        if   c >= 0.35: label = "Bullish"
        elif c >= 0.10: label = "Mildly Bullish"
        elif c <= -0.35: label = "Bearish"
        elif c <= -0.10: label = "Mildly Bearish"
        else:            label = "Neutral"
        return round(c, 3), label
    @staticmethod
    def _classify(title: str) -> list[str]:
        tl  = title.lower()
        out = []
        for cat, keywords in CATEGORIES.items():
            if any(kw in tl for kw in keywords):
                out.append(cat)
        return out or ["General"]
    def fetch_all_sources(self, max_per_source: int = 30) -> bool:
        from bs4 import BeautifulSoup
        from rich.console  import Console
        from rich.progress import Progress, SpinnerColumn, TextColumn, BarColumn
        console = Console()
        cache_key = f"news_all:{int(time.time()//CACHE_TTL)}"
        cp        = self._cache_path(cache_key)
        if cp.exists() and self._cache_valid(cache_key):
            try:
                self.articles = json.loads(cp.read_text(encoding="utf-8"))
                self._post_process()
                console.print(
                    f"  [dim]Cache: {len(self.articles)} articles "
                    f"(TTL {CACHE_TTL//60}m)[/]"
                )
                return True
            except: pass
        raw_all  : list[dict] = []
        failed   : list[str]  = []
        lock     = threading.Lock()
        hdrs     = {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 Chrome/124 Safari/537.36"
            )
        }
        def _fetch_one(source_tuple) -> None:
            name, url, weight, region = source_tuple
            try:
                resp = requests.get(url, headers=hdrs, timeout=12)
                resp.raise_for_status()
                soup = BeautifulSoup(resp.content, 'xml')
                items= soup.find_all('item')
                batch= []
                for item in items[:max_per_source]:
                    raw_title = (item.title.text if item.title else "").strip()
                    pub_date  = (item.pubDate.text if item.pubDate else "")
                    link_tag  = item.link
                    link      = (link_tag.text.strip()
                                 if link_tag and link_tag.text
                                 else item.find('link') and
                                 item.find('link').get_text(strip=True) or "")
                    if " - " in raw_title:
                        clean_title = raw_title.rsplit(" - ", 1)[0].strip()
                    else:
                        clean_title = raw_title
                    if not clean_title or len(clean_title) < 10:
                        continue
                    time_ago, age_hrs = BloombergLiveWire._parse_time_ago(pub_date)
                    sentiment, sent_label = BloombergLiveWire._score_sentiment(clean_title)
                    categories = BloombergLiveWire._classify(clean_title)
                    batch.append({
                        'title'         : clean_title,
                        'time_ago'      : time_ago,
                        'age_hrs'       : age_hrs,
                        'link'          : link,
                        'source'        : name,
                        'source_weight' : weight,
                        'region'        : region,
                        'sentiment'     : sentiment,
                        'sent_label'    : sent_label,
                        'categories'    : categories,
                        'pub_date'      : pub_date,
                    })
                with lock:
                    raw_all.extend(batch)
            except Exception as e:
                with lock:
                    failed.append(f"{name}: {str(e)[:40]}")
        with Progress(
            SpinnerColumn(),
            TextColumn("[bold cyan]Fetching {task.description}[/]"),
            BarColumn(),
            TextColumn("{task.completed}/{task.total} sources"),
            console=console, transient=True
        ) as prog:
            task = prog.add_task("news sources", total=len(NEWS_SOURCES))
            with ThreadPoolExecutor(max_workers=8) as pool:
                futures = {
                    pool.submit(_fetch_one, src): src
                    for src in NEWS_SOURCES
                }
                for fut in as_completed(futures):
                    prog.advance(task)
        if not raw_all:
            console.print("  [red]✗ All sources failed.[/]")
            return False
        raw_all.sort(key=lambda x: x['age_hrs'])
        self.articles = self._deduplicate(raw_all, threshold=0.55)
        try:
            cp.write_text(json.dumps(self.articles), encoding="utf-8")
        except: pass
        if failed:
            console.print(
                f"  [dim]Sources failed: {', '.join(failed[:3])}[/]"
            )
        self._post_process()
        return True
    def _post_process(self) -> None:
        self.clusters = {cat: [] for cat in CATEGORIES}
        self.clusters["General"] = []
        self.breaking = []
        for art in self.articles:
            for cat in art.get('categories', ['General']):
                if cat in self.clusters:
                    self.clusters[cat].append(art)
            if art.get('age_hrs', 99) < 0.5:
                self.breaking.append(art)
            art['watchlist_hit'] = False
            if self._watchlist:
                tl = art['title'].lower()
                if any(w.lower().replace('.ns','').replace('.bo','')
                       in tl for w in self._watchlist):
                    art['watchlist_hit'] = True
    def _category_sentiment(self) -> dict[str, float]:
        result = {}
        for cat, arts in self.clusters.items():
            if arts:
                result[cat] = sum(a['sentiment'] for a in arts) / len(arts)
        return result
    def _ai_call(self, sys_p: str, user_p: str) -> tuple[str, float]:
        if not self._or_key:
            return "[AI UNAVAILABLE] Configure API key.", 0.0
        bag  = {}; done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization":f"Bearer {self._or_key}",
                             "Content-Type":"application/json",
                             "X-Title":"Module47-NewsTerminal"},
                    json={"model":self._or_model,
                          "messages":[{"role":"system","content":sys_p},
                                      {"role":"user","content":user_p}],
                          "temperature":0.35},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter()-t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter()-t0
            finally: done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin="⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i=0; t0=time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i%len(spin)]} AI scanning wire… "
                  f"{time.perf_counter()-t0:.1f}s   ",
                  end="", flush=True)
            i+=1
        print()
        return bag.get("reply",""), bag.get("latency",0.0)
    def _build_wire_context(self, max_headlines: int = 60) -> str:
        arts   = self.articles[:max_headlines]
        n      = len(arts)
        fresh1 = sum(1 for a in arts if a['age_hrs'] < 1)
        fresh5 = sum(1 for a in arts if 1 <= a['age_hrs'] < 5)
        older  = n - fresh1 - fresh5
        cat_counts = {
            cat: len(lst) for cat, lst in self.clusters.items() if lst
        }
        cat_sent   = self._category_sentiment()
        lines = [
            f"=== LIVE FINANCIAL WIRE ===",
            f"Fetched: {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}",
            f"Total: {n} headlines from {len(set(a['source'] for a in arts))} sources",
            f"Freshness: {fresh1} <1h  |  {fresh5} 1-5h  |  {older} 5h+",
            f"Breaking (last 30min): {len(self.breaking)} articles",
            "",
            "CATEGORY COVERAGE & SENTIMENT:",
        ]
        for cat, cnt in sorted(cat_counts.items(), key=lambda x: -x[1]):
            sent = cat_sent.get(cat, 0.0)
            sc   = "↑ Bullish" if sent>0.1 else "↓ Bearish" if sent<-0.1 else "→ Neutral"
            lines.append(f"  {cat:<18}: {cnt:>3} headlines  {sc} ({sent:+.2f})")
        if self._watchlist:
            wl_hits = [a for a in arts if a.get('watchlist_hit')]
            lines += ["", f"WATCHLIST HITS ({', '.join(self._watchlist[:6])}):"]
            for a in wl_hits[:8]:
                lines.append(f"  [{a['time_ago']}] {a['title'][:80]}")
        lines += ["", "HEADLINES (numbered, newest first):"]
        for i, a in enumerate(arts, 1):
            cats_str = ", ".join(a.get('categories', ['General']))[:30]
            lines.append(
                f"  {i:>3}. [{a['time_ago']:<7}] [{a['source']:<12}] "
                f"[{a['sent_label']:<14}] [{cats_str}]  {a['title']}"
            )
        return "\n".join(lines)
