    def run_ai_chat(self, seed_reply: str = "") -> None:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.prompt   import Prompt
        from rich.markdown import Markdown
        console = Console()
        digest  = self._build_wire_context()
        _SYS    = (
            "You are a Bloomberg Markets Desk Analyst with access to today's "
            "full news wire.\n"
            "Answer questions about specific headlines, market themes, "
            "macro implications, or investment ideas.\n"
            "Reference headlines by number. Distinguish wire evidence vs "
            "training knowledge.\n"
            "Be direct, precise, and quantitative where possible."
        )
        history = [
            {"role":"system",    "content":_SYS},
            {"role":"user",      "content":f"Wire context:\n{digest}"},
            {"role":"assistant", "content": seed_reply or
             f"I have the full wire — {len(self.articles)} headlines from "
             f"{len(set(a['source'] for a in self.articles))} sources. "
             "Ask me about any story, theme, or market implication."},
        ]
        turn=0; _WARN=8_000
        console.print(Panel(
            f"[bold cyan]💬 Bloomberg Wire Chat[/]\n\n"
            f"[dim]{len(self.articles)} headlines loaded from "
            f"{len(set(a['source'] for a in self.articles))} sources[/]\n\n"
            "Ask about specific headlines, themes, or market implications.\n\n"
            "[bold]Commands:[/]  [cyan]clear[/]   "
            "[cyan]export[/]   [cyan]exit[/]",
            border_style="cyan", expand=False
        ))
        while True:
            est = sum(len(m["content"]) for m in history)//4
            tok = f"[yellow]~{est} ⚠[/]" if est>=_WARN else f"[dim]~{est}t[/]"
            q   = Prompt.ask(
                f"\n  [bold cyan]You[/] [dim](turn {turn+1} | {tok})[/]"
            ).strip()
            if not q: continue
            if q.lower()=="exit":  console.print("  [dim]Returning…[/]"); break
            if q.lower()=="clear":
                history=[{"role":"system","content":_SYS}]; turn=0
                console.print("  [green]✓ Cleared.[/]"); continue
            if q.lower()=="export":
                self._export_session(history); continue
            history.append({"role":"user","content":q})
            conv = "\n".join(f"{m['role'].upper()}: {m['content']}"
                             for m in history[1:])
            reply, lat = self._ai_call(_SYS, conv)
            if reply:
                console.print(Panel(
                    Markdown(reply), border_style="green",
                    title=f"[bold green]{self._or_model_name}[/] "
                          f"[dim]({lat:.2f}s)[/]",
                    expand=False
                ))
                history.append({"role":"assistant","content":reply})
                turn+=1
            else:
                history.pop()
    def _export_session(self, history: list = None) -> None:
        ts   = datetime.now().strftime("%Y%m%d_%H%M%S")
        fn   = f"wire_session_{ts}.json"
        data = {
            "exported_at" : datetime.now().isoformat(),
            "model"       : self._or_model,
            "articles"    : self.articles[:60],
            "messages"    : history[1:] if history else [],
        }
        try:
            Path(fn).write_text(
                json.dumps(data, indent=2, ensure_ascii=False),
                encoding="utf-8"
            )
            from rich.console import Console
            Console().print(f"  [green]✓ Exported → {fn}[/]")
        except Exception as e:
            from rich.console import Console
            Console().print(f"  [red]Export failed: {e}[/]")
    def _settings(self, console) -> None:
        from rich.panel  import Panel
        from rich.prompt import Prompt
        from rich.table  import Table
        console.clear()
        masked = (f"sk-…{self._or_key[-6:]}"
                  if len(self._or_key)>6 else "[red]Not set[/]")
        console.print(Panel(
            f"[bold cyan]🔧 Module 47 — Settings[/]\n\n"
            f"AI Key   : {masked}\n"
            f"Model    : [dim]{self._or_model}[/]\n"
            f"Watchlist: [dim]{', '.join(self._watchlist) or 'Empty'}[/]",
            border_style="cyan"
        ))
        nk = Prompt.ask("  New API Key [dim](ENTER=keep)[/]",default="").strip()
        if nk: self._or_key = nk
        tbl = Table(border_style="cyan")
        tbl.add_column("#"); tbl.add_column("Model"); tbl.add_column("Note",style="dim")
        for i, m in enumerate(FREE_MODELS, 1):
            act = " [green]◄[/]" if m["id"]==self._or_model else ""
            tbl.add_row(str(i), m["name"]+act, m["note"])
        console.print(tbl)
        mc = Prompt.ask("  Model #",default="").strip()
        if mc.isdigit() and 1<=int(mc)<=len(FREE_MODELS):
            self._or_model      = FREE_MODELS[int(mc)-1]["id"]
            self._or_model_name = FREE_MODELS[int(mc)-1]["name"]
        nw = Prompt.ask(
            "  Watchlist tickers [dim](comma-sep, ENTER=keep)[/]",
            default=""
        ).strip()
        if nw:
            self._watchlist = [
                t.strip().upper() for t in nw.split(",") if t.strip()
            ]
        self._save_config()
        console.print("  [green]✓ Saved.[/]"); time.sleep(1)
    def _render_wire_table(self,
                           articles: list,
                           title: str = "🔴 LIVE FINANCIAL WIRE",
                           page: int  = 0,
                           page_size: int = 20) -> int:                                               
        from rich.console import Console
        from rich.table   import Table
        from rich.rule    import Rule
        from rich         import box as _box
        console = Console()
        total_pages = max(1, (len(articles)+page_size-1)//page_size)
        page        = max(0, min(page, total_pages-1))
        start       = page * page_size
        slice_      = articles[start : start+page_size]
        console.print(Rule(
            f"[bold white]{title}[/]  "
            f"[dim]Page {page+1}/{total_pages}  "
            f"({len(articles)} articles)[/]"
        ))
        tbl = Table(
            box=_box.ROUNDED, show_header=True,
            header_style="bold white", expand=True, show_lines=True, padding=(0, 1)
        )
        tbl.add_column("#",         width=4,  justify="right", style="dim", no_wrap=True)
        tbl.add_column("Time",      width=8,  justify="right", no_wrap=True)
        tbl.add_column("Source",    width=14, style="dim", no_wrap=True)
        tbl.add_column("Headline",  ratio=1)
        tbl.add_column("Sentiment", width=15, justify="center", no_wrap=True)
        tbl.add_column("Category",  width=16, style="dim", no_wrap=True)
        for i, a in enumerate(slice_, start+1):
            age = a.get('age_hrs', 12)
            if   age < 0.5:  tc = "bold red"
            elif age < 1.0:  tc = "green"
            elif age < 5.0:  tc = "yellow"
            else:            tc = "dim"
            sc = a.get('sentiment', 0)
            if   sc >= 0.35: sc_str = "[bold green]▲ Bullish[/]"
            elif sc >= 0.10: sc_str = "[green]↑ Mild Bull[/]"
            elif sc <= -0.35:sc_str = "[bold red]▼ Bearish[/]"
            elif sc <= -0.10:sc_str = "[red]↓ Mild Bear[/]"
            else:            sc_str = "[dim]→ Neutral[/]"
            wl = "⭐ " if a.get('watchlist_hit') else ""
            cats= ", ".join(a.get('categories',['General']))[:16]
            tbl.add_row(
                str(i),
                f"[{tc}]{a['time_ago']}[/{tc}]",
                a['source'][:13],
                f"{wl}{a['title']}",                                                          
                sc_str,
                cats,
            )
        console.print(tbl)
        return total_pages
    def _render_sentiment_heatmap(self) -> None:
        from rich.console import Console
        from rich.table   import Table
        from rich.panel   import Panel
        from rich         import box as _box
        console = Console()
        cat_sent = self._category_sentiment()
        tbl = Table(
            border_style="dim", box=_box.SIMPLE, show_header=True,
            header_style="bold cyan", expand=False
        )
        tbl.add_column("Category",   width=18, style="bold")
        tbl.add_column("Headlines",  width=10, justify="right")
        tbl.add_column("Sentiment",  width=12, justify="right")
        tbl.add_column("Bar",        width=22)
        tbl.add_column("Signal",     width=16)
        for cat in sorted(cat_sent, key=lambda c: -abs(cat_sent[c])):
            score = cat_sent[cat]
            cnt   = len(self.clusters.get(cat, []))
            if cnt == 0: continue
            pos_w = int(max(score, 0) * 10)
            neg_w = int(max(-score, 0) * 10)
            bar   = (
                "[red]" + "█"*neg_w + "[/]" +
                "[dim]│[/]" +
                "[green]" + "█"*pos_w + "[/]"
            )
            if   score >= 0.35: sig = "[bold green]BULLISH[/]"
            elif score >= 0.10: sig = "[green]Mild Bull[/]"
            elif score <= -0.35:sig = "[bold red]BEARISH[/]"
            elif score <= -0.10:sig = "[red]Mild Bear[/]"
            else:               sig = "[dim]Neutral[/]"
            sc_clr = "green" if score>0 else "red"
            tbl.add_row(
                cat, str(cnt),
                f"[{sc_clr}]{score:+.3f}[/{sc_clr}]",
                bar, sig
            )
        console.print(Panel(
            tbl,
            title="[bold white]Category Sentiment Heatmap[/]",
            border_style="cyan", expand=False
        ))
