class GrowwIntradayScanner:
    def __init__(self):
        self.target_url = "https://groww.in/stocks/intraday"
        self.headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
            'Accept-Language': 'en-US,en;q=0.9',
            'Referer': 'https://groww.in/',
            'Sec-Ch-Ua': '"Chromium";v="124", "Google Chrome";v="124", "Not-A.Brand";v="99"',
            'Sec-Ch-Ua-Mobile': '?0',
            'Sec-Ch-Ua-Platform': '"Windows"',
            'Sec-Fetch-Dest': 'document',
            'Sec-Fetch-Mode': 'navigate',
            'Sec-Fetch-Site': 'same-origin',
            'Upgrade-Insecure-Requests': '1'
        }
        self.stocks_data = []
    def _generate_52w_bar(self, html_cell_str):
        B, C, RES = '\033[1m', '\033[96m', '\033[0m'
        match = re.search(r'left:\s*([\d.]+)%', html_cell_str)
        if match:
            pct = float(match.group(1))
            bar_len = 12
            pip_pos = int((pct / 100) * bar_len)
            bar = ["─"] * bar_len
            if 0 <= pip_pos < bar_len:
                bar[pip_pos] = f"{C}█{RES}\033[90m"
            joined_bar = "".join(bar)
            return f"\033[90mL {joined_bar} H\033[0m"
        else:
            return f"\033[90mL ─────{C}█{RES}\033[90m────── H\033[0m"
    def fetch_data(self):
        try:
            from bs4 import BeautifulSoup
        except ImportError:
            print("  \033[91m[!] Missing libraries. Run: pip install requests beautifulsoup4\033[0m")
            return False
        print(f"  \033[96mEstablishing secure link to Groww Intraday Servers...\033[0m")
        print(f"  \033[90mRunning Auto-Healing Parser on DOM payloads...\033[0m")
        try:
            res = requests.get(self.target_url, headers=self.headers, timeout=12)
            res.raise_for_status()
        except Exception as e:
            print(f"  \033[91m[!] Connection to Groww failed or blocked: {e}\033[0m")
            return False
        soup = BeautifulSoup(res.text, 'html.parser')
        table = soup.find('table')
        if not table:
            print(f"  \033[93m[!] Could not locate the primary data table.\033[0m")
            return False
        self.stocks_data = []
        rows = table.find_all('tr')
        for row in rows[1:]:
            cols = row.find_all('td')
            valid_cols = []
            for c in cols:
                text = c.get_text(separator=' ', strip=True)
                if text: valid_cols.append((text, c))
            if len(valid_cols) >= 4:
                try:
                    a_tag = row.find('a')
                    if a_tag:
                        company = a_tag.get_text(strip=True)
                    else:
                        company = valid_cols[0][0]
                    company = company.replace('In news', '').strip()
                    price_str = valid_cols[1][0].replace('₹', '').replace(',', '').strip()
                    change_str = valid_cols[2][0]
                    volume_str = valid_cols[3][0]
                    bar_html = str(valid_cols[-1][1])
                    ascii_bar = self._generate_52w_bar(bar_html)
                    price_val = float(price_str) if price_str.replace('.', '', 1).isdigit() else 0.0
                    pct_val = 0.0
                    pct_match = re.search(r'\(([-+]?[\d.]+)%\)', change_str)
                    if pct_match: pct_val = float(pct_match.group(1))
                    vol_val = int(volume_str.replace(',', '')) if volume_str.replace(',', '').isdigit() else 0
                    self.stocks_data.append({
                        'company': company,
                        'price': f"₹{price_str}",
                        'price_val': price_val,
                        'change': change_str,
                        'pct_val': pct_val,
                        'volume': volume_str,
                        'vol_val': vol_val,
                        '52w_bar': ascii_bar
                    })
                except Exception:
                    continue
        return len(self.stocks_data) > 0
    def print_table(self, data):
        B, C, G, Y, R, M, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[95m', '\033[0m'
        header = f"  {B}{'COMPANY':<32} │ {'LTP':>10} │ {'1D CHANGE':>18} │ {'1D VOLUME':>14} │ {'52W RANGE':<16}{RES}"
        print(f"\n{header}")
        print("  " + "═" * 102)
        for s in data:
            c_color = G if "+" in s['change'] else (R if "-" in s['change'] else Y)
            comp_name = s['company'][:29] + ".." if len(s['company']) > 32 else s['company']
            print(f"  {B}{comp_name:<32}{RES} │ {s['price']:>10} │ {c_color}{s['change']:>18}{RES} │ {s['volume']:>14} │ {s['52w_bar']}")
        print("  " + "═" * 102)
    def interactive_menu(self):
        import webbrowser
        B, C, G, Y, R, M, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[95m', '\033[0m'
        GREEN_BG = '\033[42m\033[30m'
        if not self.fetch_data():
            print(f"  {Y}Falling back to main menu...{RES}")
            input("  Press ENTER to continue...")
            return
        current_view = self.stocks_data.copy()
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            print(f"\n  {GREEN_BG}{B} GROWW INTRADAY SCANNER | LIVE MOMENTUM & VOLUME SHOCKS {' ' * 23} {RES}")
            self.print_table(current_view)
            print(f"  {B}1.{RES} Sort by {C}Highest Volume{RES}       {B}2.{RES} Sort by {G}Biggest % Gainers{RES}     {B}3.{RES} Sort by {R}Biggest % Losers{RES}")
            print(f"  {B}R.{RES} Refresh Live Data          {B}W.{RES} Open Groww Website          {B}0.{RES} Return to Main Menu")
            choice = input(f"\n  Select an action: ").strip().upper()
            if choice == '0':
                break
            elif choice == '1':
                current_view = sorted(self.stocks_data, key=lambda x: x['vol_val'], reverse=True)
            elif choice == '2':
                current_view = sorted(self.stocks_data, key=lambda x: x['pct_val'], reverse=True)
            elif choice == '3':
                current_view = sorted(self.stocks_data, key=lambda x: x['pct_val'])
            elif choice == 'R':
                self.fetch_data()
                current_view = self.stocks_data.copy()
            elif choice == 'W':
                print(f"  {G}Launching Groww Intraday Dashboard...{RES}")
                webbrowser.open(self.target_url)
            else:
                print(f"  {R}[!] Invalid selection.{RES}")
def run_groww_intraday(ticker_ignored):
    header("MODULE 21 — INTRADAY SCANNER")
    scanner = GrowwIntradayScanner()
    scanner.interactive_menu()
