class LivemintLiveWire:
    def __init__(self):
        self.articles     = []
        self.clusters     = {}
        self.breaking     = []
        self._or_key      = _GLOBAL_OR_KEY
        self._or_model    = FREE_MODELS[0]["id"]
        self._or_model_name = FREE_MODELS[0]["name"]
        self._watchlist   = []
        self._load_config()
    def _load_config(self):
        if CONFIG_FILE.exists():
            try:
                d = json.loads(CONFIG_FILE.read_text(encoding="utf-8"))
                self._or_key = _GLOBAL_OR_KEY
                self._or_model = _GLOBAL_OR_MODEL
                self._or_model_name = d.get("model_name","") or self._or_model_name
                self._watchlist     = d.get("watchlist",[])
            except: pass
    def _cache_path(self, key: str) -> Path:
        h = hashlib.md5(key.encode()).hexdigest()[:10]
        return CACHE_DIR / f"{h}.json"
    @staticmethod
    def _parse_time_ago(pub_date_str: str) -> tuple[str, float]:
        import email.utils
        try:
            dt_tuple = email.utils.parsedate_tz(pub_date_str)
            if dt_tuple:
                dt = datetime.fromtimestamp(email.utils.mktime_tz(dt_tuple), timezone.utc)
            else:
                dt = datetime.fromisoformat(pub_date_str.replace("Z","+00:00")).astimezone(timezone.utc)
            now  = datetime.now(timezone.utc)
            diff = (now - dt).total_seconds()
            hrs  = diff / 3600
            if diff < 60:      return f"{int(diff)}s ago", hrs
            if diff < 3600:    return f"{int(diff//60)}m ago", hrs
            if diff < 86400:   return f"{int(diff//3600)}h ago", hrs
            return "1d+ ago", hrs
        except Exception:
            return "Recent", 12.0
    def _deduplicate(self, articles: list, threshold: float = 0.5) -> list:
        kept = []
        tri_sets = []
        for art in sorted(articles, key=lambda x: x.get('source_weight', 0.5), reverse=True):
            t = art['title'].lower()
            tri = {t[i:i+3] for i in range(len(t)-2)}
            if all(len(tri & ts) / len(tri | ts) < threshold for ts in tri_sets if (tri | ts)):
                kept.append(art)
                tri_sets.append(tri)
        return kept
    @staticmethod
    def _score_sentiment(text: str) -> tuple[float, str]:
        try:
            from nltk.sentiment.vader import SentimentIntensityAnalyzer
            import nltk
            try: nltk.data.find('sentiment/vader_lexicon.zip')
            except: nltk.download('vader_lexicon', quiet=True)
            sia = SentimentIntensityAnalyzer()
            sia.lexicon.update(FINANCE_LEXICON)
            c = sia.polarity_scores(text)['compound']
        except ImportError:
            tl = text.lower()
            c  = 0.0
            for word, score in FINANCE_LEXICON.items():
                if word in tl: c += score * 0.15
            c = max(-1.0, min(1.0, c))
        if   c >= 0.35: label = "Bullish"
        elif c >= 0.10: label = "Mildly Bullish"
        elif c <= -0.35: label = "Bearish"
        elif c <= -0.10: label = "Mildly Bearish"
        else:            label = "Neutral"
        return round(c, 3), label
    @staticmethod
    def _classify(title: str) -> list[str]:
        tl  = title.lower()
        out = []
        for cat, keywords in CATEGORIES.items():
            if any(kw in tl for kw in keywords): out.append(cat)
        return out or ["General India"]
    def fetch_news(self, force=False) -> bool:
        from bs4 import BeautifulSoup
        from rich.console  import Console
        from rich.progress import Progress, SpinnerColumn, TextColumn, BarColumn
        console = Console()
        cache_key = f"livemint_all:{int(time.time()//CACHE_TTL)}"
        cp        = self._cache_path(cache_key)
        if not force and cp.exists() and (time.time() - cp.stat().st_mtime) < CACHE_TTL:
            try:
                self.articles = json.loads(cp.read_text(encoding="utf-8"))
                self._post_process()
                console.print(f"  [dim]Cache: {len(self.articles)} Livemint articles[/]")
                return True
            except: pass
        raw_all = []
        lock    = threading.Lock()
        hdrs    = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/124.0.0.0"}
        def _fetch_one(source_tuple) -> None:
            name, url, weight, region = source_tuple
            try:
                resp = requests.get(url, headers=hdrs, timeout=12)
                resp.raise_for_status()
                try:
                    soup = BeautifulSoup(resp.content, 'xml')
                except Exception:
                    soup = BeautifulSoup(resp.content, 'html.parser')
                items = soup.find_all('item')
                batch = []
                for item in items[:max_per_source]:
                    title_tag = item.find('title')
                    raw_title = title_tag.text.strip() if title_tag else ""
                    pub_tag   = item.find('pubdate') or item.find('pubDate')
                    pub_date  = pub_tag.text.strip() if pub_tag else ""
                    link_tag  = item.find('link')
                    link      = link_tag.text.strip() if link_tag and link_tag.text else ""
                    if " - " in raw_title:
                        clean_title = raw_title.rsplit(" - ", 1)[0].strip()
                    else:
                        clean_title = raw_title
                    if not clean_title or len(clean_title) < 10:
                        continue
                    time_ago, age_hrs = BloombergLiveWire._parse_time_ago(pub_date)
                    sentiment, sent_label = BloombergLiveWire._score_sentiment(clean_title)
                    categories = BloombergLiveWire._classify(clean_title)
                    batch.append({
                        'title'         : clean_title,
                        'time_ago'      : time_ago,
                        'age_hrs'       : age_hrs,
                        'link'          : link,
                        'source'        : name,
                        'source_weight' : weight,
                        'region'        : region,
                        'sentiment'     : sentiment,
                        'sent_label'    : sent_label,
                        'categories'    : categories,
                        'pub_date'      : pub_date,
                    })
                with lock:
                    raw_all.extend(batch)
            except Exception as e:
                with lock:
                    failed.append(f"{name}: {str(e)[:40]}")
        with Progress(SpinnerColumn(), TextColumn("[bold cyan]Fetching Livemint {task.description}[/]"),
                      BarColumn(), console=console, transient=True) as prog:
            task = prog.add_task("feeds", total=len(NEWS_SOURCES))
            with ThreadPoolExecutor(max_workers=5) as pool:
                futures = {pool.submit(_fetch_one, src): src for src in NEWS_SOURCES}
                for fut in as_completed(futures): prog.advance(task)
        if not raw_all:
            console.print("  [red]✗ All sources failed.[/]")
            if failed:
                console.print("\n  [dim]Diagnostic Errors:[/]")
                for err in failed[:5]:
                    console.print(f"  [dim]- {err}[/]")
            return False
        raw_all.sort(key=lambda x: x['age_hrs'])
        self.articles = self._deduplicate(raw_all, threshold=0.55)
        try: cp.write_text(json.dumps(self.articles), encoding="utf-8")
        except: pass
        self._post_process()
        return True
    def _post_process(self):
        self.clusters = {cat: [] for cat in CATEGORIES}
        self.clusters["General India"] = []
        self.breaking = []
        for art in self.articles:
            for cat in art.get('categories', ['General India']):
                if cat in self.clusters: self.clusters[cat].append(art)
            if art.get('age_hrs', 99) < 0.5:
                self.breaking.append(art)
            art['watchlist_hit'] = False
            if self._watchlist:
                tl = art['title'].lower()
                if any(w.lower().replace('.ns','').replace('.bo','') in tl for w in self._watchlist):
                    art['watchlist_hit'] = True
    def _ai_call(self, sys_p: str, user_p: str) -> tuple[str, float]:
        if not self._or_key: return "[AI UNAVAILABLE] Configure API key.", 0.0
        bag = {}; done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization":f"Bearer {self._or_key}", "Content-Type":"application/json"},
                    json={"model":self._or_model, "messages":[{"role":"system","content":sys_p}, {"role":"user","content":user_p}], "temperature":0.35},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter()-t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter()-t0
            finally: done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin="⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i=0; t0=time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i%len(spin)]} Analyst AI thinking... {time.perf_counter()-t0:.1f}s   ", end="", flush=True)
            i+=1
        print("\r" + " "*40 + "\r", end="")
        return bag.get("reply",""), bag.get("latency",0.0)
    def _build_context(self, max_headlines=50):
        arts = self.articles[:max_headlines]
        lines = ["=== LIVEMINT NEWS WIRE ===", f"Total: {len(arts)} headlines", ""]
        for i, a in enumerate(arts, 1):
            cats = ", ".join(a.get('categories', ['General India']))
            lines.append(f"{i:>2}. [{a['time_ago']}] [{a['sent_label']}] [{cats}] {a['title']}")
        return "\n".join(lines)
    def run_ai_scan(self):
        from rich.console import Console
        from rich.panel import Panel
        from rich.markdown import Markdown
        console = Console()
        _SYS = (
            "You are a veteran Dalal Street Analyst reading the morning Livemint wire.\n"
            "Analyse the headline batch provided. Give a structured brief:\n"
            "1. Market Moving News: Top 2 stories affecting Nifty/Sensex.\n"
            "2. Corporate Action: Major company news, M&A, earnings.\n"
            "3. Macro/Policy: RBI, Govt policy, or economic indicators.\n"
            "4. Retail Investor Impact: What does this mean for retail portfolios?\n"
            "Reference headlines by number. Be crisp, professional, and definitive."
        )
        reply, lat = self._ai_call(_SYS, self._build_context())
        console.print(Panel(Markdown(reply), border_style="green", title=f"[bold green]Dalal Street AI Scan[/] [dim]({lat:.2f}s)[/]"))
        input("\n  Press ENTER to return...")
    def _render_wire_table(self, articles: list, title: str, page: int, page_size: int = 20):
        from rich.console import Console
        from rich.table   import Table
        from rich.rule    import Rule
        from rich         import box as _box
        console = Console()
        total_pages = max(1, (len(articles)+page_size-1)//page_size)
        page        = max(0, min(page, total_pages-1))
        start       = page * page_size
        slice_      = articles[start : start+page_size]
        console.print(Rule(f"[bold white on magenta] {title} [/]  [dim]Page {page+1}/{total_pages}[/]"))
        tbl = Table(
            box=_box.ROUNDED, show_header=True, header_style="bold white", 
            expand=True, show_lines=True, padding=(0, 1)
        )
        tbl.add_column("#",         width=4,  justify="right", style="dim", no_wrap=True)
        tbl.add_column("Time",      width=8,  justify="right", no_wrap=True)
        tbl.add_column("Section",   width=12, style="dim", no_wrap=True)
        tbl.add_column("Headline",  ratio=1)
        tbl.add_column("Sentiment", width=15, justify="center", no_wrap=True)
        tbl.add_column("Category",  width=18, style="dim", no_wrap=True)
        for i, a in enumerate(slice_, start+1):
            age = a.get('age_hrs', 12)
            if age < 0.5: tc = "bold red"
            elif age < 2.0: tc = "green"
            else: tc = "dim"
            sc = a.get('sentiment', 0)
            if   sc >= 0.35: sc_str = "[bold green]▲ Bullish[/]"
            elif sc >= 0.10: sc_str = "[green]↑ Mild Bull[/]"
            elif sc <= -0.35:sc_str = "[bold red]▼ Bearish[/]"
            elif sc <= -0.10:sc_str = "[red]↓ Mild Bear[/]"
            else:            sc_str = "[dim]→ Neutral[/]"
            wl = "⭐ " if a.get('watchlist_hit') else ""
            cats= ", ".join(a.get('categories',['General India']))[:18]
            tbl.add_row(
                str(i), f"[{tc}]{a['time_ago']}[/{tc}]", a['source'][:11],
                f"{wl}{a['title']}", sc_str, cats
            )
        console.print(tbl)
        return total_pages
    def interactive_menu(self):
        import webbrowser
        from rich.console import Console
        from rich.panel   import Panel
        from rich.prompt  import Prompt
        from rich         import box as _box
        console = Console()
        self.fetch_news()
        current_page  = 0
        current_arts  = None
        current_title = "LIVEMINT TOP NEWS & MARKETS"
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            display = current_arts if current_arts is not None else self.articles
            total_pages = self._render_wire_table(display, current_title, current_page, page_size=20)
            menu_panel = Panel(
                "  [bold cyan]NAV:[/]    [white]N[/] Next   [white]V[/] Prev   [white]G[/] Go to page\n"
                "  [bold cyan]FILTER:[/] [white]C[/] Category   [white]X[/] Clear   [white]W[/] Watchlist\n"
                "  [bold cyan]AI:[/]     [white]S[/] Dalal Street Scan   [white]D[/] AI Deep-Dive\n"
                "  [bold cyan]OTHER:[/]  [white]R[/] Refresh   [white]0[/] Back to Main",
                border_style="dim", box=_box.ROUNDED, expand=False
            )
            console.print(menu_panel)
            try: choice = Prompt.ask("  Choice").strip().upper()
            except KeyboardInterrupt: break
            if choice == "0": break
            elif choice == "N": current_page = min(current_page + 1, total_pages - 1)
            elif choice == "V": current_page = max(current_page - 1, 0)
            elif choice.isdigit():
                idx = current_page * 20 + int(choice) - 1
                if 0 <= idx < len(display):
                    art = display[idx]
                    console.print(f"  [green]Opening:[/] {art['title']}")
                    time.sleep(0.5)
                    webbrowser.open(art['link'])
            elif choice == "C":
                cats = list(CATEGORIES.keys())
                for i, c in enumerate(cats, 1):
                    console.print(f"  [cyan]{i}.[/] {c} ({len(self.clusters.get(c, []))})")
                cc = Prompt.ask("  Category #").strip()
                if cc.isdigit() and 1 <= int(cc) <= len(cats):
                    sel = cats[int(cc)-1]
                    current_arts = self.clusters.get(sel, [])
                    current_title = f"📁 Category: {sel}"
                    current_page = 0
            elif choice == "X":
                current_arts, current_page, current_title = None, 0, "LIVEMINT TOP NEWS & MARKETS"
            elif choice == "R":
                self.fetch_news(force=True)
                current_arts, current_page = None, 0
            elif choice == "S":
                console.clear()
                self.run_ai_scan()
def run_livemint_news(ticker_ignored=""):
    app = LivemintLiveWire()
    app.interactive_menu()
import re, json, time, threading, textwrap
def run_shareholding_scraper(ticker: str) -> None:
    warnings.filterwarnings("ignore")
    from rich.console  import Console
    from rich.panel    import Panel
    from rich.table    import Table
    from rich.rule     import Rule
    from rich.markdown import Markdown
    from rich.prompt   import Prompt
    from rich          import box as _box
    console = Console()
    def _load_or():
        return _GLOBAL_OR_KEY, _GLOBAL_OR_MODEL
    OR_KEY, OR_MODEL = _load_or()
    def _ai_call(sys_p: str, user_p: str) -> tuple[str, float]:
        if not OR_KEY:
            return "[AI UNAVAILABLE] Configure API key in Module 71/37 Settings.", 0.0
        bag = {}; done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization": f"Bearer {OR_KEY}",
                             "Content-Type": "application/json",
                             "X-Title": "Module39-Shareholding"},
                    json={"model": OR_MODEL,
                          "messages": [{"role":"system","content":sys_p},
                                       {"role":"user",  "content":user_p}],
                          "temperature": 0.3},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter() - t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter() - t0
            finally: done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i = 0; t0 = time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i%len(spin)]} AI thinking… {time.perf_counter()-t0:.1f}s   ",
                  end="", flush=True)
            i += 1
        print()
        return bag.get("reply",""), bag.get("latency", 0.0)
    clean_ticker = ticker.upper().replace('.NS','').replace('.BO','')
    def _scrape_screener(clean: str) -> Optional[dict]:
        try:
            from bs4 import BeautifulSoup
        except ImportError:
            return None
        headers = {
            'User-Agent': (
                'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
                'AppleWebKit/537.36 (KHTML, like Gecko) '
                'Chrome/124.0.0.0 Safari/537.36'
            )
        }
        html = None
        used_url = ""
        for url in [
            f"https://www.screener.in/company/{clean}/consolidated/",
            f"https://www.screener.in/company/{clean}/",
        ]:
            try:
                res = requests.get(url, headers=headers, timeout=15)
                if res.status_code == 200:
                    html = res.text
                    used_url = url
                    break
            except Exception:
                continue
        if not html:
            return None
        soup = BeautifulSoup(html, 'html.parser')
        section = soup.find('section', id='shareholding')
        if not section:
            return None
        table = section.find('table')
        if not table:
            return None
        thead = table.find('thead')
        if not thead:
            return None
        th_cells = thead.find_all('th')
        quarters = [th.get_text(strip=True) for th in th_cells[1:]]
        tbody = table.find('tbody')
        if not tbody:
            return None
        MACRO_CATS = {
            "Promoters", "FIIs", "DIIs", "Government",
            "Public", "Others", "No. of Shareholders"
        }
        SUB_KEYWORDS = [
            "Pledged", "Mutual Funds", "Insurance", "Banks",
            "Foreign Portfolio", "Individual", "NRI",
        ]
        rows       = []
        pledge_rows= []
        for tr in tbody.find_all('tr'):
            tds = tr.find_all('td')
            if len(tds) < 2:
                continue
            raw_name = tds[0].get_text(strip=True)
            is_sub   = raw_name.startswith('+') or raw_name.startswith('-')
            name     = raw_name.lstrip('+-').strip()
            values   = [td.get_text(strip=True) for td in tds[1:]]
            if "pledged" in name.lower():
                pledge_rows.append({'name': name, 'values': values})
                continue
            rows.append({
                'name'  : name,
                'values': values,
                'is_sub': is_sub,
            })
        return {
            'quarters'   : quarters,
            'rows'       : rows,
            'pledge_rows': pledge_rows,
            'source_url' : used_url,
        }
    def _yf_holders(ticker_sym: str) -> dict:
        try:
            stock = yf.Ticker(ticker_sym)
            inst  = stock.institutional_holders
            major = stock.major_holders
            return {
                'institutional': inst,
                'major'        : major,
            }
        except Exception:
            return {}
    def _parse_float(s: str) -> Optional[float]:
        if not s or s in ('—', '-', '', 'N/A'):
            return None
        cleaned = s.replace(',', '').replace('%', '').strip()
        try:
            return float(cleaned)
        except ValueError:
            return None
    def _compute_deltas(values: list[str]) -> list[Optional[float]]:
        floats = [_parse_float(v) for v in values]
        deltas: list[Optional[float]] = [None]
        for i in range(1, len(floats)):
            if floats[i] is not None and floats[i-1] is not None:
                deltas.append(round(floats[i] - floats[i-1], 2))
            else:
                deltas.append(None)
        return deltas
    def _trend_arrow(deltas: list[Optional[float]],
                     n: int = 3) -> str:
        recent = [d for d in deltas[-n:] if d is not None]
        if not recent:
            return "  "
        if all(d > 0.05 for d in recent):
            return f"[green]{'↑'*len(recent)}[/]"
        if all(d < -0.05 for d in recent):
            return f"[red]{'↓'*len(recent)}[/]"
        if recent[-1] > 0.05:
            return "[green]↑[/]"
        if recent[-1] < -0.05:
            return "[red]↓[/]"
        return "[yellow]→[/]"
    def _sparkline(values: list[str], width: int = 8) -> str:
        blocks = "▁▂▃▄▅▆▇█"
        floats = [_parse_float(v) for v in values if _parse_float(v) is not None]
        if len(floats) < 2:
            return " " * width
        mn, mx = min(floats), max(floats)
        rng    = mx - mn or 1e-9
        scaled = [int((f - mn) / rng * (len(blocks)-1)) for f in floats[-width:]]
        return "".join(blocks[s] for s in scaled)
    def _alert_check(name: str,
                     deltas: list[Optional[float]]) -> list[str]:
        alerts = []
        latest = next((d for d in reversed(deltas) if d is not None), None)
        floats = [_parse_float]              
        if latest is not None:
            if abs(latest) >= 2.0:
                direction = "surge" if latest > 0 else "drop"
                alerts.append(
                    f"[bold red]HIGH:[/] {name} {direction} of "
                    f"[bold]{latest:+.2f}%[/] in latest quarter"
                )
            elif abs(latest) >= 1.0:
                direction = "increase" if latest > 0 else "decrease"
                alerts.append(
                    f"[yellow]MED:[/] {name} {direction} of "
                    f"[bold]{latest:+.2f}%[/] in latest quarter"
                )
        recent = [d for d in deltas[-4:] if d is not None]
        if len(recent) >= 3:
            if all(d > 0.05 for d in recent[-3:]):
                alerts.append(
                    f"[green]STREAK:[/] {name} rising for "
                    f"{len([d for d in recent if d > 0.05])} consecutive quarters"
                )
            elif all(d < -0.05 for d in recent[-3:]):
                alerts.append(
                    f"[red]STREAK:[/] {name} falling for "
                    f"{len([d for d in recent if d < -0.05])} consecutive quarters"
                )
        return alerts
    console.clear()
    console.print(Panel(
        f"[bold white on blue] MODULE 39 — SHAREHOLDING INTELLIGENCE  v3.0 [/]\n"
        f"Ticker: [cyan]{ticker.upper()}[/]   "
        f"AI: {'[green]■ Ready[/]' if OR_KEY else '[red]■ Off[/]'} "
        f"[dim]({OR_MODEL[:35]})[/]",
        border_style="blue", expand=False
    ))
    console.print(Rule("[bold cyan]Fetching Shareholding Data[/]"))
    console.print(f"  [dim]Scraping Screener.in for {clean_ticker}…[/]")
    scraped = _scrape_screener(clean_ticker)
    if not scraped:
        console.print(
            f"  [bold red]✗ Could not fetch shareholding data for {clean_ticker}.[/]\n"
            "  Check the ticker spelling or try the browser link below."
        )
        url = f"https://www.screener.in/company/{clean_ticker}/#shareholding"
        console.print(f"  [dim]{url}[/]")
        import webbrowser
        if Prompt.ask("  Open in browser? [Y/N]", default="N").upper() == "Y":
            webbrowser.open(url)
        return
    quarters  = scraped['quarters']                                      
    all_rows  = scraped['rows']
    pledge_rws= scraped['pledge_rows']
    source_url= scraped['source_url']
    Q_DISPLAY = 8
    q_display = quarters[:Q_DISPLAY]                                                 
    q_chron   = list(reversed(q_display))                                   
    console.print(
        f"  [green]✓[/] {len(all_rows)} shareholding rows found across "
        f"{len(quarters)} quarters  |  source: [dim]{source_url}[/]"
    )
    yf_data = _yf_holders(ticker.upper())
    CATEGORY_COLOUR = {
        "Promoters": "bold green",
        "FIIs"     : "bold cyan",
        "DIIs"     : "bold yellow",
        "Government": "magenta",
        "Public"   : "white",
        "Others"   : "dim",
        "No. of Shareholders": "dim",
    }
    enriched = []
    all_alerts: list[str] = []
    for row in all_rows:
        name    = row['name']
        raw_vals= row['values']
        vals    = raw_vals[:Q_DISPLAY]
        vals_chron = list(reversed(vals))
        deltas_chron = _compute_deltas(vals_chron)
        deltas_display = list(reversed(deltas_chron))                      
        spark   = _sparkline(vals_chron, width=8)
        arrow   = _trend_arrow(deltas_chron)
        alerts  = _alert_check(name, deltas_chron)
        all_alerts.extend(alerts)
        clr     = CATEGORY_COLOUR.get(name, "dim" if row['is_sub'] else "white")
        enriched.append({
            'name'   : name,
            'vals'   : vals,                          
            'deltas' : deltas_display,                
            'spark'  : spark,
            'arrow'  : arrow,
            'colour' : clr,
            'is_sub' : row['is_sub'],
            'alerts' : alerts,
        })
    def _latest_float(enriched_rows: list[dict]) -> Optional[float]:
        prom_row = next((r for r in enriched_rows
                        if r['name'] == "Promoters"), None)
        govt_row = next((r for r in enriched_rows
                        if r['name'] == "Government"), None)
        prom = _parse_float(prom_row['vals'][0]) if prom_row else None
        govt = _parse_float(govt_row['vals'][0]) if govt_row else 0.0
        if prom is not None:
            return round(100 - prom - (govt or 0.0), 2)
        return None
    public_float = _latest_float(enriched)
    def _row_latest_delta(name: str) -> tuple[Optional[float], Optional[float]]:
        r = next((x for x in enriched if x['name']==name), None)
        if not r: return None, None
        latest = _parse_float(r['vals'][0])
        delta  = r['deltas'][0]
        return latest, delta
    fii_v, fii_d  = _row_latest_delta("FIIs")
    dii_v, dii_d  = _row_latest_delta("DIIs")
    prom_v, prom_d= _row_latest_delta("Promoters")
    fii_dii_div = None
    if fii_d is not None and dii_d is not None:
        fii_dii_div = fii_d - dii_d
    def _fmt(v, d, suffix="%"):
        if v is None: return "N/A"
        dc = ("green" if (d or 0) > 0 else "red" if (d or 0) < 0 else "white")
        ds = f" ([{dc}]{d:+.2f}%[/{dc}])" if d is not None else ""
        return f"[bold]{v:.2f}{suffix}[/]{ds}"
    float_clr = ("red" if public_float is not None and public_float < 25
                 else "yellow" if public_float is not None and public_float < 40
                 else "green" if public_float is not None
                 else "dim")
    float_str = f"{public_float:.2f}%" if public_float is not None else "N/A"
    console.print(Panel(
        f"[bold]Promoter:[/] {_fmt(prom_v,prom_d)}   "
        f"[bold]FII:[/] {_fmt(fii_v,fii_d)}   "
        f"[bold]DII:[/] {_fmt(dii_v,dii_d)}\n"
        f"[bold]Public Float:[/] [{float_clr}]{float_str}[/{float_clr}]  "
        f"[dim](Float <25% = illiquid; >50% = dilution risk)[/]\n"
        + (f"[bold]FII-DII Divergence:[/] "
           f"[{'green' if fii_dii_div and fii_dii_div>0 else 'red'}]"
           f"{fii_dii_div:+.2f}%[/]  "
           f"[dim](+ve = FII buying more than DII; -ve = DII defensive)[/]"
           if fii_dii_div is not None else ""),
        title=f"[bold white]Latest Quarter Snapshot — {ticker.upper()}[/]",
        border_style="cyan", expand=False
    ))
    if all_alerts:
        console.print(Rule("[bold yellow]⚠ Shareholding Alerts[/]"))
        for alert in all_alerts[:10]:
            console.print(f"  • {alert}")
    console.print(Rule("[bold cyan]Shareholding Pattern (QoQ Delta)[/]"))
    main_tbl = Table(
        title=f"{ticker.upper()} — Shareholding % (last {len(q_display)} quarters)",
        border_style="cyan",
        box=_box.SIMPLE_HEAVY,
        show_lines=True,
        expand=True,
    )
    main_tbl.add_column("Entity",   width=26, style="bold", no_wrap=True)
    main_tbl.add_column("Trend",    width=7,  justify="center")
    main_tbl.add_column("Chart",    width=10, justify="left", style="dim")
    for q in q_display:
        main_tbl.add_column(q[:7], width=9, justify="right")
    def _delta_cell(val: str, delta: Optional[float]) -> str:
        v_str = val if val else "—"
        if delta is None:
            return v_str
        dc = "green" if delta > 0.05 else ("red" if delta < -0.05 else "dim")
        d_str = f"\n[{dc}]{delta:+.2f}[/{dc}]" if abs(delta) > 0.001 else ""
        return f"{v_str}{d_str}"
    MACRO_ORDER = [
        "Promoters", "FIIs", "DIIs", "Government",
        "Public", "Others", "No. of Shareholders"
    ]
    macro_rows = {r['name']: r for r in enriched if not r['is_sub']}
    sub_rows   = [r for r in enriched if r['is_sub']]
    for target in MACRO_ORDER:
        row = macro_rows.get(target)
        if row is None:
            continue
        cells = [
            _delta_cell(v, d)
            for v, d in zip(row['vals'], row['deltas'])
        ]
        while len(cells) < len(q_display):
            cells.append("—")
        main_tbl.add_row(
            f"[{row['colour']}]{row['name']}[/{row['colour']}]",
            row['arrow'],
            row['spark'],
            *cells[:len(q_display)]
        )
        parent_lower = target.lower()
        for sub in sub_rows:
            sub_parent = any(
                kw in sub['name'].lower()
                for kw in [parent_lower,
                            parent_lower[:4],                                
                            "promoter" if "promoter" in parent_lower else "",
                            "foreign"  if "fii" in parent_lower else "",
                            "domestic" if "dii" in parent_lower else "",
                            "mutual"   if "dii" in parent_lower else "",
                            "insurance"if "dii" in parent_lower else "",
                            "individual" if "public" in parent_lower else "",
                            ]
            )
            if not sub_parent:
                continue
            sub_cells = [
                _delta_cell(v, d)
                for v, d in zip(sub['vals'], sub['deltas'])
            ]
            while len(sub_cells) < len(q_display):
                sub_cells.append("—")
            main_tbl.add_row(
                f"  [dim]↳ {sub['name'][:22]}[/]",
                sub['arrow'],
                sub['spark'],
                *sub_cells[:len(q_display)]
            )
    for row in enriched:
        if row['is_sub']:
            continue
        if row['name'] in MACRO_ORDER:
            continue
        cells = [
            _delta_cell(v, d)
            for v, d in zip(row['vals'], row['deltas'])
        ]
        while len(cells) < len(q_display):
            cells.append("—")
        main_tbl.add_row(
            f"[dim]{row['name'][:26]}[/]",
            row['arrow'],
            row['spark'],
            *cells[:len(q_display)]
        )
    console.print(main_tbl)
    if pledge_rws:
        console.print(Rule("[bold red]Promoter Pledge Data[/]"))
        p_tbl = Table(
            title="Pledged Promoter Shares",
            border_style="red", box=_box.SIMPLE_HEAVY,
            show_lines=True, expand=False
        )
        p_tbl.add_column("Metric", style="bold red", width=30)
        for q in q_display[:6]:
            p_tbl.add_column(q[:7], width=9, justify="right")
        for pr in pledge_rws:
            vals = pr['values'][:6]
            cells = []
            for v in vals:
                fv = _parse_float(v)
                if fv is not None and fv > 30:
                    cells.append(f"[bold red]{v}[/]")
                elif fv is not None and fv > 10:
                    cells.append(f"[yellow]{v}[/]")
                else:
                    cells.append(v or "—")
            p_tbl.add_row(pr['name'][:28], *cells)
        console.print(p_tbl)
        console.print(
            "  [dim]Pledge >30% = HIGH RISK (margin call could force promoter selling)[/]"
        )
    if yf_data.get('institutional') is not None and not yf_data['institutional'].empty:
        inst = yf_data['institutional']
        if inst is not None and not inst.empty:
            console.print(Rule("[bold cyan]Top Institutional Holders (yfinance)[/]"))
            i_tbl = Table(
                border_style="dim", box=_box.SIMPLE_HEAVY,
                show_lines=False, expand=False
            )
            i_tbl.add_column("Institution",      width=36)
            i_tbl.add_column("Shares",           justify="right", width=16)
            i_tbl.add_column("% Held",           justify="right", width=10)
            i_tbl.add_column("Date Reported",    justify="right", width=14, style="dim")
            for _, row in inst.head(8).iterrows():
                pct = f"{row.get('pctHeld',0)*100:.2f}%" if 'pctHeld' in row else "—"
                shares = f"{int(row.get('Shares',0)):,}" if 'Shares' in row else "—"
                date   = str(row.get('Date Reported',''))[:10] if 'Date Reported' in row else "—"
                name   = str(row.get('Holder',row.get('Name','')))[:34]
                i_tbl.add_row(name, shares, pct, date)
            console.print(i_tbl)
    def _build_digest() -> str:
        lines = [
            f"Company Ticker: {ticker.upper()}",
            f"Latest Quarter Data:",
            f"  Promoter Holding: {prom_v}%  (QoQ: {prom_d:+.2f}%)" if prom_v else "",
            f"  FII Holding: {fii_v}%  (QoQ: {fii_d:+.2f}%)"       if fii_v else "",
            f"  DII Holding: {dii_v}%  (QoQ: {dii_d:+.2f}%)"       if dii_v else "",
            f"  Public Float: {public_float}%"                        if public_float else "",
            f"  FII-DII Divergence: {fii_dii_div:+.2f}%"            if fii_dii_div else "",
            "",
            "Shareholding Trend (last 8 quarters, newest first):",
        ]
        for row in enriched:
            if not row['is_sub'] and row['name'] != "No. of Shareholders":
                vals_str = "  ".join(
                    f"{v}({d:+.2f})" if d else v
                    for v, d in zip(row['vals'][:6], row['deltas'][:6])
                )
                lines.append(f"  {row['name']}: {vals_str}")
        if pledge_rws:
            lines.append("\nPromoter Pledge Data:")
            for pr in pledge_rws:
                lines.append(f"  {pr['name']}: {' | '.join(pr['values'][:4])}")
        if all_alerts:
            lines.append("\nAlert Flags:")
            for a in all_alerts:
                clean = re.sub(r'\[.*?\]','', a)
                lines.append(f"  • {clean}")
        return "\n".join(l for l in lines if l is not None)
