def normalize_cli_ticker(raw, fallback="RELIANCE.NS"):
    ticker = (raw or fallback or "RELIANCE.NS").strip().upper()
    if not ticker:
        return "RELIANCE.NS"
    if ticker.startswith("^") or "." in ticker:
        return ticker
    return f"{ticker}.NS"
def parse_cli_module_ids(values):
    module_ids = []
    seen = set()
    for raw in values or []:
        for part in str(raw).split(","):
            module_id = part.strip()
            if module_id and module_id not in seen:
                seen.add(module_id)
                module_ids.append(module_id)
    return module_ids
def format_module_label(module_fn):
    tokens = module_fn.__name__.removeprefix("run_").split("_")
    special = {
        "ai": "AI",
        "api": "API",
        "arima": "ARIMA",
        "dcf": "DCF",
        "epub": "EPUB",
        "garch": "GARCH",
        "greeks": "Greeks",
        "hmm": "HMM",
        "html": "HTML",
        "ipo": "IPO",
        "lbo": "LBO",
        "lstm": "LSTM",
        "md": "MD",
        "nbfc": "NBFC",
        "ode": "ODE",
        "pdf": "PDF",
        "pnl": "PnL",
        "rl": "RL",
        "xgb": "XGB",
    }
    words = []
    for token in tokens:
        lower = token.lower()
        words.append(special.get(lower, token.upper() if len(token) <= 3 else token.title()))
    return " ".join(words)
def print_module_catalog(module_dispatch):
    print("\nAvailable modules:\n")
    for module_id in sorted(module_dispatch, key=lambda item: int(item)):
        print(f"  {module_id:>2}  {format_module_label(module_dispatch[module_id])}")
    print("\nSome modules still open prompts or charts because they reuse the full terminal workflows.")
def save_active_ticker(ticker, prefs=None):
    prefs = prefs or load_app_prefs()
    _record_ticker(ticker)
    prefs["default_ticker"] = ticker
    save_app_prefs(prefs)
    return prefs
def build_cli_parser():
    examples = (
        "examples:\n"
        "  python stock_analyzer.py\n"
        "  python stock_analyzer.py RELIANCE.NS\n"
        "  python stock_analyzer.py --ticker INFY --snapshot\n"
        "  python stock_analyzer.py --ticker TCS --module 1 --module 7\n"
        "  python stock_analyzer.py --dashboard\n"
        "  python stock_analyzer.py --list-modules"
    )
    parser = argparse.ArgumentParser(
        description="Indian Stock Market Analysis Suite",
        epilog=examples,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument("ticker", nargs="?", help="Ticker symbol such as RELIANCE or RELIANCE.NS.")
    parser.add_argument("-t", "--ticker", dest="ticker_opt", help="Ticker symbol to analyze.")
    parser.add_argument(
        "-m",
        "--module",
        dest="modules",
        action="append",
        default=[],
        metavar="ID",
        help="Run a module number. Repeat the flag or pass comma-separated IDs.",
    )
    parser.add_argument("--snapshot", action="store_true", help="Print the stock snapshot and exit.")
    parser.add_argument("--dashboard", action="store_true", help="Print the live dashboard and exit.")
    parser.add_argument("--list-modules", action="store_true", help="List available module IDs and exit.")
    parser.add_argument("--interactive", action="store_true", help="Launch the existing interactive terminal UI.")
    parser.add_argument("--no-save", action="store_true", help="Do not save the ticker as the default preference.")
    return parser
def cli_main(argv=None):
    parser = build_cli_parser()
    args = parser.parse_args(argv)
    raw_ticker = args.ticker_opt or args.ticker
    module_dispatch = get_module_dispatch()
    module_ids = parse_cli_module_ids(args.modules)
    wants_cli = any([
        raw_ticker,
        args.snapshot,
        args.dashboard,
        args.list_modules,
        module_ids,
    ])
    if args.interactive and wants_cli:
        parser.error("--interactive cannot be combined with other CLI actions.")
    if args.interactive or not wants_cli:
        main()
        return 0
    invalid_modules = [module_id for module_id in module_ids if module_id not in module_dispatch]
    if invalid_modules:
        parser.error(f"Unknown module ID(s): {', '.join(invalid_modules)}")
    if args.list_modules:
        print_module_catalog(module_dispatch)
        return 0
    global _CLI_BATCH_MODE
    _CLI_BATCH_MODE = True
    prefs = load_app_prefs()
    ticker = normalize_cli_ticker(raw_ticker, prefs.get("default_ticker", "RELIANCE.NS"))
    if raw_ticker and not args.no_save:
        prefs = save_active_ticker(ticker, prefs)
    try:
        if args.dashboard:
            movers = fetch_market_movers()
            idx_data = fetch_index_data()
            sector_perf = fetch_sector_performance()
            display_market_dashboard(movers, idx_data, sector_perf)
        if args.snapshot or (raw_ticker and not module_ids and not args.dashboard):
            run_stock_snapshot(ticker)
        for module_id in module_ids:
            label = format_module_label(module_dispatch[module_id])
            print(f"\n[CLI] Running module {module_id}: {label} for {ticker}\n")
            result = module_dispatch[module_id](ticker)
            if isinstance(result, str) and result.strip():
                ticker = normalize_cli_ticker(result, ticker)
                if not args.no_save:
                    prefs = save_active_ticker(ticker, prefs)
    except EOFError:
        print(
            "\nThis command reached an interactive prompt. "
            "Run `python stock_analyzer.py` for the full terminal UI.",
            file=sys.stderr,
        )
        return 1
    finally:
        _CLI_BATCH_MODE = False
    return 0
def main():
    MODULE_DISPATCH = get_module_dispatch()
    prefs = load_app_prefs()
    mode, _ = show_startup_splash(prefs)
    if mode == "dashboard":
        movers      = fetch_market_movers()
        idx_data    = fetch_index_data()
        sector_perf = fetch_sector_performance()
        gainers, losers = display_market_dashboard(movers, idx_data, sector_perf)
        ticker = pick_ticker_enhanced(movers, gainers, losers, idx_data, sector_perf)
    else:
        ticker = prompt_direct_ticker(prefs)
        gainers, losers = [], []
    _record_ticker(ticker)
    prefs["default_ticker"] = ticker
    save_app_prefs(prefs)
    if prefs.get("snapshot_auto", True):
        run_stock_snapshot(ticker)
    while True:
        choice = show_menu(ticker)
        if choice in ("I", "C", "T", "W", "P", "N", "H", "B", "X", "S", "M"):
            ticker, prefs = run_in_session_settings(ticker, prefs, MODULE_DISPATCH)
            continue
        if choice == "Q":
            print("\n  👋  Goodbye! Happy Trading.\n")
            sys.exit(0)
        if choice in MODULE_DISPATCH:
            ret = MODULE_DISPATCH[choice](ticker)
            if isinstance(ret, str) and ret and ret != ticker:
                ticker = ret
                _record_ticker(ticker)
                prefs["default_ticker"] = ticker
                save_app_prefs(prefs)
                print(f"\n  ✔  Active ticker updated to: \033[92m{ticker}\033[0m")
                import time as _t; _t.sleep(0.9)
        else:
            print("  Invalid option. Try again.")
class PredictiveStochasticEngine:
    B   = '\033[1m'
    C   = '\033[96m'
    G   = '\033[92m'
    Y   = '\033[93m'
    R   = '\033[91m'
    M   = '\033[95m'
    RES = '\033[0m'
    DIM = '\033[2m'
    UL  = '\033[4m'
    BBG = '\033[44m\033[97m'
    def __init__(self, ticker: str = "RELIANCE.NS"):
        self.ticker    = ticker or "RELIANCE.NS"
        self.num_times = 252                            
        self.num_paths = 200                                                  
        self.rf_rate   = 0.065                                        
        self.confidence_levels = [0.90, 0.95, 0.99]
        self.spot_price   = 0.0
        self.hist_vol     = 0.0
        self.ewma_vol     = 0.0
        self.drift        = 0.0
        self.skewness     = 0.0
        self.excess_kurt  = 0.0
        self.tail_df      = 5.0                                      
        self.sharpe_hist  = 0.0
        self.max_drawdown = 0.0
        self.autocorr_lag1= 0.0
        self.v0    = 0.04                     
        self.kappa = 3.0                          
        self.theta = 0.04                      
        self.xi    = 0.4                
        self.rho   = -0.7                                                    
        self.jump_freq     = 0.0
        self.jump_mean     = 0.0
        self.jump_std      = 0.0
        self.pos_jump_freq = 0.0
        self.neg_jump_freq = 0.0
        self.garch_omega = 0.0
        self.garch_alpha = 0.0
        self.garch_beta  = 0.0
        self.regime_labels   = []                                           
        self.regime_vol_map  = {}
        self.paths        = None
        self.var_paths    = None                                     
        self.shock_log    = []
        self.risk_metrics = {}
        self.data_loaded  = False
    def _check_dependencies(self) -> bool:
        required = ["numpy", "matplotlib", "yfinance", "pandas", "scipy"]
        missing  = []
        for pkg in required:
            try:
                __import__(pkg)
            except ImportError:
                missing.append(pkg)
        if missing:
            import sys, subprocess
            print(f"  {self.Y}[!] Installing: {', '.join(missing)}{self.RES}")
            try:
                subprocess.check_call([sys.executable, "-m", "pip", "install"] + missing,
                                      stdout=subprocess.DEVNULL)
                print(f"  {self.G}[✓] Done. Please restart the module.{self.RES}")
            except Exception as e:
                print(f"  {self.R}[!] Auto-install failed: {e}{self.RES}")
                return False
        return True
    def fetch_historical_data(self) -> bool:
        B,C,G,Y,R,M,RES,DIM = (self.B,self.C,self.G,self.Y,
                                self.R,self.M,self.RES,self.DIM)
        print(f"\n  {C}[1/6] Downloading OHLCV data for {self.ticker}...{RES}")
        try:
            obj  = yf.Ticker(self.ticker)
            hist = obj.history(period="2y")                                            
            if hist.empty or len(hist) < 60:
                print(f"  {R}[!] Insufficient data. Check ticker symbol.{RES}")
                return False
            hist = hist.ffill().bfill().dropna()
            close    = hist['Close']
            volume   = hist['Volume']
            high     = hist['High']
            low      = hist['Low']
            self.spot_price = float(close.iloc[-1])
            if np.isnan(self.spot_price) or self.spot_price <= 0:
                self.spot_price = 100.0                                      
            log_ret  = np.log(close / close.shift(1)).dropna()
            pct_ret  = close.pct_change().dropna()
            self.hist_vol  = float(log_ret.std() * np.sqrt(252))
            self.ewma_vol  = float(log_ret.ewm(span=30).std().iloc[-1] * np.sqrt(252))
            self.drift     = float(log_ret.ewm(span=60).mean().iloc[-1] * 252)
            print(f"  {C}[2/6] Calibrating fat-tail distribution (Student-t MLE)...{RES}")
            self.skewness    = float(stats.skew(log_ret))
            self.excess_kurt = float(stats.kurtosis(log_ret))                               
            df_fit, loc_fit, scale_fit = stats.t.fit(log_ret, floc=log_ret.mean())
            self.tail_df = max(2.1, float(df_fit))
            print(f"  {C}[3/6] Estimating GARCH(1,1) parameters...{RES}")
            self._fit_garch(log_ret.values)
            print(f"  {C}[4/6] Calibrating Heston SV parameters...{RES}")
            self._calibrate_heston(log_ret.values)
            print(f"  {C}[5/6] Extracting Merton jump events (asymmetric)...{RES}")
            std_dev = log_ret.std()
            all_jumps = log_ret[abs(log_ret) > (2.5 * std_dev)]
            pos_jumps = all_jumps[all_jumps > 0]
            neg_jumps = all_jumps[all_jumps < 0]
            if len(all_jumps) > 0:
                self.jump_freq     = len(all_jumps)
                self.jump_mean     = float(all_jumps.mean())
                self.jump_std      = float(all_jumps.std()) if len(all_jumps) > 1 else abs(float(all_jumps.mean())) * 0.5
                self.pos_jump_freq = len(pos_jumps)
                self.neg_jump_freq = len(neg_jumps)
            else:
                self.jump_freq = 4.0; self.jump_mean = -0.02
                self.jump_std  = 0.04; self.pos_jump_freq = 2; self.neg_jump_freq = 2
            print(f"  {C}[6/6] Running regime detection (HMM-proxy)...{RES}")
            self._detect_regimes(log_ret, close)
            annual_ret = float(log_ret.mean() * 252)
            self.sharpe_hist = (annual_ret - self.rf_rate) / self.hist_vol if self.hist_vol else 0.0
            cum = (1 + pct_ret).cumprod()
            roll_max = cum.cummax()
            dd = (cum - roll_max) / roll_max
            self.max_drawdown = float(dd.min())
            self.autocorr_lag1 = float(log_ret.autocorr(lag=1))
            self.ewma_vol = max(0.05, self.ewma_vol)
            self.drift    = np.clip(self.drift, -0.6, 0.6)
            self.v0       = self.ewma_vol ** 2
            self.theta    = self.hist_vol ** 2
            self.data_loaded = True
            print(f"  {G}[✓] Calibration complete for {self.ticker}{RES}")
            return True
        except Exception as e:
            print(f"  {R}[!] Data fetch error: {e}{RES}")
            import traceback; traceback.print_exc()
            return False
    def _fit_garch(self, returns: 'np.ndarray'):
        n = len(returns)
        mu = returns.mean()
        eps = returns - mu
        var_uncon = eps.var()
        rv5 = np.array([eps[max(0,i-5):i].var() if i>5 else var_uncon for i in range(n)])
        acf1 = float(np.corrcoef(eps[1:]**2, eps[:-1]**2)[0,1])
        persistence = max(0.85, min(0.98, abs(acf1) * 0.5 + 0.92))
        self.garch_alpha = max(0.03, min(0.15, (1 - persistence) * 0.3))
        self.garch_beta  = persistence - self.garch_alpha
        self.garch_omega = var_uncon * (1 - self.garch_alpha - self.garch_beta)
    def _calibrate_heston(self, returns: 'np.ndarray'):
        rv = returns ** 2
        if len(rv) > 10:
            from numpy.polynomial import polynomial as P
            corr = np.corrcoef(rv[1:], rv[:-1])[0,1]
            corr = max(0.01, min(0.999, corr))
            self.kappa = float(np.clip(-252 * np.log(corr), 0.5, 15.0))
        self.theta = float(np.clip(rv.mean(), 0.0009, 4.0))
        self.v0    = float(np.clip(rv[-30:].mean(), 0.0009, 4.0))
        self.xi = float(np.clip(rv.std() * np.sqrt(252) * 2.0, 0.1, 2.0))
        self.rho = float(np.clip(-0.5 - self.skewness * 0.1 if hasattr(self,'skewness') else -0.65, -0.95, -0.1))
    def _detect_regimes(self, log_ret: 'pd.Series', close: 'pd.Series'):
        roll_vol  = log_ret.rolling(20).std() * np.sqrt(252)
        roll_mean = log_ret.rolling(20).mean() * 252
        med_vol   = roll_vol.median()
        self.regime_labels = []
        for rv, rm in zip(roll_vol.fillna(med_vol), roll_mean.fillna(0)):
            if rv > med_vol * 1.8:
                self.regime_labels.append('CRISIS')
            elif rm > 0 and rv <= med_vol * 1.8:
                self.regime_labels.append('BULL')
            else:
                self.regime_labels.append('BEAR')
        for label in ['BULL','BEAR','CRISIS']:
            idxs = [i for i,l in enumerate(self.regime_labels) if l==label]
            if idxs:
                self.regime_vol_map[label] = float(
                    log_ret.iloc[idxs].std() * np.sqrt(252)) if len(idxs)>1 else self.hist_vol
    def generate_vol_surface(self, price_levels: 'np.ndarray', times: 'np.ndarray') -> 'np.ndarray':
        T    = len(times)
        P    = len(price_levels)
        surf = np.zeros((T, P))
        garch_term = np.sqrt(np.clip(
            self.theta + (self.v0 - self.theta) * np.exp(-self.kappa * times / 252.0),
            0.0001, 4.0))
        latest_regime = self.regime_labels[-1] if self.regime_labels else 'BULL'
        regime_mult   = {'BULL': 0.90, 'BEAR': 1.05, 'CRISIS': 1.35}.get(latest_regime, 1.0)
        moneyness = (price_levels - self.spot_price) / self.spot_price           
        for t_idx in range(T):
            base = garch_term[t_idx] * regime_mult
            smile = base * (1.0
                            + self.skewness * 0.15 * moneyness
                            + (3.0 + self.excess_kurt * 0.1) * 0.05 * moneyness**2)
            jump_premium = (self.jump_freq / 252.0) * abs(self.jump_std) * abs(moneyness) * 2.0
            surf[t_idx] = np.clip(smile + jump_premium, 0.01, 3.0)
        return surf
    def simulate_paths(self, vol_surface: 'np.ndarray', price_levels: 'np.ndarray') -> 'np.ndarray':
        N = self.num_paths
        T = self.num_times
        dt = 1.0 / 252.0
        half = N // 2
        all_paths  = np.zeros((N, T))
        all_varpaths = np.zeros((N, T))
        all_paths[:, 0]   = self.spot_price
        all_varpaths[:, 0] = self.v0
        self.shock_log = []
        Z_raw = np.random.normal(0, 1, (half, T - 1, 2))
        Z_raw[:, :, 0] -= Z_raw[:, :, 0].mean(axis=0)
        Z_raw[:, :, 0] /= (Z_raw[:, :, 0].std(axis=0) + 1e-12)
        Z_raw[:, :, 1] -= Z_raw[:, :, 1].mean(axis=0)
        Z_raw[:, :, 1] /= (Z_raw[:, :, 1].std(axis=0) + 1e-12)
        rho_eff = np.clip(self.rho, -0.999, -0.001)
        chol = np.array([[1.0, 0.0],
                         [rho_eff, np.sqrt(1 - rho_eff**2)]])
        W_asset = Z_raw[:, :, 0]
        W_var   = Z_raw[:, :, 0] * chol[1, 0] + Z_raw[:, :, 1] * chol[1, 1]
        W_asset_anti = -W_asset
        W_var_anti   = -W_var
        from scipy.stats import t as student_t
        lambda_pos = self.pos_jump_freq * dt
        lambda_neg = self.neg_jump_freq * dt
        for i in range(1, T):
            j = i - 1                                   
            def _step(s_prev, v_prev, w_s, w_v, path_slice):
                s_prev_clean = np.nan_to_num(s_prev, nan=self.spot_price, posinf=self.spot_price * 100, neginf=1e-8)
                v_prev_clean = np.nan_to_num(v_prev, nan=self.theta, posinf=5.0, neginf=0.0)
                v_prev_pos = np.maximum(v_prev_clean, 0)
                v_new = (v_prev_pos
                         + self.kappa * (self.theta - v_prev_pos) * dt
                         + self.xi * np.sqrt(v_prev_pos * dt) * w_v)
                v_new = np.maximum(np.nan_to_num(v_new, nan=self.theta, posinf=5.0, neginf=0.0), 0)                                
                _pl_range = price_levels[-1] - price_levels[0]
                if _pl_range == 0:
                    _pl_range = 1e-8
                p_pcts = np.clip(
                    (s_prev_clean - price_levels[0]) / _pl_range,
                    0.0, 1.0)
                p_idxs = np.clip(
                    (p_pcts * (len(price_levels) - 1)).astype(int),
                    0, len(price_levels) - 1)
                sigma_surf = vol_surface[i, p_idxs]
                sigma_heston = np.sqrt(v_prev_pos)
                sigma = 0.6 * sigma_heston + 0.4 * sigma_surf
                sigma = np.nan_to_num(sigma, nan=self.hist_vol, posinf=5.0, neginf=0.0)
                gbm = (self.drift - 0.5 * sigma**2) * dt + sigma * np.sqrt(dt) * w_s
                gbm = np.nan_to_num(gbm, nan=0.0, posinf=2.0, neginf=-2.0)
                n_pos = np.random.poisson(lambda_pos, len(s_prev_clean))
                n_neg = np.random.poisson(lambda_neg, len(s_prev_clean))
                j_scale = abs(self.jump_std) + 1e-9
                j_pos_size = student_t.rvs(df=max(2.1, self.tail_df), loc=abs(self.jump_mean),
                                           scale=j_scale, size=len(s_prev_clean))
                j_neg_size = student_t.rvs(df=max(2.1, self.tail_df), loc=-abs(self.jump_mean),
                                           scale=j_scale, size=len(s_prev_clean))
                jump_total = n_pos * np.abs(j_pos_size) - n_neg * np.abs(j_neg_size)
                jump_total = np.nan_to_num(jump_total, nan=0.0, posinf=2.0, neginf=-2.0)
                mask = n_pos + n_neg > 0
                if np.any(mask):
                    mean_impact = float(np.mean(jump_total[mask]))
                    if not np.isnan(mean_impact) and abs(mean_impact) > 0.008:
                        self.shock_log.append((i, mean_impact))
                s_new = s_prev_clean * np.exp(gbm + jump_total)
                s_new = np.nan_to_num(s_new, nan=self.spot_price, posinf=self.spot_price * 100, neginf=1e-8)
                return s_new, v_new
            s_n, v_n = _step(
                all_paths[:half, i-1], all_varpaths[:half, i-1],
                W_asset[:, j], W_var[:, j], slice(0, half))
            all_paths[:half, i]   = s_n
            all_varpaths[:half, i] = v_n
            s_a, v_a = _step(
                all_paths[half:, i-1], all_varpaths[half:, i-1],
                W_asset_anti[:, j], W_var_anti[:, j], slice(half, N))
            all_paths[half:, i]   = s_a
            all_varpaths[half:, i] = v_a
        self.var_paths = all_varpaths
        return all_paths
    def compute_risk_metrics(self, paths: 'np.ndarray') -> dict:
        final  = paths[:, -1]
        ret_1y = (final - self.spot_price) / self.spot_price
        log_ret_sim = np.log(paths[:, 1:] / paths[:, :-1])
        metrics = {}
        metrics['spot']        = self.spot_price
        metrics['mean']        = float(np.mean(final))
        metrics['median']      = float(np.median(final))
        metrics['std']         = float(np.std(final))
        metrics['p01']         = float(np.percentile(final, 1))
        metrics['p05']         = float(np.percentile(final, 5))
        metrics['p10']         = float(np.percentile(final, 10))
        metrics['p25']         = float(np.percentile(final, 25))
        metrics['p75']         = float(np.percentile(final, 75))
        metrics['p90']         = float(np.percentile(final, 90))
        metrics['p95']         = float(np.percentile(final, 95))
        metrics['p99']         = float(np.percentile(final, 99))
        for cl in self.confidence_levels:
            pct = (1 - cl) * 100
            var_price = float(np.percentile(final, pct))
            cvar_price = float(np.mean(final[final <= var_price]))
            metrics[f'VaR_{int(cl*100)}']  = (self.spot_price - var_price) / self.spot_price
            metrics[f'CVaR_{int(cl*100)}'] = (self.spot_price - cvar_price) / self.spot_price
        metrics['prob_profit'] = float(np.mean(final > self.spot_price))
        metrics['prob_10up']   = float(np.mean(final > self.spot_price * 1.10))
        metrics['prob_20up']   = float(np.mean(final > self.spot_price * 1.20))
        metrics['prob_10dn']   = float(np.mean(final < self.spot_price * 0.90))
        metrics['prob_20dn']   = float(np.mean(final < self.spot_price * 0.80))
        metrics['prob_crash']  = float(np.mean(final < self.spot_price * 0.70))
        path_maxdd = []
        for p in paths:
            roll_max = np.maximum.accumulate(p)
            dd_arr   = (p - roll_max) / roll_max
            path_maxdd.append(float(dd_arr.min()))
        path_maxdd = np.array(path_maxdd)
        metrics['avg_maxdd']    = float(path_maxdd.mean())
        metrics['worst_maxdd']  = float(path_maxdd.min())
        metrics['p95_maxdd']    = float(np.percentile(path_maxdd, 5))                      
        sim_annual_ret  = float(np.mean(log_ret_sim) * 252)
        sim_annual_std  = float(np.std(log_ret_sim) * np.sqrt(252))
        downside_std    = float(log_ret_sim[log_ret_sim < 0].std() * np.sqrt(252))
        metrics['sim_sharpe']  = (sim_annual_ret - self.rf_rate) / (sim_annual_std + 1e-9)
        metrics['sim_sortino'] = (sim_annual_ret - self.rf_rate) / (downside_std   + 1e-9)
        thr = self.rf_rate / 252.0
        gains  = log_ret_sim[log_ret_sim > thr] - thr
        losses = thr - log_ret_sim[log_ret_sim <= thr]
        metrics['omega'] = float(gains.sum() / (losses.sum() + 1e-9))
        metrics['calmar'] = float(sim_annual_ret / (abs(metrics['avg_maxdd']) + 1e-9))
        metrics['ret_skew']  = float(stats.skew(ret_1y))
        metrics['ret_kurt']  = float(stats.kurtosis(ret_1y))
        metrics['tail_ratio'] = float(
            abs(np.percentile(ret_1y, 95)) / (abs(np.percentile(ret_1y, 5)) + 1e-9))
        return metrics
    def compute_sensitivity(self) -> dict:
        if not self.data_loaded:
            return {}
        B,C,G,Y,R,M,RES = self.B,self.C,self.G,self.Y,self.R,self.M,self.RES
        print(f"  {M}Computing Greeks-style sensitivities...{RES}", end="", flush=True)
        def quick_run(spot_bump=0, vol_bump=0, drift_bump=0, days_bump=0):
            orig_spot  = self.spot_price
            orig_vol   = self.ewma_vol
            orig_drift = self.drift
            orig_days  = self.num_times
            self.spot_price  += spot_bump
            self.ewma_vol    = max(0.01, self.ewma_vol + vol_bump)
            self.drift       += drift_bump
            self.num_times   = max(21, self.num_times + days_bump)
            P_lev = np.linspace(self.spot_price * 0.5, self.spot_price * 2.0, 40)
            T_arr = np.arange(self.num_times)
            surf  = self.generate_vol_surface(P_lev, T_arr)
            paths = self.simulate_paths(surf, P_lev)
            mean  = float(np.mean(paths[:, -1]))
            self.spot_price  = orig_spot
            self.ewma_vol    = orig_vol
            self.drift       = orig_drift
            self.num_times   = orig_days
            return mean
        base  = quick_run()
        dS    = self.spot_price * 0.01            
        dVol  = 0.01                                   
        dDr   = 0.01                                     
        dT    = 21                                  
        sens = {
            'base_mean':     base,
            'delta_1pct':    (quick_run(spot_bump=+dS) - quick_run(spot_bump=-dS)) / (2 * dS),
            'vega_1vol':     (quick_run(vol_bump=+dVol) - quick_run(vol_bump=-dVol)) / (2 * dVol),
            'drift_sens':    (quick_run(drift_bump=+dDr) - quick_run(drift_bump=-dDr)) / (2 * dDr),
            'theta_1month':   quick_run(days_bump=+dT) - base,
        }
        print(f"  {G}Done.{RES}")
        return sens
    def run_simulation(self):
        if not self.data_loaded and not self.fetch_historical_data():
            return
        from matplotlib.animation import FuncAnimation
        B,C,G,Y,R,M,RES,DIM,BBG = self.B,self.C,self.G,self.Y,self.R,self.M,self.RES,self.DIM,self.BBG
        print(f"  {M}Solving Heston-Merton hybrid matrices...{RES}")
        PRICE_LEVELS = np.linspace(self.spot_price * 0.5, self.spot_price * 2.0, 40)
        TIMES        = np.arange(self.num_times)
        VOL_SURFACE = self.generate_vol_surface(PRICE_LEVELS, TIMES)
        PATHS       = self.simulate_paths(VOL_SURFACE, PRICE_LEVELS)
        PATHS = np.nan_to_num(PATHS, nan=self.spot_price,
                              posinf=self.spot_price * 10,
                              neginf=max(self.spot_price * 0.01, 1e-4))
        PATHS = np.clip(PATHS, 1e-4, self.spot_price * 100)
        if hasattr(self, 'var_paths') and self.var_paths is not None:
            self.var_paths = np.nan_to_num(self.var_paths, nan=self.theta,
                                           posinf=5.0, neginf=0.0)
            self.var_paths = np.clip(self.var_paths, 0.0, 5.0)
        for shock in self.shock_log:
            t_idx, impact = shock
            intensity = abs(impact) * 8.0
            for t in range(t_idx, min(t_idx + 30, len(TIMES))):
                decay = np.exp(-0.12 * (t - t_idx))
                VOL_SURFACE[t, :] += intensity * decay
        VOL_SURFACE = np.clip(VOL_SURFACE, 0.01, 3.0)
        self.risk_metrics = self.compute_risk_metrics(PATHS)
        RM = self.risk_metrics
        print(f"\n  {B}{'═'*65}{RES}")
        print(f"  {B}{self.BBG}  252-DAY PREDICTION REPORT ─ {self.ticker:<12}               {RES}")
        print(f"  {B}{'═'*65}{RES}")
        print(f"  {'Spot Price:':<28} {Y}{self.spot_price:>12,.2f}{RES}")
        print(f"  {'Expected Mean:':<28} {C}{RM['mean']:>12,.2f}{RES}")
        print(f"  {'Median (50th pct):':<28} {C}{RM['median']:>12,.2f}{RES}")
        print(f"  {'99th Percentile:':<28} {G}{RM['p99']:>12,.2f}{RES}")
        print(f"  {'95th Percentile:':<28} {G}{RM['p95']:>12,.2f}{RES}")
        print(f"  {'5th  Percentile:':<28} {R}{RM['p05']:>12,.2f}{RES}")
        print(f"  {'1st  Percentile:':<28} {R}{RM['p01']:>12,.2f}{RES}")
        print(f"  {DIM}{'─'*65}{RES}")
        print(f"  {'VaR 95%  (1-year):':<28} {Y}{RM['VaR_95']*100:>11.2f}%{RES}")
        print(f"  {'CVaR 95% (Exp. Shortfall):':<28} {Y}{RM['CVaR_95']*100:>11.2f}%{RES}")
        print(f"  {'VaR 99%  (1-year):':<28} {R}{RM['VaR_99']*100:>11.2f}%{RES}")
        print(f"  {DIM}{'─'*65}{RES}")
        print(f"  {'Prob. Profitable:':<28} {G}{RM['prob_profit']*100:>11.1f}%{RES}")
        print(f"  {'Prob. +10%:':<28} {G}{RM['prob_10up']*100:>11.1f}%{RES}")
        print(f"  {'Prob. -10%:':<28} {R}{RM['prob_10dn']*100:>11.1f}%{RES}")
        print(f"  {'Prob. Crash (>-30%):':<28} {R}{RM['prob_crash']*100:>11.1f}%{RES}")
        print(f"  {DIM}{'─'*65}{RES}")
        print(f"  {'Sim. Sharpe Ratio:':<28} {C}{RM['sim_sharpe']:>12.3f}{RES}")
        print(f"  {'Sim. Sortino Ratio:':<28} {C}{RM['sim_sortino']:>12.3f}{RES}")
        print(f"  {'Omega Ratio:':<28} {C}{RM['omega']:>12.3f}{RES}")
        print(f"  {'Calmar Ratio:':<28} {C}{RM['calmar']:>12.3f}{RES}")
        print(f"  {'Avg Max Drawdown:':<28} {R}{RM['avg_maxdd']*100:>11.2f}%{RES}")
        print(f"  {'Worst Max Drawdown:':<28} {R}{RM['worst_maxdd']*100:>11.2f}%{RES}")
        print(f"  {B}{'═'*65}{RES}\n")
        print(f"  {G}Rendering 5-panel interactive model...{RES}")
        plt.style.use('dark_background')
        fig = plt.figure(figsize=(22, 12))
        fig.patch.set_facecolor('#0d0d0d')
        fig.canvas.manager.set_window_title(f'Heston-Merton Engine: {self.ticker}')
        gs = gridspec.GridSpec(3, 3, figure=fig, hspace=0.45, wspace=0.35)
        ax3d   = fig.add_subplot(gs[0:2, 0:2], projection='3d')                    
        ax_mc  = fig.add_subplot(gs[0, 2])                                             
        ax_dd  = fig.add_subplot(gs[1, 2])                                                 
        ax_ret = fig.add_subplot(gs[2, 0])                                                    
        ax_vol = fig.add_subplot(gs[2, 1])                                                  
        ax_sts = fig.add_subplot(gs[2, 2])                                           
        cmap = plt.get_cmap('inferno')
        final_rets = (PATHS[:, -1] - self.spot_price) / self.spot_price * 100
        final_rets = final_rets[np.isfinite(final_rets)]                              
        if len(final_rets) == 0:
            final_rets = np.array([0.0])                                  
        ax_ret.hist(final_rets, bins=60, color='#5566ff', edgecolor='none',
                    alpha=0.75, density=True, label='Simulated Returns')
        x_fit = np.linspace(final_rets.min(), final_rets.max(), 200)
        t_params = stats.t.fit(final_rets)
        ax_ret.plot(x_fit, stats.t.pdf(x_fit, *t_params), 'r-', lw=2, label=f'Student-t fit (df={t_params[0]:.1f})')
        ax_ret.plot(x_fit, stats.norm.pdf(x_fit, final_rets.mean(), final_rets.std()), 'y--', lw=1.5, alpha=0.7, label='Normal approx')
        ax_ret.axvline(0, color='white', ls='--', alpha=0.4)
        ax_ret.axvline(np.percentile(final_rets, 5), color='red', ls=':', alpha=0.9, label='5th pct (VaR)')
        ax_ret.set_title('1Y Return Distribution', color='white', fontsize=9)
        ax_ret.set_xlabel('Return (%)', color='#aaa', fontsize=8)
        ax_ret.legend(fontsize=7, facecolor='#1a1a1a')
        ax_ret.tick_params(colors='#aaa', labelsize=7)
        vol_paths = np.sqrt(self.var_paths) * np.sqrt(252) * 100                
        median_vol = np.median(vol_paths, axis=0)
        pct5_vol   = np.percentile(vol_paths, 5,  axis=0)
        pct95_vol  = np.percentile(vol_paths, 95, axis=0)
        ax_vol.fill_between(TIMES, pct5_vol, pct95_vol, alpha=0.3, color='#ff9944', label='5–95% band')
        ax_vol.plot(TIMES, median_vol, color='#ff9944', lw=1.5, label='Median vol')
        ax_vol.axhline(self.ewma_vol * 100, color='cyan', ls='--', lw=1, alpha=0.7, label='EWMA vol')
        ax_vol.axhline(np.sqrt(self.theta) * np.sqrt(252) * 100, color='white', ls=':', lw=1, alpha=0.5, label='LR vol (θ)')
        ax_vol.set_title('Heston Variance Process (Ann. %)', color='white', fontsize=9)
        ax_vol.set_xlabel('Days', color='#aaa', fontsize=8)
        ax_vol.legend(fontsize=7, facecolor='#1a1a1a')
        ax_vol.tick_params(colors='#aaa', labelsize=7)
        path_dd_min = []
        for p in PATHS:
            roll_max = np.maximum.accumulate(p)
            roll_max_safe = np.where(roll_max == 0, 1e-8, roll_max)            
            dd = ((p - roll_max_safe) / roll_max_safe) * 100
            min_dd = float(np.nanmin(dd))
            if np.isfinite(min_dd):
                path_dd_min.append(min_dd)
        path_dd_min = np.array(path_dd_min) if path_dd_min else np.array([0.0])
        ax_dd.hist(path_dd_min, bins=50, color='#cc3344', edgecolor='none', alpha=0.8, density=True)
        ax_dd.axvline(np.mean(path_dd_min), color='orange', ls='--', lw=1.5, label=f'Mean DD: {np.mean(path_dd_min):.1f}%')
        ax_dd.axvline(np.percentile(path_dd_min, 5), color='red', ls=':', lw=1.5, label=f'95th worst: {np.percentile(path_dd_min,5):.1f}%')
        ax_dd.set_title('Max Drawdown Distribution', color='white', fontsize=9)
        ax_dd.set_xlabel('Max Drawdown (%)', color='#aaa', fontsize=8)
        ax_dd.legend(fontsize=7, facecolor='#1a1a1a')
        ax_dd.tick_params(colors='#aaa', labelsize=7)
        ax_sts.axis('off')
        regime = self.regime_labels[-1] if self.regime_labels else 'N/A'
        regime_col = {'BULL': '#00ee66', 'BEAR': '#ffaa33', 'CRISIS': '#ff3344'}.get(regime, 'white')
        tbl_data = [
            ['Metric', 'Value'],
            ['EWMA Vol', f"{self.ewma_vol*100:.1f}%"],
            ['Hist Vol', f"{self.hist_vol*100:.1f}%"],
            ['Heston θ', f"{np.sqrt(self.theta)*np.sqrt(252)*100:.1f}%"],
            ['κ (mean-rev)', f"{self.kappa:.2f}"],
            ['ξ (vol-of-vol)', f"{self.xi:.2f}"],
            ['ρ (leverage)', f"{self.rho:.2f}"],
            ['Jump λ', f"{self.jump_freq:.0f}/yr"],
            ['Jump μ', f"{self.jump_mean*100:.2f}%"],
            ['Tail df (t)', f"{self.tail_df:.1f}"],
            ['Skewness', f"{self.skewness:.3f}"],
            ['Ex.Kurtosis', f"{self.excess_kurt:.3f}"],
            ['GARCH α', f"{self.garch_alpha:.3f}"],
            ['GARCH β', f"{self.garch_beta:.3f}"],
            ['Hist Sharpe', f"{self.sharpe_hist:.3f}"],
            ['Max Hist DD', f"{self.max_drawdown*100:.1f}%"],
            ['Regime', regime],
        ]
        y_pos = 0.98
        for row in tbl_data:
            if row[0] == 'Metric':
                ax_sts.text(0.02, y_pos, row[0], fontsize=8, color='#aaaaaa',
                            fontweight='bold', transform=ax_sts.transAxes)
                ax_sts.text(0.58, y_pos, row[1], fontsize=8, color='#aaaaaa',
                            fontweight='bold', transform=ax_sts.transAxes)
            else:
                col = regime_col if row[0] == 'Regime' else 'white'
                ax_sts.text(0.02, y_pos, row[0], fontsize=7.5, color='#888888',
                            transform=ax_sts.transAxes)
                ax_sts.text(0.58, y_pos, row[1], fontsize=7.5, color=col,
                            transform=ax_sts.transAxes)
            y_pos -= 0.057
        ax_sts.set_title('Model Parameters', color='white', fontsize=9)
        surf_obj = [None]
        mc_lines = []
        def _init_3d():
            ax3d.clear()
            X, Y_g = np.meshgrid(PRICE_LEVELS, TIMES)
            surf_obj[0] = ax3d.plot_surface(X, Y_g, VOL_SURFACE,
                                            cmap=cmap, edgecolor='none', alpha=0.88)
            ax3d.set_xlabel('\nPrice', fontsize=8, color='#aaa')
            ax3d.set_ylabel('\nDays', fontsize=8, color='#aaa')
            ax3d.set_zlabel('\nσ (vol)', fontsize=8, color='#aaa')
            ax3d.set_title(f'{self.ticker} — Heston-Merton Vol Surface\n'
                           f'Regime: {regime}  |  κ={self.kappa:.1f}  ξ={self.xi:.2f}  ρ={self.rho:.2f}',
                           color='white', fontsize=9, pad=12)
            ax3d.tick_params(colors='#666', labelsize=7)
            ax3d.view_init(elev=28, azim=55)
        def _init_mc():
            ax_mc.clear()
            for _ in range(self.num_paths):
                ln, = ax_mc.plot([], [], lw=0.9, alpha=0.45)
                mc_lines.append(ln)
            _spot = float(self.spot_price)
            if np.isnan(_spot) or _spot <= 0: _spot = 100.0
            ylo = min(PRICE_LEVELS[0], RM.get('p01', _spot * 0.5) * 0.95)
            yhi = max(PRICE_LEVELS[-1], RM.get('p99', _spot * 1.5) * 1.05)
            ylo = float(ylo)
            yhi = float(yhi)
            if not np.isfinite(ylo) or ylo <= 0:
                ylo = _spot * 0.1
            if not np.isfinite(yhi) or yhi <= ylo:
                yhi = max(ylo * 2.0, _spot * 2.0)
            ax_mc.set_xlim(0, self.num_times)
            ax_mc.set_ylim(ylo, yhi)
            ax_mc.set_title('Monte Carlo Paths (Heston-Merton)', color='white', fontsize=9)
            ax_mc.set_xlabel('Days', color='#aaa', fontsize=8)
            ax_mc.axhline(self.spot_price, color='gray',  ls='--', lw=1, alpha=0.5, label='Spot')
            ax_mc.axhline(RM.get('median', self.spot_price), color='cyan', ls='-', lw=1.3, alpha=0.85, label='Median')
            ax_mc.axhline(RM.get('p95', self.spot_price*1.2), color='lime', ls=':', lw=1, alpha=0.8, label='95th pct')
            ax_mc.axhline(RM.get('p05', self.spot_price*0.8), color='red', ls=':', lw=1, alpha=0.8, label='5th pct')
            ax_mc.axhspan(RM.get('p01', self.spot_price*0.5), RM.get('p05', self.spot_price*0.8), alpha=0.12, color='red', label='CVaR zone')
            ax_mc.legend(fontsize=7, facecolor='#1a1a1a', loc='upper left')
            ax_mc.tick_params(colors='#aaa', labelsize=7)
        _init_3d()
        _init_mc()
        def update(frame):
            if surf_obj[0] is not None:
                surf_obj[0].remove()
            X, Y_g = np.meshgrid(PRICE_LEVELS, TIMES)
            Z = VOL_SURFACE.copy()
            for t in range(frame + 1, self.num_times):
                Z[t, :] = (self.ewma_vol
                           + abs(PRICE_LEVELS - self.spot_price) / self.spot_price
                           * (self.ewma_vol * 0.5))
            surf_obj[0] = ax3d.plot_surface(X, Y_g, Z, cmap=cmap,
                                            edgecolor='none', alpha=0.88)
            ax3d.view_init(elev=28, azim=55 + frame * 0.12)
            for i, line in enumerate(mc_lines):
                line.set_data(np.arange(min(frame, self.num_times)),
                              PATHS[i, :min(frame, self.num_times)])
                if 0 < frame < self.num_times:
                    p_idx = int(np.clip(
                        (PATHS[i, frame - 1] - PRICE_LEVELS[0])
                        / (PRICE_LEVELS[-1] - PRICE_LEVELS[0])
                        * (len(PRICE_LEVELS) - 1), 0, len(PRICE_LEVELS) - 1))
                    local_vol = VOL_SURFACE[frame - 1, p_idx]
                    colour_val = np.clip((local_vol - self.ewma_vol * 0.5)
                                        / (self.ewma_vol * 1.5 + 0.001), 0, 1)
                    line.set_color(cmap(colour_val))
            return [surf_obj[0]] + mc_lines
        anim = FuncAnimation(fig, update, frames=self.num_times,
                             interval=20, blit=False, repeat=False)
        plt.tight_layout()
        plt.show()
    def run_sensitivity_report(self):
        B   = self.B
        C   = self.C
        G   = self.G
        Y   = self.Y
        R   = self.R
        M   = self.M
        RES = self.RES
        DIM = self.DIM
        BBG = self.BBG
        sens = self.compute_sensitivity()
        if not sens:
            print(f"  {R}[!] Load data first.{RES}")
            return
        print(f"\n  {B}{'='*55}{RES}")
        print(f"  {BBG}  GREEKS-STYLE SENSITIVITY REPORT - {self.ticker:<10}  {RES}")
        print(f"  {B}{'='*55}{RES}")
        print(f"  {'Base Expected Price:':<35} {C}{sens['base_mean']:>10,.2f}{RES}")
        print(f"  {DIM}{'-'*55}{RES}")
        print(f"  {'Delta (per 1% spot move):':<35} {Y}{sens['delta_1pct']:>+10.4f}{RES}")
        print(f"  {'Vega  (per 1 vol-pt move):':<35} {Y}{sens['vega_1vol']:>+10.4f}{RES}")
        print(f"  {'Drift Sensitivity (per 1%):':<35} {Y}{sens['drift_sens']:>+10.4f}{RES}")
        print(f"  {'Theta (+1 month horizon):':<35} {Y}{sens['theta_1month']:>+10.4f}{RES}")
        print(f"  {B}{'='*55}{RES}\n")
    def interactive_menu(self):
        if not self._check_dependencies():
            return
        B,C,G,Y,R,M,RES,DIM,UL,BBG = (self.B,self.C,self.G,self.Y,self.R,
                                         self.M,self.RES,self.DIM,self.UL,self.BBG)
        if not self.data_loaded:
            self.fetch_historical_data()
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            regime       = self.regime_labels[-1] if self.regime_labels else 'N/A'
            regime_c     = {'BULL': G, 'BEAR': Y, 'CRISIS': R}.get(regime, C)
            RM = self.risk_metrics
            print(f"\n  {BBG}  HESTON-MERTON PREDICTIVE ENGINE v2  ─  {self.ticker:<12}         {RES}")
            print("  " + "═" * 76)
            if self.data_loaded:
                print(f"  {B}{'Spot Price:':<22}{RES} {Y}₹{self.spot_price:>12,.2f}{RES}")
                print(f"  {B}{'EWMA Volatility:':<22}{RES} {self.ewma_vol*100:.2f}%  "
                      f"{DIM}(Hist: {self.hist_vol*100:.2f}%  LR: {(self.theta**0.5)*(252**0.5)*100:.2f}%){RES}")
                print(f"  {B}{'EMA Drift (Ann.):':<22}{RES} {(G if self.drift>0 else R)}{self.drift*100:+.2f}%{RES}")
                print(f"  {B}{'Skewness / Kurtosis:':<22}{RES} {self.skewness:.3f} / {self.excess_kurt:.3f}  "
                      f"{DIM}(Tail df={self.tail_df:.1f}){RES}")
                print(f"  {B}{'Market Regime:':<22}{RES} {regime_c}{B}{regime}{RES}  "
                      f"{DIM}(κ={self.kappa:.2f}  ξ={self.xi:.2f}  ρ={self.rho:.2f}){RES}")
                print(f"\n  {M}{B}Fat-Tail Jump Analysis (24-month window):{RES}")
                print(f"  {'Total Jumps:':<22} {Y}{int(self.jump_freq)} events/yr{RES}  "
                      f"{DIM}(+{int(self.pos_jump_freq)} up / -{int(self.neg_jump_freq)} down){RES}")
                print(f"  {'Avg Jump Size:':<22} {(R if self.jump_mean<0 else G)}{self.jump_mean*100:.2f}%{RES}  "
                      f"{DIM}(σ={self.jump_std*100:.2f}%){RES}")
                if RM:
                    print(f"\n  {C}{B}Last Simulation Results:{RES}")
                    print(f"  {'Prob. of Profit:':<22} {G}{RM.get('prob_profit',0)*100:.1f}%{RES}  "
                          f"{'Prob. Crash:':<18} {R}{RM.get('prob_crash',0)*100:.1f}%{RES}")
                    print(f"  {'VaR 95% (1yr):':<22} {Y}{RM.get('VaR_95',0)*100:.2f}%{RES}  "
                          f"{'CVaR 95%:':<18} {R}{RM.get('CVaR_95',0)*100:.2f}%{RES}")
                    print(f"  {'Sim Sharpe:':<22} {C}{RM.get('sim_sharpe',0):.3f}{RES}  "
                          f"{'Sortino:':<18} {C}{RM.get('sim_sortino',0):.3f}{RES}")
                    print(f"  {'Omega Ratio:':<22} {C}{RM.get('omega',0):.3f}{RES}  "
                          f"{'Calmar:':<18} {C}{RM.get('calmar',0):.3f}{RES}")
            else:
                print(f"  {R}[!] Data not loaded. Please change ticker.{RES}")
            print("  " + "═" * 76)
            print(f"  {B}Parameters:{RES}")
            print(f"  {'Paths:':<22} {Y}{self.num_paths}{RES}  (×2 via antithetic = {self.num_paths*2} effective)")
            print(f"  {'Horizon:':<22} {Y}{self.num_times}{RES} trading days")
            print(f"  {'Risk-free rate:':<22} {Y}{self.rf_rate*100:.2f}%{RES}")
            print("  " + "═" * 76)
            print(f"  {B}L.{RES} {G}Launch 3D Render + Full Report{RES}")
            print(f"  {B}S.{RES} Run Greeks-style Sensitivity Analysis")
            print(f"  {B}T.{RES} Change Ticker")
            print(f"  {B}C.{RES} Change Parameters  (Paths / Horizon / Risk-free Rate)")
            print(f"  {B}H.{RES} Recalibrate Heston Parameters Manually")
            print(f"  {B}0.{RES} Return to Main Menu")
            choice = input(f"\n  Select action: ").strip().upper()
            if choice == '0':
                break
            elif choice == 'L':
                if self.data_loaded:
                    self.run_simulation()
                    input(f"\n  {B}Simulation complete. Press ENTER to continue...{RES}")
                else:
                    input(f"  {R}[!] Cannot simulate without data. Press ENTER...{RES}")
            elif choice == 'S':
                if self.data_loaded:
                    self.run_sensitivity_report()
                    input(f"\n  Press ENTER to continue...")
                else:
                    input(f"  {R}[!] Load data first. Press ENTER...{RES}")
            elif choice == 'T':
                new_t = input(f"  Enter ticker (e.g. TCS.NS, AAPL, NIFTY.NS): ").strip().upper()
                if new_t:
                    self.ticker     = new_t
                    self.data_loaded = False
                    self.risk_metrics = {}
                    self.fetch_historical_data()
            elif choice == 'C':
                try:
                    p = input(f"  Paths [{self.num_paths}]: ").strip()
                    if p.isdigit(): self.num_paths = max(50, int(p))
                    t = input(f"  Horizon days [{self.num_times}]: ").strip()
                    if t.isdigit(): self.num_times = max(21, int(t))
                    r = input(f"  Risk-free rate % [{self.rf_rate*100:.2f}]: ").strip()
                    try:
                        if r: self.rf_rate = float(r) / 100.0
                    except: pass
                except: pass
            elif choice == 'H':
                if not self.data_loaded:
                    input(f"  {R}[!] Load data first. Press ENTER...{RES}")
                    continue
                print(f"  {C}Current Heston params: κ={self.kappa:.2f}  θ={self.theta:.4f}  "
                      f"ξ={self.xi:.2f}  ρ={self.rho:.2f}  v0={self.v0:.4f}{RES}")
                try:
                    k = input(f"  κ kappa (mean-reversion speed) [{self.kappa:.2f}]: ").strip()
                    if k: self.kappa = float(k)
                    x = input(f"  ξ xi (vol-of-vol) [{self.xi:.2f}]: ").strip()
                    if x: self.xi = float(x)
                    r_in = input(f"  ρ rho (leverage corr, neg) [{self.rho:.2f}]: ").strip()
                    if r_in: self.rho = float(r_in)
                    v = input(f"  v0 initial variance [{self.v0:.4f}]: ").strip()
                    if v: self.v0 = float(v)
                except: pass
            else:
                print(f"  {R}[!] Invalid selection.{RES}")
