import os, json, time, threading, warnings
warnings.filterwarnings('ignore')
class GARCH_LSTM_Hybrid:
    def __init__(self, ticker: str = "RELIANCE.NS"):
        self.ticker          = ticker.upper() if ticker else "RELIANCE.NS"
        self.lookback        = 60                             
        self.pred_days       = 10                        
        self.epochs          = 80
        self.batch_size      = 32
        self.hidden_dim      = 128
        self.n_heads         = 4                                    
        self.mc_samples      = 50                                  
        self.model_type      = "ensemble"                                       
        self.use_attention   = True
        self.period          = "5y"
        self._data_ready     = False
        self._model_trained  = False
        self._hist           = None
        self._feature_names  : list[str] = []
        self._scaler         = None
        self._price_scaler   = None
        self._models         : dict      = {}
        self._val_losses     : dict      = {}
        self._forecast       : Optional[dict] = None
        self._backtest       : Optional[dict] = None
        self._or_key   = _GLOBAL_OR_KEY
        self._or_model = _GLOBAL_OR_MODEL
        self._load_or_config()
    def _load_or_config(self):
        self._or_key   = _GLOBAL_OR_KEY
        self._or_model = _GLOBAL_OR_MODEL
    def _save_or_config(self):
        try:
            pass                                            
        except: pass
    def _check_deps(self) -> bool:
        missing = []
        for pkg in ['torch','arch','yfinance','pandas',
                    'numpy','sklearn','scipy']:
            try: __import__(pkg.replace('-','_'))
            except ImportError: missing.append(pkg)
        if not missing:
            return True
        import sys, subprocess
        from rich.console import Console
        console = Console()
        console.print(
            f"  [yellow]Installing: {', '.join(missing)}…[/]"
        )
        try:
            subprocess.check_call([
                sys.executable, "-m", "pip", "install",
                "torch", "arch", "yfinance", "scikit-learn",
                "scipy", "--quiet", "--break-system-packages"
            ])
            return True
        except Exception as e:
            console.print(f"  [red]Install failed: {e}[/]")
            return False
    def _build_features(self, hist) -> 'np.ndarray':
        from arch import arch_model
        df = hist.copy()
        df.index = pd.to_datetime(df.index)
        df['log_ret'] = np.log(df['Close'] / df['Close'].shift(1))
        rets = df['log_ret'].dropna() * 100
        try:
            gm = arch_model(rets, vol='Garch', p=1, q=1,
                            dist='Normal', rescale=False)
            gres = gm.fit(disp='off', show_warning=False)
            cond_vol = gres.conditional_volatility
            df['garch_vol'] = cond_vol.reindex(df.index).ffill()
        except Exception:
            df['garch_vol'] = df['log_ret'].rolling(21).std() * 100
        df['realised_vol'] = df['log_ret'].rolling(21).std() * np.sqrt(252)
        delta  = df['Close'].diff()
        gain   = delta.clip(lower=0).rolling(14).mean()
        loss   = (-delta.clip(upper=0)).rolling(14).mean()
        rs     = gain / (loss + 1e-9)
        df['rsi'] = 100 - 100 / (1 + rs)
        ema12 = df['Close'].ewm(span=12, adjust=False).mean()
        ema26 = df['Close'].ewm(span=26, adjust=False).mean()
        macd  = ema12 - ema26
        df['macd_signal'] = macd.ewm(span=9, adjust=False).mean()
        df['macd_hist']   = macd - df['macd_signal']
        df['roc_10'] = df['Close'].pct_change(10) * 100
        ema20 = df['Close'].ewm(span=20, adjust=False).mean()
        df['ema20_ratio'] = df['Close'] / ema20 - 1.0
        bb_mid  = df['Close'].rolling(20).mean()
        bb_std  = df['Close'].rolling(20).std()
        bb_up   = bb_mid + 2 * bb_std
        bb_dn   = bb_mid - 2 * bb_std
        df['bb_pos'] = (df['Close'] - bb_dn) / (bb_up - bb_dn + 1e-9)
        df['vol_pct'] = (df['realised_vol']
                         .rolling(252, min_periods=30)
                         .rank(pct=True))
        df['log_vol'] = np.log(df['Volume'].clip(lower=1))
        dow = df.index.dayofweek
        df['day_sin'] = np.sin(2 * np.pi * dow / 5.0)
        df['day_cos'] = np.cos(2 * np.pi * dow / 5.0)
        feature_cols = [
            'log_ret','garch_vol','realised_vol',
            'rsi','macd_signal','macd_hist','roc_10',
            'ema20_ratio','bb_pos','vol_pct',
            'log_vol','day_sin','day_cos',
            'Close',                           
        ]
        self._feature_names = feature_cols
        out = df[feature_cols].dropna()
        return out
    def fetch_and_prepare(self) -> bool:
        from sklearn.preprocessing import RobustScaler
        from rich.console import Console
        from rich.rule    import Rule
        console = Console()
        console.print(Rule(
            f"[bold cyan]Data Preparation — {self.ticker}[/]"
        ))
        console.print(f"  [dim]Downloading {self.period} of OHLCV data…[/]")
        try:
            tk   = yf.Ticker(self.ticker)
            hist = tk.history(period=self.period)
            if hist.empty or len(hist) < 200:
                console.print("  [red]✗ Insufficient data.[/]")
                return False
            self._hist = hist
        except Exception as e:
            console.print(f"  [red]✗ Download failed: {e}[/]")
            return False
        console.print(
            f"  [green]✓[/] {len(hist)} trading days  "
            f"({hist.index[0].date()} → {hist.index[-1].date()})"
        )
        console.print("  [dim]Engineering 14 features (GARCH + technical)…[/]")
        feat_df = self._build_features(hist)
        feat_arr = feat_df.values            
        from sklearn.preprocessing import MinMaxScaler
        self._scaler = RobustScaler()
        scaled_all   = self._scaler.fit_transform(feat_arr)
        self._price_scaler = MinMaxScaler(feature_range=(0, 1))
        self._price_scaler.fit(feat_arr[:, [-1]])                     
        self._close_series = feat_df['Close'].values
        X, y = [], []
        for i in range(self.lookback, len(scaled_all) - self.pred_days):
            X.append(scaled_all[i - self.lookback : i])                      
            y.append(feat_arr[i : i + self.pred_days, -1])                     
        self._X          = np.array(X, dtype=np.float32)
        self._y_raw      = np.array(y, dtype=np.float32)
        self._latest_win = scaled_all[-self.lookback:]                         
        console.print(
            f"  [green]✓[/] Feature tensor: "
            f"X={self._X.shape}  y={self._y_raw.shape}"
        )
        self._data_ready = True
        return True
    def _build_lstm(self, n_feat: int):
        import torch
        import torch.nn as nn
        class Attention(nn.Module):
            def __init__(self, hd):
                super().__init__()
                self.W = nn.Linear(hd*2, 1)
            def forward(self, h):
                e = self.W(h).squeeze(-1)                
                a = torch.softmax(e, dim=1)               
                c = (a.unsqueeze(-1) * h).sum(1)             
                return c
        class GARCHLSTMNet(nn.Module):
            def __init__(self, n_feat, hd, out, use_attn):
                super().__init__()
                self.bilstm = nn.LSTM(
                    n_feat, hd, num_layers=2,
                    batch_first=True, dropout=0.3,
                    bidirectional=True
                )
                self.attn    = Attention(hd) if use_attn else None
                self.dropout = nn.Dropout(0.3)
                self.fc1     = nn.Linear(hd*2, hd)
                self.act     = nn.GELU()
                self.fc2     = nn.Linear(hd, out)
            def forward(self, x):
                h, _ = self.bilstm(x)                           
                if self.attn is not None:
                    c = self.attn(h)
                else:
                    c = h[:, -1, :]
                c = self.dropout(c)
                return self.fc2(self.act(self.fc1(c)))
        return GARCHLSTMNet(n_feat, self.hidden_dim, self.pred_days,
                            self.use_attention)
    def _build_transformer(self, n_feat: int):
        import torch
        import torch.nn as nn
        class PositionalEncoding(nn.Module):
            def __init__(self, d_model, max_len=500):
                super().__init__()
                pe  = torch.zeros(max_len, d_model)
                pos = torch.arange(0, max_len).unsqueeze(1).float()
                div = torch.exp(
                    torch.arange(0, d_model, 2).float()
                    * (-math.log(10000.0) / d_model)
                )
                pe[:, 0::2] = torch.sin(pos * div)
                pe[:, 1::2] = torch.cos(pos * div)
                self.register_buffer('pe', pe.unsqueeze(0))
            def forward(self, x):
                return x + self.pe[:, :x.size(1)]
        class TransformerForecaster(nn.Module):
            def __init__(self, n_feat, d_model, nhead, out):
                super().__init__()
                self.embed  = nn.Linear(n_feat, d_model)
                self.pos    = PositionalEncoding(d_model)
                enc_layer   = nn.TransformerEncoderLayer(
                    d_model=d_model, nhead=nhead,
                    dim_feedforward=d_model*4,
                    dropout=0.2, batch_first=True
                )
                self.enc    = nn.TransformerEncoder(enc_layer, num_layers=2)
                self.pool   = nn.AdaptiveAvgPool1d(1)
                self.head   = nn.Sequential(
                    nn.Linear(d_model, d_model//2),
                    nn.GELU(),
                    nn.Dropout(0.2),
                    nn.Linear(d_model//2, out)
                )
            def forward(self, x):
                x = self.pos(self.embed(x))
                x = self.enc(x)
                x = self.pool(x.transpose(1,2)).squeeze(-1)
                return self.head(x)
        d_model = max(32, self.hidden_dim)
        nhead   = self.n_heads
        while d_model % nhead != 0:
            nhead -= 1
        return TransformerForecaster(n_feat, d_model, nhead, self.pred_days)
    def _build_tcn(self, n_feat: int):
        import torch.nn as nn
        class CausalConv1d(nn.Module):
            def __init__(self, in_ch, out_ch, k, d):
                super().__init__()
                pad  = (k - 1) * d
                self.conv = nn.Conv1d(in_ch, out_ch, k,
                                      dilation=d, padding=pad)
                self.trim = pad
            def forward(self, x):
                return self.conv(x)[:, :, :x.size(2)]
        class TCNBlock(nn.Module):
            def __init__(self, in_ch, out_ch, k, d):
                super().__init__()
                self.net = nn.Sequential(
                    CausalConv1d(in_ch,  out_ch, k, d),
                    nn.BatchNorm1d(out_ch),
                    nn.GELU(),
                    nn.Dropout(0.2),
                    CausalConv1d(out_ch, out_ch, k, d),
                    nn.BatchNorm1d(out_ch),
                    nn.GELU(),
                )
                self.res = (nn.Conv1d(in_ch, out_ch, 1)
                            if in_ch != out_ch else nn.Identity())
            def forward(self, x):
                return self.net(x) + self.res(x)
        class TCN(nn.Module):
            def __init__(self, n_feat, hd, out):
                super().__init__()
                ch = hd
                self.blocks = nn.Sequential(
                    TCNBlock(n_feat, ch,   3, 1),
                    TCNBlock(ch,     ch,   3, 2),
                    TCNBlock(ch,     ch,   3, 4),
                    TCNBlock(ch,     ch*2, 3, 8),
                )
                self.head = nn.Sequential(
                    nn.AdaptiveAvgPool1d(1),
                    nn.Flatten(),
                    nn.Linear(ch*2, out)
                )
            def forward(self, x):
                x = x.transpose(1, 2)
                x = self.blocks(x)
                return self.head(x)
        return TCN(n_feat, self.hidden_dim, self.pred_days)
    def train_models(self) -> bool:
        import torch
        import torch.nn as nn
        import torch.optim as optim
        from sklearn.model_selection import train_test_split
        from rich.console  import Console
        from rich.progress import Progress, BarColumn, TextColumn, TimeRemainingColumn
        from rich.panel    import Panel
        console = Console()
        device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        console.print(
            f"  [dim]Device: [bold]{device}[/]  |  "
            f"Features: {self._X.shape[2]}  |  "
            f"Samples: {self._X.shape[0]}[/]"
        )
        n_feat = self._X.shape[2]
        split  = int(len(self._X) * 0.85)
        X_tr   = torch.tensor(self._X[:split],   dtype=torch.float32)
        y_tr   = torch.tensor(self._y_raw[:split],dtype=torch.float32)
        X_val  = torch.tensor(self._X[split:],   dtype=torch.float32)
        y_val  = torch.tensor(self._y_raw[split:],dtype=torch.float32)
        from sklearn.preprocessing import MinMaxScaler
        _ts = MinMaxScaler()
        y_tr_n  = torch.tensor(
            _ts.fit_transform(y_tr.numpy().reshape(-1,1)
            ).reshape(y_tr.shape), dtype=torch.float32
        )
        y_val_n = torch.tensor(
            _ts.transform(y_val.numpy().reshape(-1,1)
            ).reshape(y_val.shape), dtype=torch.float32
        )
        self._target_scaler = _ts
        from torch.utils.data import TensorDataset, DataLoader
        tr_ds  = TensorDataset(X_tr, y_tr_n)
        tr_dl  = DataLoader(tr_ds, batch_size=self.batch_size, shuffle=False)
        model_builders = {
            'lstm'       : self._build_lstm,
            'transformer': self._build_transformer,
            'tcn'        : self._build_tcn,
        }
        if self.model_type == 'ensemble':
            to_train = ['lstm','transformer','tcn']
        else:
            to_train = [self.model_type]
        self._models       = {}
        self._val_losses   = {}
        for mname in to_train:
            console.print(f"\n  [bold cyan]Training {mname.upper()}…[/]")
            model = model_builders[mname](n_feat).to(device)
            n_params = sum(p.numel() for p in model.parameters())/1e3
            console.print(f"  [dim]Parameters: {n_params:.1f}K[/]")
            opt   = optim.AdamW(model.parameters(), lr=3e-4,
                                weight_decay=1e-4)
            sched = optim.lr_scheduler.OneCycleLR(
                opt, max_lr=3e-3,
                steps_per_epoch=len(tr_dl),
                epochs=self.epochs, pct_start=0.3
            )
            crit  = nn.HuberLoss(delta=0.5)
            best_val  = float('inf')
            patience  = 15
            no_improv = 0
            best_wts  = None
            with Progress(
                TextColumn("[cyan]{task.description}"),
                BarColumn(),
                TextColumn("[progress.percentage]{task.percentage:>3.0f}%"),
                TextColumn("loss={task.fields[loss]:.6f}"),
                TextColumn("val={task.fields[val]:.6f}"),
                TimeRemainingColumn(),
                console=console
            ) as prog:
                task = prog.add_task(
                    mname.upper(),
                    total=self.epochs,
                    loss=0.0, val=0.0
                )
                for epoch in range(self.epochs):
                    model.train()
                    ep_loss = 0.0
                    for xb, yb in tr_dl:
                        xb, yb = xb.to(device), yb.to(device)
                        opt.zero_grad()
                        out  = model(xb)
                        loss = crit(out, yb)
                        loss.backward()
                        nn.utils.clip_grad_norm_(model.parameters(), 1.0)
                        opt.step()
                        sched.step()
                        ep_loss += loss.item()
                    ep_loss /= max(len(tr_dl), 1)
                    model.eval()
                    with torch.no_grad():
                        val_out  = model(X_val.to(device))
                        val_loss = crit(val_out,
                                        y_val_n.to(device)).item()
                    prog.update(task, advance=1,
                                loss=ep_loss, val=val_loss)
                    if val_loss < best_val - 1e-6:
                        best_val  = val_loss
                        best_wts  = {k: v.cpu().clone()
                                     for k, v in model.state_dict().items()}
                        no_improv = 0
                    else:
                        no_improv += 1
                        if no_improv >= patience:
                            console.print(
                                f"  [dim]Early stop @ epoch {epoch+1} "
                                f"(best val={best_val:.6f})[/]"
                            )
                            break
            if best_wts:
                model.load_state_dict(best_wts)
            model.eval()
            self._models[mname]     = model
            self._val_losses[mname] = best_val
            console.print(
                f"  [green]✓ {mname.upper()}[/]  "
                f"best_val_loss={best_val:.6f}"
            )
        self._model_trained = True
        return True
    def forecast(self) -> dict:
        import torch
        from rich.console import Console
        console = Console()
        if not self._model_trained:
            console.print("  [red]Train a model first.[/]")
            return {}
        device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        win_t  = torch.tensor(
            self._latest_win, dtype=torch.float32
        ).unsqueeze(0).to(device)
        all_preds : dict[str, list] = {}
        for mname, model in self._models.items():
            mc_preds = []
            model.train()
            with torch.no_grad():
                for _ in range(self.mc_samples):
                    p = model(win_t).cpu().numpy().flatten()
                    mc_preds.append(p)
            model.eval()
            all_preds[mname] = np.array(mc_preds)                           
        if len(all_preds) > 1:
            weights = {}
            tot_inv = sum(1.0 / (v + 1e-9) for v in self._val_losses.values())
            for mn, vl in self._val_losses.items():
                weights[mn] = (1.0 / (vl + 1e-9)) / tot_inv
            mc_ensemble = sum(
                all_preds[mn] * weights[mn]
                for mn in all_preds
            )
        else:
            mn = list(all_preds.keys())[0]
            mc_ensemble = all_preds[mn]
            weights = {mn: 1.0}
        mean_norm = mc_ensemble.mean(axis=0)                 
        std_norm  = mc_ensemble.std(axis=0)                           
        _ts = self._target_scaler
        mean_price = _ts.inverse_transform(
            mean_norm.reshape(-1, 1)
        ).flatten()
        std_price  = std_norm * (
            _ts.data_max_[0] - _ts.data_min_[0]
        )                             
        last_price = float(self._close_series[-1])
        garch_std_daily = float(self._hist['Close'].pct_change()
                                .std() * last_price)
        garch_component = np.array([
            garch_std_daily * np.sqrt(d+1)
            for d in range(self.pred_days)
        ])
        combined_std = np.sqrt(std_price**2 + garch_component**2)
        self._forecast = {
            'mean'      : mean_price,
            'std'       : combined_std,
            'ci_68_lo'  : mean_price - 1.0 * combined_std,
            'ci_68_hi'  : mean_price + 1.0 * combined_std,
            'ci_95_lo'  : mean_price - 1.96 * combined_std,
            'ci_95_hi'  : mean_price + 1.96 * combined_std,
            'last_price': last_price,
            'weights'   : weights,
            'mc_samples': self.mc_samples,
        }
        return self._forecast
    def backtest(self, n_windows: int = 10) -> dict:
        from rich.console  import Console
        from rich.progress import Progress, SpinnerColumn, TextColumn
        console = Console()
        if not self._data_ready:
            console.print("  [red]Load data first.[/]"); return {}
        console.print(
            f"  [dim]Walk-forward backtest: {n_windows} windows…[/]"
        )
        n     = len(self._X)
        step  = max(1, (n - n_windows * self.pred_days) // n_windows)
        maes, rmses, mapes, dir_accs = [], [], [], []
        import torch
        import torch.nn as nn
        device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        n_feat = self._X.shape[2]
        with Progress(
            SpinnerColumn(),
            TextColumn("[cyan]Walk-forward window {task.completed}/{task.total}[/]"),
            console=console
        ) as prog:
            task = prog.add_task("BT", total=n_windows)
            for w in range(n_windows):
                end_tr  = n - (n_windows - w) * self.pred_days
                if end_tr < self.lookback + 50:
                    prog.advance(task); continue
                X_tr = torch.tensor(
                    self._X[:end_tr], dtype=torch.float32
                ).to(device)
                y_tr_raw = self._y_raw[:end_tr]
                from sklearn.preprocessing import MinMaxScaler
                ts = MinMaxScaler()
                y_tr_n = torch.tensor(
                    ts.fit_transform(
                        y_tr_raw.reshape(-1,1)
                    ).reshape(y_tr_raw.shape),
                    dtype=torch.float32
                ).to(device)
                m = self._build_lstm(n_feat).to(device)
                opt  = torch.optim.Adam(m.parameters(), lr=1e-3)
                crit = nn.HuberLoss()
                for ep in range(min(30, self.epochs)):
                    m.train()
                    opt.zero_grad()
                    out = m(X_tr)
                    loss= crit(out, y_tr_n)
                    loss.backward()
                    opt.step()
                m.eval()
                test_win  = torch.tensor(
                    self._X[end_tr:end_tr+1], dtype=torch.float32
                ).to(device)
                with torch.no_grad():
                    pred_n = m(test_win).cpu().numpy().flatten()
                pred   = ts.inverse_transform(
                    pred_n.reshape(-1,1)
                ).flatten()
                actual = self._y_raw[end_tr].flatten()
                n_pts  = min(len(pred), len(actual))
                pred   = pred[:n_pts]
                actual = actual[:n_pts]
                mae  = np.mean(np.abs(pred - actual))
                rmse = np.sqrt(np.mean((pred - actual)**2))
                mape = np.mean(np.abs((pred - actual)/(actual+1e-9)))*100
                da   = np.mean(np.sign(np.diff(pred)) ==
                               np.sign(np.diff(actual))) * 100
                maes.append(mae)
                rmses.append(rmse)
                mapes.append(mape)
                dir_accs.append(da)
                prog.advance(task)
        if not maes:
            return {}
        self._backtest = {
            'mae'          : float(np.mean(maes)),
            'rmse'         : float(np.mean(rmses)),
            'mape'         : float(np.mean(mapes)),
            'dir_acc'      : float(np.mean(dir_accs)),
            'n_windows'    : n_windows,
            'mae_list'     : maes,
            'rmse_list'    : rmses,
        }
        return self._backtest
    def _render_forecast(self) -> None:
        from rich.console import Console
        from rich.table   import Table
        from rich.panel   import Panel
        from rich.rule    import Rule
        from rich         import box as _box
        console = Console()
        fc      = self._forecast
        if not fc:
            console.print("  [red]No forecast generated.[/]"); return
        lp       = fc['last_price']
        mean     = fc['mean']
        lo68     = fc['ci_68_lo']
        hi68     = fc['ci_68_hi']
        lo95     = fc['ci_95_lo']
        hi95     = fc['ci_95_hi']
        total_chg= (mean[-1] - lp) / lp * 100
        console.print(Rule(
            f"[bold cyan]{self.pred_days}-Day Probabilistic Forecast — {self.ticker}[/]"
        ))
        if len(fc['weights']) > 1:
            wt_str = "  ".join(
                f"[bold]{mn.upper()}[/]={w*100:.0f}%"
                for mn, w in fc['weights'].items()
            )
            console.print(f"  [dim]Ensemble weights: {wt_str}  |  "
                          f"MC samples: {fc['mc_samples']}[/]")
        tbl = Table(
            box=_box.SIMPLE_HEAVY, show_header=True,
            header_style="bold cyan", expand=False
        )
        tbl.add_column("Day",       width=5,  justify="right", style="bold")
        tbl.add_column("Price",     width=12, justify="right")
        tbl.add_column("Δ vs Now",  width=12, justify="right")
        tbl.add_column("68% CI Lo", width=12, justify="right")
        tbl.add_column("68% CI Hi", width=12, justify="right")
        tbl.add_column("Width±",    width=10, justify="right")
        tbl.add_column("Signal",    width=10, justify="center")
        prev = lp
        for i in range(self.pred_days):
            p    = mean[i]
            chg  = p - lp
            d_chg= p - prev
            pc   = "green" if chg > 0 else "red"
            dc   = "green" if d_chg > 0 else "red"
            band = hi68[i] - lo68[i]
            prob_up = (p - lo95[i]) / max(hi95[i] - lo95[i], 1e-9)
            if prob_up > 0.65:
                sig = "[green]▲ BUY[/]"
            elif prob_up < 0.35:
                sig = "[red]▼ SELL[/]"
            else:
                sig = "[yellow]● HOLD[/]"
            tbl.add_row(
                str(i+1),
                f"[bold]{p:>10,.2f}[/]",
                f"[{pc}]{chg:>+10,.2f}[/{pc}]",
                f"{lo68[i]:>10,.2f}",
                f"{hi68[i]:>10,.2f}",
                f"±{band/2:>7,.2f}",
                sig,
            )
            prev = p
        console.print(tbl)
        tc = "green" if total_chg > 0 else "red"
        console.print(
            f"\n  [bold]Forecast Summary:[/]  "
            f"Current=[bold]₹{lp:,.2f}[/]  "
            f"Day-{self.pred_days} median=[bold]₹{mean[-1]:,.2f}[/]  "
            f"({tc}][bold]{total_chg:+.2f}%[/])\n"
            f"  [dim]Bands widen over time (GARCH + epistemic uncertainty).  "
            f"Treat signals as probabilistic, not deterministic.[/]"
        )
        if self._backtest:
            bt = self._backtest
            bc = "green" if bt['dir_acc'] > 55 else "yellow"
            console.print(Panel(
                f"[bold]Walk-Forward Validation ({bt['n_windows']} windows)[/]\n\n"
                f"MAE = [bold]₹{bt['mae']:,.2f}[/]   "
                f"RMSE = [bold]₹{bt['rmse']:,.2f}[/]   "
                f"MAPE = [bold]{bt['mape']:.2f}%[/]   "
                f"Directional Accuracy = [{bc}]{bt['dir_acc']:.1f}%[/{bc}]",
                border_style="cyan", expand=False
            ))
    def _plot_forecast(self) -> None:
        try:
            fc      = self._forecast
            if not fc: return
            plt.style.use('dark_background')
            fig, axes = plt.subplots(2, 1, figsize=(14, 9),
                                     gridspec_kw={'height_ratios':[3,1]})
            ax = axes[0]
            hist_close = self._close_series[-90:]
            hist_x     = range(-len(hist_close), 0)
            fc_x       = range(0, len(fc['mean']))
            ax.plot(hist_x, hist_close, color='#aaaaaa',
                    lw=1.5, label='Historical Close')
            ax.axvline(0, color='#555555', lw=1.5, ls='--', alpha=0.7)
            ax.fill_between(fc_x, fc['ci_95_lo'], fc['ci_95_hi'],
                            alpha=0.18, color='#3498db', label='95% CI')
            ax.fill_between(fc_x, fc['ci_68_lo'], fc['ci_68_hi'],
                            alpha=0.32, color='#3498db', label='68% CI')
            ax.plot(fc_x, fc['mean'], color='#00FFC6',
                    lw=2.5, marker='o', markersize=5,
                    label=f'Median Forecast ({self.model_type.upper()})')
            ax.set_title(
                f"{self.ticker} — {self.pred_days}-Day Probabilistic Forecast "
                f"(GARCH-LSTM v5.0)",
                fontsize=13, fontweight='bold'
            )
            ax.set_ylabel("Price (₹)")
            ax.legend(fontsize=9)
            ax.grid(alpha=0.15)
            ax2   = axes[1]
            widths= fc['ci_95_hi'] - fc['ci_95_lo']
            ax2.bar(fc_x, widths, color='#e74c3c', alpha=0.7)
            ax2.set_ylabel("95% CI Width")
            ax2.set_xlabel("Trading Days from Today")
            ax2.grid(alpha=0.15)
            plt.tight_layout()
            plt.show()
        except ImportError:
            from rich.console import Console
            Console().print("  [yellow]matplotlib not available.[/]")
        except Exception as e:
            from rich.console import Console
            Console().print(f"  [red]Plot error: {e}[/]")
    def _ai_call(self, sys_p: str, user_p: str) -> tuple[str, float]:
        if not self._or_key:
            return "[AI UNAVAILABLE] Configure API key in Settings.", 0.0
        bag  = {}; done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization":f"Bearer {self._or_key}",
                             "Content-Type":"application/json",
                             "X-Title":"Module55-GARCH-LSTM"},
                    json={"model":self._or_model,
                          "messages":[{"role":"system","content":sys_p},
                                      {"role":"user","content":user_p}],
                          "temperature":0.3},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter()-t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter()-t0
            finally: done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin="⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i=0; t0=time.perf_counter()
        while not done.wait(0.5):
            print(f"\r  {spin[i%len(spin)]} AI thinking… "
                  f"{time.perf_counter()-t0:.1f}s   ",
                  end="", flush=True)
            i+=1
        print()
        return bag.get("reply",""), bag.get("latency",0.0)
    def _build_ai_digest(self) -> str:
        lines = [
            f"Ticker: {self.ticker}",
            f"Model Type: {self.model_type.upper()} "
            f"({'ensemble of LSTM+Transformer+TCN' if self.model_type=='ensemble' else ''} )",
            f"Features: 14 (GARCH vol, RSI, MACD, Bollinger, log-return, volume…)",
            f"Lookback: {self.lookback}d  Forecast: {self.pred_days}d  "
            f"Epochs: {self.epochs}",
        ]
        if self._forecast:
            fc = self._forecast
            lp = fc['last_price']
            lines += [
                "",
                f"=== FORECAST (Current price: {lp:.2f}) ===",
                "Day | Median | 68%CI_Lo | 68%CI_Hi | 95%CI_Lo | 95%CI_Hi",
            ]
            for i in range(self.pred_days):
                lines.append(
                    f"{i+1:>3}  {fc['mean'][i]:>9.2f}  "
                    f"{fc['ci_68_lo'][i]:>9.2f}  {fc['ci_68_hi'][i]:>9.2f}  "
                    f"{fc['ci_95_lo'][i]:>9.2f}  {fc['ci_95_hi'][i]:>9.2f}"
                )
            lines.append(
                f"\nTotal forecast change: "
                f"{(fc['mean'][-1]-lp)/lp*100:+.2f}%  "
                f"Band day-10: ±{(fc['ci_95_hi'][-1]-fc['ci_95_lo'][-1])/2:.2f}"
            )
        if self._val_losses:
            lines += ["","=== MODEL VALIDATION LOSSES ==="]
            for mn, vl in self._val_losses.items():
                lines.append(f"  {mn.upper()}: {vl:.6f}")
        if self._backtest:
            bt = self._backtest
            lines += [
                "","=== WALK-FORWARD BACKTEST ===",
                f"MAE={bt['mae']:.2f}  RMSE={bt['rmse']:.2f}  "
                f"MAPE={bt['mape']:.2f}%  DirAcc={bt['dir_acc']:.1f}%",
                f"Windows={bt['n_windows']}",
            ]
        return "\n".join(lines)
