    def run_ai_chat(self, seed_reply: str = "") -> None:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.prompt   import Prompt
        from rich.markdown import Markdown
        console = Console()
        _SYS    = (
            "You are a quantitative analyst and ML engineer.\n"
            "The user has run a GARCH-LSTM-Transformer-TCN ensemble "
            "forecast for a stock.\n"
            "Answer questions about the model architecture, forecast interpretation, "
            "risk management, position sizing, and quantitative finance.\n"
            "Be precise. Cite specific numbers from the forecast data provided."
        )
        digest  = self._build_ai_digest()
        history = [
            {"role":"system",    "content":_SYS},
            {"role":"user",      "content":digest},
            {"role":"assistant", "content": seed_reply or
             "I have reviewed the forecast. Ask me anything about the model, "
             "the predictions, risk management, or underlying statistics."},
        ]
        turn  = 0; _WARN = 7_000
        console.print(Panel(
            "[bold cyan]💬 Forecast Chat[/]\n\n"
            "Ask about model architecture, uncertainty bands, position sizing,\n"
            "GARCH interpretation, or trading signals.\n\n"
            "[bold]Commands:[/]  [cyan]clear[/]   [cyan]exit[/]",
            border_style="cyan", title="[bold white]Chat[/]", expand=False
        ))
        while True:
            est = sum(len(m["content"]) for m in history)//4
            tok = f"[yellow]~{est} ⚠[/]" if est>=_WARN else f"[dim]~{est} tokens[/]"
            q   = Prompt.ask(
                f"\n  [bold cyan]You[/] [dim](turn {turn+1} | {tok})[/]"
            ).strip()
            if not q: continue
            if q.lower()=="exit":  console.print("  [dim]Returning…[/]"); break
            if q.lower()=="clear":
                history=[{"role":"system","content":_SYS}]; turn=0
                console.print("  [green]✓ Cleared.[/]"); continue
            history.append({"role":"user","content":q})
            conv  = "\n".join(
                f"{m['role'].upper()}: {m['content']}" for m in history[1:]
            )
            reply, lat = self._ai_call(_SYS, conv)
            if reply:
                console.print(Panel(
                    Markdown(reply), border_style="green",
                    title=f"[bold green]Assistant[/] [dim]({lat:.2f}s)[/]",
                    expand=False
                ))
                history.append({"role":"assistant","content":reply})
                turn+=1
            else:
                history.pop()
