    def _ckpt_path(self) -> Path:
        return Path(f"transformer56_{self.ticker.replace('.','_')}.ckpt")
    def _check_deps(self) -> bool:
        missing = []
        for pkg in ['torch','yfinance','pandas','numpy','sklearn']:
            try: __import__(pkg.replace('-','_'))
            except ImportError: missing.append(pkg)
        if not missing: return True
        from rich.console import Console
        Console().print(f"  [yellow]Installing: {', '.join(missing)}…[/]")
        try:
            subprocess.check_call([
                sys.executable, "-m", "pip", "install",
                "torch","yfinance","scikit-learn",
                "--quiet","--break-system-packages"
            ])
            return True
        except Exception as e:
            from rich.console import Console
            Console().print(f"  [red]Install failed: {e}[/]")
            return False
    def _build_features(self, hist) -> 'np.ndarray':
        close  = hist['Close'].values.astype(float)
        high   = hist['High'].values.astype(float)
        low    = hist['Low'].values.astype(float)
        open_  = hist['Open'].values.astype(float)
        volume = hist['Volume'].values.astype(float)
        T      = len(close)
        log_ret = np.zeros(T)
        log_ret[1:] = np.log(close[1:] / (close[:-1] + 1e-9))
        roll252 = np.array([
            close[max(0,i-252):i+1].mean() for i in range(T)
        ])
        norm_close = close / (roll252 + 1e-9) - 1.0
        overnight = np.zeros(T)
        overnight[1:] = open_[1:] / (close[:-1] + 1e-9) - 1.0
        rsi14 = _rsi(close, 14) / 100.0
        ema12 = _ema(close, 12)
        ema26 = _ema(close, 26)
        macd  = ema12 - ema26
        sig9  = _ema(macd, 9)
        macd_hist = (macd - sig9) / (close + 1e-9)
        roc5  = np.zeros(T); roc5[5:]  = close[5:]  / close[:-5]  - 1.0
        roc20 = np.zeros(T); roc20[20:]= close[20:] / close[:-20] - 1.0
        vol10 = np.array([
            log_ret[max(0,i-10):i+1].std() for i in range(T)
        ])
        vol30 = np.array([
            log_ret[max(0,i-30):i+1].std() for i in range(T)
        ])
        atr14 = _atr(high, low, close, 14) / (close + 1e-9)
        ema20 = _ema(close, 20)
        ema20_ratio = close / (ema20 + 1e-9) - 1.0
        bb_mid = np.array([close[max(0,i-20):i+1].mean() for i in range(T)])
        bb_std = np.array([close[max(0,i-20):i+1].std()  for i in range(T)])
        bb_up  = bb_mid + 2*bb_std;  bb_dn = bb_mid - 2*bb_std
        bb_pos = (close - bb_dn) / (bb_up - bb_dn + 1e-9)
        bb_pos = bb_pos.clip(0, 1)
        hl_mid = (high + low) / 2.0
        hl_roll= np.array([hl_mid[max(0,i-20):i+1].mean() for i in range(T)])
        vwap_proxy = close / (hl_roll + 1e-9) - 1.0
        log_vol = np.log(volume.clip(1))
        obv_raw = _obv(close, volume)
        obv_std = np.array([
            obv_raw[max(0,i-30):i+1].std() for i in range(T)
        ])
        obv_norm = obv_raw / (obv_std + 1e-9)
        try:
            dow = hist.index.dayofweek.values
        except Exception:
            dow = np.zeros(T)
        day_enc = np.sin(2 * math.pi * dow / 5.0)
        feat = np.column_stack([
            log_ret, norm_close, overnight, rsi14,
            macd_hist, roc5, roc20, vol10, vol30, atr14,
            ema20_ratio, bb_pos, vwap_proxy, log_vol,
            obv_norm, day_enc
        ])
        return np.nan_to_num(feat, nan=0.0, posinf=0.0, neginf=0.0)
    def fetch_and_prepare(self) -> bool:
        from sklearn.preprocessing import RobustScaler
        from rich.console import Console
        from rich.rule    import Rule
        console = Console()
        console.print(Rule(f"[bold cyan]Data Preparation — {self.ticker}[/]"))
        console.print(f"  [dim]Downloading {self.period} OHLCV…[/]")
        try:
            tk   = yf.Ticker(self.ticker)
            hist = tk.history(period=self.period)
            if hist.empty or len(hist) < 150:
                console.print("  [red]✗ Insufficient data.[/]"); return False
            self._hist = hist
        except Exception as e:
            console.print(f"  [red]✗ Download failed: {e}[/]"); return False
        console.print(
            f"  [green]✓[/] {len(hist)} days  "
            f"({hist.index[0].date()} → {hist.index[-1].date()})"
        )
        console.print("  [dim]Engineering 16 features…[/]")
        feat = self._build_features(hist)
        close= hist['Close'].values.astype(float)
        self._close_series = close
        split_idx = int(len(feat) * 0.85)
        self._scaler = RobustScaler()
        self._scaler.fit(feat[:split_idx])
        scaled = self._scaler.transform(feat)
        X, y = [], []
        for i in range(self.seq_len, len(scaled) - self.HORIZON):
            X.append(scaled[i - self.seq_len : i])
            y.append(close[i : i + self.HORIZON])
        X = np.array(X, dtype=np.float32)
        y = np.array(y, dtype=np.float32)
        y_base = np.array([
            close[i - 1]
            for i in range(self.seq_len, len(scaled) - self.HORIZON)
        ], dtype=np.float32)[:, None]
        y_norm = (y - y_base) / (y_base + 1e-9)                  
        split = int(len(X) * 0.85)
        self._X_train, self._X_val = X[:split], X[split:]
        self._y_train, self._y_val = y_norm[:split], y_norm[split:]
        self._y_base_train = y_base[:split]
        self._y_base_val   = y_base[split:]
        self._latest_seq   = scaled[-self.seq_len:]
        self._last_close   = float(close[-1])
        console.print(
            f"  [green]✓[/] Tensor shapes: "
            f"X={X.shape}  y={y_norm.shape}  "
            f"train={split}  val={len(X)-split}"
        )
        self._data_ready = True
        return True
    def _build_model(self):
        import torch
        import torch.nn as nn
        class SinCosPositionalEncoding(nn.Module):
            def __init__(self, d_model, max_len=512):
                super().__init__()
                pe  = torch.zeros(max_len, d_model)
                pos = torch.arange(max_len, dtype=torch.float).unsqueeze(1)
                div = torch.exp(
                    torch.arange(0, d_model, 2).float()
                    * (-math.log(10000.0) / d_model)
                )
                pe[:, 0::2] = torch.sin(pos * div)
                pe[:, 1::2] = torch.cos(pos * div)
                self.register_buffer('pe', pe.unsqueeze(0))
            def forward(self, x):
                return x + self.pe[:, :x.size(1)]
        class DualHeadTransformer(nn.Module):
            def __init__(self, n_feat, d_model, nhead,
                         n_layers, horizon, dropout):
                super().__init__()
                self.input_proj = nn.Sequential(
                    nn.Linear(n_feat, d_model),
                    nn.LayerNorm(d_model),
                )
                self.cls_token = nn.Parameter(torch.zeros(1, 1, d_model))
                nn.init.trunc_normal_(self.cls_token, std=0.02)
                self.pos_enc = SinCosPositionalEncoding(d_model)
                enc_layer = nn.TransformerEncoderLayer(
                    d_model=d_model,
                    nhead=nhead,
                    dim_feedforward=d_model * 4,
                    dropout=dropout,
                    batch_first=True,
                    norm_first=True,                                
                )
                self.encoder = nn.TransformerEncoder(
                    enc_layer, num_layers=n_layers,
                    norm=nn.LayerNorm(d_model)
                )
                self.trunk = nn.Sequential(
                    nn.Dropout(dropout),
                    nn.Linear(d_model, d_model),
                    nn.GELU(),
                )
                self.head_mu  = nn.Linear(d_model, horizon)
                self.head_logv= nn.Linear(d_model, horizon)
            def forward(self, x):
                B = x.size(0)
                x  = self.input_proj(x)
                cls = self.cls_token.expand(B, -1, -1)
                x   = torch.cat([cls, x], dim=1)
                x   = self.pos_enc(x)
                x   = self.encoder(x)
                h   = self.trunk(x[:, 0, :])
                return self.head_mu(h), self.head_logv(h)
        return DualHeadTransformer(
            self.N_FEATURES, self.d_model, self.nhead,
            self.num_layers, self.HORIZON, self.dropout
        )
    def train_model(self) -> bool:
        import torch
        import torch.nn as nn
        import torch.optim as optim
        from torch.utils.data import TensorDataset, DataLoader
        from rich.console  import Console
        from rich.progress import Progress, BarColumn, TextColumn, TimeRemainingColumn
        console = Console()
        device  = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        self._device = device
        console.print(
            f"  [dim]Device: [bold]{device}[/]  |  "
            f"d_model={self.d_model}  heads={self.nhead}  "
            f"layers={self.num_layers}  seq={self.seq_len}[/]"
        )
        model  = self._build_model().to(device)
        n_p    = sum(p.numel() for p in model.parameters()) / 1e3
        console.print(f"  [dim]Parameters: {n_p:.1f}K[/]")
        X_tr = torch.tensor(self._X_train).to(device)
        y_tr = torch.tensor(self._y_train).to(device)
        X_vl = torch.tensor(self._X_val).to(device)
        y_vl = torch.tensor(self._y_val).to(device)
        loader = DataLoader(
            TensorDataset(X_tr, y_tr),
            batch_size=self.batch_size, shuffle=True
        )
        opt    = optim.AdamW(model.parameters(),
                             lr=self.lr, weight_decay=1e-4)
        sched  = optim.lr_scheduler.OneCycleLR(
            opt, max_lr=self.lr * 10,
            steps_per_epoch=len(loader),
            epochs=self.epochs, pct_start=0.3
        )
        def _nll_loss(mu, log_var, target):
            log_var = log_var.clamp(-10, 4)
            return 0.5 * (log_var + (target - mu).pow(2) * (-log_var).exp()).mean()
        best_val  = float('inf')
        no_improv = 0
        best_wts  = None
        with Progress(
            TextColumn("[cyan]{task.description}"),
            BarColumn(),
            TextColumn("[progress.percentage]{task.percentage:>3.0f}%"),
            TextColumn("train={task.fields[tl]:.5f}"),
            TextColumn("val={task.fields[vl]:.5f}"),
            TimeRemainingColumn(),
            console=console
        ) as prog:
            task = prog.add_task(
                "Training", total=self.epochs, tl=0.0, vl=0.0
            )
            for epoch in range(self.epochs):
                model.train()
                ep_loss = 0.0
                for xb, yb in loader:
                    opt.zero_grad()
                    mu, lv = model(xb)
                    loss   = _nll_loss(mu, lv, yb)
                    loss.backward()
                    nn.utils.clip_grad_norm_(model.parameters(), 1.0)
                    opt.step()
                    sched.step()
                    ep_loss += loss.item()
                ep_loss /= max(len(loader), 1)
                model.eval()
                with torch.no_grad():
                    mu_v, lv_v = model(X_vl)
                    val_loss   = _nll_loss(mu_v, lv_v, y_vl).item()
                prog.update(task, advance=1, tl=ep_loss, vl=val_loss)
                if val_loss < best_val - 1e-7:
                    best_val  = val_loss
                    no_improv = 0
                    best_wts  = {k: v.cpu().clone()
                                 for k, v in model.state_dict().items()}
                else:
                    no_improv += 1
                    if no_improv >= self.patience:
                        console.print(
                            f"  [dim]Early stop @ epoch {epoch+1}  "
                            f"best_val={best_val:.5f}[/]"
                        )
                        break
        if best_wts:
            model.load_state_dict(best_wts)
        self._model     = model
        self._val_loss  = best_val
        self._model_trained = True
        console.print(
            f"  [green]✓ Training complete[/]  val_NLL={best_val:.5f}"
        )
        return True
    def forecast(self) -> dict:
        import torch
        from rich.console import Console
        console = Console()
        if not self._model_trained:
            console.print("  [red]Train a model first.[/]"); return {}
        device = self._device or torch.device('cpu')
        win_t  = torch.tensor(
            self._latest_seq, dtype=torch.float32
        ).unsqueeze(0).to(device)
        mu_list  = []
        lv_list  = []
        self._model.train()
        with torch.no_grad():
            for _ in range(self.mc_samples):
                mu, lv = self._model(win_t)
                mu_list.append(mu.cpu().numpy().flatten())
                lv_list.append(lv.cpu().numpy().flatten())
        self._model.eval()
        mu_mc  = np.array(mu_list)                             
        lv_mc  = np.array(lv_list)                                 
        mean_rel = mu_mc.mean(axis=0)
        epist_std= mu_mc.std(axis=0)
        aleat_std= np.exp(0.5 * lv_mc.mean(axis=0))
        combined_std = np.sqrt(epist_std**2 + aleat_std**2)
        base  = self._last_close
        mean_abs = base * (1.0 + mean_rel)
        lo68  = base * (1.0 + mean_rel - 1.00 * combined_std)
        hi68  = base * (1.0 + mean_rel + 1.00 * combined_std)
        lo95  = base * (1.0 + mean_rel - 1.96 * combined_std)
        hi95  = base * (1.0 + mean_rel + 1.96 * combined_std)
        band_width_pct = (hi95 - lo95) / (base + 1e-9) * 100
        confidence     = np.clip(100 - band_width_pct * 4, 5, 95)
        self._forecast = {
            'mean'       : mean_abs,
            'lo68'       : lo68,
            'hi68'       : hi68,
            'lo95'       : lo95,
            'hi95'       : hi95,
            'epist_std'  : epist_std * base,
            'aleat_std'  : aleat_std * base,
            'combined_std': combined_std * base,
            'confidence' : confidence,
            'last_close' : base,
            'mc_samples' : self.mc_samples,
        }
        return self._forecast
    def backtest(self, n_windows: int = 8) -> dict:
        import torch
        import torch.nn as nn
        from rich.console  import Console
        from rich.progress import Progress, SpinnerColumn, TextColumn
        console = Console()
        if not self._data_ready:
            console.print("  [red]Load data first.[/]"); return {}
        device = self._device or torch.device('cpu')
        console.print(
            f"  [dim]Walk-forward ({n_windows} windows)…[/]"
        )
        n    = len(self._X_train) + len(self._X_val)
        step = max(self.HORIZON, n // (n_windows + 1))
        maes, rmses, mapes, dir_accs, sharpes = [], [], [], [], []
        def _nll(mu, lv, y):
            lv = lv.clamp(-10, 4)
            return 0.5*(lv + (y-mu).pow(2)*(-lv).exp()).mean()
        X_all  = np.vstack([self._X_train, self._X_val])
        yb_all = np.vstack([self._y_base_train, self._y_base_val])
        yn_all = np.vstack([self._y_train, self._y_val])
        with Progress(
            SpinnerColumn(),
            TextColumn(
                "[cyan]Window {task.completed}/{task.total}  "
                "mae={task.fields[mae]:.2f}[/]"
            ),
            console=console
        ) as prog:
            task = prog.add_task("BT", total=n_windows, mae=0.0)
            for w in range(n_windows):
                end_tr = n - (n_windows - w) * step
                if end_tr < self.seq_len + 30: continue
                X_tr_ = torch.tensor(X_all[:end_tr],  dtype=torch.float32)
                y_tr_ = torch.tensor(yn_all[:end_tr], dtype=torch.float32)
                X_ts_ = torch.tensor(X_all[end_tr:end_tr+1], dtype=torch.float32)
                yb_ts = yb_all[end_tr]
                m   = self._build_model().to(device)
                o   = torch.optim.AdamW(m.parameters(), lr=self.lr*2)
                s   = torch.optim.lr_scheduler.OneCycleLR(
                    o, max_lr=self.lr*10,
                    steps_per_epoch=max(1,len(X_tr_)//self.batch_size),
                    epochs=min(40, self.epochs)
                )
                for ep in range(min(40, self.epochs)):
                    m.train()
                    idx = torch.randperm(len(X_tr_))[:self.batch_size]
                    xb  = X_tr_[idx].to(device)
                    yb  = y_tr_[idx].to(device)
                    o.zero_grad()
                    mu_, lv_ = m(xb)
                    loss = _nll(mu_, lv_, yb)
                    loss.backward()
                    nn.utils.clip_grad_norm_(m.parameters(), 1.0)
                    o.step(); s.step()
                m.eval()
                with torch.no_grad():
                    mu_p, _ = m(X_ts_.to(device))
                pred_rel = mu_p.cpu().numpy().flatten()[:self.HORIZON]
                pred_abs = yb_ts[0] * (1.0 + pred_rel)
                raw_y = (1.0 + yn_all[end_tr]) * yb_ts[0]
                n_pts = min(len(pred_abs), len(raw_y), self.HORIZON)
                p, a  = pred_abs[:n_pts], raw_y[:n_pts]
                mae  = np.mean(np.abs(p-a))
                rmse = np.sqrt(np.mean((p-a)**2))
                mape = np.mean(np.abs((p-a)/(a+1e-9)))*100
                da   = (np.mean(np.sign(np.diff(p))==
                                np.sign(np.diff(a)))*100
                        if n_pts > 1 else 50.0)
                sig_rets = np.diff(p) * np.sign(np.diff(a))
                sh = (sig_rets.mean()/(sig_rets.std()+1e-9)*
                      np.sqrt(252)) if len(sig_rets)>1 else 0.0
                maes.append(mae); rmses.append(rmse)
                mapes.append(mape); dir_accs.append(da)
                sharpes.append(sh)
                prog.update(task, advance=1, mae=mae)
        if not maes: return {}
        self._backtest = {
            'mae'      : float(np.mean(maes)),
            'rmse'     : float(np.mean(rmses)),
            'mape'     : float(np.mean(mapes)),
            'dir_acc'  : float(np.mean(dir_accs)),
            'sharpe'   : float(np.mean(sharpes)),
            'n_windows': n_windows,
        }
        return self._backtest
    def _render_forecast(self) -> None:
        from rich.console import Console
        from rich.table   import Table
        from rich.panel   import Panel
        from rich.rule    import Rule
        from rich         import box as _box
        console = Console()
        fc = self._forecast
        if not fc:
            console.print("  [red]No forecast.[/]"); return
        lp  = fc['last_close']
        tc  = (fc['mean'][-1] - lp) / lp * 100
        console.print(Rule(
            f"[bold cyan]{self.HORIZON}-Day Probabilistic Forecast — {self.ticker}[/]"
        ))
        console.print(
            f"  [dim]MC samples={fc['mc_samples']}  |  "
            f"d_model={self.d_model}  layers={self.num_layers}  "
            f"heads={self.nhead}[/]"
        )
        tbl = Table(
            box=_box.SIMPLE_HEAVY, show_header=True,
            header_style="bold cyan", expand=False
        )
        tbl.add_column("Day",     width=5,  justify="right", style="bold")
        tbl.add_column("Median",  width=12, justify="right")
        tbl.add_column("Δ%",      width=9,  justify="right")
        tbl.add_column("68% Lo",  width=12, justify="right")
        tbl.add_column("68% Hi",  width=12, justify="right")
        tbl.add_column("95% Lo",  width=12, justify="right")
        tbl.add_column("95% Hi",  width=12, justify="right")
        tbl.add_column("Conf%",   width=7,  justify="right")
        tbl.add_column("Signal",  width=8,  justify="center")
        prev = lp
        for i in range(self.HORIZON):
            p  = fc['mean'][i]
            d  = (p - lp) / lp * 100
            dc = "green" if p > prev else "red"
            conf = fc['confidence'][i]
            cc   = ("bold green" if conf > 70
                    else "yellow" if conf > 45 else "dim")
            prob_up = (p - fc['lo95'][i]) / (fc['hi95'][i] - fc['lo95'][i] + 1e-9)
            if   prob_up > 0.65: sig = "[green]▲ BUY[/]"
            elif prob_up < 0.35: sig = "[red]▼ SELL[/]"
            else:                sig = "[yellow]● HOLD[/]"
            tbl.add_row(
                str(i+1),
                f"[{dc}]₹{p:>10,.2f}[/{dc}]",
                f"[{dc}]{d:>+6.2f}%[/{dc}]",
                f"₹{fc['lo68'][i]:>10,.2f}",
                f"₹{fc['hi68'][i]:>10,.2f}",
                f"₹{fc['lo95'][i]:>10,.2f}",
                f"₹{fc['hi95'][i]:>10,.2f}",
                f"[{cc}]{conf:.0f}%[/{cc}]",
                sig,
            )
            prev = p
        console.print(tbl)
        tc_c = "green" if tc > 0 else "red"
        console.print(
            f"\n  Current: [bold]₹{lp:,.2f}[/]  "
            f"Day-{self.HORIZON} median: [bold]₹{fc['mean'][-1]:,.2f}[/]  "
            f"[{tc_c}]({tc:+.2f}%)[/{tc_c}]\n"
            f"  [dim]Aleatoric (market noise) vs Epistemic (model uncertainty) "
            f"— Day-1: ±₹{fc['aleat_std'][0]:,.2f} vs ±₹{fc['epist_std'][0]:,.2f}[/]"
        )
        if self._backtest:
            bt  = self._backtest
            dac = "green" if bt['dir_acc']>55 else "yellow"
            shc = "green" if bt['sharpe'] >0.5 else "red"
            console.print(Panel(
                f"[bold]Walk-Forward Backtest ({bt['n_windows']} windows)[/]\n\n"
                f"MAE=₹{bt['mae']:.2f}  RMSE=₹{bt['rmse']:.2f}  "
                f"MAPE={bt['mape']:.2f}%  "
                f"DirAcc=[{dac}]{bt['dir_acc']:.1f}%[/{dac}]  "
                f"Sharpe=[{shc}]{bt['sharpe']:.2f}[/{shc}]",
                border_style="cyan", expand=False
            ))
    def _plot_forecast(self) -> None:
        try:
            fc = self._forecast
            if not fc: return
            plt.style.use('dark_background')
            fig, axes = plt.subplots(
                2, 1, figsize=(14, 9),
                gridspec_kw={'height_ratios':[3,1]}
            )
            ax   = axes[0]
            hist = self._close_series[-90:]
            hx   = range(-len(hist), 0)
            fx   = range(0, self.HORIZON)
            ax.plot(hx, hist, color='#aaaaaa', lw=1.5, label='History')
            ax.axvline(0, color='#555', lw=1.5, ls='--')
            ax.fill_between(fx, fc['lo95'], fc['hi95'],
                            alpha=0.18, color='#3498db', label='95% CI')
            ax.fill_between(fx, fc['lo68'], fc['hi68'],
                            alpha=0.32, color='#3498db', label='68% CI')
            ax.plot(fx, fc['mean'], color='#00FFC6', lw=2.5,
                    marker='o', markersize=6,
                    label='Median Forecast')
            ax.set_title(
                f"{self.ticker} — {self.HORIZON}-Day Probabilistic Forecast "
                f"(Deep Transformer v5.0)", fontsize=13, fontweight='bold'
            )
            ax.set_ylabel("Price (₹)")
            ax.legend(fontsize=9); ax.grid(alpha=0.15)
            ax2 = axes[1]
            w   = 0.35
            xs  = np.arange(self.HORIZON)
            ax2.bar(xs - w/2, fc['aleat_std'], w,
                    color='#e74c3c', alpha=0.8, label='Aleatoric (market)')
            ax2.bar(xs + w/2, fc['epist_std'], w,
                    color='#f39c12', alpha=0.8, label='Epistemic (model)')
            ax2.set_ylabel("Uncertainty ±₹")
            ax2.set_xlabel("Forecast Day")
            ax2.legend(fontsize=8); ax2.grid(alpha=0.15)
            ax2.set_xticks(xs)
            ax2.set_xticklabels([f"D{i+1}" for i in xs])
            plt.tight_layout()
            plt.show()
        except Exception as e:
            from rich.console import Console
            Console().print(f"  [red]Plot error: {e}[/]")
    def save_checkpoint(self) -> None:
        import torch
        from rich.console import Console
        if not self._model_trained:
            Console().print("  [red]Nothing to save.[/]"); return
        ckpt = {
            'state_dict': self._model.state_dict(),
            'scaler'    : self._scaler,
            'config'    : {
                'd_model'   : self.d_model,
                'nhead'     : self.nhead,
                'num_layers': self.num_layers,
                'seq_len'   : self.seq_len,
                'dropout'   : self.dropout,
                'HORIZON'   : self.HORIZON,
                'N_FEATURES': self.N_FEATURES,
            },
            'val_loss'   : self._val_loss,
            'last_close' : self._last_close,
        }
        try:
            with open(self._ckpt_path(), 'wb') as f:
                pickle.dump(ckpt, f)
            Console().print(
                f"  [green]✓ Checkpoint saved → {self._ckpt_path()}[/]"
            )
        except Exception as e:
            Console().print(f"  [red]Save failed: {e}[/]")
    def load_checkpoint(self) -> bool:
        import torch
        from rich.console import Console
        p = self._ckpt_path()
        if not p.exists():
            Console().print(f"  [yellow]No checkpoint for {self.ticker}.[/]")
            return False
        try:
            with open(p, 'rb') as f:
                ckpt = pickle.load(f)
            cfg = ckpt['config']
            self.d_model    = cfg['d_model']
            self.nhead      = cfg['nhead']
            self.num_layers = cfg['num_layers']
            self.seq_len    = cfg['seq_len']
            self.dropout    = cfg.get('dropout', 0.15)
            self._scaler    = ckpt['scaler']
            self._val_loss  = ckpt.get('val_loss', None)
            self._last_close= ckpt['last_close']
            device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
            m = self._build_model().to(device)
            m.load_state_dict(ckpt['state_dict'])
            m.eval()
            self._model         = m
            self._device        = device
            self._model_trained = True
            Console().print(
                f"  [green]✓ Loaded checkpoint[/]  "
                f"[dim]val_NLL={self._val_loss:.5f}[/]"
            )
            return True
        except Exception as e:
            Console().print(f"  [red]Load failed: {e}[/]"); return False
    def _ai_call(self, sys_p: str, user_p: str) -> tuple[str, float]:
        if not self._or_key:
            return "[AI UNAVAILABLE] Configure API key in Settings.", 0.0
        bag  = {}; done = threading.Event()
        def _w():
            import requests as _r
            t0 = time.perf_counter()
            try:
                resp = _r.post(
                    "http://127.0.0.1:9999/disabled",
                    headers={"Authorization":f"Bearer {self._or_key}",
                             "Content-Type":"application/json",
                             "X-Title":"Module56-Transformer"},
                    json={"model":self._or_model,
                          "messages":[{"role":"system","content":sys_p},
                                      {"role":"user","content":user_p}],
                          "temperature":0.3},
                    timeout=90,
                )
                resp.raise_for_status()
                bag["reply"]   = resp.json()["choices"][0]["message"]["content"]
                bag["latency"] = time.perf_counter()-t0
            except Exception as e:
                bag["reply"]   = f"[AI ERROR] {e}"
                bag["latency"] = time.perf_counter()-t0
            finally: done.set()
        threading.Thread(target=_w, daemon=True).start()
        spin="⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"; i=0; t0=time.perf_counter()
        while not done.wait(0.5):
            print(
                f"\r  {spin[i%len(spin)]} AI thinking… "
                f"{time.perf_counter()-t0:.1f}s   ",
                end="", flush=True
            )
            i+=1
        print()
        return bag.get("reply",""), bag.get("latency",0.0)
    def _build_ai_digest(self) -> str:
        lines = [
            f"Ticker: {self.ticker}",
            f"Model: Deep Transformer v5.0 (CLS-token, Pre-LN, Dual-Head NLL)",
            f"Architecture: d_model={self.d_model}  heads={self.nhead}  "
            f"layers={self.num_layers}  seq={self.seq_len}d",
            f"Features: 16 (log-ret, RSI, MACD-hist, ATR, BB-pos, OBV, "
            f"EMA-ratio, VWAP-proxy, vol-10/30, 2×ROC, overnight-gap, calendar)",
            f"Uncertainty: MC Dropout ({self.mc_samples} passes) "
            f"+ learned heteroscedastic log-variance",
        ]
        if self._val_loss:
            lines.append(f"Validation NLL Loss: {self._val_loss:.6f}")
        if self._forecast:
            fc = self._forecast
            lp = fc['last_close']
            lines += [
                "",
                f"=== {self.HORIZON}-DAY FORECAST (current ₹{lp:.2f}) ===",
                "Day | Median | 68%Lo | 68%Hi | 95%Lo | 95%Hi | Conf%",
            ]
            for i in range(self.HORIZON):
                lines.append(
                    f"{i+1:>3}  ₹{fc['mean'][i]:>9.2f}  "
                    f"₹{fc['lo68'][i]:>9.2f}  ₹{fc['hi68'][i]:>9.2f}  "
                    f"₹{fc['lo95'][i]:>9.2f}  ₹{fc['hi95'][i]:>9.2f}  "
                    f"{fc['confidence'][i]:.0f}%"
                )
            tc = (fc['mean'][-1]-lp)/lp*100
            lines.append(
                f"Net {self.HORIZON}-day forecast change: {tc:+.2f}%"
            )
        if self._backtest:
            bt = self._backtest
            lines += [
                "",
                f"=== WALK-FORWARD BACKTEST ({bt['n_windows']} windows) ===",
                f"MAE=₹{bt['mae']:.2f}  RMSE=₹{bt['rmse']:.2f}  "
                f"MAPE={bt['mape']:.2f}%  "
                f"DirAcc={bt['dir_acc']:.1f}%  Sharpe={bt['sharpe']:.2f}",
            ]
        return "\n".join(lines)
    def run_ai_forecast_analyst(self) -> str:
        from rich.console  import Console
