    def run_ai_chat(self, seed_reply: str = "") -> None:
        from rich.console  import Console
        from rich.panel    import Panel
        from rich.prompt   import Prompt
        from rich.markdown import Markdown
        console = Console()
        _SYS    = (
            "You are a quantitative ML engineer and financial analyst.\n"
            "The user has run a CLS-token Deep Transformer forecast. "
            "Answer questions about architecture, features, uncertainty "
            "interpretation, trading signals, and risk management.\n"
            "Cite specific numbers from the forecast."
        )
        digest  = self._build_ai_digest()
        history = [
            {"role":"system",    "content":_SYS},
            {"role":"user",      "content":digest},
            {"role":"assistant", "content": seed_reply or
             "I've reviewed the transformer forecast. Ask me anything."},
        ]
        turn=0; _WARN=7_000
        console.print(Panel(
            "[bold cyan]💬 Transformer Forecast Chat[/]\n\n"
            "Ask about uncertainty bands, signal interpretation,\n"
            "model architecture, or trading setup.\n\n"
            "[bold]Commands:[/]  [cyan]clear[/]   [cyan]exit[/]",
            border_style="cyan", expand=False
        ))
        while True:
            est = sum(len(m["content"]) for m in history)//4
            tok = f"[yellow]~{est} ⚠[/]" if est>=_WARN else f"[dim]~{est}t[/]"
            q   = Prompt.ask(
                f"\n  [bold cyan]You[/] [dim](turn {turn+1} | {tok})[/]"
            ).strip()
            if not q: continue
            if q.lower()=="exit":  console.print("  [dim]Returning…[/]"); break
            if q.lower()=="clear":
                history=[{"role":"system","content":_SYS}]; turn=0
                console.print("  [green]✓ Cleared.[/]"); continue
            history.append({"role":"user","content":q})
            conv = "\n".join(f"{m['role'].upper()}: {m['content']}"
                             for m in history[1:])
            reply, lat = self._ai_call(_SYS, conv)
            if reply:
                console.print(Panel(
                    Markdown(reply), border_style="green",
                    title=f"[bold green]Assistant[/] [dim]({lat:.2f}s)[/]",
                    expand=False
                ))
                history.append({"role":"assistant","content":reply})
                turn+=1
            else:
                history.pop()
