def _m57_load_config() -> dict:
    defaults = {
        "api_key":    _GLOBAL_OR_KEY,
        "model_id":   _GLOBAL_OR_MODEL,
        "model_name": _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title(),
    }
    if not os.path.exists(_M57_CONFIG_FILE):
        return defaults
    try:
        with open(_M57_CONFIG_FILE, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        return {**defaults, **data}
    except (json.JSONDecodeError, OSError):
        return defaults                                                    
def _m57_save_config(cfg: dict) -> bool:
    payload = {
        "api_key":    cfg.get("api_key", _GLOBAL_OR_KEY),
        "model_id":   cfg.get("model_id",   _GLOBAL_OR_MODEL),
        "model_name": cfg.get("model_name", _GLOBAL_OR_MODEL.split("/")[-1].replace(":free","(Free)").replace("-"," ").title()),
    }
    try:
        with open(_M57_CONFIG_FILE, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        return True
    except OSError as exc:
        print(f"  \033[93m[!] Could not save config: {exc}\033[0m")
        return False
def _m57_setup_key(cfg: dict) -> dict:
    import getpass, sys
    print("\n  ── API Key Setup (Module 57) ────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M57_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m57_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
    return cfg
def _m57_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models (quant-optimised) ─────────")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 58)
    for i, m in enumerate(_M57_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M57_FREE_MODELS):
            sel               = _M57_FREE_MODELS[idx]
            cfg["model_id"]   = sel["id"]
            cfg["model_name"] = sel["name"]
            _m57_save_config(cfg)
            print(f"  [✓] Switched to {sel['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
def _build_portfolio_context(
    tickers:       List[str],
    risk_free_rate: float,
    data_period:   str,
    trading_days:  int,
    date_range:    dict,
    asset_stats:   dict,
    corr_matrix:   dict,
    session_results: dict,
    frontier_summary: dict,
) -> dict:
    portfolios_serialised = {}
    for strategy_label, pm in session_results.items():
        portfolios_serialised[strategy_label] = {
            "weights":        {t: round(w, 4) for t, w in pm.weights.items()},
            "annual_return":  round(pm.annual_return * 100, 2),         
            "annual_vol":     round(pm.annual_vol * 100, 2),            
            "sharpe":         round(pm.sharpe, 3),
            "sortino":        round(pm.sortino, 3) if not math.isnan(pm.sortino) else None,
            "calmar":         round(pm.calmar, 3)  if not math.isnan(pm.calmar)  else None,
            "var_95_pct":     round(pm.var_95 * 100, 3) if pm.var_95 is not None else None,
            "cvar_95_pct":    round(pm.cvar_95 * 100, 3) if pm.cvar_95 is not None else None,
            "var_99_pct":     round(pm.var_99 * 100, 3) if pm.var_99 is not None else None,
            "cvar_99_pct":    round(pm.cvar_99 * 100, 3) if pm.cvar_99 is not None else None,
            "risk_contributions": {
                t: round(rc * 100, 2)
                for t, rc in pm.risk_contributions.items()
            } if pm.risk_contributions else {},
            "converged":      pm.converged,
        }
    return {
        "portfolio_summary": {
            "tickers":        tickers,
            "risk_free_rate": round(risk_free_rate * 100, 2),
            "data_period":    data_period,
            "trading_days":   trading_days,
            "date_range":     date_range,
            "n_assets":       len(tickers),
        },
        "asset_stats":        asset_stats,
        "correlation_matrix": corr_matrix,
        "optimized_portfolios": portfolios_serialised,
        "frontier_summary":   frontier_summary,
    }
def _build_m57_system_prompt(ctx: dict, model_name: str) -> str:
    import json, textwrap
    tickers = ctx["portfolio_summary"]["tickers"]
    n       = ctx["portfolio_summary"]["n_assets"]
    period  = ctx["portfolio_summary"]["data_period"]
    rf_pct  = ctx["portfolio_summary"]["risk_free_rate"]
    days    = ctx["portfolio_summary"]["trading_days"]
    n_strat = len(ctx["optimized_portfolios"])
    persona = textwrap.dedent(f"""\
        You are a senior portfolio manager and quantitative risk analyst.
        You have just completed a full Markowitz/QAOA optimisation session
        on a {n}-asset universe: {', '.join(tickers)}.
        The analysis covers {days} trading days ({period}) with a {rf_pct}% risk-free rate.
        You ran {n_strat} distinct allocation strategies and computed VaR, CVaR,
        Sortino, Calmar, and per-asset risk contributions for each.
        You are powered by {model_name}.
        Your goal: help the user understand the portfolio results, risk trade-offs,
        and practical implications — at whatever depth they need.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in the <asset_stats>, <correlation>, <portfolios>,
           or <frontier> data.  Never fabricate statistics.
        2. When citing a specific metric, quote it explicitly
           (e.g. "The Max-Sharpe portfolio has CVaR₉₅ = −X.XX%").
        3. Flag concentration risk: any single-asset weight > 40% is
           a red flag and must be surfaced proactively.
        4. Flag correlation risk: corr > 0.75 between two assets in the
           same portfolio means limited diversification — mention this.
        5. Translate risk ratios into plain-English investor profiles:
           Sortino > Sharpe implies asymmetric upside; Calmar > 1 implies
           strong recovery from drawdowns; CVaR >> VaR implies fat tails.
        6. When comparing strategies, structure your response as a table.
        7. Offer concrete next steps: stress tests, factor tilts, ESG
           overlays, rebalancing schedules, hedging with options, etc.
        8. Never recommend a specific stock to buy — focus on allocations
           and risk framework, not stock-picking advice.
        9. Keep responses under 500 words unless the user asks for depth.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Lead every response with: [ALLOCATION] | [RISK] | [REGIME] | [ACTION]
        - **Bold** key financial terms on first use.
        - Use Markdown tables for any multi-strategy comparison.
        - Use > blockquotes when citing statistics directly from the data.
        - Use bullet lists for findings; prose for interpretation.
        - Round all percentages to 2 decimal places in tables.
    """)
    meta_block = (
        f'<portfolio_meta tickers="{",".join(tickers)}" n_assets="{n}" '
        f'period="{period}" trading_days="{days}" '
        f'risk_free_rate_pct="{rf_pct}" '
        f'date_start="{ctx["portfolio_summary"]["date_range"].get("start","")}" '
        f'date_end="{ctx["portfolio_summary"]["date_range"].get("end","")}">'
        f'\n</portfolio_meta>'
    )
    asset_block = (
        "<asset_stats description='per-ticker annualised statistics'>\n"
        + json.dumps(ctx["asset_stats"], indent=2)
        + "\n</asset_stats>"
    )
    corr_block = (
        "<correlation description='Pearson correlation matrix of daily returns'>\n"
        + json.dumps(ctx["correlation_matrix"], indent=2)
        + "\n</correlation>"
    )
    port_block = (
        "<portfolios description='all optimised strategies — weights, metrics, VaR, risk contributions'>\n"
        + json.dumps(ctx["optimized_portfolios"], indent=2)
        + "\n</portfolios>"
    )
    front_block = (
        "<frontier description='efficient frontier endpoints and Monte Carlo summary'>\n"
        + json.dumps(ctx["frontier_summary"], indent=2)
        + "\n</frontier>"
    )
    return "\n\n".join([persona, rules, fmt,
                        meta_block, asset_block,
                        corr_block, port_block, front_block])
def _m57_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        import subprocess, sys
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    import json, time
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS  = 20
    turn_count = (len(history) - 1) // 2
    if turn_count > MAX_TURNS and len(history) > 3:
        del history[1:3]                                    
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 57 Portfolio Optimiser Co-Pilot",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    model_id,
        "messages": history,
        "stream":   True,
    }
    BACKOFF_BASE  = 1.5
    MAX_RETRIES   = 3
    full_response = ""
    last_error    = None
    for attempt in range(MAX_RETRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers,
                json=payload,
                stream=True,
                timeout=(10, 90),                                            
            )
            if resp.status_code == 401:
                console.print(
                    "\n  [bold red][!] API key rejected (401). "
                    "Use /setkey to update.[/bold red]"
                )
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            word_count = 0
            print(f"\n  \033[90m{model_name} is analysing ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        word_count    += len(token.split())
                        if word_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass                                        
            print(f" done ({word_count} words)\033[0m\n")
            if full_response.strip():
                console.print(
                    Panel(
                        Markdown(full_response),
                        title=f"[bold cyan]{model_name}[/bold cyan]",
                        border_style="cyan",
                        padding=(1, 2),
                        expand=True,
                    )
                )
            return full_response
        except requests.Timeout:
            console.print(
                "\n  [bold red][!] Request timed out. "
                "Try a shorter question or /models to switch.[/bold red]"
            )
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < MAX_RETRIES - 1:
                wait = BACKOFF_BASE ** (attempt + 1)
                console.print(
                    f"  [yellow][~] Attempt {attempt + 1} failed ({exc}). "
                    f"Retrying in {wait:.1f}s…[/yellow]"
                )
                time.sleep(wait)
            else:
                console.print(
                    f"  [bold red][!] All {MAX_RETRIES} attempts failed: "
                    f"{last_error}[/bold red]"
                )
    return ""
def _print_m57_chat_help() -> None:
    print("\n  ── Module 57 Portfolio Co-Pilot Commands ────────────")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by full OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter API"),
        ("/compare",     "Ask AI to compare all optimised strategies"),
        ("/risk",        "Ask AI to analyse portfolio tail risk (VaR/CVaR)"),
        ("/regime",      "Ask AI what market regime the data suggests"),
        ("/clear",       "Reset conversation (keeps portfolio context)"),
        ("/export",      "Save session to a timestamped JSON file"),
        ("/status",      "Show model, key, portfolio summary"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to the Optimiser menu"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m57_chat(ctx: dict, cfg: Optional[dict] = None) -> None:
    import json, time
    if cfg is None:
        cfg = _m57_load_config()
    if not cfg["api_key"]:
        print("\n  \033[93m[!] No API key configured for the Portfolio Co-Pilot.\033[0m")
        cfg = _m57_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Configure a key to enable this feature.")
            return
    history = [
        {
            "role":    "system",
            "content": _build_m57_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    B, C_C, G, Y, R, M, RES = (
        '\033[1m', '\033[96m', '\033[92m', '\033[93m',
        '\033[91m', '\033[95m', '\033[0m'
    )
    tickers  = ctx["portfolio_summary"]["tickers"]
    n_strat  = len(ctx["optimized_portfolios"])
    period   = ctx["portfolio_summary"]["data_period"]
    days     = ctx["portfolio_summary"]["trading_days"]
    print("\n" + "─" * 68)
    print(f"  {M}✦ PORTFOLIO AI CO-PILOT{RES}  |  {C_C}{cfg['model_name']}{RES}")
    print(f"  {Y}{', '.join(tickers)}{RES}")
    print(f"  {C_C}{n_strat} strategies optimised{RES}  |  "
          f"\033[90m{days} trading days  ·  {period}{RES}")
    print("  Ask about risk, allocations, regimes, or strategy trade-offs.")
    print("  Type /help for commands.")
    print("─" * 68)
    strategy_names = list(ctx["optimized_portfolios"].keys())
    strategies_str = ", ".join(f'"{s}"' for s in strategy_names)
    n_assets       = ctx["portfolio_summary"]["n_assets"]
    rf_pct         = ctx["portfolio_summary"]["risk_free_rate"]
    first_prompt = (
        f"I just ran a Markowitz/QAOA portfolio optimisation on "
        f"{n_assets} assets ({', '.join(tickers)}) over {days} trading days "
        f"({period}), using a {rf_pct}% risk-free rate. "
        f"The strategies I ran are: {strategies_str}. "
        f"Please give me: "
        f"(1) A Markdown table comparing all {len(strategy_names)} strategies "
        f"by annual return, volatility, Sharpe, Sortino, Calmar, and CVaR₉₅. "
        f"(2) The most important red flag in these results — look for "
        f"concentration (>40% in one asset), high correlation between assets "
        f"in the same portfolio, or CVaR₉₅ that is more than 1.5× the VaR₉₅. "
        f"(3) Which strategy you would recommend for a balanced investor "
        f"(moderate risk tolerance, 3–5 year horizon) and why. "
        f"(4) One concrete stress-test scenario (e.g. rate hike, sector crash) "
        f"and which strategy is best positioned to survive it."
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m57_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        print(f"  {R}[!] Auto-analysis failed. "
              f"You can still ask questions below.{RES}\n")
    while True:
        try:
            from rich.console import Console
            _con       = Console()
            user_input = _con.input("\n  [bold cyan]You ›[/bold cyan] ").strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Session ended]")
            break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m57_chat_help()
            continue
        elif cmd == "/setkey":
            cfg = _m57_setup_key(cfg)
            history[0]["content"] = _build_m57_system_prompt(ctx, cfg["model_name"])
            continue
        elif cmd == "/models":
            cfg = _m57_pick_model(cfg)
            history[0]["content"] = _build_m57_system_prompt(ctx, cfg["model_name"])
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}")
                print("  Usage:   /model <openrouter-model-id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = (
                    arg.split("/")[-1]
                       .replace(":free", " (free)")
                       .replace("-", " ")
                       .title()
                )
                _m57_save_config(cfg)
                history[0]["content"] = _build_m57_system_prompt(ctx, cfg["model_name"])
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get(
                    "http://127.0.0.1:9999/disabled", timeout=10
                )
                resp.raise_for_status()
                free = [
                    m for m in resp.json().get("data", [])
                    if m.get("id", "").endswith(":free")
                ]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    ctx_k = (m.get("context_length") or 0) // 1000
                    print(f"  {m['id']:<55} {ctx_k:>5}K")
                print(f"\n  {len(free)} free models. Activate with: /model <id>\n")
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/compare":
            cmp_prompt = (
                "Please produce a comprehensive Markdown comparison table of all "
                "optimised strategies, then in 3 sentences explain which strategy "
                "is most appropriate for: (a) a risk-averse retiree, "
                "(b) an aggressive growth investor, (c) an endowment fund."
            )
            history.append({"role": "user", "content": cmp_prompt})
            ai_resp = _m57_stream_response(
                history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
            )
            if ai_resp:
                history.append({"role": "assistant", "content": ai_resp})
            else:
                history.pop()
            continue
        elif cmd == "/risk":
            risk_prompt = (
                "Focus entirely on tail risk. For each strategy: interpret the "
                "VaR₉₅ and CVaR₉₅ values — what do they mean in practice? "
                "Flag any strategy where CVaR₉₅ > 1.5 × VaR₉₅ (fat-tail signal). "
                "Which strategy has the best downside protection and why?"
            )
            history.append({"role": "user", "content": risk_prompt})
            ai_resp = _m57_stream_response(
                history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
            )
            if ai_resp:
                history.append({"role": "assistant", "content": ai_resp})
            else:
                history.pop()
            continue
        elif cmd == "/regime":
            regime_prompt = (
                "Based on the correlation matrix and the gap between the "
                "min-volatility and max-Sharpe portfolios on the efficient frontier, "
                "what market regime does this data suggest? "
                "(e.g. trending bull, mean-reverting, high-correlation crisis, "
                "low-vol carry environment). Explain your reasoning using the data."
            )
            history.append({"role": "user", "content": regime_prompt})
            ai_resp = _m57_stream_response(
                history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
            )
            if ai_resp:
                history.append({"role": "assistant", "content": ai_resp})
            else:
                history.pop()
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Portfolio context retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns    = (len(history) - 1) // 2
            key_hint = (
                f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}"
                if len(cfg["api_key"]) > 12 else "not set"
            )
            print(f"\n  Model      : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key    : {key_hint}")
            print(f"  Tickers    : {', '.join(tickers)}")
            print(f"  Strategies : {', '.join(list(ctx['optimized_portfolios'].keys()))}")
            print(f"  Period     : {period}  |  {days} trading days")
            print(f"  History    : {turns} turns (max 20 before auto-prune)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help.")
            continue
        history.append({"role": "user", "content": user_input})
        ai_response = _m57_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_response:
            history.append({"role": "assistant", "content": ai_response})
        else:
            history.pop()
    print("  [Portfolio session closed — returning to Optimiser menu]\n")
@dataclass
class PortfolioMetrics:
    weights:             Dict[str, float]
    annual_return:       float = 0.0
    annual_vol:          float = 0.0
    sharpe:              float = 0.0
    sortino:             float = 0.0
    calmar:              float = 0.0
    var_95:              Optional[float] = None
    cvar_95:             Optional[float] = None
    var_99:              Optional[float] = None
    cvar_99:             Optional[float] = None
    risk_contributions:  Dict[str, float] = field(default_factory=dict)
    strategy_label:      str  = ""
    converged:           bool = True
@dataclass
class MarketData:
    tickers:        List[str]
    annual_returns: object = None                                     
    cov_matrix:     object = None                               
    daily_returns:  object = None                                
    price_history:  object = None                                    
    loaded:         bool   = False
    fetch_ts:       float  = 0.0                                   
class _Colours:
    BOLD    = '\033[1m'
    CYAN    = '\033[96m'
    GREEN   = '\033[92m'
    YELLOW  = '\033[93m'
    RED     = '\033[91m'
    MAGENTA = '\033[95m'
    BLUE_BG = '\033[44m\033[97m'
    RESET   = '\033[0m'
    DIM     = '\033[2m'
    B   = BOLD;  G   = GREEN;  Y   = YELLOW; R   = RED
    RST = RESET; CY  = CYAN;   BLU = '\033[94m'
    MGN = MAGENTA; BB = BLUE_BG; M = MAGENTA    
C = _Colours                                
def _compute_var_cvar(
    weights,
    daily_returns,
    confidence_levels: Tuple[float, float] = (0.95, 0.99),
) -> Tuple[Optional[float], Optional[float], Optional[float], Optional[float]]:
    try:
        w         = np.asarray(weights, dtype=float)
        port_pnl  = daily_returns.values @ w                                          
        results   = []
        for alpha in confidence_levels:
            var_quantile = np.quantile(port_pnl, 1 - alpha)
            var   = float(var_quantile)
            tail  = port_pnl[port_pnl <= var_quantile]
            cvar  = float(tail.mean()) if len(tail) > 0 else var
            results.extend([var, cvar])
        return tuple(results)                                       
    except Exception:
        return (None, None, None, None)
def _compute_risk_contributions(weights, cov) -> Dict[str, float]:
    try:
        w        = np.asarray(weights, dtype=float)
        cov_arr  = np.asarray(cov, dtype=float)
        sigma_w  = cov_arr @ w                                         
        p_var    = float(w @ sigma_w)                                     
        if p_var < 1e-12:
            n = len(w)
            return {col: 1.0 / n for col in (cov.columns if hasattr(cov, 'columns') else range(n))}
        rc       = w * sigma_w / p_var                                                
        cols     = list(cov.columns) if hasattr(cov, 'columns') else [f"Asset {i}" for i in range(len(w))]
        return dict(zip(cols, rc.tolist()))
    except Exception:
        return {}
def _compute_asset_stats(
    tickers: List[str],
    mu,
    cov,
    daily_returns,
    rf: float,
) -> dict:
    stats = {}
    for t in tickers:
        try:
            ann_ret = float(mu[t]) if t in mu.index else float('nan')
            ann_vol = math.sqrt(max(float(cov.loc[t, t]), 1e-12))
            sharpe  = (ann_ret - rf) / ann_vol if ann_vol > 1e-12 else float('nan')
            if t in daily_returns.columns:
                dr     = daily_returns[t].dropna()
                cum    = (1 + dr).cumprod()
                rolling_max = cum.cummax()
                dd     = (cum - rolling_max) / rolling_max
                max_dd = float(dd.min())
                skew_  = float(dr.skew())
                kurt_  = float(dr.kurt())                    
            else:
                max_dd = skew_ = kurt_ = float('nan')
            stats[t] = {
                "annual_return_pct": round(ann_ret * 100, 2),
                "annual_vol_pct":    round(ann_vol * 100, 2),
                "sharpe":            round(sharpe, 3),
                "max_drawdown_pct":  round(max_dd * 100, 2),
                "skewness":          round(skew_, 3),
                "excess_kurtosis":   round(kurt_, 3),
            }
        except Exception:
            stats[t] = {}
    return stats
def _neg_sharpe(weights, mu, cov, rf: float) -> float:
    p_ret = float(np.dot(weights, mu))
    p_var = float(np.dot(weights, np.dot(cov, weights)))
    p_std = math.sqrt(max(p_var, 1e-12))
    return -(p_ret - rf) / p_std
def _portfolio_vol(weights, mu, cov, rf: float) -> float:
    p_var = float(np.dot(weights, np.dot(cov, weights)))
    return math.sqrt(max(p_var, 1e-12))
def _neg_return(weights, mu, cov, rf: float) -> float:
    return -float(np.dot(weights, mu))
def _risk_parity_objective(weights, mu, cov, rf: float) -> float:
    cov_arr = np.asarray(cov)
    sigma_w = cov_arr @ weights
    rc      = weights * sigma_w
    return float(np.sum((rc - rc.mean()) ** 2))
_STRATEGY_MAP = {
    "S": (_neg_sharpe,             "Maximum Sharpe Ratio"),
    "V": (_portfolio_vol,          "Minimum Volatility"),
    "R": (_neg_return,             "Maximum Expected Return"),
    "P": (_risk_parity_objective,  "Risk-Parity (Equal RC)"),
}
def _run_optimiser(
    objective,
    mu,
    cov,
    rf: float,
    n: int,
    extra_constraints: Optional[list] = None,
) -> Tuple[object, bool]:
    from scipy.optimize import minimize
    bounds      = tuple((0.0, 1.0) for _ in range(n))
    constraints = [{'type': 'eq', 'fun': lambda w: np.sum(w) - 1.0}]
    if extra_constraints:
        constraints.extend(extra_constraints)
    opts = {'maxiter': 1000, 'ftol': 1e-9}
    rng          = np.random.default_rng(seed=42)                 
    init_guesses = [np.full(n, 1.0 / n)]
    for _ in range(3):
        init_guesses.append(rng.dirichlet(np.ones(n)))
    best_result    = None
    best_obj_value = math.inf
    for w0 in init_guesses:
        try:
            res = minimize(
                objective, w0,
                args=(mu, cov, rf),
                method='SLSQP',
                bounds=bounds,
                constraints=constraints,
                options=opts,
            )
            if res.fun < best_obj_value:
                best_obj_value = res.fun
                best_result    = res
        except Exception:
            continue                                     
    converged = bool(best_result is not None and best_result.success)
    return best_result, converged
def _compute_metrics(
    weights, mu, cov, daily_returns, rf: float,
    tickers: Optional[List[str]] = None,
) -> dict:
    w   = np.asarray(weights, dtype=float)
    mu_ = np.asarray(mu,  dtype=float)
    cov_= np.asarray(cov, dtype=float)
    p_ret = float(np.dot(w, mu_))
    p_var = float(np.dot(w, np.dot(cov_, w)))
    p_std = math.sqrt(max(p_var, 1e-12))
    sharpe = (p_ret - rf) / p_std
    if daily_returns is not None and len(daily_returns) > 1:
        port_daily = daily_returns.values @ w                                    
        downside   = port_daily[port_daily < 0]
        if len(downside) > 1:
            semi_std = float(np.std(downside, ddof=1)) * math.sqrt(252)
            sortino  = (p_ret - rf) / max(semi_std, 1e-12)
        else:
            sortino = float('nan')
        cum_ret     = (1 + pd.Series(port_daily)).cumprod()
        rolling_max = cum_ret.cummax()
        dd          = (cum_ret - rolling_max) / rolling_max
        max_dd      = float(dd.min())
        calmar      = p_ret / max(abs(max_dd), 1e-12) if max_dd < 0 else float('nan')
        var_95, cvar_95, var_99, cvar_99 = _compute_var_cvar(
            w, daily_returns
        )
        rc_dict = _compute_risk_contributions(w, cov)
        if tickers and len(tickers) == len(w):
            rc_dict = dict(zip(tickers, rc_dict.values()))
    else:
        sortino = calmar = var_95 = cvar_95 = var_99 = cvar_99 = float('nan')
        rc_dict = {}
    return {
        'annual_return':     p_ret,
        'annual_vol':        p_std,
        'sharpe':            sharpe,
        'sortino':           sortino,
        'calmar':            calmar,
        'var_95':            var_95,
        'cvar_95':           cvar_95,
        'var_99':            var_99,
        'cvar_99':           cvar_99,
        'risk_contributions': rc_dict,
    }
def _monte_carlo_frontier(
    mu, cov, n_sim: int = 4000
) -> List[Tuple[float, float, float]]:
    mu_  = np.asarray(mu,  dtype=float)
    cov_ = np.asarray(cov, dtype=float)
    n    = len(mu_)
    rng  = np.random.default_rng(seed=0)
    results = []
    for _ in range(n_sim):
        w   = rng.dirichlet(np.ones(n))
        ret = float(np.dot(w, mu_))
        vol = math.sqrt(max(float(np.dot(w, np.dot(cov_, w))), 1e-12))
        sr  = (ret - 0.07) / vol
        results.append((vol, ret, sr))
    return results
class QuantumPortfolioOptimizer:
    _ANNUALISATION_FACTOR: int = 252
    _CACHE_TTL:            int = 3600                                         
    def __init__(
        self,
        tickers: Optional[List[str]] = None,
        risk_free_rate: float = 0.07,
        data_period: str = "2y",
    ):
        default_tickers = [
            "RELIANCE.NS", "TCS.NS", "INFY.NS",
            "HDFCBANK.NS", "ICICIBANK.NS",
        ]
        self.tickers        = self._normalise_tickers(tickers or default_tickers)
        self.risk_free_rate = float(risk_free_rate)
        self.data_period    = data_period
        self._market        = MarketData(tickers=self.tickers)
        self._session_results: Dict[str, PortfolioMetrics] = {}
    @staticmethod
    def _normalise_tickers(raw: List[str]) -> List[str]:
        normalised = []
        for t in raw:
            t = t.strip().upper()
            if not t:
                continue
            normalised.append(t if '.' in t else t + '.NS')
        seen = set()
        return [t for t in normalised if not (t in seen or seen.add(t))]
    @staticmethod
    def _check_dependencies() -> bool:
        required = {
            'numpy':   'pip install numpy',
            'pandas':  'pip install pandas',
            'scipy':   'pip install scipy',
            'yfinance':'pip install yfinance',
        }
        missing = []
        for lib, cmd in required.items():
            try:
                __import__(lib)
            except ImportError:
                missing.append((lib, cmd))
        if missing:
            print(f"\n  {C.RED}[!] Missing dependencies:{C.RESET}")
            for lib, cmd in missing:
                print(f"      {C.YELLOW}{lib:<12}{C.RESET} → {cmd}")
            return False
        return True
    def _is_cache_stale(self) -> bool:
        if not self._market.loaded:
            return True
        return (time.time() - self._market.fetch_ts) > self._CACHE_TTL
    def _fetch_and_cache(self, force: bool = False) -> bool:
        if self._market.loaded and not force and not self._is_cache_stale():
            print(f"  {C.GREEN}[✓] Using cached market data.{C.RESET}")
            return True
        if self._is_cache_stale() and self._market.loaded:
            age_min = int((time.time() - self._market.fetch_ts) / 60)
            print(f"  {C.YELLOW}[⚠] Cache is {age_min} min old — refreshing.{C.RESET}")
        print(f"  {C.CYAN}Fetching {self.data_period} of daily price data "
              f"for {len(self.tickers)} tickers …{C.RESET}")
        try:
            raw = yf.download(
                self.tickers,
                period=self.data_period,
                interval="1d",
                progress=False,
                auto_adjust=True,                                     
            )
        except Exception as exc:
            print(f"  {C.RED}[!] Network error: {exc}{C.RESET}")
            return False
        if raw.empty:
            print(f"  {C.RED}[!] Empty download. "
                  f"Check tickers ({', '.join(self.tickers)}) and connection.{C.RESET}")
            return False
        if isinstance(raw.columns, pd.MultiIndex):
            try:
                prices = raw['Close']
            except KeyError:
                print(f"  {C.RED}[!] 'Close' column missing in yfinance output. "
                      f"Check yfinance version compatibility.{C.RESET}")
                return False
        else:
            prices = raw[['Close']] if 'Close' in raw.columns else raw.iloc[:, :1]
        raw_rows  = len(prices)
        daily_ret = prices.pct_change().dropna()
        dropped   = raw_rows - len(daily_ret) - 1
        if dropped > 0:
            pct = 100 * dropped / max(raw_rows, 1)
            print(f"  {C.YELLOW}[⚠] Dropped {dropped} rows ({pct:.1f}%) with NaN.{C.RESET}")
        if len(daily_ret) < 20:
            print(f"  {C.RED}[!] < 20 valid trading days — "
                  f"statistics will be unreliable.{C.RESET}")
        daily_ret = daily_ret.dropna(axis=1, how='all')
        valid_tickers = list(daily_ret.columns)
        if len(valid_tickers) < len(self.tickers):
            dropped_t = set(self.tickers) - set(valid_tickers)
            print(f"  {C.YELLOW}[⚠] Removed {len(dropped_t)} ticker(s) with no data: "
                  f"{', '.join(dropped_t)}{C.RESET}")
            self.tickers = valid_tickers
        mu  = daily_ret.mean() * self._ANNUALISATION_FACTOR
        cov = daily_ret.cov()  * self._ANNUALISATION_FACTOR
        date_start = str(daily_ret.index[0])[:10]
        date_end   = str(daily_ret.index[-1])[:10]
        self._market = MarketData(
            tickers        = self.tickers,
            annual_returns = mu,
            cov_matrix     = cov,
            daily_returns  = daily_ret,
            price_history  = prices,
            loaded         = True,
            fetch_ts       = time.time(),
        )
        if len(self.tickers) == 1:
            print(f"  {C.YELLOW}[⚠] Single-asset portfolio: "
                  f"diversification benefit is zero.{C.RESET}")
        print(f"  {C.GREEN}[✓] Loaded {len(daily_ret)} trading days "
              f"({date_start} → {date_end}) "
              f"for {len(self.tickers)} assets.{C.RESET}")
        self._session_results.clear()
        return True
    def _run_and_display(self, strategy_code: str) -> Optional[PortfolioMetrics]:
        if strategy_code not in _STRATEGY_MAP:
            print(f"  {C.RED}[!] Unknown strategy code: {strategy_code}{C.RESET}")
            return None
        objective, label = _STRATEGY_MAP[strategy_code]
        mu  = np.asarray(self._market.annual_returns)
        cov = np.asarray(self._market.cov_matrix)
        n   = len(self.tickers)
        print(f"\n  {C.MAGENTA}Running [{label}] optimisation …{C.RESET}")
        print(f"  {C.CYAN}(QAOA mapping: {n} assets → {n}-spin Ising Hamiltonian){C.RESET}")
        t0 = time.perf_counter()
        result, converged = _run_optimiser(
            objective, mu, cov, self.risk_free_rate, n
        )
        elapsed = time.perf_counter() - t0
        if result is None:
            print(f"  {C.RED}[!] Optimiser returned no result. "
                  f"Try fewer assets or a different period.{C.RESET}")
            return None
        weights = np.clip(result.x, 0, 1)
        weights /= weights.sum()
        metrics_dict = _compute_metrics(
            weights, mu, cov,
            self._market.daily_returns,
            self.risk_free_rate,
            tickers=self.tickers,
        )
        pm = PortfolioMetrics(
            weights             = dict(zip(self.tickers, weights.tolist())),
            annual_return       = metrics_dict['annual_return'],
            annual_vol          = metrics_dict['annual_vol'],
            sharpe              = metrics_dict['sharpe'],
            sortino             = metrics_dict['sortino'],
            calmar              = metrics_dict['calmar'],
            var_95              = metrics_dict['var_95'],
            cvar_95             = metrics_dict['cvar_95'],
            var_99              = metrics_dict['var_99'],
            cvar_99             = metrics_dict['cvar_99'],
            risk_contributions  = metrics_dict['risk_contributions'],
            strategy_label      = label,
            converged           = converged,
        )
        self._session_results[label] = pm
        self._display_result(pm, elapsed)
        return pm
    @staticmethod
    def _display_result(pm: PortfolioMetrics, elapsed: float) -> None:
        B, G, Y, R, M, CY, RES = (
            C.BOLD, C.GREEN, C.YELLOW, C.RED, C.MAGENTA, C.CYAN, C.RESET
        )
        def _fmt_ratio(val) -> str:
            if val is None or (isinstance(val, float) and math.isnan(val)):
                return "    N/A"
            return f"{val:>7.3f}"
        def _fmt_pct(val) -> str:
            if val is None or (isinstance(val, float) and math.isnan(val)):
                return "     N/A"
            return f"{val*100:>7.2f}%"
        conv_flag = f"{G}✓ CONVERGED{RES}" if pm.converged else f"{R}✗ UNCONVERGED{RES}"
        print(f"\n  {B}{'═'*66}{RES}")
        print(f"  {C.BLUE_BG}  QUANTUM-OPTIMISED ALLOCATION — {pm.strategy_label:<30}{RES}")
        print(f"  {B}{'═'*66}{RES}")
        print(f"  {'Ticker':<16}  {'Weight':>8}  {'Bar (30 chars)':<32}  {'Risk Contr':>10}")
        print(f"  {'─'*64}")
        for ticker, w in pm.weights.items():
            bar_len  = int(round(w * 30))
            bar_fill = '█' * bar_len + '░' * (30 - bar_len)
            rc       = pm.risk_contributions.get(ticker, float('nan'))
            rc_str   = f"{rc*100:>8.1f}%" if not (isinstance(rc, float) and math.isnan(rc)) else "      N/A"
            if w > 0.05:   colour = G
            elif w > 0.01: colour = Y
            else:           colour = RES
            print(f"  {colour}{ticker:<16}{RES}  {colour}{w*100:>7.2f}%{RES}  "
                  f"{colour}{bar_fill}{RES}  {colour}{rc_str}{RES}")
        print(f"  {'─'*64}")
        print(f"  {'Solver status':<24}  {conv_flag}   ({elapsed*1000:.1f} ms)")
        print(f"  {'─'*64}")
        print(f"  {B}{'Expected Annual Return':<24}{RES}  {G}{pm.annual_return*100:>7.2f}%{RES}")
        print(f"  {B}{'Annual Volatility (σ)':<24}{RES}  {Y}{pm.annual_vol*100:>7.2f}%{RES}")
        print(f"  {B}{'Sharpe Ratio':<24}{RES}  {CY}{_fmt_ratio(pm.sharpe)}{RES}")
        print(f"  {B}{'Sortino Ratio':<24}{RES}  {CY}{_fmt_ratio(pm.sortino)}{RES}")
        print(f"  {B}{'Calmar Ratio':<24}{RES}  {CY}{_fmt_ratio(pm.calmar)}{RES}")
        print(f"  {'─'*64}")
        print(f"  {B}{'VaR₉₅  (1-day)':<24}{RES}  {R}{_fmt_pct(pm.var_95)}{RES}  "
              f"\033[90m← loss exceeded 5% of days\033[0m")
        print(f"  {B}{'CVaR₉₅ (Exp. Shortfall)':<24}{RES}  {R}{_fmt_pct(pm.cvar_95)}{RES}  "
              f"\033[90m← avg loss in worst 5% of days\033[0m")
        print(f"  {B}{'VaR₉₉  (1-day)':<24}{RES}  {R}{_fmt_pct(pm.var_99)}{RES}  "
              f"\033[90m← loss exceeded 1% of days\033[0m")
        print(f"  {B}{'CVaR₉₉ (Exp. Shortfall)':<24}{RES}  {R}{_fmt_pct(pm.cvar_99)}{RES}  "
              f"\033[90m← avg loss in worst 1% of days\033[0m")
        print(f"  {B}{'═'*66}{RES}")
        if not math.isnan(pm.sharpe):
            if pm.sharpe < 0.5:
                print(f"  {R}[!] Sharpe < 0.5: weak risk-adjusted return. "
                      f"Review asset selection.{RES}")
            elif pm.sharpe < 1.0:
                print(f"  {Y}[~] Sharpe 0.5–1.0: acceptable. "
                      f"Frontier position is sub-optimal.{RES}")
            elif pm.sharpe >= 2.0:
                print(f"  {G}[✓] Sharpe ≥ 2.0: excellent risk-adjusted return.{RES}")
        if (pm.var_95 is not None and pm.cvar_95 is not None and
                pm.var_95 != 0 and abs(pm.cvar_95 / pm.var_95) > 1.5):
            print(f"  {Y}[⚠] CVaR₉₅ > 1.5× VaR₉₅: fat-tailed return distribution. "
                  f"Tail risk is elevated.{RES}")
        max_weight = max(pm.weights.values())
        if max_weight > 0.40:
            top_asset = max(pm.weights, key=pm.weights.get)
            print(f"  {Y}[⚠] {top_asset} = {max_weight*100:.1f}% — "
                  f"concentration risk. Consider position limits.{RES}")
    def _display_asset_stats(self) -> None:
        if not self._market.loaded:
            print(f"  {C.RED}[!] Fetch data first (option F).{C.RESET}")
            return
        B, G, Y, R, CY, RES = C.BOLD, C.GREEN, C.YELLOW, C.RED, C.CYAN, C.RESET
        stats = _compute_asset_stats(
            self.tickers,
            self._market.annual_returns,
            self._market.cov_matrix,
            self._market.daily_returns,
            self.risk_free_rate,
        )
        print(f"\n  {B}{'═'*82}{RES}")
        print(f"  {C.BLUE_BG}  INDIVIDUAL ASSET STATISTICS  {' '*52}{RES}")
        print(f"  {B}{'═'*82}{RES}")
        print(f"  {'Ticker':<16}  {'Ann.Ret':>8}  {'Ann.Vol':>8}  "
              f"{'Sharpe':>8}  {'MaxDD':>8}  {'Skew':>8}  {'Kurt':>8}")
        print(f"  {'─'*80}")
        for t in self.tickers:
            s = stats.get(t, {})
            if not s:
                print(f"  {R}{t:<16}  [no data]{RES}")
                continue
            ret   = s.get('annual_return_pct', float('nan'))
            vol   = s.get('annual_vol_pct', float('nan'))
            sr    = s.get('sharpe', float('nan'))
            dd    = s.get('max_drawdown_pct', float('nan'))
            skew  = s.get('skewness', float('nan'))
            kurt  = s.get('excess_kurtosis', float('nan'))
            sr_col = G if sr > 1.0 else (Y if sr > 0.5 else R)
            dd_col = G if dd > -15 else (Y if dd > -30 else R)
            print(
                f"  {B}{t:<16}{RES}  "
                f"{G}{ret:>7.2f}%{RES}  "
                f"{Y}{vol:>7.2f}%{RES}  "
                f"{sr_col}{sr:>8.3f}{RES}  "
                f"{dd_col}{dd:>7.2f}%{RES}  "
                f"{CY}{skew:>8.3f}{RES}  "
                f"{CY}{kurt:>8.3f}{RES}"
            )
        print(f"  {'─'*80}")
        print(f"  \033[90mSharpe = (μ−rf)/σ  |  MaxDD = worst peak-to-trough  |  "
              f"Kurt = excess kurtosis (>0 = fat tails)\033[0m")
        print(f"  {B}{'═'*82}{RES}")
    def _display_correlation_matrix(self) -> None:
        if not self._market.loaded:
            print(f"  {C.RED}[!] Fetch data first (option F).{C.RESET}")
            return
        B, G, Y, R, DIM, RES = (
            C.BOLD, C.GREEN, C.YELLOW, C.RED, C.DIM, C.RESET
        )
        corr = self._market.daily_returns.corr()
        n    = len(self.tickers)
        print(f"\n  {B}{'═'*66}{RES}")
        print(f"  {C.BLUE_BG}  PEARSON CORRELATION MATRIX  {' '*37}{RES}")
        print(f"  {B}{'═'*66}{RES}")
        abbrevs = [t.replace('.NS', '')[:8] for t in self.tickers]
        header  = '  ' + ' ' * 14
        for a in abbrevs:
            header += f"{a:>10}"
        print(header)
        print(f"  {'─'*64}")
        for i, ti in enumerate(self.tickers):
            row = f"  {abbrevs[i]:<14}"
            for j, tj in enumerate(self.tickers):
                val = corr.iloc[i, j]
                s   = f"{val:>9.3f} "
                if i == j:
                    row += f"{DIM}{s}{RES}"
                elif abs(val) > 0.75:
                    row += f"{R}{s}{RES}"
                elif abs(val) > 0.50:
                    row += f"{Y}{s}{RES}"
                else:
                    row += f"{G}{s}{RES}"
            print(row)
        print(f"  {'─'*64}")
        print(f"  {G}Green < 0.50{RES}  {Y}Yellow 0.50–0.75{RES}  {R}Red > 0.75{RES}")
        print(f"  \033[90mHigh correlation = limited diversification benefit\033[0m")
        print(f"  {B}{'═'*66}{RES}")
    def _display_comparison_table(self) -> None:
        if len(self._session_results) < 2:
            print(f"\n  {C.YELLOW}[~] Run at least 2 strategies to enable comparison.{C.RESET}")
            return
        B, G, Y, R, CY, RES = C.BOLD, C.GREEN, C.YELLOW, C.RED, C.CYAN, C.RESET
        labels = list(self._session_results.keys())
        abbrev_labels = [lbl[:14] for lbl in labels]
        col_w  = 14                                  
        row_lbl = 24                                    
        sep     = "─"
        print(f"\n  {B}{'═' * (row_lbl + col_w * len(labels) + 6)}{RES}")
        print(f"  {C.BLUE_BG}  STRATEGY COMPARISON TABLE{' '*30}{RES}")
        print(f"  {B}{'═' * (row_lbl + col_w * len(labels) + 6)}{RES}")
        header = f"  {'Metric':<{row_lbl}}"
        for al in abbrev_labels:
            header += f"{B}{al:^{col_w}}{RES}"
        print(header)
        print(f"  {sep * (row_lbl + col_w * len(labels) + 4)}")
        def _row(label, extractor, formatter, color_fn=None):
            line = f"  {B}{label:<{row_lbl}}{RES}"
            for lbl in labels:
                pm  = self._session_results[lbl]
                val = extractor(pm)
                s   = formatter(val)
                col = color_fn(val) if color_fn else RES
                line += f"{col}{s:^{col_w}}{RES}"
            print(line)
        def _nan_safe(val, fmt) -> str:
            if val is None or (isinstance(val, float) and math.isnan(val)):
                return "N/A"
            return fmt.format(val)
        _row("Annual Return (%)",
             lambda pm: pm.annual_return * 100,
             lambda v:  _nan_safe(v, "{:+.2f}%"),
             lambda v:  G if v > 12 else (Y if v > 6 else R))
        _row("Annual Vol (%)",
             lambda pm: pm.annual_vol * 100,
             lambda v:  _nan_safe(v, "{:.2f}%"),
             lambda v:  G if v < 15 else (Y if v < 25 else R))
        _row("Sharpe Ratio",
             lambda pm: pm.sharpe,
             lambda v:  _nan_safe(v, "{:.3f}"),
             lambda v:  G if v > 1.0 else (Y if v > 0.5 else R))
        _row("Sortino Ratio",
             lambda pm: pm.sortino,
             lambda v:  _nan_safe(v, "{:.3f}"),
             lambda v:  G if v > 1.2 else (Y if v > 0.7 else R))
        _row("Calmar Ratio",
             lambda pm: pm.calmar,
             lambda v:  _nan_safe(v, "{:.3f}"),
             lambda v:  G if v > 0.8 else (Y if v > 0.4 else R))
        _row("VaR₉₅ (%/day)",
             lambda pm: pm.var_95 * 100 if pm.var_95 else None,
             lambda v:  _nan_safe(v, "{:.2f}%"),
             lambda v:  G if v is not None and v > -2.0 else (Y if v is not None and v > -3.0 else R))
        _row("CVaR₉₅ (%/day)",
             lambda pm: pm.cvar_95 * 100 if pm.cvar_95 else None,
             lambda v:  _nan_safe(v, "{:.2f}%"),
             lambda v:  G if v is not None and v > -3.0 else (Y if v is not None and v > -5.0 else R))
        print(f"  {sep * (row_lbl + col_w * len(labels) + 4)}")
        line = f"  {B}{'Top Asset / Weight':<{row_lbl}}{RES}"
        for lbl in labels:
            pm  = self._session_results[lbl]
            top = max(pm.weights, key=pm.weights.get)
            tw  = pm.weights[top]
            s   = f"{top.replace('.NS','')} {tw*100:.0f}%"
            col = R if tw > 0.4 else (Y if tw > 0.25 else G)
            line += f"{col}{s:^{col_w}}{RES}"
        print(line)
        print(f"  {B}{'═' * (row_lbl + col_w * len(labels) + 6)}{RES}")
        print(f"  \033[90mGreen = favourable  Yellow = acceptable  Red = caution\033[0m")
    def _show_efficient_frontier(self) -> Optional[dict]:
        if not self._market.loaded:
            print(f"  {C.RED}[!] Fetch data first (option F).{C.RESET}")
            return None
        mu  = np.asarray(self._market.annual_returns)
        cov = np.asarray(self._market.cov_matrix)
        n   = len(self.tickers)
        print(f"\n  {C.CYAN}Computing Efficient Frontier (4 000 Monte Carlo draws) …{C.RESET}")
        points = _monte_carlo_frontier(mu, cov, n_sim=4000)
        COLS, ROWS = 64, 22
        vols       = [p[0] for p in points]
        rets       = [p[1] for p in points]
        v_min, v_max = min(vols), max(vols)
        r_min, r_max = min(rets), max(rets)
        v_pad = (v_max - v_min) * 0.05 or 0.01
        r_pad = (r_max - r_min) * 0.05 or 0.01
        v_min -= v_pad; v_max += v_pad
        r_min -= r_pad; r_max += r_pad
        def _to_col(vol):
            return int((vol - v_min) / (v_max - v_min) * (COLS - 1))
        def _to_row(ret):
            return ROWS - 1 - int((ret - r_min) / (r_max - r_min) * (ROWS - 1))
        canvas = [['·' for _ in range(COLS)] for _ in range(ROWS)]
        for vol, ret, _ in points:
            r, c = _to_row(ret), _to_col(vol)
            if 0 <= r < ROWS and 0 <= c < COLS:
                canvas[r][c] = '·'
        special      = {}
        optimal_data = {}
        sym_map = {
            "S": ("★", C.GREEN,   "Max Sharpe"),
            "V": ("▲", C.CYAN,    "Min Vol"),
            "P": ("●", C.YELLOW,  "Risk Parity"),
            "R": ("◆", C.MAGENTA, "Max Return"),
        }
        for code, (sym, col_str, name) in sym_map.items():
            obj, _ = _STRATEGY_MAP[code]
            res, _ = _run_optimiser(obj, mu, cov, self.risk_free_rate, n)
            if res is not None:
                w      = np.clip(res.x, 0, 1); w /= w.sum()
                v_opt  = math.sqrt(max(float(np.dot(w, np.dot(cov, w))), 1e-12))
                r_opt  = float(np.dot(w, mu))
                r_idx, c_idx = _to_row(r_opt), _to_col(v_opt)
                if 0 <= r_idx < ROWS and 0 <= c_idx < COLS:
                    special[(r_idx, c_idx)] = (sym, col_str)
                optimal_data[name] = {
                    "vol_pct": round(v_opt * 100, 2),
                    "ret_pct": round(r_opt * 100, 2),
                }
        print(f"\n  {'Return':>7} │ Markowitz Feasible Set ({len(points)} random portfolios)")
        print(f"  {'':>7} │ {'─'*COLS}")
        for row_idx in range(ROWS):
            ret_label = r_min + (ROWS - 1 - row_idx) * (r_max - r_min) / (ROWS - 1)
            label     = f"{ret_label*100:>5.1f}% │ "
            line      = ""
            for col_idx in range(COLS):
                if (row_idx, col_idx) in special:
                    sym, col_str = special[(row_idx, col_idx)]
                    line += col_str + sym + C.RESET
                else:
                    line += f"\033[2m{canvas[row_idx][col_idx]}\033[0m"
            print(f"  {label}{line}")
        print(f"  {'':>7} └{'─'*COLS}")
        step = (v_max - v_min) / 5
        x_row = f"  {'':>8}"
        for i in range(6):
            x_row += f"{(v_min + i*step)*100:.1f}% ".ljust(11)
        print(x_row)
        print(f"  {' '*10}{'Volatility →':^{COLS}}")
        print(f"\n  Legend: {C.GREEN}★ Max Sharpe{C.RESET}  "
              f"{C.CYAN}▲ Min Vol{C.RESET}  "
              f"{C.YELLOW}● Risk Parity{C.RESET}  "
              f"{C.MAGENTA}◆ Max Return{C.RESET}  "
              f"\033[2m· random portfolio\033[0m")
        frontier_summary = {
            "n_simulated":  len(points),
            "vol_range":    {"min_pct": round(v_min*100,2), "max_pct": round(v_max*100,2)},
            "ret_range":    {"min_pct": round(r_min*100,2), "max_pct": round(r_max*100,2)},
            "optimal_points": optimal_data,
        }
        return frontier_summary
    def _build_ai_context(self) -> Optional[dict]:
        if not self._market.loaded:
            print(f"  {C.RED}[!] Fetch data first (option F).{C.RESET}")
            return None
        if not self._session_results:
            print(f"  {C.YELLOW}[~] Run at least one optimisation strategy first.{C.RESET}")
            return None
        mu  = np.asarray(self._market.annual_returns)
        cov = np.asarray(self._market.cov_matrix)
        asset_stats = _compute_asset_stats(
            self.tickers,
            self._market.annual_returns,
            self._market.cov_matrix,
            self._market.daily_returns,
            self.risk_free_rate,
        )
        corr_dict = self._market.daily_returns.corr().round(3).to_dict()
        dr = self._market.daily_returns
        date_range = {
            "start": str(dr.index[0])[:10],
            "end":   str(dr.index[-1])[:10],
        }
        print(f"  {C.CYAN}Computing frontier summary for AI context …{C.RESET}")
        points = _monte_carlo_frontier(mu, cov, n_sim=2000)
        vols   = [p[0] for p in points]
        rets   = [p[1] for p in points]
        frontier_summary = {
            "n_simulated": len(points),
            "vol_range": {
                "min_pct": round(min(vols)*100, 2),
                "max_pct": round(max(vols)*100, 2),
            },
            "ret_range": {
                "min_pct": round(min(rets)*100, 2),
                "max_pct": round(max(rets)*100, 2),
            },
        }
        return _build_portfolio_context(
            tickers          = self.tickers,
            risk_free_rate   = self.risk_free_rate,
            data_period      = self.data_period,
            trading_days     = len(self._market.daily_returns),
            date_range       = date_range,
            asset_stats      = asset_stats,
            corr_matrix      = corr_dict,
            session_results  = self._session_results,
            frontier_summary = frontier_summary,
        )
