    print("\n  ── API Key Setup (Module 58) ─────────────────────────")
    print("  Get a free key at: https://openrouter.ai/keys")
    print(f"  Config saved to:   {_M58_CONFIG_FILE}\n")
    key = ""
    try:
        key = getpass.getpass("  Paste your OpenRouter API key (hidden): ").strip()
    except Exception:
        pass
    if not key:
        try:
            sys.stdout.write("  Paste your OpenRouter API key: ")
            sys.stdout.flush()
            key = sys.stdin.readline().strip()
        except Exception:
            pass
    if not key:
        try:
            key = input("  Paste your OpenRouter API key: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n  [!] Key setup cancelled.")
            return cfg
    if not key:
        print("  [!] Empty key — setup cancelled.")
        return cfg
    if not key.startswith("sk-"):
        print("  [~] Key doesn't start with 'sk-' — double-check the source.")
    cfg["api_key"] = key
    _m58_save_config(cfg)
    print(f"  [✓] Key saved  ({key[:8]}…{key[-4:]})")
