@dataclass
class NodeResult:
    node_id:           int
    strategy:          str
    forecast_path:     object                                 
    forecast_price:    float
    confidence:        float                
    signal:            float                     
    signal_components: Dict[str, float]
    description:       str
    byzantine:         bool = False
@dataclass
class AggregationResult:
    method:          str
    consensus_path:  object                              
    consensus_price: float
    lower_90:        float
    upper_90:        float
@dataclass
class SwarmResult:
    ticker:           str
    last_price:       float
    horizon:          int
    nodes:            List[NodeResult]
    clean_nodes:      List[NodeResult]
    byzantine_ids:    List[int]
    fedavg:           Optional[AggregationResult]
    median_agg:       Optional[AggregationResult]
    trimmed:          Optional[AggregationResult]
    swarm_confidence: float
    node_agreement:   float
    bull_case:        float
    bear_case:        float
    date_run:         str
def _node_momentum(close: np.ndarray, horizon: int, S0: float) -> NodeResult:
    T = len(close)
    m5  = float(close[-1] / close[-6] - 1)  if T >= 6  else 0.0
    m20 = float(close[-1] / close[-21] - 1) if T >= 21 else m5
    m60 = float(close[-1] / close[-61] - 1) if T >= 61 else m20
    signal  = 0.5 * m5 + 0.3 * m20 + 0.2 * m60
    signal  = float(np.clip(signal, -0.3, 0.3))                       
    signs       = [np.sign(m5), np.sign(m20), np.sign(m60)]
    agreement   = abs(sum(signs)) / 3.0                                       
    signal_mag  = min(abs(signal) / 0.05, 1.0)                           
    confidence  = 0.4 * agreement + 0.4 * signal_mag + 0.2              
    decay_days = min(horizon, 40)
    daily_drifts = np.array([
        signal / decay_days * max(0.0, 1.0 - t / decay_days)
        for t in range(1, horizon + 1)
    ])
    path = S0 * np.cumprod(1.0 + daily_drifts)
    desc = (
        f"5d={m5*100:+.1f}%  20d={m20*100:+.1f}%  60d={m60*100:+.1f}%  "
        f"→ {'bullish' if signal > 0 else 'bearish'} momentum "
        f"(composite signal {signal*100:+.1f}%)"
    )
    return NodeResult(
        node_id=1, strategy="Momentum",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.1, 0.95)),
        signal=float(np.clip(signal * 5, -1, 1)),
        signal_components={"m5": round(m5,4), "m20": round(m20,4), "m60": round(m60,4)},
        description=desc,
    )
def _node_mean_reversion(close: np.ndarray, horizon: int, S0: float) -> NodeResult:
    lookback = min(20, len(close))
    sma      = float(np.mean(close[-lookback:]))
    std_p    = float(np.std(close[-lookback:], ddof=1))
    std_p    = max(std_p, sma * 0.001)                                      
    z_score  = (S0 - sma) / (2 * std_p)                               
    z_score  = float(np.clip(z_score, -3, 3))
    signal   = -float(np.clip(z_score, -1, 1))
    confidence = min(abs(z_score) / 1.5, 1.0) * 0.75 + 0.15
    reversion_speed = max(10, 30 - abs(z_score) * 5)
    t_arr  = np.arange(1, horizon + 1)
    path   = sma + (S0 - sma) * np.exp(-t_arr / reversion_speed)
    sma_trend = (sma - float(np.mean(close[-40:-20]))) / 20 if len(close) >= 40 else 0
    path   = path + sma_trend * t_arr
    desc = (
        f"SMA_20=₹{sma:.2f}  z-score={z_score:+.2f}  "
        f"{'Above band → reversion down' if z_score > 0 else 'Below band → reversion up'}"
    )
    return NodeResult(
        node_id=2, strategy="Mean Reversion",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.15, 0.90)),
        signal=signal,
        signal_components={"z_score": round(z_score,3), "sma_20": round(sma,2),
                           "bb_std": round(std_p,2)},
        description=desc,
    )
def _node_trend_ols(close: np.ndarray, horizon: int, S0: float) -> NodeResult:
    lookback = min(90, len(close))
    log_p    = np.log(close[-lookback:])
    t_in     = np.arange(lookback, dtype=float)
    t_mean   = t_in.mean()
    p_mean   = log_p.mean()
    beta     = float(np.dot(t_in - t_mean, log_p - p_mean) /
                     np.dot(t_in - t_mean, t_in - t_mean))
    alpha    = p_mean - beta * t_mean
    fitted   = alpha + beta * t_in
    ss_res   = float(np.sum((log_p - fitted) ** 2))
    ss_tot   = float(np.sum((log_p - p_mean) ** 2))
    r_sq     = max(0.0, 1.0 - ss_res / max(ss_tot, 1e-12))
    t_out    = np.arange(lookback, lookback + horizon, dtype=float)
    path     = np.exp(alpha + beta * t_out)
    signal   = float(np.clip(beta * 252, -1, 1))                              
    confidence = r_sq * 0.85 + 0.1                              
    desc = (
        f"OLS slope β={beta*252*100:+.1f}%/yr  R²={r_sq:.3f}  "
        f"lookback={lookback}d  → "
        f"{'uptrend' if beta > 0 else 'downtrend'}"
    )
    return NodeResult(
        node_id=3, strategy="Trend (OLS)",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.10, 0.93)),
        signal=signal,
        signal_components={"beta_annual": round(beta*252,4), "r_squared": round(r_sq,4),
                           "alpha": round(alpha,4)},
        description=desc,
    )
def _node_volume_obv(
    close: np.ndarray, volume: np.ndarray, horizon: int, S0: float
) -> NodeResult:
    T        = len(close)
    lookback = min(T - 1, 60)
    returns_sign = np.sign(np.diff(close[-lookback-1:]))
    obv_changes  = volume[-lookback:] * returns_sign
    obv          = np.cumsum(obv_changes)
    obv_window   = min(20, len(obv))
    obv_recent   = obv[-obv_window:]
    t_obv        = np.arange(obv_window, dtype=float)
    if np.std(obv_recent) > 0 and obv_window > 2:
        obv_beta = float(np.dot(t_obv - t_obv.mean(), obv_recent - obv_recent.mean()) /
                         np.dot(t_obv - t_obv.mean(), t_obv - t_obv.mean()))
        obv_signal = float(np.clip(obv_beta / (np.std(obv_recent) + 1e-12), -2, 2))
    else:
        obv_beta = 0.0; obv_signal = 0.0
    price_ret_20 = float(close[-1] / close[-min(21, T)] - 1) if T > 20 else 0.0
    divergence   = 0.0
    if price_ret_20 > 0 and obv_signal < 0:
        divergence = -min(abs(obv_signal) * 0.3, 0.3)                       
    elif price_ret_20 < 0 and obv_signal > 0:
        divergence = min(abs(obv_signal) * 0.3, 0.3)                        
    signal     = float(np.clip(obv_signal * 0.4 + divergence, -1, 1))
    confidence = min(abs(obv_signal) / 1.5, 1.0) * 0.70 + 0.15
    daily_drift = signal * 0.002                                       
    decay       = np.exp(-np.arange(1, horizon + 1) / 30.0)
    path        = S0 * np.cumprod(1.0 + daily_drift * decay)
    div_str = ("bearish divergence" if divergence < 0 else
               "bullish divergence" if divergence > 0 else "no divergence")
    desc = (
        f"OBV slope={obv_beta:.0f}/d  signal={obv_signal:+.2f}  "
        f"{div_str}  volume pressure: "
        f"{'accumulation' if signal > 0 else 'distribution'}"
    )
    return NodeResult(
        node_id=4, strategy="Volume / OBV",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.15, 0.85)),
        signal=signal,
        signal_components={"obv_signal": round(obv_signal,3), "divergence": round(divergence,3),
                           "price_ret_20d": round(price_ret_20,4)},
        description=desc,
    )
def _node_autocorr_ar(
    returns: np.ndarray, horizon: int, S0: float
) -> NodeResult:
    p    = 5             
    T    = len(returns)
    lookback = min(T, 120)
    r    = returns[-lookback:]
    n_obs = lookback - p
    if n_obs < 20:
        drift   = float(returns.mean())
        path    = S0 * np.exp(np.cumsum(np.full(horizon, drift)))
        return NodeResult(
            node_id=5, strategy="AR Model",
            forecast_path=path, forecast_price=float(path[-1]),
            confidence=0.20, signal=float(np.clip(drift * 252, -1, 1)),
            signal_components={"drift": round(drift,6), "ar_order": 0},
            description="Insufficient data — random walk with drift fallback",
        )
    X = np.column_stack([
        np.ones(n_obs),
        *[r[p - k - 1: lookback - k - 1] for k in range(p)]
    ])
    y = r[p:]
    try:
        XTX     = X.T @ X
        coeffs  = np.linalg.lstsq(XTX, X.T @ y, rcond=None)[0]
        c       = float(coeffs[0])
        phi     = coeffs[1:]
    except np.linalg.LinAlgError:
        c, phi  = float(r.mean()), np.zeros(p)
    residuals   = y - (X @ np.concatenate([[c], phi]))
    if len(residuals) > 1 and np.sum(residuals**2) > 1e-16:
        dw   = float(np.sum(np.diff(residuals)**2) / np.sum(residuals**2))
    else:
        dw   = 2.0
    dw_penalty  = 1.0 - abs(dw - 2.0) / 2.0                         
    confidence  = dw_penalty * 0.65 + 0.20
    history_buf = list(r[-p:])                                             
    forecast_returns = np.zeros(horizon)
    for h in range(horizon):
        r_hat = c + float(np.dot(phi, history_buf[-p:][::-1]))
        r_hat = float(np.clip(r_hat, -0.15, 0.15))                              
        forecast_returns[h] = r_hat
        history_buf.append(r_hat)
    path   = S0 * np.exp(np.cumsum(forecast_returns))
    signal = float(np.clip(np.sum(phi) / (1 - np.sum(phi) + 1e-6) * 2, -1, 1))
    desc = (
        f"AR(5)  c={c*1e4:.2f}e-4  Σφ={np.sum(phi):.3f}  "
        f"DW={dw:.2f}  {'good fit' if abs(dw-2)<0.5 else 'poor fit — use with caution'}"
    )
    return NodeResult(
        node_id=5, strategy="AR Model",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.15, 0.85)),
        signal=signal,
        signal_components={"ar_const": round(c,6), "phi_sum": round(float(np.sum(phi)),4),
                           "dw": round(dw,3)},
        description=desc,
    )
def _node_ewma_vol(
    returns: np.ndarray, horizon: int, S0: float
) -> NodeResult:
    LAMBDA    = 0.94                                                          
    T         = len(returns)
    lookback  = min(T, 252)
    r         = returns[-lookback:]
    var_ewma = float(np.var(r[:20]))                                               
    for rt in r:
        var_ewma = (1 - LAMBDA) * rt**2 + LAMBDA * var_ewma
    sigma_now = math.sqrt(max(var_ewma, 1e-10))                              
    sigma_avg = float(np.std(r, ddof=1))                                
    vol_ratio   = sigma_now / max(sigma_avg, 1e-10)
    vol_signal  = float(np.clip(1.0 - vol_ratio, -1, 1))                               
    mu_daily    = float(np.mean(r))
    if vol_ratio > 1.5:
        adj_mu = mu_daily * 0.5                                 
    elif vol_ratio < 0.7:
        adj_mu = mu_daily * 1.2                              
    else:
        adj_mu = mu_daily
    t_arr       = np.arange(1, horizon + 1)
    vol_decay   = sigma_now + (sigma_avg - sigma_now) * (1 - np.exp(-t_arr / 40))
    path        = S0 * np.exp(np.cumsum(adj_mu - 0.5 * vol_decay**2))
    signal      = float(np.clip(vol_signal * 0.7 + np.sign(mu_daily) * 0.3, -1, 1))
    confidence  = min(1.0 / max(vol_ratio, 0.5), 1.0) * 0.65 + 0.20
    desc = (
        f"σ_now={sigma_now*100:.2f}%/d  σ_avg={sigma_avg*100:.2f}%/d  "
        f"vol_ratio={vol_ratio:.2f}  "
        f"regime: {'HIGH-VOL (bearish)' if vol_ratio > 1.3 else 'LOW-VOL (bullish)' if vol_ratio < 0.8 else 'NORMAL'}"
    )
    return NodeResult(
        node_id=6, strategy="EWMA Vol",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.15, 0.88)),
        signal=signal,
        signal_components={"sigma_now_daily": round(sigma_now,6),
                           "sigma_avg_daily": round(sigma_avg,6),
                           "vol_ratio": round(vol_ratio,3),
                           "adj_mu_daily": round(adj_mu,6)},
        description=desc,
    )
def _node_support_resistance(
    close: np.ndarray, horizon: int, S0: float
) -> NodeResult:
    T        = len(close)
    lookback = min(T, 252)
    hi_52w   = float(np.max(close[-lookback:]))
    lo_52w   = float(np.min(close[-lookback:]))
    hi_20d   = float(np.max(close[-min(20, T):]))
    lo_20d   = float(np.min(close[-min(20, T):]))
    pivot    = (hi_20d + lo_20d + S0) / 3.0
    levels   = {
        "hi_52w": hi_52w, "lo_52w": lo_52w,
        "hi_20d": hi_20d, "lo_20d": lo_20d,
        "pivot":  pivot,
    }
    resistances = {k: v for k, v in levels.items() if v > S0 * 1.001}
    supports    = {k: v for k, v in levels.items() if v < S0 * 0.999}
    nearest_res = min(resistances.values()) if resistances else S0 * 1.20
    nearest_sup = max(supports.values())    if supports    else S0 * 0.80
    dist_res_pct = (nearest_res - S0) / S0                      
    dist_sup_pct = (S0 - nearest_sup) / S0                      
    res_weight  = 1.0 / max(dist_res_pct, 0.005)
    sup_weight  = 1.0 / max(dist_sup_pct, 0.005)
    total_w     = res_weight + sup_weight
    signal      = float(np.clip((sup_weight - res_weight) / total_w, -1, 1))
    confidence  = min((abs(signal) + 0.3) * 0.7, 0.85)
    if signal > 0:                                               
        target    = min(pivot, nearest_res * 0.99)
    else:                                                             
        target    = max(pivot, nearest_sup * 1.01)
    attr_speed   = 30
    t_arr        = np.arange(1, horizon + 1)
    path         = target + (S0 - target) * np.exp(-t_arr / attr_speed)
    key_str = (
        f"nearest res=₹{nearest_res:.2f}({dist_res_pct*100:.1f}% away)  "
        f"nearest sup=₹{nearest_sup:.2f}({dist_sup_pct*100:.1f}% away)  "
        f"pivot=₹{pivot:.2f}"
    )
    return NodeResult(
        node_id=7, strategy="Support / Res.",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.20, 0.85)),
        signal=signal,
        signal_components={"nearest_resistance": round(nearest_res,2),
                           "nearest_support": round(nearest_sup,2),
                           "pivot": round(pivot,2),
                           "dist_res_pct": round(dist_res_pct,4)},
        description=key_str,
    )
def _node_technical_composite(
    close: np.ndarray, returns: np.ndarray, horizon: int, S0: float
) -> NodeResult:
    def _ema(series, period):
        alpha = 2.0 / (period + 1)
        ema   = float(series[0])
        for val in series[1:]:
            ema = alpha * float(val) + (1 - alpha) * ema
        return ema
    T = len(close)
    if T >= 26:
        ema12 = _ema(close[-26:], 12)
        ema26 = float(close[-26:].mean())                        
        macd_val = ema12 - ema26
        macd_norm = float(np.clip(macd_val / (S0 * 0.02), -1, 1))
    else:
        macd_norm = 0.0
    if T >= 15:
        recent_rets = returns[-14:]
        gains   = recent_rets[recent_rets > 0]
        losses  = recent_rets[recent_rets < 0]
        avg_gain = float(gains.mean()) if len(gains) > 0 else 1e-10
        avg_loss = abs(float(losses.mean())) if len(losses) > 0 else 1e-10
        rs   = avg_gain / avg_loss
        rsi  = 100.0 - (100.0 / (1.0 + rs))
        rsi_signal = float(np.clip((50 - rsi) / 20.0, -1, 1))
    else:
        rsi = 50.0; rsi_signal = 0.0
    signal     = float(np.clip(0.6 * macd_norm + 0.4 * rsi_signal, -1, 1))
    aligned    = np.sign(macd_norm) == np.sign(rsi_signal)
    confidence = 0.65 + (0.25 if aligned and abs(signal) > 0.2 else 0.0)
    daily_drift = signal * 0.0025                                              
    decay       = np.exp(-np.arange(1, horizon + 1) / 25.0)
    path        = S0 * np.cumprod(1.0 + daily_drift * decay)
    desc = (
        f"MACD_norm={macd_norm:+.3f}  RSI={rsi:.1f}  "
        f"{'overbought' if rsi > 70 else 'oversold' if rsi < 30 else 'neutral'}  "
        f"signals {'aligned' if aligned else 'conflicted'}"
    )
    return NodeResult(
        node_id=8, strategy="Technical",
        forecast_path=path, forecast_price=float(path[-1]),
        confidence=float(np.clip(confidence, 0.20, 0.90)),
        signal=signal,
        signal_components={"macd_norm": round(macd_norm,4), "rsi": round(rsi,1),
                           "rsi_signal": round(rsi_signal,4), "aligned": int(aligned)},
        description=desc,
    )
def _detect_byzantine(
    nodes: List[NodeResult],
    threshold: float = 2.0,
) -> Tuple[List[int], List[NodeResult]]:
    prices = np.array([n.forecast_price for n in nodes])
    med    = float(np.median(prices))
    mad    = float(np.median(np.abs(prices - med)))
    mad    = max(mad, med * 0.001)                                        
    byzantine_ids = []
    clean_nodes   = []
    for node in nodes:
        z = abs(node.forecast_price - med) / (mad * 1.4826)                                
        if z > threshold:
            byzantine_ids.append(node.node_id)
            node.byzantine = True
        else:
            clean_nodes.append(node)
    return byzantine_ids, clean_nodes
def _fedavg_aggregate(
    nodes: List[NodeResult],
    method: str = "fedavg",
) -> AggregationResult:
    if not nodes:
        return AggregationResult(
            method=method, consensus_path=np.array([0.0]),
            consensus_price=0.0, lower_90=0.0, upper_90=0.0,
        )
    paths = np.array([n.forecast_path for n in nodes])                 
    if method == "fedavg":
        confs   = np.array([n.confidence for n in nodes])
        weights = confs / confs.sum()
        agg     = (paths * weights[:, np.newaxis]).sum(axis=0)
    elif method == "median":
        agg = np.median(paths, axis=0)
    elif method == "trimmed":
        n = len(nodes)
        k = max(1, int(n * 0.125))                                                
        sorted_idx  = np.argsort([n.forecast_price for n in nodes])
        keep_idx    = sorted_idx[k : n - k] if n > 2 * k else sorted_idx
        agg         = np.mean(paths[keep_idx], axis=0)
    else:
        agg = paths.mean(axis=0)
    terminal_prices = paths[:, -1]
    return AggregationResult(
        method          = method,
        consensus_path  = agg,
        consensus_price = float(agg[-1]),
        lower_90        = float(np.percentile(terminal_prices, 10)),
        upper_90        = float(np.percentile(terminal_prices, 90)),
    )
def _run_all_nodes(
    close:   np.ndarray,
    returns: np.ndarray,
    volume:  np.ndarray,
    horizon: int,
    S0:      float,
) -> List[NodeResult]:
    nodes = [
        _node_momentum(close, horizon, S0),
        _node_mean_reversion(close, horizon, S0),
        _node_trend_ols(close, horizon, S0),
        _node_volume_obv(close, volume, horizon, S0),
        _node_autocorr_ar(returns, horizon, S0),
        _node_ewma_vol(returns, horizon, S0),
        _node_support_resistance(close, horizon, S0),
        _node_technical_composite(close, returns, horizon, S0),
    ]
    return nodes
def _build_swarm_context(result: SwarmResult) -> dict:
    node_dicts = []
    for n in result.nodes:
        node_dicts.append({
            "node_id":       n.node_id,
            "strategy":      n.strategy,
            "forecast_price": round(n.forecast_price, 2),
            "pct_from_last":  round((n.forecast_price - result.last_price)
                                     / result.last_price * 100, 2),
            "confidence":    round(n.confidence, 3),
            "signal":        round(n.signal, 3),
            "byzantine":     n.byzantine,
            "signal_components": {k: round(v, 4) if isinstance(v, float) else v
                                  for k, v in n.signal_components.items()},
            "description":   n.description,
        })
    agg_dicts = {}
    for agg in [result.fedavg, result.median_agg, result.trimmed]:
        if agg:
            agg_dicts[agg.method] = {
                "consensus_price": round(agg.consensus_price, 2),
                "pct_from_last":   round((agg.consensus_price - result.last_price)
                                          / result.last_price * 100, 2),
                "lower_90":        round(agg.lower_90, 2),
                "upper_90":        round(agg.upper_90, 2),
                "spread_90_pct":   round((agg.upper_90 - agg.lower_90)
                                          / result.last_price * 100, 2),
            }
    clean_signals  = [n.signal for n in result.clean_nodes]
    bullish_nodes  = [n.strategy for n in result.clean_nodes if n.signal > 0.2]
    bearish_nodes  = [n.strategy for n in result.clean_nodes if n.signal < -0.2]
    neutral_nodes  = [n.strategy for n in result.clean_nodes if abs(n.signal) <= 0.2]
    return {
        "ticker":         result.ticker,
        "last_price":     round(result.last_price, 2),
        "horizon_days":   result.horizon,
        "date_run":       result.date_run,
        "n_nodes_total":  len(result.nodes),
        "n_byzantine":    len(result.byzantine_ids),
        "byzantine_ids":  result.byzantine_ids,
        "swarm_confidence": round(result.swarm_confidence, 3),
        "node_agreement":   round(result.node_agreement, 3),
        "bull_case_90":   round(result.bull_case, 2),
        "bear_case_90":   round(result.bear_case, 2),
        "nodes":          node_dicts,
        "aggregations":   agg_dicts,
        "signal_alignment": {
            "bullish_nodes":  bullish_nodes,
            "bearish_nodes":  bearish_nodes,
            "neutral_nodes":  neutral_nodes,
            "net_alignment":  round(float(np.mean(clean_signals)) if clean_signals else 0.0, 3),
        },
    }
def _build_m58_system_prompt(ctx: dict, model_name: str) -> str:
    import json, textwrap
    ticker    = ctx["ticker"]
    n_nodes   = ctx["n_nodes_total"]
    horizon   = ctx["horizon_days"]
    n_byz     = ctx["n_byzantine"]
    agreement = ctx["node_agreement"]
    persona = textwrap.dedent(f"""\
        You are a federated machine learning researcher and quantitative analyst.
        You have just run a {n_nodes}-node federated forecast swarm for {ticker}
        over a {horizon}-day horizon.
        {n_byz} node(s) were flagged as Byzantine (statistical outliers).
        Swarm agreement score: {agreement:.3f} (0=total disagreement, 1=perfect).
        You are powered by {model_name}.
        Your goal: help the user understand the swarm results, interpret each
        node's signal, assess the consensus reliability, and make practical
        decisions about how much to trust the forecast.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in the <node_results> or <aggregations> data.
        2. When citing a node's forecast, include its confidence and signal
           (e.g. "The Momentum node forecasts +8.2% with confidence 0.72").
        3. Explain Byzantine nodes: what signal behaviour caused the flag,
           and whether it's likely a meaningful outlier or a data artefact.
        4. When all clean nodes agree in direction (all bullish or bearish),
           flag this as a HIGH-CONVICTION swarm signal.
        5. When clean nodes split roughly 50/50, flag as LOW-CONVICTION
           — the swarm is uncertain and the user should widen their horizon.
        6. Compare FedAvg vs Median: a large gap implies one or two nodes
           dominate the weighted average — check which and why.
        7. Translate the bull_case_90 and bear_case_90 into position-sizing
           advice: what risk/reward ratio does the spread imply?
        8. Keep responses under 450 words unless the user asks for depth.
        9. Never predict a specific price with certainty — always frame as
           probabilistic scenarios.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Lead every response with: [SWARM] | [SIGNAL] | [RISK] | [ACTION]
        - **Bold** key ML/quant terms on first use.
        - Use Markdown tables for node-by-node comparisons.
        - Use > blockquotes when citing statistics from the data.
        - Colour-code signals in your language: bullish/bearish/neutral.
    """)
    summary_block = (
        "<swarm_summary>\n"
        + json.dumps({k: v for k, v in ctx.items()
                      if k not in ("nodes", "aggregations", "signal_alignment")},
                     indent=2)
        + "\n</swarm_summary>"
    )
    nodes_block = (
        "<node_results>\n"
        + json.dumps(ctx["nodes"], indent=2)
        + "\n</node_results>"
    )
    agg_block = (
        "<aggregations description='FedAvg vs Median vs Trimmed'>\n"
        + json.dumps(ctx["aggregations"], indent=2)
        + "\n</aggregations>"
    )
    align_block = (
        "<signal_alignment>\n"
        + json.dumps(ctx["signal_alignment"], indent=2)
        + "\n</signal_alignment>"
    )
    return "\n\n".join([persona, rules, fmt, summary_block,
                        nodes_block, agg_block, align_block])
def _m58_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        import subprocess, sys
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    import json, time
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS = 20
    if (len(history) - 1) // 2 > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 58 Federated Swarm Co-Pilot",
        "Content-Type":  "application/json",
    }
    payload  = {"model": model_id, "messages": history, "stream": True}
    full_response = ""
    for attempt in range(3):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers, json=payload, stream=True, timeout=(10, 90),
            )
            if resp.status_code == 401:
                console.print("\n  [bold red][!] API key rejected. Use /setkey.[/bold red]")
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            word_count = 0
            print(f"\n  \033[90m{model_name} is analysing ", end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                ps = line[6:]
                if ps.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(ps)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        word_count    += len(token.split())
                        if word_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({word_count} words)\033[0m\n")
            if full_response.strip():
                console.print(Panel(
                    Markdown(full_response),
                    title=f"[bold cyan]{model_name}[/bold cyan]",
                    border_style="cyan", padding=(1, 2), expand=True,
                ))
            return full_response
        except requests.Timeout:
            console.print("\n  [bold red][!] Request timed out.[/bold red]")
            return ""
        except Exception as exc:
            if attempt < 2:
                w = 1.5 ** (attempt + 1)
                console.print(f"  [yellow][~] Attempt {attempt+1} failed. Retry in {w:.1f}s…[/yellow]")
                time.sleep(w)
            else:
                console.print(f"  [bold red][!] All 3 attempts failed: {exc}[/bold red]")
    return ""
def _print_m58_chat_help() -> None:
    print("\n  ── Module 58 Federated Swarm Co-Pilot Commands ──────")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter"),
        ("/nodes",       "Ask AI to explain each node's signal"),
        ("/byzantine",   "Ask AI to analyse Byzantine flagged nodes"),
        ("/swarm",       "Ask AI for full swarm consensus interpretation"),
        ("/disagree",    "Ask AI to explain the biggest node disagreements"),
        ("/action",      "Ask AI for a practical trading action summary"),
        ("/clear",       "Reset conversation (keeps swarm context)"),
        ("/export",      "Save session to timestamped JSON"),
        ("/status",      "Show model, key, swarm summary"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to swarm menu"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m58_chat(ctx: dict, cfg: Optional[dict] = None) -> None:
    if cfg is None:
        cfg = _m58_load_config()
    if not cfg["api_key"]:
        print("\n  \033[93m[!] No API key configured for the Swarm Co-Pilot.\033[0m")
        cfg = _m58_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Configure a key to enable this.")
            return
    history = [
        {
            "role":    "system",
            "content": _build_m58_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    B, CY, G, Y, R, M, RST = (
        '\033[1m', '\033[96m', '\033[92m', '\033[93m',
        '\033[91m', '\033[95m', '\033[0m'
    )
    ticker    = ctx["ticker"]
    n_byz     = ctx["n_byzantine"]
    agreement = ctx["node_agreement"]
    fedavg_p  = ctx["aggregations"].get("fedavg", {}).get("consensus_price", 0)
    print("\n" + "─" * 68)
    print(f"  {M}✦ FEDERATED SWARM AI CO-PILOT{RST}  |  {CY}{cfg['model_name']}{RST}")
    print(f"  {Y}{ticker}{RST}  |  {CY}{ctx['n_nodes_total']} nodes{RST}  |  "
          f"\033[90magreement={agreement:.3f}  Byzantine={n_byz}  "
          f"FedAvg=₹{fedavg_p:.2f}\033[0m")
    print("  Ask about node signals, consensus reliability, or trading strategy.")
    print("  Type /help for commands.")
    print("─" * 68)
    align     = ctx["signal_alignment"]
    net_align = align["net_alignment"]
    first_prompt = (
        f"I just ran a {ctx['n_nodes_total']}-node federated swarm forecast for "
        f"{ticker} over {ctx['horizon_days']} trading days. "
        f"{n_byz} node(s) were Byzantine. Swarm agreement = {agreement:.3f}. "
        f"Net signal alignment = {net_align:+.3f}. "
        f"Bullish nodes: {align['bullish_nodes']}. "
        f"Bearish nodes: {align['bearish_nodes']}. "
        f"Please give me: "
        f"(1) A Markdown table of all 8 nodes showing strategy, signal, "
        f"confidence, forecast price, and % change from current price. "
        f"(2) The single most important signal finding — "
        f"is this a high-conviction or low-conviction swarm? Why? "
        f"(3) If any Byzantine nodes were flagged, explain what their "
        f"outlier forecast implies and whether it should concern me. "
        f"(4) Which aggregation method (FedAvg, Median, or Trimmed) should "
        f"I trust most for THIS specific swarm run, and why?"
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m58_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        print(f"  {R}[!] Auto-analysis failed. Ask questions below.{RST}\n")
    while True:
        try:
            from rich.console import Console
            user_input = Console().input("\n  [bold cyan]You ›[/bold cyan] ").strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Session ended]"); break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m58_chat_help(); continue
        elif cmd == "/setkey":
            cfg = _m58_setup_key(cfg)
            history[0]["content"] = _build_m58_system_prompt(ctx, cfg["model_name"])
            continue
        elif cmd == "/models":
            cfg = _m58_pick_model(cfg)
            history[0]["content"] = _build_m58_system_prompt(ctx, cfg["model_name"])
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}"); print("  Usage: /model <id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = arg.split("/")[-1].replace(":free"," (free)").replace("-"," ").title()
                _m58_save_config(cfg)
                history[0]["content"] = _build_m58_system_prompt(ctx, cfg["model_name"])
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get("http://127.0.0.1:9999/disabled", timeout=10)
                resp.raise_for_status()
                free = [m for m in resp.json().get("data",[]) if m.get("id","").endswith(":free")]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    print(f"  {m['id']:<55} {(m.get('context_length') or 0)//1000:>5}K")
                print(f"\n  {len(free)} free models. Use: /model <id>\n")
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/nodes":
            np_ = (
                "For each of the 8 nodes, produce a 2-3 sentence explanation of: "
                "(1) what signal mechanism it uses, (2) what the current signal value "
                "means for this stock specifically, and (3) why it might agree or "
                "disagree with the rest of the swarm. Format as a Markdown table."
            )
            history.append({"role": "user", "content": np_})
        elif cmd == "/byzantine":
            if ctx["n_byzantine"] == 0:
                print("  [✓] No Byzantine nodes detected in this run.")
                continue
            byz_ids   = ctx["byzantine_ids"]
            byz_nodes = [n for n in ctx["nodes"] if n["node_id"] in byz_ids]
            bp = (
                f"Byzantine nodes flagged: {byz_ids}. "
                f"Their forecasts: {[n['forecast_price'] for n in byz_nodes]}. "
                f"Their signals: {[n['signal'] for n in byz_nodes]}. "
                f"Explain: (1) why each was flagged as a Byzantine outlier, "
                f"(2) whether its extreme forecast might actually be correct "
                f"(are there fundamental reasons this node could be right?), "
                f"(3) the risk of excluding it vs including it in the consensus."
            )
            history.append({"role": "user", "content": bp})
        elif cmd == "/swarm":
            sp = (
                "Give me a complete swarm consensus interpretation: "
                "Compare the three aggregation methods (FedAvg, Median, Trimmed). "
                "Explain what the node agreement score means in terms of forecast "
                "reliability. State whether this is a high, medium, or low confidence "
                "forecast, and what the 90% prediction interval implies for position sizing."
            )
            history.append({"role": "user", "content": sp})
        elif cmd == "/disagree":
            dp = (
                "Focus on disagreement within the swarm. "
                "Which two nodes have the most conflicting signals/forecasts? "
                "What does their disagreement tell us about competing market forces "
                "currently affecting this stock? "
                "Is the disagreement structurally meaningful (e.g. momentum vs mean "
                "reversion — a classic market debate) or likely due to noise?"
            )
            history.append({"role": "user", "content": dp})
        elif cmd == "/action":
            ap = (
                "Translate the swarm results into a practical trading action summary. "
                "For each of three investor profiles — (a) momentum trader, "
                "(b) value/mean-reversion investor, (c) long-term buy-and-hold — "
                "what does the swarm suggest? Include: direction, conviction level, "
                "suggested position size as a fraction of portfolio (based on the "
                f"bull/bear case spread of ₹{ctx['bull_case_90']:.0f}–₹{ctx['bear_case_90']:.0f}), "
                "and one specific risk to watch for."
            )
            history.append({"role": "user", "content": ap})
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. Swarm context retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns = (len(history) - 1) // 2
            kh    = f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}" if len(cfg["api_key"])>12 else "not set"
            fedavg_str = f"₹{ctx['aggregations'].get('fedavg',{}).get('consensus_price',0):.2f}"
            print(f"\n  Model    : {cfg['model_name']}")
            print(f"  API Key  : {kh}")
            print(f"  Ticker   : {ticker}  |  Horizon: {ctx['horizon_days']}d")
            print(f"  FedAvg   : {fedavg_str}  |  Agreement: {agreement:.3f}")
            print(f"  Byzantine: {n_byz}  |  History: {turns} turns\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help."); continue
        if not user_input.startswith("/"):
            history.append({"role": "user", "content": user_input})
        ai_resp = _m58_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_resp: history.append({"role": "assistant", "content": ai_resp})
        else:       history.pop()
    print("  [Swarm session closed — returning to Swarm menu]\n")
class FederatedSwarmAI:
    def __init__(
        self,
        ticker:           str,
        horizon:          int   = 63,
        byzantine_thresh: float = 2.0,
    ):
        self.ticker           = ticker.strip().upper() if ticker else "RELIANCE.NS"
        self.node_count       = 8                                     
        self.horizon          = horizon
        self.byzantine_thresh = byzantine_thresh
        self._close:   Optional[np.ndarray] = None
        self._returns: Optional[np.ndarray] = None
        self._volume:  Optional[np.ndarray] = None
        self._last_price: float = 0.0
        self._data_loaded: bool = False
        self._last_result:  Optional[SwarmResult] = None
    @staticmethod
    def _check_dependencies() -> bool:
        required = {
            "numpy":    "pip install numpy",
            "pandas":   "pip install pandas",
            "yfinance": "pip install yfinance",
            "matplotlib":"pip install matplotlib",
            "plotly":   "pip install plotly",
        }
        missing = [(lib, cmd) for lib, cmd in required.items()
                   if not __import__("importlib").util.find_spec(lib)]
        if missing:
            print(f"\n  \033[91m[!] Missing dependencies:\033[0m")
            for lib, cmd in missing:
                print(f"      \033[93m{lib:<14}\033[0m → {cmd}")
            return False
        return True
    def _fetch_data(self) -> bool:
        B, CY, G, Y, R, M, RST = (
            '\033[1m', '\033[96m', '\033[92m', '\033[93m',
            '\033[91m', '\033[95m', '\033[0m'
        )
        try:
            pass
        except ImportError as e:
            print(f"  {R}[!] Import error: {e}{RST}")
            return False
        print(f"  {CY}Downloading 1Y daily data for {self.ticker} …{RST}")
        try:
            raw = yf.download(
                self.ticker, period="1y", interval="1d",
                progress=False, auto_adjust=True,
            )
        except Exception as exc:
            print(f"  {R}[!] Download error: {exc}{RST}")
            return False
        if raw.empty:
            print(f"  {R}[!] Empty data. Check ticker format (e.g. RELIANCE.NS, AAPL).{RST}")
            return False
        if isinstance(raw.columns, pd.MultiIndex):
            raw.columns = raw.columns.get_level_values(0)
        if "Close" not in raw.columns:
            print(f"  {R}[!] 'Close' column not found. Check yfinance version.{RST}")
            return False
        close_s   = raw["Close"].dropna()
        volume_s  = raw["Volume"].dropna().reindex(close_s.index).fillna(0)
        T = len(close_s)
        if T < 30:
            print(f"  {R}[!] Only {T} trading days — need at least 30.{RST}")
            return False
        self._close     = close_s.values.astype(float)
        self._volume    = volume_s.values.astype(float)
        self._returns   = np.diff(np.log(self._close))               
        self._last_price = float(self._close[-1])
        self._data_loaded = True
        date_start = str(close_s.index[0])[:10]
        date_end   = str(close_s.index[-1])[:10]
        print(f"  {G}[✓] {T} trading days loaded  "
              f"({date_start} → {date_end})  S0=₹{self._last_price:.2f}{RST}")
        return True
    def _run_swarm(self) -> Optional[SwarmResult]:
        from datetime import date
        if not self._data_loaded:
            print("  \033[91m[!] Fetch data first (option F).\033[0m")
            return None
        B, CY, G, Y, R, M, RST = (
            '\033[1m', '\033[96m', '\033[92m', '\033[93m',
            '\033[91m', '\033[95m', '\033[0m'
        )
        BB = '\033[44m\033[97m'
        print(f"\n  {CY}Deploying {self.node_count} federated intelligence nodes …{RST}")
        print(f"  {B}{'─'*60}{RST}")
        t0    = time.perf_counter()
        nodes = _run_all_nodes(
            self._close, self._returns, self._volume,
            self.horizon, self._last_price,
        )
        elapsed = time.perf_counter() - t0
        for n in nodes:
            bar  = "▓" * int(n.confidence * 20) + "░" * (20 - int(n.confidence * 20))
            sign = "\033[92m▲" if n.signal > 0.1 else ("\033[91m▼" if n.signal < -0.1 else "\033[93m─")
            byz_tag = f"  \033[91m[BYZANTINE]\033[0m" if n.byzantine else ""
            print(
                f"  {B}[Node {n.node_id:02}]{RST}  {n.strategy:<20}  "
                f"₹{n.forecast_price:>10,.2f}  "
                f"conf={n.confidence:.2f}  {bar}  "
                f"{sign} {n.signal:+.2f}\033[0m{byz_tag}"
            )
        byzantine_ids, clean_nodes = _detect_byzantine(
            nodes, threshold=self.byzantine_thresh
        )
        if byzantine_ids:
            print(f"\n  {Y}[⚠] Byzantine nodes detected: {byzantine_ids}  "
                  f"(z-score > {self.byzantine_thresh}){RST}")
        else:
            print(f"\n  {G}[✓] All nodes passed Byzantine filter.{RST}")
        use_nodes = clean_nodes if clean_nodes else nodes                           
        fedavg    = _fedavg_aggregate(use_nodes, method="fedavg")
        median_r  = _fedavg_aggregate(use_nodes, method="median")
        trimmed   = _fedavg_aggregate(use_nodes, method="trimmed")
        clean_prices = np.array([n.forecast_price for n in clean_nodes]) if clean_nodes                       else np.array([n.forecast_price for n in nodes])
        clean_confs  = np.array([n.confidence for n in (clean_nodes or nodes)])
        swarm_conf   = float(np.average(clean_confs))
        cv           = float(np.std(clean_prices) / max(np.mean(clean_prices), 1e-12))
        node_agr     = float(1.0 - min(cv, 1.0))                                             
        bull_90 = float(np.percentile(clean_prices, 90))
        bear_10 = float(np.percentile(clean_prices, 10))
        result = SwarmResult(
            ticker           = self.ticker,
            last_price       = self._last_price,
            horizon          = self.horizon,
            nodes            = nodes,
            clean_nodes      = clean_nodes if clean_nodes else nodes,
            byzantine_ids    = byzantine_ids,
            fedavg           = fedavg,
            median_agg       = median_r,
            trimmed          = trimmed,
            swarm_confidence = swarm_conf,
            node_agreement   = node_agr,
            bull_case        = bull_90,
            bear_case        = bear_10,
            date_run         = str(date.today()),
        )
        self._last_result = result
        print(f"\n  {B}{'═'*60}{RST}")
        print(f"  {BB}  SWARM CONSENSUS  |  {self.ticker}  "
              f"|  {self.node_count} nodes  |  {self.horizon}d forecast  {' '*4}{RST}")
        print(f"  {B}{'═'*60}{RST}")
        print(f"  {'Method':<20}  {'Consensus':>12}  {'Δ from last':>12}  {'90% range':>16}")
        print(f"  {'─'*60}")
        for agg in [fedavg, median_r, trimmed]:
            delta = (agg.consensus_price - self._last_price) / self._last_price * 100
            dc    = G if delta >= 0 else R
            print(
                f"  {B}{agg.method.title():<20}{RST}  "
                f"{dc}₹{agg.consensus_price:>10,.2f}{RST}  "
                f"{dc}{delta:>+11.2f}%{RST}  "
                f"[₹{agg.lower_90:,.0f}–₹{agg.upper_90:,.0f}]"
            )
        print(f"  {'─'*60}")
        print(f"  {B}{'Node Agreement':<20}{RST}  {CY}{node_agr:.3f}{RST}  "
              f"\033[90m(0=total disagreement, 1=perfect)\033[0m")
        print(f"  {B}{'Swarm Confidence':<20}{RST}  {CY}{swarm_conf:.3f}{RST}  "
              f"\033[90m(weighted avg confidence across clean nodes)\033[0m")
        print(f"  {B}{'Byzantine nodes':<20}{RST}  "
              f"{R if byzantine_ids else G}{len(byzantine_ids)}/8{RST}")
        print(f"  {B}{'Bull case (90th)':<20}{RST}  {G}₹{bull_90:>10,.2f}{RST}")
        print(f"  {B}{'Bear case (10th)':<20}{RST}  {R}₹{bear_10:>10,.2f}{RST}")
        print(f"  {B}{'─'*60}{RST}")
        print(f"  {B}Runtime:{RST} {elapsed*1000:.0f} ms")
        print(f"  {B}{'═'*60}{RST}")
        return result
    def _display_node_detail(self) -> None:
        if self._last_result is None:
            print("  \033[91m[!] Run swarm first (option R).\033[0m")
            return
        B, CY, G, Y, R, M, RST = (
            '\033[1m', '\033[96m', '\033[92m', '\033[93m',
            '\033[91m', '\033[95m', '\033[0m'
        )
        BB = '\033[44m\033[97m'
        print(f"\n  {BB}  NODE SIGNAL EXPLAINABILITY REPORT  "
              f"|  {self.ticker}  {' '*18}{RST}")
        for n in self._last_result.nodes:
            byz_str = f"  {R}[BYZANTINE — excluded from FedAvg]{RST}" if n.byzantine else ""
            sc      = G if n.signal > 0.1 else (R if n.signal < -0.1 else Y)
            print(f"\n  {B}Node {n.node_id} — {n.strategy}{RST}{byz_str}")
            print(f"  {'─'*60}")
            print(f"  Signal:   {sc}{n.signal:+.3f}{RST}  "
                  f"({'BULLISH' if n.signal > 0.1 else 'BEARISH' if n.signal < -0.1 else 'NEUTRAL'})")
            print(f"  Forecast: ₹{n.forecast_price:,.2f}  "
                  f"({(n.forecast_price - self._last_price)/self._last_price*100:+.1f}%)")
            print(f"  Confidence: {CY}{n.confidence:.3f}{RST}")
            print(f"  Rationale: {n.description}")
            print(f"  Components: " + "  ".join(
                f"{k}={v}" for k, v in n.signal_components.items()
            ))
        print(f"\n  {B}{'═'*60}{RST}")
    def visualize_2d(self) -> None:
        if self._last_result is None:
            print("  \033[91m[!] Run swarm first (option R).\033[0m")
            return
        result = self._last_result
        S0     = result.last_price
        days   = np.arange(1, result.horizon + 1)
        NODE_COLORS = {
            1: "#7F77DD",                     
            2: "#5DCAA5",                         
            3: "#378ADD",                
            4: "#1D9E75",                  
            5: "#D85A30",                    
            6: "#EF9F27",                    
            7: "#E24B4A",                     
            8: "#7F77DD",                              
        }
        print(f"  \033[95mRendering 2D swarm fan chart …\033[0m")
        fig = plt.figure(figsize=(18, 9))
        gs  = gridspec.GridSpec(2, 2, width_ratios=[2.2, 1.8], hspace=0.35, wspace=0.3)
        ax1 = fig.add_subplot(gs[:, 0])
        ax2 = fig.add_subplot(gs[0, 1])
        ax3 = fig.add_subplot(gs[1, 1])
        fig.suptitle(
            f"Federated Swarm AI Forecast  |  {self.ticker}  |  "
            f"{result.node_count if hasattr(result,'node_count') else 8} nodes  |  "
            f"{result.horizon}d horizon  |  "
            f"Byzantine: {len(result.byzantine_ids)}",
            fontsize=14, fontweight="bold",
        )
        all_paths = np.array([n.forecast_path for n in result.clean_nodes])
        ax1.axhline(S0, color="gray", ls=":", lw=1.0, alpha=0.5, label=f"Current ₹{S0:.2f}")
        ax1.fill_between(
            days,
            np.percentile(all_paths, 10, axis=0),
            np.percentile(all_paths, 90, axis=0),
            alpha=0.12, color="teal", label="10th–90th pctile (clean nodes)",
        )
        for n in result.nodes:
            ls    = "--" if n.byzantine else "-"
            alpha = 0.3 if n.byzantine else 0.6
            color = NODE_COLORS.get(n.node_id, "#888888")
            ax1.plot(days, n.forecast_path, ls=ls, alpha=alpha,
                     lw=1.2, color=color, label=n.strategy)
        if result.fedavg:
            ax1.plot(days, result.fedavg.consensus_path,
                     "k-", lw=2.5, label="FedAvg Consensus", zorder=5)
        if result.median_agg:
            ax1.plot(days, result.median_agg.consensus_path,
                     color="#333333", lw=1.5, ls="--", alpha=0.7,
                     label="Median Consensus")
        ax1.set_title(f"Swarm Forecast Fan — {self.ticker}", fontweight="bold")
        ax1.set_xlabel("Forecast Day")
        ax1.set_ylabel("Price (₹)")
        ax1.legend(fontsize=8, ncol=2, loc="upper left")
        ax1.grid(True, alpha=0.2)
        sorted_nodes = sorted(result.nodes, key=lambda n: n.confidence)
        colors_conf  = [NODE_COLORS.get(n.node_id, "#888") for n in sorted_nodes]
        edge_colors  = ["red" if n.byzantine else "none" for n in sorted_nodes]
        bars = ax2.barh(
            [n.strategy for n in sorted_nodes],
            [n.confidence for n in sorted_nodes],
            color=colors_conf, edgecolor=edge_colors, linewidth=1.5, alpha=0.8,
        )
        ax2.axvline(0.5, color="orange", ls="--", lw=1.0, alpha=0.7)
        ax2.set_xlim(0, 1.05)
        ax2.set_title("Node Confidence (red border = Byzantine)", fontweight="bold")
        ax2.set_xlabel("Confidence Score")
        ax2.grid(True, axis="x", alpha=0.2)
        for bar, node in zip(bars, sorted_nodes):
            ax2.text(bar.get_width() + 0.01, bar.get_y() + bar.get_height() / 2,
                     f"{node.confidence:.2f}", va="center", fontsize=8)
        terminal_prices = [n.forecast_price for n in result.clean_nodes]
        ax3.hist(terminal_prices, bins=max(4, len(terminal_prices)),
                 color="#7F77DD", alpha=0.55, edgecolor="black", lw=0.5)
        ax3.axvline(S0, color="gray", ls=":", lw=1.5, label=f"S0 ₹{S0:.0f}")
        if result.fedavg:
            ax3.axvline(result.fedavg.consensus_price, color="black", lw=2.0,
                        label=f"FedAvg ₹{result.fedavg.consensus_price:.0f}")
        ax3.axvline(result.bull_case, color="green", ls="--", lw=1.5,
                    label=f"Bull 90th ₹{result.bull_case:.0f}")
        ax3.axvline(result.bear_case, color="red", ls="--", lw=1.5,
                    label=f"Bear 10th ₹{result.bear_case:.0f}")
        ax3.set_title("Terminal Price Distribution", fontweight="bold")
        ax3.set_xlabel("Terminal Price (₹)")
        ax3.set_ylabel("Count")
        ax3.legend(fontsize=8)
        ax3.grid(True, alpha=0.2)
        plt.tight_layout(rect=[0, 0, 1, 0.96])
        plt.show()
    def visualize_3d(self) -> None:
        if self._last_result is None:
            print("  \033[91m[!] Run swarm first (option R).\033[0m")
            return
        try:
            import plotly.graph_objs as go
        except ImportError:
            print("  \033[91m[!] plotly required: pip install plotly\033[0m")
            return
        result   = self._last_result
        S0       = result.last_price
        horizon  = result.horizon
        n_nodes  = len(result.nodes)
        DARK_BG  = "#0e1117"
        ACCENT   = "#00d4aa"
        print(f"  \033[95mBuilding 3D prediction landscape …\033[0m")
        try:
            node_paths = np.array([n.forecast_path for n in result.nodes], dtype=float)
        except ValueError:
            min_len = min(len(n.forecast_path) for n in result.nodes)
            node_paths = np.array([n.forecast_path[:min_len] for n in result.nodes], dtype=float)
            horizon = min_len
        strategy_names = [n.strategy for n in result.nodes]
        if result.fedavg and len(result.fedavg.consensus_path) >= horizon:
            consensus = np.array(result.fedavg.consensus_path[:horizon], dtype=float)
            deviation = node_paths - consensus[np.newaxis, :]
        else:
            deviation = np.zeros_like(node_paths)
        days_ax  = np.arange(1, horizon + 1)
        nodes_ax = np.arange(1, n_nodes + 1)
        X_mesh, Y_mesh = np.meshgrid(days_ax, nodes_ax)
        Z_surface      = node_paths
        C_surface      = deviation
        surf = go.Surface(
            x=X_mesh, y=Y_mesh, z=Z_surface,
            surfacecolor=C_surface,
            colorscale=[
                [0.0,  "#185FA5"],                                    
                [0.35, "#5DCAA5"],                          
                [0.50, "#888780"],                        
                [0.65, "#EF9F27"],                           
                [1.0,  "#A32D2D"],                              
            ],
            opacity=0.88,
            showscale=True,
            colorbar=dict(
                title=dict(text="Deviation from FedAvg (₹)", font=dict(color=ACCENT)),
                tickfont=dict(color=ACCENT),
            ),
            hovertemplate=(
                "Day: %{x}<br>"
                "Node: %{y}<br>"
                "Price: ₹%{z:.2f}<br>"
                "vs FedAvg: ₹%{surfacecolor:.2f}<extra></extra>"
            ),
        )
        fig1_data = [surf]
        if result.fedavg:
            cons_line = go.Scatter3d(
                x=days_ax,
                y=np.full(horizon, (n_nodes + 1) / 2.0),
                z=result.fedavg.consensus_path[:horizon],
                mode="lines",
                line=dict(color=ACCENT, width=8),
                name="FedAvg consensus",
                hovertemplate="Day: %{x}<br>FedAvg: ₹%{z:.2f}<extra></extra>",
            )
            fig1_data.append(cons_line)
        x_p, y_p = np.meshgrid([1, horizon], [1, n_nodes])
        z_p      = np.full_like(x_p, S0, dtype=float)
        baseline_plane = go.Surface(
            x=x_p, y=y_p, z=z_p,
            opacity=0.12, showscale=False,
            colorscale=[[0, "gray"], [1, "gray"]],
            name=f"S0 = ₹{S0:.2f}",
            hoverinfo="skip",
        )
        fig1_data.insert(0, baseline_plane)
        fig1 = go.Figure(data=fig1_data)
        fig1.update_layout(
            title=dict(
                text=f"3D Swarm Prediction Landscape — {self.ticker}  "
                     f"[{horizon}d horizon | warm=above consensus, cool=below]",
                font=dict(color=ACCENT, size=15),
            ),
            scene=dict(
                xaxis=dict(title="Forecast Day", color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                yaxis=dict(title="Node", color=ACCENT,
                           tickvals=list(range(1, n_nodes+1)), ticktext=strategy_names,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                zaxis=dict(title="Predicted Price (₹)", color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                bgcolor=DARK_BG,
                camera=dict(eye=dict(x=1.8, y=-1.6, z=0.9)),
            ),
            paper_bgcolor=DARK_BG,
            font=dict(color=ACCENT),
            margin=dict(l=0, r=0, b=0, t=50),
            legend=dict(font=dict(color=ACCENT), bgcolor=DARK_BG),
        )
        print(f"  \033[92mLaunching 3D Prediction Landscape in browser …\033[0m")
        fig1.show()
        print(f"  \033[95mBuilding 3D signal quality scatter …\033[0m")
        signals   = [n.signal    for n in result.nodes]
        confs     = [n.confidence for n in result.nodes]
        ret_pcts  = [(n.forecast_price - S0) / S0 * 100 for n in result.nodes]
        byz_mask  = [n.byzantine for n in result.nodes]
        colors_pt = ["#E24B4A" if b else "#7F77DD" for b in byz_mask]
        sizes_pt  = [14 if b else 10 for b in byz_mask]
        text_pt   = [f"{n.strategy}<br>Signal: {n.signal:+.3f}<br>"
                     f"Conf: {n.confidence:.2f}<br>Ret: {r:+.1f}%"
                     for n, r in zip(result.nodes, ret_pcts)]
        scatter3d = go.Scatter3d(
            x=signals, y=confs, z=ret_pcts,
            mode="markers+text",
            marker=dict(
                size=sizes_pt, color=colors_pt,
                line=dict(color="#ffffff", width=1.0),
                opacity=0.85,
            ),
            text=[n.strategy for n in result.nodes],
            textposition="top center",
            textfont=dict(color=ACCENT, size=10),
            hovertext=text_pt,
            hoverinfo="text",
            name="Nodes (red = Byzantine)",
        )
        x_sig, y_c = np.meshgrid([-1, 1], [0, 1])
        zero_signal_plane = go.Surface(
            x=x_sig, y=y_c, z=np.zeros_like(x_sig),
            opacity=0.08, showscale=False,
            colorscale=[[0,"gray"],[1,"gray"]], hoverinfo="skip",
        )
        fig2 = go.Figure(data=[zero_signal_plane, scatter3d])
        fig2.update_layout(
            title=dict(
                text=f"Signal Quality Scatter — {self.ticker}  "
                     f"[X=signal | Y=confidence | Z=forecast return %]  "
                     f"red=Byzantine",
                font=dict(color=ACCENT, size=14),
            ),
            scene=dict(
                xaxis=dict(title="Signal (−1=bear, +1=bull)", color=ACCENT,
                           range=[-1.1, 1.1], gridcolor="#333",
                           backgroundcolor=DARK_BG),
                yaxis=dict(title="Node confidence", color=ACCENT,
                           range=[0, 1.1], gridcolor="#333",
                           backgroundcolor=DARK_BG),
                zaxis=dict(title="Forecast return (%)", color=ACCENT,
                           gridcolor="#333", backgroundcolor=DARK_BG),
                bgcolor=DARK_BG,
                camera=dict(eye=dict(x=1.5, y=1.5, z=1.2)),
            ),
            paper_bgcolor=DARK_BG,
            font=dict(color=ACCENT),
            margin=dict(l=0, r=0, b=0, t=50),
        )
        print(f"  \033[92mLaunching Signal Quality Scatter in browser …\033[0m")
        fig2.show()
    def interactive_menu(self) -> None:
        if not self._check_dependencies():
            return
        ai_cfg = _m58_load_config()
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            B, CY, G, Y, R, M, RST = (
                '\033[1m', '\033[96m', '\033[92m', '\033[93m',
                '\033[91m', '\033[95m', '\033[0m'
            )
            BB = '\033[44m\033[97m'
            has_data   = self._data_loaded
            has_result = self._last_result is not None
            ds = f"{G}[data ready]{RST}" if has_data else f"{Y}[no data — press F]{RST}"
            rs = f"{G}[swarm ready]{RST}" if has_result else f"{Y}[not run]{RST}"
            fedavg_str = ""
            if has_result and self._last_result.fedavg:
                fa  = self._last_result.fedavg
                dlt = (fa.consensus_price - self._last_price) / self._last_price * 100
                dc  = G if dlt >= 0 else R
                fedavg_str = (
                    f"\n  {B}FedAvg:{RST}  {dc}₹{fa.consensus_price:,.2f}  ({dlt:+.1f}%){RST}  "
                    f"Agreement: {CY}{self._last_result.node_agreement:.3f}{RST}  "
                    f"Byzantine: {R if self._last_result.byzantine_ids else G}"
                    f"{len(self._last_result.byzantine_ids)}{RST}"
                )
            print(f"\n  {BB} MODULE 58 — FEDERATED SWARM AI  {' '*44}{RST}")
            print(f"  {'═'*76}")
            print(f"  {B}Ticker:{RST}  {CY}{self.ticker}{RST}   {ds}   {rs}")
            print(f"  {B}Nodes:{RST} 8 (fixed)   {B}Horizon:{RST} {self.horizon}d   "
                  f"{B}Byzantine threshold:{RST} z>{self.byzantine_thresh:.1f}")
            if fedavg_str:
                print(fedavg_str)
            print(f"  {'═'*76}")
            print(f"  {B}F.{RST} {G}Fetch Market Data{RST}")
            print(f"  {B}R.{RST} Run Federated Swarm  (all 8 nodes + aggregation)")
            if has_result:
                print(f"  {'─'*76}")
                print(f"  {B}2.{RST} 2D Fan Chart  (matplotlib paths + confidence + distribution)")
                print(f"  {B}3.{RST} {CY}3D Prediction Landscape + Signal Scatter  (Plotly){RST}")
                print(f"  {B}D.{RST} Node Explainability Report  (signal components per node)")
                print(f"  {B}I.{RST} {M}AI Federated Swarm Co-Pilot{RST}")
            print(f"  {'─'*76}")
            print(f"  {B}H.{RST} Tune Hyperparameters  (horizon, Byzantine threshold)")
            print(f"  {B}X.{RST} Change Ticker")
            print(f"  {B}0.{RST} Return to Main Menu")
            print(f"  {'═'*76}")
            choice = input(f"\n  Select: ").strip().upper()
            if choice == '0':
                break
            elif choice == 'F':
                self._fetch_data()
                input(f"\n  Press ENTER to continue …")
            elif choice == 'R':
                if not has_data:
                    print(f"  {CY}Auto-fetching data first …{RST}")
                    if not self._fetch_data():
                        input(f"\n  Press ENTER to continue …"); continue
                self._run_swarm()
                input(f"\n  Press ENTER to continue …")
            elif choice == '2' and has_result:
                self.visualize_2d()
                input(f"\n  Press ENTER to continue …")
            elif choice == '3' and has_result:
                self.visualize_3d()
                input(f"\n  Press ENTER to continue …")
            elif choice == 'D' and has_result:
                self._display_node_detail()
                input(f"\n  Press ENTER to continue …")
            elif choice == 'I' and has_result:
                ctx = _build_swarm_context(self._last_result)
                run_m58_chat(ctx, cfg=ai_cfg)
            elif choice == 'H':
                try:
                    h = input(f"  Horizon days (current: {self.horizon}, min 5, max 252): ").strip()
                    if h.isdigit() and 5 <= int(h) <= 252:
                        self.horizon     = int(h)
                        self._last_result = None          
                    elif h:
                        print(f"  {R}[!] Must be 5–252.{RST}")
                    bt = input(f"  Byzantine z-score threshold (current: {self.byzantine_thresh:.1f}, "
                               f"typical 1.5–3.0): ").strip()
                    try:
                        btf = float(bt)
                        if 1.0 <= btf <= 5.0:
                            self.byzantine_thresh = btf
                        elif bt:
                            print(f"  {R}[!] Must be 1.0–5.0.{RST}")
                    except ValueError:
                        pass
                    print(f"  {G}[✓] Hyperparameters updated. Re-run swarm to apply.{RST}")
                except (KeyboardInterrupt, EOFError):
                    pass
                input(f"\n  Press ENTER to continue …")
            elif choice == 'X':
                new_t = input("  New ticker (e.g. TCS.NS, AAPL, MSFT): ").strip().upper()
                if new_t:
                    self.ticker        = new_t
                    self._data_loaded  = False
                    self._last_result  = None
                    print(f"  {G}[✓] Ticker set to {self.ticker}. Press F to fetch data.{RST}")
                input(f"\n  Press ENTER to continue …")
def run_federated_swarm(ticker: str) -> None:
    header("MODULE 58 — FEDERATED SWARM AI")
    swarm = FederatedSwarmAI(ticker=ticker)
    swarm.interactive_menu()
import traceback
from typing import Optional, Tuple, List, Dict
warnings.filterwarnings("ignore", category=UserWarning)
class _C:
    B    = '\033[1m'              
    DIM  = '\033[2m'             
    RST  = '\033[0m'               
    RESET = '\033[0m'                                
    BOLD  = '\033[1m'                                
    BLUE_BG = '\033[44m\033[97m'                                 
    BBLU    = '\033[44m\033[97m'                           
    YELLOW  = '\033[43m\033[30m'                                   
    RED  = '\033[91m'
    GRN  = '\033[92m'
    GREEN = '\033[92m'             
    YLW  = '\033[93m'
    CYN  = '\033[96m'
    CYAN = '\033[96m'              
    MGN  = '\033[95m'
    WHT  = '\033[97m'
    @staticmethod
    def bold(s: str) -> str:  return f"{_C.BOLD}{s}{_C.RESET}"
    @staticmethod
    def dim(s: str) -> str:   return f"{_C.DIM}{s}{_C.RESET}"
    @staticmethod
    def green(s: str) -> str: return f"{_C.GREEN}{s}{_C.RESET}"
    @staticmethod
    def red(s: str) -> str:   return f"{_C.RED}{s}{_C.RESET}"
    @staticmethod
    def cyan(s: str) -> str:  return f"{_C.CYAN}{s}{_C.RESET}"
@dataclass
class NodeConfig:
    ticker:         str   = "RELIANCE.NS"
    history_period: str   = "2y"                             
    window_size:    int   = 30                                        
    val_fraction:   float = 0.15                                               
    forecast_days:  int   = 10                                             
    latent_dim:     int   = 32                                     
    ode_hidden:     int   = 64                                                 
    n_features:     int   = 5                                                  
    epochs:         int   = 150
    batch_size:     int   = 32
    lr:             float = 5e-4                            
    lr_eta_min:     float = 1e-5                          
    grad_clip:      float = 1.0                                  
    patience:       int   = 20                                         
    rtol:           float = 1e-3                                    
    atol:           float = 1e-4                                    
    ode_method:     str   = "dopri5"                                              
    seed:           int   = 42                        
    device:         str   = "auto"                            
class _DependencyManager:
    REQUIRED = {
        "torch":        "torch",
        "torchdiffeq":  "torchdiffeq",
        "yfinance":     "yfinance",
        "pandas":       "pandas",
        "numpy":        "numpy",
        "sklearn":      "scikit-learn",
        "matplotlib":   "matplotlib",
    }
    @classmethod
    def ensure(cls) -> bool:
        missing: List[str] = []
        for import_name, pip_name in cls.REQUIRED.items():
            try:
                __import__(import_name)
            except ImportError:
                missing.append(pip_name)
        if not missing:
            return True                                   
        print(f"  {_C.YLW}[!] Installing missing packages: {', '.join(missing)}{_C.RST}")
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install", "--quiet"] + missing,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except subprocess.CalledProcessError as e:
            print(f"  {_C.RED}[✗] pip install failed: {e}{_C.RST}")
            return False
        for import_name in cls.REQUIRED:
            try:
                __import__(import_name)
            except ImportError:
                print(f"  {_C.RED}[✗] Still cannot import '{import_name}' after install.{_C.RST}")
                return False
        print(f"  {_C.GRN}[✓] All dependencies satisfied.{_C.RST}")
        return True
class _FeatureEngineer:
    def __init__(self):
        self.close_scaler  = None                                              
        self.feature_means = None                                            
        self.feature_stds  = None
    def fit_transform(self, hist) -> Tuple["np.ndarray", "np.ndarray"]:
        from sklearn.preprocessing import MinMaxScaler
        df = hist[['Open', 'High', 'Low', 'Close', 'Volume']].copy()
        df.dropna(inplace=True)
        df['log_ret'] = np.log(df['Close'] / df['Close'].shift(1))
        df['vol_5']   = df['log_ret'].rolling(5).std()
        df['vol_20']  = df['log_ret'].rolling(20).std()
        vol_mean = df['Volume'].mean()
        vol_std  = df['Volume'].std() + 1e-8                             
        df['vol_z'] = (df['Volume'] - vol_mean) / vol_std
        self.close_scaler = MinMaxScaler(feature_range=(0, 1))
        df['close_scaled'] = self.close_scaler.fit_transform(
            df[['Close']].values
        )
        df.dropna(inplace=True)
        feature_cols = ['log_ret', 'vol_5', 'vol_20', 'vol_z', 'close_scaled']
        X = df[feature_cols].values.astype(np.float32)
        self.feature_means = X.mean(axis=0)
        self.feature_stds  = X.std(axis=0) + 1e-8
        X_norm = (X - self.feature_means) / self.feature_stds
        X_norm[:, -1] = df['close_scaled'].values
        close_scaled = df['close_scaled'].values.astype(np.float32)
        return X_norm, close_scaled
    def inverse_close(self, scaled_values: "np.ndarray") -> "np.ndarray":
        return self.close_scaler.inverse_transform(
            scaled_values.reshape(-1, 1)
        ).flatten()
def _make_windows(
    X: "np.ndarray",
    close: "np.ndarray",
    window: int
) -> Tuple["torch.Tensor", "torch.Tensor"]:
    import torch
    inputs, targets = [], []
    for t in range(len(X) - window):
        inputs.append(X[t : t + window])                        
        targets.append(close[t + window])                               
    inputs_arr  = np.stack(inputs,  axis=0)              
    targets_arr = np.array(targets, dtype=np.float32)
    return (
        torch.tensor(inputs_arr,  dtype=torch.float32),
        torch.tensor(targets_arr, dtype=torch.float32),
    )
class _ODEFunc:
    @staticmethod
    def build(latent_dim: int, ode_hidden: int) -> "nn.Module":
        import torch
        import torch.nn as nn
        _latent = latent_dim
        _hidden = ode_hidden
        class _Func(nn.Module):
            def __init__(self):
                super().__init__()
                self.net = nn.Sequential(
                    nn.Linear(_latent + 1, _hidden),
                    nn.Tanh(),
                    nn.Linear(_hidden, _hidden),
                    nn.Tanh(),
                    nn.Linear(_hidden, _latent),
                )
                self.alpha = nn.Parameter(torch.full((1,), 0.01))
                self._nfe = 0                                                 
            def forward(self, t, h):
                t_vec = t.expand(h.shape[0], 1)
                self._nfe += 1
                inp = torch.cat([h, t_vec], dim=-1)
                return self.net(inp) + self.alpha * h
        return _Func()
class _Encoder:
    @staticmethod
    def build(n_features: int, latent_dim: int) -> "nn.Module":
        import torch.nn as nn
        class _Enc(nn.Module):
            def __init__(self, n_feat, d_lat):
                super().__init__()
                self.gru = nn.GRU(
                    input_size=n_feat,
                    hidden_size=d_lat,
                    num_layers=2,
                    batch_first=True,
                    bidirectional=True,
                    dropout=0.1,
                )
                self.proj = nn.Sequential(
                    nn.Linear(d_lat * 2, d_lat),
                    nn.LayerNorm(d_lat),                        
                    nn.Tanh(),
                )
            def forward(self, x):
                _, h_n = self.gru(x)
                h_fwd = h_n[-2]                        
                h_bwd = h_n[-1]                         
                h0 = self.proj(
                    __import__('torch').cat([h_fwd, h_bwd], dim=-1)
                )
                return h0                        
        return _Enc(n_features, latent_dim)
class _Decoder:
    @staticmethod
    def build(latent_dim: int) -> "nn.Module":
        import torch.nn as nn
        return nn.Sequential(
            nn.Linear(latent_dim, latent_dim // 2),
            nn.ReLU(),
            nn.Dropout(0.1),
            nn.Linear(latent_dim // 2, 1),
            nn.Sigmoid(),                                                 
        )
class _NeuralODEModel:
    @staticmethod
    def build(cfg: "NodeConfig") -> "nn.Module":
        import torch
        import torch.nn as nn
        from torchdiffeq import odeint_adjoint as odeint                        
        encoder  = _Encoder.build(cfg.n_features, cfg.latent_dim)
        ode_func = _ODEFunc.build(cfg.latent_dim, cfg.ode_hidden)
        decoder  = _Decoder.build(cfg.latent_dim)
        class _FullModel(nn.Module):
            def __init__(self):
                super().__init__()
                self.encoder  = encoder
                self.ode_func = ode_func
                self.decoder  = decoder
                self.register_buffer('t_span', torch.tensor([0.0, 1.0]))
            def forward(self, x):
                h0 = self.encoder(x)                                
                h_traj = odeint(
                    self.ode_func,
                    h0,
                    self.t_span,
                    method=cfg.ode_method,
                    rtol=cfg.rtol,
                    atol=cfg.atol,
                    adjoint_params=list(self.ode_func.parameters()),
                )
                h_final = h_traj[-1]                                
                return self.decoder(h_final).squeeze(-1)             
            @property
            def nfe(self) -> int:
                return self.ode_func._nfe
            def reset_nfe(self):
                self.ode_func._nfe = 0
        return _FullModel()
def _huber_loss(pred: "torch.Tensor", target: "torch.Tensor",
                delta: float = 0.05) -> "torch.Tensor":
    import torch.nn.functional as F
    return F.huber_loss(pred, target, delta=delta)
def _eval_metrics(pred: "np.ndarray", true: "np.ndarray") -> Dict[str, float]:
    mae  = float(np.mean(np.abs(pred - true)))
    mape = float(np.mean(np.abs((pred - true) / (true + 1e-8))) * 100)
    if len(pred) > 1:
        pred_dir = np.sign(np.diff(pred))
        true_dir = np.sign(np.diff(true))
        dir_acc  = float(np.mean(pred_dir == true_dir) * 100)
    else:
        dir_acc = float('nan')
    return {"MAE": mae, "MAPE_%": mape, "Dir_Acc_%": dir_acc}
class NeuralODEQuant:
    def __init__(self, ticker: Optional[str] = None,
                 cfg: Optional[NodeConfig] = None):
        self.cfg = cfg or NodeConfig()
        if ticker:
            self.cfg.ticker = ticker
        self._feature_eng: Optional[_FeatureEngineer] = None
        self._model       = None                     
        self._device      = None                        
        self._train_loss_hist: List[float] = []
        self._val_loss_hist:   List[float] = []
        self._best_val_loss    = float('inf')
        self._is_trained       = False
    def _resolve_device(self):
        import torch
        if self.cfg.device == "auto":
            self._device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        else:
            self._device = torch.device(self.cfg.device)
        print(f"  {_C.DIM}[device] Running on: {self._device}{_C.RST}")
    def fetch_and_prepare_data(
        self
    ) -> Tuple[
        "torch.Tensor", "torch.Tensor",                           
        "torch.Tensor", "torch.Tensor",                           
        "np.ndarray",                                                
    ]:
        print(f"  {_C.CYN}[data] Fetching {self.cfg.history_period} of "
              f"{self.cfg.ticker} history...{_C.RST}")
        ticker_obj = yf.Ticker(self.cfg.ticker)
        hist = ticker_obj.history(period=self.cfg.history_period)
        if hist.empty:
            raise ValueError(
                f"No data returned for ticker '{self.cfg.ticker}'. "
                "Check the symbol and try again."
            )
        n_rows = len(hist)
        print(f"  {_C.DIM}[data] {n_rows} trading days loaded.{_C.RST}")
        if n_rows < self.cfg.window_size + 30:
            raise ValueError(
                f"Insufficient history: {n_rows} rows < "
                f"window_size ({self.cfg.window_size}) + 30 buffer. "
                "Use a longer history_period."
            )
        self._feature_eng = _FeatureEngineer()
        X_norm, close_scaled = self._feature_eng.fit_transform(hist)
        self.cfg.n_features = X_norm.shape[1]
        X_wins, y_wins = _make_windows(X_norm, close_scaled, self.cfg.window_size)
        n_total = len(X_wins)
        n_val   = max(1, int(n_total * self.cfg.val_fraction))
        n_train = n_total - n_val
        X_tr, y_tr   = X_wins[:n_train], y_wins[:n_train]
        X_val, y_val = X_wins[n_train:],  y_wins[n_train:]
        print(f"  {_C.DIM}[data] Windows — train: {n_train}, val: {n_val}{_C.RST}")
        return X_tr, y_tr, X_val, y_val, close_scaled
    @staticmethod
    def _batch_iter(X: "torch.Tensor", y: "torch.Tensor",
                    batch_size: int, shuffle: bool = True):
        import torch
        n = len(X)
        idx = torch.randperm(n) if shuffle else torch.arange(n)
        for start in range(0, n, batch_size):
            batch_idx = idx[start : start + batch_size]
            yield X[batch_idx], y[batch_idx]
    def train_node(
        self,
        X_tr: "torch.Tensor", y_tr: "torch.Tensor",
        X_val: "torch.Tensor", y_val: "torch.Tensor",
    ) -> None:
        import torch
        import torch.nn as nn
        torch.manual_seed(self.cfg.seed)
        self._resolve_device()
        model = _NeuralODEModel.build(self.cfg).to(self._device)
        self._model = model
        n_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
        print(f"  {_C.DIM}[model] Trainable parameters: {n_params:,}{_C.RST}")
        optimiser = torch.optim.AdamW(
            model.parameters(),
            lr=self.cfg.lr,
            weight_decay=1e-4,                            
        )
        scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(
            optimiser,
            T_max=self.cfg.epochs,
            eta_min=self.cfg.lr_eta_min,
        )
        X_tr_d  = X_tr.to(self._device)
        y_tr_d  = y_tr.to(self._device)
        X_val_d = X_val.to(self._device)
        y_val_d = y_val.to(self._device)
        best_state  = None
        no_improve  = 0
        print(
            f"\n  {_C.GRN}[train] Adjoint Neural ODE — "
            f"{self.cfg.epochs} epochs, "
            f"batch={self.cfg.batch_size}, "
            f"solver={self.cfg.ode_method}{_C.RST}"
        )
        print(f"  {'─'*62}")
        print(f"  {'Epoch':>6}  {'Train Loss':>12}  {'Val Loss':>10}  "
              f"{'LR':>9}  {'NFE':>5}")
        print(f"  {'─'*62}")
        t0 = time.time()
        for epoch in range(1, self.cfg.epochs + 1):
            model.train()
            model.reset_nfe()
            epoch_loss = 0.0
            n_batches  = 0
            for xb, yb in self._batch_iter(
                X_tr_d, y_tr_d, self.cfg.batch_size
            ):
                optimiser.zero_grad(set_to_none=True)                           
                pred = model(xb)
                loss = _huber_loss(pred, yb)
                loss.backward()
                nn.utils.clip_grad_norm_(model.parameters(), self.cfg.grad_clip)
                optimiser.step()
                epoch_loss += loss.item()
                n_batches  += 1
            train_loss = epoch_loss / max(n_batches, 1)
            self._train_loss_hist.append(train_loss)
            model.eval()
            with torch.no_grad():
                val_pred = model(X_val_d)
                val_loss = _huber_loss(val_pred, y_val_d).item()
            self._val_loss_hist.append(val_loss)
            scheduler.step()
            if epoch % 25 == 0 or epoch == 1:
                cur_lr = scheduler.get_last_lr()[0]
                print(
                    f"  {epoch:>6}  {train_loss:>12.6f}  "
                    f"{val_loss:>10.6f}  {cur_lr:>9.2e}  "
                    f"{model.nfe:>5}"
                )
                model.reset_nfe()
            if val_loss < self._best_val_loss - 1e-6:
                self._best_val_loss = val_loss
                best_state = {k: v.clone() for k, v in model.state_dict().items()}
                no_improve = 0
            else:
                no_improve += 1
                if no_improve >= self.cfg.patience:
                    print(
                        f"\n  {_C.YLW}[train] Early stop at epoch {epoch} "
                        f"(no val improvement for {self.cfg.patience} epochs){_C.RST}"
                    )
                    break
        elapsed = time.time() - t0
        print(f"  {'─'*62}")
        print(f"  {_C.DIM}[train] Completed in {elapsed:.1f}s | "
              f"Best val loss: {self._best_val_loss:.6f}{_C.RST}")
        if best_state is not None:
            model.load_state_dict(best_state)
        self._is_trained = True
    def evaluate(
        self,
        X_val: "torch.Tensor",
        y_val: "torch.Tensor",
    ) -> Dict[str, float]:
        import torch
        self._model.eval()
        with torch.no_grad():
            pred_scaled = self._model(X_val.to(self._device)).cpu().numpy()
        true_scaled = y_val.numpy()
        pred_prices = self._feature_eng.inverse_close(pred_scaled)
        true_prices = self._feature_eng.inverse_close(true_scaled)
        return _eval_metrics(pred_prices, true_prices)
    def forecast(
        self,
        close_scaled_full: "np.ndarray",
        X_full_norm: "np.ndarray",
        n_mc: int = 50,
    ) -> Tuple["np.ndarray", "np.ndarray", "np.ndarray"]:
        import torch
        model = self._model
        W = self.cfg.window_size
        F = self.cfg.n_features
        dev = self._device
        seed_window = torch.tensor(
            X_full_norm[-W:], dtype=torch.float32
        ).unsqueeze(0).to(dev)              
        all_trajectories = []
        for mc_run in range(n_mc):
            model.train()
            window = seed_window.clone()
            trajectory = []
            with torch.no_grad():
                for _ in range(self.cfg.forecast_days):
                    pred_scaled = model(window).item()
                    trajectory.append(pred_scaled)
                    new_row = torch.zeros(1, 1, F, device=dev)
                    new_row[0, 0, -1] = pred_scaled                         
                    window = torch.cat([window[:, 1:, :], new_row], dim=1)
            trajectory_arr = np.array(trajectory, dtype=np.float32)
            all_trajectories.append(
                self._feature_eng.inverse_close(trajectory_arr)
            )
        trajectories = np.stack(all_trajectories, axis=0)                         
        mean_prices  = trajectories.mean(axis=0)
        std_prices   = trajectories.std(axis=0)
        lower_prices = mean_prices - std_prices
        upper_prices = mean_prices + std_prices
        return mean_prices, lower_prices, upper_prices
    def run_pipeline(self) -> None:
        try:
            X_tr, y_tr, X_val, y_val, close_scaled = self.fetch_and_prepare_data()
            hist = yf.Ticker(self.cfg.ticker).history(period=self.cfg.history_period)
            X_full_norm, _ = self._feature_eng.fit_transform(hist)
            self.train_node(X_tr, y_tr, X_val, y_val)
            metrics = self.evaluate(X_val, y_val)
            print(f"\n  {_C.B}[eval] Validation Metrics{_C.RST}")
            for k, v in metrics.items():
                symbol = "₹" if k == "MAE" else "%"
                print(f"    {k:<12}:  {v:>8.3f} {symbol}")
            mean_f, lo_f, hi_f = self.forecast(close_scaled, X_full_norm)
            print(f"\n  {_C.B}═══ NEURAL ODE FORECAST — {self.cfg.ticker} ═══{_C.RST}")
            print(f"  {'Day':<8}  {'Mean (₹)':>12}  {'Lower (₹)':>12}  {'Upper (₹)':>12}")
            print(f"  {'─'*50}")
            for i, (m, lo, hi) in enumerate(zip(mean_f, lo_f, hi_f), 1):
                print(f"  T+{i:02}      {m:>12,.2f}  {lo:>12,.2f}  {hi:>12,.2f}")
            self._plot(mean_f, lo_f, hi_f)
        except Exception as exc:
            print(f"\n  {_C.RED}[✗] Pipeline error: {exc}{_C.RST}")
            traceback.print_exc()
    def _plot(
        self,
        mean_f: "np.ndarray",
        lo_f:   "np.ndarray",
        hi_f:   "np.ndarray",
    ) -> None:
        fig, axes = plt.subplots(2, 1, figsize=(11, 7))
        fig.patch.set_facecolor('#0f0f1a')
        for ax in axes:
            ax.set_facecolor('#161625')
            ax.tick_params(colors='#aaaacc')
            for spine in ax.spines.values():
                spine.set_edgecolor('#333355')
        ax = axes[0]
        days = np.arange(1, len(mean_f) + 1)
        ax.fill_between(days, lo_f, hi_f, alpha=0.25, color='#bc8cff',
                        label='±1σ MC-Dropout band')
        ax.plot(days, mean_f, color='#bc8cff', marker='o', linewidth=2,
                label='Mean Forecast')
        for d, m in zip(days, mean_f):
            ax.annotate(f"₹{m:,.0f}", (d, m),
                        textcoords="offset points", xytext=(0, 8),
                        fontsize=7, color='#ddccff', ha='center')
        ax.set_title(f"{self.cfg.ticker}  |  Neural ODE Trajectory Forecast",
                     color='white', fontsize=12, pad=10)
        ax.set_xlabel("Day Ahead", color='#aaaacc')
        ax.set_ylabel("Price (₹)", color='#aaaacc')
        ax.legend(facecolor='#1e1e30', labelcolor='white', fontsize=8)
        ax.grid(True, linestyle='--', linewidth=0.4, color='#333355')
        ax2 = axes[1]
        ax2.plot(self._train_loss_hist, color='#5cc8ff', linewidth=1.2,
                 label='Train Huber Loss')
        ax2.plot(self._val_loss_hist,   color='#ff7f7f', linewidth=1.2,
                 label='Val Huber Loss',   linestyle='--')
        ax2.set_title("Training Dynamics", color='white', fontsize=11, pad=8)
        ax2.set_xlabel("Epoch", color='#aaaacc')
        ax2.set_ylabel("Huber Loss", color='#aaaacc')
        ax2.legend(facecolor='#1e1e30', labelcolor='white', fontsize=8)
        ax2.grid(True, linestyle='--', linewidth=0.4, color='#333355')
        plt.tight_layout(pad=2.5)
        plt.show()
    def interactive_menu(self) -> None:
        if not _DependencyManager.ensure():
            return
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            trained_tag = (
                f"  {_C.GRN}[trained  best_val={self._best_val_loss:.5f}]{_C.RST}"
                if self._is_trained else
                f"  {_C.YLW}[not yet trained]{_C.RST}"
            )
            print(f"\n  {_C.BBLU} NEURAL DIFFERENTIAL EQUATIONS (CONTINUOUS-TIME AI) "
                  f"{'':24} {_C.RST}")
            print("  " + "═" * 76)
            print(f"  {_C.B}Active Ticker:{_C.RST}  {_C.CYN}{self.cfg.ticker}{_C.RST}"
                  f"   {trained_tag}")
            print(f"  {_C.B}Window / Horizon:{_C.RST}  "
                  f"{self.cfg.window_size}d look-back  →  "
                  f"{self.cfg.forecast_days}d forecast")
            print(f"  {_C.B}Epochs / Patience:{_C.RST}  "
                  f"{self.cfg.epochs}  /  {self.cfg.patience}")
            print("  " + "═" * 76)
            print(f"  {_C.B}N.{_C.RST} {_C.GRN}Train Neural ODE & Forecast{_C.RST}")
            print(f"  {_C.B}T.{_C.RST} Change Ticker Symbol")
            print(f"  {_C.B}C.{_C.RST} Configure Hyper-parameters")
            print(f"  {_C.B}0.{_C.RST} Return to Main Menu")
            choice = input(f"\n  Select: ").strip().upper()
            if choice == '0':
                break
            elif choice == 'N':
                self.run_pipeline()
                input(f"\n  Press ENTER to return...")
            elif choice == 'T':
                sym = input("  Enter ticker symbol: ").strip().upper()
                if sym:
                    self.cfg.ticker   = sym
                    self._is_trained  = False                                          
                    self._best_val_loss = float('inf')
                    self._train_loss_hist.clear()
                    self._val_loss_hist.clear()
            elif choice == 'C':
                self._configure_interactive()
    def _configure_interactive(self) -> None:
        print(f"\n  {_C.B}Current Configuration:{_C.RST}")
        fields = [
            ('epochs',       'Epochs'),
            ('window_size',  'Look-back window (days)'),
            ('forecast_days','Forecast horizon (days)'),
            ('latent_dim',   'Latent dim'),
            ('ode_hidden',   'ODE hidden units'),
            ('patience',     'Early-stop patience'),
            ('lr',           'Learning rate'),
        ]
        for attr, label in fields:
            print(f"    {label:<30}: {getattr(self.cfg, attr)}")
        print(f"\n  {_C.DIM}(Enter blank to keep current value){_C.RST}")
        for attr, label in fields:
            raw = input(f"  {label}: ").strip()
            if raw:
                try:
                    current = getattr(self.cfg, attr)
                    setattr(self.cfg, attr, type(current)(raw))
                except ValueError:
                    print(f"  {_C.YLW}[!] Invalid value for {attr}, skipped.{_C.RST}")
        self._is_trained = False                                             
        print(f"  {_C.GRN}[✓] Configuration updated.{_C.RST}")
def run_neural_ode_quant(ticker: str) -> None:
    header("MODULE 59 — NEURAL ODE QUANT")
    engine = NeuralODEQuant(ticker=ticker)
    engine.interactive_menu()
import itertools
from typing import Dict, List, Optional, Tuple, Set
warnings.filterwarnings("ignore", category=FutureWarning)
warnings.filterwarnings("ignore", category=RuntimeWarning)
class _CG:
    BOLD    = '\033[1m'
    DIM     = '\033[2m'
    CYAN    = '\033[96m'
    GREEN   = '\033[92m'
    YELLOW  = '\033[93m'
    RED     = '\033[91m'
    MAGENTA = '\033[95m'
    BLUE    = '\033[94m'
    BLUE_BG = '\033[44m\033[97m'
    RESET   = '\033[0m'
_C = _CG
@dataclass
class NodeMetrics:
    ticker:           str
    degree:           int   = 0                          
    degree_centrality:float = 0.0                            
    betweenness:      float = 0.0                                       
    eigenvector:      float = 0.0                                         
    clustering:       float = 0.0                                         
    community:        int   = 0                                
    avg_edge_weight:  float = 0.0                                          
    is_hub:           bool  = False                                   
@dataclass
class GraphReport:
    method:         str                                                                 
    n_nodes:        int   = 0
    n_edges:        int   = 0
    density:        float = 0.0                                    
    avg_weight:     float = 0.0
    threshold:      float = 0.0                                      
    n_communities:  int   = 0
    node_metrics:   Dict[str, NodeMetrics] = field(default_factory=dict)
    adjacency:      Dict[str, Dict[str, float]] = field(default_factory=dict)
    is_directed:    bool  = False                                   
    computed_at:    float = 0.0                             
@dataclass
class MarketDataGNN:
    tickers:      List[str]
    returns:      object = None                               
    corr_matrix:  object = None                               
    prices:       object = None                               
    loaded:       bool   = False
    fetch_ts:     float  = 0.0
    period:       str    = "1y"
def _check_gnn_dependencies() -> Dict[str, bool]:
    libs = {
        'numpy':      'pip install numpy',
        'pandas':     'pip install pandas',
        'yfinance':   'pip install yfinance',
        'scipy':      'pip install scipy',
        'networkx':   'pip install networkx',
        'matplotlib': 'pip install matplotlib',
    }
    status = {}
    for lib, install_cmd in libs.items():
        try:
            __import__(lib)
            status[lib] = True
        except ImportError:
            status[lib] = False
            print(f"  {_C.YELLOW}[⚠] Missing: {lib:<12}"
                  f"  →  {install_cmd}{_C.RESET}")
    return status
def _pearson_graph(
    returns,                                       
    threshold: float,                                   
) -> GraphReport:
    cols    = list(returns.columns)
    n       = len(cols)
    corr    = returns.corr().values                             
    adj: Dict[str, Dict[str, float]] = {c: {} for c in cols}
    report = GraphReport(
        method    = "pearson",
        n_nodes   = n,
        threshold = threshold,
        computed_at = time.time(),
    )
    edge_weights = []
    for i in range(n):
        for j in range(i + 1, n):
            w = float(corr[i, j])
            if not math.isfinite(w):
                continue
            if abs(w) > threshold:
                adj[cols[i]][cols[j]] = w
                adj[cols[j]][cols[i]] = w
                edge_weights.append(abs(w))
    report.adjacency  = adj
    report.n_edges    = len(edge_weights)
    report.avg_weight = float(sum(edge_weights) / len(edge_weights)) if edge_weights else 0.0
    max_edges = n * (n - 1) / 2
    report.density = report.n_edges / max_edges if max_edges > 0 else 0.0
    return report
def _partial_correlation_graph(
    returns,
    threshold: float,
) -> GraphReport:
    cols = list(returns.columns)
    n    = len(cols)
    T    = len(returns)
    if T < n:
        print(f"  {_C.YELLOW}[⚠] T={T} < N={n}: under-determined system. "
              f"Falling back to Pearson graph.{_C.RESET}")
        return _pearson_graph(returns, threshold)
    cov = returns.cov().values.astype(float)           
    lambda_ridge = 1e-4
    cov_reg = cov + lambda_ridge * np.eye(n)
    try:
        precision = np.linalg.inv(cov_reg)
    except np.linalg.LinAlgError:
        print(f"  {_C.RED}[!] Matrix inversion failed — using Pearson fallback.{_C.RESET}")
        return _pearson_graph(returns, threshold)
    diag_sqrt = np.sqrt(np.diag(precision))                 
    norm = np.outer(diag_sqrt, diag_sqrt)               
    norm = np.where(norm < 1e-12, 1e-12, norm)
    partial_corr = -precision / norm
    adj: Dict[str, Dict[str, float]] = {c: {} for c in cols}
    edge_weights = []
    for i in range(n):
        for j in range(i + 1, n):
            w = float(partial_corr[i, j])
            if not math.isfinite(w):
                continue
            if abs(w) > threshold:
                adj[cols[i]][cols[j]] = w
                adj[cols[j]][cols[i]] = w
                edge_weights.append(abs(w))
    max_edges = n * (n - 1) / 2
    return GraphReport(
        method      = "partial",
        n_nodes     = n,
        n_edges     = len(edge_weights),
        density     = len(edge_weights) / max_edges if max_edges else 0.0,
        avg_weight  = float(sum(edge_weights) / len(edge_weights)) if edge_weights else 0.0,
        threshold   = threshold,
        adjacency   = adj,
        computed_at = time.time(),
    )
def _mst_graph(returns) -> GraphReport:
    import networkx as nx
    cols = list(returns.columns)
    n    = len(cols)
    corr = returns.corr().values
    G_complete = nx.Graph()
    G_complete.add_nodes_from(cols)
    for i in range(n):
        for j in range(i + 1, n):
            rho = float(corr[i, j])
            if not math.isfinite(rho):
                rho = 0.0
            rho   = max(-1.0, min(1.0, rho))
            dist  = math.sqrt(2.0 * (1.0 - rho))                      
            G_complete.add_edge(cols[i], cols[j],
                                weight=dist,
                                corr=rho)
    mst = nx.minimum_spanning_tree(G_complete, weight='weight')
    adj: Dict[str, Dict[str, float]] = {c: {} for c in cols}
    edge_weights = []
    for u, v, data in mst.edges(data=True):
        rho = data.get('corr', 0.0)
        adj[u][v] = rho
        adj[v][u] = rho
        edge_weights.append(abs(rho))
    return GraphReport(
        method      = "mst",
        n_nodes     = n,
        n_edges     = len(edge_weights),                   
        density     = len(edge_weights) / (n * (n-1) / 2) if n > 1 else 0.0,
        avg_weight  = float(sum(edge_weights) / len(edge_weights)) if edge_weights else 0.0,
        threshold   = 0.0,                           
        adjacency   = adj,
        computed_at = time.time(),
    )
def _granger_graph(
    returns,
    max_lag: int  = 2,
    p_value: float = 0.05,
) -> GraphReport:
    from scipy.stats import f as f_dist
    cols = list(returns.columns)
    n    = len(cols)
    T    = len(returns)
    ret  = returns.values.astype(float)                    
    adj: Dict[str, Dict[str, float]] = {c: {} for c in cols}
    edge_weights = []
    max_t = T - max_lag
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            Y = ret[max_lag:, j]                           
            X_r = np.ones((max_t, 1 + max_lag))
            for k in range(1, max_lag + 1):
                X_r[:, k] = ret[max_lag - k: T - k, j]
            X_u = np.ones((max_t, 1 + 2 * max_lag))
            X_u[:, :1 + max_lag] = X_r
            for k in range(1, max_lag + 1):
                X_u[:, max_lag + k] = ret[max_lag - k: T - k, i]
            def _ols_rss(X, y):
                beta = np.linalg.lstsq(X, y, rcond=None)[0]
                resid = y - X @ beta
                return float(resid @ resid)
            rss_r = _ols_rss(X_r, Y)                                       
            rss_u = _ols_rss(X_u, Y)                     
            df1 = max_lag
            df2 = max_t - (1 + 2 * max_lag)
            if df2 <= 0 or rss_u < 1e-12:
                continue
            if rss_r < 1e-12:
                continue
            f_stat = ((rss_r - rss_u) / df1) / (rss_u / df2)
            p_val  = float(f_dist.sf(f_stat, df1, df2))               
            if p_val < p_value:
                w = 1.0 - p_val
                adj[cols[i]][cols[j]] = w
                edge_weights.append(w)
    return GraphReport(
        method      = "granger",
        n_nodes     = n,
        n_edges     = len(edge_weights),
        density     = len(edge_weights) / (n * (n-1)) if n > 1 else 0.0,
        avg_weight  = float(sum(edge_weights) / len(edge_weights)) if edge_weights else 0.0,
        threshold   = p_value,
        adjacency   = adj,
        is_directed = True,
        computed_at = time.time(),
    )
def _compute_node_metrics(report: GraphReport) -> GraphReport:
    import networkx as nx
    adj  = report.adjacency
    cols = list(adj.keys())
    n    = len(cols)
    if report.is_directed:
        G = nx.DiGraph()
    else:
        G = nx.Graph()
    G.add_nodes_from(cols)
    for u, neighbours in adj.items():
        for v, w in neighbours.items():
            G.add_edge(u, v, weight=abs(w))
    dc  = nx.degree_centrality(G)
    bc  = nx.betweenness_centrality(G, weight='weight', normalized=True)
    try:
        ec = nx.eigenvector_centrality_numpy(G, weight='weight')
    except Exception:
        ec = dc                      
    if report.is_directed:
        cc = {node: 0.0 for node in cols}
    else:
        cc = nx.clustering(G, weight='weight')
    communities: Dict[str, int] = {}
    n_communities = 1
    if not report.is_directed and G.number_of_edges() > 0:
        try:
            comm_sets = list(
                nx.community.greedy_modularity_communities(G, weight='weight')
            )
            n_communities = len(comm_sets)
            for idx, comm_set in enumerate(comm_sets):
                for node in comm_set:
                    communities[node] = idx
        except Exception:
            communities = {node: 0 for node in cols}
    else:
        communities = {node: 0 for node in cols}
    node_metrics: Dict[str, NodeMetrics] = {}
    for node in cols:
        nbr_weights = [abs(w) for w in adj[node].values()]
        avg_w = sum(nbr_weights) / len(nbr_weights) if nbr_weights else 0.0
        nm = NodeMetrics(
            ticker            = node,
            degree            = G.degree(node),
            degree_centrality = dc.get(node, 0.0),
            betweenness       = bc.get(node, 0.0),
            eigenvector       = ec.get(node, 0.0),
            clustering        = cc.get(node, 0.0),
            community         = communities.get(node, 0),
            avg_edge_weight   = avg_w,
            is_hub            = dc.get(node, 0.0) > 0.5,
        )
        node_metrics[node] = nm
    report.node_metrics  = node_metrics
    report.n_communities = n_communities
    return report
def _draw_matplotlib_graph(
    report:      GraphReport,
    layout:      str = "spring",                                                  
    save_path:   Optional[str] = None,
) -> None:
    import networkx as nx
    import matplotlib.cm as cm
    adj  = report.adjacency
    cols = list(adj.keys())
    G = nx.DiGraph() if report.is_directed else nx.Graph()
    G.add_nodes_from(cols)
    for u, neighbours in adj.items():
        for v, w in neighbours.items():
            G.add_edge(u, v, weight=abs(w), signed_weight=w)
    if G.number_of_edges() == 0:
        print(f"  {_C.YELLOW}[⚠] No edges to draw (all correlations below threshold).{_C.RESET}")
        return
    seed = 42                          
    layouts = {
        "spring":   lambda: nx.spring_layout(G, k=1.2/math.sqrt(len(cols)+1),
                                              seed=seed, weight='weight'),
        "spectral": lambda: nx.spectral_layout(G, weight='weight'),
        "circular": lambda: nx.circular_layout(G),
        "kamada":   lambda: nx.kamada_kawai_layout(G, weight='weight'),
    }
    pos_fn = layouts.get(layout, layouts["spring"])
    pos    = pos_fn()
    nm      = report.node_metrics
    n_comms = max((m.community for m in nm.values()), default=0) + 1
    cmap    = cm.get_cmap('tab10', max(n_comms, 1))
    node_sizes  = []
    node_colours= []
    node_borders= []
    for node in G.nodes():
        metrics = nm.get(node, NodeMetrics(ticker=node))
        size = 400 + metrics.eigenvector * 2100
        node_sizes.append(size)
        node_colours.append(cmap(metrics.community % n_comms))
        node_borders.append('gold' if metrics.is_hub else 'white')
    edge_widths  = []
    edge_colours = []
    for u, v, data in G.edges(data=True):
        sw = data.get('signed_weight', data.get('weight', 0))
        edge_widths.append(max(0.5, min(5.0, abs(sw) * 6)))
        if sw >= 0:
            edge_colours.append((0.1, 0.75, 0.1, 0.55))              
        else:
            edge_colours.append((0.85, 0.1, 0.1, 0.55))            
    fig, ax = plt.subplots(figsize=(12, 9))
    fig.patch.set_facecolor('#1a1a2e')
    ax.set_facecolor('#1a1a2e')
    nx.draw_networkx_edges(
        G, pos,
        width       = edge_widths,
        edge_color  = edge_colours,
        arrows      = report.is_directed,
        arrowsize   = 15,
        ax          = ax,
    )
    for i, node in enumerate(G.nodes()):
        nx.draw_networkx_nodes(
            G, pos,
            nodelist    = [node],
            node_size   = [node_sizes[i]],
            node_color  = [node_colours[i]],
            edgecolors  = [node_borders[i]],
            linewidths  = 2.5,
            ax          = ax,
        )
    labels = {n: re.sub(r'\.(NS|BO|BSE)$', '', n, flags=re.IGNORECASE)
              for n in G.nodes()}
    nx.draw_networkx_labels(
        G, pos, labels,
        font_size   = 8,
        font_color  = 'white',
        font_weight = 'bold',
        ax          = ax,
    )
    if report.method == "mst":
        edge_labels = {
            (u, v): f"{data.get('signed_weight', data.get('weight',0)):.2f}"
            for u, v, data in G.edges(data=True)
        }
        nx.draw_networkx_edge_labels(
            G, pos, edge_labels,
            font_size   = 7,
            font_color  = '#aaaaaa',
            ax          = ax,
        )
    method_labels = {
        "pearson": "Pearson Correlation",
        "partial": "Partial Correlation (GGM)",
        "mst":     "Minimum Spanning Tree (Mantegna)",
        "granger": "Granger Causality (directed)",
    }
    title = (
        f"Asset Dependency Graph — {method_labels.get(report.method, report.method)}\n"
        f"N={report.n_nodes} assets  |  {report.n_edges} edges  |  "
        f"density={report.density:.2%}  |  "
        f"{report.n_communities} communities"
    )
    ax.set_title(title, color='white', fontsize=11, pad=12)
    if n_comms > 1 and not report.is_directed:
        handles = [
            matplotlib.patches.Patch(
                facecolor=cmap(c % n_comms),
                label=f"Community {c+1}"
            )
            for c in range(n_comms)
        ]
        ax.legend(
            handles=handles, loc='upper left',
            facecolor='#2a2a4e', labelcolor='white',
            fontsize=9, framealpha=0.8,
        )
    if report.threshold > 0:
        ax.annotate(
            f"τ = {report.threshold:.2f}",
            xy=(0.01, 0.01), xycoords='axes fraction',
            color='#aaaaaa', fontsize=8,
        )
    ax.axis('off')
    plt.tight_layout()
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches='tight',
                    facecolor=fig.get_facecolor())
        print(f"  {_C.GREEN}[✓] Graph saved to: {save_path}{_C.RESET}")
    else:
        plt.show()
    plt.close(fig)                                                              
def _draw_ascii_graph(report: GraphReport) -> None:
    adj   = report.adjacency
    nodes = list(adj.keys())
    n     = len(nodes)
    nm    = report.node_metrics
    def _short(t: str) -> str:
        return re.sub(r'\.(NS|BO|BSE)$', '', t, flags=re.IGNORECASE)[:8]
    short = [_short(t) for t in nodes]
    pad_w = max(len(s) for s in short) + 1
    print(f"\n  {_C.BOLD}── CORRELATION ADJACENCY HEATMAP ──{_C.RESET}")
    header_row = " " * (pad_w + 5)
    for s in short:
        header_row += f"{s:>{pad_w}}"
    print(f"  {_C.DIM}{header_row}{_C.RESET}")
    for i, node_i in enumerate(nodes):
        row = f"  {_C.DIM}{short[i]:>{pad_w}}{_C.RESET}  "
        for j, node_j in enumerate(nodes):
            if i == j:
                row += f"{_C.DIM}{'  ·  ':>{pad_w}}{_C.RESET}"
                continue
            w = adj[node_i].get(node_j, None)
            if w is None:
                row += f"{_C.DIM}{'':>{pad_w}}{_C.RESET}"
            else:
                cell = f"{w:>+{pad_w-1}.2f} "
                if w > 0.6:
                    row += f"{_C.GREEN}{cell}{_C.RESET}"
                elif w > 0.3:
                    row += f"{_C.CYAN}{cell}{_C.RESET}"
                elif w > 0:
                    row += f"{_C.DIM}{cell}{_C.RESET}"
                elif w > -0.3:
                    row += f"{_C.YELLOW}{cell}{_C.RESET}"
                else:
                    row += f"{_C.RED}{cell}{_C.RESET}"
        print(row)
    print(f"\n  {_C.BOLD}── NODE CENTRALITY METRICS ──{_C.RESET}")
    hdr = (f"  {'Ticker':<16} {'Deg':>4} {'DC':>6} {'BC':>6} "
           f"{'EC':>6} {'CC':>6} {'Comm':>5} {'AvgW':>6}")
    print(f"  {_C.DIM}{hdr}{_C.RESET}")
    print(f"  {'─'*70}")
    sorted_nodes = sorted(
        nm.values(),
        key=lambda m: m.eigenvector,
        reverse=True,
    )
    comm_colours = [_C.GREEN, _C.CYAN, _C.YELLOW, _C.MAGENTA, _C.BLUE]
    for m in sorted_nodes:
        hub_marker = f" {_C.YELLOW}★{_C.RESET}" if m.is_hub else "  "
        comm_col   = comm_colours[m.community % len(comm_colours)]
        print(
            f"  {_C.BOLD}{m.ticker:<16}{_C.RESET}"
            f"{hub_marker}"
            f"{m.degree:>3}  "
            f"{m.degree_centrality:>5.3f}  "
            f"{m.betweenness:>5.3f}  "
            f"{m.eigenvector:>5.3f}  "
            f"{m.clustering:>5.3f}  "
            f"{comm_col}C{m.community+1:>2}{_C.RESET}  "
            f"{m.avg_edge_weight:>5.3f}"
        )
    print(f"\n  {'─'*70}")
    print(f"  {_C.BOLD}Method:{_C.RESET}       {report.method.upper()}")
    print(f"  {_C.BOLD}Nodes:{_C.RESET}        {report.n_nodes}")
    print(f"  {_C.BOLD}Edges:{_C.RESET}        {report.n_edges}")
    print(f"  {_C.BOLD}Density:{_C.RESET}      {report.density:.3f}  "
          f"{_C.DIM}({report.density:.1%} of possible edges active){_C.RESET}")
    print(f"  {_C.BOLD}Avg |weight|:{_C.RESET} {report.avg_weight:.3f}")
    print(f"  {_C.BOLD}Communities:{_C.RESET}  {report.n_communities}  "
          f"{_C.DIM}(Louvain greedy modularity){_C.RESET}")
    if report.is_directed:
        print(f"  {_C.DIM}★ Directed graph (Granger) — betweenness / "
              f"clustering not applicable{_C.RESET}")
class AssetDependencyGraph:
    _ANNUALISATION  = 252
    _CACHE_TTL      = 1800                          
    def __init__(
        self,
        tickers:    Optional[List[str]] = None,
        period:     str   = "1y",
        threshold:  float = 0.4,
    ):
        default_tickers = [
            "RELIANCE.NS", "TCS.NS", "INFY.NS",
            "HDFCBANK.NS", "ICICIBANK.NS",
        ]
        self.tickers   = self._normalise_tickers(tickers or default_tickers)
        self.period    = period
        self.threshold = threshold
        self._market   = MarketDataGNN(tickers=self.tickers, period=period)
        self._last_report: Optional[GraphReport] = None
    @staticmethod
    def _normalise_tickers(raw: List[str]) -> List[str]:
        result = []
        for t in raw:
            t = t.strip().upper()
            if t:
                result.append(t if '.' in t else t + '.NS')
        return result
    def _is_cache_stale(self) -> bool:
        if not self._market.loaded:
            return True
        return (time.time() - self._market.fetch_ts) > self._CACHE_TTL
    def _fetch_and_cache(self, force: bool = False) -> bool:
        if self._market.loaded and not force and not self._is_cache_stale():
            return True
        print(f"  {_C.CYAN}Downloading {self.period} of data for "
              f"{len(self.tickers)} assets …{_C.RESET}")
        try:
            raw = yf.download(
                self.tickers, period=self.period,
                interval='1d', progress=False, auto_adjust=True,
            )
        except Exception as exc:
            print(f"  {_C.RED}[!] Download failed: {exc}{_C.RESET}")
            return False
        if raw.empty:
            print(f"  {_C.RED}[!] Empty response. Check tickers / connection.{_C.RESET}")
            return False
        prices = raw['Close'] if isinstance(raw.columns, pd.MultiIndex) else raw
        returns = prices.pct_change().dropna()
        T, N = returns.shape
        print(f"  {_C.GREEN}[✓] {T} trading days × {N} assets loaded.{_C.RESET}")
        if T < N:
            print(f"  {_C.YELLOW}[⚠] T={T} < N={N}: partial correlation will "
                  f"fall back to Pearson.{_C.RESET}")
        if T < 20:
            print(f"  {_C.RED}[!] Fewer than 20 rows — Granger results unreliable.{_C.RESET}")
        self._market = MarketDataGNN(
            tickers     = self.tickers,
            returns     = returns,
            corr_matrix = returns.corr(),
            prices      = prices,
            loaded      = True,
            fetch_ts    = time.time(),
            period      = self.period,
        )
        return True
    def _build_and_analyse(
        self,
        method:    str,
        threshold: Optional[float] = None,
        max_lag:   int   = 2,
        p_value:   float = 0.05,
    ) -> Optional[GraphReport]:
        if not self._market.loaded:
            print(f"  {_C.RED}[!] No data loaded. Fetch first.{_C.RESET}")
            return None
        τ = threshold if threshold is not None else self.threshold
        returns = self._market.returns
        print(f"  {_C.MAGENTA}Building [{method.upper()}] graph …{_C.RESET}")
        t0 = time.perf_counter()
        if method == "pearson":
            report = _pearson_graph(returns, τ)
        elif method == "partial":
            report = _partial_correlation_graph(returns, τ)
        elif method == "mst":
            report = _mst_graph(returns)
        elif method == "granger":
            n = len(self.tickers)
            n_tests = n * (n - 1)
            print(f"  {_C.DIM}Running {n_tests} Granger F-tests "
                  f"(lag={max_lag}, p<{p_value}) …{_C.RESET}")
            report = _granger_graph(returns, max_lag=max_lag, p_value=p_value)
        else:
            print(f"  {_C.RED}[!] Unknown method: {method}{_C.RESET}")
            return None
        elapsed = time.perf_counter() - t0
        print(f"  {_C.GREEN}[✓] Graph built in {elapsed*1000:.1f} ms — "
              f"{report.n_edges} edges found.{_C.RESET}")
        if report.n_edges == 0:
            print(f"  {_C.YELLOW}[⚠] No edges at τ={τ:.2f}. "
                  f"Try lowering the threshold.{_C.RESET}")
            return report
        print(f"  {_C.DIM}Computing centrality metrics …{_C.RESET}")
        report = _compute_node_metrics(report)
        self._last_report = report
        return report
    def interactive_menu(self) -> None:
        dep_status = _check_gnn_dependencies()
        core_ok = all(dep_status.get(lib, False)
                      for lib in ['numpy', 'pandas', 'yfinance', 'networkx', 'scipy'])
        if not core_ok:
            print(f"\n  {_C.RED}[!] Core dependencies missing. "
                  f"Install the listed packages and retry.{_C.RESET}")
            input(f"\n  Press ENTER to return …")
            return
        has_plt = dep_status.get('matplotlib', False)
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            cache_s = (
                f"{_C.GREEN}[data cached]{_C.RESET}"
                if self._market.loaded and not self._is_cache_stale()
                else f"{_C.YELLOW}[no data]{_C.RESET}"
            )
            print(f"\n  {_C.BLUE_BG} MODULE 60 — GRAPH NEURAL NETWORK: ASSET DEPENDENCY MAPPING "
                  f"{'':>10}{_C.RESET}")
            print(f"  {'═'*76}")
            print(f"  {_C.BOLD}Assets:{_C.RESET} {', '.join(self.tickers)}")
            print(f"  {_C.BOLD}Threshold:{_C.RESET} τ={self.threshold:.2f}   "
                  f"{_C.BOLD}Period:{_C.RESET} {self.period}   {cache_s}")
            print(f"  {'═'*76}")
            print(f"  {_C.BOLD}F.{_C.RESET} {_C.GREEN}Fetch / Refresh Market Data{_C.RESET}")
            print(f"  {'─'*76}")
            print(f"  {_C.BOLD}1.{_C.RESET} Pearson Correlation Graph        "
                  f"{_C.DIM}(pairwise linear co-movement){_C.RESET}")
            print(f"  {_C.BOLD}2.{_C.RESET} Partial Correlation Graph  "
                  f"{_C.DIM}[DEFAULT]{_C.RESET}"
                  f"  {_C.DIM}(direct links, removes confounders){_C.RESET}")
            print(f"  {_C.BOLD}3.{_C.RESET} Minimum Spanning Tree            "
                  f"{_C.DIM}(Mantegna backbone, N-1 edges){_C.RESET}")
            print(f"  {_C.BOLD}4.{_C.RESET} Granger Causality Graph          "
                  f"{_C.DIM}(directed, predictive precedence){_C.RESET}")
            print(f"  {'─'*76}")
            print(f"  {_C.BOLD}A.{_C.RESET} Show ASCII Adjacency Map + Metrics Table")
            if has_plt:
                print(f"  {_C.BOLD}V.{_C.RESET} Visualise Graph  "
                      f"[spring | spectral | circular | kamada]")
            else:
                print(f"  {_C.DIM}  V. Visualise (matplotlib not available){_C.RESET}")
            print(f"  {_C.BOLD}T.{_C.RESET} Adjust Correlation Threshold  "
                  f"(current: {self.threshold:.2f})")
            print(f"  {_C.BOLD}E.{_C.RESET} Edit Asset List")
            print(f"  {_C.BOLD}P.{_C.RESET} Change Data Period  (current: {self.period})")
            print(f"  {_C.BOLD}0.{_C.RESET} Return to Main Menu")
            print(f"  {'═'*76}")
            choice = input(f"\n  Select: ").strip().upper()
            if choice == 'F':
                self._fetch_and_cache(force=True)
                input(f"\n  Press ENTER to continue …")
            elif choice in ('1', '2', '3', '4'):
                if not self._market.loaded or self._is_cache_stale():
                    if not self._fetch_and_cache():
                        input(f"\n  Press ENTER to continue …")
                        continue
                method_map = {
                    '1': 'pearson',
                    '2': 'partial',
                    '3': 'mst',
                    '4': 'granger',
                }
                method = method_map[choice]
                max_lag, p_val = 2, 0.05
                if method == 'granger':
                    try:
                        lag_in = input(
                            f"  Max lag (default 2, press ENTER to accept): "
                        ).strip()
                        max_lag = int(lag_in) if lag_in.isdigit() else 2
                        p_in = input(
                            f"  p-value threshold (default 0.05, press ENTER): "
                        ).strip()
                        p_val = float(p_in) if p_in else 0.05
                    except ValueError:
                        pass
                report = self._build_and_analyse(
                    method, max_lag=max_lag, p_value=p_val
                )
                if report:
                    _draw_ascii_graph(report)
                    if has_plt and report.n_edges > 0:
                        show_plt = input(
                            f"\n  {_C.CYAN}Open matplotlib graph? [y/N]: {_C.RESET}"
                        ).strip().lower()
                        if show_plt == 'y':
                            layout = input(
                                "  Layout [spring/spectral/circular/kamada] "
                                "(default spring): "
                            ).strip().lower() or "spring"
                            _draw_matplotlib_graph(report, layout=layout)
                input(f"\n  Press ENTER to continue …")
            elif choice == 'A':
                if self._last_report:
                    _draw_ascii_graph(self._last_report)
                else:
                    print(f"  {_C.YELLOW}[⚠] No graph computed yet. Run options 1–4 first.{_C.RESET}")
                input(f"\n  Press ENTER to continue …")
            elif choice == 'V':
                if not has_plt:
                    print(f"  {_C.RED}[!] matplotlib not available. "
                          f"Run: pip install matplotlib{_C.RESET}")
                elif not self._last_report:
                    print(f"  {_C.YELLOW}[⚠] No graph computed yet. Run options 1–4 first.{_C.RESET}")
                else:
                    layout = input(
                        "  Layout [spring/spectral/circular/kamada] "
                        "(default spring): "
                    ).strip().lower() or "spring"
                    save = input(
                        "  Save to file? Enter path or ENTER to display: "
                    ).strip() or None
                    _draw_matplotlib_graph(
                        self._last_report,
                        layout    = layout,
                        save_path = save,
                    )
                input(f"\n  Press ENTER to continue …")
            elif choice == 'T':
                print(f"  Current threshold: τ = {self.threshold:.2f}")
                print(f"  {_C.DIM}Typical ranges: 0.2 (permissive) · 0.4 (standard) · "
                      f"0.6 (conservative){_C.RESET}")
