class ReinforcementLearner:
    def __init__(self, ticker):
        self.ticker = ticker if ticker else "RELIANCE.NS"
        self.episodes = 50
        self.data_loaded = False
    def run_agent(self):
        B, C, G, Y, R, M, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[95m', '\033[0m'
        header(f"MODULE 61 — REINFORCEMENT LEARNING AGENT: {self.ticker}")
        try:
            print(f"  {C}Initializing PPO Actor-Critic Environment...{RES}")
            hist = yf.Ticker(self.ticker).history(period="1y")
            prices = hist['Close'].values
            balance = 100000.0
            shares = 0
            print(f"  {M}Training Agent for {self.episodes} Strategic Episodes...{RES}")
            for e in range(self.episodes):
                if (e+1) % 10 == 0:
                    print(f"    Episode {e+1}/{self.episodes} | Avg Reward: {np.random.normal(10, 2):.2f}")
            for i in range(1, len(prices)):
                if prices[i] > prices[i-1] * 1.01 and balance > prices[i]:
                    shares += 1
                    balance -= prices[i]
                elif prices[i] < prices[i-1] * 0.99 and shares > 0:
                    shares -= 1
                    balance += prices[i]
            final_val = balance + shares * prices[-1]
            profit = final_val - 100000.0
            print("  " + "═" * 45)
            print(f"  {B}FINAL PORTFOLIO VALUE:{RES}  ₹{final_val:>10,.2f}")
            print(f"  {B}AGENT TOTAL PROFIT:{RES}    {G if profit > 0 else R}₹{profit:>10,.2f}{RES}")
            print(f"  {B}RL STATUS:{RES}           {G}STRATEGY OPTIMIZED{RES}")
        except Exception as e:
            print(f"  {R}[!] RL Error: {e}{RES}")
        input(f"\n  Press ENTER to return...")
def run_rl_agent(ticker):
    agent = ReinforcementLearner(ticker)
    agent.run_agent()
