def _m62_pick_model(cfg: dict) -> dict:
    print("\n  ── Free OpenRouter Models ───────────────────────────")
    print(f"  {'#':<4} {'Model':<18} {'Note'}")
    print("  " + "─" * 54)
    for i, m in enumerate(_M62_FREE_MODELS, 1):
        active = " ◄" if m["id"] == cfg["model_id"] else ""
        print(f"  {i:<4} {m['name']:<18} {m['note']}{active}")
    print()
    try:
        choice = input("  Enter number to switch (ENTER to cancel): ").strip()
    except (EOFError, KeyboardInterrupt):
        return cfg
    if not choice:
        return cfg
    try:
        idx = int(choice) - 1
        if 0 <= idx < len(_M62_FREE_MODELS):
            sel               = _M62_FREE_MODELS[idx]
            cfg["model_id"]   = sel["id"]
            cfg["model_name"] = sel["name"]
            _m62_save_config(cfg)
            print(f"  [✓] Switched to {sel['name']}")
        else:
            print("  [!] Number out of range.")
    except ValueError:
        print("  [!] Enter a valid number.")
    return cfg
def _prepare_hmm_features(ticker: str) -> "tuple[pd.DataFrame, np.ndarray, np.ndarray] | tuple[None, None, None]":
    try:
        from sklearn.preprocessing import StandardScaler
    except ImportError:
        class StandardScaler:
            def fit_transform(self, X):
                self._mean = X.mean(axis=0)
                self._std  = X.std(axis=0)
                self._std[self._std < 1e-10] = 1.0
                return (X - self._mean) / self._std
            def transform(self, X):
                return (X - self._mean) / self._std
    print(f"  Downloading 5-year daily data for {ticker} …")
    raw = yf.Ticker(ticker).history(period="5y")
    if raw is None or raw.empty or len(raw) < 100:
        print(f"  ✗ Insufficient data for '{ticker}'.")
        return None, None, None
    df = raw.copy()
    close = df['Close']
    df['ret']    = np.log(close / close.shift(1))
    df['vol21']  = df['ret'].rolling(21).std() * np.sqrt(252)
    df['mom5']   = close.pct_change(5)
    roll_mean  = df['ret'].rolling(63).mean()
    roll_std   = df['ret'].rolling(63).std().replace(0, np.nan)
    df['zret']  = (df['ret'] - roll_mean) / roll_std
    df = df.dropna()
    if len(df) < 60:
        print("  ✗ Too few rows after feature engineering.")
        return None, None, None
    feature_cols = ['ret', 'vol21', 'mom5', 'zret']
    X_raw = df[feature_cols].values.astype(float)
    scaler = StandardScaler()
    X_std  = scaler.fit_transform(X_raw)
    return df, X_std, X_raw
def _fit_hmm(
    X_std:    "np.ndarray",
    X_raw:    "np.ndarray",
    df:       "pd.DataFrame",
    n_states: int = 3,
) -> "dict | None":
    try:
        from hmmlearn.hmm import GaussianHMM
    except ImportError:
        print("  [!] Installing hmmlearn …")
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "hmmlearn", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
        from hmmlearn.hmm import GaussianHMM
    best_model  = None
    best_score  = -np.inf
    N_RESTARTS  = 10
    print(f"  Fitting {n_states}-state GaussianHMM "
          f"({N_RESTARTS} random restarts, max 2000 EM iters) …")
    for seed in range(N_RESTARTS):
        try:
            model = GaussianHMM(
                n_components    = n_states,
                covariance_type = "full",
                n_iter          = 2000,
                random_state    = seed,
                tol             = 1e-5,
            )
            model.fit(X_std)
            score = model.score(X_std)
            if score > best_score:
                best_score  = score
                best_model  = model
        except Exception:
            continue
    if best_model is None:
        print("  ✗ All HMM fitting attempts failed.")
        return None
    print(f"  [✓] Best log-likelihood: {best_score:.2f} "
          f"(converged in {best_model.monitor_.iter} iters)")
    viterbi_states = best_model.predict(X_std)
    posterior = best_model.predict_proba(X_std)                 
    mean_returns = best_model.means_[:, 0]                              
    sorted_states = np.argsort(mean_returns)                          
    if n_states == 2:
        labels = {
            int(sorted_states[0]): "Bear",
            int(sorted_states[1]): "Bull",
        }
        colors = {
            int(sorted_states[0]): '#e74c3c',
            int(sorted_states[1]): '#2ecc71',
        }
    elif n_states == 3:
        labels = {
            int(sorted_states[0]): "Bear",
            int(sorted_states[1]): "Neutral",
            int(sorted_states[2]): "Bull",
        }
        colors = {
            int(sorted_states[0]): '#e74c3c',
            int(sorted_states[1]): '#f39c12',
            int(sorted_states[2]): '#2ecc71',
        }
    else:            
        labels = {
            int(sorted_states[0]): "Crash",
            int(sorted_states[1]): "Bear",
            int(sorted_states[2]): "Neutral",
            int(sorted_states[3]): "Bull",
        }
        colors = {
            int(sorted_states[0]): '#9b59b6',
            int(sorted_states[1]): '#e74c3c',
            int(sorted_states[2]): '#f39c12',
            int(sorted_states[3]): '#2ecc71',
        }
    current_state  = int(viterbi_states[-1])
    current_label  = labels[current_state]
    current_post   = posterior[-1]                                      
    next_probs = current_post @ best_model.transmat_               
    n_obs    = len(X_std)
    n_feat   = X_std.shape[1]
    n_params = (
        n_states * (n_states - 1)                                               
        + (n_states - 1)                                       
        + n_states * n_feat                     
        + n_states * n_feat * (n_feat + 1) // 2                                
    )
    aic = -2 * best_score + 2 * n_params
    bic = -2 * best_score + np.log(n_obs) * n_params
    return {
        "model":          best_model,
        "viterbi":        viterbi_states,
        "posterior":      posterior,
        "labels":         labels,
        "colors":         colors,
        "current_state":  current_state,
        "current_label":  current_label,
        "current_post":   current_post,
        "next_probs":     next_probs,
        "log_likelihood": float(best_score),
        "aic":            float(aic),
        "bic":            float(bic),
        "n_params":       n_params,
        "n_obs":          n_obs,
        "n_states":       n_states,
    }
def _compute_state_analytics(
    df:       "pd.DataFrame",
    result:   dict,
    X_raw:    "np.ndarray",
) -> dict:
    labels    = result["labels"]
    viterbi   = result["viterbi"]
    model     = result["model"]
    n_states  = result["n_states"]
    posterior = result["posterior"]
    close  = df['Close'].values
    ret    = df['ret'].values                                            
    vol21  = df['vol21'].values
    dates  = df.index
    state_stats = {}
    for k in range(n_states):
        mask = viterbi == k
        label = labels[k]
        if mask.sum() == 0:
            state_stats[label] = {}
            continue
        state_ret  = ret[mask]
        state_vol  = vol21[mask]
        n_days     = int(mask.sum())
        pct_time   = float(n_days / len(viterbi) * 100)
        avg_ret    = float(np.mean(state_ret) * 252 * 100)                 
        avg_vol    = float(np.mean(state_vol) * 100)
        med_ret    = float(np.median(state_ret) * 252 * 100)
        std_ret    = float(np.std(state_ret, ddof=1))
        daily_sharpe = float(np.mean(state_ret) / std_ret) if std_ret > 0 else 0
        ann_sharpe   = daily_sharpe * np.sqrt(252)
        win_rate   = float(np.mean(state_ret > 0) * 100)
        state_prices  = close[mask]
        state_peak    = np.maximum.accumulate(state_prices)
        state_dd      = float(np.min(
            (state_prices - state_peak) / state_peak * 100
        )) if len(state_prices) > 1 else 0.0
        state_stats[label] = {
            "n_days":          n_days,
            "pct_time":        round(pct_time, 1),
            "ann_return_pct":  round(avg_ret, 2),
            "median_ann_pct":  round(med_ret, 2),
            "avg_vol_pct":     round(avg_vol, 2),
            "ann_sharpe":      round(ann_sharpe, 3),
            "win_rate_pct":    round(win_rate, 1),
            "worst_dd_pct":    round(state_dd, 2),
        }
    trans = {}
    for i in range(n_states):
        row = {}
        for j in range(n_states):
            row[labels[j]] = round(float(model.transmat_[i, j]) * 100, 1)
        trans[labels[i]] = row
    dwell = {labels[k]: {"runs": [], "avg": 0, "max": 0}
             for k in range(n_states)}
    cur_state = viterbi[0]
    cur_count = 1
    for i in range(1, len(viterbi)):
        if viterbi[i] == cur_state:
            cur_count += 1
        else:
            dwell[labels[cur_state]]["runs"].append(cur_count)
            cur_state = viterbi[i]
            cur_count = 1
    dwell[labels[cur_state]]["runs"].append(cur_count)
    for label, dt in dwell.items():
        runs = dt["runs"]
        dt["avg"] = round(float(np.mean(runs)), 1) if runs else 0
        dt["max"] = int(max(runs)) if runs else 0
        del dt["runs"]
    fwd_returns = {labels[k]: {
        "fwd_5d":  [], "fwd_21d": [], "fwd_63d": [],
    } for k in range(n_states)}
    for i in range(1, len(viterbi)):
        if viterbi[i] != viterbi[i - 1]:
            entry_state = viterbi[i]
            label       = labels[entry_state]
            for horizon, key in [(5, "fwd_5d"), (21, "fwd_21d"),
                                  (63, "fwd_63d")]:
                end_idx = i + horizon
                if end_idx < len(close):
                    fwd_ret = (close[end_idx] / close[i] - 1) * 100
                    fwd_returns[label][key].append(float(fwd_ret))
    fwd_summary = {}
    for label, horizons in fwd_returns.items():
        fwd_summary[label] = {}
        for key, vals in horizons.items():
            if vals:
                fwd_summary[label][f"{key}_avg_pct"] = round(
                    float(np.mean(vals)), 2
                )
                fwd_summary[label][f"{key}_win_pct"] = round(
                    float(np.mean(np.array(vals) > 0)) * 100, 1
                )
                fwd_summary[label][f"{key}_n"] = len(vals)
            else:
                fwd_summary[label][f"{key}_avg_pct"] = None
                fwd_summary[label][f"{key}_win_pct"] = None
                fwd_summary[label][f"{key}_n"]       = 0
    current_post_dict = {
        labels[k]: round(float(posterior[-1, k]) * 100, 1)
        for k in range(n_states)
    }
    feature_names = ["daily_log_ret", "vol21_annualised",
                     "mom5_pct", "return_zscore"]
    raw_mean = X_raw.mean(axis=0)
    raw_std  = X_raw.std(axis=0)
    raw_std[raw_std < 1e-10] = 1.0
    emission_params = {}
    for k in range(n_states):
        label = labels[k]
        raw_means = model.means_[k] * raw_std + raw_mean
        emission_params[label] = {
            "daily_log_ret_pct":      round(float(raw_means[0]) * 100, 4),
            "ann_ret_pct":            round(float(raw_means[0]) * 252 * 100, 2),
            "vol21_annualised_pct":   round(float(raw_means[1]) * 100, 2),
            "mom5_pct":               round(float(raw_means[2]) * 100, 3),
            "return_zscore":          round(float(raw_means[3]), 3),
        }
    next_probs_dict = {
        labels[k]: round(float(result["next_probs"][k]) * 100, 1)
        for k in range(n_states)
    }
    next_most_likely = max(next_probs_dict, key=next_probs_dict.get)
    return {
        "state_stats":      state_stats,
        "transition_matrix": trans,
        "dwell_times":      dwell,
        "forward_returns":  fwd_summary,
        "posterior_current": current_post_dict,
        "next_state_probs": next_probs_dict,
        "next_most_likely": next_most_likely,
        "emission_params":  emission_params,
        "model_quality": {
            "log_likelihood": round(result["log_likelihood"], 2),
            "aic":            round(result["aic"], 2),
            "bic":            round(result["bic"], 2),
            "n_params":       result["n_params"],
            "n_obs":          result["n_obs"],
        },
    }
def _print_hmm_report(
    ticker:    str,
    result:    dict,
    analytics: dict,
) -> None:
    BOLD = '\033[1m'; RST = '\033[0m'
    LABEL_ANSI = {
        "Bull":    '\033[92m',
        "Neutral": '\033[93m',
        "Bear":    '\033[91m',
        "Crash":   '\033[95m',
    }
    def _clr(label):
        return LABEL_ANSI.get(label, '\033[96m')
    cur_label = result["current_label"]
    cur_post  = analytics["posterior_current"]
    model_q   = analytics["model_quality"]
    section("HMM Model Quality")
    print(f"  States           : {result['n_states']}")
    print(f"  Log-Likelihood   : {model_q['log_likelihood']:,.2f}")
    print(f"  AIC              : {model_q['aic']:,.2f}  "
          f"(lower = better fit vs complexity)")
    print(f"  BIC              : {model_q['bic']:,.2f}  "
          f"(lower = better; penalises params more than AIC)")
    print(f"  Free parameters  : {model_q['n_params']}  "
          f"| Observations: {model_q['n_obs']}")
    section("Current State (Viterbi + Posterior)")
    print(f"  Viterbi State    : {BOLD}{_clr(cur_label)}{cur_label}{RST}")
    print(f"  Posterior probs  : ", end="")
    parts = [f"{_clr(lb)}{lb}{RST} {p:.1f}%"
             for lb, p in cur_post.items()]
    print("  |  ".join(parts))
    print(f"\n  Next-State Forecast:")
    for lb, p in analytics["next_state_probs"].items():
        bar = '█' * int(p / 5) + '░' * (20 - int(p / 5))
        print(f"    {_clr(lb)}{lb:<10}{RST} [{bar}] {p:.1f}%")
    print(f"\n  Most likely next state: "
          f"{_clr(analytics['next_most_likely'])}"
          f"{analytics['next_most_likely']}{RST}")
    section("Emission Parameters (Unstandardised Feature Means per State)")
    print(f"  {'State':<12} {'AnnRet%':>9} {'Vol21%':>9} "
          f"{'Mom5%':>9} {'RetZ':>8}")
    print("  " + "─" * 50)
    for label, ep in analytics["emission_params"].items():
        print(f"  {_clr(label)}{label:<12}{RST} "
              f"{ep['ann_ret_pct']:>+8.2f}% "
              f"{ep['vol21_annualised_pct']:>8.2f}% "
              f"{ep['mom5_pct']:>+8.3f}% "
              f"{ep['return_zscore']:>+7.3f}")
    section("Historical State Statistics")
    print(f"  {'State':<12} {'Days':>6} {'%Time':>6} "
          f"{'AnnRet%':>9} {'Vol%':>7} {'Sharpe':>8} "
          f"{'WinRate':>8} {'MaxDD%':>8}")
    print("  " + "─" * 70)
    for label, st in analytics["state_stats"].items():
        if not st:
            continue
        print(f"  {_clr(label)}{label:<12}{RST} "
              f"{st['n_days']:>6} "
              f"{st['pct_time']:>5.1f}% "
              f"{st['ann_return_pct']:>+8.2f}% "
              f"{st['avg_vol_pct']:>6.2f}% "
              f"{st['ann_sharpe']:>+7.3f} "
              f"{st['win_rate_pct']:>7.1f}% "
              f"{st['worst_dd_pct']:>+7.2f}%")
    section("State Dwell Times (consecutive days)")
    for label, dt in analytics["dwell_times"].items():
        print(f"  {_clr(label)}{label:<12}{RST} "
              f"avg {dt['avg']:>5.1f} days  |  max {dt['max']:>4} days")
    section("Forward Returns at State Entry (avg % | win rate)")
    print(f"  {'State':<12} "
          f"{'5d avg':>9} {'5d win%':>8} "
          f"{'21d avg':>9} {'21d win%':>9} "
          f"{'63d avg':>9} {'63d win%':>9}")
    print("  " + "─" * 68)
    for label, fr in analytics["forward_returns"].items():
        def _fv(k):
            v = fr.get(k)
            return f"{v:>+8.2f}%" if v is not None else "      N/A"
        def _fw(k):
            v = fr.get(k)
            return f"{v:>8.1f}%" if v is not None else "      N/A"
        print(f"  {_clr(label)}{label:<12}{RST} "
              f"{_fv('fwd_5d_avg_pct')} "
              f"{_fw('fwd_5d_win_pct')} "
              f"{_fv('fwd_21d_avg_pct')} "
              f"{_fw('fwd_21d_win_pct')} "
              f"{_fv('fwd_63d_avg_pct')} "
              f"{_fw('fwd_63d_win_pct')}")
    section("Transition Matrix  (row=from, col=to, % probability)")
    trans  = analytics["transition_matrix"]
    labels = list(trans.keys())
    print(f"  {'From / To':<12} " +
          "  ".join(f"{lb:>10}" for lb in labels))
    print("  " + "─" * (14 + 12 * len(labels)))
    for from_lb in labels:
        row   = trans[from_lb]
        vals  = [row.get(to, 0) for to in labels]
        diag  = row.get(from_lb, 0)
        cells = []
        for to_lb, v in zip(labels, vals):
            if to_lb == from_lb:
                cells.append(f"\033[90m{v:>9.1f}%\033[0m")               
            elif v == max(row.get(t, 0) for t in labels if t != from_lb):
                cells.append(f"\033[93m{v:>9.1f}%\033[0m")                
            else:
                cells.append(f"{v:>9.1f}%")
        print(f"  {_clr(from_lb)}{from_lb:<12}\033[0m " +
              "  ".join(cells))
def _render_hmm_dashboard(
    df:        "pd.DataFrame",
    result:    dict,
    analytics: dict,
    ticker:    str,
) -> None:
    from matplotlib.gridspec import GridSpec
    plt.style.use('dark_background')
    BG    = '#0d1117'
    PANEL = '#161b22'
    GRID  = '#2a2a3c'
    viterbi   = result["viterbi"]
    posterior = result["posterior"]
    labels    = result["labels"]
    colors    = result["colors"]
    n_states  = result["n_states"]
    label_names = [labels[k] for k in range(n_states)]
    fig = plt.figure(figsize=(24, 20), facecolor=BG)
    gs  = GridSpec(
        3, 2, figure=fig,
        height_ratios=[2.2, 1.5, 1.3],
        hspace=0.40, wspace=0.30,
        left=0.05, right=0.97,
        top=0.93, bottom=0.04,
    )
    ax0 = fig.add_subplot(gs[0, :])                  
    ax1 = fig.add_subplot(gs[1, 0])                            
    ax2 = fig.add_subplot(gs[1, 1])              
    ax3 = fig.add_subplot(gs[2, 0])                               
    ax4 = fig.add_subplot(gs[2, 1])                             
    for ax in [ax0, ax1, ax2, ax3, ax4]:
        ax.set_facecolor(PANEL)
        for sp in ax.spines.values():
            sp.set_edgecolor(GRID)
    close_arr = df['Close'].values
    idx       = df.index
    cur_label = result["current_label"]
    cur_color = colors[result["current_state"]]
    prev_state   = viterbi[0]
    span_start   = idx[0]
    for i in range(1, len(viterbi)):
        if viterbi[i] != prev_state or i == len(viterbi) - 1:
            ax0.axvspan(span_start, idx[i],
                        alpha=0.14, color=colors[prev_state])
            span_start = idx[i]
            prev_state = viterbi[i]
    for k in range(n_states):
        mask = viterbi == k
        ax0.scatter(
            idx[mask], close_arr[mask],
            c=colors[k], s=3, alpha=0.6, zorder=3,
            label=labels[k],
        )
    ax0.plot(idx, close_arr, color='white', lw=0.8, alpha=0.35,
             zorder=2, label='_nolegend_')
    max_post = posterior.max(axis=1)
    ax0_twin = ax0.twinx()
    ax0_twin.fill_between(idx, max_post * 100, 70,
                          where=(max_post * 100 < 70),
                          color='white', alpha=0.05,
                          label='Uncertain zone (<70% conf)')
    ax0_twin.set_ylabel("Max Post. %", fontsize=8,
                        color='white', alpha=0.5)
    ax0_twin.tick_params(colors='white', labelsize=7)
    for tick in ax0_twin.get_yticklabels():
        tick.set_alpha(0.5)
    ax0_twin.set_ylim(0, 100)
    patches = [mpatches.Patch(color=colors[k], alpha=0.7,
                              label=labels[k])
               for k in range(n_states)]
    ax0.legend(handles=patches, fontsize=8.5, loc='upper left',
               ncol=n_states,
               facecolor='#1a1a2e', edgecolor=GRID,
               labelcolor='white', framealpha=0.9)
    ax0.set_ylabel("Price (₹)", fontsize=10, color='white')
    ax0.set_title(
        f"Price Coloured by HMM Viterbi State  |  "
        f"Current: {cur_label}  |  "
        f"Next most likely: {analytics['next_most_likely']}",
        fontsize=12, color='white', pad=8,
    )
    ax0.tick_params(colors='white', labelsize=8)
    ax0.grid(ls='--', alpha=0.15, zorder=0)
    bottom = np.zeros(len(idx))
    for k in range(n_states):
        ax1.fill_between(idx, bottom,
                         bottom + posterior[:, k] * 100,
                         color=colors[k], alpha=0.75,
                         label=labels[k])
        bottom += posterior[:, k] * 100
    ax1.set_ylim(0, 100)
    ax1.yaxis.set_major_formatter(
        plt.FuncFormatter(lambda x, _: f"{x:.0f}%")
    )
    ax1.set_title(
        "Posterior State Probabilities  (Forward-Backward soft assignments)",
        fontsize=11, color='white', pad=8,
    )
    ax1.set_ylabel("Probability %", fontsize=9, color='white')
    ax1.tick_params(colors='white', labelsize=8)
    ax1.grid(ls='--', alpha=0.15)
    ax1.legend(fontsize=7.5, loc='lower left', ncol=n_states,
               facecolor='#1a1a2e', edgecolor=GRID,
               labelcolor='white', framealpha=0.8)
    ax2.plot(idx, df['vol21'] * 100, color='#f39c12',
             lw=1.1, label='Vol21 %', zorder=3)
    ax2.fill_between(idx, df['vol21'] * 100, 0,
                     alpha=0.12, color='#f39c12')
    ax2.axhline(20, color='#f39c12', ls='--', lw=0.7, alpha=0.5,
                label='20% elevated')
    ax2.axhline(35, color='#e74c3c', ls='--', lw=0.7, alpha=0.5,
                label='35% panic')
    ax2.set_ylabel("Ann. Vol %", fontsize=9, color='#f39c12')
    ax2.tick_params(colors='white', labelsize=8)
    ax2r = ax2.twinx()
    ax2r.plot(idx, df['zret'], color='#3498db',
              lw=0.8, alpha=0.7, label='Return Z-score')
    ax2r.axhline(0, color='white', lw=0.5, alpha=0.3)
    ax2r.fill_between(idx, df['zret'], 0,
                      where=(df['zret'] > 2),
                      color='#2ecc71', alpha=0.20)
    ax2r.fill_between(idx, df['zret'], 0,
                      where=(df['zret'] < -2),
                      color='#e74c3c', alpha=0.20)
    ax2r.set_ylabel("Return Z-score", fontsize=8, color='#3498db')
    ax2r.tick_params(colors='#3498db', labelsize=7)
    ax2.set_title("Emission Features: Vol21 + Return Z-score",
                  fontsize=11, color='white', pad=8)
    ax2.grid(ls='--', alpha=0.15)
    ax2.legend(fontsize=7, loc='upper right',
               facecolor='#1a1a2e', edgecolor=GRID,
               labelcolor='white', framealpha=0.8)
    trans  = analytics["transition_matrix"]
    t_mat  = np.array([[trans[fr].get(to, 0)
                        for to in label_names]
                       for fr in label_names])
    state_colors_list = [colors[k] for k in range(n_states)]
    im = ax3.imshow(t_mat, cmap='YlOrRd',
                    vmin=0, vmax=100, aspect='auto')
    for i in range(n_states):
        for j in range(n_states):
            v = t_mat[i, j]
            txt_col = 'white' if v > 60 else 'black'
            ax3.text(j, i, f"{v:.1f}%",
                     ha='center', va='center',
                     fontsize=10, fontweight='bold',
                     color=txt_col)
        ax3.add_patch(plt.Rectangle(
            (-0.5, i - 0.5), 0.08, 1,
            color=colors[k],
            transform=ax3.transData, clip_on=False,
        ))
    ax3.set_xticks(range(n_states))
    ax3.set_yticks(range(n_states))
    ax3.set_xticklabels(
        [f"→ {lb}" for lb in label_names],
        fontsize=9, color='white',
    )
    ax3.set_yticklabels(
        [f"{lb} →" for lb in label_names],
        fontsize=9, color='white',
    )
    ax3.set_title(
        "HMM Transition Matrix  (% probability of next state)",
        fontsize=11, color='white', pad=8,
    )
    plt.colorbar(im, ax=ax3, fraction=0.03, pad=0.02).ax.tick_params(
        colors='white', labelsize=7
    )
    fwd    = analytics["forward_returns"]
    dwell  = analytics["dwell_times"]
    x_pos  = np.arange(n_states)
    width  = 0.25
    bar_colors = [colors[k] for k in range(n_states)]
    for i, (horizon, label_h) in enumerate(
        [("fwd_5d_avg_pct", "5d"), ("fwd_21d_avg_pct", "21d"),
         ("fwd_63d_avg_pct", "63d")]
    ):
        vals = []
        for lb in label_names:
            v = fwd.get(lb, {}).get(horizon)
            vals.append(v if v is not None else 0.0)
        ax4.bar(
            x_pos + (i - 1) * width,
            vals,
            width=width,
            label=f"{label_h} avg",
            alpha=0.80,
            edgecolor='white',
            linewidth=0.4,
            color=[bar_colors[k] for k in range(n_states)],
        )
    ax4.axhline(0, color='white', lw=1.0, zorder=5)
    ax4.set_xticks(x_pos)
    ax4.set_xticklabels(label_names, fontsize=9, color='white')
    ax4.set_title(
        "Forward Returns at State Entry  (5d / 21d / 63d avg)",
        fontsize=11, color='white', pad=8,
    )
    ax4.set_ylabel("Avg Return %", fontsize=9, color='white')
    ax4.tick_params(colors='white', labelsize=8)
    ax4.grid(axis='y', ls='--', alpha=0.20)
    ax4.legend(fontsize=8, loc='upper right',
               facecolor='#1a1a2e', edgecolor=GRID,
               labelcolor='white', framealpha=0.9)
    for ax in [ax1, ax2]:
        ax.xaxis.set_major_formatter(mdates.DateFormatter('%Y'))
        ax.xaxis.set_major_locator(mdates.YearLocator())
        plt.setp(ax.get_xticklabels(), rotation=0,
                 color='white', fontsize=8)
    fig.suptitle(
        f"Hidden Markov Model Regime Analysis  |  {ticker.upper()}  "
        f"|  {n_states}-State GaussianHMM  "
        f"|  Current: {cur_label}  "
        f"|  Next: {analytics['next_most_likely']}  "
        f"|  Log-L: {analytics['model_quality']['log_likelihood']:,.0f}",
        fontsize=13, fontweight='bold', color='white', y=0.96,
    )
    plt.show()
def _build_hmm_context(
    ticker:    str,
    n_states:  int,
    result:    dict,
    analytics: dict,
) -> dict:
    import math as _m
    def _sanitise(obj):
        if isinstance(obj, dict):
            return {k: _sanitise(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_sanitise(v) for v in obj]
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating, float)):
            v = float(obj)
            return None if (_m.isnan(v) or _m.isinf(v)) else v
        if isinstance(obj, (np.bool_,)):
            return bool(obj)
        return obj
    return _sanitise({
        "ticker":          ticker,
        "analysis_period": "5 years daily",
        "hmm_config": {
            "n_states":          n_states,
            "covariance_type":   "full (each state has own covariance matrix)",
            "emission_features": [
                "daily_log_return",
                "21day_realised_vol_annualised",
                "5day_momentum",
                "63day_return_zscore",
            ],
            "fitting_method": "Baum-Welch EM, 10 restarts, max 2000 iters",
            "decoding":       "Viterbi (hard) + Forward-Backward (soft posterior)",
        },
        "current_state": {
            "viterbi_label":     result["current_label"],
            "posterior_probs":   analytics["posterior_current"],
        },
        "next_state_forecast": {
            "probabilities":     analytics["next_state_probs"],
            "most_likely":       analytics["next_most_likely"],
            "formula":           "P(next) = current_posterior @ transition_matrix",
        },
        "model_quality":        analytics["model_quality"],
        "emission_params":      analytics["emission_params"],
        "state_statistics":     analytics["state_stats"],
        "dwell_times":          analytics["dwell_times"],
        "transition_matrix":    analytics["transition_matrix"],
        "forward_returns":      analytics["forward_returns"],
        "concept_guide": {
            "viterbi":     "Hard state assignment — most likely single path through states",
            "posterior":   "Soft state probability — P(state|all data). Shows uncertainty.",
            "transition":  "P(next state | current state). Diagonal = regime persistence.",
            "dwell_time":  "Average consecutive days in each regime before switching.",
            "forward_ret": "Average return X days after first entering this regime.",
            "aic_bic":     "Model selection: lower = better. BIC penalises more for params.",
            "emission":    "Multivariate Gaussian parameters per state (mean + covariance).",
        },
    })
def _build_m62_system_prompt(ctx: dict, model_name: str) -> str:
    ticker    = ctx.get("ticker", "Unknown")
    cur       = ctx.get("current_state", {})
    nxt       = ctx.get("next_state_forecast", {})
    mq        = ctx.get("model_quality", {})
    cur_label = cur.get("viterbi_label", "Unknown")
    nxt_label = nxt.get("most_likely", "Unknown")
    persona = textwrap.dedent(f"""\
        You are a senior Quantitative Strategist specialising in Hidden Markov
        Model regime analysis for financial markets. You have just completed a
        full HMM analysis for {ticker} using a {ctx.get('hmm_config',{}).get('n_states',3)}-state
        multivariate Gaussian HMM fitted on 4 emission features.
        Current regime (Viterbi): {cur_label}
        Next most likely regime:  {nxt_label}
        Model log-likelihood: {mq.get('log_likelihood','?')}
        AIC: {mq.get('aic','?')}  |  BIC: {mq.get('bic','?')}
        You are powered by {model_name}.
        Explain HMM concepts in plain English BEFORE giving numbers.
        The audience ranges from quantitative beginners to experienced traders.
    """)
    rules = textwrap.dedent("""\
        RULES:
        1. Ground every claim in <hmm_data> below. Do not invent values.
        2. Always distinguish Viterbi (hard assignment) from posterior
           (soft probability) — they answer different questions.
        3. When discussing forward returns, include both average return
           AND win rate: "entering this state has historically returned
           +X% over 21 days with Y% of entries being profitable."
        4. The transition matrix diagonal = regime persistence probability.
           Always mention this when discussing how long a regime typically lasts.
        5. AIC/BIC explain model complexity trade-off — reference them when
           discussing whether n_states is appropriate.
        6. Emission parameters (per-state means) are the fingerprint of each
           regime — use them to explain WHAT each state actually looks like
           in terms of return, volatility, and momentum.
        7. Keep responses under 500 words unless user explicitly asks for more.
        8. If a metric is not in the data, say so explicitly.
    """)
    fmt = textwrap.dedent("""\
        FORMAT:
        - Prefix every response: [HMM] | [REGIME] | [FORECAST] |
          [RISK] | [ANSWER] | [INFO]
        - **Bold** state names and key metric values.
        - Use > blockquotes for critical warnings
          (bear/crash state, low transition confidence, model fit warnings).
        - Use Markdown tables for:
          • Transition matrix comparison
          • State emission parameter comparison
          • Forward return profiles across states
        - Express probabilities as percentages (e.g. "73.2% probability").
    """)
    data_json  = json.dumps(ctx, indent=2)
    data_block = f"<hmm_data>\n{data_json}\n</hmm_data>"
    return "\n\n".join([persona, rules, fmt, data_block])
def _m62_stream_response(
    history:    list,
    api_key:    str,
    model_id:   str,
    model_name: str,
) -> str:
    try:
        pass
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "requests", "--quiet"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
        )
    from rich.console  import Console
    from rich.markdown import Markdown
    from rich.panel    import Panel
    console = Console()
    MAX_TURNS  = 20
    turn_count = (len(history) - 1) // 2
    if turn_count > MAX_TURNS and len(history) > 3:
        del history[1:3]
    headers = {
        "Authorization": f"Bearer {api_key}",
        "HTTP-Referer":  "https://github.com/quant-terminal",
        "X-Title":       "Module 62 HMM CoPilot",
        "Content-Type":  "application/json",
    }
    payload = {
        "model":    model_id,
        "messages": history,
        "stream":   True,
    }
    BACKOFF_BASE  = 1.5
    MAX_RETRIES   = 3
    full_response = ""
    last_error    = None
    for attempt in range(MAX_RETRIES):
        try:
            resp = requests.post(
                "http://127.0.0.1:9999/disabled",
                headers=headers,
                json=payload,
                stream=True,
                timeout=(10, 60),
            )
            if resp.status_code == 401:
                console.print(
                    "\n  [bold red][!] API key rejected (401). "
                    "Use /setkey to update.[/bold red]"
                )
                return ""
            if resp.status_code in (429, 503):
                raise Exception(f"HTTP {resp.status_code}")
            resp.raise_for_status()
            token_count = 0
            print(f"\n  \033[90m{model_name} is analysing HMM results ",
                  end="", flush=True)
            for raw_line in resp.iter_lines():
                if not raw_line:
                    continue
                try:
                    line = raw_line.decode("utf-8", errors="replace")
                except AttributeError:
                    line = raw_line
                if not line.startswith("data: "):
                    continue
                payload_str = line[6:]
                if payload_str.strip() == "[DONE]":
                    break
                try:
                    chunk = json.loads(payload_str)
                    token = chunk["choices"][0]["delta"].get("content", "")
                    if token:
                        full_response += token
                        token_count   += len(token.split())
                        if token_count % 20 == 0:
                            print(".", end="", flush=True)
                except (json.JSONDecodeError, KeyError, IndexError):
                    pass
            print(f" done ({token_count} words)\033[0m\n")
            if full_response.strip():
                console.print(
                    Panel(
                        Markdown(full_response),
                        title=f"[bold cyan]{model_name}[/bold cyan]",
                        border_style="cyan",
                        padding=(1, 2),
                        expand=True,
                    )
                )
            return full_response
        except requests.Timeout:
            console.print(
                "\n  [bold red][!] Timed out. "
                "Try shorter question or /models.[/bold red]"
            )
            return ""
        except Exception as exc:
            last_error = exc
            if attempt < MAX_RETRIES - 1:
                wait = BACKOFF_BASE ** (attempt + 1)
                console.print(
                    f"  [yellow][~] Attempt {attempt+1} failed ({exc}). "
                    f"Retrying in {wait:.1f}s…[/yellow]"
                )
                time.sleep(wait)
            else:
                console.print(
                    f"  [bold red][!] All {MAX_RETRIES} attempts failed: "
                    f"{last_error}[/bold red]"
                )
    return ""
def _print_m62_chat_help() -> None:
    print("\n  ── Module 62 HMM Co-Pilot Commands ──────────────────")
    cmds = [
        ("/setkey",      "Update your OpenRouter API key"),
        ("/models",      "Browse & switch free AI models"),
        ("/model <id>",  "Switch to any model by full OpenRouter ID"),
        ("/fetchmodels", "Pull live free model list from OpenRouter API"),
        ("/clear",       "Clear conversation (keep HMM data)"),
        ("/export",      "Save session to a timestamped JSON file"),
        ("/status",      "Show model, key, current state, history"),
        ("/help",        "Show this command list"),
        ("0 / exit",     "Return to the main terminal"),
    ]
    for cmd, desc in cmds:
        print(f"  {cmd:<22}  {desc}")
    print()
def run_m62_chat(
    ticker:    str,
    n_states:  int,
    result:    dict,
    analytics: dict,
) -> None:
    cfg = _m62_load_config()
    if not cfg["api_key"]:
        print(
            "\n  \033[93m[!] No API key configured for "
            "the HMM Co-Pilot.\033[0m"
        )
        cfg = _m62_setup_key(cfg)
        if not cfg["api_key"]:
            print("  Skipping AI analysis. Run module again to configure.")
            return
    ctx = _build_hmm_context(ticker, n_states, result, analytics)
    history = [
        {
            "role":    "system",
            "content": _build_m62_system_prompt(ctx, cfg["model_name"]),
        }
    ]
    from rich.console import Console
    from rich.panel   import Panel
    console = Console()
    cur_label = result["current_label"]
    nxt_label = analytics["next_most_likely"]
    cur_post  = analytics["posterior_current"]
    mq        = analytics["model_quality"]
    console.print(Panel(
        f"[bold]Model:[/]    [cyan]{cfg['model_name']}[/cyan]\n"
        f"[bold]Ticker:[/]   [yellow]{ticker}[/yellow]  |  "
        f"{n_states}-state GaussianHMM  |  5-year daily\n"
        f"[bold]State:[/]    [green]{cur_label}[/green]  |  "
        f"Next: [yellow]{nxt_label}[/yellow]\n"
        f"[bold]Quality:[/]  "
        f"Log-L {mq['log_likelihood']:,.0f}  |  "
        f"AIC {mq['aic']:,.0f}  |  "
        f"BIC {mq['bic']:,.0f}\n"
        f"[bold]Posterior:[/] "
        + "  |  ".join(
            f"[{'green' if lb == cur_label else 'dim'}]{lb} {p:.1f}%[/]"
            for lb, p in cur_post.items()
        )
        + "\n\n[dim]Ask about HMM states, transitions, forward returns, "
        "or the algorithm. /help for commands.[/dim]",
        title="[bold cyan]🧠 HMM REGIME CO-PILOT[/bold cyan]",
        border_style="cyan",
        padding=(0, 2),
    ))
    fwd   = analytics["forward_returns"].get(cur_label, {})
    trans = analytics["transition_matrix"].get(cur_label, {})
    dwell = analytics["dwell_times"].get(cur_label, {})
    eps   = analytics["emission_params"].get(cur_label, {})
    first_prompt = (
        f"I've just fitted a {n_states}-state Hidden Markov Model to "
        f"5 years of daily data for {ticker}. "
        f"The Viterbi algorithm assigns the current date to the "
        f"'{cur_label}' state. "
        f"Give me a comprehensive integrated analysis covering all layers:\n\n"
        f"(1) EMISSION FINGERPRINT: Based on the per-state emission "
        f"parameters, what does each HMM state ACTUALLY represent in "
        f"market terms? Compare their return means, volatility, and "
        f"momentum profiles — what makes each state distinct? "
        f"Use the emission_params to give exact numbers.\n\n"
        f"(2) CURRENT STATE DEEP DIVE: The current state is '{cur_label}' "
        f"with a posterior distribution of "
        f"{', '.join(f'{lb}: {p:.1f}%' for lb, p in cur_post.items())}. "
        f"What does this posterior tell us — is the model confident, "
        f"or is there meaningful uncertainty? What does the '{cur_label}' "
        f"emission profile imply about current market conditions?\n\n"
        f"(3) FORWARD RETURN OUTLOOK: Based on the forward returns table, "
        f"what has historically happened at 5, 21, and 63 days after "
        f"entering the '{cur_label}' state? Include win rates. "
        f"How does this compare to the other states?\n\n"
        f"(4) TRANSITION FORECAST: The model forecasts the next most "
        f"likely state is '{nxt_label}'. Walk through the transition "
        f"matrix row for '{cur_label}' — what is the probability of staying "
        f"in this state vs. transitioning to each other state? "
        f"The average dwell time for '{cur_label}' is "
        f"{dwell.get('avg', '?')} days — how should this inform a trader's "
        f"time horizon?\n\n"
        f"(5) ACTIONABLE CONCLUSION: Given the current regime, forward "
        f"return profile, and most likely next transition, what is the "
        f"single most important trading insight from this analysis — "
        f"and what specific market development would cause you to "
        f"revise this view?"
    )
    history.append({"role": "user", "content": first_prompt})
    response = _m62_stream_response(
        history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
    )
    if response:
        history.append({"role": "assistant", "content": response})
    else:
        history.pop()
        console.print(
            "[bold red][!] Auto-analysis failed. "
            "You can still ask questions below.[/bold red]\n"
        )
    while True:
        try:
            from rich.console import Console as _C
            _con       = _C()
            user_input = _con.input(
                "\n  [bold cyan]You ›[/bold cyan] "
            ).strip()
        except (KeyboardInterrupt, EOFError):
            print("\n  [Co-Pilot session ended]")
            break
        except Exception:
            user_input = input("\n  You › ").strip()
        if not user_input:
            continue
        if user_input.lower() in {"0", "exit", "quit"}:
            break
        parts = user_input.split(maxsplit=1)
        cmd   = parts[0].lower()
        arg   = parts[1].strip() if len(parts) > 1 else ""
        if cmd == "/help":
            _print_m62_chat_help()
            continue
        elif cmd == "/setkey":
            cfg = _m62_setup_key(cfg)
            history[0] = {"role": "system",
                          "content": _build_m62_system_prompt(ctx, cfg["model_name"])}
            continue
        elif cmd == "/models":
            cfg = _m62_pick_model(cfg)
            history[0] = {"role": "system",
                          "content": _build_m62_system_prompt(ctx, cfg["model_name"])}
            continue
        elif cmd == "/model":
            if not arg:
                print(f"  Current: {cfg['model_id']}")
                print("  Usage:   /model <openrouter-model-id>")
            else:
                cfg["model_id"]   = arg
                cfg["model_name"] = (arg.split("/")[-1]
                                     .replace(":free", " (free)")
                                     .replace("-", " ").title())
                _m62_save_config(cfg)
                history[0] = {"role": "system",
                              "content": _build_m62_system_prompt(ctx, cfg["model_name"])}
                print(f"  [✓] Model set to: {cfg['model_name']}")
            continue
        elif cmd == "/fetchmodels":
            try:
                resp = requests.get(
                    "http://127.0.0.1:9999/disabled", timeout=10
                )
                resp.raise_for_status()
                free = [m for m in resp.json().get("data", [])
                        if m.get("id", "").endswith(":free")]
                print(f"\n  {'ID':<55} {'Ctx(K)':>6}")
                print("  " + "─" * 64)
                for m in free[:30]:
                    ctx_k = (m.get("context_length") or 0) // 1000
                    print(f"  {m['id']:<55} {ctx_k:>5}K")
                print(f"\n  {len(free)} free models. Activate: /model <id>\n")
            except Exception as exc:
                print(f"  [!] Fetch failed: {exc}")
            continue
        elif cmd == "/clear":
            history = [history[0]]
            print("  [✓] Conversation cleared. HMM data retained.")
            continue
        elif cmd == "/export":
            print("  [!] Export feature is disabled in this build.")
        elif cmd == "/status":
            turns    = (len(history) - 1) // 2
            key_hint = (f"{cfg['api_key'][:8]}…{cfg['api_key'][-4:]}"
                        if len(cfg["api_key"]) > 12 else "not set")
            print(f"\n  Model    : {cfg['model_name']} ({cfg['model_id']})")
            print(f"  API Key  : {key_hint}")
            print(f"  Ticker   : {ticker}  |  {n_states}-state HMM")
            print(f"  State    : {cur_label}  (next: {nxt_label})")
            print(f"  History  : {turns} turns (max 20 before auto-prune)\n")
            continue
        elif cmd.startswith("/"):
            print(f"  [?] Unknown command '{cmd}'. Type /help.")
            continue
        history.append({"role": "user", "content": user_input})
        ai_response = _m62_stream_response(
            history, cfg["api_key"], cfg["model_id"], cfg["model_name"]
        )
        if ai_response:
            history.append({"role": "assistant", "content": ai_response})
        else:
            history.pop()
    print("  [Co-Pilot closed — returning to terminal]\n")
def run_regime_hmm(ticker: str) -> None:
    header(f"MODULE 62 — HIDDEN MARKOV MODEL REGIME ANALYSIS  |  {ticker}")
    plt.style.use('dark_background')
    try:
        from hmmlearn.hmm import GaussianHMM
    except ImportError:
        print("  [!] Installing hmmlearn …")
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install",
                 "hmmlearn", "--quiet"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            print("  [✓] hmmlearn installed. Continuing …")
        except Exception as exc:
            print(f"  ✗ Could not install hmmlearn: {exc}")
            print("  Run manually: pip install hmmlearn")
            press_enter(); return
    print("\n  How many HMM states would you like?")
    print("  [2] Bull / Bear")
    print("  [3] Bull / Neutral / Bear  (default)")
    print("  [4] Bull / Neutral / Bear / Crash")
    try:
        n_choice = input("  Select [2/3/4, ENTER=3]: ").strip()
        n_states = int(n_choice) if n_choice in ("2", "3", "4") else 3
    except (ValueError, EOFError):
        n_states = 3
    print(f"  Using {n_states}-state model.\n")
    df, X_std, X_raw = _prepare_hmm_features(ticker)
    if df is None:
        press_enter(); return
    result = _fit_hmm(X_std, X_raw, df, n_states=n_states)
    if result is None:
        print("  ✗ HMM fitting failed completely.")
        press_enter(); return
    df = df.copy()
    df['HMM_State']    = result["viterbi"]
    df['HMM_Conf']     = result["posterior"].max(axis=1) * 100
    print("  Computing state analytics …\n")
    analytics = _compute_state_analytics(df, result, X_raw)
    _print_hmm_report(ticker, result, analytics)
    _render_hmm_dashboard(df, result, analytics, ticker)
    print(f"\n  {'─' * 54}")
    try:
        launch = input(
            "  Open AI Co-Pilot to analyse these HMM results? [Y/n]: "
        ).strip().lower()
    except (EOFError, KeyboardInterrupt):
        launch = "n"
    if launch not in {"n", "no"}:
        run_m62_chat(ticker, n_states, result, analytics)
    else:
        press_enter()
class ThreeStatementLinker:
    def __init__(self, ticker):
        self.ticker = ticker if ticker else "RELIANCE.NS"
        self.data_loaded = False
        self.fiscal_years = []                                                    
        self.inc_stmts  = []
        self.bal_sheets = []
        self.cash_flows = []
        self.balance_plugs = []
        self.ratios     = {}
        self.dupont     = {}
        self.wc_metrics = {}
        self.qoe        = {}
        self._or_key   : str = ""
        self._or_model : str = _GLOBAL_OR_MODEL
        self._load_or_config()                                   
    def _check_dependencies(self):
        try:
            import yfinance, pandas, numpy
            return True
        except ImportError:
            import sys, subprocess
            print("  \033[93m[!] Installing yfinance, pandas, numpy…\033[0m")
            try:
                subprocess.check_call([sys.executable, "-m", "pip", "install",
                                       "yfinance", "pandas", "numpy", "-q"])
                return True
            except Exception as e:
                print(f"  \033[91m[!] Install failed: {e}\033[0m")
                return False
    @staticmethod
    def _get(df, keys, col):
        for k in keys:
            if k in df.index:
                v = df.loc[k, col]
                if pd.notna(v):
                    return float(v)
        return 0.0
    @staticmethod
    def fmt(val, unit="auto", width=15):
        if val == 0:
            return "-".rjust(width)
        neg = val < 0
        av  = abs(val)
        if unit == "auto":
            if av >= 1e12:   s = f"{av/1e12:,.3f}T"
            elif av >= 1e9:  s = f"{av/1e9:,.2f}B"
            elif av >= 1e6:  s = f"{av/1e6:,.2f}M"
            elif av >= 1e3:  s = f"{av/1e3:,.1f}K"
            else:            s = f"{av:,.0f}"
        elif unit == "%":    s = f"{av:.1f}%"
        elif unit == "x":    s = f"{av:.2f}x"
        elif unit == "days": s = f"{av:.1f}d"
        else:                s = f"{av:,.2f}"
        txt = f"({s})" if neg else s
        return txt.rjust(width)
    @staticmethod
    def pct_change(new, old):
        if old == 0:
            return None
        return (new - old) / abs(old) * 100
    def fetch_financials(self):
        B,C,G,Y,R,M,RES = '\033[1m','\033[96m','\033[92m','\033[93m','\033[91m','\033[95m','\033[0m'
        print(f"\n  {C}◆ Fetching multi-year financials for {B}{self.ticker}{RES}{C}...{RES}")
        try:
            stk = yf.Ticker(self.ticker)
            inc = stk.financials                                           
            bs  = stk.balance_sheet          
            cf  = stk.cashflow                
            if inc.empty or bs.empty or cf.empty:
                print(f"  {R}[!] Insufficient data for {self.ticker}.{RES}")
                return False
            common = [d for d in inc.columns if d in bs.columns and d in cf.columns]
            if not common:
                common = inc.columns.tolist()             
            years = common[:4]                  
            self.fiscal_years = years
            g = self._get              
            self.inc_stmts, self.bal_sheets, self.cash_flows, self.balance_plugs = [], [], [], []
            for col in years:
                rev      = g(inc, ['Total Revenue','Operating Revenue'], col)
                cogs     = g(inc, ['Cost Of Revenue','Cost Of Goods Sold'], col)
                gp       = g(inc, ['Gross Profit'], col) or (rev - abs(cogs))
                rd       = g(inc, ['Research And Development','Research Development'], col)
                sga      = g(inc, ['Selling General Administrative',
                                   'Selling General And Administrative'], col)
                dep_is   = g(inc, ['Depreciation And Amortization',
                                   'Depreciation Amortization Depletion'], col)
                opex_tot = g(inc, ['Operating Expense','Total Operating Expenses'], col)
                ebit     = g(inc, ['EBIT','Operating Income',
                                   'Total Operating Income As Reported'], col) or (gp - abs(opex_tot))
                ebitda   = ebit + abs(dep_is)
                int_exp  = g(inc, ['Interest Expense',
                                   'Interest Expense Non Operating'], col)
                int_inc  = g(inc, ['Interest Income',
                                   'Interest Income Non Operating'], col)
                ebt      = g(inc, ['Pretax Income'], col) or (ebit - abs(int_exp) + int_inc)
                tax      = g(inc, ['Tax Provision','Income Tax Expense'], col)
                npat     = g(inc, ['Net Income',
                                   'Net Income Applicable To Common Shares'], col)
                eps_b    = g(inc, ['Basic EPS','Basic Eps'], col)
                eps_d    = g(inc, ['Diluted EPS','Diluted Eps'], col)
                shares_d = g(inc, ['Diluted Average Shares','Average Dilution Earnings'], col)
                gp_margin  = (gp  / rev * 100) if rev else 0
                ebit_margin= (ebit/ rev * 100) if rev else 0
                net_margin = (npat/ rev * 100) if rev else 0
                eff_tax    = (abs(tax)/ abs(ebt) * 100) if ebt else 0
                self.inc_stmts.append({
                    'Revenue': rev, 'COGS': -abs(cogs), 'Gross Profit': gp,
                    'R&D': -abs(rd), 'SG&A': -abs(sga), 'D&A (IS)': -abs(dep_is),
                    'EBIT': ebit, 'EBITDA': ebitda,
                    'Interest Exp': -abs(int_exp), 'Interest Inc': int_inc,
                    'EBT': ebt, 'Tax': -abs(tax), 'NPAT': npat,
                    'EPS Basic': eps_b, 'EPS Diluted': eps_d, 'Shares Diluted': shares_d,
                    'GP Margin %': gp_margin, 'EBIT Margin %': ebit_margin,
                    'Net Margin %': net_margin, 'Eff Tax Rate %': eff_tax,
                })
                cash     = g(bs, ['Cash And Cash Equivalents',
                                  'Cash Cash Equivalents And Short Term Investments',
                                  'Cash'], col)
                sti      = g(bs, ['Short Term Investments',
                                  'Other Short Term Investments'], col)
                ar       = g(bs, ['Net Receivables','Accounts Receivable',
                                  'Trade And Other Receivables Current'], col)
                inv      = g(bs, ['Inventory'], col)
                other_ca = g(bs, ['Other Current Assets','Prepaid Assets'], col)
                tot_ca   = g(bs, ['Total Current Assets','Current Assets'], col)
                ppe      = g(bs, ['Net PPE','Net Property Plant And Equipment',
                                  'Property Plant And Equipment Net'], col)
                goodwill = g(bs, ['Goodwill'], col)
                intang   = g(bs, ['Other Intangible Assets',
                                  'Goodwill And Other Intangible Assets'], col)
                other_nca= g(bs, ['Other Non Current Assets',
                                  'Non Current Deferred Assets'], col)
                tot_assets= g(bs, ['Total Assets'], col)
                ap       = g(bs, ['Accounts Payable',
                                  'Payables And Accrued Expenses'], col)
                accrued  = g(bs, ['Accrued Liabilities',
                                  'Current Accrued Expenses'], col)
                std      = g(bs, ['Current Debt','Short Term Debt',
                                  'Current Debt And Capital Lease Obligation'], col)
                other_cl = g(bs, ['Other Current Liabilities'], col)
                tot_cl   = g(bs, ['Total Current Liabilities',
                                  'Current Liabilities'], col)
                ltd      = g(bs, ['Long Term Debt',
                                  'Long Term Debt And Capital Lease Obligation'], col)
                other_ncl= g(bs, ['Other Non Current Liabilities',
                                  'Non Current Deferred Liabilities'], col)
                tot_ncl  = g(bs, ['Total Non Current Liabilities Net Minority Interest',
                                  'Non Current Liabilities'], col)
                tot_liab = g(bs, ['Total Liabilities Net Minority Interest',
                                  'Total Liabilities'], col)
                ret_earn = g(bs, ['Retained Earnings'], col)
                share_cap= g(bs, ['Common Stock','Share Capital'], col)
                other_eq = g(bs, ['Additional Paid In Capital',
                                  'Other Equity Adjustments'], col)
                tot_eq   = g(bs, ['Stockholders Equity',
                                  'Total Equity Gross Minority Interest'], col)
                nwc  = tot_ca - tot_cl                          
                plug = tot_assets - (tot_liab + tot_eq)
                self.bal_sheets.append({
                    'Cash': cash, 'Short-Term Invest': sti, 'Accounts Receivable': ar,
                    'Inventory': inv, 'Other Curr Assets': other_ca, 'Total Curr Assets': tot_ca,
                    'Net PPE': ppe, 'Goodwill': goodwill, 'Intangibles': intang,
                    'Other NC Assets': other_nca, 'Total Assets': tot_assets,
                    'Accounts Payable': ap, 'Accrued Liab': accrued, 'Short-Term Debt': std,
                    'Other Curr Liab': other_cl, 'Total Curr Liab': tot_cl,
                    'Long-Term Debt': ltd, 'Other NC Liab': other_ncl, 'Total NC Liab': tot_ncl,
                    'Total Liab': tot_liab,
                    'Share Capital': share_cap, 'Retained Earnings': ret_earn,
                    'Other Equity': other_eq, 'Total Equity': tot_eq,
                    'Net Working Capital': nwc,
                })
                self.balance_plugs.append(plug)
                ni_cf    = g(cf, ['Net Income From Continuing Operations',
                                  'Net Income'], col)
                da_cf    = g(cf, ['Depreciation And Amortization',
                                  'Depreciation Amortization Depletion',
                                  'Depreciation'], col)
                sbc      = g(cf, ['Stock Based Compensation'], col)
                ch_ar    = g(cf, ['Change In Receivables',
                                  'Changes In Account Receivables'], col)
                ch_inv   = g(cf, ['Change In Inventory'], col)
                ch_ap    = g(cf, ['Change In Payable',
                                  'Changes In Account Payable'], col)
                ch_other = g(cf, ['Change In Other Working Capital',
                                  'Change In Other Current Assets'], col)
                ocf      = g(cf, ['Operating Cash Flow',
                                  'Total Cash From Operating Activities',
                                  'Cash Flows From Used In Operating Activities Direct'], col)
                capex    = g(cf, ['Capital Expenditure',
                                  'Purchase Of Property Plant And Equipment',
                                  'Capital Expenditures'], col)
                fcf_calc = ocf - abs(capex)
                acq      = g(cf, ['Acquisitions Net','Acquisition Of Business'], col)
                purchases_invest = g(cf, ['Purchase Of Investment',
                                          'Purchase Of Investments'], col)
                proceeds_invest  = g(cf, ['Proceeds From Sales Of Investments',
                                          'Sale And Maturity Of Investments'], col)
                icf      = g(cf, ['Investing Cash Flow',
                                  'Total Cashflows From Investing Activities',
                                  'Cash Flows From Used In Investing Activities Direct'], col)
                debt_issued = g(cf, ['Proceeds From Issuance Of Debt',
                                     'Issuance Of Debt'], col)
                debt_repaid = g(cf, ['Repayment Of Debt','Repayment Of Debt'], col)
                eq_issued   = g(cf, ['Proceeds From Issuance Of Common Stock',
                                     'Common Stock Issued'], col)
                divs_paid   = g(cf, ['Payment Of Dividends','Common Stock Dividend Paid',
                                     'Dividends Paid'], col)
                buybacks    = g(cf, ['Repurchase Of Capital Stock',
                                     'Common Stock Repurchased'], col)
                fcf_fin     = g(cf, ['Financing Cash Flow',
                                     'Total Cash From Financing Activities',
                                     'Cash Flows From Used In Financing Activities Direct'], col)
                net_cash    = g(cf, ['Changes In Cash','Net Change In Cash',
                                     'Effect Of Exchange Rate Changes'], col) or (ocf + icf + fcf_fin)
                ocf_to_npat = (ocf / npat) if npat else None
                capex_intensity = (abs(capex) / rev * 100) if rev else 0
                self.cash_flows.append({
                    'Net Income (CF)': ni_cf, 'D&A (CF)': da_cf, 'SBC': sbc,
                    'Chg Receivables': ch_ar, 'Chg Inventory': ch_inv,
                    'Chg Payables': ch_ap, 'Chg Other WC': ch_other,
                    'Operating CF': ocf, 'CapEx': -abs(capex),
                    'Free Cash Flow': fcf_calc, 'Acquisitions': -abs(acq),
                    'Purchases Invest': -abs(purchases_invest),
                    'Proceeds Invest': proceeds_invest, 'Investing CF': icf,
                    'Debt Issued': debt_issued, 'Debt Repaid': -abs(debt_repaid),
                    'Equity Issued': eq_issued, 'Dividends Paid': -abs(divs_paid),
                    'Buybacks': -abs(buybacks), 'Financing CF': fcf_fin,
                    'Net Change Cash': net_cash,
                    'OCF/NPAT Ratio': ocf_to_npat or 0,
                    'CapEx Intensity %': capex_intensity,
                })
            self._compute_ratios()
            self.data_loaded = True
            print(f"  \033[92m✔ Loaded {len(self.fiscal_years)} year(s) of data.\033[0m\n")
            return True
        except Exception as e:
            print(f"  \033[91m[!] Error: {e}\033[0m")
            traceback.print_exc()
            return False
    def _compute_ratios(self):
        if not self.fiscal_years:
            return
        i  = self.inc_stmts[0]
        b  = self.bal_sheets[0]
        cf = self.cash_flows[0]
        rev  = i['Revenue']
        npat = i['NPAT']
        ebit = i['EBIT']
        ebitda = i['EBITDA']
        ocf  = cf['Operating CF']
        fcf  = cf['Free Cash Flow']
        capex= abs(cf['CapEx'])
        tot_assets = b['Total Assets']
        tot_eq     = b['Total Equity']
        tot_liab   = b['Total Liab']
        tot_cl     = b['Total Curr Liab']
        tot_ca     = b['Total Curr Assets']
        cash       = b['Cash']
        ar         = b['Accounts Receivable']
        inv        = b['Inventory']
        ap         = b['Accounts Payable']
        ltd        = b['Long-Term Debt']
        std        = b['Short-Term Debt']
        tot_debt   = abs(ltd) + abs(std)
        net_debt   = tot_debt - cash
        current_ratio = (tot_ca / tot_cl) if tot_cl else 0
        quick_ratio   = ((tot_ca - abs(inv)) / tot_cl) if tot_cl else 0
        cash_ratio    = (cash / tot_cl) if tot_cl else 0
        ocf_to_cl     = (ocf / tot_cl) if tot_cl else 0
        roa  = (npat / tot_assets * 100) if tot_assets else 0
        roe  = (npat / tot_eq * 100) if tot_eq else 0
        roce = (ebit / (tot_assets - tot_cl) * 100) if (tot_assets - tot_cl) else 0
        roa_ocf = (ocf / tot_assets * 100) if tot_assets else 0
        debt_to_eq    = (tot_debt / tot_eq) if tot_eq else 0
        debt_to_ebitda= (net_debt / ebitda) if ebitda else 0
        interest_cov  = (ebit / abs(i['Interest Exp'])) if i['Interest Exp'] else 0
        debt_to_assets= (tot_liab / tot_assets) if tot_assets else 0
        asset_turn    = (rev / tot_assets) if tot_assets else 0
        ar_days       = (ar  / rev * 365) if rev else 0          
        inv_days      = (abs(inv) / abs(i['COGS']) * 365) if i['COGS'] else 0       
        ap_days       = (abs(ap) / abs(i['COGS']) * 365) if i['COGS'] else 0        
        ccc           = ar_days + inv_days - ap_days                               
        ocf_to_npat   = (ocf / npat) if npat else 0
        fcf_yield_eq  = (fcf / tot_eq * 100) if tot_eq else 0
        capex_to_ocf  = (capex / ocf * 100) if ocf else 0
        fcf_margin    = (fcf / rev * 100) if rev else 0
        net_margin = i['Net Margin %'] / 100
        eq_mult    = (tot_assets / tot_eq) if tot_eq else 0
        dupont_roe = net_margin * asset_turn * eq_mult * 100
        tax_burden  = (npat  / i['EBT'])  if i['EBT'] else 0
        int_burden  = (i['EBT'] / ebit)   if ebit else 0
        ebit_margin = ebit / rev          if rev else 0
        self.ratios = {
            'Current Ratio':      current_ratio,
            'Quick Ratio':        quick_ratio,
            'Cash Ratio':         cash_ratio,
            'OCF / Curr Liab':    ocf_to_cl,
            'ROA %':              roa,
            'ROE %':              roe,
            'ROCE %':             roce,
            'OCF-based ROA %':    roa_ocf,
            'Debt / Equity':      debt_to_eq,
            'Net Debt / EBITDA':  debt_to_ebitda,
            'Interest Coverage':  interest_cov,
            'Debt / Assets':      debt_to_assets,
            'Asset Turnover':     asset_turn,
            'Days Sales Outstand':ar_days,
            'Days Inv Outstand':  inv_days,
            'Days Payable Outst': ap_days,
            'Cash Conv Cycle':    ccc,
            'OCF / NPAT':         ocf_to_npat,
            'FCF Margin %':       fcf_margin,
            'FCF Yield on Equity':fcf_yield_eq,
            'CapEx / OCF %':      capex_to_ocf,
        }
        self.dupont = {
            'Tax Burden':         tax_burden,
            'Interest Burden':    int_burden,
            'EBIT Margin':        ebit_margin,
            'Asset Turnover':     asset_turn,
            'Equity Multiplier':  eq_mult,
            'DuPont ROE %':       dupont_roe,
        }
        self.wc_metrics = {
            'Net Working Capital': b['Net Working Capital'],
            'Current Ratio':       current_ratio,
            'Quick Ratio':         quick_ratio,
            'DSO (days)':          ar_days,
            'DIO (days)':          inv_days,
            'DPO (days)':          ap_days,
            'CCC (days)':          ccc,
            'Accounts Receivable': ar,
            'Inventory':           abs(inv),
            'Accounts Payable':    abs(ap),
        }
        accruals    = npat - ocf                                                         
        accrual_rat = (accruals / abs(npat) * 100) if npat else 0
        sbc_to_ocf  = (abs(cf['SBC']) / ocf * 100) if ocf else 0
        da_to_rev   = (abs(cf['D&A (CF)']) / rev * 100) if rev else 0
        self.qoe = {
            'OCF / NPAT':         ocf_to_npat,
            'Accruals (NPAT-OCF)':accruals,
            'Accrual Ratio %':    accrual_rat,
            'SBC / OCF %':        sbc_to_ocf,
            'D&A / Revenue %':    da_to_rev,
            'FCF / NPAT':         (fcf / npat) if npat else 0,
        }
    def _colors(self):
        return ('\033[1m','\033[96m','\033[92m','\033[93m',
                '\033[91m','\033[95m','\033[0m','\033[90m')
    def _year_label(self, idx):
        try:
            return self.fiscal_years[idx].strftime('%b %Y')
        except Exception:
            return f"YR-{idx}"
