    def print_trend_table(self):
        B,C,G,Y,R,M,RES,DIM = self._colors()
        n = len(self.fiscal_years)
        yr_labels = [self._year_label(i) for i in range(n)]
        def row(label, key, src_list, color=None, unit="auto"):
            vals = []
            for idx, d in enumerate(src_list):
                v = d.get(key, 0)
                vals.append(v)
            line = f"  {label:<32}"
            for idx, v in enumerate(vals):
                col = color or (G if v >= 0 else R)
                line += f"  {col}{self.fmt(v, unit):>14}{RES}"
            if n >= 2 and vals[1] != 0:
                chg = self.pct_change(vals[0], vals[1])
                arrow = "▲" if chg and chg >= 0 else "▼"
                chg_col = G if chg and chg >= 0 else R
                line += f"   {chg_col}{arrow}{abs(chg or 0):>5.1f}%{RES}"
            print(line)
        header_line = f"  {'Metric':<32}" + "".join(f"  {B}{l:>14}{RES}" for l in yr_labels) + f"   {B}{'YoY Δ':>7}{RES}"
        sep = "  " + "─"*90
        print(f"\n  {B}{C}MULTI-YEAR TREND ANALYSIS — {self.ticker}{RES}")
        print(sep)
        print(header_line)
        print(sep)
        print(f"\n  {B}{Y}── INCOME STATEMENT ──{RES}")
        row("Revenue",        'Revenue',     self.inc_stmts, G)
        row("Gross Profit",   'Gross Profit',self.inc_stmts, G)
        row("EBIT",           'EBIT',        self.inc_stmts, G)
        row("EBITDA",         'EBITDA',      self.inc_stmts, G)
        row("NPAT",           'NPAT',        self.inc_stmts, Y)
        row("GP Margin %",    'GP Margin %', self.inc_stmts, C, "%")
        row("EBIT Margin %",  'EBIT Margin %',self.inc_stmts,C, "%")
        row("Net Margin %",   'Net Margin %',self.inc_stmts, C, "%")
        print(f"\n  {B}{Y}── CASH FLOW ──{RES}")
        row("Operating CF",   'Operating CF',  self.cash_flows, G)
        row("CapEx",          'CapEx',          self.cash_flows, R)
        row("Free Cash Flow", 'Free Cash Flow', self.cash_flows, Y)
        row("Financing CF",   'Financing CF',   self.cash_flows)
        print(f"\n  {B}{Y}── BALANCE SHEET ──{RES}")
        row("Total Assets",   'Total Assets',  self.bal_sheets, G)
        row("Total Equity",   'Total Equity',  self.bal_sheets, G)
        row("Long-Term Debt", 'Long-Term Debt', self.bal_sheets, R)
        row("Net Working Cap",'Net Working Capital',self.bal_sheets, Y)
        print(sep)
    def print_ratio_dashboard(self):
        B,C,G,Y,R,M,RES,DIM = self._colors()
        ra = self.ratios
        def rrow(label, key, unit="x", good_hi=True, threshold=None):
            v = ra.get(key, 0)
            if unit == "%":     fs = self.fmt(v, "%")
            elif unit == "days":fs = self.fmt(v, "days")
            else:               fs = self.fmt(v, "x")
            if threshold is not None:
                col = G if (v >= threshold) == good_hi else R
            else:
                col = C
            print(f"  {label:<36}  {col}{fs:>12}{RES}")
        print(f"\n  {B}{C}ADVANCED RATIO DASHBOARD — {self.ticker}{RES}")
        print("  " + "═"*60)
        print(f"\n  {B}{Y}  LIQUIDITY{RES}                                    {DIM}(Higher = more liquid){RES}")
        rrow("Current Ratio",         'Current Ratio',   threshold=1.5)
        rrow("Quick Ratio",           'Quick Ratio',     threshold=1.0)
        rrow("Cash Ratio",            'Cash Ratio',      threshold=0.2)
        rrow("OCF / Current Liab.",   'OCF / Curr Liab', threshold=0.4)
        print(f"\n  {B}{Y}  PROFITABILITY{RES}                                 {DIM}(Higher = more profitable){RES}")
        rrow("Return on Assets %",    'ROA %',           "%", threshold=5)
        rrow("Return on Equity %",    'ROE %',           "%", threshold=10)
        rrow("ROCE %",                'ROCE %',          "%", threshold=10)
        rrow("OCF-Based ROA %",       'OCF-based ROA %', "%", threshold=5)
        print(f"\n  {B}{Y}  LEVERAGE & SOLVENCY{RES}                          {DIM}(Lower Debt = less risk){RES}")
        rrow("Debt / Equity",         'Debt / Equity',   threshold=1.0, good_hi=False)
        rrow("Net Debt / EBITDA",     'Net Debt / EBITDA', threshold=3.0, good_hi=False)
        rrow("Interest Coverage",     'Interest Coverage', threshold=3.0)
        rrow("Total Debt / Assets",   'Debt / Assets',   threshold=0.6, good_hi=False)
        print(f"\n  {B}{Y}  EFFICIENCY / ACTIVITY{RES}                        {DIM}(Operational speed){RES}")
        rrow("Asset Turnover",        'Asset Turnover',   threshold=0.5)
        rrow("Days Sales Outstanding","Days Sales Outstand","days", threshold=60, good_hi=False)
        rrow("Days Inventory Outst.", "Days Inv Outstand", "days", threshold=90, good_hi=False)
        rrow("Days Payable Outst.",   "Days Payable Outst","days", threshold=30)
        rrow("Cash Conversion Cycle", "Cash Conv Cycle",  "days", threshold=60, good_hi=False)
        print(f"\n  {B}{Y}  CASH FLOW QUALITY{RES}                            {DIM}(Earnings reliability){RES}")
        rrow("OCF / NPAT (>1 = good)","OCF / NPAT",      threshold=1.0)
        rrow("FCF Margin %",          "FCF Margin %",     "%", threshold=5)
        rrow("FCF Yield on Equity %", "FCF Yield on Equity","%",threshold=8)
        rrow("CapEx / OCF %",         "CapEx / OCF %",    "%", threshold=80, good_hi=False)
        print("  " + "═"*60)
    def print_dupont(self):
        B,C,G,Y,R,M,RES,DIM = self._colors()
        d  = self.dupont
        i0 = self.inc_stmts[0]
        print(f"\n  {B}{C}DU PONT 5-FACTOR ROE DECOMPOSITION — {self.ticker}{RES}")
        print(f"  {DIM}ROE = Tax Burden × Interest Burden × EBIT Margin × Asset Turnover × Equity Multiplier{RES}")
        print("  " + "═"*72)
        print(f"\n  {'Factor':<30}  {'Value':>12}  {'Description'}")
        print("  " + "─"*72)
        factors = [
            ('Tax Burden',       'd',  'NPAT / EBT   — % of pre-tax profit kept after tax'),
            ('Interest Burden',  'd',  'EBT  / EBIT  — % of EBIT kept after interest cost'),
            ('EBIT Margin',      'd',  'EBIT / Rev   — operational profitability'),
            ('Asset Turnover',   'x',  'Rev  / Assets — efficiency of asset deployment'),
            ('Equity Multiplier','x',  'Assets / Equity — financial leverage used'),
        ]
        for k, unit, desc in factors:
            v = d.get(k, 0)
            fs = f"{v:.3f}x" if unit == 'x' else f"{v:.3f}"
            print(f"  {k:<30}  {G}{fs:>12}{RES}  {DIM}{desc}{RES}")
        print("  " + "─"*72)
        print(f"  {'DuPont ROE':<30}  {Y}{d.get('DuPont ROE %', 0):>11.2f}%{RES}")
        print(f"  {DIM}(Verify: all five factors multiplied together × 100){RES}")
        taxb = d.get('Tax Burden', 1)
        intb = d.get('Interest Burden', 1)
        ebitm= d.get('EBIT Margin', 0)
        at   = d.get('Asset Turnover', 0)
        em   = d.get('Equity Multiplier', 0)
        roe  = d.get('DuPont ROE %', 0)
        print(f"\n  {B}Interpretation:{RES}")
        print(f"    {G}▸{RES} Leverage (Equity Multiplier):  {em:.2f}x — amplifies returns by {em:.2f}× equity")
        print(f"    {G}▸{RES} Operations (EBIT Margin):       {ebitm*100:.1f}% of revenue reaches EBIT")
        print(f"    {G}▸{RES} Tax drag (Tax Burden):          {taxb*100:.1f}% of pre-tax income survives tax")
        print(f"    {G}▸{RES} Financing drag (Int. Burden):   {intb*100:.1f}% of EBIT survives interest expense")
        print(f"    {G}▸{RES} Capital efficiency (Asset Turn): {at:.2f}x — revenue per dollar of assets")
    def print_working_capital(self):
        B,C,G,Y,R,M,RES,DIM = self._colors()
        w  = self.wc_metrics
        b0 = self.bal_sheets[0]
        c0 = self.cash_flows[0]
        print(f"\n  {B}{C}WORKING CAPITAL & CASH CONVERSION CYCLE — {self.ticker}{RES}")
        print(f"  {DIM}The operating cycle: Inventory → Receivables → Cash{RES}")
        print("  " + "═"*70)
        dso = w['DSO (days)']
        dio = w['DIO (days)']
        dpo = w['DPO (days)']
        ccc = w['CCC (days)']
        total_span = max(int(dso + dio), 1)
        scale = 40 / total_span
        dio_bar = int(dio * scale)
        dso_bar = int(dso * scale)
        dpo_bar = int(dpo * scale)
        ccc_bar = max(int(ccc * scale), 0)
        print(f"\n  {B}Operating Cycle Timeline:{RES}")
        print(f"  {M}{'─'*dio_bar}{RES}{Y}{'─'*dso_bar}{RES}  ← {G}{total_span:.0f} days total operating cycle{RES}")
        print(f"  {M}◀── Inventory Days ({dio:.0f}d) ──▶{RES}{Y}◀── DSO ({dso:.0f}d) ──▶{RES}")
        print(f"  {R}◀── DPO ({dpo:.0f}d, supplier funding) ─────────▶{RES}")
