import os, json, time, threading, textwrap
@dataclass
class OFSignal:
    type       : str
    bar_idx    : int
    bar_time   : str
    price      : float
    direction  : str
    confidence : int
    detail     : str
_SIGNAL_TYPES = {
    "ABSORPTION"    : "Sellers/buyers absorbed at key level",
    "EXHAUSTION"    : "Buying/selling exhausted, reversal likely",
    "DIVERGENCE"    : "Price/delta divergence — weak move",
    "SWEEP"         : "Liquidity sweep below/above swing",
    "IMBALANCE"     : "Stacked bid/ask imbalance",
    "LARGE_LOT"     : "Abnormal volume bar — institutional activity",
    "VWAP_REJECT"   : "Price rejected at VWAP or band",
    "HVN_ACCEPT"    : "Price accepted at high-volume node",
    "LVN_REJECT"    : "Price rejected at low-volume node (fast move likely)",
}
class OrderFlowEngine:
    def __init__(self, ticker: str):
        self.ticker   = ticker.upper().strip()
        self.period   = "1d"
        self.interval = "5m"
        self.df       = None
        self.signals  : list[OFSignal] = []
        self.profile  : dict           = {}                        
        self.session  : dict           = {}                          
        self._or_key  : str = ""
        self._or_model: str = _GLOBAL_OR_MODEL
        self._load_or_config()
    def _load_or_config(self):
        self._or_key   = _GLOBAL_OR_KEY
        self._or_model = _GLOBAL_OR_MODEL
    def _save_or_config(self):
        try:
            pass                                            
        except: pass
    def fetch_data(self) -> bool:
        from rich.console import Console
        console = Console()
        fallbacks = [self.interval, "5m", "15m", "1h"]
        for iv in fallbacks:
            try:
                console.print(
                    f"  [dim]Fetching {self.ticker} ({self.period}, {iv})…[/]",
                    end="\r"
                )
                stock  = yf.Ticker(self.ticker)
                df     = stock.history(period=self.period, interval=iv)
                if not df.empty:
                    self.interval = iv
                    self.df       = df.copy()
                    break
            except Exception as e:
                console.print(f"  [dim]{iv} failed: {e}[/]")
        else:
            console.print(
                f"  [bold red]✗ No intraday data available for {self.ticker}.[/]"
            )
            return False
        console.print(
            f"  [green]✓[/] {len(self.df)} bars loaded "
            f"([bold]{self.interval}[/] interval)"
        )
        self._process_all()
        return True
    def _process_all(self):
        self._process_footprint()
        self._process_vwap()
        self._process_volume_profile()
        self._detect_signals()
        self._build_session_summary()
    def _process_footprint(self):
        df = self.df
        rng = (df['High'] - df['Low']).replace(0, 0.0001)
        ask_pct         = (df['Close'] - df['Low']) / rng
        df['Ask_Vol']   = df['Volume'] * ask_pct
        df['Bid_Vol']   = df['Volume'] * (1 - ask_pct)
        df['Delta']     = df['Ask_Vol'] - df['Bid_Vol']
        df['Cum_Delta'] = df['Delta'].cumsum()
        df['Ask_Pct']   = ask_pct * 100                                
        avg_vol            = df['Volume'].mean()
        df['Vol_Ratio']    = df['Volume'] / avg_vol.clip(0.0001)
        df['Imbalance']    = (df['Ask_Vol'] / df['Bid_Vol'].replace(0,0.0001)).clip(0,10)
        price_chg          = df['Close'].diff()
        df['Div_Score']    = price_chg.rolling(5).corr(df['Delta'])
        bid_dom            = (df['Imbalance'] > 3).astype(int)
        ask_dom            = (df['Imbalance'] < 0.33).astype(int)
        df['Stack_Bull']   = bid_dom.rolling(3).sum() == 3
        df['Stack_Bear']   = ask_dom.rolling(3).sum() == 3
        df['Signal']       = ""
        df['Sig_Dir']      = ""                                          
        self.df = df
    def _process_vwap(self):
        df = self.df
        tp             = (df['High'] + df['Low'] + df['Close']) / 3
        cum_tp_vol     = (tp * df['Volume']).cumsum()
        cum_vol        = df['Volume'].cumsum().replace(0, 0.0001)
        df['VWAP']     = cum_tp_vol / cum_vol
        sq_diff        = ((tp - df['VWAP']) ** 2) * df['Volume']
        cum_sq_diff    = sq_diff.cumsum()
        variance       = cum_sq_diff / cum_vol
        std            = variance.clip(0).apply(np.sqrt)
        df['VWAP_1U']  = df['VWAP'] + std
        df['VWAP_1D']  = df['VWAP'] - std
        df['VWAP_2U']  = df['VWAP'] + 2 * std
        df['VWAP_2D']  = df['VWAP'] - 2 * std
        self.df = df
    def _process_volume_profile(self, n_bins: int = 24):
        df        = self.df
        min_p     = df['Low'].min()
        max_p     = df['High'].max()
        bins      = np.linspace(min_p, max_p, n_bins + 1)
        mids      = [(bins[i] + bins[i+1])/2 for i in range(n_bins)]
        bid_prof  = np.zeros(n_bins)
        ask_prof  = np.zeros(n_bins)
        tot_prof  = np.zeros(n_bins)
        for _, row in df.iterrows():
            idx = int(np.clip(
                (np.abs(np.array(mids) - row['Close'])).argmin(),
                0, n_bins - 1
            ))
            bid_prof[idx] += row['Bid_Vol']
            ask_prof[idx] += row['Ask_Vol']
            tot_prof[idx] += row['Volume']
        poc_idx   = int(tot_prof.argmax())
        poc_price = mids[poc_idx]
        total_vol = tot_prof.sum()
        target    = total_vol * 0.70
        included  = {poc_idx}
        acc_vol   = tot_prof[poc_idx]
        above = poc_idx + 1
        below = poc_idx - 1
        while acc_vol < target:
            above_v = tot_prof[above] if above < n_bins else 0
            below_v = tot_prof[below] if below >= 0     else 0
            if above_v == 0 and below_v == 0: break
            if above_v >= below_v and above < n_bins:
                included.add(above); acc_vol += above_v; above += 1
            elif below >= 0:
                included.add(below); acc_vol += below_v; below -= 1
            else:
                included.add(above); acc_vol += above_v; above += 1
        vah = mids[max(included)]
        val = mids[min(included)]
        mean_vol  = tot_prof.mean()
        hvn_idx   = [i for i in range(n_bins) if tot_prof[i] > mean_vol * 1.5]
        lvn_idx   = [i for i in range(n_bins) if tot_prof[i] < mean_vol * 0.5]
        sp_idx    = [i for i in range(n_bins) if tot_prof[i] < mean_vol * 0.20]
        self.profile = {
            'bins'    : bins,
            'mids'    : mids,
            'bid'     : bid_prof,
            'ask'     : ask_prof,
            'total'   : tot_prof,
            'poc_idx' : poc_idx,
            'poc_price': poc_price,
            'vah'     : vah,
            'val'     : val,
            'hvn'     : [mids[i] for i in hvn_idx],
            'lvn'     : [mids[i] for i in lvn_idx],
            'singles' : [mids[i] for i in sp_idx],
            'n_bins'  : n_bins,
        }
    def _detect_signals(self):
        df  = self.df
        sig = []
        avg_delta  = df['Delta'].abs().mean()
        avg_vol    = df['Volume'].mean()
        poc        = self.profile.get('poc_price', 0)
        vah        = self.profile.get('vah', 0)
        val        = self.profile.get('val', 0)
        def _near_level(price, level, tol=0.003):
            return abs(price - level) / max(level, 0.01) < tol
        def _level_conf(price):
            return 1 if (
                _near_level(price, poc) or
                _near_level(price, vah) or
                _near_level(price, val)
            ) else 0
        for i in range(2, len(df)):
            row      = df.iloc[i]
            prev     = df.iloc[i-1]
            prev2    = df.iloc[i-2]
            time_str = df.index[i].strftime('%H:%M')
            price    = row['Close']
            conf     = 1 + _level_conf(price)
            if prev['Delta'] < -avg_delta * 1.2 and price > prev['Close']:
                conf2 = min(3, conf + (1 if row['Div_Score'] is not None and
                                       row['Div_Score'] < -0.3 else 0))
                sig.append(OFSignal(
                    type="ABSORPTION", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bullish", confidence=conf2,
                    detail=f"Δ={prev['Delta']:+,.0f} selling absorbed; "
                           f"price held {prev['Close']:.2f}→{price:.2f}"
                ))
                df.iat[i, df.columns.get_loc('Signal')] = "🟢 BUY: Sellers Absorbed"
                df.iat[i, df.columns.get_loc('Sig_Dir')] = "Bullish"
            elif prev['Delta'] > avg_delta * 1.2 and price < prev['Close']:
                conf2 = min(3, conf + (1 if row['Div_Score'] is not None and
                                       row['Div_Score'] < -0.3 else 0))
                sig.append(OFSignal(
                    type="EXHAUSTION", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bearish", confidence=conf2,
                    detail=f"Δ={prev['Delta']:+,.0f} buying failed; "
                           f"price fell {prev['Close']:.2f}→{price:.2f}"
                ))
                df.iat[i, df.columns.get_loc('Signal')] = "🔴 SELL: Buyers Exhausted"
                df.iat[i, df.columns.get_loc('Sig_Dir')] = "Bearish"
            if row['Div_Score'] is not None and row['Div_Score'] < -0.5:
                d = row['Cum_Delta'] - df.iloc[max(0,i-5)]['Cum_Delta']
                direction = "Bearish" if d > 0 else "Bullish"
                sig.append(OFSignal(
                    type="DIVERGENCE", bar_idx=i, bar_time=time_str,
                    price=price, direction=direction, confidence=2,
                    detail=f"5-bar price/delta corr={row['Div_Score']:.2f} "
                           f"(CVD {'rising' if d>0 else 'falling'} while price "
                           f"{'falling' if d>0 else 'rising'})"
                ))
            if (row['Low'] < prev['Low'] and row['Close'] > prev['Low']):
                sig.append(OFSignal(
                    type="SWEEP", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bullish", confidence=min(3, conf+1),
                    detail=f"Low swept to {row['Low']:.2f}, closed back above "
                           f"prev low {prev['Low']:.2f} — stop hunt"
                ))
            elif (row['High'] > prev['High'] and row['Close'] < prev['High']):
                sig.append(OFSignal(
                    type="SWEEP", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bearish", confidence=min(3, conf+1),
                    detail=f"High swept to {row['High']:.2f}, closed back below "
                           f"prev high {prev['High']:.2f} — stop hunt"
                ))
            if row.get('Stack_Bull', False):
                sig.append(OFSignal(
                    type="IMBALANCE", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bullish", confidence=2,
                    detail="3+ consecutive bid-dominated bars (Ask/Bid>3)"
                ))
            elif row.get('Stack_Bear', False):
                sig.append(OFSignal(
                    type="IMBALANCE", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bearish", confidence=2,
                    detail="3+ consecutive ask-dominated bars (Bid/Ask>3)"
                ))
            if row['Vol_Ratio'] > 2.5:
                direction = "Bullish" if row['Delta'] > 0 else "Bearish"
                sig.append(OFSignal(
                    type="LARGE_LOT", bar_idx=i, bar_time=time_str,
                    price=price, direction=direction, confidence=min(3,conf+1),
                    detail=f"Volume {row['Vol_Ratio']:.1f}× average "
                           f"({row['Volume']:,.0f} vs avg {avg_vol:,.0f}), "
                           f"Δ={row['Delta']:+,.0f}"
                ))
            vwap = row.get('VWAP', 0)
            v1u  = row.get('VWAP_1U', 0)
            v1d  = row.get('VWAP_1D', 0)
            v2u  = row.get('VWAP_2U', 0)
            v2d  = row.get('VWAP_2D', 0)
            if (row['High'] > v2u and row['Close'] < v2u):
                sig.append(OFSignal(
                    type="VWAP_REJECT", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bearish", confidence=2,
                    detail=f"Rejected at VWAP +2σ ({v2u:.2f})"
                ))
            elif (row['Low'] < v2d and row['Close'] > v2d):
                sig.append(OFSignal(
                    type="VWAP_REJECT", bar_idx=i, bar_time=time_str,
                    price=price, direction="Bullish", confidence=2,
                    detail=f"Rejected at VWAP −2σ ({v2d:.2f})"
                ))
        last   = df.iloc[-1]
        lp     = last['Close']
        for hvn in self.profile.get('hvn', []):
            if _near_level(lp, hvn):
                sig.append(OFSignal(
                    type="HVN_ACCEPT", bar_idx=len(df)-1,
                    bar_time=df.index[-1].strftime('%H:%M'),
                    price=lp, direction="Neutral", confidence=2,
                    detail=f"Price at HVN {hvn:.2f} — expect consolidation "
                           f"or strong support/resistance"
                ))
        self.signals = sig
        self.df = df
    def _build_session_summary(self):
        df  = self.df
        p   = self.profile
        total_vol  = df['Volume'].sum()
        total_delta= df['Delta'].sum()
        bull_bars  = (df['Delta'] > 0).sum()
        bear_bars  = (df['Delta'] < 0).sum()
        high_delta = df['Delta'].max()
        low_delta  = df['Delta'].min()
        current    = df['Close'].iloc[-1]
        vwap       = df['VWAP'].iloc[-1]
        open_p     = df['Open'].iloc[0]
        self.session = {
            'ticker'       : self.ticker,
            'interval'     : self.interval,
            'bars'         : len(df),
            'open'         : open_p,
            'current'      : current,
            'high'         : df['High'].max(),
            'low'          : df['Low'].min(),
            'vwap'         : vwap,
            'vwap_1u'      : df['VWAP_1U'].iloc[-1],
            'vwap_1d'      : df['VWAP_1D'].iloc[-1],
            'vwap_2u'      : df['VWAP_2U'].iloc[-1],
            'vwap_2d'      : df['VWAP_2D'].iloc[-1],
            'total_vol'    : total_vol,
            'total_delta'  : total_delta,
            'bull_bars'    : bull_bars,
            'bear_bars'    : bear_bars,
            'delta_bias'   : 'Bullish' if total_delta>0 else 'Bearish',
            'high_delta'   : high_delta,
            'low_delta'    : low_delta,
            'poc'          : p.get('poc_price',0),
            'vah'          : p.get('vah',0),
            'val'          : p.get('val',0),
            'above_vwap'   : current > vwap,
            'n_hvn'        : len(p.get('hvn',[])),
            'n_lvn'        : len(p.get('lvn',[])),
            'n_singles'    : len(p.get('singles',[])),
            'signal_count' : len(self.signals),
            'bull_signals' : sum(1 for s in self.signals if s.direction=="Bullish"),
            'bear_signals' : sum(1 for s in self.signals if s.direction=="Bearish"),
            'high_conf_sig': sum(1 for s in self.signals if s.confidence==3),
        }
    def _show_session_header(self, console) -> None:
        from rich.panel  import Panel
        from rich.table  import Table
        from rich        import box as _box
        s    = self.session
        cur  = s['current']
        vwap = s['vwap']
        poc  = s['poc']
        vc   = "green" if s['above_vwap'] else "red"
        dc   = "green" if s['total_delta']>0 else "red"
        is_india = ".NS" in self.ticker or ".BO" in self.ticker
        cur_sym  = "₹" if is_india else "$"
        tbl = Table(box=_box.SIMPLE, show_header=False, expand=False)
        tbl.add_column("K", style="dim", width=22)
        tbl.add_column("V", width=18)
        tbl.add_column("K2", style="dim", width=22)
        tbl.add_column("V2", width=18)
        tbl.add_row(
            "Price", f"[bold]{cur_sym}{cur:,.2f}[/]",
            "vs VWAP", f"[{vc}]{'↑' if s['above_vwap'] else '↓'} {cur_sym}{vwap:,.2f}[/{vc}]"
        )
        tbl.add_row(
            "Session Δ", f"[{dc}]{s['total_delta']:+,.0f}[/{dc}]",
            "Δ Bias", f"[{dc}]{s['delta_bias']}[/{dc}]"
        )
        tbl.add_row(
            "POC", f"{cur_sym}{poc:,.2f}",
            "VA", f"{cur_sym}{s['val']:,.2f} – {cur_sym}{s['vah']:,.2f}"
        )
        tbl.add_row(
            "Bull Bars", f"[green]{s['bull_bars']}[/]",
            "Bear Bars", f"[red]{s['bear_bars']}[/]"
        )
        tbl.add_row(
            "Volume", f"{s['total_vol']:,.0f}",
            "Signals", f"[bold]{s['signal_count']}[/] "
                       f"([green]{s['bull_signals']}↑[/] "
                       f"[red]{s['bear_signals']}↓[/])"
        )
        console.print(Panel(
            tbl,
            title=f"[bold white]Session Summary — {self.ticker} ({self.interval})[/]",
            border_style="blue",
        ))
