            imbal     = row['Imbalance']
            ic        = "green" if imbal>2 else ("red" if imbal<0.5 else "white")
            sig_text  = row['Signal'] if row['Signal'] else ""
            sig_dc    = row.get('Sig_Dir','')
            sig_clr   = "green" if sig_dc=="Bullish" else ("red" if sig_dc=="Bearish" else "white")
