    def show_volume_profile(self) -> None:
        from rich.console import Console
        from rich.table   import Table
        from rich         import box
        console = Console()
        self._show_session_header(console)
        p    = self.profile
        mids = p['mids']
        bid  = p['bid']
        ask  = p['ask']
        tot  = p['total']
        poc  = p['poc_idx']
        vah  = p['vah']
        val  = p['val']
        hvns = set(p['hvn'])
        lvns = set(p['lvn'])
        sps  = set(p['singles'])
        mx   = max(tot) if max(tot) > 0 else 1
        is_india = ".NS" in self.ticker or ".BO" in self.ticker
        cur_sym  = "₹" if is_india else "$"
        tbl = Table(
            title=f"[bold magenta]📊 VOLUME PROFILE + DOM — {self.ticker}[/]",
            caption=("[dim]POC=Point of Control | VA=Value Area | "
                     "HVN=High Vol Node | LVN=Low Vol Node | SP=Single Print[/]"),
            box=box.SIMPLE_HEAD, header_style="bold white", show_lines=False
        )
        tbl.add_column("Label",      width=6,  justify="center")
        tbl.add_column("Bid (Sell)", width=26, justify="right", style="red")
        tbl.add_column("Price",      width=16, justify="center")
        tbl.add_column("Ask (Buy)",  width=26, justify="left",  style="green")
        tbl.add_column("LvlΔ",       width=10, justify="right")
        for i in range(len(mids)-1, -1, -1):
            price    = mids[i]
            bid_v    = bid[i]
            ask_v    = ask[i]
            delta    = ask_v - bid_v
            dc       = "green" if delta>0 else "red"
            bar_w    = 22
            bid_bar  = "█" * int((bid_v / mx) * bar_w)
            ask_bar  = "█" * int((ask_v / mx) * bar_w)
            p_str    = f"{cur_sym}{price:,.2f}"
            label    = ""
            if i == poc:
                p_str = f"[bold black on yellow] {p_str} [/]"
                label = "[bold yellow]POC[/]"
            elif abs(price - vah) < (mids[1]-mids[0]) * 0.6:
                p_str = f"[bold white]{p_str}[/]"
                label = "[white]VAH[/]"
            elif abs(price - val) < (mids[1]-mids[0]) * 0.6:
                p_str = f"[bold white]{p_str}[/]"
                label = "[white]VAL[/]"
            for hvn in hvns:
                if abs(price - hvn) < (mids[1]-mids[0]) * 0.6:
                    label = "[cyan]HVN[/]"
            for lvn in lvns:
                if abs(price - lvn) < (mids[1]-mids[0]) * 0.6:
                    label = "[dim]LVN[/]"
            for sp in sps:
                if abs(price - sp) < (mids[1]-mids[0]) * 0.6:
                    label = "[dim]SP[/]"
            in_va = val <= price <= vah
            bid_str = (f"[dim]{bid_v:,.0f}[/] " if in_va else f"{bid_v:,.0f} ") + f"[red]{bid_bar}[/red]"
            ask_str = f"[green]{ask_bar}[/green] " + (f"[dim]{ask_v:,.0f}[/]" if in_va else f"{ask_v:,.0f}")
            tbl.add_row(
                label,
                bid_str,
                p_str,
                ask_str,
                f"[{dc}]{delta:+,.0f}[/{dc}]"
            )
        console.print(tbl)
        console.print(
            f"  [bold]Value Area:[/] {cur_sym}{val:,.2f} – {cur_sym}{vah:,.2f}   "
            f"[bold]POC:[/] {cur_sym}{p['poc_price']:,.2f}   "
            f"[dim]HVN×{len(hvns)}  LVN×{len(lvns)}  SP×{len(sps)}[/]"
        )
