class RiskReturnAnalyzer:
    def __init__(self):
        self.tickers = []
        self.results = []
    def _check_dependencies(self):
        try:
            return True
        except ImportError:
            import sys, subprocess
            print("  \033[93m[!] Missing libraries. Installing numpy, matplotlib, yfinance, pandas...\033[0m")
            try:
                subprocess.check_call([sys.executable, "-m", "pip", "install", "numpy", "matplotlib", "yfinance", "pandas"])
                print("  \033[92m[✓] Libraries installed successfully. Please restart the module.\033[0m")
            except:
                print("  \033[91m[!] Failed to install dependencies automatically.\033[0m")
            return False
    def fetch_and_calculate(self, ticker_string):
        B, C, G, Y, R, M, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[95m', '\033[0m'
        raw_tickers = ticker_string.replace(' ', '').split(',')
        self.tickers = [t.upper() for t in raw_tickers if t]
        if not self.tickers:
            print(f"  {R}[!] No valid tickers provided.{RES}")
            return False
        print(f"\n  {C}Downloading 1-Year Data & Calculating Metrics...{RES}")
        self.results = []
        for ticker in self.tickers:
            try:
                data = yf.Ticker(ticker).history(period="1y")
                if data.empty:
                    print(f"  {Y}[!] No data found for {ticker}. Skipping.{RES}")
                    continue
                close_prices = data['Close']
                daily_returns = close_prices.pct_change().dropna()
                if daily_returns.empty:
                    print(f"  {Y}[!] Insufficient return data for {ticker}. Skipping.{RES}")
                    continue
                annual_return = daily_returns.mean() * 252
                annual_volatility = daily_returns.std() * np.sqrt(252)
                sharpe_ratio = annual_return / annual_volatility if annual_volatility != 0 else 0
                self.results.append({
                    'ticker': ticker,
                    'return': annual_return,
                    'risk': annual_volatility,
                    'sharpe': sharpe_ratio
                })
                print(f"  {G}[✓]{RES} Processed {B}{ticker:<10}{RES}")
            except Exception as e:
                print(f"  {R}[!] Error processing {ticker}: {e}{RES}")
        return len(self.results) > 0
    def print_terminal_table(self):
        B, C, G, Y, R, M, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[95m', '\033[0m'
        print(f"\n  {B}═══ RISK/RETURN MATRIX (ANNUALIZED) ═══{RES}")
        print(f"  {B}{'TICKER':<12} │ {'RETURN':>10} │ {'RISK (VOL)':>12} │ {'SHARPE RATIO':>14}{RES}")
        print("  " + "═" * 55)
        sorted_results = sorted(self.results, key=lambda x: x['sharpe'], reverse=True)
        for res in sorted_results:
            t = res['ticker']
            ret = res['return'] * 100
            risk = res['risk'] * 100
            sharpe = res['sharpe']
            ret_color = G if ret >= 0 else R
            sharpe_color = G if sharpe >= 1.0 else (Y if sharpe >= 0 else R)
            print(f"  {B}{t:<12}{RES} │ {ret_color}{ret:>9.2f}%{RES} │ {Y}{risk:>11.2f}%{RES} │ {sharpe_color}{sharpe:>14.2f}{RES}")
        print("  " + "═" * 55)
    def render_matplotlib_chart(self):
        B, C, G, Y, R, M, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[95m', '\033[0m'
        print(f"\n  {G}Launching Graphical Interface... (Close the window to return to terminal){RES}")
        tickers = [r['ticker'] for r in self.results]
        returns = [r['return'] * 100 for r in self.results]                         
        risks = [r['risk'] * 100 for r in self.results]                             
        sharpes = [r['sharpe'] for r in self.results]
        median_return = np.median(returns) if returns else 0
        median_risk = np.median(risks) if risks else 0
        plt.style.use('dark_background')
        fig, ax = plt.subplots(figsize=(10, 7))
        fig.canvas.manager.set_window_title('Quantitative Risk vs Return Analyzer')
        scatter = ax.scatter(risks, returns, c=sharpes, cmap='RdYlGn', s=100, edgecolors='white', linewidth=0.5, zorder=3)
        cbar = plt.colorbar(scatter)
        cbar.set_label('Sharpe Ratio (Return per unit of Risk)')
        for i, txt in enumerate(tickers):
            ax.annotate(txt, (risks[i], returns[i]), xytext=(5, 5), textcoords='offset points', 
                        fontsize=9, color='white', fontweight='bold', zorder=4)
        ax.axhline(median_return, color='gray', linestyle='--', alpha=0.5, zorder=1)
        ax.axvline(median_risk, color='gray', linestyle='--', alpha=0.5, zorder=1)
        if len(self.results) > 1:
            ax.text(min(risks), max(returns), 'High Return\nLow Risk', color='#00FFC6', alpha=0.6, fontsize=10, va='top', ha='left')
            ax.text(max(risks), max(returns), 'High Return\nHigh Risk', color='#FFD700', alpha=0.6, fontsize=10, va='top', ha='right')
            ax.text(min(risks), min(returns), 'Low Return\nLow Risk', color='#FF8C00', alpha=0.6, fontsize=10, va='bottom', ha='left')
            ax.text(max(risks), min(returns), 'Low Return\nHigh Risk', color='#FF3333', alpha=0.6, fontsize=10, va='bottom', ha='right')
        ax.set_title('Risk vs Return (1-Year Annualized)', fontsize=14, fontweight='bold', pad=15)
        ax.set_xlabel('Risk (Annualized Volatility %)', fontsize=11)
        ax.set_ylabel('Return (Annualized Return %)', fontsize=11)
        ax.grid(True, linestyle=':', alpha=0.3, zorder=0)
        plt.tight_layout()
        plt.show()
    def interactive_menu(self):
        if not self._check_dependencies(): return
        B, C, G, Y, R, M, RES = '\033[1m', '\033[96m', '\033[92m', '\033[93m', '\033[91m', '\033[95m', '\033[0m'
        BLUE_BG = '\033[44m\033[97m'
        while True:
            os.system('cls' if os.name == 'nt' else 'clear')
            print(f"\n  {BLUE_BG} RISK VS RETURN (MARKOWITZ) ANALYZER {' ' * 38} {RES}")
            print("  " + "═" * 78)
            print(f"  {B}Instructions:{RES}")
            print("  Enter a list of stock tickers separated by commas to compare their risk/return.")
            print(f"  Example: {Y}AAPL, MSFT, TSLA, NVDA, GOOGL{RES} (or RELIANCE.NS, TCS.NS for Indian stocks)")
            print("  " + "═" * 78)
            print(f"  {B}0.{RES} Return to Main Menu")
            choice = input(f"\n  Enter Tickers (or 0): ").strip()
            if choice == '0':
                break
            elif choice:
                if self.fetch_and_calculate(choice):
                    self.print_terminal_table()
                    self.render_matplotlib_chart()
                    input(f"\n  {B}Analysis complete. Press ENTER to continue...{RES}")
                else:
                    input(f"\n  {R}[!] Analysis failed. Press ENTER to continue...{RES}")
            else:
                print(f"  {R}[!] Please enter valid tickers.{RES}")
                time.sleep(1)
def run_market_newcomers(current_ticker):
    import urllib.request
    import urllib.error
    import html
    header("MODULE 65 — NEW & TRENDING COMPANIES (NEWS SCRAPER)")
    B   = '\033[1m'
    C   = '\033[96m'
    G   = '\033[92m'
    Y   = '\033[93m'
    R   = '\033[91m'
    M   = '\033[95m'
    DIM = '\033[2m'
    RES = '\033[0m'
    NEW_LISTINGS = [
        ("HYUNDAIMOTOR",  "Hyundai Motor India",     "Auto",        "HYUNDAIMOTOR.NS"),
        ("SWIGGY",         "Swiggy (Bundl Tech)",    "Food-Tech",   "SWIGGY.NS"),
        ("NTPCGREEN",      "NTPC Green Energy",      "Power/RE",    "NTPCGREEN.NS"),
        ("SAGILITY",       "Sagility India",         "IT/BPO",      "SAGILITY.NS"),
        ("AADHARHFC",      "Aadhar Housing Finance", "NBFC",        "AADHARHFC.NS"),
        ("AWFIS",          "Awfis Space Solutions",  "Co-working",  "AWFIS.NS"),
        ("BHARTIHEXA",     "Bharti Hexacom",         "Telecom",     "BHARTIHEXA.NS"),
        ("KRSNAA",         "Krsnaa Diagnostics",     "Healthcare",  "KRSNAA.NS"),
        ("INOXGREEN",      "INOX Green Energy",      "Renewable",   "INOXGREEN.NS"),
        ("TBOTEK",         "TBO Tek",                "Travel Tech", "TBOTEK.NS"),
        ("EMCURE",         "Emcure Pharma",          "Pharma",      "EMCURE.NS"),
        ("VRAJ",           "Vraj Iron & Steel",      "Steel",       "VRAJIR.NS"),
        ("JUNIPER",        "Juniper Hotels",         "Hospitality", "JUNIPER.NS"),
        ("GODIGIT",        "Go Digit GIC",           "Insurance",   "GODIGIT.NS"),
        ("BLACKBUCK",      "Zinka Logistics (BB)",   "Logistics",   "BLACKBUCK.NS"),
        ("NIVA",           "Niva Bupa Health Ins",   "Insurance",   "NIVABUPA.NS"),
        ("MANBA",          "Manba Finance",          "NBFC",        "MANBA.NS"),
        ("DEEPAKBUILDERS", "Deepak Builders",        "Construction","DEEPAKBB.NS"),
    ]
    NEWS_FEEDS = [
        ("Moneycontrol IPO",   "https://www.moneycontrol.com/rss/ipo.xml"),
        ("Economic Times MCap","https://economictimes.indiatimes.com/markets/stocks/rss.cms"),
        ("NSE News",           "https://www1.nseindia.com/rss/news.xml"),
        ("Business Standard",  "https://www.business-standard.com/rss/home_page_top_stories.rss"),
    ]
    def _fetch_feed(url, timeout=6):
        try:
            req = urllib.request.Request(url, headers={
                'User-Agent': 'Mozilla/5.0 (Stock Analyzer Bot/1.0)'
            })
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return r.read().decode('utf-8', errors='ignore')
        except Exception:
            return None
    def _parse_rss_items(xml_text):
        items = []
        raw_items = re.findall(r'<item>(.*?)</item>', xml_text, re.DOTALL)
        for item in raw_items[:15]:
            title = re.search(r'<title[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?</title>', item, re.DOTALL)
            desc  = re.search(r'<description[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?</description>', item, re.DOTALL)
            pub   = re.search(r'<pubDate[^>]*>(.*?)</pubDate>', item, re.DOTALL)
            t = html.unescape(re.sub(r'<[^>]+>', '', title.group(1).strip())) if title else '—'
            d = html.unescape(re.sub(r'<[^>]+>', '', desc.group(1).strip()))[:120]  if desc  else ''
            p = pub.group(1).strip()[:20] if pub else ''
            items.append((t, d, p))
        return items
    NSE_HINT_PATTERNS = [
        r'\b([A-Z]{3,10})\.NS\b',
        r'NSE:\s*([A-Z]{3,10})\b',
        r'BSE:\s*(\d{6})\b',                           
        r'\bIPO\b',
        r'listed on NSE',
        r'new listing',
        r'debut',
    ]
    def _extract_tickers_from_text(text):
        tickers = []
        for pat in NSE_HINT_PATTERNS[:2]:                      
            tickers += re.findall(pat, text.upper())
        return list(set(tickers))
    clear()
    print(f"\n  {B}{C}MODULE 65 — NEW & TRENDING COMPANIES IN THE MARKET{RES}")
    print(f"  {'═'*65}")
    print(f"  {DIM}Fetching live news feeds … (may take a few seconds){RES}\n")
    live_news = []
    mentioned_tickers = set()
    for feed_name, feed_url in NEWS_FEEDS:
        print(f"  {DIM}→ {feed_name} …{RES}", end='', flush=True)
        xml = _fetch_feed(feed_url)
        if xml:
            items = _parse_rss_items(xml)
            for title, desc, pub in items:
                combined = title + ' ' + desc
                tks = _extract_tickers_from_text(combined)
                for t in tks:
                    mentioned_tickers.add(t)
                if any(kw in combined.upper() for kw in
                       ['IPO', 'LISTING', 'LISTED', 'DEBUT', 'ALLOTMENT',
                        'SUBSCRIBE', 'NEW COMPANY', 'SME IPO']):
                    live_news.append((title[:80], feed_name, pub))
            print(f" {G}✓ {len(items)} items{RES}")
        else:
            print(f" {Y}⚠ unavailable{RES}")
    print(f"\n  {DIM}Fetching live prices for new listings …{RES}")
    listing_data = []
    for sym, name, sector, ns_sym in NEW_LISTINGS:
        try:
            import contextlib as _ctx, io as _io2
            with _ctx.redirect_stdout(_io2.StringIO()), _ctx.redirect_stderr(_io2.StringIO()):
                d = yf.download(ns_sym, period='5d', interval='1d', progress=False)
            d = flatten_cols(d)
            if not d.empty and len(d) >= 2:
                curr  = float(d['Close'].iloc[-1])
                prev  = float(d['Close'].iloc[-2])
                chg   = (curr - prev) / prev * 100
                listing_data.append((sym, name, sector, ns_sym, curr, chg, True))
            else:
                listing_data.append((sym, name, sector, ns_sym, 0.0, 0.0, False))
        except Exception:
            listing_data.append((sym, name, sector, ns_sym, 0.0, 0.0, False))
    trending_news_tickers = []
    for t in sorted(mentioned_tickers):
        ns = t + '.NS'
        try:
            import contextlib as _ctx2, io as _io3
            with _ctx2.redirect_stdout(_io3.StringIO()), _ctx2.redirect_stderr(_io3.StringIO()):
                d2 = yf.download(ns, period='2d', interval='1d', progress=False)
            d2 = flatten_cols(d2)
            if not d2.empty and len(d2) >= 2:
                curr2 = float(d2['Close'].iloc[-1])
                prev2 = float(d2['Close'].iloc[-2])
                chg2  = (curr2 - prev2) / prev2 * 100
                trending_news_tickers.append((t, ns, curr2, chg2))
        except Exception:
            pass
    trending_news_tickers.sort(key=lambda x: abs(x[3]), reverse=True)
    while True:
        clear()
        print(f"\n  {B}{C}══ MODULE 65 — NEW & TRENDING COMPANIES ══{RES}")
        print(f"  {DIM}Active Ticker: {Y}{current_ticker}{RES}")
        print()
        print(f"  {B}┌─── 🆕 RECENTLY LISTED / NEW COMPANIES ON NSE {'─'*18}┐{RES}")
        print(f"  │  {'No':<4} {'Symbol':<14} {'Name':<24} {'Sector':<14} {'Price':>8}  {'Day Chg':>9}  │")
        print(f"  ├──────────────────────────────────────────────────────────────┤")
        for i, (sym, name, sector, ns_sym, price, chg, has_data) in enumerate(listing_data[:15], 1):
            if has_data:
                dc = G if chg >= 0 else R
                di = '▲' if chg >= 0 else '▼'
                price_str = f"₹{price:>7,.2f}"
                chg_str   = f"{dc}{di}{chg:>+6.2f}%{RES}"
            else:
                price_str = f"{'—':>9}"
                chg_str   = f"{DIM}N/A{RES}    "
            print(f"  │  [{i:>2}]  {sym:<14} {name[:24]:<24} {sector[:14]:<14} {price_str}  {chg_str}  │")
        print(f"  └──────────────────────────────────────────────────────────────┘")
        print()
        if trending_news_tickers:
            print(f"  {B}┌─── 🔥 TRENDING FROM LIVE NEWS {'─'*30}┐{RES}")
            print(f"  │  {'No':<4} {'Symbol':<14} {'NSE Ticker':<16} {'Price':>8}  {'Day Chg':>9}         │")
            print(f"  ├──────────────────────────────────────────────────────────────┤")
            for j, (sym2, ns2, pr2, ch2) in enumerate(trending_news_tickers[:10], 1):
                idx_j = len(listing_data) + j
                dc2 = G if ch2 >= 0 else R
                di2 = '▲' if ch2 >= 0 else '▼'
                print(f"  │  [{idx_j:>2}]  {sym2:<14} {ns2:<16} ₹{pr2:>7,.2f}  {dc2}{di2}{ch2:>+6.2f}%{RES}         │")
            print(f"  └──────────────────────────────────────────────────────────────┘")
